    check('VG11 not owned',      select(2, rg(nil, 75, 714, 100)), 'Oneiros Grip not owned (the Gear Helpers tab rescans itself)');
    check('VG12 under level',    select(2, rg(g, 74, 714, 100)), 'under level for Oneiros Grip (Lv75)');
    check('VG13 base unreadable', select(2, rg(g, 75, nil, 100)), 'native MP unreadable (login settle?)');
    check('VG14 no pool',        select(2, rg(g, 75, 0, 0)), 'no native MP pool on this job');
    check('VG15 cur unreadable', select(2, rg(g, 75, 714, nil)), 'current MP unreadable');
end)();

-- ---------------------------------------------------------------------------
-- SF. The statefile seam (engine v70): ONE cached reader (ensureStateFile)
--     behind the auto/acc/craft/helm/fish/pin caches -- they were six
--     near-identical clones and had drifted (pin dropped corrupt writes, the
--     others kept the last good table glued on forever). Policy pinned HERE,
--     once, for all of them; _charDirOverride makes the file-driven surface
--     run headless for the first time.
-- ---------------------------------------------------------------------------
(function()
    local esf = dispatchM._ensureStateFile;
    check('SF0 helper exported', type(esf), 'function');
    local function put(p, t) local f = io.open(p, 'w'); f:write(t); f:close(); end
    dispatchM._charDirOverride = 'tests\\';
    local cache = { raw = nil, data = nil, lastCheck = -1 };

    put('tests\\sf_state.lua', 'return { enabled = true, craft = "Alchemy" }');
    local d = esf(cache, 'sf_state.lua');
    check('SF1 file read + parsed', d ~= nil and d.craft, 'Alchemy');

    -- same-second throttle: a changed file is not re-read until the clock moves
    put('tests\\sf_state.lua', 'return { craft = "Smithing" }');
    cache.lastCheck = os.time();
    check('SF2 throttled within the second', esf(cache, 'sf_state.lua').craft, 'Alchemy');

    -- THE POLICY: corrupt write -> DROP (not last-good); re-reads stay dropped
    cache.lastCheck = -1;
    put('tests\\sf_state.lua', 'return {');
    check('SF3 corrupt write drops the state', esf(cache, 'sf_state.lua'), nil);
    cache.lastCheck = -1;
    check('SF4 corrupt stays dropped on re-read', esf(cache, 'sf_state.lua'), nil);

    -- the next good write self-heals
    cache.lastCheck = -1;
    put('tests\\sf_state.lua', 'return { craft = "Bonecraft" }');
    check('SF5 good write self-heals', esf(cache, 'sf_state.lua').craft, 'Bonecraft');

    -- a file that parses but ERRORS on run drops too
    cache.lastCheck = -1;
    put('tests\\sf_state.lua', 'error("boom")');
    check('SF6 run-error drops the state', esf(cache, 'sf_state.lua'), nil);

    -- missing file = state off
    cache.lastCheck = -1;
    os.remove('tests\\sf_state.lua');
    check('SF7 missing file = state off', esf(cache, 'sf_state.lua'), nil);

    -- pre-login (no char dir) keeps whatever is cached
    cache.lastCheck = -1; cache.data = { keep = true };
    dispatchM._charDirOverride = nil;
    check('SF8 no char dir keeps cache', esf(cache, 'sf_state.lua').keep, true);

    -- WIRING: with no test override, the auto manifest reads through the seam.
    -- The _auto singleton's 1s throttle may have been armed by an earlier
    -- section in this same second -- cross the boundary so the read is live.
    dispatchM._charDirOverride = 'tests\\';
    dispatchM._autoOverride = nil;
    put('tests\\autogear.lua', 'return { universal = { name = "Chatoyant Staff", tier = 2, level = 51 } }');
    local t0 = os.time(); repeat until os.time() ~= t0;
    check('SF9 resolveVirtual reads the manifest through the seam',
        dispatchM._resolveVirtual('dlac:AutoStaff', { player = { MainJobSync = 75 } }), 'Chatoyant Staff');
    os.remove('tests\\autogear.lua');
    dispatchM._charDirOverride = nil;
end)();

-- ---------------------------------------------------------------------------
-- PL. equipResolved's post-pass order is DATA (engine v71): the five
--     whole-table passes run in M._postPassOrder. A reorder must edit BOTH the
--     list and this pin -- which is the point: the ADR 0010 constraint
--     (trinket-vs-ranged strictly before reserved-drops, or the loser gets to
--     reserve and the result flaps) is now checkable instead of prose.
-- ---------------------------------------------------------------------------
(function()
    local po = dispatchM._postPassOrder;
    check('PL1 order exported', type(po), 'table');
    check('PL2 exact order', table.concat(po, '>'),
        'mp-hold>craft-sub-guard>sync-hold-ammo>trinket-vs-ranged>reserved-drops');
    local ti, ri = nil, nil;
    for i, nm in ipairs(po) do
        if nm == 'trinket-vs-ranged' then ti = i; end
        if nm == 'reserved-drops' then ri = i; end
    end
    check('PL3 ADR 0010: trinket strictly before reserved', ti ~= nil and ri ~= nil and ti < ri, true);
end)();

-- ---------------------------------------------------------------------------
-- AR. THE ARBITER, step 1 (engine v97, ADR 0012). One data-driven claim
--     registry orders every Claim's application, replacing the hardcoded
--     overlay sequence. This section is the ORDER-PINNING test (a reorder of
--     the built-in default must edit BOTH the constant and this pin), the pure
--     resolve core (claims + rank + floor -> winners + attribution), arbstate
--     sanitization + the Statefile drop policy, MaxMP's rank-consult (ceded
--     slots), and the ONE deliberate change wired through equipResolved
--     (AutoAmmo's projectile beats a battery in Ammo).
-- ---------------------------------------------------------------------------
(function()
    -- AR1: the built-in default rank, highest first. Pinned so an accidental
    -- reorder fails loudly (the POST_ORDER precedent, PL2).
    local def = dispatchM._arbDefaultOrder;
    check('AR1 default order exported', type(def), 'table');
    check('AR1b exact default rank', table.concat(def, '>'),
        'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    -- AR1c: the ADR 0012 laws the order encodes, checked as adjacency (not prose)
    local rank = {}; for i, n in ipairs(def) do rank[n] = i; end
    -- Naked (ADR 0021) is the ONE row above Pins: "naked" must mean naked, and a
    -- player who wants "naked except my pins" drags Pins over it. Do not "fix"
    -- this back to Pins == 1.
    check('AR1d Naked outranks every RANKED row (the Disabled ceiling is not one -- ADR 0024)',
        rank['Disabled'] == 1 and rank['Naked'] == 2 and rank['Pins'] == 3, true);
    check('AR1e Locks veto sits under Pins', rank['Locks'] == rank['Pins'] + 1, true);
    check('AR1f AutoAmmo outranks MaxMP (the deliberate change)', rank['AutoAmmo'] < rank['MaxMP'], true);
    check('AR1g MaxMP outranks Craft/HELM/Fishing (batteries over their armor)',
        rank['MaxMP'] < rank['Craft'] and rank['Craft'] < rank['HELM'] and rank['HELM'] < rank['Fishing'], true);
    check('AR1h Triggers is the floor (last)', rank['Triggers'], #def);

    -- AR2: arbOrder sanitizes. Missing/torn -> default; unknown dropped, missing
    -- known rows restored AT THEIR DEFAULT POSITION (v122 -- see NK8/NK9; the old
    -- law appended them, which is right only for a row that belongs last); a valid
    -- reorder is preserved.
    check('AR2 nil -> default', table.concat(dispatchM.arbOrder(nil), '>'),
        'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    check('AR2b no order field -> default', table.concat(dispatchM.arbOrder({ foo = 1 }), '>'),
        'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    check('AR2c a valid reorder is preserved',
        table.concat(dispatchM.arbOrder({ order = { 'MaxMP', 'AutoAmmo', 'Pins', 'Locks', 'Craft', 'HELM', 'Fishing', 'Triggers' } }), '>'),
        'Disabled>Naked>MaxMP>AutoAmmo>Pins>Locks>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    -- Listed rows keep the user's order absolutely (Fishing still above Pins);
    -- every unlisted row lands where it sits by default RELATIVE to them --
    -- Naked before Fishing, Chocobo after Pins because nothing outranks it.
    check('AR2d unknown rows dropped, missing known rows restored at their default position',
        table.concat(dispatchM.arbOrder({ order = { 'Fishing', 'Nonsense', 'Pins' } }), '>'),
        'Disabled>Naked>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Pins>Chocobo>ModeLock>External>Triggers');
    check('AR2e duplicates collapse',
        table.concat(dispatchM.arbOrder({ order = { 'Pins', 'Pins', 'AutoAmmo' } }), '>'),
        'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');

    -- ARP: arbOrderPersist -- the WRITE view (issue #136). arbOrder above drops
    -- unknown rows (right for the walk + the Priority tab); arbOrderPersist keeps
    -- them at their position so the file survives a rewrite and a claimant can
    -- reclaim its saved spot when it later exists. The ceiling/floor stay pinned.
    do
        -- A file the player has dragged, carrying one row THIS build does not know
        -- (an uninstalled module's claimant), anchored between MaxMP and Craft.
        local fileWithGhost = { order = { 'Disabled', 'Naked', 'Pins', 'Locks',
            'AutoAmmo', 'MaxMP', 'Ghost', 'Craft', 'HELM', 'Fishing', 'Chocobo', 'Triggers' } };
        -- The live walk / Priority tab NEVER see Ghost.
        check('ARP1 arbOrder (the live view) drops the unknown row',
            table.concat(dispatchM.arbOrder(fileWithGhost), '>'),
            'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
        -- The drag produced a new KNOWN order (Craft moved below HELM); persisting
        -- it weaves Ghost back in anchored to MaxMP -- position intact.
        local dragged = { 'Disabled', 'Naked', 'Pins', 'Locks', 'AutoAmmo', 'MaxMP',
            'HELM', 'Craft', 'Fishing', 'Chocobo', 'Triggers' };
        local persisted = dispatchM.arbOrderPersist(dragged, fileWithGhost);
        check('ARP2 persist keeps the unknown row anchored to its predecessor',
            table.concat(persisted, '>'),
            'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Ghost>HELM>Craft>Fishing>Chocobo>ModeLock>External>Triggers');
        -- Preserve-through-rewrite: feed the persisted order back as the raw file
        -- and drag again -- Ghost survives ANY number of rewrites, still anchored.
        local persisted2 = dispatchM.arbOrderPersist(
            dispatchM.arbOrder({ order = persisted }), { order = persisted });
        check('ARP3 unknown row survives a second rewrite intact',
            table.concat(persisted2, '>'),
            'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Ghost>HELM>Craft>Fishing>Chocobo>ModeLock>External>Triggers');
        -- No raw file / no unknowns -> persist == arbOrder (a fresh character).
        check('ARP4 no raw file -> plain sanitized order (nothing to preserve)',
            table.concat(dispatchM.arbOrderPersist(dispatchM.arbOrder(nil), nil), '>'),
            'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
        -- Reclaim-on-return: the file position of a LISTED row is honored by
        -- arbOrder over the default -- so the instant Ghost's identity becomes a
        -- known claimant, it takes its preserved spot, not its default one. Pinned
        -- here with Chocobo listed OUT of its default place (which is last-before-
        -- Triggers): arbOrder keeps it where the file puts it, exactly as it will
        -- for a returning claimant.
        check('ARP5 a listed row keeps its saved position (reclaim law)',
            table.concat(dispatchM.arbOrder({ order = { 'Disabled', 'Naked', 'Pins',
                'Locks', 'Chocobo', 'AutoAmmo', 'MaxMP', 'Craft', 'HELM', 'Fishing', 'Triggers' } }), '>'),
            'Disabled>Naked>Pins>Locks>Chocobo>AutoAmmo>MaxMP>Craft>HELM>Fishing>ModeLock>External>Triggers');
        -- Two unknowns in a row share an anchor and keep their relative order; the
        -- ceiling/floor stay pinned even when an unknown sits at an extreme.
        local twoGhosts = { order = { 'Zeta', 'Disabled', 'Naked', 'Pins', 'Locks',
            'AutoAmmo', 'MaxMP', 'Craft', 'HELM', 'Fishing', 'Chocobo', 'Alpha', 'Beta', 'Triggers' } };
        check('ARP6 multiple unknowns keep order; ceiling first / floor last hold',
            table.concat(dispatchM.arbOrderPersist(dispatchM.arbOrder(twoGhosts), twoGhosts), '>'),
            'Disabled>Zeta>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>Alpha>Beta>ModeLock>External>Triggers');
    end

    -- AR3: the PURE resolve core -- claims + rank + floor -> winners + by.
    local order = dispatchM.arbOrder(nil);
    local floor = { Head = 'Idle Hat', Body = 'Idle Robe', Ammo = 'Iron Arrow' };
    -- floor only
    local w0, by0 = dispatchM.arbResolve({}, order, floor);
    check('AR3 floor flows when no claims', w0.Body, 'Idle Robe');
    check('AR3b floor attribution', by0.Body, 'Triggers');
    -- pins over everything (default-order equivalence: pins over craft over floor)
    local w1, by1 = dispatchM.arbResolve({
        Pins  = { Head = 'Pinned Crown' },
        Craft = { Head = 'Craft Cap', Hands = 'Craft Gloves' },
    }, order, floor);
    check('AR4 pins win the contested slot',   w1.Head, 'Pinned Crown');
    check('AR4b attribution names the pin',    by1.Head, 'Pins');
    check('AR4c craft wins where pins are silent', w1.Hands, 'Craft Gloves');
    check('AR4d craft over the floor',         by1.Hands, 'Craft');
    check('AR4e the floor still shows through', w1.Body, 'Idle Robe');
    -- reorder changes winners: move Craft above Pins and craft takes Head
    local reordered = dispatchM.arbOrder({ order = { 'Craft', 'Pins', 'Locks', 'AutoAmmo', 'MaxMP', 'HELM', 'Fishing', 'Triggers' } });
    local w2 = dispatchM.arbResolve({
        Pins  = { Head = 'Pinned Crown' },
        Craft = { Head = 'Craft Cap' },
    }, reordered, floor);
    check('AR5 a reorder changes the winner (craft over pins)', w2.Head, 'Craft Cap');

    -- AR6: arbCededAbove -- the pure "which slots did rows above X win" query.
    -- (The live consumer died with the FOLD, stage 6 -- ceding is apply order
    -- now -- but the query stays part of the arbiter's model: at default rank
    -- Pins' and AutoAmmo's slots read as ceded to them, Craft/HELM/Fishing
    -- rank BELOW MaxMP so theirs never do, and a reorder moves the answer.)
    local ceded = dispatchM.arbCededAbove({
        Pins     = { Head = 'Pinned Crown' },
        AutoAmmo = { Ammo = 'Fire Bomblet' },
        Craft    = { Hands = 'Craft Gloves', Neck = 'Craft Torque' },
    }, order, 'MaxMP');
    check('AR6 Ammo ceded to AutoAmmo',        ceded['ammo'], 'AutoAmmo');
    check('AR6b Head ceded to Pins',           ceded['head'], 'Pins');
    check('AR6c Craft slots NOT ceded (below MaxMP)', ceded['hands'], nil);
    check('AR6d Craft neck NOT ceded',         ceded['neck'], nil);
    local cededReord = dispatchM.arbCededAbove({
        AutoAmmo = { Ammo = 'Fire Bomblet' },
    }, dispatchM.arbOrder({ order = { 'Pins', 'Locks', 'MaxMP', 'AutoAmmo', 'Craft', 'HELM', 'Fishing', 'Triggers' } }), 'MaxMP');
    check('AR6e reorder MaxMP above AutoAmmo -> Ammo no longer ceded', cededReord['ammo'], nil);
    check('AR6f who not in the order -> nothing ceded',
        next(dispatchM.arbCededAbove({ Pins = { Head = 'x' } }, order, 'Nobody')), nil);

    -- AR7: arbstate as a Statefile through the shared reader -- a hand-edited
    -- reorder changes the order; a torn write drops to the default (the SF
    -- policy). Driven through _ensureStateFile like the SF section.
    local esf = dispatchM._ensureStateFile;
    local function put(p, t) local f = io.open(p, 'w'); f:write(t); f:close(); end
    dispatchM._charDirOverride = 'tests\\';
    local cache = { raw = nil, data = nil, lastCheck = -1 };
    put('tests\\arbstate.lua', 'return { order = { "MaxMP", "AutoAmmo", "Pins", "Locks", "Craft", "HELM", "Fishing", "Triggers" } }');
    check('AR7 hand-edited reorder is read + sanitized',
        table.concat(dispatchM.arbOrder(esf(cache, 'arbstate.lua')), '>'),
        'Disabled>Naked>MaxMP>AutoAmmo>Pins>Locks>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    cache.lastCheck = -1;
    put('tests\\arbstate.lua', 'return { order = {');   -- torn write
    check('AR7b torn write drops to default',
        table.concat(dispatchM.arbOrder(esf(cache, 'arbstate.lua')), '>'),
        'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    os.remove('tests\\arbstate.lua');
    dispatchM._charDirOverride = nil;

    -- AR8: activities CO-CLAIM (ADR 0012 amendment, step 1.5). The newest-armed
    -- (`at` stamp) exclusivity that stood the others down whole is retired: with
    -- two OR three of Craft/HELM/Fishing armed, EVERY armed activity claims and
    -- the rank list settles each overlapping slot PER SLOT. Pinned at the resolve
    -- seam -- arbResolve is blind to any `at` field, which is exactly the point:
    -- arming one activity does not affect the others' claims. (The exclusivity
    -- lived inline in M.dispatch, never at a pure seam, so there was no old
    -- exclusivity-pin test to invert -- these ADD the co-claim law it replaced.)
    do
        local ord = dispatchM.arbOrder(nil);   -- ...Craft>HELM>Fishing...
        -- Two armed: Craft + HELM share Head/Hands; Craft ranks above HELM.
        local w, by = dispatchM.arbResolve({
            Craft = { Head = 'Craft Cap', Hands = 'Craft Gloves', Neck = 'Craft Torque' },
            HELM  = { Head = 'Field Hat', Hands = 'Field Gloves', Waist = 'Field Belt' },
        }, ord, { Body = 'Idle Robe' });
        check('AR8 both armed -> both claim, no whole stand-down (craft neck kept)', w.Neck, 'Craft Torque');
        check('AR8b HELM keeps its own slot (waist)', w.Waist, 'Field Belt');
        check('AR8c rank settles the shared slot per slot (Craft > HELM on Head)', w.Head, 'Craft Cap');
        check('AR8d shared Hands also to Craft', by.Hands, 'Craft');
        check('AR8e floor still shows where none claim', w.Body, 'Idle Robe');
        -- Three armed at once: each keeps its own exclusive slot; the shared one
        -- goes to the highest rank. Nothing stands down.
        local w3 = dispatchM.arbResolve({
            Craft   = { Hands = 'Craft Gloves' },
            HELM    = { Neck  = 'Field Torque' },
            Fishing = { Range = 'Lu Shangs Rod', Hands = 'Fishing Gloves' },
        }, ord, {});
        check('AR9 three armed: craft keeps Hands (ranked top of the three)', w3.Hands, 'Craft Gloves');
        check('AR9b HELM keeps Neck',   w3.Neck, 'Field Torque');
        check('AR9c Fishing keeps Range (no other claims it)', w3.Range, 'Lu Shangs Rod');
    end

    -- AR10: the PUP field case that drove the ruling, VERBATIM (issue #53). PUP
    -- idle floor names Range = Animator. Fishing armed -> rod in Range. HELM also
    -- armed (ranked ABOVE Fishing) wins only its seven armor slots; HELM never
    -- claims weapons/Range/rings/Ammo, so the ROD STAYS IN RANGE. The Animator
    -- returns only when Fishing itself is disarmed.
    do
        local ord = dispatchM.arbOrder(nil);   -- default: HELM ranks above Fishing
        -- PUP idle floor (the trigger overlay result the claims dress over).
        local floor = {
            Main = 'Animator P', Sub = 'Animator P II', Range = 'Animator',
            Head = 'Idle Head', Body = 'Idle Body', Hands = 'Idle Hands',
            Legs = 'Idle Legs', Feet = 'Idle Feet', Neck = 'Idle Neck',
            Waist = 'Idle Waist', Ring1 = 'Idle Ring1', Ring2 = 'Idle Ring2',
        };
        -- Fishing armed: rod in Range, spear in Main, bait in Ammo, fishing armor.
        local fishing = {
            Main = 'Halieutica', Range = 'Lu Shangs Rod', Ammo = 'Little Worm',
            Head = 'Fish Head', Body = 'Fish Body', Hands = 'Fish Hands',
            Legs = 'Fish Legs', Feet = 'Fish Feet',
        };
        -- HELM armed: its seven armor slots ONLY (armor + neck + waist).
        local helm = {
            Head = 'Helm Head', Body = 'Helm Body', Hands = 'Helm Hands',
            Legs = 'Helm Legs', Feet = 'Helm Feet', Neck = 'Helm Neck',
            Waist = 'Helm Waist',
        };
        local w, by = dispatchM.arbResolve({ HELM = helm, Fishing = fishing }, ord, floor);
        check('AR10 the rod stays in Range (HELM never claims it)', w.Range, 'Lu Shangs Rod');
        check('AR10b Range attributed to Fishing, not the floor Animator', by.Range, 'Fishing');
        check('AR10c HELM wins its seven armor slots (Head)', by.Head, 'HELM');
        check('AR10d HELM wins Neck', w.Neck, 'Helm Neck');
        check('AR10e HELM wins Waist', w.Waist, 'Helm Waist');
        check('AR10f fishing Main spear survives (HELM never claims weapons)', w.Main, 'Halieutica');
        check('AR10g fishing bait survives in Ammo (HELM never claims Ammo)', w.Ammo, 'Little Worm');
        check('AR10h rings fall to the floor (neither claims them)', w.Ring1, 'Idle Ring1');
        -- Disarm Fishing (drop its claim): the Animator returns to Range.
        local w2, by2 = dispatchM.arbResolve({ HELM = helm }, ord, floor);
        check('AR10i Fishing disarmed -> Animator returns to Range', w2.Range, 'Animator');
        check('AR10j and Range is the floor again', by2.Range, 'Triggers');
    end
end)();

-- ---------------------------------------------------------------------------
-- AR11/AR12. THE ARBITER, step 4 (ADR 0012 / issue #51). The registry is the
--      SINGLE precedence authority, so the pure resolve that decides winners
--      ALSO explains them (/dl why). AR11 pins the whole claim path -- every
--      claimant (incl. the MaxMP battery claim + the Locks veto) resolved in
--      ONE rank walk via arbExplain. AR12 pins the /dl why line format:
--      'Ammo: AutoAmmo (rank 3) over MaxMP (rank 4)', veto slots 'stopped by
--      Locks', floor-only slots 'Triggers (floor)', in canonical LAC order.
-- ---------------------------------------------------------------------------
(function()
    local ord = dispatchM.arbOrder(nil);  -- Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>Triggers
    -- The whole claim path in one resolve. MaxMP is a proper CLAIM now (step 4):
    -- its battery targets a claim table, ranked below AutoAmmo (the deliberate
    -- cede) and above Craft (batteries over craft armor).
    local claims = {
        Pins     = { Head = 'Pinned Crown' },
        AutoAmmo = { Ammo = 'Orichalc. Bullet' },
        MaxMP    = { Ammo = 'MP Bullet', Ring1 = 'MP Ring', Head = 'MP Crown' },
        Craft    = { Head = 'Craft Cap', Hands = 'Craft Gloves' },
        Locks    = dispatchM.arbLockClaim({ 'Legs' }),
    };
    local floor = { Head = 'Idle Hat', Ammo = 'Idle Ammo', Ring1 = 'Idle Ring',
                    Hands = 'Idle Hands', Legs = 'Idle Legs', Body = 'Idle Body' };
    local ex = dispatchM.arbExplain(claims, ord, floor);
    -- Ammo: AutoAmmo(4) > MaxMP(5) > Triggers(10) -- the issue's headline contest.
    check('AR11 Ammo winner is AutoAmmo',            ex.Ammo[1].name, 'AutoAmmo');
    check('AR11b Ammo winner rank is 5 (the Disabled ceiling took 1, Naked 2)', ex.Ammo[1].rank, 5);
    check('AR11c Ammo runner-up is the MaxMP battery (the deliberate cede)', ex.Ammo[2].name, 'MaxMP');
    check('AR11d Ammo third is the floor',           ex.Ammo[3].name, 'Triggers');
    -- Head: Pins(2) > MaxMP(5) > Craft(6) > Triggers(10).
    check('AR11e Head winner is the pin',            ex.Head[1].name, 'Pins');
    check('AR11f Head second is MaxMP (battery over craft armor)', ex.Head[2].name, 'MaxMP');
    check('AR11g Head third is Craft',               ex.Head[3].name, 'Craft');
    -- Ring1: a MaxMP battery in a bare ring over the floor.
    check('AR11h Ring1 winner is MaxMP',             ex.Ring1[1].name, 'MaxMP');
    check('AR11i Ring1 second is the floor',         ex.Ring1[2].name, 'Triggers');
    -- Hands: only Craft claims it.
    check('AR11j Hands winner is Craft',             ex.Hands[1].name, 'Craft');
    -- Legs: the Locks veto (rank 3) wins; nothing claims above it.
    check('AR11k Legs winner is the Locks veto',     ex.Legs[1].name, 'Locks');
    check('AR11l Legs veto held off the floor',      ex.Legs[2].name, 'Triggers');
    -- Body: floor-only.
    check('AR11m Body is floor-only Triggers',       ex.Body[1].name, 'Triggers');
    check('AR11n Body has no other opinion',         #ex.Body, 1);
end)();

(function()
    local ord = dispatchM.arbOrder(nil);
    local claims = {
        AutoAmmo = { Ammo = 'Orichalc. Bullet' },
        MaxMP    = { Ammo = 'MP Bullet', Ring1 = 'MP Ring' },
        Craft    = { Hands = 'Craft Gloves' },
        Locks    = dispatchM.arbLockClaim({ 'legs' }),   -- lowercase key (the live M.locks shape)
    };
    local floor = { Ammo = 'Idle Ammo', Ring1 = 'Idle Ring', Hands = 'Idle Hands',
                    Legs = 'Idle Legs', Body = 'Idle Body' };
    local joined = table.concat(dispatchM.arbWhyLines(claims, ord, floor), '\n');
    -- The winner is named by its DISPLAY LABEL (arbiter.claimantLabel): the
    -- claimant identity stays 'AutoAmmo' in claims/order/arbstate, but no
    -- player-facing surface prints it (2026-07-28, Henrik: "not in the GUI").
    check('AR12 the Ammo contest line names winner over runner-up (the issue example)',
        joined:find('Ammo: Ammo rule (rank 5)  over MaxMP (rank 6)', 1, true) ~= nil, true);
    check('AR12b a MaxMP-only slot reads MaxMP over the floor',
        joined:find('Ring1: MaxMP (rank 6)  over Triggers (rank 13)', 1, true) ~= nil, true);
    check('AR12c a veto slot reads stopped by Locks (even from a lowercase key)',
        joined:find('Legs: stopped by Locks (rank 4)', 1, true) ~= nil, true);
    check('AR12d floor-only slots collapse into one named Triggers-floor summary',
        joined:find('Triggers floor (rank 13, uncontested):', 1, true) ~= nil
        and joined:find('Body', 1, true) ~= nil, true);
    -- Contested slots emit individually in canonical LAC order (ammo 4 < hands 10
    -- < ring1 11), BEFORE the trailing floor summary.
    local iAmmo, iHands, iRing = joined:find('Ammo:', 1, true), joined:find('Hands:', 1, true), joined:find('Ring1:', 1, true);
    check('AR12e contested slots emit in canonical LAC order (Ammo < Hands < Ring1)',
        iAmmo < iHands and iHands < iRing, true);
    -- THE GUARD (2026-07-28). The claimant IDENTITY 'AutoAmmo' is persisted in
    -- arbstate's order and keys claims/CLAIMANTS/CLAIM_COL/HINT -- it must not
    -- move. What must never happen is a PLAYER reading it. /dl why is the
    -- richest naming surface, so it is the one pinned here: the identity is
    -- still what the caller passed in, and it appears nowhere in the output.
    check('AR12f the claim table still keys on the IDENTITY (nothing was renamed)',
        claims.AutoAmmo ~= nil and claims.AutoAmmo.Ammo, 'Orichalc. Bullet');
    check('AR12g ...and no /dl why line ever prints it',
        joined:find('AutoAmmo', 1, true), nil);
end)();

-- ---------------------------------------------------------------------------
-- ARL. CLAIMANT DISPLAY LABELS (2026-07-28, Henrik: "I don't mind its name
--      being that internally, but not in the GUI"). ONE map in gear/arbiter
--      feeds every surface that names a claimant to a human -- the Priority
--      list, the Arbiter Monitor, /dl prio, /dl why -- so the GUI and the chat
--      cannot drift apart. Identity in, label out; unmapped = itself, so a new
--      claimant needs an entry only when its internal name is not readable.
-- ---------------------------------------------------------------------------
(function()
    local ARB = require('dlac\\gear\\arbiter');
    check('ARL1 the one Auto name a player could still see is mapped',
        ARB.claimantLabel('AutoAmmo'), 'Ammo rule');
    check('ARL2 an unmapped claimant is its own label',
        ARB.claimantLabel('MaxMP'), 'MaxMP');
    check('ARL3 ...for every other rank row too (no accidental entries)',
        ARB.claimantLabel('Pins') .. '/' .. ARB.claimantLabel('Locks')
            .. '/' .. ARB.claimantLabel('Triggers'), 'Pins/Locks/Triggers');
    check('ARL4 a nil/non-string is handed straight back (never a crash)',
        ARB.claimantLabel(nil), nil);
    -- The identity list is untouched: renaming a rank row would silently
    -- reorder every character's saved arbstate ladder.
    local n = 0;
    for _, name in ipairs(ARB.ARB_ORDER_DEFAULT) do
        if name == 'AutoAmmo' then n = n + 1; end
    end
    check('ARL5 the rank vocabulary still carries the IDENTITY', n, 1);
    -- (The GUI end of this -- priorityui.label + the Arbiter Monitor -- is
    -- pinned in smoke_ui: UI modules load only in that harness.)
end)();

-- ---------------------------------------------------------------------------
-- ARE. CEDING IS APPLY ORDER (the FOLD, stage 6 -- was: the v97 ctx.mpCeded
--      rank consult). The MaxMP row builds its claim like every other
--      claimant and its apply writes batteries into the dispatch plan; a slot
--      wanted by a claimant ranked ABOVE is simply overwritten when that row
--      applies after it -- there is nothing to compute. These drive the row
--      directly (claim + apply against a stubbed band context + a live plan).
-- ---------------------------------------------------------------------------
(function()
    local savedAC, savedBands = AshitaCore, dispatchM.mpBands;
    AshitaCore = nil;                                   -- wornItemName -> nil everywhere
    for k in pairs(dispatchM.locks) do dispatchM.locks[k] = nil; end
    dispatchM.modes['maxmp'] = true;
    local row;
    for _, r in ipairs(dispatchM._claimants) do if r.name == 'MaxMP' then row = r; end end
    check('ARE0 the MaxMP row carries claim + apply since the fold',
        row ~= nil and type(row.claim) == 'function' and type(row.apply) == 'function', true);

    dispatchM.mpBands = function()
        return { mpMap = { ['mp bullet'] = 20, ['fire bomblet'] = 0 },
                 target = { ammo = 'MP Bullet' },
                 bands = {}, mpBest = {}, moveYield = false, moving = false, mvMap = {} };
    end;
    -- The claim IS the band target map, canonical slot casing.
    local mc = row.claim(nil, false, { ctx = {} });
    check('ARE1 the row claim is the band target map', mc ~= nil and mc.Ammo, 'MP Bullet');
    -- The apply lands the battery over the already-merged floor piece.
    local ctx2 = { planOut = { Ammo = 'Fire Bomblet' } };
    row.apply({ built = { MaxMP = { Ammo = 'MP Bullet' } }, ctx = ctx2,
                respect = function() return true; end });
    check('ARE2 the apply lands the battery in the shared plan', ctx2.planOut.Ammo, 'MP Bullet');
    -- Ceding is apply order: a stronger row (AutoAmmo, above MaxMP) applies
    -- AFTER and overwrites -- the projectile wins Ammo with no consult at all.
    dispatchM._equipResolved({ Ammo = 'Orichalc. Bullet' }, ctx2, false, 'AutoAmmo');
    check('ARE3 a stronger row overwrites the battery -- ceding is apply order',
        ctx2.planOut.Ammo, 'Orichalc. Bullet');
    -- v91 gate: an explicit `remove` in the plan is never claimed over.
    dispatchM.mpBands = function()
        return { mpMap = { ['mp ring'] = 15 }, target = { ring1 = 'MP Ring' },
                 bands = {}, mpBest = {}, moveYield = false, moving = false, mvMap = {} };
    end;
    local ctx4 = { planOut = { Ring1 = 'remove' } };
    row.apply({ built = { MaxMP = { Ring1 = 'MP Ring' } }, ctx = ctx4,
                respect = function() return true; end });
    check('ARE4 the remove-respect gate: an explicit empty beats a battery',
        ctx4.planOut.Ring1, 'remove');
    -- Weave-parity sight: a row ABOVE MaxMP claiming the sibling ring with the
    -- SAME piece vetoes the battery even though it has not applied yet (the
    -- weave ran inside that row's equipResolved and saw its table live).
    local ctx5 = { planOut = {}, rankOf = { Pins = 3, MaxMP = 6 } };
    row.apply({ built = { MaxMP = { Ring1 = 'MP Ring' },
                          Pins  = { Ring2 = 'MP Ring' } }, ctx = ctx5,
                respect = function() return true; end });
    check('ARE5 an unapplied above-claim on the sibling vetoes the duplicate battery',
        ctx5.planOut.Ring1, nil);

    dispatchM.modes['maxmp'] = nil;
    dispatchM.mpBands = savedBands;
    AshitaCore = savedAC;
end)();

-- ---------------------------------------------------------------------------
-- LV. LOCKS ARE THE DRAGGABLE VETO ROW (ADR 0012, step 3 / issue #50). Two
--     pinned surfaces: (a) the PURE resolve model -- Locks passed to arbResolve
--     as a veto claim (arbLockClaim -> the LOCK_HELD sentinel), so its rank
--     decides who punches through and who stops; (b) the LIVE wiring -- the
--     per-layer respectLocks flag through equipResolved; since the FOLD
--     (stage 6) MaxMP rides the same flag via its row's respect('MaxMP').
-- ---------------------------------------------------------------------------
(function()
    -- (a) The pure resolve model. arbLockClaim builds the veto table.
    local lc = dispatchM.arbLockClaim({ head = true, ring2 = false });
    check('LV0 arbLockClaim maps only truthy slots to the veto sentinel',
        lc.head == dispatchM.LOCK_HELD and lc.ring2 == nil, true);
    check('LV0b arbLockClaim accepts an array of slot keys',
        dispatchM.arbLockClaim({ 'Head', 'Ring1' }).Ring1, dispatchM.LOCK_HELD);

    local order = dispatchM.arbOrder(nil);  -- Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>Triggers
    local floor = { Head = 'Idle Hat', Ring1 = 'Idle Ring' };
    local locked = dispatchM.arbLockClaim({ 'Head', 'Ring1' });  -- both slots locked

    -- Default position: pins (above Locks) punch through; craft + floor (below) stop.
    local w1, by1 = dispatchM.arbResolve({
        Pins  = { Head = 'Pinned Crown' },
        Craft = { Head = 'Craft Cap', Ring1 = 'Craft Ring' },
        Locks = locked,
    }, order, floor);
    check('LV1 a pin above Locks punches through the locked slot', w1.Head, 'Pinned Crown');
    check('LV1b that slot is attributed to the pin', by1.Head, 'Pins');
    check('LV1c craft below Locks stops at the lock (kept worn)', w1.Ring1, dispatchM.LOCK_HELD);
    check('LV1d the locked-stop is attributed to Locks', by1.Ring1, 'Locks');

    -- Locks dragged to the TOP: an absolute veto, pins included.
    local topLocks = dispatchM.arbOrder({ order = {
        'Locks', 'Pins', 'AutoAmmo', 'MaxMP', 'Craft', 'HELM', 'Fishing', 'Triggers' } });
    local w2, by2 = dispatchM.arbResolve({
        Pins = { Head = 'Pinned Crown' }, Locks = locked,
    }, topLocks, floor);
    check('LV2 Locks at the top vetoes even pins', w2.Head, dispatchM.LOCK_HELD);
    check('LV2b attributed to Locks', by2.Head, 'Locks');

    -- Locks dragged LOWER: everyone above punches through, everyone below stops.
    local lowLocks = dispatchM.arbOrder({ order = {
        'Pins', 'AutoAmmo', 'MaxMP', 'Craft', 'Locks', 'HELM', 'Fishing', 'Triggers' } });
    local w3, by3 = dispatchM.arbResolve({
        Craft = { Head = 'Craft Cap' },   -- rank 4, above the lowered Locks (5): punches through
        HELM  = { Ring1 = 'Helm Ring' },  -- rank 6, below Locks: stops
        Locks = locked,
    }, lowLocks, floor);
    check('LV3 a claimant above the lowered Locks punches through', w3.Head, 'Craft Cap');
    check('LV3b a claimant below the lowered Locks stops', w3.Ring1, dispatchM.LOCK_HELD);
    check('LV3c the below-Locks stop is attributed to Locks', by3.Ring1, 'Locks');

    -- (b) The LIVE wiring through equipResolved: the per-layer respectLocks flag.
    local savedAC = AshitaCore;
    AshitaCore = nil;                                   -- wornItemName -> nil
    for k in pairs(dispatchM.locks) do dispatchM.locks[k] = nil; end
    dispatchM.locks['head'] = true;
    -- respectLocks default (nil == true): the locked slot is stripped (held worn).
    local _, wResp = dispatchM._equipResolved({ Head = 'Some Hat', Body = 'Some Body' }, {});
    check('LV4 respectLocks default strips the locked slot', wResp.Head, nil);
    check('LV4b an unlocked slot still equips', wResp.Body, 'Some Body');
    check('LV4c the strip is still traced', (function()
        local note = dispatchM._equipResolved({ Head = 'Some Hat' }, {});
        return string.find(note, 'LOCKED', 1, true) ~= nil;
    end)(), true);
    -- respectLocks = false: a layer ranked ABOVE Locks punches through.
    local _, wPunch = dispatchM._equipResolved({ Head = 'Some Hat', Body = 'Some Body' }, {}, false);
    check('LV5 respectLocks=false punches the layer through the lock', wPunch.Head, 'Some Hat');
    check('LV5b explicit respectLocks=true stops (== the default)',
        select(2, dispatchM._equipResolved({ Head = 'Some Hat' }, {}, true)).Head, nil);

    -- (b) MaxMP vs Locks since the FOLD (stage 6): the row's apply passes the
    -- ordinary respect('MaxMP') into equipResolved -- below Locks the battery
    -- stops at a locked slot, above it punches through. Stub mpBands (the MB*
    -- tests own the band core); the veto guard is what this exercises.
    local savedBands = dispatchM.mpBands;
    dispatchM.modes['maxmp'] = true;
    for k in pairs(dispatchM.locks) do dispatchM.locks[k] = nil; end
    dispatchM.locks['ring1'] = true;
    dispatchM.mpBands = function()
        return { mpMap = { ['mp ring'] = 15 }, target = { ring1 = 'MP Ring' },
                 bands = {}, mpBest = {}, moveYield = false, moving = false, mvMap = {} };
    end;
    local mrow;
    for _, r in ipairs(dispatchM._claimants) do if r.name == 'MaxMP' then mrow = r; end end
    local ctxA = { planOut = {} };
    mrow.apply({ built = { MaxMP = { Ring1 = 'MP Ring' } }, ctx = ctxA,
                 respect = function() return true; end });
    check('LV6 the MaxMP row respects a locked slot while below Locks', ctxA.planOut.Ring1, nil);
    local ctxB = { planOut = {} };
    mrow.apply({ built = { MaxMP = { Ring1 = 'MP Ring' } }, ctx = ctxB,
                 respect = function() return false; end });
    check('LV7 the MaxMP row punches through the lock while above Locks', ctxB.planOut.Ring1, 'MP Ring');

    dispatchM.modes['maxmp'] = nil;
    dispatchM.mpBands = savedBands;
    for k in pairs(dispatchM.locks) do dispatchM.locks[k] = nil; end
    AshitaCore = savedAC;
end)();

-- ---------------------------------------------------------------------------
-- MH. THE MP-HOLD CONSTRAINT (the FOLD, stage 6). The one piece of MaxMP that
--     stays inside equipResolved: a worn battery in a slot the bands do NOT
--     target holds against an MP-lighter incoming piece (the no-band protect),
--     releases when the band says `false`, and stands down when the asking
--     claimant ranks at or above MaxMP (`who` + ctx.rankOf). Worn state comes
--     through the real wornItemName glue (AshitaCore stubbed, the TB idiom).
-- ---------------------------------------------------------------------------
(function()
    local savedAC, savedBands = AshitaCore, dispatchM.mpBands;
    -- Worn stub: 'MP Robe' sits in Body (equip id 5), every other slot empty.
    AshitaCore = {
        GetMemoryManager = function()
            return { GetInventory = function()
                return {
                    GetEquippedItem = function(self, id)
                        if id == 5 then return { Index = 1 }; end
                        return { Index = 0 };
                    end,
                    GetContainerItem = function(self, c, i) return { Id = 9001 }; end,
                };
            end };
        end,
        GetResourceManager = function()
            return { GetItemById = function(self, id) return { Name = { 'MP Robe' } }; end };
        end,
    };
    for k in pairs(dispatchM.locks) do dispatchM.locks[k] = nil; end
    dispatchM.modes['maxmp'] = true;
    dispatchM.mpBands = function()
        return { mpMap = { ['mp robe'] = 50, ['plain robe'] = 0 },
                 target = {}, bands = {}, mpBest = {},
                 moveYield = false, moving = false, mvMap = {} };
    end;
    -- No band target + worn MP-heavier: the incoming piece is held out.
    local nHold, wHold = dispatchM._equipResolved({ Body = 'Plain Robe' }, {});
    check('MH1 no-band worn battery holds the slot', wHold.Body, nil);
    check('MH1b the hold is traced', string.find(nHold, 'MP-HOLD', 1, true) ~= nil, true);
    -- Band target `false`: the set piece flows (release), and says so.
    dispatchM.mpBands = function()
        return { mpMap = { ['mp robe'] = 50, ['plain robe'] = 0 },
                 target = { body = false }, bands = {}, mpBest = {},
                 moveYield = false, moving = false, mvMap = {} };
    end;
    local nRel, wRel = dispatchM._equipResolved({ Body = 'Plain Robe' }, {});
    check('MH2 a false band target releases: the set piece flows', wRel.Body, 'Plain Robe');
    check('MH2b the release is traced', string.find(nRel, 'MP-RELEASE', 1, true) ~= nil, true);
    -- The rank guard: a claimant AT or ABOVE MaxMP is never held -- its win is
    -- the arbitration's answer, and the constraint yields to rank.
    dispatchM.mpBands = function()
        return { mpMap = { ['mp robe'] = 50, ['plain robe'] = 0 },
                 target = {}, bands = {}, mpBest = {},
                 moveYield = false, moving = false, mvMap = {} };
    end;
    local _, wPin = dispatchM._equipResolved({ Body = 'Plain Robe' },
        { rankOf = { Pins = 3, MaxMP = 6 } }, false, 'Pins');
    check('MH3 a claimant above MaxMP is never MP-held', wPin.Body, 'Plain Robe');
    local _, wCr = dispatchM._equipResolved({ Body = 'Plain Robe' },
        { rankOf = { Craft = 7, MaxMP = 6 } }, true, 'Craft');
    check('MH3b a claimant below MaxMP is still held', wCr.Body, nil);
    dispatchM.modes['maxmp'] = nil;
    dispatchM.mpBands = savedBands;
    AshitaCore = savedAC;
end)();

-- ---------------------------------------------------------------------------
-- NK. NAKED (ADR 0021) -- /dl naked strips every slot and HOLDS it empty, as an
--     ordinary Arbiter claimant ranked first, not as a lock.
--
--     Why a claim: a lock only WITHHOLDS (it deletes a slot from a layer's plan
--     -- it cannot take a piece off), it is wiped by every engine self-swap,
--     Pins punch through it by default, and three unrelated buttons release it.
--     A claim is recomputed every dispatch, so a strip the server refuses heals
--     itself -- and precedence becomes the player's, for free.
--
--     The two traps these pin, both of which would ship silently:
--       NK3  the claim must use PROPER-CASE slot keys. equipcore.SLOT_ID is
--            case-sensitive and LuaAshitacast's is not, so a lowercase claim
--            works in LAC and strips NOTHING natively -- broken only in the
--            mode that actually ships.
--       NK8  a row missing from an existing arbstate file must land at its
--            DEFAULT position, not the bottom. Appended, Naked would rank under
--            Locks for every character who ever opened the Priority list.
-- ---------------------------------------------------------------------------
(function()
    local canon = dispatchM._lacSlotsCanon;
    check('NK1 the canonical slot list is the 16', type(canon) == 'table' and #canon, 16);
    -- The equip vocabulary and the /dl lock vocabulary must name the SAME slots.
    -- Compared as SETS, not concatenated: gear\equipcore.lua's SLOT_NAMES is a
    -- third order again, so order equality would be a lie that happens to hold.
    check('NK1b lowercasing the equip vocabulary yields the lock vocabulary', (function()
        for _, s in ipairs(canon) do
            if dispatchM.setLock(string.lower(s), false) == nil then return 'missing ' .. s; end
        end
        return true;
    end)(), true);

    local claim = dispatchM.nakedClaim();
    local n, allRemove = 0, true;
    for _, v in pairs(claim) do n = n + 1; if v ~= 'remove' then allRemove = false; end end
    check('NK2 the claim names all 16 slots', n, 16);
    check('NK2b every value is the unequip literal', allRemove, true);
    check('NK3 keys are PROPER case (a lowercase key is dropped by the native engine)',
        claim.Main == 'remove' and claim.main == nil and claim.Ring1 == 'remove', true);
    claim.Main = 'mutated';
    check('NK4 each call returns a fresh table', dispatchM.nakedClaim().Main, 'remove');

    -- The flag. setNaked is the ONE door; nakedOn the ONE reader.
    dispatchM.nakedArmed = false;
    check('NK5 off by default', dispatchM.nakedOn(), false);
    check('NK5b setNaked(true) returns the new state', dispatchM.setNaked(true), true);
    check('NK5c and arms the flag', dispatchM.nakedOn(), true);
    check('NK5d arming twice is idempotent', dispatchM.setNaked(true), true);
    dispatchM.nakedArmed = 'yes';                     -- a truthy non-true must not count
    check('NK5e only a literal true is armed', dispatchM.nakedOn(), false);
    dispatchM.setNaked(false);
    check('NK5f setNaked(false) disarms', dispatchM.nakedOn(), false);

    -- The rank row.
    local def = dispatchM._arbDefaultOrder;
    local rank = {}; for i, nm in ipairs(def) do rank[nm] = i; end
    check('NK6 exact default rank', table.concat(def, '>'),
        'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    check('NK7 Naked outranks Pins, which outranks Locks',
        rank['Naked'] < rank['Pins'] and rank['Pins'] < rank['Locks'], true);

    -- TRAP: every arbstate file written before v122 lists nine rows and no Naked.
    -- Index 2, not 1: the Disabled ceiling is pinned above every RANKED row
    -- (ADR 0024), so "the top" for a claimant means directly under it.
    check('NK8 a pre-v122 file gets Naked at the TOP, not the bottom',
        dispatchM.arbOrder({ order = { 'Pins', 'Locks', 'AutoAmmo', 'MaxMP',
                                       'Craft', 'HELM', 'Fishing', 'Chocobo', 'Triggers' } })[2], 'Naked');
    check('NK9 a file that places Naked LOW keeps it there (the user has spoken)',
        table.concat(dispatchM.arbOrder({ order = { 'Pins', 'Locks', 'Naked', 'Triggers' } }), '>'),
        'Disabled>Pins>Locks>Naked>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    check('NK10 the restore never duplicates a row', (function()
        local seen = 0;
        for _, nm in ipairs(dispatchM.arbOrder(nil)) do if nm == 'Naked' then seen = seen + 1; end end
        return seen;
    end)(), 1);
    -- The same law from the other end: Chocobo still lands LAST (it did when it
    -- was the new row), so the positional rule did not regress the append case.
    check('NK10b a missing bottom row still lands just above the floor',
        table.concat(dispatchM.arbOrder({ order = { 'Naked', 'Pins', 'Locks', 'AutoAmmo',
                                                    'MaxMP', 'Craft', 'HELM', 'Fishing', 'Triggers' } }), '>'),
        'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');

    -- The pure resolve: Naked beats everything, and the rank list is the ONLY
    -- exception mechanism (this is the "naked except my pins" contract).
    local ord = dispatchM.arbOrder(nil);
    local floor = { Head = 'Idle Hat', Body = 'Idle Robe' };
    local wN, byN = dispatchM.arbResolve(
        { Naked = dispatchM.nakedClaim(), Pins = { Head = 'Pinned Crown' } }, ord, floor);
    check('NK11 Naked wins a pinned slot',       wN.Head, 'remove');
    check('NK11b attributed to Naked',           byN.Head, 'Naked');
    check('NK11c and a floor-only slot',         wN.Body, 'remove');
    local pinTop = dispatchM.arbOrder({ order = { 'Pins', 'Naked', 'Locks', 'AutoAmmo', 'MaxMP',
                                                  'Craft', 'HELM', 'Fishing', 'Chocobo', 'Triggers' } });
    local wP, byP = dispatchM.arbResolve(
        { Naked = dispatchM.nakedClaim(), Pins = { Head = 'Pinned Crown' } }, pinTop, floor);
    check('NK12 drag Pins above Naked -> naked EXCEPT the pin', wP.Head, 'Pinned Crown');
    check('NK12b attributed to Pins',                           byP.Head, 'Pins');
    check('NK12c every other slot is still stripped',           wP.Body, 'remove');
    local lockTop = dispatchM.arbOrder({ order = { 'Locks', 'Naked', 'Pins', 'AutoAmmo', 'MaxMP',
                                                   'Craft', 'HELM', 'Fishing', 'Chocobo', 'Triggers' } });
    local wL = dispatchM.arbResolve(
        { Naked = dispatchM.nakedClaim(), Locks = dispatchM.arbLockClaim({ 'Head' }) }, lockTop, floor);
    check('NK13 drag Locks above Naked -> a locked slot keeps what it wears',
        wL.Head, dispatchM.LOCK_HELD);

    -- Woven MaxMP stands down for free: registering the claim is the whole fix.
    local ceded = dispatchM.arbCededAbove({ Naked = dispatchM.nakedClaim() }, ord, 'MaxMP');
    local nCede = 0;
    for _, who in pairs(ceded) do if who == 'Naked' then nCede = nCede + 1; end end
    check('NK14 MaxMP cedes all 16 slots to Naked (lowercase keys)', nCede, 16);
    check('NK14b including the Ammo slot it would otherwise battery', ceded['ammo'], 'Naked');

    -- (NK15-NK17 RETIRED with nakedVoidsPinReserve, step-1 cleanup
    --  2026-07-27: pins-vs-naked is the verdict's strength contest now.)

    -- THE LIVE EQUIP LAYER. The claim has to survive equipResolved's five post
    -- passes intact -- an all-'remove' table is an input none of them were
    -- written for.
    local savedAC = AshitaCore;
    AshitaCore = nil;                                   -- wornItemName -> nil
    for k in pairs(dispatchM.locks) do dispatchM.locks[k] = nil; end
    local _, wNak = dispatchM._equipResolved(dispatchM.nakedClaim(), {});
    local kept = 0;
    for _, v in pairs(wNak) do if v == 'remove' then kept = kept + 1; end end
    check('NK18 all 16 removes survive the post-passes', kept, 16);
    -- Locked + punching through (Naked ranks above Locks by default).
    dispatchM.setLock('all', true);
    local _, wPunch = dispatchM._equipResolved(dispatchM.nakedClaim(), {}, false);
    local kept2 = 0;
    for _, v in pairs(wPunch) do if v == 'remove' then kept2 = kept2 + 1; end end
    check('NK19 punch-through keeps all 16 even with every slot locked', kept2, 16);
    -- ...and respecting locks (the "drag Locks above Naked" composition) strips them.
    local _, wStop = dispatchM._equipResolved(dispatchM.nakedClaim(), {}, true);
    check('NK20 respecting locks, a locked slot is left alone', wStop.Head, nil);
    for k in pairs(dispatchM.locks) do dispatchM.locks[k] = nil; end

    -- The craft Sub-vs-Main guard DOES run over the naked table (it rides the
    -- shared ctx, which carries craftMainGuard whenever craft is armed). It is
    -- harmless only because 'remove' resolves to no gear record -- so pin that,
    -- or the day the guard learns the literal, naked silently stops taking your
    -- weapon off while a craft Sub is armed.
    local askedWith = nil;
    local _, wGuard = dispatchM._equipResolved(dispatchM.nakedClaim(),
        { craftMainGuard = function(mainName) askedWith = mainName; return true; end });
    check('NK21 the guard IS consulted on the naked table', askedWith, 'remove');
    check('NK21b and a guard that holds would keep the weapon on', wGuard.Main, nil);
    -- What actually saves us is that 'remove' is not a gear record, so the real
    -- guard's early-out fires. Pin the fact itself, not the accident.
    check('NK21c "remove" resolves to no gear record (why the real guard returns false)',
        type(utils.resolveGearName('remove')) == 'table', false);
    local _, wGuard2 = dispatchM._equipResolved(dispatchM.nakedClaim(),
        { craftMainGuard = function(mainName)
              return type(utils.resolveGearName(mainName)) == 'table';   -- the real guard's early-out
          end });
    check('NK21d so Main comes off even with a craft Sub armed', wGuard2.Main, 'remove');
    AshitaCore = savedAC;

    -- /dl why: sixteen identical winner lines would bury everything else it says,
    -- so a whole-sweep Naked collapses to one line -- naming who it beat.
    local why = table.concat(dispatchM.arbWhyLines(
        { Naked = dispatchM.nakedClaim(), Pins = { Head = 'Pinned Crown' } }, ord, floor), '\n');
    check('NK22 /dl why collapses the sweep into ONE line',
        select(2, why:gsub('NAKED %(rank 2%)', '')), 1);
    check('NK22b it counts the slots',   why:find('holds 16 slots empty', 1, true) ~= nil, true);
    check('NK22c and names who it beat', why:find('over Pins (rank 3)', 1, true) ~= nil, true);
    check('NK22d no per-slot Naked line survives', why:find('Head: Naked', 1, true), nil);

    -- The command tokens. dispatch's handler only registers inside engineActive(),
    -- which is false headlessly, so the whitelist cannot be driven -- pin it as
    -- SOURCE instead (the v46 trap: a subcommand missing from the whitelist
    -- returns in silence and looks like the command does not exist).
    local src = (function() local f = io.open('dispatch.lua', 'r'); local d = f:read('*a'); f:close(); return d; end)();
    local wl = src:match("\n%s*if sub ~= 'mode'[^\n]*\n");
    check('NK23 the command whitelist is findable', wl ~= nil, true);
    check('NK23b naked is whitelisted', wl and wl:find("sub ~= 'naked'", 1, true) ~= nil, true);
    check('NK23c dress is whitelisted',  wl and wl:find("sub ~= 'dress'", 1, true) ~= nil, true);
    check('NK24 the strip flag is carried across a self-swap, not reset',
        src:find('M.nakedArmed = (M.nakedArmed == true);', 1, true) ~= nil, true);

    -- arbwatch's headless fallback is DEAD whenever dispatch loads -- which is
    -- both Lua states and every other AB check -- so a drifting mirror ships
    -- green. Force the branch by hiding dispatch from the require.
    local savedDsp = package.loaded['dlac\\dispatch'];
    package.loaded['dlac\\dispatch'] = nil;
    local awNo = dofile('feature/arbwatch.lua');
    package.loaded['dlac\\dispatch'] = savedDsp;
    check('NK25 the no-dispatch fallback agrees on the default order',
        table.concat(awNo.defaultOrder(), '>'), table.concat(def, '>'));
    check('NK25b and on the positional restore',
        table.concat(awNo.sanitize({ order = { 'Pins', 'Locks', 'AutoAmmo', 'MaxMP',
                                               'Craft', 'HELM', 'Fishing', 'Chocobo', 'Triggers' } }), '>'),
        table.concat(dispatchM.arbOrder({ order = { 'Pins', 'Locks', 'AutoAmmo', 'MaxMP',
                                               'Craft', 'HELM', 'Fishing', 'Chocobo', 'Triggers' } }), '>'));
    -- NK25c: and on preserving unknown rows (issue #136). The no-dispatch mirror
    -- of arbOrderPersist must weave an unknown row back exactly as the engine does.
    do
        local rawG = { order = { 'Disabled', 'Naked', 'Pins', 'Locks', 'AutoAmmo',
            'MaxMP', 'Ghost', 'Craft', 'HELM', 'Fishing', 'Chocobo', 'Triggers' } };
        local dragK = { 'Disabled', 'Naked', 'Pins', 'Locks', 'AutoAmmo', 'MaxMP',
            'Craft', 'HELM', 'Fishing', 'Chocobo', 'Triggers' };
        check('NK25c the no-dispatch fallback preserves unknown rows identically',
            table.concat(awNo.persist(dragK, rawG), '>'),
            table.concat(dispatchM.arbOrderPersist(dragK, rawG), '>'));
    end

    -- NK26. END TO END through the REAL M.dispatch.
    --
    -- Worth its own note: until this check, M.dispatch was called ZERO times by
    -- the suite -- every other test drives a pure seam under it. So the wiring
    -- BETWEEN the seams (the bail guard, the claims table, the rank walk, the
    -- apply closure) was covered by nothing, and a local that fell out of scope
    -- would not be an error in Lua -- it would silently become a nil GLOBAL and
    -- the strip would just not happen. Naked is the cheapest possible driver for
    -- it: with the flag on and NOTHING else armed -- no triggers, no pins, no
    -- hobby, no ammo -- a bare dispatch must still produce all 16 removes, which
    -- is exactly the path the bail guard has to let through.
    local savedPlayer, savedFunc, savedState = TEST_PLAYER, rawget(_G, 'gFunc'), rawget(_G, 'gState');
    TEST_PLAYER = { MainJob = 'WHM', MainJobLevel = 75, SubJob = 'BLM', SubJobLevel = 37,
                    MainJobSync = 75, SubJobSync = 37, Status = 'Idle', IsMoving = false };
    local wrote = {};
    -- The NATIVE equip door (purge Phase 2: gFunc.EquipSet is gone) -- stub
    -- equipengine so engineEquipSet routes the resolved set into `wrote`.
    local savedEngNK = package.loaded['dlac\\feature\\equipengine'];
    package.loaded['dlac\\feature\\equipengine'] = {
        nativeOn = function() return true; end,
        equipSet = function(t) for k, v in pairs(t or {}) do wrote[k] = v; end end,
        state = { tripped = false },
    };
    _G.gState = { CurrentCall = 'N/A', Disabled = {} };
    dispatchM.nakedArmed = true;
    local okDisp, dispErr = pcall(dispatchM.dispatch, 'Default');
    check('NK26 a bare Default dispatch with only naked armed does not throw', okDisp, true);
    if not okDisp then print('NK26 error: ' .. tostring(dispErr)); end
    local nWrote, allRm = 0, true;
    for _, v in pairs(wrote) do nWrote = nWrote + 1; if v ~= 'remove' then allRm = false; end end
    check('NK26b it reaches the equip door with all 16 slots', nWrote, 16);
    check('NK26c every one of them is an unequip', allRm, true);
    check('NK26d proper case survives the whole path', wrote.Ring1, 'remove');
    -- A local that escaped its block would show up here as a nil-valued global
    -- turned real -- the failure mode the check above cannot see on its own.
    local leaked = nil;
    for _, nm in ipairs({ 'nakedOn', 'nEquip', 'nSig', 'rankOf', 'claims', 'nakedSlots' }) do
        if rawget(_G, nm) ~= nil then leaked = nm; break; end
    end
    check('NK26e no dispatch local leaked to the globals', leaked, nil);
    -- ...and with the flag OFF the same bare dispatch writes nothing at all.
    dispatchM.nakedArmed = false;
    wrote = {};
    pcall(dispatchM.dispatch, 'Default');
    check('NK26f released, a bare dispatch writes nothing', next(wrote), nil);

    -- NK27. The __naked mirror, through the REAL saveModeState onto disk. It must
    -- be written even when nothing changed: an early return there strands a stale
    -- mirror -- quit the client while naked and the next launch is genuinely
    -- dressed, but the file still says true, so the GUI draws the red NAKED button
    -- and clicking it (setNaked(false) on an already-false flag) would write
    -- nothing and never clear it.
    dispatchM._charDirOverride = 'tests' .. string.char(92);
    local function readMirror()
        local f = io.open('tests' .. string.char(92) .. 'modestate.lua', 'r');
        if f == nil then return nil; end
        local d = f:read('*a'); f:close(); return d;
    end
    os.remove('tests' .. string.char(92) .. 'modestate.lua');
    dispatchM.nakedArmed = false;
    dispatchM.setNaked(false);                                  -- no change at all
    local m0 = readMirror();
    check('NK27 setNaked writes the mirror even when nothing changed', m0 ~= nil, true);
    check('NK27b and it reads false', m0 and m0:find('["__naked"] = false', 1, true) ~= nil, true);
    dispatchM.setNaked(true);
    check('NK27c arming flips it to true',
        (readMirror() or ''):find('["__naked"] = true', 1, true) ~= nil, true);
    check('NK27d the flag lives OUTSIDE M.modes (no collision with a user Mode)',
        dispatchM.modes['naked'], nil);

    -- NK28. THE DISARM WATCH -- the relog guard the ADR calls the worst possible
    -- outcome to get wrong, plus the job-change drop (Henrik, 07-25). M.nakedArmed
    -- rides across a relog on its own (an Ashita addon survives a logout, and LAC
    -- never clears package.loaded), so this watch is what actually clears it.
    check('NK28 same job, in the world -> stays armed', dispatchM.nakedWorldWatch(7, 7), nil);
    check('NK28b and the flag is untouched',    dispatchM.nakedOn(), true);
    -- ZONES SURVIVE (Henrik, 2026-07-27): a zone load reads job 0/nil exactly
    -- like character select, so absence alone HOLDS -- only outlasting a zone
    -- (WORLD_GONE_S) or returning with a different job drops. `now` injected.
    check('NK28c a world-gone read HOLDS (a zone load looks like char select)',
        dispatchM.nakedWorldWatch(0, 7), nil);
    check('NK28c2 still armed through the load', dispatchM.nakedOn(), true);
    check('NK28c3 coming back the SAME job keeps it', dispatchM.nakedWorldWatch(7, 0), nil);
    check('NK28c4 ...armed', dispatchM.nakedOn(), true);
    dispatchM.nakedWorldWatch(0, 7);
    check('NK28c5 outlasting a zone disarms', dispatchM.nakedWorldWatch(0, 7, 1e9), 'world');
    check('NK28d you come back dressed',        dispatchM.nakedOn(), false);
    check('NK28e the mirror follows it down',
        (readMirror() or ''):find('["__naked"] = false', 1, true) ~= nil, true);
    dispatchM.setNaked(true);
    dispatchM.nakedWorldWatch(nil, 7);
    check('NK28f a nil job read holds too, then times out the same way',
        dispatchM.nakedWorldWatch(nil, 7, 1e9), 'world');
    dispatchM.setNaked(true);
    -- Returning from absence with a DIFFERENT job still disarms because the
    -- tick's _tickJob latch only advances on LIVE reads (source-pinned
    -- below), so the return is judged against the job you LEFT with.
    check('NK28f2 returning from absence with a DIFFERENT job disarms',
        (function() dispatchM.nakedWorldWatch(7, 7); dispatchM.nakedWorldWatch(0, 7);
                    return dispatchM.nakedWorldWatch(3, 7); end)(), 'job');
    check('NK28f3 the tick latches prevJob on LIVE reads only (source pin)',
        (function() local f = io.open('dispatch.lua', 'r'); local d = f:read('*a'); f:close();
            return d:find('if j ~= nil and j ~= 0 then', 1, true) ~= nil
               and d:find('_tickJob = j;', 1, true) ~= nil; end)(), true);
    dispatchM.setNaked(true);
    check('NK28g a JOB CHANGE disarms',         dispatchM.nakedWorldWatch(3, 7), 'job');
    check('NK28h ...and dresses you',           dispatchM.nakedOn(), false);
    -- The first in-world read of a session has no previous job to compare
    -- against; latching it must not read as a change and strip you at login.
    dispatchM.setNaked(true);
    check('NK28i the first job latch is not a change', dispatchM.nakedWorldWatch(7, nil), nil);
    check('NK28j nor is coming back from character select',
        dispatchM.nakedWorldWatch(7, 0), nil);
    check('NK28k still armed through both',     dispatchM.nakedOn(), true);
    check('NK28l it only ever CLEARS, never arms', (function()
        dispatchM.nakedWorldWatch(0, 7);                     -- absence starts
        dispatchM.nakedWorldWatch(0, 7, 1e9);                -- ...and times out (disarm)
        return dispatchM.nakedWorldWatch(0, 7, 1e9) == nil and dispatchM.nakedOn() == false;
    end)(), true);
    -- NK29. THE LOCKSTYLE REFUSAL, on the door that actually runs.
    --
    -- lockstyleapply freezes every slot the box does not name to the WORN id --
    -- which is 0 while stripped, and style 0 renders the slot EMPTY. The server
    -- keeps styles per slot, so that outlives /dl dress, and because a style
    -- survives having no armor the player never sees it happen.
    --
    -- The refusal must sit in feature/lockstyle._applyDirect, NOT only in the
    -- engine's apply half: _applyDirect is the addon-resident executor that the
    -- GUI Apply button, the native typed handler and every SCRIPTED apply (town
    -- transitions, OnLoad restore, keep-on-subjob) funnel into -- and those last
    -- three fire with NO user action, so a naked player zoning into town would
    -- otherwise style themselves permanently bare.
    (function()
        local lsN = dofile('feature/lockstyle.lua');
        check('NK29 lockstyle exposes the naked read', type(lsN._nakedArmed), 'function');
        local applied = 0;
        local savedCap = lsN._capNote;
        local notes = {};
        lsN._capNote = function(t) notes[#notes + 1] = tostring(t); end
        -- Stand in for the naked read (the real one asks dispatch natively, or the
        -- __naked mirror in legacy -- neither is reachable headless).
        local armed = true;
        lsN._nakedArmed = function() return armed; end
        -- Re-point the module's own reference so _applyDirect sees the stub: the
        -- upvalue is a file-local, so the test drives the exported seam instead.
        local okRefuse = pcall(lsN._applyDirect, 1);
        check('NK29b applying while naked does not throw', okRefuse, true);
        local refused = false;
        for _, n in ipairs(notes) do if n:find('naked', 1, true) then refused = true; end end
        check('NK29c ...and is recorded as a refusal', refused, true);
        lsN._capNote = savedCap;
    end)();

    os.remove('tests' .. string.char(92) .. 'modestate.lua');
    dispatchM._charDirOverride = nil;

    TEST_PLAYER = savedPlayer;
    _G.gFunc, _G.gState = savedFunc, savedState;
    package.loaded['dlac\\feature\\equipengine'] = savedEngNK;
    dispatchM.nakedArmed = false;
end)();

-- ---------------------------------------------------------------------------
-- CR. THE CLAIMANT REGISTRY (ADR 0027, stage 0 -- engine v136). CLAIMANTS is
--     the one table M.dispatch's ensure pass, both bail guards, the claims
--     map, the signature legs, the rank-walk applies and /dl prio all
--     iterate; these pin its SHAPE as data, so the silent-bail class (a
--     missed bail term, a missed signature leg) cannot come back as drift.
--     NK26 above drives the rewired dispatch body end to end; these drive
--     the rows directly.
-- ---------------------------------------------------------------------------
(function()
    local reg = dispatchM._claimants;
    check('CR0 the registry is exported', type(reg), 'table');

    -- One row per rank row except the Triggers floor -- both directions.
    local names = {};
    for _, row in ipairs(reg) do names[row.name] = true; end
    local missing, extra, inOrder = {}, {}, {};
    for _, n in ipairs(dispatchM._arbDefaultOrder) do
        if n ~= 'Triggers' then
            inOrder[n] = true;
            if not names[n] then missing[#missing + 1] = n; end
        end
    end
    for n in pairs(names) do
        if not inOrder[n] then extra[#extra + 1] = n; end
    end
    check('CR1 every rank row except Triggers has a registry row', table.concat(missing, ','), '');
    -- JobHelper (issue #138) is the ONE registry row deliberately NOT in the
    -- GLOBAL ARB_ORDER_DEFAULT: its Claim Priority position is per job, woven into
    -- the live order by jobHelperPlace, so it is an intentional "extra".
    table.sort(extra);
    check('CR1b the only registry row without a global rank row is the per-job JobHelper',
        table.concat(extra, ','), 'JobHelper');
    -- #reg = (#order - 1 for the floorless Triggers) + 1 for the per-job JobHelper.
    check('CR1c the row count is exact', #reg, #dispatchM._arbDefaultOrder);

    -- The signature-leg order keeps the pre-registry byte order for the nine
    -- original legs -- craft | pins | HELM | fishing | chocobo | ammo | mp |
    -- naked | disabled -- with every later row APPENDED (JobHelper #138,
    -- External 2026-08-01, ModeLock 2026-08-03): a new trailing leg leaves the
    -- earlier ones byte-identical, so no live session retraces on upgrade until
    -- that row actually claims. Reordering them still retraces: on purpose or
    -- not at all.
    check('CR2 the signature legs keep the pre-registry byte order, later rows appended',
        table.concat(dispatchM._claimantSigOrder, '|'),
        'Craft|Pins|HELM|Fishing|Chocobo|AutoAmmo|MaxMP|Naked|Disabled|JobHelper|External|ModeLock');

    -- The documented exceptions are EXACTLY the documented exceptions. Since
    -- the FOLD (stage 6) EVERY row builds its claim and applies through the
    -- registry -- MaxMP was the last exception and it is gone. Locks: no
    -- signature leg (pre-registry parity -- it never had one).
    local noClaim, noApply, noSig = {}, {}, {};
    for _, row in ipairs(reg) do
        if row.claim == nil then noClaim[#noClaim + 1] = row.name; end
        if row.apply == nil then noApply[#noApply + 1] = row.name; end
        if row.sig == nil then noSig[#noSig + 1] = row.name; end
    end
    check('CR3 every row has a claim builder (the fold closed the MaxMP exception)', table.concat(noClaim, ','), '');
    check('CR3b every row has an apply (the weave is dead)', table.concat(noApply, ','), '');
    check('CR3c Locks is the only row without a signature leg', table.concat(noSig, ','), 'Locks');

    -- The bail sets: Disabled and MaxMP sit out BOTH bails by design (free
    -- equip or a bare mode is not a reason to dispatch); the other eight
    -- participate in both.
    local b1, b2 = {}, {};
    for _, row in ipairs(reg) do
        if row.bail1 == true then b1[#b1 + 1] = row.name; end
        if row.bail2 == true then b2[#b2 + 1] = row.name; end
    end
    table.sort(b1); table.sort(b2);
    check('CR4 the bail #1 set is exactly the dispatch reasons (JobHelper #138, ModeLock 2026-08-03)',
        table.concat(b1, ','),
        'AutoAmmo,Chocobo,Craft,External,Fishing,HELM,JobHelper,Locks,ModeLock,Naked,Pins');
    check('CR4b the bail #2 set is the same rows', table.concat(b2, ','), table.concat(b1, ','));
    check('CR4c every row carries a prioStatus (the /dl prio twin is dead)',
        (function()
            for _, row in ipairs(reg) do if type(row.prioStatus) ~= 'function' then return row.name; end end
            return true;
        end)(), true);

    -- The rows themselves, driven directly -- the same tables the dispatch
    -- loops hand them.
    local by = {};
    for _, row in ipairs(reg) do by[row.name] = row; end

    -- Pins: active on a non-empty state; the claim builds even when inactive
    -- (scoped pins decide inside pinOverlayFor, against the dispatch's hits).
    check('CR5 pins are active on a non-empty state', by['Pins'].active({ Head = { item = 'X' } }), true);
    check('CR5b and inactive on an empty one', by['Pins'].active({}), false);
    local pinsBuilt = by['Pins'].claim({ Head = { item = 'Pinned Crown', scope = 'All' } }, false,
        { hits = {}, event = 'Default' });
    check('CR5c the pin claim builds regardless of active', type(pinsBuilt), 'table');
    check('CR5d and carries the pinned item', pinsBuilt.Head, 'Pinned Crown');

    -- Craft: the active predicate is the enabled-plus-name check, verbatim.
    check('CR6 craft is active when enabled with a craft name',
        by['Craft'].active({ enabled = true, craft = 'Alchemy' }), true);
    check('CR6b not without the name', by['Craft'].active({ enabled = true }), false);
    check('CR6c not when disabled', by['Craft'].active({ enabled = false, craft = 'Alchemy' }), false);

    -- The signature legs: generic = sorted slot=item, '' on nil; the specials
    -- keep their exact pre-registry spellings.
    check('CR7 the generic leg is sorted slot=item',
        by['Craft'].sig({ Body = 'Weaver Apron', Head = 'Chef Hat' }), 'Body=Weaver Apron,Head=Chef Hat');
    check('CR7b a nil claim is a quiet leg', by['Craft'].sig(nil), '');
    check('CR7c AutoAmmo names only the Ammo decision',
        by['AutoAmmo'].sig({ Ammo = 'Iron Arrow' }), 'Ammo=Iron Arrow');
    check('CR7d naked is the flag, not a table walk', by['Naked'].sig(nil, true), 'NAKED');
    check('CR7e released naked is quiet', by['Naked'].sig(nil, false), '');

    -- An apply through the REAL equipResolved and the REAL write seam: the
    -- row's overlay lands on the (stubbed) engine and traces its line.
    dispatchM.setLock('all', false);   -- a stray lock from an earlier section must not hold the slot
    local savedEngCR = package.loaded['dlac\\feature\\equipengine'];
    local wroteCR = {};
    package.loaded['dlac\\feature\\equipengine'] = {
        nativeOn = function() return true; end,
        equipSet = function(t) for k, v in pairs(t or {}) do wroteCR[k] = v; end end,
        state = { tripped = false },
    };
    local linesCR = {};
    by['Craft'].apply({ built = { Craft = { Body = 'Weaver Apron' } }, bx = {},
                        ctx = {}, retrace = true, lines = linesCR,
                        respect = function() return true; end, rankOf = {} });
    check('CR8 a row apply reaches the equip door', wroteCR.Body, 'Weaver Apron');
    check('CR8b and traces the overlay slot list', linesCR[1], 'craft gear (overlay)  ->  Body');
    package.loaded['dlac\\feature\\equipengine'] = savedEngCR;

    -- /dl prio's status strings come from the rows now. Naked is provably off
    -- (NK's cleanup above); Locks/Disabled are pattern-checked so a stray
    -- state from an earlier section cannot flake the wording pin.
    check('CR9 prio: naked reads off', by['Naked'].prioStatus(), 'off');
    check('CR9b prio: the Locks row reports the VETO, not the locked set',
        by['Locks'].prioStatus():find('veto', 1, true) ~= nil, true);
    check('CR9c prio: the ceiling names itself',
        by['Disabled'].prioStatus():find('ceiling', 1, true) ~= nil, true);

    -- CR10. The AutoAmmo prio line is JOB-AWARE (v137 -- Henrik's stage-0
    -- field report: the file-level read said ON on a job with no setup).
    -- Driven through the pure seam: fmt-2 sections, the fmt-1 jobs gate
    -- (resolveAmmoPlan's, mirrored), the who-has-it naming, and the nil-job
    -- fallback to the file-level answer. ammoStateOn itself stays file-level
    -- (it feeds the dispatch bail) -- CR10i pins that it did not move.
    local ajl = dispatchM._ammoJobLine;
    local AMMO_ON = 'ON (claims Ammo on shooting events)';
    local fmt2 = { jobs = { DRK = { enabled = true,  ammo = { { name = 'Acid Bolt' } } },
                            WAR = { enabled = false, ammo = { { name = 'Stone' } } } } };
    check('CR10 fmt2: the set-up job reads ON', ajl(fmt2, 'DRK'), AMMO_ON);
    check('CR10b fmt2: another job reads off AND names who has it',
        ajl(fmt2, 'SCH'), 'off (this job -- set up on DRK)');
    check('CR10c fmt2: a disabled section is not "set up"',
        ajl(fmt2, 'WAR'), 'off (this job -- set up on DRK)');
    check('CR10d a nil job falls back to the file-level answer', ajl(fmt2, nil), AMMO_ON);
    local fmt1 = { enabled = true, ammo = { 'Iron Arrow' }, jobs = { RNG = true } };
    check('CR10e fmt1: the gated-in job reads ON', ajl(fmt1, 'RNG'), AMMO_ON);
    check('CR10f fmt1: a gated-out job reads off and names the gate',
        ajl(fmt1, 'SCH'), 'off (this job -- set up on RNG)');
    check('CR10g fmt1: no jobs map = every job',
        ajl({ enabled = true, ammo = { 'X' } }, 'SCH'), AMMO_ON);
    check('CR10h an absent state is off', ajl(nil, 'DRK'), 'off');
    check('CR10i ammoStateOn stays file-level (the bail read is untouched)',
        dispatchM._ammoStateOn(fmt2), true);
end)();

-- ---------------------------------------------------------------------------
-- LD. THE SLOT LADDER (ADR 0027, stage 1 -- utils.slotLadder/flattenHead +
--     dispatch.candidatesFor). BuildDynamicSets now DERIVES its pick from the
--     ladder's head, so parity holds by construction; these pin the pieces:
--     the comparator as data, the composition encodings, the pass-2 virtual
--     quirk (preserved on purpose), and the on-demand door with its memo.
-- ---------------------------------------------------------------------------
(function()
    local cctx = { mjLevel = 50, isDW = false };
    local L = utils.slotLadder;
    local H = utils.flattenHead;

    -- The comparator: a live range beats an unbounded level (the Garrison
    -- Tunica field case), level within tier, earlier entry on ties.
    local lad = L({ { Name = 'Druid Robe', Level = 50 },
                    { Name = 'Garrison Tunica', Level = 20, minLevel = 20, maxLevel = 51 } },
                  'Body', nil, cctx);
    check('LD1 a live range outranks a higher unbounded level', lad.items[1].name, 'Garrison Tunica');
    check('LD1b the unbounded piece is rung 2, not discarded', lad.items[2].name, 'Druid Robe');
    check('LD1c the head is the flatten pick', (H(lad, 'Body')), 'Garrison Tunica');
    lad = L({ { Name = 'First', Level = 40 }, { Name = 'Second', Level = 40 } }, 'Body', nil, cctx);
    check('LD2 an exact tie keeps the earlier entry', lad.items[1].name, 'First');
    lad = L({ { Name = 'Too Big', Level = 60 }, { Name = 'Fits', Level = 10 } }, 'Body', nil, cctx);
    check('LD3 an over-level entry is not a rung at all', #lad.items, 1);
    check('LD3b the declared window gates too',
        #L({ { Name = 'Old Cap', Level = 5, maxLevel = 30 } }, 'Body', nil, cctx).items, 0);

    -- The mode tier (save/restore the real dispatch binding).
    local savedDM = utils.dispatchModule;
    utils.dispatchModule = { modeActive = function(v) return v == 'DT' end };
    lad = L({ { Name = 'Plain Body', Level = 40 }, { Name = 'DT Body', Level = 10, mode = 'DT' } },
            'Body', nil, cctx);
    check('LD4 an ACTIVE mode entry outranks every unconditional one', lad.items[1].name, 'DT Body');
    check('LD4b the unconditional piece is its fallback rung', lad.items[2].name, 'Plain Body');
    lad = L({ { Name = 'Plain Body', Level = 40 }, { Name = 'PDT Body', Level = 10, mode = 'PDT' } },
            'Body', nil, cctx);
    check('LD4c an INACTIVE mode entry is excluded outright', #lad.items, 1);

    -- The Dual Wield gear rule (dw = true): a pure GATE, not a tier -- without
    -- the trait the entry is not a rung at all; with it, normal ranking decides.
    local dwList = { { Name = 'Plain Ear', Level = 20 },
                     { Name = 'Suppanomimi', Level = 30, dw = true } };
    lad = L(dwList, 'Ear1', nil, cctx);                       -- cctx.isDW = false
    check('LD4d a dw entry without the trait is excluded outright', #lad.items, 1);
    check('LD4e ...and the plain piece owns the slot', lad.items[1].name, 'Plain Ear');
    lad = L(dwList, 'Ear1', nil, { mjLevel = 50, isDW = true });
    check('LD4f with the trait it ranks like any entry (level wins)', lad.items[1].name, 'Suppanomimi');
    check('LD4g the plain piece stays as its fallback rung', lad.items[2].name, 'Plain Ear');

    -- Virtuals: marker|fallback composition + the minLevel rung law.
    utils.dispatchModule = { virtualMinLevel = function() return 3 end };
    lad = L({ 'dlac:AutoStaff', { Name = 'Maple Wand', Level = 5 } }, 'Main', nil, cctx);
    check('LD5 the virtual tops the slot with the item as fallback',
        (H(lad, 'Main')), 'dlac:AutoStaff|Maple Wand');
    local _, moLD = H(lad, 'Main');
    check('LD5b a Main staff marker synthesizes the 2H pairing object', moLD.Type, 'Staff');
    utils.dispatchModule = { virtualMinLevel = function() return 60 end };
    lad = L({ 'dlac:AutoStaff', { Name = 'Maple Wand', Level = 5 } }, 'Main', nil, cctx);
    check('LD5c below the marker level the real pick owns the slot',
        (H(lad, 'Main')), 'Maple Wand');
    utils.dispatchModule = savedDM;

    -- Sub pairing per CANDIDATE: a 2H main takes grips, never shields.
    local twoH = { Name = 'Heavy Great Axe', Type = 'Great Axe', OneHanded = false, Level = 1 };
    lad = L({ { Name = 'Kite Shield', Type = 'Shield', Level = 1 },
              { Name = 'Dark Grip', Type = 'Sub', Level = 1 } }, 'Sub', twoH, cctx);
    check('LD6 a 2H main gates the Sub ladder to grips', #lad.items, 1);
    check('LD6b and the grip is the rung', lad.items[1].name, 'Dark Grip');

    -- LD6c-LD6h. THE SECOND COPY IS READ LIVE (Coffeepoo, 2026-08-03: two Bone
    -- Knives +1, the Main took one and the Sub was left as worn). The same-name
    -- off-hand rule wants proof of a second copy; the flatten used to offer
    -- subSlotAllowed nothing but the record's `Count`, a stamp written once at
    -- first index that no command can refresh -- so a weapon bought AFTER its
    -- twin was indexed could never pair. The engine's bag reader answers now.
    local dwctx = { mjLevel = 50, isDW = true };
    local knife = { Name = 'Bone Knife +1', Type = 'Dagger', OneHanded = true, Level = 46, Id = 17611 };
    utils.dispatchModule = { bagCopies = function() return 2; end };
    check('LD6c live bags prove the second copy -- the twin pairs',
        #L({ knife }, 'Sub', knife, dwctx).items, 1);
    utils.dispatchModule = { bagCopies = function() return 1; end };
    check('LD6d one copy live -> the same-name off-hand is still refused',
        #L({ knife }, 'Sub', knife, dwctx).items, 0);
    -- The live read ADDS evidence, never subtracts it: a stamped Count still
    -- wins, so nothing that pairs today can stop pairing.
    local stamped = { Name = 'Bone Knife +1', Type = 'Dagger', OneHanded = true,
                      Level = 46, Id = 17611, Count = 2 };
    check('LD6e a stamped Count survives a live count of one',
        #L({ stamped }, 'Sub', stamped, dwctx).items, 1);
    utils.dispatchModule = { bagCopies = function() error('bags unreadable'); end };
    check('LD6f an unreadable bag read falls back to the stamp',
        #L({ stamped }, 'Sub', stamped, dwctx).items, 1);
    check('LD6g ...and refuses on no stamp rather than guessing',
        #L({ knife }, 'Sub', knife, dwctx).items, 0);
    -- A DIFFERENT off-hand never asks the bags at all (the rule only counts
    -- copies when the names match) -- pinned by an exploding reader.
    local other = { Name = 'Mercenary\'s Knife', Type = 'Dagger', OneHanded = true, Level = 20, Id = 16746 };
    check('LD6h a different-named off-hand pairs without a bag lookup',
        #L({ other }, 'Sub', knife, dwctx).items, 1);
    utils.dispatchModule = savedDM;

    -- The AutoAcc pool: its own winner, composed only under no virtual.
    lad = L({ { Name = 'Plain Ring', Level = 40 },
              { Name = 'Acc Ring', Level = 30, autoType = 'AutoAcc', removePrio = 2, acc = 15 } },
            'Ring1', nil, cctx);
    check('LD7 the acc pool never contests the normal pick', lad.items[1].name, 'Plain Ring');
    check('LD7b it composes the AutoAcc marker over the fallback',
        (H(lad, 'Ring1')), 'dlac:AutoAcc:2:15:Acc Ring|Plain Ring');

    -- LD7c-e. An augment-PINNED winner (augment-split records) flattens as the
    -- table entry form so the AugKey reaches the resolver -- a bare name would
    -- equip whichever roll the bag scan found first. Unpinned winners keep the
    -- plain-string head byte-identical.
    lad = L({ { Name = 'Hecatomb Mittens +1', Level = 50, AugKey = '23:3|258:6', AugText = 'Acc+3, Dagger Skill+6' } },
            'Hands', nil, cctx);
    local pinHead = H(lad, 'Hands');
    check('LD7c a pinned winner flattens as { Name, AugKey }',
        type(pinHead) == 'table' and pinHead.Name == 'Hecatomb Mittens +1'
        and pinHead.AugKey == '23:3|258:6', true);
    lad = L({ { Name = 'Hecatomb Mittens +1', Level = 50 } }, 'Hands', nil, cctx);
    check('LD7d an unpinned winner keeps the plain-string head',
        H(lad, 'Hands'), 'Hecatomb Mittens +1');
    -- ...and the arbiter reasons about a pinned entry by its Name: the floor
    -- merge and the reserve walk must SEE the slot, not skip it as a non-string.
    local ARBt = dofile('gear/arbiter.lua');
    local fl = ARBt.reserveFloor({ { prio = 1, set = { Hands = pinHead }, src = 'S' } });
    check('LD7e the floor merges a pinned entry by Name',
        fl.Hands ~= nil and fl.Hands.name == 'Hecatomb Mittens +1', true);
    local rd = ARBt.reservedDrops(
        { Body = 'Vermillion Cloak', Head = pinHead },
        function(nm) return (nm == 'Vermillion Cloak') and 0x0010 or 0; end);   -- Body reserves Head
    check('LD7f a reserver still drops a pinned slot (judged by its Name)',
        rd ~= nil and rd.Head, 'Vermillion Cloak');

    -- The pass-2 virtual re-adoption QUIRK, preserved on purpose (see the
    -- slotLadder comment): with no eligible mode item, the last BARE virtual
    -- beats a later mode-gated one; with one, file order stands.
    utils.dispatchModule = { modeActive = function(v) return v == 'DT' end };
    local quirk = { 'dlac:AutoObi', { gear = 'dlac:AutoStaff', mode = 'DT' } };
    check('LD8 no mode item -> the bare virtual re-adopts last',
        L(quirk, 'Waist', nil, cctx).virt, 'dlac:AutoObi');
    local quirk2 = { 'dlac:AutoObi', { gear = 'dlac:AutoStaff', mode = 'DT' },
                     { Name = 'DT Belt', Level = 10, mode = 'DT' } };
    check('LD8b a mode item present -> file order stands',
        L(quirk2, 'Waist', nil, cctx).virt, 'dlac:AutoStaff');
    utils.dispatchModule = savedDM;

    -- LD9. PARITY BY CONSTRUCTION, verified anyway: a full BuildDynamicSets
    -- run equals flattenHead over each slot's own ladder.
    local savedPlayerLD = TEST_PLAYER;
    TEST_PLAYER = { MainJob = 'WHM', MainJobLevel = 50, SubJob = 'BLM', SubJobLevel = 25,
                    MainJobSync = 50, SubJobSync = 25, Status = 'Idle', IsMoving = false };
    local dynLD = {
        Main = { 'dlac:AutoStaff', { Name = 'Pilgrim Wand', Type = 'Staff', OneHanded = false, Level = 1 } },
        Sub  = { { Name = 'Dark Grip', Type = 'Sub', Level = 1 },
                 { Name = 'Kite Shield', Type = 'Shield', Level = 1 } },
        Body = { { Name = 'Druid Robe', Level = 50 },
                 { Name = 'Garrison Tunica', Level = 20, minLevel = 20, maxLevel = 51 } },
    };
    local setsP = { Dynamic = { LadP = dynLD } };
    utils.BuildDynamicSets(setsP);
    local cctxP = utils._lastFlattenCtx;
    check('LD9 the flatten stamps its context', type(cctxP), 'table');
    local mladP = utils.slotLadder(dynLD.Main, 'Main', nil, cctxP);
    local headM, moP = utils.flattenHead(mladP, 'Main');
    check('LD9b Main parity', headM, setsP.LadP.Main);
    check('LD9c Sub parity (judged against the derived Main)',
        (utils.flattenHead(utils.slotLadder(dynLD.Sub, 'Sub', moP, cctxP), 'Sub')), setsP.LadP.Sub);
    check('LD9d Body parity',
        (utils.flattenHead(utils.slotLadder(dynLD.Body, 'Body', nil, cctxP), 'Body')), setsP.LadP.Body);
    TEST_PLAYER = savedPlayerLD;

    -- LD10. The on-demand door + its memo epoch (dispatch.candidatesFor).
    -- dispatch reaches utils through utilsModule() -> require('dlac\\utils');
    -- seed package.loaded with THE harness's own utils instance so the door
    -- and the epoch bump below talk about the same module (the RQU idiom).
    local savedPkgU = package.loaded['dlac\\utils'];
    package.loaded['dlac\\utils'] = utils;
    local savedNS = dispatchM._nativeSets;
    dispatchM._nativeSets = { Dynamic = { CF = { Body = { { Name = 'X Robe', Level = 10 } } } } };
    local l1 = dispatchM.candidatesFor('CF', 'Body');
    check('LD10 candidatesFor reads the authored store',
        type(l1) == 'table' and l1.items[1] ~= nil and l1.items[1].name or '?', 'X Robe');
    check('LD10b the memo returns the same ladder within an epoch',
        rawequal(dispatchM.candidatesFor('CF', 'Body'), l1), true);
    utils._laddersRev = (utils._laddersRev or 0) + 1;   -- a rebuild bumps the epoch
    check('LD10c a new epoch recomputes',
        rawequal(dispatchM.candidatesFor('CF', 'Body'), l1), false);
    check('LD10d an unknown set is nil', dispatchM.candidatesFor('Nope', 'Body'), nil);

    -- FS. flattenedSet: the TOP-LEVEL (flattened) store read the manifest's
    -- pair-home harvest uses -- the set's chosen picks, never the authored
    -- rungs (field 2026-07-28: an authored-only leveling rung must FLOAT).
    dispatchM._nativeSets = {
        Dynamic = { Idle = { Ear2 = { { Name = 'Outlaws Earring', Level = 50 },
                                      { Name = 'Loquac. Earring', Level = 75 } } } },
        Idle = { Ear2 = 'Loquac. Earring', Head = { Name = 'Zenith Crown' } },
    };
    local fsIdle = dispatchM.flattenedSet('Idle');
    check('FS1 flattenedSet answers the FLATTENED entry, not Dynamic',
        type(fsIdle) == 'table' and fsIdle.Ear2, 'Loquac. Earring');
    check('FS2 an unknown set is nil', dispatchM.flattenedSet('Nope'), nil);
    dispatchM._nativeSets = nil;
    check('FS3 no store is nil', dispatchM.flattenedSet('Idle'), nil);
    dispatchM._nativeSets = savedNS;
    package.loaded['dlac\\utils'] = savedPkgU;
end)();

-- ---------------------------------------------------------------------------
-- LD11. THE WORKING-MODEL BRIDGE (ADR 0027, stage 5 -- utils.workingPick).
--       The Sets tab's preview twin (gearui's hand-mirrored bestByLevel)
--       retired into this: working entries are shaped into authored form and
--       judged by slotLadder, so the preview obeys the SAME laws -- the
--       comparator, virtual adoption (LD8's quirk included), Sub pairing --
--       with the caller's own level and mode judge (cctx.modeOk).
-- ---------------------------------------------------------------------------
(function()
    local cctx = { mjLevel = 50, isDW = false };
    local W = utils.workingPick;

    -- The comparator through the bridge; the winner is the WORKING entry itself.
    local wl = { { rec = { Name = 'Druid Robe', Level = 50 } },
                 { rec = { Name = 'Garrison Tunica', Level = 20 }, minLevel = 20, maxLevel = 51 } };
    local pick, lad = W(wl, 'Body', nil, cctx);
    check('LD11 the bridge answers with the evaluator comparator',
        pick ~= nil and pick.rec.Name or '?', 'Garrison Tunica');
    check('LD11b the winner is the working entry itself (identity)', rawequal(pick, wl[2]), true);
    check('LD11c the ladder rides along (rung 2 = the fall)', lad.items[2].name, 'Druid Robe');

    -- The caller's own mode judge (display truth), never the engine's.
    local wm = { { rec = { Name = 'Plain Body', Level = 40 } },
                 { rec = { Name = 'DT Body', Level = 10 }, mode = 'DT' } };
    local pOn  = W(wm, 'Body', nil, { mjLevel = 50, modeOk = function(m) return m == 'DT' end });
    local pOff = W(wm, 'Body', nil, { mjLevel = 50, modeOk = function() return false end });
    check('LD11d cctx.modeOk active -> the gated entry outranks', pOn ~= nil and pOn.rec.Name or '?', 'DT Body');
    check('LD11e cctx.modeOk inactive -> excluded outright', pOff ~= nil and pOff.rec.Name or '?', 'Plain Body');

    -- Virtual adoption follows the ENGINE law and maps back to the marker entry.
    local savedDM3 = utils.dispatchModule;
    utils.dispatchModule = { virtualMinLevel = function() return 3 end };
    local wv = { { rec = { Name = 'dlac:AutoObi', Level = 3, Virtual = true } },
                 { rec = { Name = 'Corsette', Level = 40 } } };
    local pv = W(wv, 'Waist', nil, cctx);
    check('LD11f a virtual takes the slot and maps to its working entry', rawequal(pv, wv[1]), true);
    utils.dispatchModule = savedDM3;

    -- Sub pairing judges against the planned Main, exactly like the flatten.
    local twoH2 = { Name = 'Heavy Great Axe', Type = 'Great Axe', OneHanded = false, Level = 1 };
    local ws = { { rec = { Name = 'Kite Shield', Type = 'Shield', Level = 1 } },
                 { rec = { Name = 'Dark Grip', Type = 'Sub', Level = 1 } } };
    local ps = W(ws, 'Sub', twoH2, cctx);
    check('LD11g Sub pairing gates the preview like the flatten', ps ~= nil and ps.rec.Name or '?', 'Dark Grip');

    -- A rec-less entry is a HOLE (skipped cleanly); ord still maps back.
    local wh = { { rec = nil }, { rec = { Name = 'Real Robe', Level = 10 } } };
    check('LD11h a hole entry skips and ord still maps back',
        rawequal((W(wh, 'Body', nil, cctx)), wh[2]), true);

    -- AutoAcc fields ride the working entry into the pool split; the marker
    -- composes over the fallback exactly as the flatten stores it.
    local wa = { { rec = { Name = 'Plain Ring', Level = 40 } },
                 { rec = { Name = 'Acc Ring', Level = 30 }, autoType = 'AutoAcc', removePrio = 2, acc = 15 } };
    local pa, laa = W(wa, 'Ring1', nil, cctx);
    check('LD11i the AutoAcc entry wins as the composed head (pool split)', rawequal(pa, wa[2]), true);
    check('LD11j ...and its ladder still composes the flatten marker',
        (utils.flattenHead(laa, 'Ring1')), 'dlac:AutoAcc:2:15:Acc Ring|Plain Ring');
end)();

-- ---------------------------------------------------------------------------
-- GC. GEARCHECK THROUGH THE LADDER DOOR (ADR 0027, stage 5). With
--     deps.candidatesFor wired, a named set audits each slot's HEAD rung --
--     what the set will actually ask for -- so list-valued slots (silently
--     skipped by the raw walk) are covered and deeper rungs are not false
--     needs. Without the door, the raw degraded walk stands as before.
-- ---------------------------------------------------------------------------
(function()
    local gcm = dofile('gear/gearcheck.lua');   -- fresh instance (the harness idiom)
    local savedGI = package.loaded['dlac\\gear\\gearimport'];
    package.loaded['dlac\\gear\\gearimport'] = {
        ownedSplit = function()
            return { avail = { [77] = 0, [88] = 1 }, total = { [77] = 1, [88] = 1 },
                     where = { [77] = { [5] = 1 } } };
        end,
        containerName = function(cid) return 'Mog Safe'; end,
    };
    local lookup = { ['Head Robe'] = { Id = 77 }, ['Deep Robe'] = { Id = 88 } };
    local base = {
        setsRoot = function() return { Dynamic = { LadSet = { Body = { 'authored entry' } } } }; end,
        lookupByName = function(nm) return lookup[nm]; end,
        model = function() return { HandleDefault = { { set = 'LadSet' } } }; end,
    };

    -- The door answers: the audit reads the HEAD rung only.
    base.candidatesFor = function(s, sl)
        if s == 'LadSet' and sl == 'Body' then
            return { items = { { name = 'Head Robe' }, { name = 'Deep Robe' } }, accs = {} };
        end
        return nil;
    end;
    gcm.configure(base);
    local warns = gcm.audit();
    check('GC1 the ladder-door audit warns on the head rung', #warns, 1);
    check('GC1b ...as stored (owned, not equippable)', warns[1] ~= nil and warns[1].kind or '?', 'stored');
    check('GC1c ...naming the head piece', warns[1] ~= nil and warns[1].item or '?', 'Head Robe');
    check('GC1d ...with the retrieve-from location', warns[1] ~= nil and warns[1].where or '?', 'Mog Safe');
    local deepNamed = false;
    for _, w in ipairs(warns) do if w.item == 'Deep Robe' then deepNamed = true; end end
    check('GC2 deeper rungs are alternatives, never false needs', deepNamed, false);

    -- Without the door: the raw degraded walk (a list-valued slot is silently
    -- skipped -- the pre-stage-5 hole, pinned here as WHY the door matters).
    base.candidatesFor = nil;
    gcm.configure(base);
    check('GC3 the degraded raw walk still skips list-valued slots', #gcm.audit(), 0);

    gcm.configure(nil);
    package.loaded['dlac\\gear\\gearimport'] = savedGI;
end)();

-- ---------------------------------------------------------------------------
-- GCJ. THE ONCE-PER-MAIN-JOB CHAT GATE (2026-08-01). chatWarn rides the
--      auto-sync cadence, which fires on job change AND ~5s after every
--      inventory settle -- and the signature dedup could not hold that back,
--      because moving a piece moves the availability counts the signature is
--      built from. Henrik, in the field: "only inform me once, and only once,
--      until I change main job." So: one automatic report per MAIN job (a sub
--      job change is not a re-arm -- the audit is main-job scoped), gated by
--      the "Warn about gear in storage" Setting, with /dl gearcheck (force)
--      always answering. The other law here is that an audit which could not
--      RUN never spends the gate: login hands us an empty model, and a gate
--      spent on that would silence the real answer for the whole job.
-- ---------------------------------------------------------------------------
(function()
    -- chatfmt is captured at LOAD time, so the stub goes in first.
    local lines = {};
    local savedCF = package.loaded['dlac\\chatfmt'];
    package.loaded['dlac\\chatfmt'] = {
        warn  = function(s) lines[#lines + 1] = tostring(s); end,
        msg   = function(s) lines[#lines + 1] = tostring(s); end,
        print = function() end,
    };
    local gcm = dofile('gear/gearcheck.lua');
    package.loaded['dlac\\chatfmt'] = savedCF;

    local savedGI = package.loaded['dlac\\gear\\gearimport'];
    package.loaded['dlac\\gear\\gearimport'] = {
        ownedSplit = function()
            return { avail = { [77] = 0 }, total = { [77] = 1 }, where = { [77] = { [5] = 1 } } };
        end,
        containerName = function() return 'Mog Safe'; end,
    };

    local job, on, modelReady = 5, true, true;
    gcm.configure({
        setsRoot = function() return { Dynamic = { WarnSet = { Body = 'Stored Robe' } } }; end,
        lookupByName = function(nm) return (nm == 'Stored Robe') and { Id = 77 } or nil; end,
        model = function()
            return modelReady and { HandleDefault = { { set = 'WarnSet' } } } or nil;
        end,
        warnEnabled = function() return on; end,
        mainJob = function() return job; end,
    });

    -- One call, and what it said (empty string = it stayed silent).
    local function say(force)
        lines = {};
        gcm.chatWarn(force);
        return table.concat(lines, '\n');
    end

    local first = say(false);
    check('GCJ1 the first automatic report on a main job speaks', first ~= '', true);
    check('GCJ1b ...and it is the retrieve advice',
        first:find('please retrieve if needed', 1, true) ~= nil, true);
    check('GCJ2 the next inventory settle stays silent', say(false), '');
    check('GCJ2b ...and the one after that too', say(false), '');

    job = 9;   -- a MAIN job change re-arms it
    check('GCJ3 a new main job speaks again', say(false) ~= '', true);
    check('GCJ3b ...once', say(false), '');

    -- /dl gearcheck is an explicit question: it always answers, same job or not.
    check('GCJ4 force answers on the same job', say(true) ~= '', true);
    check('GCJ4b ...and does not re-open the automatic gate', say(false), '');

    -- The Setting silences the automatic report only.
    job, on = 12, false;
    check('GCJ5 the Setting off silences a fresh job', say(false), '');
    check('GCJ5b ...while /dl gearcheck still answers', say(true) ~= '', true);

    -- Pre-login / mid-zone: the model is not there yet. Silent, and the gate is
    -- NOT spent -- the first real audit for this job must still get through.
    job, on, modelReady = 13, true, false;
    check('GCJ6 an audit that cannot run says nothing', say(false), '');
    modelReady = true;
    check('GCJ6b ...and never spent the gate', say(false) ~= '', true);

    -- rearm() is what /dl gearwarn on and the Settings tick call, so the answer
    -- lands on the job you are standing on instead of the next one.
    check('GCJ7 armed again after the report', say(false), '');
    gcm.rearm();
    check('GCJ7b rearm re-opens it on the SAME job', say(false) ~= '', true);

    gcm.configure(nil);
    package.loaded['dlac\\gear\\gearimport'] = savedGI;
end)();

-- ---------------------------------------------------------------------------
-- UNU. THE WARDROBE AUDIT (gear/unusedgear, 2026-08-03). Gearcheck read
--      backwards: start from the BAG and ask whether anything in dlac
--      references the piece -- across every profile and job entry.
--
--      The four rulings the sections pin (Henrik, 2026-08-03):
--        1. a set NO rule points at is its own answer, never "unused"
--        2. a lockstyle-only piece is MOVEABLE: the render gate (charutils
--           UpdateArmorStyle) needs HasItem -- which walks EVERY container --
--           so where it sits is irrelevant, but owning it is not
--        3. helper picks (MaxMP ladder, auto-staff, craft/HELM/fishing/chocobo,
--           ammo lists, rod+bait, a job helper's pin) COUNT as use
--        4. the name->value stat caches (autogear mp/rf/mv) do NOT
-- ---------------------------------------------------------------------------
(function()
    local ug = dofile('gear/unusedgear.lua');   -- fresh instance (the harness idiom)

    -- A tiny gear world: name -> id, both ways.
    local NAMES = {
        ['Kraken Club']    = 100, ['Peacock Charm'] = 101, ['Astral Ring'] = 102,
        ['Agwu\'s Cap']    = 103, ['Bronze Harness'] = 104, ['Terra\'s Staff'] = 105,
        ['Corsair Bullet'] = 106, ['Lu Shang\'s F. Rod'] = 107, ['Herbal Broth'] = 108,
        ['Chr. Roundlet']  = 109, ['Field Torque'] = 110,
    };
    local IDS = {};
    for n, i in pairs(NAMES) do IDS[i] = { Id = i, Name = n, Level = 30, Jobs = { 'WAR', 'MNK' } }; end
    local function idOf(n) local r = NAMES[n]; if r ~= nil then return r; end
        local lc = string.lower(tostring(n));
        for k, v in pairs(NAMES) do if string.lower(k) == lc then return v; end end
        return nil; end
    local function nameOf(id) return (IDS[id] ~= nil) and IDS[id].Name or ('item ' .. id); end
    local function recOf(id) return IDS[id]; end

    -- --- the entry grammar (utils.slotLadder's four shapes + lists)
    local got = {};
    local function emit(id) got[#got + 1] = id; end
    ug.setIds({
        Main  = { { gear = { Id = 100, Name = 'Kraken Club' }, mode = 'Weapons:SoloKC' } },  -- wrapper
        Neck  = { { Id = 101, Name = 'Peacock Charm' } },                                   -- record
        Ring1 = { 'Astral Ring' },                                                          -- name string
        Head  = { 'dlac:AutoStaff|Terra\'s Staff' },                                        -- composed virtual
        Waist = { 'dlac:AutoObi' },                                                         -- bare marker: names nothing
        Body  = { { gear = 'Agwu\'s Cap' } },                                               -- wrapper over a NAME
    }, idOf, emit);
    table.sort(got);
    check('UNU1 every authored entry shape resolves to its item',
          table.concat(got, ','), '100,101,102,103,105');

    -- --- which sets a trigger file points at
    local refs, inline = ug.triggerRefs({
        Default    = { { when = { status = 'Engaged' }, set = 'Tp' },
                       { when = {}, equip = { Neck = { 'Peacock Charm' } } } },
        Midcast    = { { when = { group = 'X' }, set = { 'Nuke', 'Skill' } } },
        Modes      = { DT = {} },
        Groups     = { X = { 'Fire', 'Blizzard' } },
    });
    local rn = {};
    for n in pairs(refs) do rn[#rn + 1] = n; end
    table.sort(rn);
    check('UNU2 rule set names, string AND ordered list', table.concat(rn, ','), 'Nuke,Skill,Tp');
    check('UNU2b an inline equip is carried too', #inline, 1);
    check('UNU2c Modes/Groups name no sets', refs['DT'] == nil and refs['X'] == nil, true);

    -- --- the collector: triggered set vs orphan set vs lockstyle box
    local entries = { {
        profile = 'Default', name = 'BLU',
        triggers = { Default = { { when = {}, set = 'Tp' } } },
        sets = {
            Tp    = { Main = { { Id = 100, Name = 'Kraken Club' } } },
            Spare = { Neck = { { Id = 101, Name = 'Peacock Charm' } } },   -- no rule points here
        },
        lockstyles = { slots = { [2] = { name = 'Agwu', set = { Head = 'Agwu\'s Cap' } } } },
    } };
    local col = ug.collect({ entries = entries, idOf = idOf });
    check('UNU3 a triggered set makes its pieces LIVE',  col.live[100] ~= nil, true);
    check('UNU3b an untriggered set is its own bucket',  col.orphan[101] ~= nil, true);
    check('UNU3c ...and never live',                     col.live[101], nil);
    check('UNU3d a lockstyle box is its own bucket',     col.style[103] ~= nil, true);
    check('UNU3e ...and never live',                     col.live[103], nil);
    check('UNU3f the reason names profile/job and set',  col.live[100][1], 'Default/BLU set Tp');
    check('UNU3g sets counted, triggered and not',
          tostring(col.stats.sets) .. '/' .. tostring(col.stats.usedSets) .. '/' .. tostring(col.stats.orphanSets),
          '2/1/1');

    -- --- ruling 3: the helpers are use, and they say which helper
    local col2 = ug.collect({
        entries = {},
        idOf = idOf,
        autogear = {
            staff  = { Earth = { name = 'Terra\'s Staff' } },
            mpBest = { ring1 = { { name = 'Astral Ring' } } },
            helm   = { neck = { { name = 'Field Torque' } } },
            -- ruling 4: name->value STAT CACHES, not picks
            mp = { ["chr. roundlet"] = 20 }, rf = { ["chr. roundlet"] = 1 }, mv = { ["chr. roundlet"] = 12 },
        },
        ammo    = { jobs = { COR = { ammo = { { name = 'Corsair Bullet', id = 106 } } } } },
        fish    = { rodId = 107, rod = 'Lu Shang\'s F. Rod' },
        helpers = { { label = 'BST helper', items = { 'Herbal Broth' }, sets = {} } },
        worn    = { 104 },
    });
    check('UNU4 an auto-staff pick is use',      col2.live[105] ~= nil, true);
    check('UNU4b the MaxMP ladder is use',       col2.live[102] ~= nil and col2.live[102][1], 'MaxMP ladder');
    check('UNU4c HELM gear is use',              col2.live[110] ~= nil, true);
    check('UNU4d the ammo list names its job',   col2.live[106] ~= nil and col2.live[106][1], 'ammo list (COR)');
    check('UNU4e the fishing rod is use',        col2.live[107] ~= nil, true);
    check('UNU4f a job-helper pin is use',       col2.live[108] ~= nil and col2.live[108][1], 'BST helper pin');
    check('UNU4g what you are WEARING is use',   col2.live[104] ~= nil and col2.live[104][1], 'worn right now');
    check('UNU5 the mp/rf/mv stat caches are NOT use (ruling 4)', col2.live[109], nil);

    -- --- a set named by CONFIG, not by a rule, is still live (the MaxMP pair
    --     home and a job helper's summon set -- otherwise they read as orphans)
    local col3 = ug.collect({
        entries = { { profile = 'Default', name = 'BST', triggers = {},
                      sets = { Chr_Swap = { Head = { { Id = 109, Name = 'Chr. Roundlet' } } } } } },
        idOf = idOf,
        helpers = { { label = 'BST helper', items = {}, sets = { 'Chr_Swap' } } },
    });
    check('UNU6 a set a HELPER equips is live, not an orphan', col3.live[109] ~= nil, true);
    check('UNU6b ...and the reason says who asked for it',
          (col3.live[109][1]):find('BST helper equips it', 1, true) ~= nil, true);
    local col4 = ug.collect({
        entries = { { profile = 'Default', name = 'WHM', triggers = {},
                      sets = { Idle = { Ring1 = { { Id = 102, Name = 'Astral Ring' } } } } } },
        idOf = idOf, pairSets = { 'Idle' },
    });
    check('UNU6c the MaxMP pair set is live too', col4.live[102] ~= nil, true);

    -- --- classification precedence + the wardrobe-only scope
    local bags = { [100] = { [8] = 1 }, [101] = { [10] = 1 }, [103] = { [10] = 2 }, [104] = { [8] = 1 } };
    local rows, counts = ug.classify(col, bags, nameOf, recOf);
    local byName = {};
    for _, r in ipairs(rows) do byName[r.name] = r; end
    check('UNU7 a used piece is counted, not listed', counts.used, 1);
    check('UNU7b nothing-references-it is the unused class', byName['Bronze Harness'].cls, 'unused');
    check('UNU7c an untriggered-set piece is orphan',        byName['Peacock Charm'].cls, 'orphan');
    check('UNU7d a lockstyle-only piece is style',           byName['Agwu\'s Cap'].cls, 'style');
    check('UNU7e the used piece is absent from the rows',    byName['Kraken Club'], nil);
    check('UNU7f counts add up', string.format('%d/%d/%d/%d', counts.total, counts.unused, counts.orphan, counts.style),
          '4/1/1/1');
    check('UNU7g the row carries WHERE it sits', byName['Agwu\'s Cap'].where[1].cid, 10);
    check('UNU7h ...with the copy count',        byName['Agwu\'s Cap'].where[1].n, 2);
    check('UNU7i and the record facts for judging', byName['Bronze Harness'].lv, 30);

    -- an item that is ONLY in the Mog Safe never reaches classify at all: the
    -- bag map handed in is the wardrobe slice (build() does that split).
    check('UNU7j only wardrobe ids are classified', #rows, 3);

    -- --- the why list is capped (an item can be in forty sets)
    local many = { live = {}, orphan = {}, style = {} };
    many.orphan[101] = {};
    for i = 1, 20 do many.orphan[101][i] = 'set number ' .. i; end
    local mrows = ug.classify(many, { [101] = { [8] = 1 } }, nameOf, recOf);
    check('UNU8 the reason list is capped', #mrows[1].why, ug.MAX_WHY + 1);
    check('UNU8b ...and says how many it dropped',
          mrows[1].why[#mrows[1].why], '...and 14 more');

    -- --- build() end to end, every live read on the seam
    local savedSrc, savedRead = ug._src, ug.readEntries;
    ug._src = {
        profiles = function() return nil; end,
        gearTable = function() return { NameToObject = { ['Kraken Club'] = IDS[100],
                                                         ['Peacock Charm'] = IDS[101],
                                                         ['Agwu\'s Cap'] = IDS[103],
                                                         ['Bronze Harness'] = IDS[104] } }; end,
        split = function() return { total = {}, avail = {},
            where = { [100] = { [8] = 1 }, [101] = { [10] = 1 }, [103] = { [10] = 1 },
                      [104] = { [8] = 1 }, [999] = { [1] = 1 } } }; end,   -- 999 = Mog Safe only
        containerName = function(cid) return 'Wardrobe ' .. tostring(cid); end,
        wardrobeIds = function() return { 8, 10 }; end,
        stateTable = function() return nil; end,
        wornIds = function() return {}; end,
        resourceId = function() return nil; end,
        resourceName = function() return nil; end,
        write = function() return true; end,
        now = function() return 1700000000; end,
        stamp = function() return '2026-08-03 12:00:00'; end,
        charName = function() return 'Mindie'; end,
    };
    ug.readEntries = function() return entries, nil; end;
    local rep, why = ug.build();
    check('UNU9 build() answers', rep ~= nil and why, nil);

    -- The one wrong answer this command must never give: "everything you own is
    -- in use" because the bag list could not be read. It refuses instead.
    local keepW = ug._src.wardrobeIds;
    ug._src.wardrobeIds = function() return {}; end;
    local nope, nwhy = ug.build();
    check('UNU9a a missing wardrobe list REFUSES, never reports all-clean', nope, nil);
    check('UNU9a2 ...and says why', (tostring(nwhy)):find('wardrobe list', 1, true) ~= nil, true);
    ug._src.wardrobeIds = keepW;
    rep = ug.build();
    check('UNU9b the Mog Safe item is not in the report', (function()
        for _, r in ipairs(rep.rows) do if r.id == 999 then return true; end end
        return false;
    end)(), false);
    check('UNU9c the wardrobe load is counted', rep.wardrobes[1].items, 2);
    check('UNU9d ...and how much of it is flagged', rep.wardrobes[1].flagged, 1);
    check('UNU9e the report says which character + when', rep.char .. '|' .. rep.stamp,
          'Mindie|2026-08-03 12:00:00');

    -- --- the saved file round-trips (the window reads it back next session)
    local text = ug.serialize(rep);
    local chunk = (loadstring or load)(text);
    check('UNU10 the saved report parses', type(chunk), 'function');
    local rok, back = pcall(chunk);
    check('UNU10b ...and reloads',        rok and type(back), 'table');
    check('UNU10c with its rows intact',  #back.rows, #rep.rows);
    check('UNU10d and their reasons',     back.rows[1].why ~= nil, true);

    ug._src, ug.readEntries = savedSrc, savedRead;
end)();

-- ---------------------------------------------------------------------------
-- AKF. THE FALL (ADR 0027, stage 2 -- M.reserveResolve + the FELL branch in
--      equipResolved). The deferred half of the v135 ruling: an ineligible
--      piece falls down its source ladder, each rung re-judged; a reserved
--      slot never falls (the asymmetry law). Field case: Henrik's Mindie BRD
--      -- Idle Body = Royal Cloak > Scorpion Harness +1 under Movement Head.
-- ---------------------------------------------------------------------------
(function()
    local HEAD, LEGS = 0x0010, 0x0080;
    local function look(masks) return function(n) return masks[n] or 0; end end
    local function ladders(map)
        return function(src, slot)
            local bySlot = map[src];
            local names = bySlot and bySlot[slot] or nil;
            if names == nil then return nil; end
            local items = {};
            for _, n in ipairs(names) do items[#items + 1] = { name = n }; end
            return { items = items };
        end
    end

    -- AKF1: the floor carries its source set through.
    local fl = dispatchM.reserveFloor({ { prio = 20, set = { Body = 'Royal Cloak' }, src = 'IdleSet' } });
    check('AKF1 the floor remembers whose set won the slot', fl.Body.src, 'IdleSet');

    -- AKF2: the Mindie case -- the cloak is beaten on Head and FALLS to the
    -- harness; nothing ends ineligible or suppressed.
    local mindie = {
        { prio = 20, set = { Body = 'Royal Cloak' },   src = 'IdleSet' },
        { prio = 25, set = { Head = 'Genbu Kabuto' },  src = 'MoveSet' },
    };
    local cloakLook = look({ ['Royal Cloak'] = HEAD });
    local mindieLad = ladders({ IdleSet = { Body = { 'Royal Cloak', 'Scorpion Harness +1' } } });
    local sup, inel, rep = dispatchM.reserveResolve(mindie, cloakLook, mindieLad);
    check('AKF2 the fall resolves the contest', inel, nil);
    check('AKF2b nothing is suppressed', sup, nil);
    check('AKF2c the slot fell to the next rung', rep.Body.to, 'Scorpion Harness +1');
    check('AKF2d the trace knows what fell', rep.Body.from, 'Royal Cloak');
    check('AKF2e ...and who beat it', rep.Body.by, 'Head');

    -- AKF3: a replacement that reserves DOMINATED slots suppresses them like
    -- any dominant reserver (the re-run verdict is the same verdict).
    local chain = {
        { prio = 10, set = { Legs = 'Amir Dirs' },     src = 'LowSet' },
        { prio = 20, set = { Body = 'Royal Cloak' },   src = 'IdleSet' },
        { prio = 25, set = { Head = 'Genbu Kabuto' },  src = 'MoveSet' },
    };
    local suitLook = look({ ['Royal Cloak'] = HEAD, ['Party Suit'] = LEGS });
    sup, inel, rep = dispatchM.reserveResolve(chain, suitLook,
        ladders({ IdleSet = { Body = { 'Royal Cloak', 'Party Suit' } } }));
    check('AKF3 the replacement lands', rep.Body.to, 'Party Suit');
    check('AKF3b and its own reservation suppresses the dominated slot', sup.Legs, 'Party Suit');
    check('AKF3c nothing ends ineligible', inel, nil);

    -- AKF4: rung 2 fails the same test rung 1 did -> rung 3 wins (two rounds).
    sup, inel, rep = dispatchM.reserveResolve(mindie,
        look({ ['Royal Cloak'] = HEAD, ['Hat Eater'] = HEAD }),
        ladders({ IdleSet = { Body = { 'Royal Cloak', 'Hat Eater', 'Scorpion Harness +1' } } }));
    check('AKF4 a refused rung falls again', rep.Body.to, 'Scorpion Harness +1');
    check('AKF4b and the trace still names the ORIGINAL piece', rep.Body.from, 'Royal Cloak');
    check('AKF4c clean end state', inel, nil);

    -- AKF5: a dry ladder keeps v135's behavior -- ineligible, no replacement.
    sup, inel, rep = dispatchM.reserveResolve(mindie, cloakLook,
        ladders({ IdleSet = { Body = { 'Royal Cloak' } } }));
    check('AKF5 a dry ladder stays ineligible', inel.Body, 'Head');
    check('AKF5b and nothing reads as replaced', rep, nil);

    -- AKF6: an inline equip has no ladder (src nil) -- v135 behavior exactly.
    sup, inel, rep = dispatchM.reserveResolve({
        { prio = 20, set = { Body = 'Royal Cloak' } },
        { prio = 25, set = { Head = 'Genbu Kabuto' }, src = 'MoveSet' },
    }, cloakLook, mindieLad);
    check('AKF6 an inline equip cannot fall', inel.Body, 'Head');
    check('AKF6b no replacement invented for it', rep, nil);

    -- AKF7: the cap -- a ladder of nothing but reservers exhausts three
    -- re-runs and reads INELIGIBLE (visible, never silent), not replaced.
    sup, inel, rep = dispatchM.reserveResolve(mindie,
        look({ ['Royal Cloak'] = HEAD, ['R2'] = HEAD, ['R3'] = HEAD, ['R4'] = HEAD, ['R5'] = HEAD }),
        ladders({ IdleSet = { Body = { 'Royal Cloak', 'R2', 'R3', 'R4', 'R5' } } }));
    check('AKF7 an all-reserver ladder ends ineligible', inel.Body, 'Head');
    check('AKF7b with no replacement record', rep, nil);

    -- AKF8: the ASYMMETRY LAW -- a reserved slot never falls, ladder or not.
    sup, inel, rep = dispatchM.reserveResolve({
        { prio = 20, set = { Head = 'Silver Hairpin' }, src = 'IdleSet' },
        { prio = 25, set = { Body = 'Royal Cloak' },    src = 'MoveSet' },
    }, cloakLook, ladders({ IdleSet = { Head = { 'Silver Hairpin', 'Leather Bandana' } } }));
    check('AKF8 the dominant reserver claims the slot empty', sup.Head, 'Royal Cloak');
    check('AKF8b the reserved slot is NOT offered a rung', rep, nil);
    check('AKF8c and nothing is ineligible', inel, nil);

    -- AKF9/10: the FELL branch in the real equipResolved.
    dispatchM.setLock('all', false);
    local _, ft = dispatchM._equipResolved({ Body = 'Royal Cloak' },
        { reserveReplace = { Body = { from = 'Royal Cloak', to = 'Scorpion Harness +1', by = 'Head' } } });
    check('AKF9 the refused writer equips the rung that passed', ft.Body, 'Scorpion Harness +1');
    local fn = dispatchM._equipResolved({ Body = 'Royal Cloak' },
        { reserveReplace = { Body = { from = 'Royal Cloak', to = 'Scorpion Harness +1', by = 'Head' } } });
    check('AKF9b and the note names the fall',
        fn:find('Body=Royal Cloak fell -> Scorpion Harness +1', 1, true) ~= nil, true);
    local _, bt = dispatchM._equipResolved({ Body = 'Bronze Harness' },
        { reserveReplace = { Body = { from = 'Royal Cloak', to = 'Scorpion Harness +1', by = 'Head' } } });
    check('AKF10 a different writer in the slot flows through untouched', bt.Body, 'Bronze Harness');
end)();

-- ---------------------------------------------------------------------------
-- UA. AVAILABILITY, THE ARBITER'S SECOND REFUSAL REASON (Henrik, 2026-08-01:
--     "It is FINE if claimants file ladders where some of the pieces are
--     ineligible. Therefore it is more important to have this intelligence in
--     arbiter"). Field case: a Lv75 BRD parks a Minstrel's Coat in the Mog Safe
--     and lowers his level until the Coat is the set's best Body -- it won the
--     ladder and then died silently in planSet's bag scan, with the rung below
--     it never asked. Same fall machinery, second reason.
-- ---------------------------------------------------------------------------
(function()
    local ARB = require('dlac\\gear\\arbiter');
    local HEAD = 0x0010;
    local function look(masks) return function(n) return masks[n] or 0; end end
    local function ladders(map)
        return function(src, slot)
            local names = map[src] and map[src][slot] or nil;
            if names == nil then return nil; end
            local items = {};
            for _, n in ipairs(names) do items[#items + 1] = { name = n }; end
            return { items = items };
        end
    end
    -- `stored` names the pieces sitting in a bag you cannot equip out of.
    local function bag(stored, unknown)
        return function(n)
            if unknown ~= nil and unknown[n] then return nil; end
            return not stored[n];
        end
    end
    local NOMASK = look({});
    local idle   = { { prio = 20, set = { Body = 'Minstrel\'s Coat' }, src = 'IdleSet' } };
    local lad    = ladders({ IdleSet = { Body = { 'Minstrel\'s Coat', 'Gold Harness' } } });

    -- UA1: availVerdict refuses ONLY on an explicit false.
    local fl = dispatchM.reserveFloor(idle);
    check('UA1 a stored piece is refused',
        ARB.availVerdict(fl, bag({ ['Minstrel\'s Coat'] = true })).Body, 'Minstrel\'s Coat');
    check('UA1b a held piece is not', ARB.availVerdict(fl, bag({})), nil);
    check('UA1c an UNKNOWN answer never refuses -- the char-select/zoning leg',
        ARB.availVerdict(fl, bag({}, { ['Minstrel\'s Coat'] = true })), nil);
    check('UA1d no read at all never refuses', ARB.availVerdict(fl, nil), nil);

    -- UA2: THE FIELD CASE -- the stored Coat falls to the rung he can wear.
    local sup, inel, rep, fall = dispatchM.reserveResolve(idle, NOMASK, lad,
        bag({ ['Minstrel\'s Coat'] = true }));
    check('UA2 the stored pick falls to the next rung', rep.Body.to, 'Gold Harness');
    check('UA2b the trace names the piece he authored', rep.Body.from, 'Minstrel\'s Coat');
    check('UA2c and says WHY it fell', rep.Body.why, 'unavail');
    check('UA2d no slot beat it -- nothing did', rep.Body.by, nil);
    check('UA2e nothing is ineligible', inel, nil);
    check('UA2f nothing is suppressed', sup, nil);
    check('UA2g the slot is not dead', fall.dead, nil);

    -- UA3: the Monitor's third depth -- EVERY refused rung, with its reason.
    check('UA3 the refused rung is recorded', fall.refused.Body[1].name, 'Minstrel\'s Coat');
    check('UA3b with its reason', fall.refused.Body[1].why, 'unavail');

    -- UA4: the whole ladder is stored -> nothing to fall to. No replacement,
    -- the slot reads dead, and NOTHING is killed: planSet cannot locate the
    -- name either, so the slot keeps what is worn (Henrik's ruling 3).
    sup, inel, rep, fall = dispatchM.reserveResolve(idle, NOMASK, lad,
        bag({ ['Minstrel\'s Coat'] = true, ['Gold Harness'] = true }));
    check('UA4 a fully stored ladder invents no replacement', rep, nil);
    check('UA4b the slot reads dead', fall.dead.Body, 'Minstrel\'s Coat');
    check('UA4c and is NOT ineligible (nothing reserved anything)', inel, nil);
    check('UA4d both refused rungs are on the record', #fall.refused.Body, 2);

    -- UA5: an unavailable RESERVER suppresses nothing. A Coat rotting in the
    -- Mog Safe is not on your body, so it must not hold Head empty from a slot
    -- it can never occupy -- the same law reserveVerdict states for a refused
    -- piece, applied to the other reason.
    local pair = {
        { prio = 10, set = { Head = 'Silver Hairpin' }, src = 'LowSet' },
        { prio = 20, set = { Body = 'Royal Cloak' },    src = 'IdleSet' },
    };
    local cloak = look({ ['Royal Cloak'] = HEAD });
    sup, inel, rep, fall = dispatchM.reserveResolve(pair, cloak,
        ladders({ IdleSet = { Body = { 'Royal Cloak' } } }), bag({ ['Royal Cloak'] = true }));
    check('UA5 a stored reserver holds nothing empty', sup, nil);
    check('UA5b and the hairpin keeps its slot', rep, nil);
    check('UA5c while the reserver itself reads dead', fall.dead.Body, 'Royal Cloak');
    -- ...and the control: held, it suppresses exactly as it always did.
    sup = dispatchM.reserveResolve(pair, cloak,
        ladders({ IdleSet = { Body = { 'Royal Cloak' } } }), bag({}));
    check('UA5d the SAME reserver in your bags still claims Head empty', sup.Head, 'Royal Cloak');

    -- UA6: both reasons at once -- 'unavail' wins the label, because "it
    -- reserves a slot owned above" is a misleading thing to print about a piece
    -- sitting in the Mog Safe.
    sup, inel, rep, fall = dispatchM.reserveResolve({
        { prio = 20, set = { Body = 'Royal Cloak' },  src = 'IdleSet' },
        { prio = 25, set = { Head = 'Genbu Kabuto' }, src = 'MoveSet' },
    }, cloak, ladders({ IdleSet = { Body = { 'Royal Cloak', 'Gold Harness' } } }),
       bag({ ['Royal Cloak'] = true }));
    check('UA6 it still falls', rep.Body.to, 'Gold Harness');
    check('UA6b and the harder fact is the one reported', rep.Body.why, 'unavail');

    -- UA7: OMITTING the read is byte-identical to life before availability --
    -- the guarantee every direct caller (immediate equips, headless suites)
    -- rides on.
    local s1, i1, r1, f1 = dispatchM.reserveResolve(idle, NOMASK, lad);
    check('UA7 no read -> nothing refused', i1, nil);
    check('UA7b no fall record either', f1, nil);
    check('UA7c and no replacement', r1, nil);
    check('UA7d nothing suppressed', s1, nil);

    -- UA8: the FELL branch in the real equipResolved says which reason it was.
    dispatchM.setLock('all', false);
    local fn = dispatchM._equipResolved({ Body = 'Minstrel\'s Coat' },
        { reserveReplace = { Body = { from = 'Minstrel\'s Coat', to = 'Gold Harness',
                                      why = 'unavail' } } });
    check('UA8 the note names the availability fall',
        fn:find('not in an equippable bag', 1, true) ~= nil, true);
    check('UA8b and never claims a reservation that did not happen',
        fn:find('reserves', 1, true), nil);
    local rn = dispatchM._equipResolved({ Body = 'Royal Cloak' },
        { reserveReplace = { Body = { from = 'Royal Cloak', to = 'Gold Harness', by = 'Head' } } });
    check('UA8c a reserve fall keeps its own wording',
        rn:find('reserves Head -- owned above', 1, true) ~= nil, true);

    -- UA9: availPick -- the SINGLE-LADDER form, for the Sets tab preview
    -- (Henrik, 2026-08-01: the panel highlighted a Coat in his Mog Locker as
    -- the chosen piece while the engine wore the Royal Cloak below it). Same
    -- rule, same three-valued read, one copy of it.
    local rungs = { { name = 'Minstrel\'s Coat' }, { name = 'Royal Cloak' }, { name = 'Gold Harness' } };
    local i, ref = ARB.availPick(rungs, bag({}));
    check('UA9 nothing stored -> the authored pick stands', i, 1);
    check('UA9b and nothing is refused', ref, nil);
    i, ref = ARB.availPick(rungs, bag({ ['Minstrel\'s Coat'] = true }));
    check('UA9c a stored head falls to the rung below it', i, 2);
    check('UA9d the refusal is recorded', ref[1].name, 'Minstrel\'s Coat');
    check('UA9e with its reason', ref[1].why, 'unavail');
    i, ref = ARB.availPick(rungs, bag({ ['Minstrel\'s Coat'] = true, ['Royal Cloak'] = true }));
    check('UA9f it keeps walking down', i, 3);
    check('UA9g refusing each rung on the way', #ref, 2);
    i, ref = ARB.availPick(rungs, bag({ ['Minstrel\'s Coat'] = true, ['Royal Cloak'] = true,
                                        ['Gold Harness'] = true }));
    check('UA9h a fully stored ladder picks NOTHING', i, nil);
    check('UA9i and says so for every rung', #ref, 3);
    -- The fail-open legs, which matter more here than in the engine: this runs
    -- on the render path, so a not-ready read must never blank the panel.
    check('UA9j no read at all -> the authored pick', (ARB.availPick(rungs, nil)), 1);
    check('UA9k an UNKNOWN answer never refuses',
        (ARB.availPick(rungs, bag({}, { ['Minstrel\'s Coat'] = true }))), 1);
    check('UA9l a thrown read never refuses',
        (ARB.availPick(rungs, function() error('boom'); end)), 1);
    -- Shape tolerance: plain strings are a ladder too, and garbage is not a crash.
    check('UA9m plain-string rungs work',
        (ARB.availPick({ 'Minstrel\'s Coat', 'Royal Cloak' }, bag({ ['Minstrel\'s Coat'] = true }))), 2);
    check('UA9n a non-table ladder answers nothing', (ARB.availPick(nil, bag({}))), nil);
    check('UA9o an empty ladder answers nothing', (ARB.availPick({}, bag({}))), nil);
end)();

-- ---------------------------------------------------------------------------
-- ARM. THE ARBITER MODULE (ADR 0027, stage 3 -- gear/arbiter.lua). The pure
--      decision core, extracted: the slot + rank vocabulary, the reservation
--      family, resolve/explain, and arbitrate() (the apply order M.dispatch
--      executes). These pin the extraction's two promises: the module is PURE
--      (loads with no stubs at all), and every old dispatch seam is the SAME
--      function (delegation, not a twin).
-- ---------------------------------------------------------------------------
(function()
    -- Purity: a bare dofile in a scratch environment -- no gData, no ashita,
    -- no AshitaCore -- must load and answer. (The suite's own stubs exist,
    -- but the module must not NEED them: no engine reads inside the decider.)
    local arb = dofile('gear/arbiter.lua');
    check('ARM1 the module loads', type(arb), 'table');
    check('ARM1b arbitrate exists', type(arb.arbitrate), 'function');

    -- Delegation identity: dispatch's old doors ARE the module's functions --
    -- rawequal, so a drifting twin is structurally impossible. (dispatchM was
    -- loaded with the seeded instance, not this fresh dofile -- compare
    -- against the seed.)
    local seeded = package.loaded['dlac\\gear\\arbiter'];
    check('ARM2 the seeded instance backs dispatch', type(seeded), 'table');
    check('ARM2b reserveFloor is the same function', rawequal(dispatchM.reserveFloor, seeded.reserveFloor), true);
    check('ARM2c reserveVerdict too', rawequal(dispatchM.reserveVerdict, seeded.reserveVerdict), true);
    check('ARM2d reserveResolve too', rawequal(dispatchM.reserveResolve, seeded.reserveResolve), true);
    check('ARM2e arbResolve too', rawequal(dispatchM.arbResolve, seeded.arbResolve), true);
    check('ARM2f arbWhyLines too', rawequal(dispatchM.arbWhyLines, seeded.arbWhyLines), true);
    check('ARM2g arbOrder too', rawequal(dispatchM.arbOrder, seeded.arbOrder), true);
    check('ARM2h the default order is the same table', rawequal(dispatchM._arbDefaultOrder, seeded.ARB_ORDER_DEFAULT), true);
    check('ARM2i LOCK_HELD keeps its identity', rawequal(dispatchM.LOCK_HELD, seeded.LOCK_HELD), true);
    check('ARM2j the LAC slot lists ride along',
        rawequal(dispatchM._lacSlotsCanon, seeded.LAC_SLOTS_CANON), true);

    -- arbitrate: the apply order is the reverse rank walk over ACTIVE claims
    -- -- exactly the inline loop it replaced.
    local plan = arb.arbitrate({ order = { 'A', 'B', 'C', 'D' },
                                 claims = { A = {}, C = {} } });
    check('ARM3 the apply order is reverse rank, active rows only',
        table.concat(plan.applies, '>'), 'C>A');
    check('ARM3b no session -> an empty plan', #arb.arbitrate(nil).applies, 0);
end)();

-- ---------------------------------------------------------------------------
-- ARK. DOMINANCE ACROSS RANK (ADR 0027 item 2 + stage 4, first slice). The
--      verdict's entries now carry `row` (the Arbiter rank index -- smaller
--      is stronger): across rows RANK wins outright, within a row trigger
--      priority decides, ties favor the reserver, ord is excluded, and WORN
--      pieces are not claims (they simply are not entries). Henrik's craft
--      bench is the acceptance: the floor's Royal Cloak vs the Craft claim's
--      Midras's Helm +1.
-- ---------------------------------------------------------------------------
(function()
    local HEAD = 0x0010;
    local function look(masks) return function(n) return masks[n] or 0; end end
    local cloakLook = look({ ['Royal Cloak'] = HEAD });
    local function ladders(map)
        return function(src, slot)
            local names = map[src] and map[src][slot] or nil;
            if names == nil then return nil; end
            local items = {};
            for _, n in ipairs(names) do items[#items + 1] = { name = n }; end
            return { items = items };
        end
    end
    local idleLad = ladders({ IdleSet = { Body = { 'Royal Cloak', 'Scorpion Harness +1' } } });

    -- ARK1: THE CRAFT BENCH. Floor cloak (Triggers row 11, prio 20) reserves
    -- Head; the Craft claim (row 7) owns Head. Rank beats priority outright:
    -- the cloak is ineligible and FALLS down Idle's ladder; the helm stands.
    local sup, inel, rep = dispatchM.reserveResolve({
        { prio = 20, row = 11, set = { Body = 'Royal Cloak' }, src = 'IdleSet' },
        { prio = 0,  row = 7,  set = { Head = 'Midras Helm +1' } },
    }, cloakLook, idleLad);
    check('ARK1 a claim-row slot beats a floor reserver outright', inel, nil);
    check('ARK1b the cloak fell down its ladder', rep.Body.to, 'Scorpion Harness +1');
    check('ARK1c the trace names the contested slot', rep.Body.by, 'Head');
    check('ARK1d nothing is suppressed', sup, nil);

    -- ARK2: within one row, priority still decides -- the v135/AKF behavior,
    -- byte-for-byte (rows equal cancel out of the compare).
    sup, inel, rep = dispatchM.reserveResolve({
        { prio = 20, row = 11, set = { Body = 'Royal Cloak' }, src = 'IdleSet' },
        { prio = 25, row = 11, set = { Head = 'Genbu Kabuto' } },
    }, cloakLook, idleLad);
    check('ARK2 same row -> priority decides, the fall lands', rep.Body.to, 'Scorpion Harness +1');
    sup, inel, rep = dispatchM.reserveResolve({
        { prio = 25, row = 11, set = { Body = 'Royal Cloak' }, src = 'IdleSet' },
        { prio = 20, row = 11, set = { Head = 'Silver Hairpin' } },
    }, cloakLook, idleLad);
    check('ARK2b same row, reserver stronger -> it claims the slot empty', sup.Head, 'Royal Cloak');
    check('ARK2c and nothing falls', rep, nil);

    -- ARK3: an exact strength tie favors the reserver (ratified: ord is not
    -- in the dominance compare, so a file reorder can never flip this).
    sup, inel, rep = dispatchM.reserveResolve({
        { prio = 20, row = 11, set = { Body = 'Royal Cloak' }, src = 'IdleSet' },
        { prio = 20, row = 11, set = { Head = 'Silver Hairpin' } },
    }, cloakLook, idleLad);
    check('ARK3 a strength tie keeps the reserver dominant', sup.Head, 'Royal Cloak');

    -- ARK4: a CLAIM-row reserver dominant over a floor slot suppresses it --
    -- the general rule pins' bespoke hold has always special-cased.
    sup, inel, rep = dispatchM.reserveResolve({
        { prio = 20, row = 11, set = { Head = 'Silver Hairpin' }, src = 'IdleSet' },
        { prio = 0,  row = 3,  set = { Body = 'Royal Cloak' } },
    }, cloakLook, ladders({ IdleSet = { Head = { 'Silver Hairpin' } } }));
    check('ARK4 a dominant claim reserver claims the floor slot empty', sup.Head, 'Royal Cloak');
    check('ARK4b the floor piece does not read as ineligible', inel, nil);

    -- ARK5: a claim reserver BEATEN by a higher row is ineligible, and with
    -- no ladder (claim pieces carry none in this slice) its slot is killed --
    -- v135's law at claim altitude.
    sup, inel, rep = dispatchM.reserveResolve({
        { prio = 0, row = 8, set = { Body = 'Royal Cloak' } },
        { prio = 0, row = 3, set = { Head = 'Pinned Crown' } },
    }, cloakLook, idleLad);
    check('ARK5 a beaten claim reserver is ineligible', inel.Body, 'Head');
    check('ARK5b and cannot fall without a ladder', rep, nil);

    -- ARK6: the merged winner is the strongest WRITER -- a claim overwriting
    -- the reserver's own slot moots the reservation entirely (apply order:
    -- claims appended after the floor, strongest last).
    sup, inel, rep = dispatchM.reserveResolve({
        { prio = 20, row = 11, set = { Body = 'Royal Cloak' }, src = 'IdleSet' },
        { prio = 0,  row = 7,  set = { Body = 'Weaver Apron' } },
    }, cloakLook, idleLad);
    check('ARK6 a claim overwriting the reserver moots the reservation',
        (sup == nil and inel == nil and rep == nil), true);

    -- ARK7: the GLOBAL flag retires the worn arm for dispatch passes. The
    -- same table that the single-set fallback WOULD prune (AK: the Tunic
    -- takes Head within one plan) passes through untouched when the dispatch
    -- verdict is the one authority and its maps are empty...
    dispatchM.setLock('all', false);
    local _, gt = dispatchM._equipResolved({ Body = 'Ryl.Ftm. Tunic', Head = 'Silver Hairpin' },
        { reserveGlobal = true });
    check('ARK7 with the global verdict, the per-pass fallback is silent', gt.Head, 'Silver Hairpin');
    -- ...while a DIRECT caller (no flag) keeps the pre-v135 judgement whole.
    local _, dt = dispatchM._equipResolved({ Body = 'Ryl.Ftm. Tunic', Head = 'Silver Hairpin' }, {});
    check('ARK7b a direct caller still gets the single-set judgement', dt.Head, nil);

    -- ARK8: SENTINEL DEFENSE ROWS (stage 4, slice 2). A '(locked)'
    -- placeholder at the Locks row defends its slot: the floor reserver is
    -- beaten by rank and FALLS -- a reserver can no longer bulldoze a locked
    -- slot. The placeholder itself never reserves (mask 0 -> inert).
    sup, inel, rep = dispatchM.reserveResolve({
        { prio = 20, row = 11, set = { Body = 'Royal Cloak' }, src = 'IdleSet' },
        { prio = 0,  row = 4,  set = { Head = '(locked)' } },
    }, cloakLook, idleLad);
    check('ARK8 a locked slot defends against a reserver', rep.Body.to, 'Scorpion Harness +1');
    check('ARK8b the placeholder reserves nothing', sup, nil);

    -- ARK9: punch-through preserved -- a claim ABOVE Locks overwrites the
    -- placeholder in the merge, and the contest is judged against ITS row.
    -- (Pins row 3 over Locks row 4: the reserver still loses, but to Pins.)
    sup, inel, rep = dispatchM.reserveResolve({
        { prio = 20, row = 11, set = { Body = 'Royal Cloak' }, src = 'IdleSet' },
        { prio = 0,  row = 4,  set = { Head = '(locked)' } },
        { prio = 0,  row = 3,  set = { Head = 'Pinned Crown' } },
    }, cloakLook, idleLad);
    check('ARK9 a punch-through claim takes over the defense', rep.Body.by, 'Head');
    check('ARK9b and the fall still lands', rep.Body.to, 'Scorpion Harness +1');

    -- ARK10: the ceiling defends the same way at row 1 -- free-equip slots
    -- cannot be emptied by a reserver landing next door.
    sup, inel, rep = dispatchM.reserveResolve({
        { prio = 20, row = 11, set = { Body = 'Royal Cloak' } },
        { prio = 0,  row = 1,  set = { Head = '(free equip)' } },
    }, cloakLook, idleLad);
    check('ARK10 a free-equip slot defends against a reserver', inel.Body, 'Head');
    check('ARK10b with no ladder the reserver dies v135-style', rep, nil);

    -- ARK11: the EMPTY-LOCK WAIVER (Henrik's field refinement, 2026-07-27):
    -- a lock on an empty slot does not defend -- freezing "empty" is exactly
    -- what a reservation preserves. The waiver lives at the BUILD site (the
    -- worn read is engine state, unreachable headless), so it is pinned as
    -- source, the NK23 idiom: the '(locked)' placeholder must be gated on a
    -- worn read, and the ceiling's placeholder must NOT be (free equip
    -- defends the FUTURE hand-equip, empty or not).
    local dsrc = (function() local f = io.open('dispatch.lua', 'r'); local d = f:read('*a'); f:close(); return d; end)();
    check('ARK11 the lock entry is the WORN piece, gated on the worn read',
        dsrc:find("local wn = wornItemName(canon);", 1, true) ~= nil
        and dsrc:find("held[canon] = wn;", 1, true) ~= nil, true);
    check('ARK11b the ceiling defense is not',
        dsrc:find("free[CANON_OF[ls] or ls] = '(free equip)'", 1, true) ~= nil, true);

    -- ARK12: A LOCK-VETOED CLAIM IS NO CLAIM AT ALL (Henrik's locked-empty-
    -- Head field case): floor entries and respect-locks claim rows must strip
    -- locked slots before the verdict, so a claim the lock will veto cannot
    -- evict a reserver on its way to not landing. Build-site law -> source
    -- pins (the worn/lock reads are engine state, unreachable headless), plus
    -- the pure consequence: with the dead claim absent, the reserver is
    -- dominant and holds its ground.
    check('ARK12 floor entries strip locked slots',
        dsrc:find('set = minusLocked(st), src = sn', 1, true) ~= nil, true);
    check('ARK12b respect-locks claim rows strip too',
        dsrc:find('if layerRespectsLocks(cn) then ctbl = minusLocked(ctbl); end', 1, true) ~= nil, true);
    sup, inel, rep = dispatchM.reserveResolve({
        { prio = 20, row = 11, set = { Body = 'Royal Cloak' }, src = 'IdleSet' },
        -- (the Movement Head claim is ABSENT -- stripped at the build site)
    }, cloakLook, idleLad);
    check('ARK12c with the dead claim gone, the reserver is dominant', inel, nil);
    check('ARK12d nothing contests, so nothing is even suppressed (the slot is not in the floor)', sup, nil);
    check('ARK12e and nothing falls -- the reserver is simply undisturbed', rep, nil);

    -- ARK13: A LOCK-FROZEN RESERVER STILL RESERVES (Henrik's locked-cloak
    -- case): locking Body with the Royal Cloak worn enters the CLOAK at the
    -- Locks row -- so Idle's Head piece stays suppressed instead of landing
    -- and having the server displace the very piece the lock froze.
    sup, inel, rep = dispatchM.reserveResolve({
        { prio = 20, row = 11, set = { Head = 'Choral Roundlet +1' }, src = 'IdleSet' },
        { prio = 0,  row = 4,  set = { Body = 'Royal Cloak' } },
    }, cloakLook, ladders({ IdleSet = { Head = { 'Choral Roundlet +1' } } }));
    check('ARK13 the frozen cloak suppresses the floor Head claim', sup.Head, 'Royal Cloak');
    check('ARK13b nothing reads ineligible', inel, nil);
    check('ARK13c and nothing falls', rep, nil);

    -- ARK14: CLAIM-SIDE LADDERS (stage 4, last slice -- future-proofing: no
    -- hobby/craft item carries an RSlot today, but the day one does, a beaten
    -- claim piece falls down its own resolver chain). The rows carry rladder;
    -- the '\031'-src route is pinned as source; a ladder-less state answers
    -- nil gracefully.
    local byR = {};
    for _, row in ipairs(dispatchM._claimants) do byR[row.name] = row; end
    check('ARK14 Craft carries a claim-side ladder', type(byR['Craft'].rladder), 'function');
    check('ARK14b Fishing and Chocobo too',
        type(byR['Fishing'].rladder) == 'function' and type(byR['Chocobo'].rladder) == 'function', true);
    check('ARK14c an off craft state has no ladder', byR['Craft'].rladder('head', { enabled = false }), nil);
    check('ARK14d a headless chain answers nil, never throws',
        (function() local ok, v = pcall(byR['Fishing'].rladder, 'body', nil, {}); return ok and v == nil; end)(), true);
    check('ARK14e the claim src route is the control-char prefix (source pin)',
        dsrc:find("('\\031' .. cn)", 1, true) ~= nil, true);

    -- OS1: ONE PLAN, ONE SEND (stage 3's last slice). A full dispatch -- the
    -- NK26 recipe with naked armed -- must reach the equip door EXACTLY once,
    -- with the same 16-remove map the N sends used to accumulate.
    local savedPlayerOS, savedStateOS = TEST_PLAYER, rawget(_G, 'gState');
    TEST_PLAYER = { MainJob = 'WHM', MainJobLevel = 75, SubJob = 'BLM', SubJobLevel = 37,
                    MainJobSync = 75, SubJobSync = 37, Status = 'Idle', IsMoving = false };
    _G.gState = { CurrentCall = 'N/A', Disabled = {} };
    local savedEngOS = package.loaded['dlac\\feature\\equipengine'];
    local sends, wroteOS = 0, {};
    package.loaded['dlac\\feature\\equipengine'] = {
        nativeOn = function() return true; end,
        equipSet = function(t) sends = sends + 1; for k, v in pairs(t or {}) do wroteOS[k] = v; end end,
        state = { tripped = false },
    };
    dispatchM.nakedArmed = true;
    local okOS = pcall(dispatchM.dispatch, 'Default');
    check('OS1 the dispatch does not throw', okOS, true);
    check('OS1b the equip door is reached EXACTLY once', sends, 1);
    local nOS = 0;
    for _, v in pairs(wroteOS) do nOS = nOS + 1; if v ~= 'remove' then nOS = -99; end end
    check('OS1c and carries the whole 16-remove plan', nOS, 16);
    dispatchM.nakedArmed = false;
    package.loaded['dlac\\feature\\equipengine'] = savedEngOS;
    TEST_PLAYER = savedPlayerOS;
    _G.gState = savedStateOS;

    -- WY1: the contest stash (/dl why <slot>, ADR 0027 item 4). NK26's real
    -- dispatch above ran the stash path; its Default trace must carry the
    -- structured contest the drill-down renders -- the same object that
    -- decided, never a re-derivation.
    local wtr = dispatchM.getTrace()['Default'];
    check('WY1 the trace stashes the contest', wtr ~= nil and type(wtr.contest) == 'table', true);
    check('WY1b it carries the rank-ordered explain',
        wtr ~= nil and type(wtr.contest) == 'table' and type(wtr.contest.explain) == 'table', true);
    check('WY1c and the order it decided with',
        wtr ~= nil and type(wtr.contest) == 'table' and type(wtr.contest.order) == 'table', true);

    -- DR: THE DECISION RING (v152, the Arbiter Monitor's record). The one law:
    -- append on OUTCOME change only (Henrik: 'only push changes'). OS1's naked
    -- dispatch above already ran the append path -- the ring's newest record
    -- must be that 16-remove plan, whichever dispatch first recorded it.
    local ring = dispatchM.getDecisions();
    local newest = ring[#ring];
    local nRemove = 0;
    if newest ~= nil then
        for _, v in pairs(newest.plan) do if v == 'remove' then nRemove = nRemove + 1; end end
    end
    check('DR1 the naked dispatch recorded its decision (16 removes)', nRemove, 16);
    check('DR1b the record carries fp + time + event', newest ~= nil
        and type(newest.fp) == 'string' and type(newest.time) == 'string'
        and newest.event == 'Default', true);

    -- PO: A RECORD'S CONTEST MUST EXPLAIN THAT RECORD'S PLAN (field report 3,
    -- 2026-08-02). The contest was rebuilt only on a retrace and reused
    -- otherwise, so a Default whose PLAN moved while the trace signature held
    -- attached the PREVIOUS plan's explanation to a NEW record. Henrik's
    -- report showed both halves: Ear1 in the plan with the contest naming
    -- nobody (a piece that became eligible on a level-up), then the claimant
    -- arriving two dispatches later as a zero-change record.
    local PO = dispatchM._planOutrunsContest;
    check('PO1 a planned slot the contest cannot account for outruns it',
        PO({ Ear1 = 'Optical Earring' },
           { explain = { main = { { name = 'Triggers', item = 'Harpoon' } } } }), true);
    check('PO2 a plan the contest fully covers does NOT',
        PO({ Main = 'Harpoon' },
           { explain = { main = { { name = 'Triggers', item = 'Harpoon' } } } }), false);
    -- THE ONE-WAY TEST, and the reason it is one-way: a lock or the level-sync
    -- weapon hold takes a slot OUT of the plan while the claim on it stands.
    -- That is two questions answered correctly, not a stale explanation, and
    -- rebuilding on it would re-explain on every held beat.
    check('PO3 a contest naming MORE than the plan is ordinary, not stale',
        PO({ Head = 'Circlet' },
           { explain = { head = { { name = 'Triggers', item = 'Circlet' } },
                         main = { { name = 'Triggers', item = 'Harpoon' } } } }), false);
    check('PO4 slot case never decides it (the findCI law)',
        PO({ MAIN = 'Harpoon' },
           { explain = { main = { { name = 'Triggers', item = 'Harpoon' } } } }), false);
    check('PO5 an absent contest under a real plan outruns by definition',
        PO({ Main = 'Harpoon' }, nil), true);
    check('PO6 ...but an empty plan never does (nothing to explain)',
        PO({}, nil), false);
    check('PO7 an explain entry with no winner does not count as coverage',
        PO({ Main = 'Harpoon' }, { explain = { main = {} } }), true);
    -- THE ITEM, not just the slot. The retrace signature does not cover the
    -- player's LEVEL, so levelling can swap the piece inside a slot the
    -- contest already covers -- a coverage-only test would keep an
    -- explanation naming the older piece (Henrik's Head went Lth. Bandana +1
    -- -> Faceguard +1 across 9 -> 10).
    check('PO9 a covered slot whose ITEM moved still outruns',
        PO({ Head = 'Faceguard +1' },
           { explain = { head = { { name = 'Triggers', item = 'Lth. Bandana +1' } } } }), true);
    check('PO10 ...and an agreeing item does not',
        PO({ Head = 'Faceguard +1' },
           { explain = { head = { { name = 'Triggers', item = 'Faceguard +1' } } } }), false);
    -- a claim that DEFENDS a slot or empties it never claimed to name the worn
    -- item, so it must not force a rebuild every beat it holds
    check('PO11 a defending sentinel is exempt',
        PO({ Main = 'Harpoon' },
           { explain = { main = { { name = 'Disabled', item = '(free equip)' } } } }), false);
    check('PO12 a planned "remove" is exempt',
        PO({ Head = 'remove' },
           { explain = { head = { { name = 'Naked', item = 'Circlet' } } } }), false);
    check('PO13 a non-string winner (the LOCK_HELD sentinel) is exempt',
        PO({ Head = 'Circlet' },
           { explain = { head = { { name = 'Locks', item = dispatchM.LOCK_HELD } } } }), false);

    -- THE INVARIANT ITSELF, over every record the suite's real dispatches
    -- built: a record whose plan outruns its contest is a record whose two
    -- halves disagree about who decided a slot, and that is what shipped for
    -- four days. Asserted on the ring rather than on one fixture, so any
    -- future dispatch path that reintroduces it fails here.
    local outran = nil;
    for _, r in ipairs(ring) do
        if PO(r.plan, r.contest) then outran = r.seq; break; end
    end
    check('PO8 every recorded decision is explained by its own contest', outran, nil);

    -- DR2: a byte-identical re-dispatch appends NOTHING; an empty plan is not
    -- a decision at all.
    local savedPlayerDR, savedStateDR = TEST_PLAYER, rawget(_G, 'gState');
    TEST_PLAYER = { MainJob = 'WHM', MainJobLevel = 75, SubJob = 'BLM', SubJobLevel = 37,
                    MainJobSync = 75, SubJobSync = 37, Status = 'Idle', IsMoving = false };
    _G.gState = { CurrentCall = 'N/A', Disabled = {} };
    local savedEngDR = package.loaded['dlac\\feature\\equipengine'];
    package.loaded['dlac\\feature\\equipengine'] = {
        nativeOn = function() return true; end,
        equipSet = function() end,
        state = { tripped = false },
    };
    dispatchM.nakedArmed = true;
    local n0 = #ring;
    pcall(dispatchM.dispatch, 'Default');
    check('DR2 an identical outcome appends nothing', #dispatchM.getDecisions(), n0);
    dispatchM.nakedArmed = false;
    package.loaded['dlac\\feature\\equipengine'] = savedEngDR;
    TEST_PLAYER = savedPlayerDR;
    _G.gState = savedStateDR;
    dispatchM._recordDecision('Default', {}, {}, nil);
    check('DR2b an empty plan records nothing', #dispatchM.getDecisions(), n0);

    -- DR3: the rank order is a retrace-sig leg (source pin, the ARK11 idiom):
    -- a dragged row must re-explain, or the ring misses a winner change and
    -- /dl why keeps stale attribution after a drag.
    check('DR3 the rank order is a retrace-sig leg',
        dsrc:find("'|ao' .. table.concat(arbOrder", 1, true) ~= nil, true);

    -- DR4-DR7: the fingerprint law, pure.
    local e1 = { Body = { { name = 'Triggers', rank = 11, item = 'X' } } };
    check('DR4 same items + same winners -> same fp',
        dispatchM.decisionFp({ Body = 'X' }, e1), dispatchM.decisionFp({ Body = 'X' }, e1));
    check('DR5 an item move changes the fp',
        dispatchM.decisionFp({ Body = 'X' }, e1) == dispatchM.decisionFp({ Body = 'Y' }, e1), false);
    local e2 = { Body = { { name = 'Craft', rank = 7, item = 'X' } } };
    check('DR6 a WINNER move under the same item changes the fp',
        dispatchM.decisionFp({ Body = 'X' }, e1) == dispatchM.decisionFp({ Body = 'X' }, e2), false);
    check('DR7 slot-key case never splits the fp',
        dispatchM.decisionFp({ Body = 'X' }, nil), dispatchM.decisionFp({ body = 'X' }, nil));

    -- DR8: the ring caps (oldest dropped). Distinct outcomes through the test
    -- seam; ctx {} is fine -- every snapshot read is defensive.
    for i = 1, dispatchM.DECISION_CAP + 10 do
        dispatchM._recordDecision('Default', {}, { Body = 'It' .. i }, nil);
    end
    check('DR8 the ring caps at DECISION_CAP', #dispatchM.getDecisions(), dispatchM.DECISION_CAP);

    -- DR9-DR12: THE RECEIPT (2026-08-01). recordDecision used to REBUILD the
    -- rung list from contest.src, which only the trigger floor writes -- so a
    -- claimant's fall had no rungs to show at all. contest.asked is the ladder
    -- the arbitration was actually handed; it wins, and the derivation is left
    -- to fill in the slots nothing was refused in.
    local kept = { Head = { set = 'HELM', items = { 'Wynav\'s Hat', 'Federation Tiara' } } };
    dispatchM._recordDecision('Default', {}, { Head = 'Federation Tiara' },
        { asked = kept });
    local drr = dispatchM.getDecisions();
    local dlast = drr[#drr];
    check('DR9 a claimant ladder reaches the record at all',
        dlast.ladders.Head.items[1], 'Wynav\'s Hat');
    check('DR9b named by its claimant, not by a set', dlast.ladders.Head.set, 'HELM');
    -- DR10: contest.src alone (no receipt) keeps the derivation path -- the
    -- uncontested slots that never asked anyone for a ladder.
    dispatchM._recordDecision('Default', {}, { Head = 'Derived Only' },
        { src = { Head = 'NoSuchSet' } });
    drr = dispatchM.getDecisions();
    check('DR10 no receipt and no derivable set -> no ladder, never a crash',
        drr[#drr].ladders, nil);
    -- DR11: both present -> the receipt wins. The derivation re-asks LATER and
    -- can answer differently (a bag moved, the level changed) than the list the
    -- decision was actually made from.
    dispatchM._recordDecision('Default', {}, { Head = 'Federation Tiara' },
        { src = { Head = 'NoSuchSet' }, asked = kept });
    drr = dispatchM.getDecisions();
    check('DR11 the receipt beats the re-derivation', drr[#drr].ladders.Head.set, 'HELM');
    -- DR12: a torn/absent receipt is simply not there.
    dispatchM._recordDecision('Default', {}, { Head = 'Bare' }, { asked = 'nonsense' });
    drr = dispatchM.getDecisions();
    check('DR12 a malformed receipt records no ladder', drr[#drr].ladders, nil);

    -- WW: the worldAbsentOutlasted seam (v153) -- the stream's lifetime gate.
    -- Bookkeeping must run UNARMED (nothing is armed here), and the boolean
    -- must flip only when absence OUTLASTS the zone window, never on absence
    -- alone -- the ZONES SURVIVE law (v146), read-only.
    dispatchM._worldGoneAt = nil;
    dispatchM.worldWatch(0, nil, 5000);
    check('WW1 absence alone does not outlast', dispatchM.worldAbsentOutlasted(5000 + 59), false);
    check('WW2 outlasting the zone window does', dispatchM.worldAbsentOutlasted(5000 + 61), true);
    dispatchM.worldWatch(6, nil, 5200);
    check('WW3 a live world clears the clock', dispatchM.worldAbsentOutlasted(5200 + 3600), false);

    -- IN: the Integration surface COMPLETE v1 -- worn + anchors + invalidate
    -- + confirm + the five queries (feature\integration). The collector
    -- decodes exactly as a consumer would: bytes -> string -> load() -- which
    -- also pins the byte-table SEND convention the probe verified.
    local _inok, IN = pcall(dofile, 'feature/integration.lua');   -- the harness seeds, it does not search
    check('IN1 integration loads headless', _inok and type(IN) == 'table', true);
    if _inok and type(IN) == 'table' then
        IN.CONFIRM_S = 999999;   -- confirms fire only when a test asks them to
        local fix = { a = 1, z = 'two words', n = { 1, 2, { deep = true } }, ok = false };
        local rt = nil;
        pcall(function() rt = (loadstring or load)('return ' .. IN._ser(fix))(); end);
        check('IN2 the serializer round-trips', rt ~= nil and rt.a == 1 and rt.z == 'two words'
            and rt.n[3].deep == true and rt.ok == false, true);

        local sent = {};
        IN._raise = function(name, bytes)
            local b = {};
            for i = 1, #bytes do b[i] = string.char(bytes[i]); end
            local t = nil;
            pcall(function() t = (loadstring or load)(table.concat(b))(); end);
            sent[#sent + 1] = { name = name, env = t };
        end;

        -- enable -> immediate snapshot of the newest ring record (6.5); the
        -- stream seq is OBSERVER-side now (one sequence across all kinds),
        -- the ring's own number rides as decisionSeq
        local ring = dispatchM.getDecisions();
        local newestSeq = ring[#ring].seq;
        IN.setOn(true);
        check('IN3 enable emits a snapshot on dlac_worn', #sent >= 1 and sent[#sent].name == 'dlac_worn'
            and sent[#sent].env ~= nil and sent[#sent].env.snapshot == true, true);
        check('IN3b the snapshot carries the ring seq as decisionSeq', sent[#sent].env.decisionSeq, newestSeq);
        check('IN3c and the stream seq starts at 1', sent[#sent].env.seq, 1);

        -- the pump drains new records FIFO, stream seq strictly continuous
        sent = {};
        dispatchM._recordDecision('Weaponskill', {}, { Body = 'StreamPiece A' }, nil);
        dispatchM._recordDecision('Default',     {}, { Body = 'StreamPiece B' }, nil);
        IN._pump();
        check('IN4 two new records -> two envelopes in order', #sent == 2
            and sent[1].env ~= nil and sent[2].env ~= nil
            and sent[2].env.seq == sent[1].env.seq + 1
            and sent[1].env.kind == 'worn' and sent[1].env.snapshot == false, true);
        check('IN4b the envelope names the items',
            sent[1].env.worn ~= nil and type(sent[1].env.worn.Body) == 'table'
            and sent[1].env.worn.Body.name, 'StreamPiece A');
        check('IN4c nothing new -> nothing sent', (function()
            local n0 = #sent; IN._pump(); return #sent == n0; end)(), true);

        -- a ring gap (overflowed past us): seqs older than ring[1] are PRUNED,
        -- so a watermark below them is a real loss and must be reported
        sent = {};
        dispatchM._recordDecision('Default', {}, { Body = 'StreamPiece C' }, nil);
        local ring2 = dispatchM.getDecisions();
        IN._lastRingSeq = math.max(1, (ring2[1].seq or 2) - 5);
        IN._pump();
        check('IN5 the first envelope after a gap carries dropped', #sent >= 1
            and sent[1].env ~= nil and (sent[1].env.dropped or 0) > 0, true);

        -- THE ANCHOR (v154): an action stub with no decision -> kind=dispatch,
        -- join key + ctx, no items; a stub LINKED to a decision emits nothing
        -- of its own (one anchor per action, never both)
        sent = {};
        dispatchM._recordAction('Weaponskill',
            { action = { Name = 'Test WS', actionId = 143, category = 7, target = 300 } }, nil);
        IN._pump();
        check('IN10 a no-change action emits a dispatch anchor', #sent == 1
            and sent[1].name == 'dlac_dispatch' and sent[1].env ~= nil
            and sent[1].env.kind == 'dispatch' and sent[1].env.actionId == 143
            and sent[1].env.worn == nil, true);
        sent = {};
        local ds = dispatchM._recordDecision('Ability', {}, { Body = 'AnchorLink' }, nil);
        dispatchM._recordAction('Ability', {}, ds);
        IN._pump();
        check('IN11 a gear-moving action emits ONE envelope (worn, no anchor)', #sent == 1
            and sent[1].env ~= nil and sent[1].env.kind == 'worn', true);

        -- invalidate: the sets-store rev watch (baselined at setOn, so this is
        -- the FIRST movement it can see)
        sent = {};
        local savedRev = dispatchM.modesRev;
        dispatchM.modesRev = (tonumber(dispatchM.modesRev) or 0) + 1;
        IN._pump();
        check('IN12 a sets-store rev bump emits invalidate', #sent == 1
            and sent[1].name == 'dlac_invalidate' and sent[1].env ~= nil
            and sent[1].env.kind == 'invalidate' and sent[1].env.changed ~= nil
            and sent[1].env.changed[1] == 'sets', true);
        dispatchM.modesRev = savedRev;
        IN._pump();   -- restoring the rev is itself a change; swallow it
        sent = {};

        -- outlasted world absence kills the switch silently (section 3)
        local savedWA = dispatchM.worldAbsentOutlasted;
        dispatchM.worldAbsentOutlasted = function() return true; end
        IN._pump();
        check('IN6 outlasted absence turns the stream off', IN.on, false);
        dispatchM.worldAbsentOutlasted = savedWA;

        -- confirm: injected services -- worn memory disagrees with the plan ->
        -- delta envelope; agrees -> silence (delta-only, the design's word)
        local fakeWornName = 'WrongPiece';
        IN._services = function()
            return {
                EQUIP_SLOTS = { { label = 'Body', equip = 5 } },
                getEquippedId = function() return 111; end,
                lookupById = function() return { Id = 111, Name = fakeWornName }; end,
                lookupByName = function(n) return { Id = 999, Name = n, Level = 70 }; end,
            };
        end;
        IN.setOn(true);
        IN.CONFIRM_S = -1;                      -- due immediately, same pump
        sent = {};
        dispatchM._recordDecision('Weaponskill', {}, { Body = 'PlannedPiece' }, nil);
        IN._pump();
        check('IN13 reality diverging from the plan emits confirm', #sent == 2
            and sent[2].name == 'dlac_confirm' and sent[2].env ~= nil
            and sent[2].env.kind == 'confirm'
            and sent[2].env.forSeq == sent[1].env.seq
            and sent[2].env.delta ~= nil and sent[2].env.delta.Body ~= nil
            and sent[2].env.delta.Body.actual == 'WrongPiece', true);
        fakeWornName = 'PlannedPiece2';
        sent = {};
        dispatchM._recordDecision('Weaponskill', {}, { Body = 'PlannedPiece2' }, nil);
        IN._pump();
        check('IN13b a plan that landed whole confirms by silence', #sent == 1
            and sent[1].env ~= nil and sent[1].env.kind == 'worn', true);
        IN.CONFIRM_S = 999999;

        -- the queries: worn, stats (routing), sets, gear, item -- and the
        -- channel gate. Replies always name their what; unknown answers err.
        sent = {};
        IN._onEvent({ name = 'dlac_query', data = 'return { reply = "tprs", what = "worn" }' });
        check('IN7 the worn query answers on the caller channel', #sent == 1 and sent[1].name == 'tprs_r'
            and sent[1].env ~= nil and sent[1].env.what == 'worn'
            and type(sent[1].env.data) == 'table' and sent[1].env.data.snapshot == true, true);
        sent = {};
        IN._onEvent({ name = 'dlac_query', data = 'return { reply = "tprs", what = "nosuch" }' });
        check('IN8 an unknown what answers with err, never silence', #sent == 1
            and sent[1].env ~= nil and sent[1].env.err ~= nil, true);
        sent = {};
        IN._onEvent({ name = 'dlac_query', data = 'return { reply = "tprs", what = "stats", comp = { Body = "PlannedPiece" } }' });
        check('IN14 the stats query routes and answers (data or a named err)', #sent == 1
            and sent[1].env ~= nil and sent[1].env.what == 'stats'
            and (sent[1].env.data ~= nil or sent[1].env.err ~= nil), true);
        local savedSets = dispatchM._nativeSets;
        dispatchM._nativeSets = { Dynamic = {}, TestSet = { Body = 'PlannedPiece' } };
        sent = {};
        IN._onEvent({ name = 'dlac_query', data = 'return { reply = "tprs", what = "sets" }' });
        local names = (#sent == 1 and sent[1].env ~= nil and sent[1].env.data ~= nil)
            and sent[1].env.data.names or nil;
        check('IN15 the sets query lists set names', names ~= nil and names[1], 'TestSet');
        sent = {};
        IN._onEvent({ name = 'dlac_query', data = 'return { reply = "tprs", what = "sets", set = "TestSet" }' });
        check('IN15b one set resolves to concrete slots', #sent == 1 and sent[1].env ~= nil
            and sent[1].env.data ~= nil and sent[1].env.data.slots ~= nil
            and sent[1].env.data.slots.Body ~= nil
            and sent[1].env.data.slots.Body.name, 'PlannedPiece');
        dispatchM._nativeSets = savedSets;
        local G = package.loaded['dlac\\gear'];
        G.NameToObject['TestBlade'] = { Id = 4242, Level = 50 };
        sent = {};
        IN._onEvent({ name = 'dlac_query', data = 'return { reply = "tprs", what = "gear" }' });
        local foundBlade = false;
        if #sent == 1 and sent[1].env ~= nil and sent[1].env.data ~= nil then
            for _, it in ipairs(sent[1].env.data.items or {}) do
                if it.name == 'TestBlade' and it.id == 4242 then foundBlade = true; end
            end
        end
        check('IN16 the gear query carries the owned record', foundBlade, true);
        G.NameToObject['TestBlade'] = nil;
        sent = {};
        IN._onEvent({ name = 'dlac_query', data = 'return { reply = "tprs", what = "item", name = "Anything" }' });
        check('IN17 the item query answers through the lookup door', #sent == 1
            and sent[1].env ~= nil and sent[1].env.data ~= nil
            and sent[1].env.data.id == 999, true);
        IN.setOn(false);
        sent = {};
        IN._onEvent({ name = 'dlac_query', data = 'return { reply = "tprs", what = "worn" }' });
        check('IN9 off = silent on the whole channel, queries included', #sent, 0);
    end
end)();

-- ---------------------------------------------------------------------------
-- EX. EXTERNAL CLAIMS -- the WRITE half of the Integration surface
--     (feature\extclaim). A separate ADDON, in its own Lua state, files a Claim
--     over plugin_event and the Arbiter settles it like any other claimant.
--
--     What these pin, in the order the design leans on them:
--       * the VALIDATOR names its refusals (a claim that vanishes silently is
--         indistinguishable from dlac being broken -- hard rule 12);
--       * the MERGE is deterministic between external addons (prio, then id
--         ascending -- never pairs() order, hard rule 8);
--       * the LEASE actually expires, and expiry TELLS the holder;
--       * the DOOR is gated but never silent, and `hello` answers even while
--         the switch is off (a consumer must be able to tell "dlac is not here"
--         from "the player has not turned this on");
--       * the SEND is a byte table carrying Lua source -- decoded here exactly
--         as a foreign addon would, which is what pins the wire format;
--       * the ROW is wired into the registry, the rank order and the retrace
--         signature. That last one is the silent killer: a claim that changes
--         without moving the signature never re-dispatches.
-- ---------------------------------------------------------------------------
(function()
    -- extclaim borrows the read half's serializer (one truth, no drifting twin),
    -- so seed it the way the live require would resolve it.
    package.loaded['dlac\\feature\\integration'] =
        package.loaded['dlac\\feature\\integration'] or dofile('feature/integration.lua');
    local _exok, EX = pcall(dofile, 'feature/extclaim.lua');
    check('EX1 extclaim loads headless', _exok and type(EX) == 'table', true);
    if not (_exok and type(EX) == 'table') then return; end

    -- ---- the validator (pure) --------------------------------------------
    local ok1, err1 = EX.normSlots({ head = 'Walahra Turban', RING1 = 'Rajas Ring' });
    check('EX2 slot keys canonicalise, whatever case arrived',
        ok1 ~= nil and ok1.Head == 'Walahra Turban' and ok1.Ring1 == 'Rajas Ring', true);
    check('EX2b and nothing else survives the rename', ok1 ~= nil and ok1.head, nil);
    local ok2, err2 = EX.normSlots({ Elbow = 'Walahra Turban' });
    check('EX3 an unknown slot is REFUSED BY NAME, never dropped in silence',
        ok2 == nil and type(err2) == 'string' and err2:find('Elbow') ~= nil, true);
    local ok3, err3 = EX.normSlots({ Head = 42 });
    check('EX3b a non-string item is refused by name', ok3 == nil and err3:find('Head') ~= nil, true);
    check('EX3c an empty claim is refused (release is the verb for that)',
        (function() local a, b = EX.normSlots({}); return a == nil and b ~= nil; end)(), true);
    check('EX3d "remove" passes through -- an external addon may claim a slot EMPTY',
        (function() local a = EX.normSlots({ Ammo = 'remove' }); return a and a.Ammo; end)(), 'remove');

    -- ---- the merge (pure) ------------------------------------------------
    -- Two addons, same slot. Higher prio wins; the loser keeps the slots nobody
    -- contested. Then equal prio -> the id ASCENDING decides, deterministically.
    local store = {
        zeta  = { id = 'zeta',  prio = 0, slots = { Head = 'Zeta Hat', Body = 'Zeta Robe' }, expires = 100 },
        alpha = { id = 'alpha', prio = 5, slots = { Head = 'Alpha Hat' }, expires = 100 },
    };
    local m, by = EX.merge(store, 50);
    check('EX4 higher prio wins the contested slot', m.Head, 'Alpha Hat');
    check('EX4b the loser keeps its uncontested slots', m.Body, 'Zeta Robe');
    check('EX4c the merge records WHO owns each slot', by.Head, 'alpha');
    -- WHO LOST TO WHOM among the externals. The Arbiter never sees this contest
    -- -- the merge settles it first -- so without `shadow` the loser is acked
    -- 'ok', holds a live lease, and is never told anything took its slot.
    -- Field-found 2026-08-01 (B claimed over A, got ok, and silence).
    local _, _, sh = EX.merge(store, 50);
    check('EX4d the loser is recorded, naming who took it', sh and sh.zeta and sh.zeta.Head, 'alpha');
    check('EX4e and only for the slot it actually lost', sh and sh.zeta and sh.zeta.Body, nil);
    check('EX4f the winner is not shadowed by anyone', sh and sh.alpha, nil);
    check('EX4g a three-way handover names the FINAL winner, never the middle one',
        (function()
            local s3 = {
                a = { id = 'a', prio = 0, slots = { Head = 'A Hat' }, expires = 100 },
                b = { id = 'b', prio = 1, slots = { Head = 'B Hat' }, expires = 100 },
                c = { id = 'c', prio = 2, slots = { Head = 'C Hat' }, expires = 100 },
            };
            local _, _, s = EX.merge(s3, 50);
            return s and s.a and s.a.Head;
        end)(), 'c');
    store.alpha.prio = 0;
    local m2 = EX.merge(store, 50);
    check('EX5 equal prio breaks on the id, ascending (never pairs order)', m2.Head, 'Alpha Hat');
    check('EX5b an expired record is invisible to the merge',
        (function()
            local s = { a = { id = 'a', prio = 0, slots = { Head = 'Gone' }, expires = 10 } };
            return EX.merge(s, 50);
        end)(), nil);

    -- ---- the lease -------------------------------------------------------
    local st = {};
    local a1 = EX.handle(st, { id = 'x', what = 'claim', slots = { Head = 'Hat' }, ttl = 5 }, 1000);
    check('EX6 a claim is accepted', a1.ok, true);
    check('EX6b and carries its lease back', a1.data.expiresIn, 5);
    check('EX6c the store holds it', st.x ~= nil and st.x.expires, 1005);
    local a2 = EX.handle(st, { id = 'x', what = 'claim', slots = { Head = 'Hat' }, ttl = 99999 }, 1000);
    check('EX6d an absurd ttl is CLAMPED and said so, not refused',
        a2.ok == true and a2.data.ttl == EX.TTL_MAX and a2.data.ttlClamped == true, true);
    EX.handle(st, { id = 'x', what = 'claim', slots = { Head = 'Hat' }, ttl = 5 }, 1000);
    local hb = EX.handle(st, { id = 'x', what = 'heartbeat' }, 1003);
    check('EX7 a heartbeat renews the lease', hb.ok == true and st.x.expires, 1008);
    local lapsed = EX.expire(st, 1007);
    check('EX7b the lease has not lapsed yet', lapsed, nil);
    lapsed = EX.expire(st, 1100);
    check('EX7c it lapses, and expire NAMES who lapsed',
        lapsed ~= nil and #lapsed == 1 and lapsed[1].id, 'x');
    check('EX7d and the store is empty again', st.x, nil);
    local hb2 = EX.handle(st, { id = 'x', what = 'heartbeat' }, 1200);
    check('EX7e a heartbeat with no claim refuses with a sentence, not a code',
        hb2.ok == false and type(hb2.err) == 'string' and hb2.err:find('claim') ~= nil, true);

    -- release + the claimant cap
    EX.handle(st, { id = 'y', what = 'claim', slots = { Head = 'Hat' } }, 1);
    local rel = EX.handle(st, { id = 'y', what = 'release' }, 1);
    check('EX8 release drops the claim and says whether there was one',
        rel.ok == true and rel.data.released == true and st.y == nil, true);
    local capStore = {};
    for i = 1, EX.MAX_CLAIMANTS do
        EX.handle(capStore, { id = 'c' .. i, what = 'claim', slots = { Head = 'H' } }, 1);
    end
    local over = EX.handle(capStore, { id = 'one-too-many', what = 'claim', slots = { Head = 'H' } }, 1);
    check('EX9 the claimant cap refuses and names itself',
        over.ok == false and over.err:find(tostring(EX.MAX_CLAIMANTS)) ~= nil, true);

    -- an unknown verb answers; a request with no id answers
    check('EX9b an unknown verb answers with err, never silence',
        (function() local a = EX.handle({}, { id = 'q', what = 'nosuch' }, 1); return a.ok == false and a.err ~= nil; end)(), true);
    check('EX9c a request with no id is told what it is missing',
        (function() local a = EX.handle({}, { what = 'claim' }, 1); return a.ok == false and a.err:find('id') ~= nil; end)(), true);

    -- ---- the live door: bytes in, bytes out -------------------------------
    -- The collector decodes exactly as a foreign addon would (bytes -> string ->
    -- load), which pins the byte-table SEND convention the probe verified.
    local sent = {};
    EX._raise = function(name, bytes)
        local b = {};
        for i = 1, #bytes do b[i] = string.char(bytes[i]); end
        local t = nil;
        pcall(function() t = (loadstring or load)(table.concat(b))(); end);
        sent[#sent + 1] = { name = name, env = t };
    end;
    local NOW = 500;
    EX._clock = function() return NOW; end
    EX._store, EX._by, EX._lastLost = {}, {}, {};

    EX.setOn(false);
    sent = {};
    EX._onEvent({ name = 'dlac_claim',
                  data = 'return { id = "p", reply = "p", what = "claim", slots = { Head = "Hat" } }' });
    check('EX10 with the switch off a claim is REFUSED, on the caller channel',
        #sent == 1 and sent[1].name == 'p_r' and sent[1].env ~= nil
        and sent[1].env.ok == false and sent[1].env.err ~= nil, true);
    check('EX10b and nothing was stored', EX._store.p, nil);
    sent = {};
    EX._onEvent({ name = 'dlac_claim', data = 'return { id = "p", reply = "p", what = "hello" }' });
    check('EX11 hello answers even while the switch is OFF (presence != permission)',
        #sent == 1 and sent[1].env ~= nil and sent[1].env.ok == true
        and sent[1].env.data.on == false, true);

    EX.setOn(true);
    sent = {};
    EX._onEvent({ name = 'dlac_claim',
                  data = 'return { id = "p", reply = "p", what = "claim", slots = { head = "Walahra Turban" }, ttl = 20 }' });
    check('EX12 with the switch on the claim lands and is acked',
        #sent == 1 and sent[1].env ~= nil and sent[1].env.ok == true
        and sent[1].env.data.slots.Head, 'Walahra Turban');
    check('EX12b and the row now has an opinion', EX.claim() ~= nil and EX.claim().Head, 'Walahra Turban');
    check('EX12c active() agrees', EX.active(), true);
    check('EX12d the status line NAMES the addon', EX.statusText():find('p') ~= nil, true);

    -- the verdict push: told once per CHANGE, then the all-clear. A notice on
    -- every Default tick would be a flood, and a flood gets filtered out.
    sent = {};
    EX.noteVerdict({ Head = 'Pins' });
    check('EX13 losing a slot pushes ONE verdict naming the winner',
        #sent == 1 and sent[1].env ~= nil and sent[1].env.what == 'verdict'
        and sent[1].env.data.lost.Head, 'Pins');
    EX.noteVerdict({ Head = 'Pins' });
    check('EX13b the same verdict does not push again', #sent, 1);
    EX.noteVerdict({});
    check('EX13c recovering the slot pushes the all-clear',
        #sent == 2 and sent[2].env.data.held == true, true);

    -- Losing to ANOTHER EXTERNAL ADDON must reach the loser too. Same notice,
    -- same dedupe: from the addon's side "something else is wearing that slot"
    -- is ONE fact and it should not have to learn it two different ways.
    EX._store['q'] = { id = 'q', label = 'Q', prio = 0, ttl = 60, reply = 'q',
                       slots = { Head = 'Q Hat' }, expires = NOW + 60 };
    EX._store['p'].prio = 5;                       -- p outranks q for the slot
    sent = {};
    EX.claim();                                    -- the merge decides + records
    EX.noteVerdict({});
    local qNote = nil;
    for _, s in ipairs(sent) do if s.name == 'q_r' then qNote = s.env; end end
    check('EX13d the shadowed addon is told it lost, and to whom',
        qNote ~= nil and qNote.what == 'verdict' and qNote.data.lost.Head, 'p');
    check('EX13e the winner is not told it lost anything',
        (function()
            for _, s in ipairs(sent) do
                if s.name == 'p_r' and s.env.data and s.env.data.held ~= true then return false; end
            end
            return true;
        end)(), true);
    EX._store['q'] = nil;
    EX._store['p'].prio = 0;
    EX.claim();
    EX._lastLost = {};

    -- the switch is a kill switch: OFF releases everything and TELLS the holder
    sent = {};
    EX.setOn(false);
    check('EX14 switching off releases every claim and notifies the holder',
        #sent == 1 and sent[1].env ~= nil and sent[1].env.what == 'expired', true);
    check('EX14b nothing is held afterwards', EX.claim(), nil);
    check('EX14c and a nil claim is how the row says "no opinion"', EX.active(), false);
    EX._store, EX._by, EX._lastLost = {}, {}, {};

    -- ---- the wiring ------------------------------------------------------
    -- The rank row, at the rank the plugin design ruled for a third party:
    -- directly above the Triggers floor.
    local def = dispatchM._arbDefaultOrder;
    local exIdx, trIdx = nil, nil;
    for i, n in ipairs(def) do
        if n == 'External' then exIdx = i; end
        if n == 'Triggers' then trIdx = i; end
    end
    check('EX15 the External rank row exists', exIdx ~= nil, true);
    check('EX15b and ships directly above the Triggers floor', exIdx, trIdx and (trIdx - 1));
    check('EX15c a player reads a phrase, not the identity',
        package.loaded['dlac\\gear\\arbiter'].claimantLabel('External'), 'Other addons');

    -- The CLAIMANTS row, with the two things that are silent when missing: the
    -- claim builder and the retrace signature leg.
    local row = nil;
    for _, r in ipairs(dispatchM._claimants or {}) do
        if r.name == 'External' then row = r; end
    end
    check('EX16 the External claimant row is registered', row ~= nil, true);
    check('EX16b it builds a claim', row ~= nil and type(row.claim), 'function');
    check('EX16c it applies', row ~= nil and type(row.apply), 'function');
    check('EX16d it reports itself to /dl prio', row ~= nil and type(row.prioStatus), 'function');
    check('EX16e it can dispatch alone (bail1/bail2 -- the Naked precedent)',
        row ~= nil and row.bail1 == true and row.bail2 == true, true);
    local hasSigLeg = false;
    for _, n in ipairs(dispatchM._claimantSigOrder or {}) do
        if n == 'External' then hasSigLeg = true; end
    end
    check('EX16f IT HAS A SIGNATURE LEG -- without one a changed claim never re-dispatches',
        hasSigLeg, true);

    -- The VERDICT JOIN, across a claimant that spells slots the other way.
    -- arbExplain says it outright: the producers disagree on case (overlay
    -- tables are proper-case, the Locks veto rides lowercased M.locks, a pin
    -- table or locked set carries whatever its source wrote). A case-sensitive
    -- join here does not name the WRONG winner -- it names NO winner, so the
    -- addon is told it still holds a slot something else took. Silent, and only
    -- for half the claimants. Field-prompted (Henrik, 2026-08-01: a pin held a
    -- slot and the verdict named MaxMP).
    local RANKS = { Disabled = 1, Naked = 2, Pins = 3, MaxMP = 6, External = 11 };
    local mineTbl = { Head = 'Claimed Hat', Ammo = 'Claimed Shot', Body = 'Claimed Robe' };
    local lost = dispatchM.externalLost(mineTbl, {
        External = mineTbl,
        Pins     = { head = 'Pinned Hat' },        -- LOWERCASE, as a pin file may be
        MaxMP    = { Ammo = 'MP Bullet' },         -- proper-case
        Triggers = { Body = 'Idle Robe' },         -- BELOW me: not a loss
    }, RANKS);
    check('EX24 a lowercase-keyed senior claimant is still reported as the winner', lost.Head, 'Pins');
    check('EX24b a proper-case one still is too', lost.Ammo, 'MaxMP');
    check('EX24c the slot comes back in MY casing, whatever the winner used', lost.head, nil);
    check('EX24d a claimant ranked BELOW me took nothing from me', lost.Body, nil);
    local lost2 = dispatchM.externalLost(mineTbl, {
        External = mineTbl,
        Pins     = { Head = 'Pinned Hat' },
        Naked    = { head = 'remove' },            -- stronger, and spelled the other way
    }, RANKS);
    check('EX24e when several beat one slot, the STRONGEST is named', lost2.Head, 'Naked');
    check('EX24f no rank row for me -> nothing is claimed to be lost',
        next(dispatchM.externalLost(mineTbl, { Pins = { Head = 'X' } }, { Pins = 3 })), nil);
    check('EX24g junk arguments answer empty, never throw',
        next(dispatchM.externalLost(nil, nil, nil)), nil);

    -- ZERO WHEN IDLE. active() and claim() run on EVERY dispatch, and Default
    -- dispatches constantly -- so leaving the switch on must cost nothing while
    -- nobody is claiming, or "just leave it on" becomes something the player has
    -- to think about. Identity on the shared EMPTY table is the cheap proxy for
    -- "allocated nothing": a fresh {} each dispatch is exactly the per-frame
    -- garbage this exists to prevent, and it would never show up as a failure
    -- anywhere else.
    EX._store, EX.on = {}, true;
    check('EX25 an idle claim() answers nil', EX.claim(), nil);
    check('EX25b and hands back the SHARED empty owner map, not a fresh one',
        EX._by, EX._EMPTY);
    check('EX25c an idle active() is false', EX.active(), false);
    check('EX25d merge answers the shared empty map too', (function()
        local _, by = EX.merge({}, 0); return by; end)(), EX._EMPTY);
    EX.on = false;

    -- THE PERSISTED PERMISSION (2026-08-01). The saved answer is the PERMISSION
    -- only; claims stay session state (EX23 above). Read ONCE per session: a
    -- re-read every frame would undo `/dl claims off` the moment it was typed,
    -- which is the failure this guards.
    do
        local sfm = package.loaded['dlac\\gear\\syncflags'];
        if sfm == nil then
            local okf, m = pcall(dofile, 'gear/syncflags.lua');
            if okf and type(m) == 'table' then
                sfm = m;
                package.loaded['dlac\\gear\\syncflags'] = m;   -- the name extclaim requires
            end
        end
        check('EX26z the persisted-flag store is reachable', type(sfm) == 'table', true);
        if type(sfm) == 'table' and type(sfm.flags) == 'table' then
            local savedSave, saved = sfm.saveUiFlags, sfm.flags[EX.FLAG];
            local wrote = 0;
            sfm.saveUiFlags = function() wrote = wrote + 1; end
            EX.on, EX._flagRead = false, false;
            sfm.flags[EX.FLAG] = nil;
            check('EX26 no saved answer -> nothing to restore, and keep asking',
                EX._readFlag(), false);
            check('EX26b and the switch stays off', EX.on, false);
            sfm.flags[EX.FLAG] = true;
            check('EX26c a saved YES is restored', EX._readFlag() == true and EX.on, true);
            check('EX26d and it is settled -- never read again this session', EX._flagRead, true);
            EX.setOn(false);
            check('EX26e turning it off WRITES the answer through', sfm.flags[EX.FLAG], false);
            check('EX26f and saves it', wrote > 0, true);
            EX.setOn(true);
            check('EX26g turning it on writes too', sfm.flags[EX.FLAG], true);
            EX.setOn(false);
            sfm.saveUiFlags, sfm.flags[EX.FLAG] = savedSave, saved;
            EX._flagRead = true;      -- leave it settled for anything after this
        end
    end

    -- ---- the published shim, driven against the real receiver ------------
    -- lib\dlacclaim.lua is the one file in dlac written to be loaded from a
    -- FOREIGN Lua state, which makes it the one file whose bugs land in someone
    -- else's addon. Its serializer is a SECOND implementation by necessity (it
    -- runs where dlac's own is unreachable), so the two are wired together here
    -- and the whole conversation is run end to end: a drift in either half is a
    -- failure, not a field report from a third party.
    local shim = dofile('lib/dlacclaim.lua');
    check('EX17 the client shim loads', type(shim) == 'table' and type(shim.new), 'function');
    do
        local savedCore = AshitaCore;
        local c = shim.new({ id = 'shimtest', label = 'Shim Test', ttl = 6, autoRegister = false });
        -- SEND side: the shim raises -> hand the bytes straight to the receiver,
        -- exactly as the broadcast would.
        AshitaCore = { GetPluginManager = function()
            return { RaiseEvent = function(_, name, bytes)
                local b = {};
                for i = 1, #bytes do b[i] = string.char(bytes[i]); end
                EX._onEvent({ name = name, data = table.concat(b), size = #bytes });
            end };
        end };
        -- RECEIVE side: dlac's replies -> back into the shim's own funnel.
        EX._raise = function(name, bytes)
            local b = {};
            for i = 1, #bytes do b[i] = string.char(bytes[i]); end
            if name == 'shimtest_r' then
                c:onEnvelope((loadstring or load)(table.concat(b))());
            end
        end;
        EX._store, EX._by, EX._lastLost = {}, {}, {};
        NOW = 900;

        EX.setOn(false);
        c:hello();
        check('EX18 hello crosses both halves and reports the switch off',
            c.present == true and c.enabled == false, true);
        c:claim({ Head = 'Walahra Turban' });
        check('EX18b a claim while off is refused, and the shim knows why',
            c.held == false and c.lastErr == 'external claims are off', true);

        EX.setOn(true);
        c:claim({ head = 'Walahra Turban', Ammo = 'remove' });
        check('EX19 the shim files a claim dlac accepts', c.held, true);
        check('EX19b the slot key came back canonicalised', c.slots and c.slots.Head, 'Walahra Turban');
        check('EX19c and dlac holds it for the arbiter', EX.claim() and EX.claim().Ammo, 'remove');

        EX.noteVerdict({ Head = 'Pins' });
        check('EX20 a lost slot reaches the shim, naming the winner', c.lost.Head, 'Pins');
        EX.noteVerdict({});
        check('EX20b and the all-clear clears it', c.lost.Head, nil);

        NOW = 903; c:heartbeat();
        check('EX21 a heartbeat renews across the wire', EX.claim() ~= nil, true);
        NOW = 910; EX._worldAt = 0; EX._pump();
        check('EX21b silence lapses the lease', EX.claim(), nil);
        check('EX21c and the shim is told, not left believing it holds gear', c.held, false);

        c:claim({ Head = 'Walahra Turban' });
        EX.setOn(false);
        check('EX22 the player switch is a kill switch the holder hears about',
            c.held == false and c.enabled == false, true);

        -- LOGOUT kills every CLAIM but NOT the switch (2026-08-01: the
        -- permission is a saved preference, the claims are session state). The
        -- holder is told, and `on` rides the notice so it knows the door is
        -- still open rather than assuming the player revoked it.
        EX.setOn(true);
        c:claim({ Head = 'Walahra Turban' });
        local savedWA2 = dispatchM.worldAbsentOutlasted;
        dispatchM.worldAbsentOutlasted = function() return true; end
        EX._worldAt = 0;              -- the world check is throttled to 1/sec (perf); force it due
        EX._pump();
        check('EX23 outlasted world absence drops every claim', EX.claim(), nil);
        check('EX23b but the SWITCH survives -- it is a saved preference, not a session consent',
            EX.on, true);
        check('EX23c the holder is told it no longer holds gear', c.held, false);
        check('EX23d and told the door is still open, without parsing a reason string',
            c.enabled, true);
        dispatchM.worldAbsentOutlasted = savedWA2;
        EX._store, EX._by, EX._lastLost = {}, {}, {};
        AshitaCore = savedCore;
    end
end)();

-- ---------------------------------------------------------------------------
-- AB. arbwatch -- the ADDON-SIDE writer of the arbstate rank Statefile (ADR
--     0012, step 2 / issue #49). The engine's read side is AR* above; these pin
--     the WRITER's pure seams: the default/sanitize reuse the engine's one
--     truth, serialize round-trips through arbOrder, and moveClaimant encodes
--     the drag rules (only the Triggers floor refuses the drag and stays last;
--     every other row -- claimants AND the Locks veto (step 3) -- moves freely).
-- ---------------------------------------------------------------------------
(function()
    local aw = dofile('feature/arbwatch.lua');
    check('AB0 arbwatch loads', type(aw), 'table');

    -- Default + sanitize delegate to the engine (one vocabulary, no drift).
    check('AB1 default order matches the engine default',
        table.concat(aw.defaultOrder(), '>'), 'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    check('AB1b defaultOrder is a fresh copy (mutating it does not stick)',
        (function() local d = aw.defaultOrder(); d[1] = 'X'; return aw.defaultOrder()[1]; end)(), 'Disabled');
    check('AB2 sanitize nil -> default',
        table.concat(aw.sanitize(nil), '>'), 'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    check('AB2b sanitize drops unknown, restores missing at its default position',
        table.concat(aw.sanitize({ order = { 'Fishing', 'Nonsense', 'Pins' } }), '>'),
        'Disabled>Naked>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Pins>Chocobo>ModeLock>External>Triggers');

    -- serialize -> the engine's file shape; round-trips through arbOrder.
    local txt = aw.serialize({ 'MaxMP', 'AutoAmmo', 'Pins', 'Locks', 'Craft', 'HELM', 'Fishing', 'Triggers' });
    check('AB3 serialize is a return { order = {...} } file',
        txt:match('^return { order = {') ~= nil, true);
    local chunk = (loadstring or load)(txt);
    check('AB3b serialized file parses', type(chunk), 'function');
    local roundtrip = dispatchM.arbOrder(chunk());
    check('AB3c serialize -> arbOrder round-trips a valid reorder',
        table.concat(roundtrip, '>'),
        'Disabled>Naked>MaxMP>AutoAmmo>Pins>Locks>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    check('AB3d serialize skips non-string / empty entries',
        aw.serialize({ 'Pins', '', 42, 'Triggers' }), 'return { order = { "Pins", "Triggers" } }\n');

    -- moveClaimant: the step-2 drag rules, pure.
    -- Indices are 1-based over the default order, which since v129 (ADR 0024)
    -- opens with the Disabled ceiling: Disabled Naked Pins Locks AutoAmmo MaxMP
    -- Craft HELM Fishing Chocobo Triggers.
    local def = aw.defaultOrder();
    check('AB4 a claimant moves up one (AutoAmmo #5 -> #4, crossing the Locks veto)',
        table.concat(aw.moveClaimant(def, 5, -1), '>'),
        'Disabled>Naked>Pins>AutoAmmo>Locks>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    check('AB4b a claimant moves down one (AutoAmmo #5 -> #6)',
        table.concat(aw.moveClaimant(def, 5, 1), '>'),
        'Disabled>Naked>Pins>Locks>MaxMP>AutoAmmo>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    check('AB4c the input order is not mutated', table.concat(def, '>'), 'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    -- Step 3: the Locks veto row now DRAGS (only the Triggers floor is fixed).
    check('AB5 Locks drags down one (#4 -> #5, under AutoAmmo)',
        table.concat(aw.moveClaimant(def, 4, 1), '>'),
        'Disabled>Naked>Pins>AutoAmmo>Locks>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    check('AB5a Locks drags up one, over Pins (Naked still above it)',
        table.concat(aw.moveClaimant(def, 4, -1), '>'),
        'Disabled>Naked>Locks>Pins>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    check('AB5b Triggers refuses the drag (the floor)', aw.moveClaimant(def, 13, -1), nil);
    -- The floor-adjacent row is External (#12) -- other addons ship directly
    -- above your triggers, with ModeLock (2026-08-03) landing directly above
    -- THEM. External is the row that cannot sink any further; Chocobo and
    -- ModeLock above it drag normally.
    check('AB6 the floor-adjacent claimant (External #12) cannot move down into the Triggers floor (stays last)',
        aw.moveClaimant(def, 12, 1), nil);
    check('AB6a Chocobo #10 CAN move down now -- it swaps with ModeLock, not the floor',
        table.concat(aw.moveClaimant(def, 10, 1), '>'),
        'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>ModeLock>Chocobo>External>Triggers');
    check('AB6b Fishing CAN move up (HELM #8 <-> Fishing #9)',
        table.concat(aw.moveClaimant(def, 9, -1), '>'),
        'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>Fishing>HELM>Chocobo>ModeLock>External>Triggers');
    -- Naked is an ORDINARY draggable row: "naked except my pins" is a drag, not
    -- a code path, so the day it becomes fixed the feature loses its escape hatch.
    check('AB6c Naked drags down (Pins takes the top -- naked except pins)',
        table.concat(aw.moveClaimant(def, 2, 1), '>'),
        'Disabled>Pins>Naked>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    check('AB6d Naked is not a FIXED row', aw.FIXED['Naked'], nil);
    check('AB7 out-of-range / bad args are nil, never a throw',
        aw.moveClaimant(def, 1, -1) == nil and aw.moveClaimant(def, 0, 1) == nil
        and aw.moveClaimant(def, 3, 0) == nil and aw.moveClaimant(nil, 1, 1) == nil, true);

    -- AB8. persist -- the WRITER's preserve-unknowns seam (issue #136). A drag
    -- gives arbwatch a KNOWN-only order; the file it overwrites may hold rows
    -- this build does not know, and those must not be dropped. persist weaves
    -- them back (delegating to the engine's arbOrderPersist); the serialized
    -- file keeps them, so setOrder no longer deletes a future/uninstalled/hand-
    -- added claimant's saved position.
    local rawGhost = { order = { 'Disabled', 'Naked', 'Pins', 'Locks', 'AutoAmmo',
        'MaxMP', 'Ghost', 'Craft', 'HELM', 'Fishing', 'Chocobo', 'Triggers' } };
    local dragKnown = { 'Disabled', 'Naked', 'Pins', 'Locks', 'AutoAmmo', 'MaxMP',
        'Craft', 'HELM', 'Fishing', 'Chocobo', 'Triggers' };
    check('AB8 persist weaves the unknown row back in at its position',
        table.concat(aw.persist(dragKnown, rawGhost), '>'),
        'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Ghost>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
    check('AB8b persist matches the engine seam exactly',
        table.concat(aw.persist(dragKnown, rawGhost), '>'),
        table.concat(dispatchM.arbOrderPersist(dragKnown, rawGhost), '>'));
    -- The serialized file the writer emits carries the unknown row through, so it
    -- reloads with the row intact (survives the round-trip on disk).
    local ghostTxt = aw.serialize(aw.persist(dragKnown, rawGhost));
    check('AB8c serialized file carries the unknown row',
        ghostTxt:find('"Ghost"', 1, true) ~= nil, true);
    local reGhost = (loadstring or load)(ghostTxt)();
    check('AB8d reload -> live view still drops it, persist still keeps it',
        (function()
            local live = table.concat(dispatchM.arbOrder(reGhost), '>');
            local kept = table.concat(aw.persist(dispatchM.arbOrder(reGhost), reGhost), '>');
            return (live:find('Ghost') == nil)
               and (kept:find('MaxMP>Ghost>Craft', 1, true) ~= nil);
        end)(), true);
    -- No raw file (fresh character) -> persist is just the sanitized order.
    check('AB8e no raw file -> plain sanitized order',
        table.concat(aw.persist(dragKnown, nil), '>'),
        'Disabled>Naked>Pins>Locks>AutoAmmo>MaxMP>Craft>HELM>Fishing>Chocobo>ModeLock>External>Triggers');
end)();

-- ---------------------------------------------------------------------------
-- GS. Groups auto-import scanner (Item 1): the pure `scan(fileText) -> candidates, notes`
--     transform (groupscan.lua). Text-scans a LuaAshitacast file for top-level
--     `[local] NAME = T?{...}` blocks and surfaces every group-shaped table (a flat string
--     array, or a container of them) as an import candidate, skipping gear sets / settings.
--     Reuses groupimport's sandbox eval + flat-list heuristic; hostile blocks error safely.
-- ---------------------------------------------------------------------------
package.loaded['dlac\\gear\\groupimport'] = dofile('gear/groupimport.lua');
(function()
    local gscan = dofile('gear/groupscan.lua');
    check('GS0 module loads',  type(gscan),      'table');
    check('GS0b scan exported', type(gscan.scan), 'function');

    local sample = [[
-- my BLU setup { this comment has an unbalanced brace
local Settings = { TpVariant = 1, ATKCAP = false }
local IdleVariantTable = { [1] = 'Refresh/Regen', [2] = 'Learn' }
local BlueSpells = {
    STR_DEX = T{'Foot Kick', 'Wild Oats', 'Queasyshroom'},
    VIT     = {'Cannonball', 'Tail Slap'},
    Debuff  = T{'Filamented Hold',},
}
local sets = {
    ['Idle'] = { Ammo = 'Tiphia Sting', Head = 'Mirage Keffiyeh +1' },
    ['TP']   = { Main = 'Maple Sugar', Sub = { Name = 'X', Augment = {'a'} } },
}
local Evil = { bad = os.execute('rm -rf /') }
]];
    local cands, notes = gscan.scan(sample);
    local byName = {};
    for _, c in ipairs(cands) do byName[c.name] = c.members; end

    -- a container of flat lists expands to one candidate per inner key
    check('GS1 BlueSpells expands to its inner groups',
        (byName.STR_DEX ~= nil and byName.VIT ~= nil and byName.Debuff ~= nil), true);
    check('GS1b STR_DEX member count',  byName.STR_DEX and #byName.STR_DEX, 3);
    check('GS1c member order preserved', byName.STR_DEX and byName.STR_DEX[1], 'Foot Kick');
    check('GS1d single-elem + trailing comma', byName.Debuff and #byName.Debuff, 1);
    check('GS1e plain {...} parses too (no T)',  byName.VIT and #byName.VIT, 2);
    -- the container name itself is NOT a candidate (only its group-shaped children are)
    check('GS2 container name not a candidate', byName.BlueSpells, nil);
    -- gear sets are skipped, not mistaken for groups
    check('GS3 gear-set keys not candidates', (byName.Idle == nil and byName.TP == nil), true);
    -- a flat variant/config table IS surfaced (the player deselects it in the preview)
    check('GS4 flat variant table surfaced', byName.IdleVariantTable ~= nil, true);

    -- hostile / unreadable blocks are skipped SAFELY (os is nil in the sandbox -> eval errors,
    -- os.execute never runs) and named in the notes; gear sets are noted too.
    local noteText = table.concat(notes, ' | ');
    check('GS5 hostile os.execute block skipped safely', string.find(noteText, 'Evil', 1, true) ~= nil, true);
    check('GS6 gear-set block noted',                    string.find(noteText, 'sets', 1, true) ~= nil, true);

    -- the candidates feed groupimport.classify / apply verbatim (the reuse contract)
    local gimp = package.loaded['dlac\\gear\\groupimport'];
    local groupsMap = {};
    for _, c in ipairs(cands) do groupsMap[c.name] = c.members; end
    local _, overwritten = gimp.classify(groupsMap, { STR_DEX = { 'old' } });
    check('GS7 classify sees the STR_DEX collision',
        (function() for _, n in ipairs(overwritten) do if n == 'STR_DEX' then return true; end end return false; end)(), true);

    -- duplicate names collapse to one candidate (first spelling wins)
    local dup = gscan.scan("local A = T{'x'}\nlocal A = T{'y'}\n");
    check('GS8 duplicate names dedup to one', #dup, 1);
    -- nil / non-string input is safe
    local c9 = gscan.scan(nil);
    check('GS9 nil input -> no candidates', #c9, 0);
end)();

-- ---------------------------------------------------------------------------
-- LS. Level-sync settle hold (dispatch.syncSettleStep + the equipResolved
--     ctx.syncHold branch, v56): a level jump on the SAME job arms a short
--     (SYNC_SETTLE_S) weapon hold -- an Incursion boss pop re-syncing the
--     party must not swap
--     Main mid-transition and zero saved TP. Job changes and first reads adopt
--     instantly; not-ready readings (level 0, job '?'/'NON') never touch the
--     tracker. While the hold is live, ONLY Main/Sub/Range are kept as worn --
--     armor and Ammo (no TP cost) dispatch normally.
-- ---------------------------------------------------------------------------
(function()
    check('LS0 pure rule exported',    type(dispatchM.syncSettleStep), 'function');
    check('LS0b live consult exported', type(dispatchM.syncSettleHold), 'function');
    local W = dispatchM.SYNC_SETTLE_S;
    check('LS0c settle window is a positive number', type(W) == 'number' and W > 0, true);

    local st = { job = nil, lv = nil, holdUntil = 0 };
    check('LS1 first read adopts, no hold',   dispatchM.syncSettleStep(st, 'WAR', 75, 100.0), false);
    check('LS2 stable level stays free',      dispatchM.syncSettleStep(st, 'WAR', 75, 101.0), false);
    check('LS3 sync lands -> hold arms',      dispatchM.syncSettleStep(st, 'WAR', 60, 102.0), true);
    check('LS4 still holding inside window',  dispatchM.syncSettleStep(st, 'WAR', 60, 102.0 + W - 0.1), true);
    check('LS5 window passed -> released',    dispatchM.syncSettleStep(st, 'WAR', 60, 102.0 + W), false);
    -- a staged transition (server re-syncs in steps) keeps extending the window
    check('LS6 second sync re-arms',          dispatchM.syncSettleStep(st, 'WAR', 50, 110.0), true);
    check('LS6b next stage extends',          dispatchM.syncSettleStep(st, 'WAR', 55, 111.0), true);
    check('LS6c still live past the FIRST deadline', dispatchM.syncSettleStep(st, 'WAR', 55, 110.0 + W + 0.5), true);
    -- job change: adopt instantly AND drop any live hold (new job must re-gear now)
    dispatchM.syncSettleStep(st, 'WAR', 40, 120.0);   -- arm
    check('LS7 job change adopts instantly',  dispatchM.syncSettleStep(st, 'NIN', 37, 120.5), false);
    check('LS7b job change drops the hold',   st.holdUntil, 0);
    -- not-ready readings leave the tracker (and a live hold) untouched
    dispatchM.syncSettleStep(st, 'NIN', 30, 130.0);   -- arm
    check('LS8 level 0 ignored (hold stays)',  dispatchM.syncSettleStep(st, nil,  0,  130.5), true);
    check('LS8b NON job ignored (hold stays)', dispatchM.syncSettleStep(st, 'NON', 75, 130.6), true);
    check('LS8c "?" job ignored (hold stays)', dispatchM.syncSettleStep(st, '?',  75, 130.7), true);
    check('LS8d junk never adopted into the tracker', st.lv, 30);

    -- equipResolved rides ctx.syncHold: weapons held as worn, the rest dispatches
    local lsSet = { Main = 'Joyeuse', Sub = 'GenbusShield', Range = 'Power Bow',
                    Ammo = 'Tiphia Sting', Body = 'Gaudy Harness' };
    local lsNote, lsTbl = dispatchM._equipResolved(lsSet, { syncHold = true });
    check('LS9 Main held',   lsTbl.Main,  nil);
    check('LS10 Sub held',   lsTbl.Sub,   nil);
    check('LS11 Range held', lsTbl.Range, nil);
    check('LS12 Ammo NOT held (no TP cost)', lsTbl.Ammo, 'Tiphia Sting');
    check('LS13 armor unaffected',           lsTbl.Body, 'Gaudy Harness');
    check('LS14 the hold is traced for /dl why', string.find(lsNote, 'SYNC-HOLD', 1, true) ~= nil, true);
    local _, lsTbl2 = dispatchM._equipResolved(lsSet, { syncHold = false });
    check('LS15 no hold: weapons dispatch',  lsTbl2.Main, 'Joyeuse');
    local _, lsTbl3 = dispatchM._equipResolved(lsSet, {});
    check('LS16 absent flag: weapons dispatch (old ctx shape)', lsTbl3.Main, 'Joyeuse');

    -- ROOT CAUSE pin: a level-driven VIRTUAL in a weapon slot must be held
    -- UNRESOLVED -- resolving it at the transient level IS the field bug. This
    -- kills the "refactor the hold into a post-pass on final names" mutant:
    -- only the branch's position ABOVE the dlac: branch guarantees it.
    local lsV = { Main = 'dlac:AutoStaff|Fallback Staff', Sub = 'dlac:AutoGrip|Fallback Grip' };
    local lsVNote, lsVTbl = dispatchM._equipResolved(lsV, { syncHold = true });
    check('LS17 virtual Main held unresolved',  lsVTbl.Main, nil);
    check('LS17b virtual Sub held unresolved',  lsVTbl.Sub, nil);
    check('LS18 the hold is what got traced',   string.find(lsVNote, 'SYNC-HOLD', 1, true) ~= nil, true);
    check('LS18b no virtual resolution leaked', string.find(lsVNote, 'AutoStaff', 1, true), nil);
    local _, lsVFree = dispatchM._equipResolved(lsV, {});
    check('LS19 no hold: virtual resolves (fallback rides)', lsVFree.Main ~= nil, true);

    -- Sync-hold companion rule (ADR 0010): with Range held, a stat-stick Ammo
    -- whose RSlot reserves Range must hold too -- otherwise it lands and the
    -- SERVER strips the worn ranged weapon mid-window. Fired ammo (no Range
    -- bit, like LS12's recordless Tiphia Sting) keeps dispatching.
    local gearLS = package.loaded['dlac\\gear'];
    gearLS.NameToObject['Aureole'] = { Name = 'Aureole', RSlot = 0x0004 + 0x0008, Level = 70 };
    local lsTrink = { Range = 'Power Bow', Ammo = 'Aureole', Body = 'Gaudy Harness' };
    local lsTNote, lsTTbl = dispatchM._equipResolved(lsTrink, { syncHold = true });
    check('LS20 Range held',                    lsTTbl.Range, nil);
    check('LS20b Range-reserving Ammo held too', lsTTbl.Ammo, nil);
    check('LS20c armor still dispatches',        lsTTbl.Body, 'Gaudy Harness');
    check('LS20d companion hold traced',
        string.find(lsTNote, 'reserves Range', 1, true) ~= nil, true);
    -- no hold: ADR 0010 behavior unchanged (trinket vs ranged decided by Level)
    local _, lsTFree = dispatchM._equipResolved(lsTrink, {});
    check('LS21 no hold: trinket rule decides (higher Level wins)', lsTFree.Ammo, 'Aureole');
    check('LS21b no hold: the lower-Level ranged weapon dropped',   lsTFree.Range, nil);
    gearLS.NameToObject['Aureole'] = nil;

    -- The LIVE consult: the gData glue (field names, tonumber, pcall) and the
    -- shared tracker on M. Deterministic: arming and the truth test share one
    -- os.clock() read inside each call; the job change zeroes holdUntil.
    TEST_PLAYER = { MainJob = 'WAR', SubJob = 'NIN', MainJobSync = 75, SubJobSync = 37 };
    dispatchM.syncSettleHold();                       -- first good read adopts silently
    check('LS22 live: stable reading, no hold',   dispatchM.syncSettleHold(), false);
    TEST_PLAYER.MainJobSync = 60;                     -- a level sync lands
    check('LS23 live: sync jump arms the hold',   dispatchM.syncSettleHold(), true);
    check('LS23b live: tracker parked on M (survives self-swap)',
        type(dispatchM._syncSt) == 'table' and dispatchM._syncSt.lv, 60);
    TEST_PLAYER.MainJob = 'NIN';                      -- job change adopts instantly
    check('LS24 live: job change drops the hold', dispatchM.syncSettleHold(), false);
    TEST_PLAYER = nil;                                -- not-ready read: tracker untouched
    check('LS25 live: nil player never arms',     dispatchM.syncSettleHold(), false);

    -- The Default gate (M.defaultGateHold): what the HandleEquipEvent wrap
    -- consults AT CALL TIME. Pet hold first, then the sync settle hold.
    TEST_PLAYER = { MainJob = 'BLM', SubJob = 'WHM', MainJobSync = 37, SubJobSync = 18 };
    dispatchM.syncSettleHold();                       -- job differs from LS24's NIN: adopt, no hold
    check('LS26 gate: idle -> not held',          dispatchM.defaultGateHold(), false);
    _G.gState = { PetAction = { Completion = os.clock() + 5 } };
    check('LS27 gate: pet action in flight -> held', dispatchM.defaultGateHold(), true);
    _G.gState.PetAction = nil;
    TEST_PLAYER.MainJobSync = 30;                     -- a sync lands (same job BLM)
    check('LS28 gate: sync settling -> held',     dispatchM.defaultGateHold(), true);
    TEST_PLAYER.MainJob = 'WAR';                      -- job change releases
    check('LS29 gate: job change releases',       dispatchM.defaultGateHold(), false);
    _G.gState = nil;

    -- (LS30-LS34 -- the HandleEquipEvent wrap SHELL -- died in the purge,
    -- Phase 2 with the wrap itself: there is no LAC entry point left to
    -- gate. The gate LOGIC survives as M.defaultGateHold, pinned by LS26-29
    -- above; the native engine consults the holds inside its own dispatch.)
    _G.gFunc, _G.gState = nil, nil;
    TEST_PLAYER = nil;
end)();

-- ---------------------------------------------------------------------------
-- PL. paired-slot dynamic ladders (gearoptim.pairLadders) -- Ear/Ring pairs
--     ladder as one running TOP-2 walk so BOTH physical slots fill. Field case
--     (Henrik, 2026-07-17): under Cure Potency weights, Curates' Earring (30)
--     and Roundel Earring (73) both laddered onto Ear1 and Ear2 stayed empty --
--     the pair must wear both once both are owned. The scores here are the
--     caller's weighted scores at the build level; pairLadders is pure.
-- ---------------------------------------------------------------------------
(function()
    local optim = dofile('gear/gearoptim.lua');
    local function names(chain)
        local t = {};
        for _, c in ipairs(chain) do t[#t + 1] = tostring(c.name); end
        return table.concat(t, ',');
    end

    -- The field case: both earrings owned -> one per ear, not both on Ear1.
    local curates = { ref = 'C', name = "Curates' Earring", id = 1, level = 30, score = 30, copies = 1 };
    local roundel = { ref = 'R', name = 'Roundel Earring',  id = 2, level = 73, score = 50, copies = 1 };
    local c1, c2 = optim.pairLadders({ curates, roundel });
    check('PL1 field case: first ear keeps the early earring', names(c1), "Curates' Earring");
    check('PL2 field case: second ear gets the late earring',  names(c2), 'Roundel Earring');

    -- joint pins matching the chain tops (in either order -- the two physical
    -- slots are interchangeable) claim the chains untouched
    c1, c2 = optim.pairLadders({ curates, roundel }, { pins = { roundel, curates } });
    check('PL3 top pins claim chains untouched (1)', names(c1), "Curates' Earring");
    check('PL4 top pins claim chains untouched (2)', names(c2), 'Roundel Earring');

    -- a strictly-improving upgrade run ALTERNATES between the chains: at every
    -- level the two flattens together wear the best two owned pieces (the old
    -- shape put all four on slot 1 and starved slot 2 completely)
    local A = { ref = 'A', name = 'A', id = 11, level = 10, score = 5  };
    local B = { ref = 'B', name = 'B', id = 12, level = 20, score = 10 };
    local C = { ref = 'C', name = 'C', id = 13, level = 30, score = 12 };
    local D = { ref = 'D', name = 'D', id = 14, level = 40, score = 20 };
    c1, c2 = optim.pairLadders({ A, B, C, D });
    check('PL5 running top-2: chain 1', names(c1), 'A,C');
    check('PL6 running top-2: chain 2', names(c2), 'B,D');

    -- same-level pieces fill both slots at once
    local X = { ref = 'X', name = 'X', id = 51, level = 30, score = 20 };
    local Y = { ref = 'Y', name = 'Y', id = 52, level = 30, score = 15 };
    c1, c2 = optim.pairLadders({ Y, X });                     -- input order shuffled on purpose
    check('PL7 same-level pair fills both slots', names(c1) .. '|' .. names(c2), 'X|Y');

    -- a single copy never fills both slots ...
    local solo = { ref = 'S', name = 'Solo Ring', id = 21, level = 30, score = 40 };
    c1, c2 = optim.pairLadders({ solo });
    check('PL8 one copy -> one chain only', names(c1) .. '|' .. names(c2), 'Solo Ring|');

    -- ... but TWO owned copies do (Auto-build passes live owned counts)
    local twin = { ref = 'T', name = 'Twin Ring', id = 22, level = 30, score = 40, copies = 2 };
    c1, c2 = optim.pairLadders({ twin });
    check('PL9 two copies -> both chains', names(c1) .. '|' .. names(c2), 'Twin Ring|Twin Ring');

    -- same-NAME legacy duplicates are ONE physical item (optimizePicks' rule)
    local dupA = { ref = 'd1', name = "Jalzahn's Ring", id = 31, level = 50, score = 40 };
    local dupB = { ref = 'd2', name = "jalzahn's ring",           level = 50, score = 40 };
    c1, c2 = optim.pairLadders({ dupA, dupB });
    check('PL10 same-name duplicate fills one slot only', #c1 + #c2, 1);

    -- zero scorers are never kept (the seed-at-0 rule: no junk padding)
    c1, c2 = optim.pairLadders({ { ref = 'z', name = 'Junk', id = 41, level = 10, score = 0 } });
    check('PL11 zero score never padded', #c1 + #c2, 0);

    -- a leftover pin (not a chain top -- the cap optimizer preferred a lower
    -- piece) trims its chain like the single-slot ladder cap, and a single-copy
    -- pin is STRIPPED from the other chain -- leaving it would double-equip at
    -- the levels where both chains flatten to it
    c1, c2 = optim.pairLadders({ A, B, C, D }, { pins = { D, B } });
    check('PL12 leftover pin trims its chain',                 names(c1), 'A,B');
    check('PL13 single-copy pin stripped from the other chain', names(c2), 'D');
end)();

-- ---------------------------------------------------------------------------
-- LL. level-banded single-slot ladders (gearoptim.levelLadder) -- Auto-build
--     re-scores candidates at every band edge (adoption level + levelstats
--     thresholds) and emits between-level windows where value changes. Field
--     case (Henrik, 2026-07-19): Garrison Tunica +1's Refresh+1 dies past
--     Lv.50 -- its points must stop at 50 and the next body take over at 51.
--     Monotone slots must come back as the classic unranged chain (parity).
-- ---------------------------------------------------------------------------
(function()
    local optim = dofile('gear/gearoptim.lua');
    local function fmt(lad)
        local t = {};
        for _, e in ipairs(lad) do
            t[#t + 1] = tostring(e.ref) .. '[' .. tostring(e.minLevel or '') .. '-' .. tostring(e.maxLevel or '') .. ']';
        end
        return table.concat(t, ',');
    end
    local function ladder(items, scores, joint, cap)
        return optim.levelLadder(items, {
            cap = cap or 75,
            scoreAt = function(ref, L) return scores[ref](L); end,
            joint = joint,
        });
    end

    -- monotone upgrades: classic chain, zero windows -- today's output verbatim
    local lad = ladder(
        { { ref = 'A', level = 1 }, { ref = 'B', level = 20 } },
        { A = function() return 5; end, B = function() return 9; end });
    check('LL1 monotone slot keeps the classic unranged chain', fmt(lad), 'A[-],B[-]');

    -- THE tunica shape: A is worth 10 up to 50 then decays to 4; B (worth 6,
    -- wearable at 30) must own 51+ -- and A's window must CLOSE at 50 even
    -- though B's adoption level is lower than the handover level
    lad = ladder(
        { { ref = 'A', level = 20, breaks = { 51 } }, { ref = 'B', level = 30 } },
        { A = function(L) return (L < 51) and 10 or 4; end, B = function() return 6; end });
    check('LL2 decay closes the window and hands over', fmt(lad), 'A[-50],B[51-]');

    -- joint pick (set-level choice, per-item score irrelevant) trims exactly
    -- like the classic chain: lower rungs stay, output unranged (parity)
    lad = ladder(
        { { ref = 'A', level = 20 }, { ref = 'C', level = 40 } },
        { A = function() return 10; end, C = function() return 3; end }, 'C');
    check('LL3 joint trim stays classic', fmt(lad), 'A[-],C[-]');

    -- zero scorers are never kept (the seed-at-0 rule)
    lad = ladder({ { ref = 'Z', level = 10 } }, { Z = function() return 0; end });
    check('LL4 zero score never kept', fmt(lad), '');

    -- a `from` gainer can win, lose the middle, and win again: the SAME item
    -- appears twice with disjoint windows
    lad = ladder(
        { { ref = 'B', level = 10, breaks = { 40 } }, { ref = 'A', level = 30 } },
        { B = function(L) return (L < 40) and 2 or 9; end, A = function() return 5; end });
    check('LL5 regain emits the item twice with disjoint windows', fmt(lad), 'B[-29],A[30-39],B[40-]');

    -- a winner-less gap (everything scores 0 there) inherits the previous
    -- winner: unweighted stats still count, the slot is never bared
    lad = ladder(
        { { ref = 'A', level = 20, breaks = { 41 } }, { ref = 'B', level = 30, breaks = { 50 } } },
        { A = function(L) return (L < 41) and 10 or 0; end, B = function(L) return (L < 50) and 0 or 7; end });
    check('LL6 winner-less gap extends the previous winner', fmt(lad), 'A[-49],B[50-]');

    -- thresholds above the build cap are ignored: below it the tunica never
    -- decays, so the slot is a single classic entry
    lad = ladder(
        { { ref = 'A', level = 20, breaks = { 51 } }, { ref = 'B', level = 30 } },
        { A = function(L) return (L < 51) and 10 or 4; end, B = function() return 6; end },
        nil, 40);
    check('LL7 breaks beyond the cap are ignored', fmt(lad), 'A[-]');

    -- emptyFrom: from that level up the slot is RESERVED by another of the set's
    -- picks (a Royal Cloak eating the Head). Rungs below it stay -- the slot is
    -- yours until the Cloak is wearable -- and NOTHING takes over above it, so
    -- every surviving rung must close (an open top rung would keep the slot).
    local function ladderE(items, scores, ef, cap)
        return optim.levelLadder(items, {
            cap = cap or 75,
            scoreAt = function(ref, L) return scores[ref](L); end,
            emptyFrom = ef,
        });
    end
    lad = ladderE(
        { { ref = 'A', level = 1 }, { ref = 'B', level = 20 } },
        { A = function() return 5; end, B = function() return 9; end }, 59);
    check('LL8 reserved slot dies at the reserver level', fmt(lad), 'A[-19],B[20-58]');

    -- a reserver wearable before anything in the slot leaves it empty outright
    lad = ladderE({ { ref = 'A', level = 30 } }, { A = function() return 5; end }, 20);
    check('LL9 reserved below every rung: nothing at all', fmt(lad), '');

    -- a reserver above the build cap never bites (the trim is a no-op)
    lad = ladderE(
        { { ref = 'A', level = 1 }, { ref = 'B', level = 20 } },
        { A = function() return 5; end, B = function() return 9; end }, 80, 75);
    check('LL10 reserver beyond the cap changes nothing', fmt(lad), 'A[-],B[-]');
end)();

-- ---------------------------------------------------------------------------
-- PLL. level-banded PAIR ladders (gearoptim.pairLevelLadders) -- the Ear/Ring
--      twin of levelLadder: at every band the pair wears the true top-2 by
--      score-at-that-level. Flat scores must reproduce pairLadders' chains
--      verbatim (PL5/6, PL12/13 parity); a decaying piece hands its slot over
--      at the breakpoint with a between-level window.
-- ---------------------------------------------------------------------------
(function()
    local optim = dofile('gear/gearoptim.lua');
    local function fmt(lad)
        local t = {};
        for _, e in ipairs(lad) do
            t[#t + 1] = tostring(e.ref) .. '[' .. tostring(e.minLevel or '') .. '-' .. tostring(e.maxLevel or '') .. ']';
        end
        return table.concat(t, ',');
    end
    local function pair(cands, scores, pins, cap)
        local cA, cB = optim.pairLevelLadders(cands, {
            cap = cap or 75,
            scoreAt = function(ref, L) return scores[ref](L); end,
            pins = pins,
        });
        return fmt(cA), fmt(cB);
    end
    local flat = {
        A = function() return 5; end,  B = function() return 10; end,
        C = function() return 12; end, D = function() return 20; end,
    };
    local A = { ref = 'A', name = 'A', id = 11, level = 10 };
    local B = { ref = 'B', name = 'B', id = 12, level = 20 };
    local C = { ref = 'C', name = 'C', id = 13, level = 30 };
    local D = { ref = 'D', name = 'D', id = 14, level = 40 };

    -- flat scores: byte-for-byte the classic running top-2 chains (PL5/6)
    local a, b = pair({ A, B, C, D }, flat);
    check('PLL1 flat scores keep pairLadders chains (1)', a, 'A[-],C[-]');
    check('PLL2 flat scores keep pairLadders chains (2)', b, 'B[-],D[-]');

    -- decay handover on a pair: E1 (Refresh-style, dies past 50) owns a slot to
    -- 50, then the SECOND-best remaining piece takes that slot with a window
    local E1 = { ref = 'E1', name = 'E1', id = 21, level = 20, breaks = { 51 } };
    local E2 = { ref = 'E2', name = 'E2', id = 22, level = 20 };
    local E3 = { ref = 'E3', name = 'E3', id = 23, level = 30 };
    a, b = pair({ E1, E2, E3 }, {
        E1 = function(L) return (L < 51) and 10 or 2; end,
        E2 = function() return 6; end,
        E3 = function() return 5; end,
    });
    check('PLL3 decaying piece hands its slot over at 51', a, 'E1[-50],E3[51-]');
    check('PLL4 partner slot undisturbed', b, 'E2[-]');

    -- one owned copy fills one slot; two copies fill both
    local S = { ref = 'S', name = 'Solo', id = 31, level = 30 };
    a, b = pair({ S }, { S = function() return 8; end });
    check('PLL5 one copy -> one chain only', a .. '|' .. b, 'S[-]|');
    local T = { ref = 'T', name = 'Twin', id = 32, level = 30, copies = 2 };
    a, b = pair({ T }, { T = function() return 8; end });
    check('PLL6 two copies -> both chains', a .. '|' .. b, 'T[-]|T[-]');

    -- pin reconciliation parity (PL12/13): a leftover pin trims its chain, a
    -- single-copy pin is swept from the other chain
    a, b = pair({ A, B, C, D }, flat, { D, B });
    check('PLL7 leftover pin trims its chain',                  a, 'A[-],B[-]');
    check('PLL8 single-copy pin swept from the other chain',    b, 'D[-]');

    -- zero scorers are never kept
    a, b = pair({ A }, { A = function() return 0; end });
    check('PLL9 zero score never kept', a .. '|' .. b, '|');
end)();

-- ---------------------------------------------------------------------------
-- HELM: helmwatch state + parsers + the engine's dlac:AutoHelm overlay (v59)
-- -- docs/design/helm-gear.md. Idle-only is STRUCTURAL (the overlay is only
-- consulted on Default, same gate as craft); these cover resolution + rules.
-- ---------------------------------------------------------------------------
(function()
    local helmwatch = dofile('feature/helmwatch.lua');

    -- state rules (the craftwatch model: select does not enable; fishing is
    -- deliberately not a category -- it gets its own automation someday)
    check('H0 fresh state defaults to Harvesting (first-timer rule: an armed switch must never sit categoryless)',
                                           helmwatch.getGather(), 'Harvesting');
    helmwatch.selectGather('Mining');
    check('H1 selectGather sets active',   helmwatch.getGather(), 'Mining');
    check('H2 select does NOT enable',     helmwatch.isEnabled(), false);
    helmwatch.selectGather('logging');
    check('H3 lowercase tolerated',        helmwatch.getGather(), 'Logging');
    helmwatch.selectGather('Fishing');
    check('H4 fishing rejected',           helmwatch.getGather(), 'Logging');
    helmwatch.setEnabled(true);
    check('H5 switch turns on',            helmwatch.isEnabled(), true);
    helmwatch.setEnabled(false);
    check('H6 switch off',                 helmwatch.isEnabled(), false);

    -- category from NPC name + the 0x034 result-event detect. The event bytes
    -- are the REAL Ghelsba Outpost capture (2026-07-17, Mindie's swing that
    -- chopped an Arrowwood Log): ActIndex 319 @0x28, zone 140 @0x2A.
    check('H7 Mining Point -> Mining',     helmwatch.gatherFromNpcName('Mining Point'), 'Mining');
    check('H8 Harvesting Point',           helmwatch.gatherFromNpcName('Harvesting Point'), 'Harvesting');
    check('H9 unrelated npc -> nil',       helmwatch.gatherFromNpcName('Goblin Miner'), nil);
    check('H10 nil npc -> nil',            helmwatch.gatherFromNpcName(nil), nil);
    -- The CLIENT abbreviates excavation (field-read 2026-08-06, Arrapago
    -- Reef): matching only the server's full polutils_name left Auto HELM
    -- blind to every excavation point. Harvesting is the same 16 characters
    -- and is NOT abbreviated -- length is not the rule, so both spellings
    -- have to match and the other three must stay single-named.
    check('H8b Excav. Point (client name) -> Excavation',
                                           helmwatch.gatherFromNpcName('Excav. Point'), 'Excavation');
    check('H8c Excavation Point (server spelling) still matches',
                                           helmwatch.gatherFromNpcName('Excavation Point'), 'Excavation');
    check('H8d trailing whitespace tolerated (GetName pads)',
                                           helmwatch.gatherFromNpcName('Excav. Point  '), 'Excavation');
    -- the `.` must be matched LITERALLY, not as a pattern wildcard
    check('H8e "." is not a wildcard',      helmwatch.gatherFromNpcName('ExcavX Point'), nil);
    check('H8f abbreviation is excavation-only',
                                           helmwatch.gatherFromNpcName('Harvest. Point'), nil);
    local evt = string.char(0x34, 0x1A, 0x8D, 0x06, 0x3F, 0xC1, 0x08, 0x01, 0xB0, 0x02, 0, 0)
        .. string.rep('\0', 28)
        .. string.char(0x3F, 0x01, 0x8C, 0x00, 0x64, 0x00, 0x08, 0x00, 0x8C, 0x00, 0x00, 0x00);
    check('H10b result-event npc index (real capture)', helmwatch.eventNpcIndex(evt), 319);
    check('H10c short packet -> nil',      helmwatch.eventNpcIndex('short'), nil);
    helmwatch.onEventNum(evt, function(i) return (i == 319) and 'Logging Point' or nil; end);
    check('H10d detection from result event',
        helmwatch.lastDetect ~= nil and helmwatch.lastDetect.gather or nil, 'Logging');
    helmwatch.onEventNum(evt, function(i) return 'Fantoccini'; end);   -- ordinary NPC event
    check('H10e non-Point event leaves detect alone',
        helmwatch.lastDetect ~= nil and helmwatch.lastDetect.gather or nil, 'Logging');

    -- 0x1A4 POINTS_ENTRY wire format (trove protocol): group@0x08 (19b) |
    -- label@0x1C (23b) | i32 value@0x34; CLEAR/END_LIST commits the stream.
    local function zi32(v) return string.char(v % 256, math.floor(v/256)%256, math.floor(v/65536)%256, math.floor(v/16777216)%256); end
    local function zfield(s, width) return s .. string.rep('\0', width - #s); end
    local function pointsEntry(group, label, value)
        return string.char(0xA4, 0, 0, 0) .. string.char(7) .. string.rep('\0', 3)
            .. zfield(group, 20) .. zfield(label, 24) .. zi32(value);
    end
    local endList = string.char(0xA4, 0, 0, 0) .. string.char(2) .. '\0';
    check('H11 entry consumed',  helmwatch.on1A4(pointsEntry('Ventures', 'Mining', 3200)), true);
    check('H12 no commit before END', helmwatch.pointsFor('Mining'), nil);
    helmwatch.on1A4(pointsEntry('Ventures', 'Harvesting', 150));
    helmwatch.on1A4(pointsEntry('Ventures', 'Dynamis', 999));
    check('H13 END commits stream', helmwatch.on1A4(endList), true);
    check('H14 exact label match',  helmwatch.pointsFor('Mining'), 3200);
    check('H15 second category',    helmwatch.pointsFor('Harvesting'), 150);
    check('H16 absent category',    helmwatch.pointsFor('Excavation'), nil);
    check('H17 pointsReady',        helmwatch.pointsReady(), true);

    -- !ventures reply parse -- format PINNED by field capture 2026-07-17:
    --   Mining: (Low) Ordelles Caves, (Mid) Garlaige Citadel [S], (High) Grauberg [S]
    local vg, vl = helmwatch.parseVentureLine(
        'Mining: (Low) Ordelles Caves, (Mid) Garlaige Citadel [S], (High) Grauberg [S]');
    check('H18 venture line category',  vg, 'Mining');
    check('H18b tier count',            vl ~= nil and #vl or 0, 3);
    check('H18c low tier',              vl ~= nil and vl[1], 'Low:  Ordelles Caves');
    check('H18d high tier keeps [S]',   vl ~= nil and vl[3], 'High: Grauberg [S]');
    local dg, dl = helmwatch.parseVentureLine('Harvesting: something the server changed');
    check('H19 drifted format keeps raw tail', dg, 'Harvesting');
    check('H19b drifted tail content',  dl ~= nil and dl[1], 'something the server changed');
    check('H20 party chatter -> nil',   helmwatch.parseVentureLine('do i go to M or go to J?'), nil);
    check('H20b unknown category -> nil', helmwatch.parseVentureLine('Fishing: (Low) Port Windurst'), nil);
    check('H21 control bytes scrubbed', helmwatch.cleanLine('a\1\2b  c\127'), 'a b c');
    check('H22 jst day rollover', helmwatch.jstDay(15 * 3600) - helmwatch.jstDay(0), 1);

    -- Engine overlay: dlac:AutoHelm resolves the manifest helm block -- the
    -- category hat first for Head (semantic map), the generic ladder as the
    -- fallback (another category's hat still carries Surveyor), best-first
    -- level-gated rungs everywhere else. Armor+neck+waist only by design.
    dispatchM._autoOverride = { helm = {
        hats = { Mining = { name = 'Miners Helmet', level = 1, surv = 1 } },
        head = { { name = 'Lumberjacks Beret', score = 10, level = 1, helm = 0, surv = 1 } },
        body = { { name = 'Plain Tunica +1', score = 21, level = 40, helm = 1, surv = 2 },
                 { name = 'Field Tunica',    score = 1,  level = 1,  helm = 1, surv = 0 } },
        neck = { { name = 'Field Torque',    score = 1,  level = 65, helm = 1, surv = 0 } },
    } };
    local hov = dispatchM._helmOverlayFor({ gather = 'Mining', enabled = true, at = 1 },
        { player = { MainJobSync = 75 } });
    check('H23 hat resolves for category',   hov and hov.Head, 'Miners Helmet');
    check('H24 body best rung',              hov and hov.Body, 'Plain Tunica +1');
    check('H25 neck usable at 75',           hov and hov.Neck, 'Field Torque');
    local hov2 = dispatchM._helmOverlayFor({ gather = 'Harvesting', enabled = true },
        { player = { MainJobSync = 75 } });
    check('H26 missing hat -> head ladder',  hov2 and hov2.Head, 'Lumberjacks Beret');
    local hov3 = dispatchM._helmOverlayFor({ gather = 'Mining', enabled = true },
        { player = { MainJobSync = 30 } });
    check('H27 underlevel rung falls through', hov3 and hov3.Body, 'Field Tunica');
    check('H28 underlevel neck -> slot empty', hov3 and hov3.Neck, nil);
    local hoff = dispatchM._helmOverlayFor({ gather = 'Mining', enabled = false },
        { player = { MainJobSync = 75 } });
    check('H29 disabled -> no overlay',      hoff, nil);
    local hnog = dispatchM._helmOverlayFor({ gather = '', enabled = true },
        { player = { MainJobSync = 75 } });
    check('H30 no category -> no overlay',   hnog, nil);
    dispatchM._autoOverride = nil;

    -- rating / preview (helmwatch reads the same manifest shape itself for
    -- the bar display: HELM sum over non-Head picks, >=5 = break-proof)
    helmwatch._setManifest({ helm = {
        hats  = { Mining = { name = 'Miners Helmet', level = 1, surv = 1 } },
        body  = { { name = 'Plain Tunica', score = 11, level = 30, helm = 1, surv = 1 } },
        hands = { { name = 'Field Gloves', score = 1,  level = 1,  helm = 1, surv = 0 } },
        neck  = { { name = 'Field Torque', score = 1,  level = 65, helm = 1, surv = 0 } },
        waist = { { name = 'Field Rope',   score = 1,  level = 65, helm = 1, surv = 0 } },
        legs  = { { name = 'Plain Hose',   score = 11, level = 30, helm = 1, surv = 1 } },
        feet  = { { name = 'Plain Boots',  score = 11, level = 30, helm = 1, surv = 1 } },
    } });
    local pv = helmwatch.preview('Mining', 75);
    check('H31 preview head is the hat',  pv.Head ~= nil and pv.Head.name, 'Miners Helmet');
    check('H32 preview body',             pv.Body ~= nil and pv.Body.name, 'Plain Tunica');
    local hr, hs, hbp = helmwatch.rating('Mining', 75);
    check('H33 rating sums HELM (no head)', hr, 6);
    check('H34 surveyor total',             hs, 4);
    check('H35 break-proof at >= 5',        hbp, true);
    local lr = select(1, helmwatch.rating('Mining', 20));
    check('H36 level gating trims rating',  lr, 1);

    -- Auto HELM (Henrik's split): the detection-armed temporary overlay.
    -- Default off; a Point result while armed opens a hold; the engine wears
    -- the gear only while the hold runs (idle switch stays independent).
    check('H37 auto default off',           helmwatch.isAutoHelm(), false);
    helmwatch.onEventNum(evt, function(i) return 'Logging Point'; end);
    check('H38 unarmed swing -> no hold',   helmwatch.autoActive(), false);
    helmwatch.setAutoHelm(true);
    check('H39 auto arms',                  helmwatch.isAutoHelm(), true);
    helmwatch.onEventNum(evt, function(i) return 'Logging Point'; end);
    check('H40 armed swing opens the hold', helmwatch.autoActive(), true);
    check('H41 armed swing sets category',  helmwatch.getGather(), 'Logging');
    helmwatch.setAutoHelm(false);
    check('H42 disarm ends the hold',       helmwatch.autoActive(), false);

    -- Engine: helmStateActive is the single truth for both ways in.
    local act = dispatchM._helmStateActive;
    check('H43 idle switch active',    act({ gather = 'Mining', enabled = true }), true);
    check('H44 auto + live hold',      act({ gather = 'Mining', enabled = false, auto = true, autoUntil = os.time() + 60 }), true);
    check('H45 auto + expired hold',   act({ gather = 'Mining', enabled = false, auto = true, autoUntil = os.time() - 1 }), false);
    check('H46 auto without hold',     act({ gather = 'Mining', enabled = false, auto = true }), false);
    check('H47 hold without auto',     act({ gather = 'Mining', enabled = false, autoUntil = os.time() + 60 }), false);
    check('H48 no category never active', act({ gather = '', enabled = true, auto = true, autoUntil = os.time() + 60 }), false);
    dispatchM._autoOverride = { helm = {
        body = { { name = 'Field Tunica', score = 1, level = 1, helm = 1, surv = 0 } },
    } };
    local aov = dispatchM._helmOverlayFor(
        { gather = 'Mining', enabled = false, auto = true, autoUntil = os.time() + 60 },
        { player = { MainJobSync = 75 } });
    check('H49 hold resolves the overlay',  aov and aov.Body, 'Field Tunica');
    local aoff = dispatchM._helmOverlayFor(
        { gather = 'Mining', enabled = false, auto = true, autoUntil = os.time() - 1 },
        { player = { MainJobSync = 75 } });
    check('H50 expired hold -> no overlay', aoff, nil);
    dispatchM._autoOverride = nil;

    -- Proximity hold via the CENTRAL entity watcher (entwatch migration --
    -- was the targeting anchor): Auto HELM tracks the four "* Point" names
    -- itself, so ANY point within range holds the gear on -- no targeting.
    -- The probe is the watcher seam: nearest('<Cat> Point') -> yalms | nil.
    local world = { points = {} };   -- ['Mining Point'] = nearest dist (yalms)
    local probe = { nearest = function(nm) return world.points[nm]; end };
    helmwatch.setAutoHelm(true);
    helmwatch.setProxRange(6);   -- pin the 6y/8y geometry for H51-H64
    world.points['Mining Point'] = 5;
    check('H51 point in range holds, no target', helmwatch.proximityStep(probe), true);
    check('H52 hold equips (live)',            helmwatch.autoActive(), true);
    check('H53 nearest point selects category', helmwatch.getGather(), 'Mining');
    world.points['Mining Point'] = 7;              -- inside the 8y leash
    check('H54 leash keeps the active category', helmwatch.proximityStep(probe), true);
    world.points['Mining Point'] = 10;             -- walked away
    check('H55 out of leash drops the hold',   helmwatch.proximityStep(probe), false);
    world.points['Mining Point'] = 5;              -- wandered back
    check('H56 re-acquires without any target', helmwatch.proximityStep(probe), true);
    world.points['Mining Point'] = nil;            -- mined out (despawn)...
    world.points['Logging Point'] = 1;             -- ...stacked twin on the spot
    check('H57 stacked spawn: hold survives',  helmwatch.proximityStep(probe), true);
    check('H58 and follows what is there',     helmwatch.getGather(), 'Logging');
    world.points['Logging Point'] = nil;
    world.points['Harvesting Point'] = 7;          -- leash range, but a SWITCH
    check('H59 category switch needs enter range', helmwatch.proximityStep(probe), false);
    world.points['Harvesting Point'] = nil;
    -- the swing result stays the category authority + latches the hold
    helmwatch.onEventNum(evt, function(i) return (i == 319) and 'Logging Point' or nil; end);
    check('H60 swing result opens the hold',   helmwatch.autoActive(), true);
    check('H61 swing result picks category',   helmwatch.getGather(), 'Logging');
    world.points['Logging Point'] = 7;             -- sweep caught up: leash applies
    check('H62 post-swing leash holds',        helmwatch.proximityStep(probe), true);
    world.points['Logging Point'] = nil;
    check('H63 all points gone -> hold drops', helmwatch.proximityStep(probe), false);
    helmwatch.setAutoHelm(false);
    world.points['Mining Point'] = 5;
    check('H64 disarmed: never holds',         helmwatch.proximityStep(probe), false);

    -- A category can render under MORE THAN ONE client name. Excavation is
    -- the live case: the client shows "Excav. Point" (Arrapago Reef,
    -- 2026-08-06) where the server's npc_list says "Excavation Point", and
    -- the exact-name watcher saw neither because we only ever asked for the
    -- server spelling. Auto HELM was blind to excavation entirely.
    check('H64a excavation carries both client names', #helmwatch.pointNames('Excavation'), 2);
    check('H64a2 the other three stay single-named',   #helmwatch.pointNames('Mining'), 1);
    check('H64a3 unknown category falls back to the convention',
                                               helmwatch.pointNames('Clamming')[1], 'Clamming Point');
    helmwatch.setAutoHelm(true);
    world.points = { ['Excav. Point'] = 4 };
    check('H64b abbreviated client name acquires', helmwatch.proximityStep(probe), true);
    check('H64c and selects Excavation',           helmwatch.getGather(), 'Excavation');
    world.points = {};
    check('H64d gone -> hold drops',               helmwatch.proximityStep(probe), false);
    world.points = { ['Excavation Point'] = 4 };   -- a zone that spells it out
    check('H64e full spelling acquires too',       helmwatch.proximityStep(probe), true);
    world.points = {};
    helmwatch.proximityStep(probe);                -- drop the hold: force a FRESH acquire
    -- Both spellings loaded at once: the NEAREST of a category's names
    -- answers, so a distant twin can never mask a point inside enter range
    -- (7.5 is past the 6y enter gate; only the 3y match can acquire here).
    world.points = { ['Excavation Point'] = 7.5, ['Excav. Point'] = 3 };
    check('H64f nearest across the category names wins', helmwatch.proximityStep(probe), true);
    world.points = {};
    helmwatch.setAutoHelm(false);

    -- Configurable detect range (Henrik: default 10 for macro-spam-at-range
    -- and lag; panel setting clamped 3..20, keep-wearing leash = range+2).
    check('H70 default range is 10',        helmwatch.PROX_DEFAULT, 10);
    helmwatch.setProxRange(25);
    check('H71 clamps high to 20',          helmwatch.proxEnter(), 20);
    helmwatch.setProxRange(1);
    check('H72 clamps low to 3',            helmwatch.proxEnter(), 3);
    helmwatch.setProxRange(10);
    helmwatch.setAutoHelm(true);
    world.points = { ['Harvesting Point'] = 9 };   -- outside 6, inside 10
    check('H73 wider range acquires at 9y', helmwatch.proximityStep(probe), true);
    world.points['Harvesting Point'] = 11.9;       -- just inside the 12y leash
    check('H74 leash follows range (+2y)',  helmwatch.proximityStep(probe), true);
    world.points['Harvesting Point'] = 12.1;       -- just past it
    check('H75 past the leash drops',       helmwatch.proximityStep(probe), false);
    helmwatch.setAutoHelm(false);

    -- Combat gate (v61): "Default" is NOT "idle" -- HandleDefault runs every
    -- frame including combat, so the overlay itself must stand aside while
    -- Engaged/Dead. 'Event' stays dressed (the swing animation is an event).
    dispatchM._autoOverride = { helm = {
        body = { { name = 'Field Tunica', score = 1, level = 1, helm = 1, surv = 0 } },
    } };
    local hsOn = { gather = 'Mining', enabled = true };
    local function stCtx(st) return { player = { MainJobSync = 75, Status = st } }; end
    check('H65 engaged -> overlay stands aside', dispatchM._helmOverlayFor(hsOn, stCtx('Engaged')), nil);
    check('H66 dead -> stands aside', dispatchM._helmOverlayFor(hsOn, stCtx('Dead')), nil);
    local hIdle = dispatchM._helmOverlayFor(hsOn, stCtx('Idle'));
    check('H67 idle -> dressed',      hIdle and hIdle.Body, 'Field Tunica');
    local hEvt = dispatchM._helmOverlayFor(hsOn, stCtx('Event'));
    check('H68 event -> stays dressed (no per-swing churn)', hEvt and hEvt.Body, 'Field Tunica');
    local hNoP = dispatchM._helmOverlayFor(hsOn, { player = nil });
    check('H69 unreadable status -> dressed (idle assumption)', hNoP and hNoP.Body, 'Field Tunica');
    dispatchM._autoOverride = nil;
end)();

-- ---------------------------------------------------------------------------
-- GD. shipped conditional-effects data pins (data\gearsets.lua +
--     data\latentstats.lua) -- regeneration guards, the smoke_ui S21 style.
--     Shapes verified against the server source 2026-07-17 (design Appendix C).
-- ---------------------------------------------------------------------------
(function()
    local gsD = dofile('data/gearsets.lua');
    local nSets, nFlat, nTiered = 0, 0, 0;
    local census = {};
    local tierKeysOk, piecesOk = true, true;
    for _, e in pairs(gsD) do
        nSets = nSets + 1;
        local tn = 0;
        for c in pairs(e.tiers) do
            tn = tn + 1;
            if c < e.min or c > e.max then tierKeysOk = false; end
        end
        if tn == 1 then nFlat = nFlat + 1; else nTiered = nTiered + 1; end
        census[e.min .. '/' .. e.max] = (census[e.min .. '/' .. e.max] or 0) + 1;
        for _, pid in ipairs(e.pieces) do
            if type(pid) ~= 'number' or pid <= 0 then piecesOk = false; end
        end
    end
    check('GD1 126 gear sets ship', nSets, 126);
    check('GD2 flat/tiered split', nFlat .. '/' .. nTiered, '39/87');
    check('GD3 min/max shape census', (census['2/2'] or 0) .. ',' .. (census['2/4'] or 0) .. ','
        .. (census['2/5'] or 0) .. ',' .. (census['5/5'] or 0), '20,1,86,19');
    check('GD4 every tier key within [min,max]', tierKeysOk, true);
    check('GD5 every piece id is a positive number', piecesOk, true);
    local s70 = gsD[70];   -- Lava's + Kusha's, THE reference set
    check('GD6 [70] pieces', s70 ~= nil and (s70.pieces[1] .. ',' .. s70.pieces[2]), '15850,15851');
    check('GD7 [70] min/max', s70 ~= nil and (s70.min .. '/' .. s70.max), '2/2');
    check('GD8 [70] tier values', s70 ~= nil and (s70.tiers[2].Attack .. ',' .. s70.tiers[2].Accuracy
        .. ',' .. s70.tiers[2].DEF), '6,12,6');
    local s43 = gsD[43];   -- Paramount: alternates -- MORE pieces than the cap
    check('GD9 [43] alternate-piece shape (9 pieces, min2/max2)',
        s43 ~= nil and (#s43.pieces .. '/' .. s43.min .. '/' .. s43.max), '9/2/2');

    local lsD = dofile('data/latentstats.lua');
    local rows, items, levelLeak = 0, 0, false;
    for _, rr in pairs(lsD) do
        items = items + 1;
        for _, r in ipairs(rr) do
            rows = rows + 1;
            -- latent 50/51 rows belong to levelscaling.lua, NEVER here (the
            -- routing boundary -- gen_levelscaling.py's old latent-52 bug class)
            if r.cond == 'JOB_LEVEL_ABOVE' or r.cond == 'JOB_LEVEL_BELOW' then levelLeak = true; end
        end
    end
    -- windows re-pinned 2026-07-19: generator now unions the live API's per-item
    -- latents (tools/api_cache) with the repo SQL -- live-only content (the CEXI
    -- "+1" leveling line, Malphas set, ...) added ~470 rows.
    check('GD10 latentstats rows in range', rows >= 2100 and rows <= 2500, true);
    check('GD11 latentstats items in range', items >= 850 and items <= 980, true);
    check('GD12 zero level-latent rows leaked', levelLeak, false);
    local spot = lsD[11312];
    check('GD13 spot row 11312 (STR +5 while TP > 100)', spot ~= nil
        and (spot[1].stat .. '/' .. spot[1].add .. '/' .. spot[1].cond .. '/' .. spot[1].param),
        'STR/5/TP_OVER/100');
end)();

-- ---------------------------------------------------------------------------
-- GE. geareffects -- the pure set-bonus evaluator (conditional-effects P1).
--     Semantics pinned to the server applier: value-at-count replacement tiers,
--     tiers[min(count,max)] with nil below min, per-SLOT counting (duplicates
--     twice), and the level gate (a piece above ctx.level stops counting while
--     its stats still sum).
-- ---------------------------------------------------------------------------
(function()
    local gfe = dofile('gear/geareffects.lua');
    gfe.configure({ gearsets = {
        [1] = { pieces = { 1001, 1002 }, min = 2, max = 2,          -- the Lava/Kusha shape
                tiers = { [2] = { Attack = 6, Accuracy = 12, DEF = 6 } } },
        [2] = { pieces = { 1101, 1102, 1103, 1104, 1105 }, min = 2, max = 5,   -- Iron Ram shape
                tiers = { [2] = { FireMagicEva = 5 }, [3] = { FireMagicEva = 10 },
                          [4] = { FireMagicEva = 15 }, [5] = { FireMagicEva = 30 } } },
        [3] = { pieces = { 1201, 1202, 1203, 1204, 1205, 1206, 1207, 1208, 1209 },
                min = 2, max = 2, tiers = { [2] = { STR = 3 } } },  -- alternates (any 2 of 9)
        [4] = { pieces = { 1001, 1301 }, min = 2, max = 2,          -- 1001 is in TWO sets
                tiers = { [2] = { VIT = 2 } } },
        [5] = { pieces = { 1401, 1402, 1403, 1404, 1405 }, min = 5, max = 5,   -- the min-5 JSE shape
                tiers = { [5] = { Haste = 5 } } },
    } });
    local so = gfe.setsOf(1001);
    check('GE1 multi-set membership, sorted', so ~= nil and (#so .. ':' .. so[1] .. ',' .. so[2]), '2:1,4');
    check('GE2 non-member items return nil (zero-alloc)', gfe.setsOf(9999), nil);
    check('GE3 below min -> no tier', gfe.setTier(1, 1), nil);
    check('GE4 tier at count', gfe.setTier(1, 2).Accuracy, 12);
    check('GE5 count clamps at max', gfe.setTier(1, 5).Accuracy, 12);
    check('GE6 tier value is the TOTAL at that count (replacement)', gfe.setTier(2, 3).FireMagicEva, 10);

    local lava  = { Id = 1001, Name = 'Lava Ring',  Level = 30, Stats = { Accuracy = 5 } };
    local kusha = { Id = 1002, Name = 'Kusha Ring', Level = 30, Stats = { Attack = 2 } };
    local res = gfe.comboStats({ Ring1 = lava, Ring2 = kusha }, { level = 75 });
    check('GE7 combo folds item stats + bonus (Accuracy)', res.stats.Accuracy, 17);
    check('GE8 combo folds item stats + bonus (Attack)', res.stats.Attack, 8);
    check('GE9 bonus-only stat appears', res.stats.DEF, 6);
    local sb1, sb4;
    for _, sb in ipairs(res.setBonuses) do
        if sb.setId == 1 then sb1 = sb; end
        if sb.setId == 4 then sb4 = sb; end
    end
    check('GE10 active bonus row (count/tier/active)',
        sb1 ~= nil and (sb1.count .. '/' .. sb1.tier .. '/' .. tostring(sb1.active)), '2/2/true');
    check('GE11 partial set listed inactive (the "one more piece" row)',
        sb4 ~= nil and (sb4.count .. '/' .. tostring(sb4.active)), '1/false');

    -- per-SLOT counting: the SAME record in both ring slots counts twice
    local dup = gfe.comboStats({ Ring1 = lava, Ring2 = lava }, { level = 75 });
    local dupRow;
    for _, sb in ipairs(dup.setBonuses) do if sb.setId == 1 then dupRow = sb; end end
    check('GE12 duplicates count per slot (server-verified)',
        dupRow ~= nil and (dupRow.count .. '/' .. tostring(dupRow.active)), '2/true');

    -- level gate: an over-level piece stops COUNTING; its stats still sum
    local high = { Id = 1002, Name = 'Kusha Ring', Level = 70, Stats = { Attack = 2 } };
    local sync = gfe.comboStats({ Ring1 = lava, Ring2 = high }, { level = 50 });
    local syncRow;
    for _, sb in ipairs(sync.setBonuses) do if sb.setId == 1 then syncRow = sb; end end
    check('GE13 level-sync gate strips the count', syncRow ~= nil and syncRow.count, 1);
    check('GE14 ...but never the item stats', sync.stats.Attack, 2);
    local nilctx = gfe.comboStats({ Ring1 = lava, Ring2 = high }, nil);
    local nilRow;
    for _, sb in ipairs(nilctx.setBonuses) do if sb.setId == 1 then nilRow = sb; end end
    check('GE15 nil ctx -> no gate', nilRow ~= nil and nilRow.count, 2);

    -- alternates activate on ANY two pieces -- weapon+weapon included
    local alt = gfe.comboStats({
        Main = { Id = 1201, Name = 'Alt A', Level = 1, Stats = {} },
        Sub  = { Id = 1205, Name = 'Alt B', Level = 1, Stats = {} },
    }, { level = 75 });
    local altRow;
    for _, sb in ipairs(alt.setBonuses) do if sb.setId == 3 then altRow = sb; end end
    check('GE16 alternates: any 2 of 9 activates', altRow ~= nil and tostring(altRow.active) .. '/'
        .. tostring(alt.stats.STR), 'true/3');

    -- itemStats stays the zero-copy levelstats passthrough
    local plain = { Name = 'Plain Ring', Level = 1, Stats = { MND = 2 } };
    check('GE17 itemStats zero-copy passthrough', gfe.itemStats(plain, { level = 75 }) == plain.Stats, true);

    -- THE threshold rule (Henrik, 2026-07-18): below a set's minimum the bonus
    -- does not exist AT ALL -- no halves, no per-piece fractions. A min-5 set at
    -- four pieces grants nothing anywhere (display marks it inactive; totals and
    -- the optimizer see zero).
    check('GE19 min-5 set at 4 pieces: no tier at all', gfe.setTier(5, 4), nil);
    local function jse(n)
        local comp = {};
        for i = 1, n do
            comp['S' .. i] = { Id = 1400 + i, Name = 'JSE ' .. i, Level = 30, Stats = {} };
        end
        return gfe.comboStats(comp, { level = 75 });
    end
    local four, five = jse(4), jse(5);
    local fourRow, fiveRow;
    for _, sb in ipairs(four.setBonuses) do if sb.setId == 5 then fourRow = sb; end end
    for _, sb in ipairs(five.setBonuses) do if sb.setId == 5 then fiveRow = sb; end end
    check('GE20 four of five: zero bonus in totals, row inactive',
        tostring(four.stats.Haste) .. '/' .. tostring(fourRow ~= nil and fourRow.active), 'nil/false');
    check('GE21 all five: the full bonus, whole', five.stats.Haste .. '/' .. tostring(fiveRow.active), '5/true');

    -- augment fold (ctx.augStats = { itemId -> deltas }): the caller's private
    -- augments ride THE evaluator, so Set totals, the weighted score, and every
    -- future consumer read identical numbers (Henrik's field case: Refresh+1
    -- body native + Refresh+1 legs augment showed "+1" in Set totals while the
    -- score already counted +2).
    local body = { Id = 2001, Name = 'Refresh Body', Level = 40, Stats = { Refresh = 1 } };
    local legs = { Id = 2002, Name = 'Plain Legs',   Level = 40, Stats = {} };
    local augd = gfe.comboStats({ Body = body, Legs = legs },
        { level = 75, augStats = { [2002] = { Refresh = 1, Note = 'hq' } } });
    check('GE22 augStats folds private augment deltas (base+aug)', augd.stats.Refresh, 2);
    check('GE23 non-numeric augment values never leak into totals', augd.stats.Note, nil);
    local noaug = gfe.comboStats({ Body = body, Legs = legs }, { level = 75 });
    check('GE24 no augStats -> base only (back-compat)', noaug.stats.Refresh, 1);
    -- per-SLOT like everything else: the same augmented ring worn twice folds twice
    local dupA = gfe.comboStats({ Ring1 = lava, Ring2 = lava },
        { level = 75, augStats = { [1001] = { Accuracy = 3 } } });
    check('GE25 augment deltas count per SLOT (5+5 base, 12 set, 3+3 aug)', dupA.stats.Accuracy, 28);

    -- the REAL shipped data end-to-end: worn Lava's + Kusha's (ids 15850/15851)
    local gfe2 = dofile('gear/geareffects.lua');
    gfe2.configure({ gearsets = dofile('data/gearsets.lua') });
    local worn = gfe2.comboStats({
        Ring1 = { Id = 15850, Name = "Lava's Ring",  Level = 30, Stats = {} },
        Ring2 = { Id = 15851, Name = "Kusha's Ring", Level = 30, Stats = {} },
    }, { level = 75 });
    check('GE18 shipped data: Lava+Kusha bonus', (worn.stats.Attack or 0) .. '/'
        .. (worn.stats.Accuracy or 0) .. '/' .. (worn.stats.DEF or 0), '6/12/6');
end)();

-- ---------------------------------------------------------------------------
-- HB. optimizePicks gear-set crediting (conditional-effects P3, ADR 0011):
--     the bonus term inside the capped objective, incremental per-slot counts,
--     and the set-seeded restarts that find pairs single-slot climbing cannot.
-- ---------------------------------------------------------------------------
(function()
    -- synthetic effects seam (no geareffects needed: optimizePicks only sees fns)
    local SETS = {
        [1] = { pieces = { 101, 102 }, min = 2, max = 2, tiers = { [2] = { Accuracy = 12 } } },
        [2] = { pieces = { 201, 202, 203, 204, 205 }, min = 2, max = 5,
                tiers = { [2] = { Accuracy = 4 }, [3] = { Accuracy = 6 },
                          [4] = { Accuracy = 6 }, [5] = { Accuracy = 30 } } },
        [3] = { pieces = { 301, 302 }, min = 2, max = 2, tiers = { [2] = { Haste = 5 } } },
    };
    local BYITEM = {};
    for sid, e in pairs(SETS) do
        for _, pid in ipairs(e.pieces) do
            BYITEM[pid] = BYITEM[pid] or {};
            table.insert(BYITEM[pid], sid);
        end
    end
    local fx = {
        setsOf  = function(id) return BYITEM[id]; end,
        setTier = function(sid, c)
            local e = SETS[sid];
            if e == nil or c < e.min then return nil; end
            return e.tiers[math.min(c, e.max)];
        end,
    };
    local W3 = { Accuracy = { perUnit = 3 } };
    local function mk(id, name, stats) return { stats = stats, ref = { Id = id, Name = name } }; end

    -- HB1: the numeric objective pin (H3-style): both set rings placed, bonus in
    local p1, p2 = mk(101, 'SetRing A', { Accuracy = 2 }), mk(102, 'SetRing B', { Accuracy = 2 });
    local hb1 = optim.optimizePicks({ Ring1 = { p1 }, Ring2 = { p2 } }, W3, { effects = fx });
    check('HB1 bonus inside the objective', hb1.total, 3 * (2 + 2 + 12));

    -- HB2: pair discovery -- each piece is a solo LOSS vs its rival; only a
    -- seeded restart can enter the bonus
    local z1, z2 = mk(101, 'SetRing A', { Accuracy = 0 }), mk(102, 'SetRing B', { Accuracy = 0 });
    local rvA, rvB = mk(901, 'Rival A', { Accuracy = 5 }), mk(902, 'Rival B', { Accuracy = 5 });
    local hb2 = optim.optimizePicks({ Ring1 = { rvA, z1 }, Ring2 = { rvB, z2 } }, W3,
        { effects = fx, conflict = function(a, b) return a == b; end });
    check('HB2 seeded restart finds the pair', hb2.total, 3 * 12);
    check('HB2b ...both set pieces picked', tostring(hb2.picks.Ring1) .. ',' .. tostring(hb2.picks.Ring2), '2,2');

    -- HB3: a bonus that exactly offsets stays EMPTY (strict improvement + the
    -- EMPTY tie preference survive the bonus term); partner via baseComposition
    local neg = mk(101, 'SetRing A', { Accuracy = -12 });
    local hb3 = optim.optimizePicks({ Ring1 = { neg } }, W3,
        { effects = { setsOf = fx.setsOf, setTier = fx.setTier,
                      baseComposition = { { Id = 102, Name = 'SetRing B' } } } });
    check('HB3 exact offset keeps EMPTY', hb3.picks.Ring1, nil);

    -- HB4: one owned copy -- the conflict beats the set (count stays 1, no bonus)
    local cA, cB = mk(101, 'SetRing A', { Accuracy = 2 }), mk(101, 'SetRing A', { Accuracy = 2 });
    local oneCopy = function(a, b)
        if a == b or (a.Id ~= nil and a.Id == b.Id) then return true; end
        return false;
    end
    local hb4 = optim.optimizePicks({ Ring1 = { cA }, Ring2 = { cB } }, W3,
        { effects = fx, conflict = oneCopy });
    local filled4 = (hb4.picks.Ring1 and 1 or 0) + (hb4.picks.Ring2 and 1 or 0);
    check('HB4 conflict beats set: one slot, no bonus', filled4 .. '/' .. hb4.total, '1/' .. (3 * 2));
    -- HB4b: two owned copies -- per-slot counting credits the SAME item twice
    local hb4b = optim.optimizePicks({ Ring1 = { cA }, Ring2 = { cB } }, W3,
        { effects = fx, conflict = function() return false; end });
    check('HB4b two copies activate the set', hb4b.total, 3 * (2 + 2 + 12));

    -- HB5: seed eviction + monotone acceptance -- a dominated set dissolves back
    local i1, i2 = mk(911, 'Indep A', { Accuracy = 10 }), mk(912, 'Indep B', { Accuracy = 10 });
    local w1, w2 = mk(101, 'SetRing A', { Accuracy = 1 }), mk(102, 'SetRing B', { Accuracy = 1 });
    local hb5 = optim.optimizePicks({ Ring1 = { i1, w1 }, Ring2 = { i2, w2 } }, W3,
        { effects = { setsOf = fx.setsOf,
                      setTier = function(sid, c) return (sid == 1 and c >= 2) and { Accuracy = 5 } or nil; end },
          conflict = function(a, b) return a == b; end });
    check('HB5 dominated seed dissolves to the baseline', hb5.total, 3 * 20);
    check('HB5b independents kept', tostring(hb5.picks.Ring1) .. ',' .. tostring(hb5.picks.Ring2), '1,1');

    -- HB6: cap sharing -- a bonus above the cap adds nothing, so a cap-redundant
    -- set stays home (H5's analog through the bonus fold)
    local WH = { Haste = { perUnit = 100, cap = 5 } };
    local hHat = mk(920, 'Haste Hat', { Haste = 5 });
    local s1, s2 = mk(301, 'SetPiece A', { Haste = 0 }), mk(302, 'SetPiece B', { Haste = 0 });
    local hb6 = optim.optimizePicks({ Head = { hHat }, Ring1 = { s1 }, Ring2 = { s2 } }, WH, { effects = fx });
    check('HB6 capped bonus stays home', tostring(hb6.picks.Ring1) .. '/' .. hb6.total, 'nil/500');

    -- HB7: effects present but nothing set-carrying -> bit-identical totals
    local W = { Haste = { perUnit = 100, cap = 5 }, SwordSkill = { perUnit = 2 }, Accuracy = { perUnit = 3 } };
    local hasteHat  = { stats = { Haste = 5 },                               ref = 'HasteHat'  };
    local statHat   = { stats = { Accuracy = 5 },                            ref = 'StatHat'   };
    local greatFeet = { stats = { Haste = 5, SwordSkill = 7, Accuracy = 5 }, ref = 'GreatFeet' };
    local weakFeet  = { stats = { Accuracy = 2 },                            ref = 'WeakFeet'  };
    local hb7 = optim.optimizePicks({ Head = { hasteHat, statHat }, Feet = { greatFeet, weakFeet } }, W,
        { effects = fx });
    check('HB7 no set-carrying candidate: H3 total bit-identical', hb7.total, 100 * 5 + 2 * 7 + 3 * (5 + 5));

    -- HB8: tiered marginal -- 3 pieces credit tiers[3], the 4th enters only when
    -- its tier step pays (tiers[4]-tiers[3] = 0 here -> stays home)
    local t1, t2, t3 = mk(201, 'Tier A', { Accuracy = 1 }), mk(202, 'Tier B', { Accuracy = 1 }),
                       mk(203, 'Tier C', { Accuracy = 1 });
    local t4 = mk(204, 'Tier D', { Accuracy = 0 });
    local hb8 = optim.optimizePicks({ Ring1 = { t1 }, Ring2 = { t2 }, Neck = { t3 }, Head = { t4 } },
        W3, { effects = fx });
    check('HB8 three pieces credit tiers[3]', hb8.total, 3 * (3 + 6));
    check('HB8b zero-step 4th piece stays home', hb8.picks.Head, nil);
    -- ...and a PAYING tier step pulls the 4th piece in (private tier fn: step +14)
    local fx4 = { setsOf = fx.setsOf, setTier = function(sid, c)
        if sid ~= 2 or c < 2 then return nil; end
        return ({ [2] = { Accuracy = 4 }, [3] = { Accuracy = 6 }, [4] = { Accuracy = 20 } })[math.min(c, 4)];
    end };
    local hb8c = optim.optimizePicks({ Ring1 = { t1 }, Ring2 = { t2 }, Neck = { t3 }, Head = { t4 } },
        W3, { effects = fx4 });
    check('HB8c paying tier step pulls the 4th piece', hb8c.picks.Head ~= nil and hb8c.total, 3 * (3 + 20));

    -- HB9: baseComposition partner -- a lone worthless pool piece is credited
    -- the bonus its already-chosen partner completes (the Sub marginal case)
    local lone = mk(101, 'SetRing A', { Accuracy = 0 });
    local hb9 = optim.optimizePicks({ Ring1 = { lone } }, W3,
        { effects = { setsOf = fx.setsOf, setTier = fx.setTier,
                      baseComposition = { { Id = 102, Name = 'SetRing B' } } } });
    check('HB9 baseComposition partner credits the bonus',
        tostring(hb9.picks.Ring1) .. '/' .. hb9.total, '1/' .. (3 * 12));
end)();

-- ---------------------------------------------------------------------------
-- HR. optimizePicks RESERVED SLOTS (RSlot, 2026-07-31). Henrik's field case:
--     under MP + Refresh weights the builder chose Royal Cloak (MP+20,
--     Refresh+1) over Dalmatica -- because the Head the Cloak EATS was still
--     being counted alongside it. A reserving piece must be weighed against the
--     rival PLUS the slot the rival lets you keep.
--
--     Bits are the server's rslot mask (arbiter.RSLOT_ORDER): Head = 0x10,
--     Ammo = 0x08, Hands|Legs|Feet = 0x1C0.
-- ---------------------------------------------------------------------------
(function()
    local reserves = function(ref) return ref.RSlot; end
    -- Refresh is what you are really buying; MP is the tiebreak trickle.
    local WR = { Refresh = { perUnit = 100 }, MP = { perUnit = 1 } };
    local royal = { stats = { MP = 20, Refresh = 1 }, ref = { Id = 13749, Name = 'Royal Cloak', RSlot = 16 } };
    local dalma = { stats = { Refresh = 1 },          ref = { Id = 13787, Name = 'Dalmatica' } };
    local rHat  = { stats = { Refresh = 1 },          ref = { Id = 1,     Name = 'Refresh Hat' } };

    -- HR1: THE field case. Cloak alone = 120; Dalmatica + hat = 200.
    local hr1 = optim.optimizePicks({ Body = { royal, dalma }, Head = { rHat } }, WR,
        { reserves = reserves });
    check('HR1 the head it eats is counted against it', hr1.total, 200);
    check('HR1b Dalmatica takes Body', hr1.picks.Body, 2);
    check('HR1c the head is worn', hr1.picks.Head, 1);
    check('HR1d nothing reserved', hr1.reserved, nil);

    -- HR2: the same solve WITHOUT opts.reserves -- the pre-fix answer, pinned so
    -- the feature stays opt-in and structurally zero (the opts.effects rule).
    local hr2 = optim.optimizePicks({ Body = { royal, dalma }, Head = { rHat } }, WR);
    check('HR2 reservation-blind without the lookup', hr2.total, 220);

    -- HR3: when the Cloak really is better, it wins and the slot goes EMPTY --
    -- and names its reserver back to the caller.
    local weakHat = { stats = { MP = 5 }, ref = { Id = 2, Name = 'Weak Hat' } };
    local hr3 = optim.optimizePicks({ Body = { royal, dalma }, Head = { weakHat } }, WR,
        { reserves = reserves });
    check('HR3 the Cloak wins on its own merit', hr3.total, 120);
    check('HR3b Royal Cloak takes Body', hr3.picks.Body, 1);
    check('HR3c the reserved slot stays empty', hr3.picks.Head, nil);
    check('HR3d ...and names who took it', hr3.reserved and hr3.reserved.Head and hr3.reserved.Head.Name,
          'Royal Cloak');

    -- HR4: a mask naming a slot this solve is not filling costs NOTHING (the
    -- build-slot grid unchecked Head: the Cloak is free again).
    local hr4 = optim.optimizePicks({ Body = { royal, dalma } }, WR, { reserves = reserves });
    check('HR4 unbuilt slot is not a loss', hr4.total .. '/' .. tostring(hr4.picks.Body), '120/1');

    -- HR5: EXACT tie -- the no-reserver regime runs first, so a tie keeps the
    -- fuller set instead of eating a slot for nothing.
    local WM = { MP = { perUnit = 1 } };
    local tRoyal = { stats = { MP = 100 }, ref = { Id = 3, Name = 'Tie Cloak', RSlot = 16 } };
    local tBody  = { stats = { MP = 60 },  ref = { Id = 4, Name = 'Tie Body' } };
    local tHat   = { stats = { MP = 40 },  ref = { Id = 5, Name = 'Tie Hat' } };
    local hr5 = optim.optimizePicks({ Body = { tRoyal, tBody }, Head = { tHat } }, WM,
        { reserves = reserves });
    check('HR5 a tie fills the slot rather than eating it',
          hr5.total .. '/' .. tostring(hr5.picks.Body) .. '/' .. tostring(hr5.picks.Head), '100/2/1');

    -- HR6: the OTHER direction -- 'Ammo' sorts before 'Range', so the reserved
    -- slot is already filled when the reserver is first probed. A boomerang
    -- reserves Ammo (0x08); bow + arrow = 35 beats the boomerang's 30.
    local WA = { Accuracy = { perUnit = 1 } };
    local boom  = { stats = { Accuracy = 30 }, ref = { Id = 6, Name = 'Boomerang', RSlot = 8 } };
    local bow   = { stats = { Accuracy = 10 }, ref = { Id = 7, Name = 'Bow' } };
    local arrow = { stats = { Accuracy = 25 }, ref = { Id = 8, Name = 'Arrow' } };
    local hr6 = optim.optimizePicks({ Range = { boom, bow }, Ammo = { arrow } }, WA,
        { reserves = reserves });
    check('HR6 Range reserving Ammo pays for it', hr6.total, 35);
    check('HR6b the bow takes Range', hr6.picks.Range, 2);
    -- ...and with a worthless arrow the boomerang wins and Ammo goes empty
    local pebble = { stats = { Accuracy = 5 }, ref = { Id = 9, Name = 'Pebble' } };
    local hr6c = optim.optimizePicks({ Range = { boom, bow }, Ammo = { pebble } }, WA,
        { reserves = reserves });
    check('HR6c boomerang wins, Ammo emptied',
          hr6c.total .. '/' .. tostring(hr6c.picks.Ammo) .. '/'
          .. tostring(hr6c.reserved and hr6c.reserved.Ammo and hr6c.reserved.Ammo.Name), '30/nil/Boomerang');

    -- HR7: a multi-bit mask (a suit: Hands|Legs|Feet = 0x1C0) empties all three.
    local suit = { stats = { Accuracy = 50 }, ref = { Id = 10, Name = 'Kupo Suit', RSlot = 448 } };
    local plain = { stats = { Accuracy = 1 }, ref = { Id = 11, Name = 'Plain Body' } };
    local bit   = function(a) return { stats = { Accuracy = a }, ref = { Id = 12 + a, Name = 'P' .. a } }; end
    local hr7 = optim.optimizePicks(
        { Body = { suit, plain }, Hands = { bit(2) }, Legs = { bit(3) }, Feet = { bit(4) } }, WA,
        { reserves = reserves });
    check('HR7 the suit beats body+hands+legs+feet', hr7.total, 50);
    check('HR7b all three slots emptied',
          tostring(hr7.picks.Hands) .. tostring(hr7.picks.Legs) .. tostring(hr7.picks.Feet), 'nilnilnil');
    check('HR7c all three named', (hr7.reserved.Hands.Name == 'Kupo Suit')
          and (hr7.reserved.Legs.Name == 'Kupo Suit') and (hr7.reserved.Feet.Name == 'Kupo Suit'), true);
    -- ...and one point more spread across them and the suit stays home
    local hr7d = optim.optimizePicks(
        { Body = { suit, plain }, Hands = { bit(20) }, Legs = { bit(20) }, Feet = { bit(20) } }, WA,
        { reserves = reserves });
    check('HR7d the three slots out-earn the suit', hr7d.total .. '/' .. tostring(hr7d.picks.Body), '61/2');

    -- HR8: a set bonus can never be completed THROUGH a slot the set's own piece
    -- reserves away -- the seeded restarts must not fake the pair into existence.
    local fx7 = {
        setsOf  = function(id) return (id == 701 or id == 702) and { 7 } or nil; end,
        setTier = function(sid, c) return (sid == 7 and c >= 2) and { Accuracy = 100 } or nil; end,
    };
    local setCloak = { stats = { Accuracy = 0 }, ref = { Id = 701, Name = 'Set Cloak', RSlot = 16 } };
    local setHat   = { stats = { Accuracy = 0 }, ref = { Id = 702, Name = 'Set Hat' } };
    local hr8 = optim.optimizePicks(
        { Body = { setCloak, { stats = { Accuracy = 5 }, ref = { Id = 703, Name = 'Plain Body' } } },
          Head = { setHat,   { stats = { Accuracy = 6 }, ref = { Id = 704, Name = 'Plain Hat' } } } },
        WA, { reserves = reserves, effects = fx7 });
    check('HR8 a reserved-away slot cannot complete a set', hr8.total, 11);
    check('HR8b ...so both plain pieces are worn',
          tostring(hr8.picks.Body) .. ',' .. tostring(hr8.picks.Head), '2,2');
end)();

-- ---------------------------------------------------------------------------
-- HB10+. buildBestSet through a geareffects-wired gearoptim instance: the
--        append-only pool augmentation + seeding, end to end -- and the greedy
--        Range/Ammo path staying set-blind (a bonus never legalizes a pairing).
-- ---------------------------------------------------------------------------
(function()
    local savedGfx = package.loaded['dlac\\gear\\geareffects'];
    local savedGear = package.loaded['dlac\\gear'];
    local gfe = dofile('gear/geareffects.lua');
    gfe.configure({ gearsets = {
        [7] = { pieces = { 610, 611 }, min = 2, max = 2, tiers = { [2] = { Accuracy = 50 } } },
        [8] = { pieces = { 601, 602 }, min = 2, max = 2, tiers = { [2] = { Accuracy = 99 } } },
    } });
    package.loaded['dlac\\gear\\geareffects'] = gfe;

    -- 21 Head fillers rank ABOVE the set piece, pushing it past the top-20
    -- prune: only the augmentation can put it in front of the optimizer.
    local G2 = { NameToObject = {}, Head = {}, Neck = {} };
    for i = 1, 21 do
        G2.Head['Filler ' .. i] = { Name = 'Filler ' .. string.char(64 + i), Level = 1, Id = 700 + i,
                                    Jobs = { 'All' }, Stats = { Accuracy = 4 + i } };
    end
    G2.Head['Set Sallet'] = { Name = 'Set Sallet', Level = 1, Id = 610, Jobs = { 'All' },
                              Stats = { Accuracy = 0 } };
    G2.Neck['Set Gorget'] = { Name = 'Set Gorget', Level = 1, Id = 611, Jobs = { 'All' },
                              Stats = { Accuracy = 0 } };
    package.loaded['dlac\\gear'] = G2;
    local optB = dofile('gear/gearoptim.lua');
    local hb11 = optB.buildBestSet({ job = 'WAR', level = 75, weights = { Accuracy = { perUnit = 3 } } });
    check('HB11 augmented pool + seeding win the set pair',
        tostring(hb11.slots.Head) .. '+' .. tostring(hb11.slots.Neck), 'Set Sallet+Set Gorget');
    check('HB11b whole-set total is the bonus', hb11.total, 3 * 50);

    -- HB10: the greedy single-stat path stays SET-BLIND (ADR 0011): an unfirable
    -- stat stick still wins the Ammo slot and Range still empties, set data or not
    local function it(name, acc, extra)
        local e = { Name = name, Level = 1, Id = 0, Jobs = { 'All' }, Stats = { Accuracy = acc } };
        for k, v in pairs(extra or {}) do e[k] = v; end
        return e;
    end
    G2.Range = { Archery = { it('Test Bow', 10, { Type = 'Archery', Id = 601 }) } };
    G2.Ammo  = { stick = it('Cinderstone', 20, { Id = 602 }) };
    local r = optB.buildMaxStatSet('Accuracy', { job = 'WAR', level = 99 });
    check('HB10 greedy path set-blind: unfirable ammo still wins', r.slots.Ammo, 'Cinderstone');
    check('HB10b ...and Range stays EMPTY despite the set', r.slots.Range, nil);

    package.loaded['dlac\\gear'] = savedGear;
    package.loaded['dlac\\gear\\geareffects'] = savedGfx;
end)();

-- ---------------------------------------------------------------------------
-- FISHING: fishcalc verdict math (server formulas, hand-computed cases) +
-- fishdb integrity + fishwatch state/pick rules + the engine's dlac:AutoFish
-- overlay (v64) -- docs/design/fishing-gear.md. The fail-chance expectations
-- below are derived BY HAND from fishingutils.cpp CalculateLoseChance :719 /
-- CalculateSnapChance :784 / CalculateBreakChance :828 -- if a port edit
-- moves one of these numbers, re-derive from the C++ before touching the test.
-- ---------------------------------------------------------------------------
(function()
    package.loaded['dlac\\data\\fishdb'] = dofile('data/fishdb.lua');
    local fcalc = dofile('feature/fishcalc.lua');
    package.loaded['dlac\\feature\\fishcalc'] = fcalc;

    -- pure verdict math on synthetic records (no db involved)
    local marlin  = { sk = 61, rank = 23, sz = 1 };
    local halcyon = { sz = 0, minR = 1, maxR = 18, brk = 1 };
    local ebisuR  = { sz = 0, minR = 1, maxR = 30, leg = 1 };
    local v = fcalc.verdictFor(marlin, halcyon, 50);
    check('F1 big fish, small rod: lose=toobig 50', v.lose .. '/' .. tostring(v.loseWhy), '50/toobig');
    check('F2 big fish, small rod: snap capped 55', v.snap, 55);
    check('F3 big fish, small rod: break 9',        v.brk, 9);
    v = fcalc.verdictFor(marlin, ebisuR, 50);
    check('F4 same fish on Ebisu: lose=lowskill 3', v.lose .. '/' .. tostring(v.loseWhy), '3/lowskill');
    check('F5 Ebisu: no snap',  v.snap, 0);
    check('F6 Ebisu never breaks', v.brk, 0);
    local legFish = { sk = 100, rank = 30, sz = 1, leg = 1 };
    local luShang = { sz = 0, minR = 1, maxR = 28, brk = 1, leg = 1 };
    v = fcalc.verdictFor(legFish, luShang, 100);
    check('F7 legendary on legendary rod at skill: SAFE', v.ok, true);
    v = fcalc.verdictFor(legFish, halcyon, 100);
    check('F8 legendary on normal rod: lose toobig', tostring(v.loseWhy), 'toobig');
    check('F9 legendary on normal rod: snap 55',     v.snap, 55);
    check('F10 legendary on normal rod: break 19',   v.brk, 19);
    -- the uint8-wrap quirk: over-skill "rebate" past zero wraps high -> 50
    v = fcalc.verdictFor({ sk = 5, rank = 10, sz = 1 }, { sz = 0, minR = 1, maxR = 5, brk = 1 }, 100);
    check('F11 toobig uint8 wrap clamps to 50', v.lose .. '/' .. tostring(v.loseWhy), '50/toobig');
    -- tooSmall has the guarded subtraction (source :753) -> floors at zero
    local largeRod = { sz = 1, minR = 8, maxR = 18, brk = 1 };
    v = fcalc.verdictFor({ sk = 5, rank = 1, sz = 0 }, largeRod, 100);
    check('F12 toosmall guarded to zero at high skill', v.lose, 0);
    v = fcalc.verdictFor({ sk = 5, rank = 1, sz = 0 }, largeRod, 30);
    check('F13 toosmall mid-skill', v.lose .. '/' .. tostring(v.loseWhy), '25/toosmall');
    v = fcalc.verdictFor({ sk = 99, rank = 1, sz = 0 }, { sz = 0, minR = 1, maxR = 5, brk = 1 }, 1);
    check('F14 lowskill capped at 55', v.lose .. '/' .. tostring(v.loseWhy), '55/lowskill');

    -- fishdb integrity (the shipped data the panel trusts)
    local db = fcalc.db();
    check('F15 fishdb loads through fishcalc', db ~= nil, true);
    local nFish = 0; for _ in pairs(db.fish) do nFish = nFish + 1; end
    local nRods = 0; for _ in pairs(db.rods) do nRods = nRods + 1; end
    local nBaits = 0; for _ in pairs(db.baits) do nBaits = nBaits + 1; end
    check('F16 fish table populated (>=120)', nFish >= 120, true);
    check('F17 all 20 public rods', nRods, 20);
    check('F18 all 39 baits', nBaits, 39);
    check('F19 Moat Carp', db.fish[4401] ~= nil and db.fish[4401].n, 'Moat Carp');
    check('F20 Moat Carp hook level', db.fish[4401].sk, 11);
    check('F21 Ebisu legendary + unbreakable', (db.rods[17011].leg or 0) == 1 and (db.rods[17011].brk or 0) == 0, true);
    check('F22 Lu Shang breaks to 489', db.rods[17386].brokenId, 489);
    check('F23 Little Worm hooks Moat Carp', db.aff[17396] ~= nil and db.aff[17396][4401] ~= nil, true);
    check('F24 search finds the carp', (fcalc.searchFish('moat')[1] or {}).id, 4401);
    check('F25 carp takes baits', #fcalc.baitsFor(4401) > 0, true);
    local iso = fcalc.isolationFor(4291);   -- Sandfish: the generator-verified case
    check('F26 sandfish has isolation rows', #iso > 0, true);
    check('F27 cleanest row first', iso[1].clean, true);
    check('F28 gearBonus: Ebisu cx4', (db.gearBonus[17011] or {}).cx4, 10);
    check('F29 gearBonus: Halieutica is a Main', (db.gearBonus[20945] or {}).sl, 'Main');
    check('F30 gearBonus: Eyepatch carries only cx', (db.gearBonus[28443] or {}).fish == nil
        and (db.gearBonus[28443] or {}).cx4 == 20, true);
    check('F31 guild rank 1 test fish is the carp', db.guild.rankFish[1], 4401);
    check('F32 eleven guild ranks', #db.guild.ranks, 11);
    -- a legendary fish exists and Ebisu beats a twig for it
    local legId = nil;
    for id, f in pairs(db.fish) do if (f.leg or 0) == 1 then legId = id; break; end end
    check('F33 a legendary fish ships', legId ~= nil, true);
    if legId ~= nil then
        local best = fcalc.bestOwnedRod(db.fish[legId], 100, { [17391] = true, [17011] = true });
        check('F34 legendary target -> Ebisu over Willow', best ~= nil and best.id, 17011);
    end
    check('F35 gearScore: verified Fish beats unverified cx', fcalc.gearScore(1, nil) > fcalc.gearScore(0, { cx4 = 50, cx5 = 5 }), true);

    -- fishwatch: state rules + rod/bait auto-pick (headless seams)
    local fw = dofile('feature/fishwatch.lua');
    check('F36 pill starts off', fw.isEnabled(), false);
    local lines = fw.parseVentureLine('Fishing: (Low) Selbina, (Mid) Qufim Island, (High) Sea of Shadows');
    check('F37 fishing venture line: 3 tiers', lines ~= nil and #lines or 0, 3);
    check('F37b low tier', lines ~= nil and lines[1], 'Low:  Selbina');
    check('F38 helm categories are not ours', fw.parseVentureLine('Mining: (Low) Ordelles Caves, (Mid) X, (High) Y'), nil);
    local drift = fw.parseVentureLine('Fishing: something new the server said');
    check('F39 drifted format keeps raw tail', drift ~= nil and drift[1], 'something new the server said');
    -- The FIELD shape (capture 2026-07-18, re-confirmed 07-28) is level bands,
    -- and six of them WRAP onto a second, prefix-less chat line.
    local band = fw.parseVentureLine('Fishing: (0-19) Quus, (20-39) Cheval Salmon, (40-59) Bluetail,');
    check('F39b band shape parses', band ~= nil and #band or 0, 3);
    check('F39c first band', band ~= nil and band[1], '0-19:  Quus');
    check('F39d the wrap comma is not eaten into the name', band ~= nil and band[3], '40-59: Bluetail');
    fw.openCapture(6);
    fw.onChatLine(29, 'Mindie', "=== Today's Goblin Ventures ===");
    fw.onChatLine(13, 'Mindie', 'Fishing: (0-19) Quus, (20-39) Cheval Salmon, (40-59) Bluetail,');
    fw.onChatLine(13, 'Mindie', '(60-79) Bladefish, (80-99) Gavial Fish, (100+) Giant Chirai');
    local vl, vfresh, vgen = fw.venturesFor();
    check('F39e the wrapped reply keeps all six bands', vl ~= nil and #vl or 0, 6);
    check('F39f the second line joins the block', vl ~= nil and vl[6], '100+:  Giant Chirai');
    check('F39g nothing stranded in general', vgen ~= nil and #vgen or 0, 0);
    check('F39h today\'s capture is fresh', vfresh, true);
    -- unarmed bands are chatter, not the reply: they must not extend the block
    fw.openCapture(6);
    fw.onChatLine(5, 'Squee', '(10-19) Bass, (20-29) Trout -- nice fish');
    local vl2, _, vgen2 = fw.venturesFor();
    check('F39i bare bands cannot hijack the block', vl2 ~= nil and #vl2 or 0, 6);
    check('F39j ...they land in general', vgen2 ~= nil and #vgen2 or 0, 1);
    -- a re-ask reprints everything, so the first named reply line swaps it out
    fw.openCapture(6);
    fw.onChatLine(29, 'Mindie', "=== Today's Goblin Ventures ===");
    fw.onChatLine(13, 'Mindie', 'Fishing: (0-19) Hamsi, (20-39) Tricolored Carp, (40-59) Black Eel,');
    local vl3, _, vgen3 = fw.venturesFor();
    check('F39k a re-ask replaces the stored reply', vl3 ~= nil and #vl3 or 0, 3);
    check('F39l ...and clears the last window\'s leftovers', vgen3 ~= nil and #vgen3 or 0, 0);
    check('F40 chatter -> nil', fw.parseVentureLine('gone fishing brb'), nil);
    check('F41 jst rollover', fw.jstDay(15 * 3600) - fw.jstDay(0), 1);
    fw._clientName = function(id)
        return ({ [17390] = 'Yew Fishing Rod', [17391] = 'Willow Fish. Rod',
                  [17396] = 'Little Worm' })[id];
    end
    fw._ownedAvail = { [17391] = 1, [17390] = 1, [17396] = 99 };
    fw.setTarget(4401);
    local rid = select(1, fw.getRod());
    check('F42 target set', select(2, fw.getTarget()), 'Moat Carp');
    -- at skill 0 the Yew (durability 6) out-risks the Willow (5) on a rank-7
    -- carp: snap 8 vs 17 -- the verdict sort must prefer it
    check('F43 rod pick minimizes risk (Yew over Willow)', rid, 17390);
    check('F44 rod stamped with the CLIENT name', select(2, fw.getRod()), 'Yew Fishing Rod');
    check('F45 bait picked from owned affinity', select(1, fw.getBait()), 17396);
    -- explicit bait choice survives re-picks while stocked
    local carpBaits = fcalc.baitsFor(4401);
    local altBait = nil;
    for _, e in ipairs(carpBaits) do if e.id ~= 17396 then altBait = e.id; break; end end
    if altBait ~= nil then
        fw._ownedAvail[altBait] = 12;
        fw.setTarget(4401, altBait);
        check('F46 explicit bait honoured', select(1, fw.getBait()), altBait);
        fw.autoPick(true);
        check('F47 explicit bait survives autoPick(keep)', select(1, fw.getBait()), altBait);
        fw._ownedAvail[altBait] = nil;
    end
    -- THE ISOLATION RULE under the bag heartbeat: a rod-only loss must re-pick
    -- the ROD and leave the user's explicit (lower-power) isolation bait alone.
    -- revalidate passed keepBait=false, silently trading it up to the strongest
    -- stocked bait -- and saying nothing, because the bait announcement only
    -- fires when the BAIT stack emptied (review find, 2026-07-18).
    local topBait = (carpBaits[1] or {}).id;
    local lowBait = (carpBaits[#carpBaits] or {}).id;
    if lowBait ~= nil and topBait ~= nil and lowBait ~= topBait then
        fw._ownedAvail = { [17391] = 1, [17390] = 1, [topBait] = 50, [lowBait] = 12 };
        fw.setTarget(4401, lowBait);              -- the user's isolation pick
        fw.setEnabled(true);
        fw._ownedAvail[17390] = nil;              -- the worn Yew vanishes; Willow remains
        fw.revalidate();
        check('F47b rod-only heartbeat re-picks the rod', select(1, fw.getRod()), 17391);
        check('F47c ...and the explicit ISOLATION bait survives (never traded for power)',
            select(1, fw.getBait()), lowBait);
        fw.setEnabled(false);
        fw._ownedAvail = { [17391] = 1, [17390] = 1, [17396] = 99 };
        fw.setTarget(4401);                       -- re-arm the exhaustion flow below
    end
    fw.setEnabled(true);
    check('F48 pill on', fw.isEnabled(), true);
    fw._ownedAvail = { [17390] = 1 };   -- bait stack gone, rod still here
    fw.revalidate();
    check('F49 exhausted bait cleared (nothing suitable left)', select(1, fw.getBait()), nil);
    fw._ownedAvail = {};                -- rod gone too
    fw.revalidate();
    check('F50 vanished rod cleared', select(1, fw.getRod()), nil);
    fw.setEnabled(false);

    -- engine: fishStateActive + the dlac:AutoFish overlay
    local act = dispatchM._fishStateActive;
    check('F51 enabled state active', act({ enabled = true }), true);
    check('F52 disabled state inactive', act({ enabled = false }), false);
    check('F53 nil state inactive', act(nil), false);
    dispatchM._autoOverride = { fish = {
        main = { { name = 'Halieutica', score = 2105, level = 1, fish = 2 } },
        body = { { name = 'Anglers Tunica', score = 1000, level = 15, fish = 1 },
                 { name = 'Fsh. Tunica',    score = 1000, level = 1,  fish = 1 } },
        ring1 = { { name = 'Anglers Ring', score = 2000, level = 75, fish = 2 } },
    } };
    local fs = { enabled = true, at = 1, rod = 'Willow Fish. Rod', bait = 'Little Worm' };
    local fov = dispatchM._fishOverlayFor(fs, { player = { MainJobSync = 75, Status = 'Idle' } });
    check('F54 rod worn from state', fov and fov.Range, 'Willow Fish. Rod');
    check('F55 bait worn from state', fov and fov.Ammo, 'Little Worm');
    check('F56 Main ladder (Halieutica)', fov and fov.Main, 'Halieutica');
    check('F57 body best rung', fov and fov.Body, 'Anglers Tunica');
    check('F58 ring ladder', fov and fov.Ring1, 'Anglers Ring');
    local fovLow = dispatchM._fishOverlayFor(fs, { player = { MainJobSync = 10, Status = 'Idle' } });
    check('F59 underlevel rung falls through', fovLow and fovLow.Body, 'Fsh. Tunica');
    check('F60 underlevel ring -> slot empty', fovLow and fovLow.Ring1, nil);
    check('F61 engaged -> stands aside', dispatchM._fishOverlayFor(fs, { player = { MainJobSync = 75, Status = 'Engaged' } }), nil);
    check('F62 dead -> stands aside', dispatchM._fishOverlayFor(fs, { player = { MainJobSync = 75, Status = 'Dead' } }), nil);
    local fovEvt = dispatchM._fishOverlayFor(fs, { player = { MainJobSync = 75, Status = 'Event' } });
    check('F63 event stays dressed', fovEvt and fovEvt.Range, 'Willow Fish. Rod');
    check('F64 disabled -> no overlay', dispatchM._fishOverlayFor({ enabled = false, rod = 'X' }, { player = { MainJobSync = 75 } }), nil);
    local fsNoGear = { enabled = true };
    local fovNoRod = dispatchM._fishOverlayFor(fsNoGear, { player = { MainJobSync = 75, Status = 'Idle' } });
    check('F65 no rod picked -> Range untouched, ladders still dress',
        (fovNoRod and fovNoRod.Range) == nil and (fovNoRod and fovNoRod.Body) ~= nil, true);
    -- v91: the rod brings an Ammo claim even with NO bait ('remove') -- an
    -- unclaimed Ammo lets an idle set's stat-stick trinket land beside the
    -- rod and the server strips the rod (ADR 0010), forever.
    local fsNoBait = { enabled = true, at = 1, rod = 'Willow Fish. Rod' };
    local fovNoBait = dispatchM._fishOverlayFor(fsNoBait, { player = { MainJobSync = 75, Status = 'Idle' } });
    check('F68 rod with no bait -> Ammo claimed empty', fovNoBait and fovNoBait.Ammo, 'remove');
    check('F69 ... and the rod still equips', fovNoBait and fovNoBait.Range, 'Willow Fish. Rod');
    check('F70 no rod AND no bait -> Ammo left alone', fovNoRod and fovNoRod.Ammo, nil);
    local fsBaitOnly = { enabled = true, at = 1, bait = 'Little Worm' };
    local fovBaitOnly = dispatchM._fishOverlayFor(fsBaitOnly, { player = { MainJobSync = 75, Status = 'Idle' } });
    check('F71 bait without a rod rides as itself', fovBaitOnly and fovBaitOnly.Ammo, 'Little Worm');
    check('F66 resolveVirtual dlac:AutoFish body', dispatchM._resolveVirtual('dlac:AutoFish',
        { player = { MainJobSync = 75 } }, 'Body'), 'Anglers Tunica');
    check('F67 resolveVirtual unknown fish slot -> nil', dispatchM._resolveVirtual('dlac:AutoFish',
        { player = { MainJobSync = 75 } }, 'Sub'), nil);
    dispatchM._autoOverride = nil;

    -- craftwatch: the fishing guild points offset (0x20) now parses
    local cw2 = dofile('feature/craftwatch.lua');
    local function fi32(v) return string.char(v % 256, math.floor(v/256)%256, math.floor(v/65536)%256, math.floor(v/16777216)%256); end
    local pkt = string.rep('\0', 0x20) .. fi32(1111) .. fi32(2555) .. fi32(6536) .. fi32(10990)
        .. fi32(540) .. fi32(23539) .. fi32(0) .. fi32(75200) .. fi32(4325);
    cw2.onCurrencyPacket(pkt);
    check('F68 fishing GP parsed at 0x20', cw2.guildPointsFor('Fishing'), 1111);
    check('F69 craft offsets unmoved', cw2.guildPointsFor('Woodworking'), 2555);

    -- field round 5 (2026-07-18): the legendary tier, manual pins, and the
    -- upgrade heartbeat. Henrik's ruling: "Lu Shang's always beats base rods,
    -- Ebisu always beats Lu Shang's" -- and no pill toggle to get there.

    -- the live bug verbatim: Moat Carp at high skill is risk-0 on everything,
    -- and the old sort let Clothespole's raw attack outrank Lu Shang's
    local poleId = nil;
    for id, r in pairs(db.rods) do
        if (r.n or ''):lower() == 'clothespole' then poleId = id; break; end
    end
    check('F70 Clothespole ships', poleId ~= nil, true);
    if poleId ~= nil then
        local best5 = fcalc.bestOwnedRod(db.fish[4401], 100, { [poleId] = true, [17386] = true });
        check('F70b Lu Shang over Clothespole on the carp', best5 and best5.id, 17386);
    end
    local bestLeg = fcalc.bestOwnedRod(db.fish[4401], 100, { [17386] = true, [17011] = true });
    check('F71 Ebisu over Lu Shang', bestLeg and bestLeg.id, 17011);
    check('F72 legRank tiers ordered', fcalc.legRank(17011) > fcalc.legRank(17386)
        and fcalc.legRank(17386) > fcalc.legRank(17390), true);
    -- risk STILL beats the tier: a fish that would snap Lu Shang's gets the
    -- safe base rod recommended (the whole point of the verdict system)
    local realDb = db;
    fcalc._setDb({ fish = { [1] = { n = 'Brutus', sk = 10, rank = 40, sz = 1 } },
                   rods = { [17386] = { n = 'Lu', leg = 1, brk = 1, sz = 0, minR = 1, maxR = 28 },
                            [900] = { n = 'Big Safe Rod', sz = 1, minR = 1, maxR = 45, brk = 1 } },
                   baits = {}, aff = {}, pools = {}, zones = {}, mobs = {} });
    local rRisk = fcalc.rodsFor(fcalc.db().fish[1], 100, { [17386] = true, [900] = true });
    check('F73 risk beats the legendary tier', rRisk[1] and rRisk[1].id, 900);
    fcalc._setDb(realDb);

    -- manual pins (the fish bar dropdowns): a pin holds through the heartbeat,
    -- falls back to auto when the item vanishes, and target changes unpin
    fw._ownedAvail = { [17391] = 1, [17390] = 1, [17396] = 99 };
    fw.setTarget(4401);
    fw.setEnabled(true);
    check('F74 auto rod first (least-risk Yew)', select(1, fw.getRod()), 17390);
    fw.setRod(17391);                          -- the user says Willow
    check('F75 manual rod set + pinned', select(1, fw.getRod()) == 17391 and fw.rodPinned(), true);
    fw.revalidate();                           -- the beat must NOT trade it back
    check('F76 pinned rod survives the heartbeat', select(1, fw.getRod()), 17391);
    fw._ownedAvail[17391] = nil;               -- the pinned rod vanishes
    fw.revalidate();
    check('F77 vanished pin falls back to auto', select(1, fw.getRod()) == 17390 and not fw.rodPinned(), true);
    fw._ownedAvail = { [17391] = 1, [17396] = 99 };   -- Yew gone, only Willow
    fw.revalidate();
    check('F78 vanish still re-picks what exists', select(1, fw.getRod()), 17391);
    fw._ownedAvail[17390] = 1;                 -- the better (least-risk) Yew RETURNS
    fw.revalidate();                           -- no vanish, no toggle -- just the beat
    check('F79 better rod adopted on the beat (the Lu Shang bug)', select(1, fw.getRod()), 17390);
    fw.setRod(17391);                          -- pin Willow again...
    fw.setTarget(4401);                        -- ...then change target
    check('F80 target change unpins', fw.rodPinned(), false);
    -- pinned bait is absolute while stocked -- even off-affinity (the user
    -- may know something fishdb doesn't)
    local offBait = nil;
    for id in pairs(db.baits) do if (db.aff[id] or {})[4401] == nil then offBait = id; break; end end
    check('F81 an off-affinity bait exists', offBait ~= nil, true);
    if offBait ~= nil then
        fw._ownedAvail[offBait] = 3;
        fw.setBait(offBait);
        check('F81b off-affinity manual bait honoured', select(1, fw.getBait()), offBait);
        fw.revalidate();
        check('F82 pinned bait survives the heartbeat', select(1, fw.getBait()), offBait);
        fw.setBait(nil);
        check('F83 AUTO returns the affine pick', select(1, fw.getBait()), 17396);
        fw._ownedAvail[offBait] = nil;
    end
    fw.setEnabled(false);

    -- wornFishTotal moved into fishcalc (fishui + fishbar share it)
    fcalc._setDb({ gearBonus = { [1] = { sl = 'Body', fish = 2 }, [2] = { sl = 'Body', fish = 1 },
                                 [3] = { sl = 'Ring', fish = 1 }, [4] = { sl = 'Range', fish = 5 } },
                   fish = {}, rods = {}, baits = {}, aff = {}, pools = {} });
    check('F84 wornFishTotal: best body + doubled ring, rod excluded',
        fcalc.wornFishTotal({ [1] = 1, [2] = 1, [3] = 2, [4] = 1 }), 4);
    fcalc._setDb(realDb);
end)();

