(function()
    local t = { active = 1, slots = {
        [1] = { name = 'Look', set = { Body = "Arhat's Gi", Head = 'Ghost Cap', Feet = 'remove' } },
        [2] = { name = 'Empty', set = {} } } };
    local ids = { ["Arhat's Gi"] = 12345 };            -- Ghost Cap does NOT resolve
    local function resolveId(nm) return ids[nm]; end
