    check('DBG3 dry-run line is last', L[#L]:find('nothing was sent', 1, true) ~= nil, true);
    local Lg = dispatchM._lsDebugReport(t, 1, resolveId, equippedId,
        function(nm) return nm == "Arhat's Gi"; end);
    local gline = nil;
    for _, l in ipairs(Lg) do if l:find('KEEP OLD LOOK', 1, true) then gline = l; end end
    check('DBG4 gate prediction names slot=piece', gline ~= nil
          and gline:find("Body=Arhat's Gi", 1, true) ~= nil, true);
    check('DBG5 empty box refuses like apply', dispatchM._lsDebugReport(t, 2, resolveId, equippedId, nil)[1],
          'apply would refuse: lockstyle box 2 has no items');
    check('DBG6 no file refuses like apply', dispatchM._lsDebugReport(nil, nil, resolveId, equippedId, nil)[1],
          'apply would refuse: no lockstyle sets saved yet');
    -- (DBG7-8 and DBR1-10 -- the capture-window flush and the engine's
    -- request-file watch -- died in the purge, Phase 2, with the two-state
    -- command bridge itself.)
    check('DBG7 the flush seam is deleted with the bridge', dispatchM._lsDbgFlushLines, nil);
    check('DBR1 the request watch seam too', dispatchM._reqFire, nil);
    check('DBR2 ...and the spec parser', dispatchM._reqSpec, nil);
end)();

-- LGD. lockstyle.M.debugLines -- the '/dl debug ls' addon half exists and
--      degrades honestly headless (no char, no boxes: the report still forms).
(function()
    local ls = dofile('feature/lockstyle.lua');
    check('LGD1 debugLines exported', type(ls.debugLines), 'function');
    local ok, L = pcall(ls.debugLines);
    check('LGD2 headless readout does not error', ok, true);
    check('LGD3 at least file/boxes/keep/town/traffic lines', ok and type(L) == 'table' and #L >= 5, true);
    check('LGD4 boxes-file line leads', ok and L[1]:find('boxes file', 1, true) ~= nil, true);
    -- the guard's 0x053 observation line (the "is anything leaving?" witness)
    check('LGD5 empty log says so', ls._outLine({}, 100):find('no 0x053 seen', 1, true) ~= nil, true);
    local line = ls._outLine({ { at = 96, mode = 3, act = 'activate' },
                               { at = 90, mode = 0, act = 'suppress' } }, 100);
    check('LGD6 SET + disable named with age and verdict', line:find('SET 4s ago (activate)', 1, true) ~= nil
          and line:find('disable 10s ago (suppress)', 1, true) ~= nil, true);
    check('LGD7 unknown mode degrades to its number', ls._outLine({ { at = 99, mode = 7, act = 'pass' } }, 100)
          :find('mode 7', 1, true) ~= nil, true);
    -- the capture window, addon half (v106): open -> note -> collect clears.
    check('LGD8 no window = notes are no-ops', (function()
        ls._capNote('before any window');
        return #ls.debugCaptureLog();
    end)(), 0);
    ls.debugCapture(30);
    ls._capNote('first event');
    ls._capNote('second event');
    local cap = ls.debugCaptureLog();
    check('LGD9 window collects stamped events in order', #cap == 2
          and cap[1]:find('t+', 1, true) == 1 and cap[1]:find('first event', 1, true) ~= nil
          and cap[2]:find('second event', 1, true) ~= nil, true);
    check('LGD10 collect clears the window', #ls.debugCaptureLog(), 0);
end)();

-- ---------------------------------------------------------------------------
-- NE. Native-engine storage home (feature/native-engine step 1) -- the flag
-- parse, the mode-aware path authorities, and the migration copy planner.
--
-- All PURE: the flag parse and the copy planner take text/lists; the path
-- composition runs against a stubbed AshitaCore install path with nativeMode
-- overridden per check (no file IO -- the WSL CI parity rule: '\'-joined io
-- paths break on Linux).
-- ---------------------------------------------------------------------------
(function()
    local prof = package.loaded['dlac\\profiles'];

    -- (NE1-NE7 pinned the engine-flag parse; NE8-NE14 pinned the legacy path
    -- family. Both died in the purge, Phase 2: the flag is retired in place
    -- and the native home is the ONLY home. charBase stays as the importers'
    -- read-only door into the old tree.)
    check('NE1 the flag parse is deleted with the flag', prof.parseEngineFlag, nil);
    check('NE2 nativeMode has one answer now', prof.nativeMode(), true);
    check('NE3 the flag state reader is gone too', prof.engineFlagState, nil);
    check('NE4 ...and the flag writer', prof.setNativeMode, nil);

    local savedAC, savedNative = AshitaCore, prof.nativeMode;
    AshitaCore = {
        GetInstallPath = function() return 'I:\\game\\'; end,
        GetMemoryManager = function() return {
            GetParty = function() return {
                GetMemberName = function() return 'Mindie'; end,
                GetMemberServerId = function() return 12345; end,
            }; end,
        }; end,
    };

    check('NE8 charFolder is <Name>_<Id>',    prof.charFolder(), 'Mindie_12345');
    check('NE9 charBase stays the importers\' read-only door', prof.charBase(),
          'I:\\game\\config\\addons\\luashitacast\\Mindie_12345\\');
    check('NE15 native dataDir is dlac\'s own root, no dlac\\ level', prof.dataDir(),
          'I:\\game\\config\\addons\\dlac\\Mindie_12345\\');
    check('NE16 native charRoot equals the char home', prof.charRoot(),
          'I:\\game\\config\\addons\\dlac\\Mindie_12345\\');
    check('NE17 native storageRoot is the dlac root', prof.storageRoot(),
          'I:\\game\\config\\addons\\dlac\\');
    check('NE18 native pointer under the char home', prof.pointerPath(),
          'I:\\game\\config\\addons\\dlac\\Mindie_12345\\profile.lua');
    check('NE19 native cross-char data dir is flat', prof.charDataDirAt('Frieda_777'),
          'I:\\game\\config\\addons\\dlac\\Frieda_777\\');
    check('NE20 native profilesRoot composes off dataDir', prof.profilesRoot(),
          'I:\\game\\config\\addons\\dlac\\Mindie_12345\\profiles\\');
    check('NE21 native still names the LEGACY exports home', prof.legacyExportsDir(),
          'I:\\game\\config\\addons\\luashitacast\\dlac-exports\\');
    check('NE22 native exports live under the dlac root', prof.exportsDir(),
          'I:\\game\\config\\addons\\dlac\\dlac-exports\\');
    check('NE23 the flag path authority is gone', prof.engineFlagPath, nil);
    check('NE24 backups follow the native char home', prof.backupPath('WHM'),
          'I:\\game\\config\\addons\\dlac\\Mindie_12345\\backups\\pre-profiles\\WHM.lua');
    check('NE25 legacy trigger tier rides the data home too', prof.legacyTriggersPath('WHM'),
          'I:\\game\\config\\addons\\dlac\\Mindie_12345\\triggers\\WHM.lua');

    -- NE30. THE NIL-TOGETHER INVARIANT. dataDir (nativeCharBase) and charBase are
    -- the same charFolder() behind two roots, so they answer or fall silent as one.
    -- gearui.dataDir / gearui.charRoot / syncflags.uiFlagsPath each used to end in
    -- a `charBase() .. 'dlac\\'` fallback; those were deleted on 2026-07-27 because
    -- this invariant makes them unreachable. If anyone ever makes the two diverge,
    -- the deletion stops being safe -- and this fires before the field finds out.
    local savedFolder = prof.charFolder;
    prof.charFolder = function() return nil; end          -- pre-login
    check('NE30 no identity -> dataDir is nil',  prof.dataDir(),  nil);
    check('NE30b ...and charBase is nil TOO',    prof.charBase(), nil);
    prof.charFolder = function() return 'Mindie_12345'; end
    check('NE30c identity -> both answer: dataDir',  prof.dataDir() ~= nil,  true);
    check('NE30d ...and charBase',                   prof.charBase() ~= nil, true);
    prof.charFolder = savedFolder;

    prof.nativeMode = savedNative;
    AshitaCore = savedAC;

    -- the migration copy planner: skip existing, reject escapes, sort output
    local copy, skip = prof.planEngineCopy(
        { 'profiles\\Default\\sets\\WHM.lua', 'gear.lua', 'profile.lua',
          'profiles\\Default\\sets\\WHM.lua' },   -- duplicate rides through (fs never produces one)
        { ['gear.lua'] = true });
    check('NE26 planner copies what the target lacks', table.concat(copy, ','),
          'profile.lua,profiles\\Default\\sets\\WHM.lua,profiles\\Default\\sets\\WHM.lua');
    check('NE27 planner skips what the target has', table.concat(skip, ','), 'gear.lua');
    local c2 = prof.planEngineCopy({ '..\\evil.lua', 'C:\\abs.lua', '\\rooted.lua', '', 'ok.lua' }, {});
    check('NE28 planner rejects escapes and absolutes', table.concat(c2, ','), 'ok.lua');
    local c3, s3 = prof.planEngineCopy(nil, nil);
    check('NE29 planner survives nil args', #c3 + #s3, 0);
end)();

-- ---------------------------------------------------------------------------
-- NO. Native-first onboarding (ADR 0015 ruling 4, issue #87) -- the pure
-- first-run decision (flag presence x legacy-data presence -> action), the
-- LAC-alive ask's once-per-session gate, and the native Setup path (storage +
-- starter files, ZERO writes under config\addons\luashitacast\).
-- ---------------------------------------------------------------------------
(function()
    local prof = package.loaded['dlac\\profiles'];

    -- (NO1-NO6 -- the pure first-run decision matrix -- died in the purge,
    -- Phase 2: no flag, no decision. ADR 0025's law is structural now.)
    check('NO1 the first-run decision is deleted with the flag', prof.firstRunAction, nil);

    -- (NO7-NO11 -- the once-per-session LAC-alive ask gate -- died in the
    -- purge, Phase 1, with shouldAskUnloadLac/lacAlive; the coexistence
    -- tripwire is the one remaining backstop.)
    check('NO7 the ask gate is deleted with its machinery', prof.shouldAskUnloadLac, nil);

    -- The native Setup path. Stub the install + identity, force native mode, and
    -- capture every write: the ACCEPTANCE guarantee is zero <JOB>.lua / shim /
    -- backup writes under LuaAshitacast's tree. IO-touching profiles helpers are
    -- overridden to no-ops (the WSL parity rule: '\'-joined io paths break on
    -- Linux) so the only writes flow through the captured writeFileText.
    local savedAC, savedNative, savedEnsure, savedExists, savedExec =
        AshitaCore, prof.nativeMode, prof.ensureStorage, prof.storageExists, os.execute;
    AshitaCore = {
        GetInstallPath = function() return 'I:\\game\\'; end,
        GetMemoryManager = function() return {
            GetParty = function() return {
                GetMemberName = function() return 'Mindie'; end,
                GetMemberServerId = function() return 12345; end,
            }; end,
        }; end,
    };
    prof.ensureStorage = function() return true; end          -- no real disk
    prof.storageExists = function() return true; end          -- seed into profile storage
    os.execute = function() return true; end                  -- swallow seedGearFile's mkdir

    local setup = dofile('ui/setupui.lua');
    package.loaded['dlac\\ui\\setupui'] = setup;
    local base = 'I:\\game\\config\\addons\\luashitacast\\Mindie_12345\\';
    local jf = base .. 'WHM.lua';
    local writes;
    local function mkDeps()
        return {
            charBase = function() return base; end,
            jobFile  = function() return jf, 'WHM'; end,
            dataDir  = function() return prof.dataDir(); end,
            charRoot = function() return prof.charRoot(); end,
            readFileText  = function() return nil; end,                 -- nothing exists yet
            writeFileText = function(p) writes[#writes + 1] = p; return true; end,
            status = function() end,
            ui = {},
        };
    end
    local function has(sub)
        for _, p in ipairs(writes) do if type(p) == 'string' and p:find(sub, 1, true) then return true; end end
        return false;
    end

    -- NATIVE: setupNative writes storage + starter files, never the LAC tree.
    prof.nativeMode = function() return true; end
    writes = {};
    setup.configure(mkDeps());
    check('NO12 setup reports native mode', setup.isNative(), true);
    setup.setupNative(base, 'WHM');
    check('NO13 native setup wrote something', #writes > 0, true);
    check('NO14 native setup: NO write under luashitacast\\', has('luashitacast'), false);
    check('NO15 native setup: no <JOB>.lua shim written', has('WHM.lua') and has(jf), false);
    check('NO16 native setup: no backup written', has('backups'), false);
    check('NO17 native setup lands under the dlac root', has('config\\addons\\dlac\\'), true);

    -- LEGACY (purge Phase 1): even the flag-off path writes NO job file --
    -- nothing in dlac writes under luashitacast\ anymore, whatever the mode.
    -- Storage/base-set/trigger seeding above is the whole setup.
    prof.nativeMode = function() return false; end
    writes = {};
    setup.configure(mkDeps());
    check('NO18 setup reports legacy mode', setup.isNative(), false);
    setup.migrateCurrentJob();   -- state 'nofile' (readFileText nil)
    local wroteShim = false;
    for _, p in ipairs(writes) do if p == jf then wroteShim = true; end end
    check('NO19 legacy setup writes NO job file either (purge Phase 1)', wroteShim, false);

    prof.nativeMode, prof.ensureStorage, prof.storageExists = savedNative, savedEnsure, savedExists;
    os.execute, AshitaCore = savedExec, savedAC;
end)();

-- ---------------------------------------------------------------------------
-- NO20+. Onboarding v2 (issue #91): needsSetup v2 (native always false;
-- legacy-with-data true), fresh-install auto-setup (idempotent, zero-clobber,
-- ZERO writes under luashitacast\, never in legacy / before job-ready), a new
-- job auto-seeding its own starters, and the migration Commit's call sequence
-- (engineMigrateStorage -> setNativeMode(true) -> the unload checklist), all
-- captured against a virtual disk -- no real IO.
-- ---------------------------------------------------------------------------
(function()
    local prof = package.loaded['dlac\\profiles'];
    local setup = dofile('ui/setupui.lua');
    package.loaded['dlac\\ui\\setupui'] = setup;

    -- A name->content virtual disk the deps read/write through, so idempotence
    -- and zero-clobber are checkable without touching real files.
    local disk, writes = {}, {};
    local savedAC, savedExec = AshitaCore, os.execute;
    local savedNative, savedEnsure, savedExists = prof.nativeMode, prof.ensureStorage, prof.storageExists;
    local savedSetsP, savedTrigP, savedDataDir = prof.setsPath, prof.triggersPath, prof.dataDir;
    local savedMig, savedSet = prof.engineMigrateStorage, prof.setNativeMode;
    AshitaCore = { GetInstallPath = function() return 'I:\\game\\'; end };
    os.execute = function() return true; end
    prof.ensureStorage = function() return true; end
    -- deterministic native paths (no real charFolder resolution)
    local NROOT = 'I:\\game\\config\\addons\\dlac\\Mindie_12345\\';
    prof.dataDir      = function() return NROOT; end
    prof.setsPath     = function(job) return NROOT .. 'profiles\\Default\\sets\\' .. job .. '.lua'; end
    prof.triggersPath = function(job) return NROOT .. 'profiles\\Default\\triggers\\' .. job .. '.lua'; end
    local storageOn = true;
    prof.storageExists = function() return storageOn; end

    local base = 'I:\\game\\config\\addons\\luashitacast\\Mindie_12345\\';
    local curAbbr = 'WHM';
    local deps = {
        charBase = function() return base; end,
        jobFile  = function() if curAbbr == nil then return nil, nil; end return base .. curAbbr .. '.lua', curAbbr; end,
        dataDir  = function() return NROOT; end,
        charRoot = function() return NROOT; end,
        readFileText  = function(p) return disk[p]; end,
        writeFileText = function(p, c) disk[p] = c or 'x'; writes[#writes + 1] = p; return true; end,
        status = function() end,
        ui = {},
    };
    setup.configure(deps);
    local function has(sub) for _, p in ipairs(writes) do if type(p) == 'string' and p:find(sub, 1, true) then return true; end end return false; end
    -- seedGearFile's last-resort source is the bundled empty template.
    disk['I:\\game\\addons\\dlac\\gear.lua'] = 'return {}\n';

    -- --- needsSetup v2 matrix ---
    prof.nativeMode = function() return true; end
    check('NO20 needsSetup native -> always false',   setup.needsSetup(), false);
    prof.nativeMode = function() return false; end
    storageOn = false;
    check('NO21 needsSetup legacy + NO data -> false', setup.needsSetup(), false);
    storageOn = true;
    check('NO22 needsSetup legacy + data -> true',     setup.needsSetup(), true);

    -- --- auto-setup NEVER fires in legacy mode ---
    writes = {};
    check('NO23 autoSetupNative idles in legacy',      setup.autoSetupNative(), 'idle');
    check('NO24 legacy auto-setup wrote nothing',      #writes, 0);

    -- --- fresh native install: baseline missing -> seed it ---
    prof.nativeMode = function() return true; end
    disk = { ['I:\\game\\addons\\dlac\\gear.lua'] = 'return {}\n' }; writes = {}; storageOn = true;
    check('NO25 fresh native auto-setup seeds',        setup.autoSetupNative(), 'seeded');
    check('NO26 auto-setup wrote gear.lua',            has('gear.lua'), true);
    check('NO27 auto-setup wrote this job\'s sets',    has('sets\\WHM.lua'), true);
    check('NO28 auto-setup wrote this job\'s triggers', has('triggers\\WHM.lua'), true);
    check('NO29 auto-setup: ZERO writes under luashitacast\\', has('luashitacast'), false);

    -- --- idempotent: a second run finds the baseline complete, writes nothing ---
    writes = {};
    check('NO30 re-run reports complete',              setup.autoSetupNative(), 'complete');
    check('NO31 re-run clobbers nothing',              #writes, 0);

    -- --- a later NEW job auto-seeds ITS starters (gear.lua is shared, not rewritten) ---
    curAbbr = 'BLM'; writes = {};
    check('NO32 new job auto-seeds its starters',      setup.autoSetupNative(), 'seeded');
    check('NO33 new job wrote BLM sets + triggers',    has('sets\\BLM.lua') and has('triggers\\BLM.lua'), true);
    check('NO34 new job did NOT rewrite gear.lua',     has('gear.lua'), false);
    curAbbr = 'WHM';

    -- --- THE MIGRATED CHARACTER (2026-08-05, the field case) ---
    -- engineAutoMigrate copies config\addons\luashitacast\<char>\dlac\ WHOLE into
    -- the native home, so an old triggers\<JOB>.lua lands at the LEGACY TIER.
    -- seedTriggersFile then refuses to overwrite it ("user data") while the
    -- baseline check demanded the PROFILE tier -- two halves disagreeing about
    -- what "has a trigger file" means, so auto-setup warned and retried forever
    -- on a character whose rules were working the whole time. A legacy-tier file
    -- is LIVE (triggersui.trigFilePath and the engine both fall back to it).
    do
        curAbbr = 'RUN';
        disk = { ['I:\\game\\addons\\dlac\\gear.lua'] = 'return {}\n' };
        disk[NROOT .. 'gear.lua'] = 'return {}\n';
        disk[NROOT .. 'profiles\\Default\\sets\\RUN.lua'] = 'return {}\n';
        disk[NROOT .. 'triggers\\RUN.lua'] = '-- migrated rules\n';   -- LEGACY TIER ONLY
        storageOn = true; writes = {};
        check('NO34a a migrated legacy-tier trigger file completes the baseline',
              setup.nativeBaselineComplete('RUN'), true);
        check('NO34b ...so auto-setup goes quiet instead of warning forever',
              setup.autoSetupNative(), 'complete');
        check('NO34c ...and writes nothing (migrated rules are never clobbered)',
              #writes, 0);
        -- With NEITHER tier present the gate still fails -- and says so in a way
        -- that shows both were looked at, so the next reader does not re-derive
        -- the two-tier rule from scratch.
        disk[NROOT .. 'triggers\\RUN.lua'] = nil;
        local ok2, miss = setup.nativeBaselineComplete('RUN');
        check('NO34d neither tier -> still incomplete', ok2, false);
        check('NO34e ...and the reason names the legacy tier as checked',
              type(miss) == 'string' and miss:find('legacy-tier', 1, true) ~= nil, true);
        curAbbr = 'WHM';
        disk = { ['I:\\game\\addons\\dlac\\gear.lua'] = 'return {}\n' };
    end

    -- --- job not ready (abbr nil, GetMainJob 0 at login) never seeds (hard rule 11) ---
    curAbbr = nil; writes = {};
    check('NO35 job-not-ready auto-setup idles',       setup.autoSetupNative(), 'idle');
    check('NO36 job-not-ready wrote nothing',          #writes, 0);
    curAbbr = 'WHM';

    -- --- a persistent write failure names itself and returns 'failed' (not latched) ---
    do
        local prevWrite = deps.writeFileText;
        deps.writeFileText = function() return true; end   -- pretend writes "succeed" but land nothing
        disk = { ['I:\\game\\addons\\dlac\\gear.lua'] = 'return {}\n' }; storageOn = true;
        setup.configure(deps);
        local failStatus = nil;
        deps.status = function(s) failStatus = s; end
        setup.configure(deps);
        check('NO37 baseline-never-lands reports failed', setup.autoSetupNative(), 'failed');
        check('NO38 failure names itself in status', type(failStatus) == 'string' and failStatus:find('could not', 1, true) ~= nil, true);
        deps.writeFileText = prevWrite; deps.status = function() end;
        setup.configure(deps);
    end

    -- (NO39-NO42 -- the migration Commit's copy-then-flip sequence -- died in
    -- the purge, Phase 2: there is no flag to flip. The stub only informs.)
    local seq = {};
    prof.engineMigrateStorage = function() seq[#seq + 1] = 'migrate'; return 7, 2, 0; end
    local msg = nil; deps.status = function(s) msg = s; end
    setup.configure(deps);
    writes = {};
    setup.migrateToNative();
    check('NO39 the Commit stub migrates nothing itself', #seq, 0);
    check('NO40 ...writes nothing anywhere', #writes, 0);
    check('NO41 ...and says migration is automatic now',
          type(msg) == 'string' and msg:find('automatic', 1, true) ~= nil, true);

    prof.engineMigrateStorage, prof.setNativeMode = savedMig, savedSet;
    prof.nativeMode, prof.ensureStorage, prof.storageExists = savedNative, savedEnsure, savedExists;
    prof.setsPath, prof.triggersPath, prof.dataDir = savedSetsP, savedTrigP, savedDataDir;
    os.execute, AshitaCore = savedExec, savedAC;
end)();

-- ---------------------------------------------------------------------------
-- NO43+. The self-manufactured-evidence bug (field 2026-07-23, Henrik's
-- fresh-install sim): in-game ashita.fs.get_dir returns nil for a MISSING
-- directory (the headless popen fallback returns {} -- the suite masked it),
-- the undecided beat fell through into the LEGACY seeder, and the next scan
-- read dlac's own files as "existing legacy user". Pins: the parent-listing
-- disambiguation (missing root = DEFINITE fresh, not can't-tell), the
-- undecided contract (nil + warn ONCE + never latch), the loud decision lines
-- with their evidence, and the flag-write-failure retry.
-- Since ADR 0025 the boot no longer scans at all -- absence of the flag IS the
-- native verdict -- so NO43-46 pin the scanner itself (migrate-era surfaces,
-- purge-slated), and NO47+ pin the born-native boot: instant, silent, with the
-- flag-write-failure retry as the ONLY undecided state left.
-- ---------------------------------------------------------------------------
(function()
    local prof = package.loaded['dlac\\profiles'];
    local savedAC = AshitaCore;
    local savedList, savedProbe = prof._listDirs, prof._legacyProbe;
    local savedFlagState, savedSetNative = prof.engineFlagState, prof.setNativeMode;
    AshitaCore = { GetInstallPath = function() return 'I:\\game\\'; end };

    -- Root listing nil (the in-game missing-dir shape), parent WITHOUT
    -- luashitacast -> a DEFINITE fresh, scanned=true.
    prof._listDirs = function(p)
        if p:find('luashitacast', 1, true) then return nil; end
        return { 'dlac', 'someotheraddon' };
    end
    local pr, sc = prof.legacyDataPresent();
    check('NO43 missing root disambiguated as FRESH (scanned)', sc, true);
    check('NO43b ...and not present', pr, false);

    -- Root nil but the parent SHOWS luashitacast -> genuinely can't tell.
    prof._listDirs = function(p)
        if p:find('luashitacast', 1, true) then return nil; end
        return { 'dlac', 'Luashitacast' };   -- case-insensitive match required
    end
    pr, sc = prof.legacyDataPresent();
    check('NO44 unlistable-but-present root stays can\'t-tell', sc, false);

    -- Both listings nil -> can't tell.
    prof._listDirs = function() return nil; end
    pr, sc = prof.legacyDataPresent();
    check('NO45 both listings failed -> can\'t tell', sc, false);

    -- Evidence: the first char folder with real data rides the third return.
    prof._listDirs = function(p)
        if p:find('luashitacast', 1, true) then return { 'notachar', 'Testy_123' }; end
        return { 'luashitacast' };
    end
    prof._legacyProbe = function(dd) return dd:find('Testy_123', 1, true) ~= nil; end
    local pr2, sc2, ev = prof.legacyDataPresent();
    check('NO46 legacy data found', pr2 and sc2, true);
    check('NO46b ...with the char named as evidence', ev, 'Testy_123');

    -- (NO47-NO50 -- firstRunInit's undecided contract, the flag-write retry
    -- and dataDir's native-first hold -- died in the purge, Phase 2, with the
    -- flag and the decision themselves. dataDir answers the native home,
    -- unconditionally: the manufactured-evidence family is undecidable-by-
    -- design now, not merely guarded.)
    check('NO47 firstRunInit is deleted with the decision', prof.firstRunInit, nil);
    local savedCharFolder = prof.charFolder;
    prof.charFolder = function() return 'Testy_123'; end   -- charBase resolves
    check('NO48 dataDir is the native home, nothing else',
          prof.dataDir(), 'I:\\game\\config\\addons\\dlac\\Testy_123\\');
    check('NO49 charRoot rides the same home', prof.charRoot(),
          'I:\\game\\config\\addons\\dlac\\Testy_123\\');
    prof.charFolder = savedCharFolder;

    prof._listDirs, prof._legacyProbe = savedList, savedProbe;
    AshitaCore = savedAC;
end)();

-- ---------------------------------------------------------------------------
-- EQC. equipcore (feature/native-engine part 1) -- the pure equip pipeline:
-- entry normalization, the set resolver, and the 0x050/0x051 packet builders.
-- Semantics are LuaAshitacast-parity (equip.lua is the reference); these pins
-- are what "a character flipping to native sees identical equips" MEANS.
-- ---------------------------------------------------------------------------
(function()
    local eqc = dofile('gear/equipcore.lua');
    package.loaded['dlac\\gear\\equipcore'] = eqc;

    -- --- entry normalization (MakeItemTable parity) ---
    local e = eqc.normalizeEntry('Miner\'s Helmet');
    check('EQC1 string entry lowercases',        e and e.Name, 'miner\'s helmet');
    check('EQC2 default priority 0',             e and e.Priority, 0);
    local r = eqc.normalizeEntry('remove');
    check('EQC3 remove pins Index 0 / P-100',    r and r.Index == 0 and r.Priority == -100, true);
    check('EQC4 ignore drops the slot',          eqc.normalizeEntry('ignore'), nil);
    local d = eqc.normalizeEntry('displaced');
    check('EQC5 displaced pins Index -1',        d and d.Index, -1);
    local t = eqc.normalizeEntry({ Name = 'Karin Obi', Bag = 'Wardrobe2', Priority = 3, Junk = 9 });
    check('EQC6 table entry: bag name resolves, junk dropped',
          t and t.Bag == 10 and t.Priority == 3 and t.Junk == nil, true);
    check('EQC7 nil/bad entries reject',         eqc.normalizeEntry(42), nil);

    -- --- fixture helpers ---
    local FULLJOBS = 2 ^ 23 - 1;
    local function mkItem(container, index, name, slot, o)
        o = o or {};
        return {
            Container = container, Index = index, Id = o.Id or 1000 + index,
            Count = o.Count or 1, Flags = o.Flags or 0,
            Name = name, Level = o.Level or 1,
            Jobs = o.Jobs or FULLJOBS,
            Slots = o.Slots or (2 ^ (slot - 1)),
            ResFlags = o.ResFlags or 0x800,
            augment = o.augment,
        };
    end
    local function mkSnap(o)
        o = o or {};
        return { job = o.job or 7, level = o.level or 75,
                 disabled = o.disabled or {}, encumbered = o.encumbered or {},
                 equipped = o.equipped or {}, items = o.items or {} };
    end

    -- --- resolver: the plain equip ---
    local snap = mkSnap({ items = {
        mkItem(8, 3, 'traveler\'s hat', 5),
        mkItem(0, 7, 'brass harness', 6),
    } });
    local plan = eqc.planSet({ Head = 'Traveler\'s Hat', Body = 'Brass Harness' }, snap);
    check('EQC8 two pieces resolve to two equips', #plan.equips, 2);
    check('EQC9 equal priority ties break to the lower slot',
          plan.equips[1].Slot == 4 and plan.equips[2].Slot == 5, true);   -- Head=5th slot -> 4, Body -> 5
    check('EQC10 equips carry index+container',
          plan.equips[1].Index == 3 and plan.equips[1].Container == 8, true);
    check('EQC11 nothing satisfied yet', plan.satisfied, false);

    -- --- already worn: satisfied, silent ---
    local worn = mkSnap({
        equipped = { [5] = mkItem(8, 3, 'traveler\'s hat', 5) },
        items    = { mkItem(8, 3, 'traveler\'s hat', 5) },
    });
    plan = eqc.planSet({ Head = 'Traveler\'s Hat' }, worn);
    check('EQC12 worn match = satisfied, no packets', plan.satisfied == true and #plan.equips == 0, true);

    -- --- remove semantics ---
    plan = eqc.planSet({ Head = 'remove' },
        mkSnap({ equipped = { [5] = mkItem(8, 3, 'traveler\'s hat', 5) } }));
    check('EQC13 remove on worn slot unequips (Index 0, worn container)',
          #plan.equips == 1 and plan.equips[1].Index == 0 and plan.equips[1].Container == 8, true);
    plan = eqc.planSet({ Head = 'remove' }, mkSnap({}));
    check('EQC14 remove on empty slot sends nothing', plan.satisfied == true and #plan.equips == 0, true);

    -- --- frozen slots ---
    plan = eqc.planSet({ Head = 'Traveler\'s Hat' },
        mkSnap({ disabled = { [5] = true }, items = { mkItem(8, 3, 'traveler\'s hat', 5) } }));
    check('EQC15 disabled slot never resolves', #plan.equips, 0);
    plan = eqc.planSet({ Head = 'Traveler\'s Hat' },
        mkSnap({ encumbered = { [5] = true }, items = { mkItem(8, 3, 'traveler\'s hat', 5) } }));
    check('EQC16 encumbered slot never resolves', #plan.equips, 0);

    -- --- priority ordering ---
    plan = eqc.planSet({
        Head = { Name = 'Traveler\'s Hat', Priority = 1 },
        Body = { Name = 'Brass Harness', Priority = 5 },
    }, mkSnap({ items = {
        mkItem(8, 3, 'traveler\'s hat', 5), mkItem(0, 7, 'brass harness', 6),
    } }));
    check('EQC17 higher priority equips first', plan.equips[1].Slot, 5);

    -- --- gates: level, job, slot bit, bag pin, bazaar, count ---
    plan = eqc.planSet({ Head = 'Traveler\'s Hat' },
        mkSnap({ level = 10, items = { mkItem(8, 3, 'traveler\'s hat', 5, { Level = 50 }) } }));
    check('EQC18 level gate drops the piece', #plan.equips, 0);
    plan = eqc.planSet({ Head = 'Traveler\'s Hat' },
        mkSnap({ job = 3, items = { mkItem(8, 3, 'traveler\'s hat', 5, { Jobs = 2 ^ 7 }) } }));
    check('EQC19 job gate drops the piece', #plan.equips, 0);
    plan = eqc.planSet({ Body = 'Traveler\'s Hat' },
        mkSnap({ items = { mkItem(8, 3, 'traveler\'s hat', 5) } }));
    check('EQC20 slot-bit mismatch drops the piece', #plan.equips, 0);
    plan = eqc.planSet({ Head = { Name = 'Traveler\'s Hat', Bag = 'Wardrobe' } },
        mkSnap({ items = { mkItem(0, 3, 'traveler\'s hat', 5) } }));
    check('EQC21 bag pin refuses the wrong bag', #plan.equips, 0);
    plan = eqc.planSet({ Head = 'Traveler\'s Hat' },
        mkSnap({ items = { mkItem(8, 3, 'traveler\'s hat', 5, { Flags = 19 }) } }));
    check('EQC22 bazaared item skipped', #plan.equips, 0);
    plan = eqc.planSet({ Head = 'Traveler\'s Hat' },
        mkSnap({ items = { mkItem(8, 3, 'traveler\'s hat', 5, { Count = 0 }) } }));
    check('EQC23 zero-count item skipped', #plan.equips, 0);
    plan = eqc.planSet({ Head = 'Traveler\'s Hat' },
        mkSnap({ items = { mkItem(8, 3, 'traveler\'s hat', 5, { ResFlags = 0 }) } }));
    check('EQC24 non-equippable flag skipped', #plan.equips, 0);

    -- --- augment pins ---
    local augItem = mkItem(8, 3, 'oneiros ring', 14, { augment = {
        Path = 'A', Rank = 15, Augs = { { String = 'STR+5' }, { String = 'Accuracy+3' } } } });
    plan = eqc.planSet({ Ring1 = { Name = 'Oneiros Ring', AugPath = 'A', AugRank = 15 } },
        mkSnap({ items = { augItem } }));
    check('EQC25 path+rank pin matches', #plan.equips, 1);
    plan = eqc.planSet({ Ring1 = { Name = 'Oneiros Ring', AugPath = 'B' } },
        mkSnap({ items = { augItem } }));
    check('EQC26 wrong path refuses', #plan.equips, 0);
    plan = eqc.planSet({ Ring1 = { Name = 'Oneiros Ring', Augment = { 'STR+5', 'Accuracy+3' } } },
        mkSnap({ items = { augItem } }));
    check('EQC27 augment string list matches', #plan.equips, 1);
    plan = eqc.planSet({ Ring1 = { Name = 'Oneiros Ring', Augment = 'VIT+5' } },
        mkSnap({ items = { augItem } }));
    check('EQC28 missing augment string refuses', #plan.equips, 0);
    plan = eqc.planSet({ Ring1 = { Name = 'Oneiros Ring', AugPath = 'A' } },
        mkSnap({ items = { mkItem(8, 3, 'oneiros ring', 14) } }));
    check('EQC29 pin vs unaugmented item refuses', #plan.equips, 0);

    -- --- AugKey pins (augment-split records): EXACT signature, never subset ---
    -- Two rolls of one item share a Name; the pin is what tells them apart, so a
    -- first-fit bag scan must skip the wrong roll even though its name matches.
    local rollA = mkItem(8, 3, 'hecatomb mittens +1', 7, { augment = { Key = '23:3|258:6|328:3' } });
    local rollB = mkItem(8, 4, 'hecatomb mittens +1', 7, { augment = { Key = '25:5|54:2' } });
    local ak = eqc.normalizeEntry({ Name = 'Hct. Mittens +1', AugKey = '23:3' });
    check('EQC29a normalizeEntry carries AugKey', ak and ak.AugKey, '23:3');
    plan = eqc.planSet({ Hands = { Name = 'Hecatomb Mittens +1', AugKey = '25:5|54:2' } },
        mkSnap({ items = { rollA, rollB } }));
    check('EQC29b AugKey picks its roll, not the first bag find',
          #plan.equips == 1 and plan.equips[1].Index == 4, true);
    plan = eqc.planSet({ Hands = { Name = 'Hecatomb Mittens +1', AugKey = '9:9' } },
        mkSnap({ items = { rollA, rollB } }));
    check('EQC29c an unowned signature refuses every copy', #plan.equips, 0);
    plan = eqc.planSet({ Hands = { Name = 'Hecatomb Mittens +1', AugKey = '23:3' } },
        mkSnap({ items = { rollA } }));
    check('EQC29d a partial signature is not a match (exact, never subset)', #plan.equips, 0);
    plan = eqc.planSet({ Hands = { Name = 'Hecatomb Mittens +1', AugKey = '' } },
        mkSnap({ items = { rollA, mkItem(8, 5, 'hecatomb mittens +1', 7) } }));
    check('EQC29e AugKey \'\' pins the unaugmented copy',
          #plan.equips == 1 and plan.equips[1].Index == 5, true);
    plan = eqc.planSet({ Hands = { Name = 'Hecatomb Mittens +1', AugKey = '25:5|54:2' } },
        mkSnap({ equipped = { [7] = rollB }, items = { rollA, rollB } }));
    check('EQC29f the worn matching roll satisfies (no re-equip)', plan.satisfied, true);
    plan = eqc.planSet({ Hands = { Name = 'Hecatomb Mittens +1', AugKey = '25:5|54:2' } },
        mkSnap({ equipped = { [7] = rollA }, items = { rollA, rollB } }));
    check('EQC29g a worn WRONG roll swaps to the right one',
          #plan.equips == 1 and plan.equips[1].Index == 4, true);

    -- --- one instance never fills two slots; second copy does ---
    plan = eqc.planSet({ Ring1 = 'Reraise Ring', Ring2 = 'Reraise Ring' },
        mkSnap({ items = { mkItem(8, 3, 'reraise ring', 14, { Slots = 2^13 + 2^14 }) } }));
    check('EQC30 single instance fills exactly one ring', #plan.equips, 1);
    plan = eqc.planSet({ Ring1 = 'Reraise Ring', Ring2 = 'Reraise Ring' },
        mkSnap({ items = {
            mkItem(8, 3, 'reraise ring', 14, { Slots = 2^13 + 2^14 }),
            mkItem(8, 4, 'reraise ring', 14, { Slots = 2^13 + 2^14 }),
        } }));
    check('EQC31 two instances fill both rings', #plan.equips, 2);

    -- --- conflicts: claimed instance worn elsewhere unreserved ---
    local swordWorn = mkItem(0, 9, 'bronze sword', 2, { Slots = 2^0 + 2^1 });   -- worn in Sub
    plan = eqc.planSet({ Main = 'Bronze Sword' },
        mkSnap({ equipped = { [2] = swordWorn }, items = { swordWorn } }));
    check('EQC32 worn-elsewhere instance claims produce a conflict unequip',
          #plan.conflicts == 1 and plan.conflicts[1].Slot == 1, true);
    check('EQC33 ...and the equip itself', #plan.equips == 1 and plan.equips[1].Slot == 0, true);
    -- when the worn slot's own entry claims it, it is reserved: not stealable
    plan = eqc.planSet({ Main = 'Bronze Sword', Sub = 'Bronze Sword' },
        mkSnap({ equipped = { [2] = swordWorn }, items = { swordWorn } }));
    check('EQC34 reserved instance is not stealable (Sub keeps it, Main unresolved)',
          #plan.equips == 0 and #plan.conflicts == 0, true);

    -- --- displaced: a stamp, never a packet. LAC parity pin: a set that is
    -- otherwise satisfied early-returns BEFORE displaced handling (equip.lua's
    -- FlagEquippedItems short-circuit), so displaced-only sets do nothing;
    -- the stamp rides only when the set has real work.
    plan = eqc.planSet({ Ammo = 'displaced' }, mkSnap({}));
    check('EQC35a displaced-only set is satisfied silence (LAC parity)',
          plan.satisfied == true and #plan.equips == 0 and #plan.stamps == 0, true);
    plan = eqc.planSet({ Ammo = 'displaced', Head = 'Traveler\'s Hat' },
        mkSnap({ items = { mkItem(8, 3, 'traveler\'s hat', 5) } }));
    check('EQC35b displaced stamps (no packet) when the set does work',
          #plan.equips == 1 and #plan.stamps == 2, true);

    -- --- packet builders (byte goldens) ---
    local p50 = eqc.build0x50(12, 4, 8);
    check('EQC36 0x50 bytes: index/slot/container at 5/6/7',
          p50[5] == 12 and p50[6] == 4 and p50[7] == 8 and #p50 == 8, true);
    local un = eqc.buildUnequip0x50(4, 8);
    check('EQC37 unequip is 0x50 with index 0', un[5] == 0 and un[6] == 4 and un[7] == 8, true);
    local p51 = eqc.build0x51({
        { Slot = 4, Index = 3, Container = 8 },
        { Slot = 5, Index = 7, Container = 0 },
    });
    check('EQC38 0x51 count byte', p51[5], 2);
    check('EQC39 0x51 first entry at offset 9',  p51[9] == 3 and p51[10] == 4 and p51[11] == 8, true);
    check('EQC40 0x51 second entry at offset 13', p51[13] == 7 and p51[14] == 5 and p51[15] == 0, true);
    check('EQC41 0x51 is 72 bytes', #p51, 72);

    -- --- style choice ---
    check('EQC42 auto under 9 = singles', eqc.chooseStyle(8), 'single');
    check('EQC43 auto at 9 = equipset',   eqc.chooseStyle(9), 'set');
    check('EQC44 explicit set wins',      eqc.chooseStyle(2, 'set'), 'set');
    check('EQC45 explicit single wins',   eqc.chooseStyle(12, 'single'), 'single');

    -- The threshold is a PARAMETER now (/dl gearpackets), and the default has
    -- to stay 9 or 'default' mode stops being LAC parity -- which is the one
    -- promise the whole equip pipeline makes.
    check('EQC46a the default threshold is byte parity', eqc.AUTO_THRESHOLD, 9);
    check('EQC46b ...and an absent argument still means 9',
          eqc.chooseStyle(8) == 'single' and eqc.chooseStyle(9) == 'set', true);
    check('EQC47a a lower threshold batches sooner',
          eqc.chooseStyle(3, 'auto', 3), 'set');
    check('EQC47b ...and still leaves smaller plans alone',
          eqc.chooseStyle(2, 'auto', 3), 'single');
    check('EQC47c threshold 1 batches everything',
          eqc.chooseStyle(1, 'auto', 1), 'set');
    check('EQC48a an explicit style ignores the threshold',
          eqc.chooseStyle(1, 'single', 1), 'single');
    check('EQC48b garbage falls back to the default threshold',
          eqc.chooseStyle(8, 'auto', 'x'), 'single');
end)();

-- ---------------------------------------------------------------------------
-- EQE. equipengine (feature/native-engine part 2) -- the pure half of the
-- action pipeline: byte readers, the chunk parser, the ACTION_ROUTES table,
-- completion math, the 0x028 decode, and the augment header decode.
-- ---------------------------------------------------------------------------
(function()
    local eng = dofile('feature/equipengine.lua');
    package.loaded['dlac\\feature\\equipengine'] = eng;

    -- bit-writer helper: the inverse of bitsAt (LSB-first within bytes)
    local function packStr(len, writes)
        local bytes = {};
        for i = 1, len do bytes[i] = 0; end
        for _, w in ipairs(writes) do
            local bitOff, nbits, value = w[1], w[2], w[3];
            for i = 0, nbits - 1 do
                local bit = math.floor(value / (2 ^ i)) % 2;
                if bit == 1 then
                    local pos = bitOff + i;
                    local bi = math.floor(pos / 8) + 1;
                    bytes[bi] = bytes[bi] + 2 ^ (pos % 8);
                end
            end
        end
        local out = {};
        for i = 1, len do out[i] = string.char(bytes[i]); end
        return table.concat(out);
    end

    -- --- byte readers ---
    local s = string.char(0x34, 0x12, 0x78, 0x56);
    check('EQE1 u16at little-endian', eng.u16at(s, 0), 0x1234);
    check('EQE2 u32at little-endian', eng.u32at(s, 0), 0x56781234);
    check('EQE3 u16at past end reads zeros', eng.u16at(s, 10), 0);
    local bs = packStr(4, { { 10, 4, 9 } });   -- 4 bits at bit 10 = 9
    check('EQE4 bitsAt round-trips the writer', eng.bitsAt(bs, 0, 10, 4), 9);
    check('EQE5 bitsAt with byte offset', eng.bitsAt(bs, 1, 2, 4), 9);   -- same bits, byte-relative

    -- --- chunk parsing: id 9 bits, size 7 bits in 4-byte units ---
    local function header(id, sizeBytes)
        local w = id + math.floor(sizeBytes / 4) * 512;
        return string.char(w % 256, math.floor(w / 256));
    end
    local pkt1 = header(0x1A, 8) .. string.rep('\1', 6);
    local pkt2 = header(0x15, 4) .. string.rep('\2', 2);
    local chunk = pkt1 .. pkt2;
    local parsed = eng.parseChunk(chunk);
    check('EQE6 chunk yields both packets', #parsed, 2);
    check('EQE7 first packet id/size/off', parsed[1].id == 0x1A and parsed[1].size == 8 and parsed[1].off == 0, true);
    check('EQE8 second packet id/off', parsed[2].id == 0x15 and parsed[2].off == 8, true);
    check('EQE9 torn header stops the walk', #eng.parseChunk(string.char(0, 0, 1, 1)), 0);

    -- --- action + item-use field decode ---
    local act = string.rep('\0', 8) .. string.char(0x21, 0x00)   -- target 0x21 at 0x08
        .. string.char(0x03, 0x00)                               -- category 3 at 0x0A
        .. string.char(0x38, 0x00);                              -- action id 0x38 at 0x0C
    local a = eng.parseAction(act);
    check('EQE10 action fields decode', a.target == 0x21 and a.category == 3 and a.actionId == 0x38, true);
    local itm = string.rep('\0', 12) .. string.char(0x44, 0x00)  -- target at 0x0C
        .. string.char(0x07)                                     -- item index at 0x0E
        .. string.char(0x00) .. string.char(0x08);               -- container at 0x10
    local u = eng.parseItemUse(itm);
    check('EQE11 item-use fields decode', u.target == 0x44 and u.itemIndex == 7 and u.container == 8, true);

    -- --- routes: the dispatch-point table ---
    check('EQE12 spell route', eng.routeOf(0x03).pre == 'Precast' and eng.routeOf(0x03).mid == 'Midcast', true);
    check('EQE13 ws route has no midcast', eng.routeOf(0x07).pre == 'Weaponskill' and eng.routeOf(0x07).mid == nil, true);
    check('EQE14 ranged route', eng.routeOf(0x10).pre == 'Preshot' and eng.routeOf(0x10).mid == 'Midshot', true);
    check('EQE15 unhandled category is nil', eng.routeOf(0x0F), nil);
    check('EQE16 precast styles: spell=set, ability=auto',
          eng.routeOf(0x03).preStyle == 'set' and eng.routeOf(0x09).preStyle == 'auto', true);

    -- --- completion math (LAC formulas) ---
    local S = { FastCast = 0, Snapshot = 0, SpellOffset = 1.0, RangedBase = 10.0,
                RangedOffset = 0.5, WeaponskillDelay = 3.0, AbilityDelay = 2.5,
                ItemBase = 8, ItemOffset = 1.0 };
    check('EQE17 spell completion = cast/4 + offset',
          eng.completionOf(eng.routeOf(3), 32, S, 100), 100 + 8 + 1.0);
    S.FastCast = 50;
    check('EQE18 fast cast halves the base', eng.completionOf(eng.routeOf(3), 32, S, 100), 100 + 4 + 1.0);
    check('EQE19 ranged completion', eng.completionOf(eng.routeOf(16), nil, S, 100), 100 + 10 + 0.5);
    S.Snapshot = 50;
    check('EQE20 snapshot halves ranged base', eng.completionOf(eng.routeOf(16), nil, S, 100), 100 + 5 + 0.5);
    check('EQE21 ws fixed delay', eng.completionOf(eng.routeOf(7), nil, S, 100), 103.0);
    check('EQE22 item with cast time', eng.itemCompletionOf(40, S, 100), 100 + 10 + 1.0);
    check('EQE23 item without resource', eng.itemCompletionOf(nil, S, 100), 100 + 8 + 1.0);

    -- --- 0x028 decode ---
    local p28 = packStr(24, {
        { 0x05 * 8, 32, 123456 },   -- userId u32 at byte 5
        { 10 * 8 + 2, 4, 4 },       -- actionType 4 (complete)
    });
    local d28 = eng.parse0x28(p28);
    check('EQE24 0x28 userId + type', d28.userId == 123456 and d28.actionType == 4, true);
    check('EQE25 type 4 is a completion type', eng.ACTION_COMPLETE_TYPES[4], true);
    local p28i = packStr(24, {
        { 0x05 * 8, 32, 123456 },
        { 10 * 8 + 2, 4, 8 },        -- type 8 (ranged/magic)
        { 10 * 8 + 6, 16, 28787 },   -- the interrupt magic
    });
    local d28i = eng.parse0x28(p28i);
    check('EQE26 interrupt magic decodes', d28i.actionType == 8 and d28i.interrupted == true, true);
    local p28n = packStr(24, { { 0x05 * 8, 32, 1 }, { 10 * 8 + 2, 4, 8 }, { 10 * 8 + 6, 16, 100 } });
    check('EQE27 type 8 without magic is not an interrupt', eng.parse0x28(p28n).interrupted, false);

    -- --- augment header decode ---
    check('EQE28 unaugmented extra is nil', eng.parseAugmentHeader(string.char(0, 0, 0, 0)), nil);
    local delve = packStr(24, { { 0, 8, 2 }, { 8, 8, 0x20 }, { 16, 2, 1 }, { 18, 4, 9 } });
    local pa = eng.parseAugmentHeader(delve);
    check('EQE29 delve path+rank', pa.Type == 'Delve' and pa.Path == 'B' and pa.Rank == 9, true);
    local dyna = packStr(24, { { 0, 8, 2 }, { 8, 8, 131 }, { 32, 2, 2 }, { 50, 5, 20 } });
    local da = eng.parseAugmentHeader(dyna);
    check('EQE30 dynamis path+rank', da.Type == 'Dynamis' and da.Path == 'C' and da.Rank == 20, true);
    local magian = packStr(24, { { 0, 8, 3 }, { 8, 8, 0x40 }, { 80, 15, 5432 } });
    local ma = eng.parseAugmentHeader(magian);
    check('EQE31 magian trial', ma.Type == 'Magian' and ma.Trial == 5432, true);
    local oseem = packStr(24, { { 0, 8, 2 }, { 8, 8, 0 } });
    check('EQE32 plain augment type is Oseem', eng.parseAugmentHeader(oseem).Type, 'Oseem');
    check('EQE33 synth-shield flag is nil', eng.parseAugmentHeader(packStr(4, { { 0, 8, 2 }, { 8, 8, 0x08 } })), nil);

    -- --- the buffer merge (through the real equipSet door) ---
    eng.bufferClear();
    eng.equipSet({ Head = 'Cap A' });
    eng.equipSet({ Head = 'Cap B', Body = 'Harness' });
    eng.equipSet({ Body = 'ignore' });
    local buf = eng._bufferPeek();
    check('EQE34 buffer merge: later write wins, ignore clears',
          buf[5] == 'Cap B' and buf[6] == nil, true);
    eng.equipSet({ [11] = 'Karin Obi' });   -- numeric slot keys ride too
    check('EQE35 numeric slot keys accepted', eng._bufferPeek()[11], 'Karin Obi');
    eng.bufferClear();
    check('EQE36 clear empties the buffer', next(eng._bufferPeek()), nil);

    -- --- encumbrance: the 0x01B word at 0x60, one bit per equip slot ---
    -- Head is equip index 4 (bit 4), Legs is 7. The same word equipmon reads as
    -- a u32 and masks with 1<<slot -- if these two ever disagree, one of them is
    -- drawing a cross over the wrong box.
    local enc = packStr(0x64, { { 0x60 * 8 + 4, 1, 1 }, { 0x60 * 8 + 7, 1, 1 } });
    eng.readEncumbrance(enc);
    check('EQE37 a set bit lands on the 1-based slot id', eng.state.encumbered[5], true);
    check('EQE38 isEncumbered takes the 0-BASED equip index',
          eng.isEncumbered(4) == true and eng.isEncumbered(7) == true, true);
    check('EQE39 a clear bit is not encumbered', eng.isEncumbered(0), false);
    check('EQE40 a garbage index never claims a lock', eng.isEncumbered(nil), false);
    -- ...and the read happens with the engine DISARMED. These bits are the only
    -- source the floating bar's cross has, and the bar draws on whichever engine
    -- you run -- before the hoist they were gated behind nativeOn() and a legacy
    -- player never saw a bit set at all.
    for i = 1, 16 do eng.state.encumbered[i] = false; end
    local savedTrip = eng.state.tripped;
    eng.state.tripped = true;                -- nativeOn() is false whatever else is set
    eng.handleIncoming({ id = 0x01B, data = enc });
    check('EQE41 0x01B is read with the engine disarmed', eng.isEncumbered(4), true);
    eng.state.tripped = savedTrip;
    -- A word with nothing set CLEARS: encumbrance lifting is another 0x01B, not
    -- a separate packet, so a stale true would strike out a slot forever.
    eng.readEncumbrance(packStr(0x64, {}));
    check('EQE42 an empty word clears every slot', eng.isEncumbered(4), false);
end)();

-- ---------------------------------------------------------------------------
-- NEB. native backend wiring (feature/native-engine step 5) -- the arming
-- rules and the pet-stream decode. The dispatch-side seams (engineActive,
-- the native sets store, engineEquipSet) are exercised through the 2600+
-- LAC-state checks above staying green: flag off = byte-identical behavior.
-- ---------------------------------------------------------------------------
(function()
    local eng = package.loaded['dlac\\feature\\equipengine'];
    local prof = package.loaded['dlac\\profiles'];

    -- arming rules: the addon state arms only with the flag on; the LAC state
    -- REFUSES even with the flag on (two interceptors = the hazard); a fired
    -- tripwire disarms.
    local savedNative, savedGFunc = prof.nativeMode, rawget(_G, 'gFunc');
    prof.nativeMode = function() return true; end
    _G.gFunc = nil;
    check('NEB1 addon state + flag on = armed', eng.nativeOn(), true);
    _G.gFunc = {};
    check('NEB2 LAC state refuses even with the flag on', eng.nativeOn(), false);
    _G.gFunc = nil;
    eng.state.tripped = true;
    check('NEB3 tripwire disarms', eng.nativeOn(), false);
    eng.state.tripped = false;
    prof.nativeMode = function() return false; end
    check('NEB4 flag off = not armed', eng.nativeOn(), false);
    prof.nativeMode = savedNative;
    _G.gFunc = savedGFunc;

    -- the pet 0x28 field decode (actionId at bit 213, message at byte 28 bit 6)
    local function packStr(len, writes)
        local bytes = {};
        for i = 1, len do bytes[i] = 0; end
        for _, w in ipairs(writes) do
            for i = 0, w[2] - 1 do
                if math.floor(w[3] / (2 ^ i)) % 2 == 1 then
                    local pos = w[1] + i;
                    bytes[math.floor(pos / 8) + 1] = bytes[math.floor(pos / 8) + 1] + 2 ^ (pos % 8);
                end
            end
        end
        local out = {};
        for i = 1, len do out[i] = string.char(bytes[i]); end
        return table.concat(out);
    end
    local pkt = packStr(40, { { 213, 17, 900 }, { 28 * 8 + 6, 10, 43 } });
    local pp = eng.parse0x28Pet(pkt);
    check('NEB5 pet actionId decodes', pp.actionId, 900);
    check('NEB6 pet mobskill message decodes', pp.message, 43);
end)();

-- ---------------------------------------------------------------------------
-- CHOCOBO DIGGING: digcalc odds math (hand-computed pools) + digdata shape +
-- fail-soft loading -- PRD #93 / issue #94, docs/design/chocobo-dig.md. The
-- odds are derived BY HAND from the PRD formula:
--   mu   = 1.5 - |moonPhase - 50| / 50
--   q_i  = min(1, weight_i / (1000 * mu))   (0 if rank < requirement_i)
--   S    = 1 - PROD_i (1 - q_i)
--   P_i  = q_i * INT_0^1 PROD_{j!=i}(1 - q_j + q_j*t) dt
--   (1) On a hit = P_i / S   (sums to ~1 within a pool)
--   (2) Per dig  = P_i       (sums to S)
-- If a port edit moves one of these numbers, re-derive from the formula before
-- touching the test. The math tests use SYNTHETIC pools (no digdata), mirroring
-- fishcalc's F1-F14; the shape/fail-soft tests exercise the shipped table.
-- ---------------------------------------------------------------------------
(function()
    local dc = dofile('feature/digcalc.lua');
    package.loaded['dlac\\feature\\digcalc'] = dc;
    local function r6(x) return math.floor((tonumber(x) or 0) * 1e6 + 0.5) / 1e6; end

    -- moon multiplier: best (0.5) at new/full, worst (1.5) at half; clamps.
    check('DC1 moon new  -> 0.5', dc.moonMult(0), 0.5);
    check('DC2 moon full -> 0.5', dc.moonMult(100), 0.5);
    check('DC3 moon half -> 1.5', dc.moonMult(50), 1.5);
    check('DC4 moon clamps below 0',  dc.moonMult(-40), 0.5);
    check('DC5 moon clamps above 100', dc.moonMult(140), 0.5);
    check('DC6 moon default (nil) = half', dc.moonMult(nil), 1.5);

    -- qualify probability q = min(1, w/(1000*mu)); best moon lifts a mid weight
    -- to certainty, worst moon thins it.
    check('DC7 qualify neutral', dc.qualify(500, 1), 0.5);
    check('DC8 qualify caps at 1', dc.qualify(1000, 1), 1);
    check('DC9 qualify best moon caps a 500-weight', dc.qualify(500, 0.5), 1);
    check('DC10 qualify worst moon thins to 1/3', r6(dc.qualify(500, 1.5)), r6(1/3));
    check('DC11 qualify zero weight -> 0', dc.qualify(0, 1), 0);

    -- two-item pool {500, 1000} at mu=1: q1=0.5, q2=1 -> S=1, P1=0.25, P2=0.75.
    local two = dc.poolOdds({ { id = 1, n = 'a', w = 500, rank = 0 },
                              { id = 2, n = 'b', w = 1000, rank = 0 } }, 8, 1);
    check('DC12 pool success S = 1', two.S, 1);
    check('DC13 P1 (per dig) = 0.25', r6(two.items[1].perDig), 0.25);
    check('DC14 P2 (per dig) = 0.75', r6(two.items[2].perDig), 0.75);
    check('DC15 on-a-hit share 1', r6(two.items[1].onHit), 0.25);
    check('DC16 on-a-hit share 2', r6(two.items[2].onHit), 0.75);
    local sPerDig = two.items[1].perDig + two.items[2].perDig;
    local sOnHit  = two.items[1].onHit + two.items[2].onHit;
    check('DC17 (2) per-dig sums to S',   r6(sPerDig), r6(two.S));
    check('DC18 (1) on-a-hit sums to ~1', r6(sOnHit), 1);

    -- symmetric three-item pool, w=100 each, mu=1: q=0.1, S=1-0.9^3=0.271,
    -- P_i=0.1*INT(0.9+0.1t)^2 = 0.0903333..., on-a-hit = 1/3 each.
    local three = dc.poolOdds({ { id = 1, n = 'a', w = 100, rank = 0 },
                                { id = 2, n = 'b', w = 100, rank = 0 },
                                { id = 3, n = 'c', w = 100, rank = 0 } }, 8, 1);
    check('DC19 three-item S = 0.271', r6(three.S), 0.271);
    check('DC20 three-item P_i', r6(three.items[1].P), r6(0.0903333333));
    check('DC21 three-item on-a-hit = 1/3', r6(three.items[2].onHit), r6(1/3));
    local t3 = three.items[1].P + three.items[2].P + three.items[3].P;
    check('DC22 three-item per-dig sums to S', r6(t3), r6(three.S));

    -- rank-gating: item 2 needs rank 5, player is rank 3 -> locked, q2=0, it
    -- drops out and reshapes the surviving share to 100%.
    local gated = dc.poolOdds({ { id = 1, n = 'a', w = 500, rank = 0 },
                                { id = 2, n = 'b', w = 1000, rank = 5 } }, 3, 1);
    check('DC23 over-rank item is locked', gated.items[2].locked, true);
    check('DC24 locked item q = 0',        gated.items[2].q, 0);
    check('DC25 locked item per-dig = 0',  gated.items[2].perDig, 0);
    check('DC26 surviving S = 0.5',        r6(gated.S), 0.5);
    check('DC27 surviving on-a-hit reshaped to 1', r6(gated.items[1].onHit), 1);
    check('DC28 active-item count drops to 1', gated.n, 1);

    -- moon applied correctly: a single 500-weight item is a certainty at best
    -- moon (S=1) and thins to 1/3 at worst.
    local mBest  = dc.poolOdds({ { id = 1, n = 'a', w = 500, rank = 0 } }, 8, dc.moonMult(0));
    local mWorst = dc.poolOdds({ { id = 1, n = 'a', w = 500, rank = 0 } }, 8, dc.moonMult(50));
    check('DC29 best moon -> S = 1',        r6(mBest.S), 1);
    check('DC30 worst moon -> S = 1/3',     r6(mWorst.S), r6(1/3));
    check('DC31 best moon beats worst',     mBest.S > mWorst.S, true);

    -- an asymmetric four-item pool at an off-neutral moon: the sum invariants
    -- must still hold exactly (the identity SUM P_i = S).
    local four = dc.poolOdds({ { id = 1, n = 'a', w = 300, rank = 0 },
                               { id = 2, n = 'b', w = 700, rank = 0 },
                               { id = 3, n = 'c', w = 250, rank = 0 },
                               { id = 4, n = 'd', w = 900, rank = 0 } }, 8, 1.2);
    local fp, fh = 0, 0;
    for _, it in ipairs(four.items) do fp = fp + it.perDig; fh = fh + it.onHit; end
    check('DC32 asymmetric per-dig sums to S', r6(fp), r6(four.S));
    check('DC33 asymmetric on-a-hit sums to 1', r6(fh), 1);

    -- digSuccess combines independent pools: two pools each with S=0.5 ->
    -- 1 - 0.5*0.5 = 0.75.
    local half = { { id = 1, n = 'x', w = 500, rank = 0 } };   -- S = 0.5 at mu=1
    check('DC34 general dig-success across pools', r6(dc.digSuccess({ half, half }, 8, 1)), 0.75);

    -- empty pool: S = 0, no items, no divide-by-zero.
    local empty = dc.poolOdds({}, 8, 1);
    check('DC35 empty pool S = 0', empty.S, 0);
    check('DC36 empty pool no items', #empty.items, 0);

    -- ---- digdata shape (the shipped table the guide trusts) ----
    dc._setDb(dofile('data/digdata.lua'));
    local db = dc.db();
    check('DC37 digdata loads', db ~= nil, true);
    check('DC38 rank ladder is 0..10', db.ranks and #db.ranks, 10);   -- [0]..[10] -> #=10
    check('DC38b Expert is rank 10',  db.ranks[10], 'Expert');
    check('DC39 Novice is rank 3',    db.ranks[3], 'Novice');
    check('DC40 Craftsman is rank 6', db.ranks[6], 'Craftsman');
    check('DC41 zones is a table',    type(db.zones), 'table');
    -- conditional rule tables: maps + gates, well-formed.
    local cond = dc.conditionals();
    check('DC42 conditionals present', type(cond), 'table');
    check('DC43 crystal gate ~10%, no rank', cond.crystals.chance == 10 and cond.crystals.minRank == 0, true);
    local nEl = 0; for _ in pairs(cond.crystals.byElement) do nEl = nEl + 1; end
    check('DC44 crystals cover 8 elements', nEl, 8);
    check('DC45 Fire crystal/cluster ids', cond.crystals.byElement.Fire.crystal == 4096
        and cond.crystals.byElement.Fire.cluster == 4104, true);
    check('DC46 Dark crystal/cluster ids', cond.crystals.byElement.Dark.crystal == 4103
        and cond.crystals.byElement.Dark.cluster == 4111, true);
    check('DC47 rock gate ~5% >= Novice', cond.rocks.chance == 5 and cond.rocks.minRank == 3, true);
    check('DC48 rock day->element map (Firesday=Fire)', cond.rocks.byDay.Firesday, 'Fire');
    local nDay = 0; for _ in pairs(cond.rocks.byDay) do nDay = nDay + 1; end
    check('DC49 rock day map has 8 days', nDay, 8);
    check('DC50 ore gate ~10% >= Craftsman', cond.ores.chance == 10 and cond.ores.minRank == 6, true);
    check('DC51 ore needs elemental weather', cond.ores.requiresElementalWeather, true);
    check('DC52 ore moon-phase window 7..21', cond.ores.moonPhaseWindow.min == 7 and cond.ores.moonPhaseWindow.max == 21, true);
    check('DC53 ore day->element map (Darksday=Dark)', cond.ores.byDay.Darksday, 'Dark');
    check('DC54 ore has a zone set', type(cond.ores.zones), 'table');

    -- every zone entry that IS present is well-formed (positive weights, valid
    -- pools, ranks in 0..8) -- guards a bad regeneration; passes vacuously while
    -- `zones` is empty pending the maintainer regen (see digdata's DATA STATUS).
    local VALID_POOL = { Treasure = true, Regular = true, Bore = true, Burrow = true };
    local zoneCount, badZone = 0, nil;
    for zid, z in pairs(db.zones) do
        zoneCount = zoneCount + 1;
        if type(z.n) ~= 'string' or type(z.pools) ~= 'table' then badZone = badZone or zid; end
        for pool, list in pairs(z.pools or {}) do
            if not VALID_POOL[pool] then badZone = badZone or ('pool:' .. tostring(pool)); end
            for _, it in ipairs(list) do
                if type(it.id) ~= 'number' or (tonumber(it.w) or 0) <= 0
                   or (tonumber(it.rank) or -1) < 0 or (tonumber(it.rank) or 99) > 8 then
                    badZone = badZone or ('item@' .. tostring(zid));
                end
            end
        end
    end
    check('DC55 every present zone is well-formed', badZone, nil);
    -- Once regenerated the table must hold exactly the 26 enabled zones; until
    -- then it is empty and the guide's by-zone queries fail soft. This asserts
    -- the invariant is one of those two honest states, never a partial mess.
    check('DC56 zone count is 0 (pending regen) or exactly 26', zoneCount == 0 or zoneCount == 26, true);

    -- ---- fail-soft: absent table disables data queries, never errors ----
    dc._setDb(false);
    check('DC57 absent db -> db() nil',        dc.db(), nil);
    check('DC58 absent db -> zoneIds empty',   #dc.zoneIds(), 0);
    check('DC59 absent db -> zoneOdds nil',    dc.zoneOdds(100, 8, 1), nil);
    check('DC60 absent db -> conditionals nil', dc.conditionals(), nil);
    -- pure math still works with no db (it never touches it)
    check('DC61 math works without a db', dc.poolOdds({ { id = 1, n = 'a', w = 500, rank = 0 } }, 8, 1).S, 0.5);
    dc._setDb(nil);   -- restore lazy load for any later section
end)();

-- ---------------------------------------------------------------------------
-- CHOCOBO DIG RANK + guide scaffold (issue #97, PRD #93): the pure rank
-- estimator (digrank -- ratchet / server-read decode / effective-rank resolve /
-- Obtained parse / item->rank lookup), the pure moon math (vanamoon), and
-- digcalc.averageSuccess for the general dig-success figure. All headless.
-- ---------------------------------------------------------------------------
(function()
    local dr = dofile('feature/digrank.lua');
    local vm = dofile('feature/vanamoon.lua');
    local dc = dofile('feature/digcalc.lua');
    local function r6(x) return math.floor((tonumber(x) or 0) * 1e6 + 0.5) / 1e6; end

    -- ---- digrank.clamp: snaps into 0..10, floors garbage to 0 ----
    check('DR1 clamp keeps in-range', dr.clamp(4), 4);
    check('DR2 clamp floors below 0', dr.clamp(-3), 0);
    check('DR3 clamp caps above 10',  dr.clamp(50), 10);
    check('DR3b MAX_RANK is Expert (10)', dr.MAX_RANK, 10);
    check('DR3c ladder labels Veteran + Expert', tostring(dr.RANKS[9]) .. '/' .. tostring(dr.RANKS[10]), 'Veteran/Expert');
    check('DR4 clamp rounds',         dr.clamp(3.6), 4);
    check('DR5 clamp nil -> 0',       dr.clamp(nil), 0);

    -- ---- ratchet: one-way, never lowers ----
    check('DR6 ratchet raises to a higher requirement', dr.ratchet(2, 5), 5);
    check('DR7 ratchet ignores a lower requirement',    dr.ratchet(5, 2), 5);
    check('DR8 ratchet equal stays',                    dr.ratchet(4, 4), 4);
    check('DR9 ratchet nil req leaves floor',           dr.ratchet(3, nil), 3);
    check('DR10 ratchet clamps a wild requirement',     dr.ratchet(0, 99), 10);
    -- monotonic across a sequence of digs (never dips)
    local floor, mono = 0, true;
    for _, req in ipairs({ 1, 3, 2, 6, 4, 5, 8, 7 }) do
        local nf = dr.ratchet(floor, req);
        if nf < floor then mono = false; end
        floor = nf;
    end
    check('DR11 ratchet is monotonic over a dig sequence', mono and floor, 8);

    -- ---- serverRank: masked read -> nil; real in-range -> rank ----
    check('DR12 masked 0xFFFF -> nil',        dr.serverRank(0xFFFF), nil);
    check('DR13 rank 31 (masked decode) -> nil', dr.serverRank(31), nil);
    check('DR14 a real rank 4 word -> 4',     dr.serverRank(4), 4);
    check('DR15 rank word 8 (Adept) -> 8',    dr.serverRank(8), 8);
    check('DR15b rank word 9 (Veteran) -> 9', dr.serverRank(9), 9);
    check('DR15c rank word 10 (Expert) -> 10', dr.serverRank(10), 10);
    check('DR16 out-of-ladder word 11 -> nil', dr.serverRank(11), nil);
    check('DR17 nil word -> nil',             dr.serverRank(nil), nil);

    -- ---- parseObtained: the dig "Obtained: <item>" line ----
    check('DR18 parses a plain Obtained line', dr.parseObtained('Obtained: Wind Crystal.'), 'Wind Crystal');
    check('DR19 tolerates no trailing period', dr.parseObtained('Obtained: Handful of Sand'), 'Handful of Sand');
    check('DR20 non-Obtained line -> nil',     dr.parseObtained('You dig and you dig...but find nothing.'), nil);
    check('DR21 nil line -> nil',              dr.parseObtained(nil), nil);
    -- inline chat colour/control codes (0x1E/0x1F + palette byte, stray controls)
    -- must not survive into the name -- else the ratchet lookup silently misses.
    check('DR21a strips a colour tag + param', dr._stripCodes('\30\06Wind Crystal\30\01'), 'Wind Crystal');
    check('DR21b strips a stray control byte', dr._stripCodes('Bird\1 Egg'), 'Bird Egg');
    check('DR21c clean text is untouched',     dr._stripCodes('Copper Ore'), 'Copper Ore');
    check('DR21d parse: name wrapped in colour codes', dr.parseObtained('Obtained: \30\06Wind Crystal\30\01.'), 'Wind Crystal');
    check('DR21e parse: a code AFTER the period', dr.parseObtained('Obtained: Maple Log.\31\02'), 'Maple Log');
    -- CASE-INSENSITIVE + prefix (the field bug: an item dig moved no rank because
    -- the tag casing / a leading prefix slipped past the old fixed-case pattern).
    -- The name must come back in its ORIGINAL case (the ratchet norm()s, but the
    -- announce shows it verbatim). Modeled on hgather's string.lower().match().
    check('DR21f ALL-CAPS tag still parses',    dr.parseObtained('OBTAINED: Chunk of Gold Ore.'), 'Chunk of Gold Ore');
    check('DR21g a leading prefix before tag',  dr.parseObtained('You dig and dig! Obtained: Bag of Fruit Seeds.'), 'Bag of Fruit Seeds');
    check('DR21h keeps original display case',  dr.parseObtained('obtained: Chunk of Platinum Ore.'), 'Chunk of Platinum Ore');
    check('DR21i classify ALL-CAPS -> obtained', ({dr.classifyDigLine('OBTAINED: Chunk of Gold Ore.')})[1], 'obtained');

    -- ---- itemRequirement: min rank across every source, fail-soft ----
    local SYNTH = { zones = {
        [100] = { n = 'A', pools = {
            Bore   = { { id = 1, n = 'Copper Ore', w = 500, rank = 2 } },
            Burrow = { { id = 2, n = 'Bird Egg',   w = 300, rank = 0 } },
        } },
        [101] = { n = 'B', pools = {
            Treasure = { { id = 1, n = 'Copper Ore', w = 400, rank = 5 } },   -- same item, harder here
        } },
    } };
    check('DR22 requirement = the MIN across sources', dr.itemRequirement('Copper Ore', SYNTH), 2);
    check('DR23 requirement is name-insensitive',      dr.itemRequirement('copper ORE.', SYNTH), 2);
    check('DR24 a rank-0 item',                        dr.itemRequirement('Bird Egg', SYNTH), 0);
    check('DR25 unknown item -> nil (no ratchet)',     dr.itemRequirement('Adaman Ore', SYNTH), nil);
    check('DR26 nil db -> nil (fail soft)',            dr.itemRequirement('Copper Ore', nil), nil);
    -- the M2 fix end-to-end: a colour-coded name still resolves its requirement
    -- (norm strips codes on BOTH sides), so the ratchet fires instead of missing.
    check('DR26a colour-coded name still resolves', dr.itemRequirement('\30\06Copper Ore\30\01', SYNTH), 2);
    -- itemRequirementById: the fail-safe 0x02A packet carries the id; prefer the
    -- CURRENT zone's requirement (you dug it here), else the cheapest zone.
    check('DR26b by-id = cheapest zone when no zone given', dr.itemRequirementById(1, SYNTH), 2);
    check('DR26c by-id prefers the CURRENT zone (harder here)', dr.itemRequirementById(1, SYNTH, 101), 5);
    check('DR26d by-id current zone (cheaper here)', dr.itemRequirementById(1, SYNTH, 100), 2);
    check('DR26e by-id a rank-0 item', dr.itemRequirementById(2, SYNTH), 0);
    check('DR26f unknown id -> nil (no ratchet)', dr.itemRequirementById(999, SYNTH), nil);
    check('DR26g nil id -> nil', dr.itemRequirementById(nil, SYNTH), nil);
    check('DR26h nil db -> nil (fail soft)', dr.itemRequirementById(1, nil), nil);
    -- ---- conditional (weather/day-gated) drops: crystals / rocks / ores ----
    -- These live in db.cond, NOT the zone pools, so the ratchet must scan them or a
    -- dug rock/ore raises no floor (the field gap). crystals gate at 0 (they are
    -- also rank-0 pool drops), day rocks at Novice(3), elemental ores at Craftsman(6).
    local COND = {
        zones = {
            [100] = { n = 'A', pools = {
                Regular = { { id = 4096, n = 'Fire Crystal', w = 50, rank = 0 } },      -- crystal: pool(0) + cond(0)
            } },
            [101] = { n = 'B', pools = {
                -- pretend Red Rock is ALSO a hard pool drop here (rank 8) to prove the
                -- ratchet takes the SAFE MIN with its rank-3 conditional, not the pool.
                Treasure = { { id = 769, n = 'Red Rock', w = 5, rank = 8 } },
            } },
        },
        cond = {
            crystals = { minRank = 0, byElement = { Fire = { crystal = 4096, cluster = 4104 } } },
            rocks    = { minRank = 3, byElement = { Fire = { id = 769,  n = 'Red Rock' } } },
            ores     = { minRank = 6, byElement = { Fire = { id = 1255, n = 'Chunk of Fire Ore' } } },
        },
    };
    check('DR26i cond by name: rock -> Novice(3)',   dr.condRequirement(COND, nil, 'Red Rock'), 3);
    check('DR26j cond by name: ore -> Craftsman(6)', dr.condRequirement(COND, nil, 'Chunk of Fire Ore'), 6);
    check('DR26k cond by id: rock',                  dr.condRequirement(COND, 769), 3);
    check('DR26l cond by id: ore',                   dr.condRequirement(COND, 1255), 6);
    check('DR26m cond by id: crystal -> 0',          dr.condRequirement(COND, 4096), 0);
    check('DR26n cond by id: cluster -> 0',          dr.condRequirement(COND, 4104), 0);
    check('DR26o crystal has no cond name -> nil',   dr.condRequirement(COND, nil, 'Fire Crystal'), nil);
    check('DR26p cond unknown id -> nil',            dr.condRequirement(COND, 999), nil);
    check('DR26q cond nil db -> nil (fail soft)',    dr.condRequirement(nil, 769), nil);
    -- THE GAP FIX: a conditional-ONLY ore now ratchets (returned nil before)
    check('DR26r ore ratchets by NAME (was nil)',    dr.itemRequirement('Chunk of Fire Ore', COND), 6);
    check('DR26s ore ratchets by ID (was nil)',      dr.itemRequirementById(1255, COND), 6);
    -- Red Rock is BOTH a rank-3 conditional and a (harder) rank-8 pool drop: the
    -- ratchet takes the SAFE MIN, and the zone-aware tighten must NOT over-claim the
    -- pool rank even when you dug it in that very zone.
    check('DR26t rock name = MIN(pool 8, cond 3)',      dr.itemRequirement('Red Rock', COND), 3);
    check('DR26u rock id = MIN(pool 8, cond 3)',        dr.itemRequirementById(769, COND), 3);
    check('DR26v rock id: cond beats the zone tighten', dr.itemRequirementById(769, COND, 101), 3);
    -- crystal is a rank-0 pool drop AND a rank-0 conditional -> 0 (never a floor)
    check('DR26w crystal by id = 0',                 dr.itemRequirementById(4096, COND, 100), 0);
    check('DR26x crystal by name = 0 (via pool)',    dr.itemRequirement('Fire Crystal', COND), 0);

    -- ---- resolve: precedence + honest exact flag ----
    local ranks = { [0]='Amateur',[1]='Recruit',[2]='Initiate',[3]='Novice',[4]='Apprentice',
                    [5]='Journeyman',[6]='Craftsman',[7]='Artisan',[8]='Adept' };
    local rManual = dr.resolve(3, 0, nil, ranks);
    check('DR27 manual seed drives the rank',   rManual.rank, 3);
    check('DR28 manual source labelled',        rManual.source, 'manual');
    check('DR29 manual is NOT exact',           rManual.exact, false);
    check('DR30 rank label resolved',           rManual.label, 'Novice');
    local rRatchet = dr.resolve(2, 5, nil, ranks);
    check('DR31 a floor above the pick wins',   rRatchet.rank, 5);
    check('DR32 ratchet source labelled',       rRatchet.source, 'ratchet');
    check('DR33 ratchet source label text',     rRatchet.sourceLabel, '>= from digs');
    check('DR34 ratchet is an estimate',        rRatchet.exact, false);
    local rBelow = dr.resolve(6, 3, nil, ranks);
    check('DR35 a floor below the pick is ignored', rBelow.rank, 6);
    check('DR36 ...and stays manual',               rBelow.source, 'manual');
    local rServer = dr.resolve(2, 4, 7, ranks);
    check('DR37 a server read beats both estimates', rServer.rank, 7);
    check('DR38 server source labelled',             rServer.source, 'server');
    check('DR39 server read IS exact',               rServer.exact, true);
    check('DR40 server source label text',           rServer.sourceLabel, 'reported by server');

    -- ---- gate: the grey-out verdict, where "never lie" lives ----
    check('DR40a reachable item is ok',            dr.gate(3, rManual), 'ok');   -- req 3 <= rank 3
    check('DR40b over an ESTIMATE -> dimmed',      dr.gate(5, rManual), 'dimmed');
    check('DR40c over an EXACT rank -> locked',    dr.gate(8, rServer), 'locked');  -- req 8 > exact 7
    check('DR40d exact but reachable -> ok',       dr.gate(7, rServer), 'ok');
    check('DR40e a bare rank number works too',    dr.gate(5, 2), 'dimmed');   -- no state = estimate
    check('DR40f a nil requirement is never gated', dr.gate(nil, rServer), 'ok');

    -- ---- timing rank detection (issue #100): classify + invert the first-dig
    --      zone cooldown clamp(60 - 5*rank, 10, 60) ----
    check('DT1 obtained line -> tag + item', (function()
        local t, i = dr.classifyDigLine('Obtained: Wind Crystal.'); return t .. '/' .. tostring(i);
    end)(), 'obtained/Wind Crystal');
    check('DT2 free reject -> wait',        dr.classifyDigLine('You must wait a little while longer.'), 'wait');
    check('DT3 "wait longer" phrasing -> wait', dr.classifyDigLine('You must wait longer to perform that action.'), 'wait');
    check('DT4 nothing-found -> nothing',   dr.classifyDigLine('You dig and you dig...but find nothing.'), 'nothing');
    check('DT5 with-ease -> ease',          dr.classifyDigLine('The chocobo digs with ease.'), 'ease');
    check('DT6 a non-dig line -> nil',      dr.classifyDigLine('Someone casts Fire.'), nil);
    check('DT7 nil line -> nil',            dr.classifyDigLine(nil), nil);
    -- completed-dig predicate (only these carry a usable first-dig timing)
    check('DT8 obtained is a completed dig', dr.isCompletedDig('obtained'), true);
    check('DT9 nothing is a completed dig',  dr.isCompletedDig('nothing'), true);
    check('DT10 ease is a completed dig',    dr.isCompletedDig('ease'), true);
    check('DT11 a reject is NOT a completed dig', dr.isCompletedDig('wait'), false);
    -- invert the cooldown: threshold seconds -> rank (round to the 5s rung)
    check('DT12 60s -> Amateur (0)',   dr.rankFromZoneTiming(60), 0);
    check('DT13 20s -> Adept (8)',     dr.rankFromZoneTiming(20), 8);
    check('DT14 15s -> Veteran (9)',   dr.rankFromZoneTiming(15), 9);
    check('DT15 10s -> Expert (10)',   dr.rankFromZoneTiming(10), 10);
    check('DT16 Henrik: 11s -> Expert (10)', dr.rankFromZoneTiming(11), 10);   -- field data
    check('DT17 sub-floor (<10s) still Expert', dr.rankFromZoneTiming(4), 10);  -- 10s clamp floor
    check('DT18 a late dig reads a low rank (never negative)', dr.rankFromZoneTiming(300), 0);
    -- FLOOR into the 5s rung, never ROUND: lag only ever pushes the observed
    -- delay LATER, so each rank is a [C, C+5) bracket (Henrik field 2026-07-24).
    check('DT19 13s (lagged Expert) FLOORS to Expert, not Veteran', dr.rankFromZoneTiming(13), 10);  -- round gave 9
    check('DT19a 14.9s (top of the Expert bracket) -> Expert', dr.rankFromZoneTiming(14.9), 10);
    check('DT19b 15s (next bracket) -> Veteran',      dr.rankFromZoneTiming(15), 9);
    check('DT19c 17s stays within Veteran',           dr.rankFromZoneTiming(17), 9);
    check('DT19d 19.9s (top of Veteran) -> Veteran',  dr.rankFromZoneTiming(19.9), 9);
    check('DT19e 24.9s (top of Adept) -> Adept',      dr.rankFromZoneTiming(24.9), 8);
    check('DT20 non-number threshold -> nil', dr.rankFromZoneTiming('soon'), nil);
    check('DT21 non-positive threshold -> nil', dr.rankFromZoneTiming(0), nil);

    -- ---- vanamoon: pure moon math ----
    check('VM1 percent in 0..100 across the whole cycle', (function()
        for d = 0, 200 do local p = vm.percent(d); if type(p) ~= 'number' or p < 0 or p > 100 then return false; end end
        return true;
    end)(), true);
    -- symmetric around the Full midpoint: age a and (CYCLE-a) share a percent.
    check('VM2 illumination is symmetric about Full', (function()
        for a = 1, 41 do
            local dayLow  = a - vm.OFFSET;              -- age a
            local dayHigh = (vm.CYCLE - a) - vm.OFFSET; -- age CYCLE-a
            if vm.percent(dayLow) ~= vm.percent(dayHigh) then return false; end
        end
        return true;
    end)(), true);
    check('VM3 New Moon (age 0) is 0%',  vm.percent(0 - vm.OFFSET), 0);
    check('VM4 Full Moon (age 42) is 100%', vm.percent(42 - vm.OFFSET), 100);
    check('VM5 waxing before Full', vm.waxing(10 - vm.OFFSET), true);
    check('VM6 waning after Full',  vm.waxing(60 - vm.OFFSET), false);
    check('VM7 New Moon named',  vm.name(0 - vm.OFFSET),  'New Moon');
    check('VM8 Full Moon named', vm.name(42 - vm.OFFSET), 'Full Moon');
    check('VM9 phase() bundles the fields', (function()
        local ph = vm.phase(42 - vm.OFFSET);
        return type(ph) == 'table' and ph.percent == 100 and ph.name == 'Full Moon';
    end)(), true);
    check('VM10 bad day -> nil (graceful)', vm.phase(nil), nil);
    -- SERVER-CONVENTION pins (absolute day numbers, NOT relative to OFFSET) --
    -- these lock vanamoon to moon::get_phase in src/common/vana_time.h, where
    -- daysmod=(day+26)%84: daysmod 0 (day 58) = 100% Full, daysmod 42 (day 16)
    -- = 0% New, daysmod<42 waning, daysmod>42 waxing. VM1-VM10 only test the
    -- internal curve shape and never caught the epoch being half a cycle off.
    check('VM11 day 58 (daysmod 0) is 100% Full', vm.percent(58), 100);
    check('VM12 day 58 named Full Moon',          vm.name(58),    'Full Moon');
    check('VM13 day 16 (daysmod 42) is 0% New',   vm.percent(16), 0);
    check('VM14 day 16 named New Moon',            vm.name(16),    'New Moon');
    check('VM15 day 79 (daysmod 21) is waning',   vm.waxing(79),  false);
    check('VM16 day 37 (daysmod 63) is waxing',   vm.waxing(37),  true);

    -- ---- digcalc.averageSuccess: the general dig-success figure ----
    dc._setDb(false);
    check('DR41 averageSuccess nil when no data', dc.averageSuccess(8, 1), nil);
    dc._setDb({ zones = {
        [1] = { n = 'X', pools = { Bore = { { id = 1, n = 'a', w = 500, rank = 0 } } } },   -- S = 0.5 at mu=1
        [2] = { n = 'Y', pools = { Bore = { { id = 2, n = 'b', w = 1000, rank = 0 } } } },  -- S = 1   at mu=1
    } });
    local avg, nz = dc.averageSuccess(8, 1);
    check('DR42 averageSuccess = mean of zone S', r6(avg), r6((0.5 + 1) / 2));
    check('DR43 averageSuccess reports zone count', nz, 2);
    -- rank-gating flows through: an over-rank pool zeroes out -> success 0.
    dc._setDb({ zones = { [1] = { n = 'X', pools = { Bore = { { id = 1, n = 'a', w = 500, rank = 5 } } } } } });
    check('DR44 averageSuccess honours rank-gating', r6((dc.averageSuccess(0, 1))), 0);
    dc._setDb(nil);   -- restore lazy load
end)();

-- ---------------------------------------------------------------------------
-- CHOCOBO BY-AREA: the pure data seams the by-area tab composes (issue #98,
-- PRD #93) -- digcalc.zones (the zone-picker source) and digcalc.conditionalDrops
-- (weather crystal / day rock / elemental ore resolved against the live clock,
-- flagged active/inactive). Uses the SHIPPED digdata (26 zones + the FFXI-standard
-- cond tables); the odds math itself is covered by DC1-61. All headless.
-- ---------------------------------------------------------------------------
(function()
    local dc = dofile('feature/digcalc.lua');
    package.loaded['dlac\\feature\\digcalc'] = dc;
    dc._setDb(dofile('data/digdata.lua'));

    -- ---- zones(): the sorted { id, n } zone-picker source ----
    local zl = dc.zones();
    check('BA1 zones() lists the 26 enabled zones', #zl, 26);
    check('BA2 zones() is sorted by name', (function()
        for i = 2, #zl do if tostring(zl[i - 1].n) > tostring(zl[i].n) then return false; end end
        return true;
    end)(), true);
    check('BA3 each zone entry has id + name', (function()
        for _, z in ipairs(zl) do
            if type(z.id) ~= 'number' or type(z.n) ~= 'string' then return false; end
        end
        return true;
    end)(), true);

    -- ---- _normElement: the Thunder/Lightning + non-elemental normalisation ----
    check('BA4 Thunder normalises to Lightning', dc._normElement('Thunder'), 'Lightning');
    check('BA5 an ordinary element passes through', dc._normElement('Fire'), 'Fire');
    check('BA6 None/Clear/empty -> nil (no elemental weather)',
        dc._normElement('None') == nil and dc._normElement('Clear') == nil and dc._normElement('') == nil, true);

    -- ---- conditionalDrops on an ORE zone under a fully-satisfied clock ----
    -- Zone 104 (Jugner Forest) is one of the 9 elemental-ore zones. Firesday +
    -- Fire weather + moon 14% + rank 8 satisfies every gate.
    local clkFull = { dayElement = 'Fire', weatherElement = 'Fire', doubleWeather = false, moonPercent = 14 };
    local cd = dc.conditionalDrops(104, 8, clkFull);
    check('BA7 ore zone lists crystal + rock + ore', #cd, 3);
    local byKind = {}; for _, r in ipairs(cd) do byKind[r.kind] = r; end
    check('BA8 crystal is the Fire Crystal (id + name)',
        byKind.crystal and byKind.crystal.id == 4096 and byKind.crystal.n, 'Fire Crystal');
    check('BA9 crystal active under Fire weather', byKind.crystal.active, true);
    check('BA10 rock is the Fire day rock', byKind.rock and byKind.rock.id == 769 and byKind.rock.n, 'Red Rock');
    check('BA11 rock active at rank 8 (>= Novice)', byKind.rock.active, true);
    check('BA12 ore is the Fire ore', byKind.ore and byKind.ore.id == 1255 and byKind.ore.n, 'Chunk of Fire Ore');
    check('BA13 ore active under the full gate', byKind.ore.active, true);

    -- ---- rank-gating flows through (active is clockActive AND rankOk) ----
    local cdLow = dc.conditionalDrops(104, 0, clkFull);
    local lowByKind = {}; for _, r in ipairs(cdLow) do lowByKind[r.kind] = r; end
    check('BA14 crystal still active at rank 0 (no rank gate)', lowByKind.crystal.active, true);
    check('BA15 rock inactive at rank 0 but the clock condition IS met',
        lowByKind.rock.active == false and lowByKind.rock.clockActive == true, true);
    check('BA16 ore inactive at rank 0 (Craftsman gate) though the clock is met',
        lowByKind.ore.active == false and lowByKind.ore.clockActive == true, true);

    -- ---- the Thunder alias resolves the live weather to the Lightning crystal ----
    local cdThunder = dc.conditionalDrops(2, 8, { dayElement = 'Lightning', weatherElement = 'Thunder', moonPercent = 50 });
    local thByKind = {}; for _, r in ipairs(cdThunder) do thByKind[r.kind] = r; end
    check('BA17 Thunder weather -> Lightning Crystal id 4100',
        thByKind.crystal and thByKind.crystal.id, 4100);

    -- ---- a NON-ore zone omits the ore row entirely ----
    local cdNoOre = dc.conditionalDrops(2, 8, clkFull);   -- zone 2 is not an ore zone
    check('BA18 non-ore zone lists only crystal + rock', #cdNoOre, 2);
    check('BA19 ...and no ore row', (function()
        for _, r in ipairs(cdNoOre) do if r.kind == 'ore' then return 'ore present'; end end
        return true;
    end)(), true);

    -- ---- double weather yields the cluster, not the crystal ----
    local cdDbl = dc.conditionalDrops(2, 8, { dayElement = 'Fire', weatherElement = 'Fire', doubleWeather = true, moonPercent = 50 });
    local dblByKind = {}; for _, r in ipairs(cdDbl) do dblByKind[r.kind] = r; end
    check('BA20 double Fire weather -> Fire Cluster (id 4104)',
        dblByKind.crystal and dblByKind.crystal.id == 4104 and dblByKind.crystal.n, 'Fire Cluster');

    -- ---- the ore gate: weather must match the day, moon must be in-window ----
    local cdMoon = dc.conditionalDrops(104, 8, { dayElement = 'Fire', weatherElement = 'Fire', moonPercent = 50 });
    local moonByKind = {}; for _, r in ipairs(cdMoon) do moonByKind[r.kind] = r; end
    check('BA21 ore inactive when the moon is out of the 7-21% window',
        moonByKind.ore.active == false and moonByKind.ore.clockActive == false, true);
    local cdWeather = dc.conditionalDrops(104, 8, { dayElement = 'Fire', weatherElement = 'Ice', moonPercent = 14 });
    local wByKind = {}; for _, r in ipairs(cdWeather) do wByKind[r.kind] = r; end
    check('BA22 ore inactive when the weather does not match the day', wByKind.ore.clockActive, false);
    check('BA23 ...but that same off-element Ice weather lights the Ice crystal',
        wByKind.crystal and wByKind.crystal.id, 4097);

    -- ---- no elemental weather: the crystal row is inactive, never errors ----
    local cdClear = dc.conditionalDrops(2, 8, { dayElement = 'Fire', weatherElement = 'None', moonPercent = 14 });
    local clByKind = {}; for _, r in ipairs(cdClear) do clByKind[r.kind] = r; end
    check('BA24 no elemental weather -> crystal inactive, no concrete id',
        clByKind.crystal.clockActive == false and clByKind.crystal.id == nil, true);

    -- ---- fail soft: no db -> empty results, never an error ----
    dc._setDb(false);
    check('BA25 absent db -> zones() empty', #dc.zones(), 0);
    check('BA26 absent db -> conditionalDrops() empty', #dc.conditionalDrops(104, 8, clkFull), 0);
    dc._setDb(nil);   -- restore lazy load
end)();

-- ---------------------------------------------------------------------------
-- CHOCOBO BY-ITEM: the pure data seams the by-item tab composes (issue #99,
-- PRD #93) -- digcalc.itemIndex (the fuzzy-search source, pool items PLUS the
-- synthesised conditional crystals/rocks/ores) and digcalc.itemSources (every
-- zone + pool a selected item drops from, priced + flagged). Uses the SHIPPED
-- digdata; the odds math itself is DC1-61. All headless, PURE (clock passed in).
-- ---------------------------------------------------------------------------
(function()
    local dc = dofile('feature/digcalc.lua');
    package.loaded['dlac\\feature\\digcalc'] = dc;
    dc._setDb(dofile('data/digdata.lua'));

    -- ---- itemIndex(): the searchable diggable-item index ----
    local idx = dc.itemIndex();
    check('BI1 itemIndex is non-empty (120 pool items + 32 conditionals)', #idx, 152);
    check('BI2 itemIndex is sorted by name', (function()
        for i = 2, #idx do if tostring(idx[i - 1].n) > tostring(idx[i].n) then return false; end end
        return true;
    end)(), true);
    local byKey = {}; for _, e in ipairs(idx) do byKey[e.key] = e; end
    -- the conditional crystals / clusters / rocks / ores are keyed by condKind:el
    -- (a conditional item can SHARE a name with a static pool drop -- Fire Crystal
    -- is both a weather conditional AND a listed pool item in some zones -- so the
    -- index carries a distinct entry for each; assert by key, not by name).
    check('BI3 Fire Crystal (conditional) is in the index, id 4096',
        byKey['crystal:Fire'] and byKey['crystal:Fire'].id == 4096
        and byKey['crystal:Fire'].n == 'Fire Crystal'
        and byKey['crystal:Fire'].kind == 'conditional'
        and byKey['crystal:Fire'].condKind, 'crystal');
    check('BI4 Fire Cluster is in the index (conditional cluster, id 4104)',
        byKey['cluster:Fire'] and byKey['cluster:Fire'].id == 4104
        and byKey['cluster:Fire'].n == 'Fire Cluster'
        and byKey['cluster:Fire'].condKind, 'cluster');
    check('BI5 Chunk of Fire Ore is in the index (ore, minRank 6)',
        byKey['ore:Fire'] and byKey['ore:Fire'].id == 1255
        and byKey['ore:Fire'].n == 'Chunk of Fire Ore'
        and byKey['ore:Fire'].condKind == 'ore'
        and byKey['ore:Fire'].minRank, 6);
    check('BI6 Red Rock is in the index (rock, minRank 3 = Novice)',
        byKey['rock:Fire'] and byKey['rock:Fire'].n == 'Red Rock'
        and byKey['rock:Fire'].condKind == 'rock'
        and byKey['rock:Fire'].minRank, 3);
    check('BI7 exactly 32 conditional entries (8 each: crystal/cluster/rock/ore)', (function()
        local c = 0; for _, e in ipairs(idx) do if e.kind == 'conditional' then c = c + 1; end end
        return c;
    end)(), 32);
    check('BI8 a pool entry carries a pool key + kind', (function()
        local e = byKey['pool:3509'];   -- Plate of Heavy Metal
        return e and e.kind == 'pool' and e.n or false;
    end)(), 'Plate of Heavy Metal');

    -- ---- itemSources() on a POOL item present in many zones ----
    -- Plate of Heavy Metal (3509) drops in 22 zones; price at rank 8, neutral moon.
    local plate = byKey['pool:3509'];
    local ps = dc.itemSources(plate, 8, dc.moonMult(50), {});
    check('BI9 pool itemSources returns a pool view', type(ps) == 'table'
        and ps.kind == 'pool' and ps.allZones == false, true);
    check('BI10 pool sources cover the 22 zones it drops in', #ps.sources, 22);
    check('BI11 each pool source carries zone + pool + the two odds', (function()
        for _, s in ipairs(ps.sources) do
            if type(s.zoneId) ~= 'number' or type(s.zoneName) ~= 'string'
               or type(s.pool) ~= 'string' or type(s.onHit) ~= 'number'
               or type(s.perDig) ~= 'number' then return false; end
        end
        return true;
    end)(), true);
    check('BI12 pool sources are sorted by per-dig descending', (function()
        for i = 2, #ps.sources do
            if (ps.sources[i - 1].perDig or 0) < (ps.sources[i].perDig or 0) then return false; end
        end
        return true;
    end)(), true);

    -- ---- itemSources() on a CONDITIONAL crystal: EVERY digging zone ----
    -- Fire Crystal under Fire weather (single) is active in all 26 zones.
    local fc = byKey['crystal:Fire'];
    local cs = dc.itemSources(fc, 8, dc.moonMult(50),
        { weatherElement = 'Fire', dayElement = 'Ice', doubleWeather = false, moonPercent = 50 });
    check('BI13 crystal itemSources spans every enabled zone (allZones)', cs.allZones == true and #cs.sources, 26);
    check('BI14 crystal active now under matching single weather', cs.active, true);
    check('BI15 crystal condition is spelled out', cs.condition, 'Fire weather up');
    -- double Fire weather yields the CLUSTER, so the single crystal is inactive.
    local csDbl = dc.itemSources(fc, 8, dc.moonMult(50),
        { weatherElement = 'Fire', doubleWeather = true, moonPercent = 50 });
    check('BI16 single crystal inactive under DOUBLE weather (that is the cluster)', csDbl.active, false);
    -- the Thunder/Lightning alias resolves the live weather to the Lightning crystal.
    local lc = byKey['crystal:Lightning'];
    local ls = dc.itemSources(lc, 8, dc.moonMult(50), { weatherElement = 'Thunder', moonPercent = 50 });
    check('BI17 Thunder weather activates the Lightning Crystal', ls.active, true);

    -- ---- itemSources() on the CLUSTER: active only under double weather ----
    local fcl = byKey['cluster:Fire'];
    local cls = dc.itemSources(fcl, 8, dc.moonMult(50), { weatherElement = 'Fire', doubleWeather = true, moonPercent = 50 });
    check('BI18 cluster active under double weather', cls.active, true);
    check('BI19 cluster condition names the double weather', cls.condition, 'double Fire weather');

    -- ---- itemSources() on an ORE: only the 9 elemental-ore zones ----
    local ore = byKey['ore:Fire'];
    local os = dc.itemSources(ore, 8, dc.moonMult(14),
        { dayElement = 'Fire', weatherElement = 'Fire', moonPercent = 14 });
    check('BI20 ore itemSources spans only the ore zones (not all-zone)', os.allZones == false and #os.sources, 9);
    check('BI21 ore active under the full gate (rank 8, Fire day+weather, moon 14%)', os.active, true);
    -- rank gate: below Craftsman the ore is not reachable though the clock is met.
    local osLow = dc.itemSources(ore, 0, dc.moonMult(14),
        { dayElement = 'Fire', weatherElement = 'Fire', moonPercent = 14 });
    check('BI22 ore rankOk false at rank 0 though the clock is met',
        osLow.rankOk == false and osLow.clockActive == true and osLow.active == false, true);
    -- moon out of window closes the clock gate.
    local osMoon = dc.itemSources(ore, 8, dc.moonMult(50),
        { dayElement = 'Fire', weatherElement = 'Fire', moonPercent = 50 });
    check('BI23 ore clock closes when the moon is out of the 7-21% window', osMoon.clockActive, false);

    -- ---- a locked pool item over-rank: the row carries the locked flag ----
    -- King Truffle (Carpenters Landing Treasure) needs rank 8; at rank 0 it locks.
    local kt = byKey['pool:4386'];
    if kt ~= nil then
        local kts = dc.itemSources(kt, 0, dc.moonMult(50), {});
        check('BI24 an over-rank pool item marks its source locked', (function()
            for _, s in ipairs(kts.sources) do if s.locked ~= true then return false; end end
            return #kts.sources > 0;
        end)(), true);
    end

    -- ---- fail soft: no db / nil entry -> empty index, nil sources ----
    dc._setDb(false);
    check('BI25 absent db -> itemIndex empty', #dc.itemIndex(), 0);
    check('BI26 absent db -> itemSources nil', dc.itemSources(plate, 8, 1, {}), nil);
    dc._setDb(dofile('data/digdata.lua'));
    check('BI27 nil entry -> itemSources nil', dc.itemSources(nil, 8, 1, {}), nil);
    dc._setDb(nil);   -- restore lazy load
end)();

-- ---------------------------------------------------------------------------
-- ML. modeslibrary -- the Mode library pure core (ADR 0019, 2026-07-24).
-- Own function scope (a do-block's locals share the chunk's 200 budget).
-- ---------------------------------------------------------------------------
;(function()
    local ml = dofile('gear/modeslibrary.lua');
    -- A broken plan can hand back nil where a list is expected. table.concat would
    -- then CRASH the whole suite and hide every later check, so render nil instead --
    -- a regression must fail loudly and locally, not take the run down with it.
    local function join(t)
        if type(t) ~= 'table' then return '(nil)'; end
        return table.concat(t, ',');
    end
    check('ML1 module loads headless', type(ml), 'table');

    -- Entry construction. kind is DERIVED from the values, never trusted, because
    -- `def.values ~= nil` is the sole cycle test everywhere else in dlac.
    local tog = ml.makeEntry('DT', nil, 'F9');
    check('ML2 no values -> toggle',    tog.kind, 'toggle');
    check('ML3 toggle keeps its bind',  tog.bind, 'F9');
    local cyc = ml.makeEntry('Weapon', { 'Melee', 'Ranged', 'Caster' }, '^F3');
    check('ML4 values -> cycle',        cyc.kind, 'cycle');
    check('ML5 cycle keeps order',      join(cyc.values), 'Melee,Ranged,Caster');
    check('ML6 blank name refused',     (select(2, ml.makeEntry('  ', nil, nil))), 'A mode needs a name.');
    check('ML7 one-value cycle refused',(select(2, ml.makeEntry('X', { 'Only' }, nil))), 'A cycle needs at least two values.');
    check('ML8 values dedupe case-insensitively',
        join(ml.makeEntry('W', { 'Melee', 'melee', 'Ranged' }).values), 'Melee,Ranged');
    check('ML9 blank values dropped',
        join(ml.makeEntry('W', { 'A', '', '  ', 'B' }).values), 'A,B');

    -- Engine-owned names must never become library entries.
    check('ML10 maxmp is reserved',     ml.isReserved('maxmp'), true);
    check('ML11 craft is reserved',     ml.isReserved('CRAFT'), true);
    check('ML12 craftgoal is reserved', ml.isReserved('craftgoal'), true);
    check('ML13 ordinary name is not',  ml.isReserved('Weapon'), false);
    check('ML14 reserved name refused at capture',
        (ml.makeEntry('maxmp', nil, nil) == nil), true);

    -- toDef: a bare toggle MUST serialize as {} and not nil -- an empty definition is
    -- load-bearing (it is what keeps a plain toggle listed across a commit round-trip).
    local d = ml.toDef(ml.makeEntry('DT'));
    check('ML15 bare toggle def is a table', type(d), 'table');
    check('ML16 bare toggle def is empty',   next(d), nil);

    -- ---- THE STAMP ----
    local job = {
        Weapon = { values = { 'Melee', 'Ranged', 'Caster' }, bind = '^F3' },
        DT = {},
    };

    -- create
    local p = ml.stampPlan(ml.makeEntry('TH', nil, nil), job, 'append');
    check('ML17 new name is a create', p.action, 'create');
    check('ML18 create collides with nothing', p.collides, false);
    check('ML19 create strands nothing', #p.dead, 0);

    -- append merges and NEVER drops
    p = ml.stampPlan(ml.makeEntry('Weapon', { 'Ranged', 'Tank' }), job, 'append');
    check('ML20 append action',            p.action, 'append');
    check('ML21 append keeps every old value', join(p.after), 'Melee,Ranged,Caster,Tank');
    check('ML22 append strands nothing',   #p.dead, 0);
    check('ML23 append reports what is new', join(p.added), 'Tank');
    check('ML24 append keeps the existing bind', p.bindTo, '^F3');

    -- overwrite drops, and names exactly what died
    p = ml.stampPlan(ml.makeEntry('Weapon', { 'Melee', 'Tank' }), job, 'overwrite');
    check('ML25 overwrite action',       p.action, 'overwrite');
    check('ML26 overwrite replaces',     join(p.after), 'Melee,Tank');
    check('ML27 overwrite names the dead', join(p.dead), 'Ranged,Caster');
    check('ML28 dead targets are Name:Value',
        table.concat(ml.deadTargets(p), ' '), 'Weapon:Ranged Weapon:Caster');
    -- (Every cycle below needs >= 2 values or makeEntry refuses it and stampPlan gets
    -- a nil -- which would make these pass for the wrong reason. ML29a proves the
    -- plan actually exists before ML29 trusts its emptiness.)
    local appendPlan = ml.stampPlan(ml.makeEntry('Weapon', { 'Tank', 'Melee' }), job, 'append');
    check('ML29a append plan really exists', type(appendPlan), 'table');
    check('ML29 append produces no strip targets', #ml.deadTargets(appendPlan), 0);

    -- THE REGRESSION THIS EXISTS FOR: a TOGGLE stamped onto a CYCLE. Under Append the
    -- cycle must KEEP its values -- demoting it would silently kill every Name:Value
    -- reference, which is the exact thing Append promises not to do. Overwrite is how
    -- you demote on purpose, and then every value is correctly reported dead.
    p = ml.stampPlan(ml.makeEntry('Weapon', nil, nil), job, 'append');
    check('ML30 append refuses to demote a cycle', p.kind, 'cycle');
    check('ML31 append demote strands nothing',    #p.dead, 0);
    check('ML32 append demote keeps values', join(p.after), 'Melee,Ranged,Caster');
    p = ml.stampPlan(ml.makeEntry('Weapon', nil, nil), job, 'overwrite');
    check('ML33 overwrite CAN demote a cycle', p.kind, 'toggle');
    check('ML34 demotion kills every value',
        join(p.dead), 'Melee,Ranged,Caster');

    -- adding values to an existing TOGGLE deletes nothing
    p = ml.stampPlan(ml.makeEntry('DT', { 'Low', 'High' }), job, 'append');
    check('ML35 toggle -> cycle is not destructive', #p.dead, 0);
    check('ML36 toggle -> cycle takes the values', join(p.after), 'Low,High');

    -- the EXISTING spelling wins, so references keep pointing at the same key
    p = ml.stampPlan(ml.makeEntry('weapon', { 'Melee', 'Ranged' }), job, 'append');
    check('ML37 collision keeps the stored spelling', p.name, 'Weapon');

    -- a stamp that changes literally nothing says so
    p = ml.stampPlan(ml.makeEntry('Weapon', { 'Melee', 'Ranged', 'Caster' }, '^F3'), job, 'append');
    check('ML38 no-op stamp is flagged', p.action, 'rebind');

    -- applyStamp never mutates the caller's map (so a plan can be abandoned)
    local before = ml.stampPlan(ml.makeEntry('Weapon', { 'Zzz', 'Yyy' }), job, 'overwrite');
    local newMap = ml.applyStamp(ml.makeEntry('Weapon', { 'Zzz', 'Yyy' }), job, 'overwrite');
    check('ML39 original map untouched',
        join(job.Weapon.values), 'Melee,Ranged,Caster');
    check('ML40 new map has the new values',
        join(newMap.Weapon.values), 'Zzz,Yyy');
    check('ML41 untouched modes survive', type(newMap.DT), 'table');
    check('ML42 plan and apply agree', before.action, 'overwrite');
    -- a differently-cased duplicate key must not survive the write
    local dup = ml.applyStamp(ml.makeEntry('weapon', { 'A', 'B' }), { Weapon = { values = { 'A' } } }, 'overwrite');
    check('ML43 no duplicate-cased key', (dup['weapon'] == nil), true);
    check('ML44 canonical key kept',     type(dup['Weapon']), 'table');

    -- ML44a-ML44f. A STAMP MUST NOT EAT THE JOB'S MODE LOCKS (2026-08-03, ADR
    -- 0034). Locks name THIS job's sets, so they never travel in a library entry
    -- -- which made applyStamp's fresh-def rebuild delete them, on APPEND too:
    -- the branch whose whole promise is "no value disappears, so no reference can
    -- break". A stamp changes values and binds and has no opinion about which
    -- slots a job freezes.
    local locked = {
        Weapon = { values = { 'Melee', 'Caster' }, bind = '^F3',
                   locks = { ['Weapon:Melee']  = { Main = 'MeleeWpn' },
                             ['Weapon:Caster'] = { Main = 'Staff' } } },
    };
    local app = ml.applyStamp(ml.makeEntry('Weapon', { 'Melee', 'Caster', 'Ranged' }), locked, 'append');
    check('ML44a append keeps the job\'s locks',
        ((app.Weapon.locks or {})['Weapon:Melee'] or {}).Main, 'MeleeWpn');
    check('ML44b ...all of them',
        ((app.Weapon.locks or {})['Weapon:Caster'] or {}).Main, 'Staff');
    check('ML44c ...and still adds the value', join(app.Weapon.values), 'Melee,Caster,Ranged');
    -- OVERWRITE is the one path that must strip: the definition SURVIVES with a
    -- shorter value list, so the ADR 0019 cascade is not free here.
    local ow = ml.applyStamp(ml.makeEntry('Weapon', { 'Melee', 'Tank' }), locked, 'overwrite');
    check('ML44d overwrite keeps a lock whose value survived',
        ((ow.Weapon.locks or {})['Weapon:Melee'] or {}).Main, 'MeleeWpn');
    check('ML44e ...and strips the lock whose value died',
        (ow.Weapon.locks or {})['Weapon:Caster'], nil);
    check('ML44f the caller\'s map is still untouched',
        (locked.Weapon.locks['Weapon:Caster'] or {}).Main, 'Staff');

    -- ---- capture from a job ----
    local caps, refused = ml.captureAll({ Weapon = { values = { 'A', 'B' } }, DT = {}, maxmp = {} });
    check('ML45 captures both real modes', #caps, 2);
    check('ML46 sorted by name',           caps[1].name, 'DT');
    check('ML47 reserved name refused, not dropped silently', #refused, 1);
    check('ML48 refusal names the mode',   refused[1].name, 'maxmp');

    -- ---- round-trip ----
    local lib = {};
    ml.add(lib, ml.makeEntry('Weapon', { 'Melee', 'Ranged' }, '^F3'));
    ml.add(lib, ml.makeEntry('DT', nil, 'F9'));
    local text = ml.serialize(lib);
    local back, perr = ml.parse(text);
    check('ML49 serialize/parse round-trips', perr, nil);
    check('ML50 count survives',   #back, 2);
    check('ML51 values survive',   join(back[1].values), 'Melee,Ranged');
    check('ML52 bind survives',    back[2].bind, 'F9');
    check('ML53 kind survives',    back[2].kind, 'toggle');
    check('ML54 deterministic',    ml.serialize(back), text);

    -- hostile / torn input is reported, never executed
    check('ML55 empty input refused', (select(2, ml.parse(''))), 'empty input');
    check('ML56 garbage refused',     (ml.parse('this is not lua') == nil), true);
    check('ML57 non-table refused',   (select(2, ml.parse('return 5'))), 'did not return a table');
    check('ML58 sandbox blocks os.exit', (function()
        local r, e = ml.parse('os.exit(1) return {}');
        return r == nil and e ~= nil;
    end)(), true);
    check('ML59 sandbox blocks io', (function()
        local r = ml.parse('return { modes = { { name = io.open("x") } } }');
        return r == nil or #r == 0;
    end)(), true);
    check('ML60 quotes/newlines survive a round-trip', (function()
        local l = { ml.makeEntry('We"ird\nName', { 'A', 'B' }) };
        local rt = ml.parse(ml.serialize(l));
        return rt ~= nil and rt[1] ~= nil and rt[1].name;
    end)(), 'We"ird\nName');

    -- ---- library CRUD + import ----
    check('ML61 duplicate add refused', (ml.add(lib, ml.makeEntry('DT'))), false);
    check('ML62 replace add allowed',   (ml.add(lib, ml.makeEntry('DT', nil, 'F10'), true)), true);
    check('ML63 replace took effect',   lib[ml.findEntryCI(lib, 'DT')].bind, 'F10');
    check('ML64 rename to a taken name refused', (ml.rename(lib, 1, 'DT')), false);
    check('ML65 rename to reserved refused',     (ml.rename(lib, 1, 'craft')), false);
    check('ML66 rename works',                   (ml.rename(lib, 1, 'Arms')), true);

    local created, collided = ml.classifyImport(
        { ml.makeEntry('Arms', { 'X', 'Y' }), ml.makeEntry('Brand New') }, lib);
    check('ML67 collision detected', table.concat(collided, ','), 'Arms');
    check('ML68 new entry detected', table.concat(created, ','), 'Brand New');

    local res = ml.applyImport(lib, { ml.makeEntry('Arms', { 'X', 'Y' }) }, false);
    check('ML69 collision refused without confirmation', res.refused, 1);
    check('ML70 ...and nothing changed', join(lib[1].values), 'Melee,Ranged');
    res = ml.applyImport(lib, { ml.makeEntry('Arms', { 'X', 'Y' }) }, true);
    check('ML71 confirmed overwrite updates', res.updated, 1);
    check('ML72 ...and the values changed', join(lib[1].values), 'X,Y');
    res = ml.applyImport(lib, { { name = 'maxmp' } }, true);
    check('ML73 import cannot smuggle in a reserved name', res.refused, 1);

    -- ---- MG. set-entry gate walk (lifted out of gearui so it can be tested) ----
    -- This is the half of the cascade that DELETES gear rows. It had no headless
    -- coverage at all while it lived as a gearui chunk-local.
    check('MG1 exact value hits itself',  ml.gateMatches('Weapon:Caster', 'Weapon:Caster'), true);
    check('MG2 whole mode hits a value',  ml.gateMatches('Weapon:Caster', 'Weapon'), true);
    check('MG3 whole mode hits the bare gate', ml.gateMatches('Weapon', 'Weapon'), true);
    check('MG4 exact value MISSES the bare gate', ml.gateMatches('Weapon', 'Weapon:Caster'), false);
    check('MG5 case-insensitive',         ml.gateMatches('weapon:caster', 'Weapon:Caster'), true);
    check('MG6 near-name is not a prefix hit', ml.gateMatches('WeaponX:A', 'Weapon'), false);
    check('MG7 empty target hits nothing', ml.gateMatches('Weapon', ''), false);

    local function mkWorking()
        return {
            Main = {
                { mode = 'Weapon:Caster', rec = { Name = 'Staff' } },      -- only gate -> row dies
                { mode = { 'Weapon:Caster', 'DT' }, rec = { Name = 'Club' } }, -- keeps DT
                { mode = 'Weapon', rec = { Name = 'Bare' } },              -- bare: NEVER touched
                { rec = { Name = 'Plain' } },                              -- ungated
            },
        };
    end

    -- preview (strip = false) must report without changing anything
    local w = mkWorking();
    local r = ml.gateRefsInSet('TP', w, 'Weapon:Caster', false);
    check('MG8 preview finds both gated rows', #r.refs, 2);
    check('MG9 preview changes nothing',       r.changed, false);
    check('MG10 preview left the rows in place', #w.Main, 4);
    check('MG11 sole-gate row flagged gone',   (function()
        for _, x in ipairs(r.refs) do if x.item == 'Staff' then return x.gone; end end
    end)(), true);
    check('MG12 multi-gate row NOT flagged gone', (function()
        for _, x in ipairs(r.refs) do if x.item == 'Club' then return x.gone; end end
    end)(), false);
    check('MG13 preview names the set',  r.refs[1].set, 'TP');
    check('MG14 preview names the slot', r.refs[1].slot, 'Main');

    -- strip = true: the sole-gate row is REMOVED, the multi-gate row is TRIMMED,
    -- and the bare `mode = 'Weapon'` gate survives untouched (the ADR's rule).
    w = mkWorking();
    r = ml.gateRefsInSet('TP', w, 'Weapon:Caster', true);
    check('MG15 strip reports changed', r.changed, true);
    check('MG16 one row removed',       #w.Main, 3);
    check('MG17 remaining names', (function()
        local n = {}; for _, it in ipairs(w.Main) do n[#n + 1] = it.rec.Name; end
        return table.concat(n, ',');
    end)(), 'Club,Bare,Plain');
    check('MG18 multi-gate row trimmed to its survivor', (function()
        for _, it in ipairs(w.Main) do if it.rec.Name == 'Club' then return it.mode; end end
    end)(), 'DT');
    check('MG19 bare mode gate untouched', (function()
        for _, it in ipairs(w.Main) do if it.rec.Name == 'Bare' then return it.mode; end end
    end)(), 'Weapon');
    check('MG20 ungated row untouched', (function()
        for _, it in ipairs(w.Main) do if it.rec.Name == 'Plain' then return it.mode; end end
    end)(), nil);

    -- targeting the WHOLE mode takes the bare gate too (that is the delete path,
    -- not the cascade -- the cascade always passes Name:Value)
    w = mkWorking();
    r = ml.gateRefsInSet('TP', w, 'Weapon', true);
    check('MG21 whole-mode target hits all three gated rows', #r.refs, 3);
    -- NOT one survivor: the multi-gate row keeps its OTHER gate (DT) and stays. Only
    -- rows whose every gate died are removed -- losing a gate is not losing the piece.
    check('MG22 rows keeping another gate survive', #w.Main, 2);
    check('MG22a ...and it is the trimmed one plus the ungated one', (function()
        local n = {}; for _, it in ipairs(w.Main) do n[#n + 1] = it.rec.Name; end
        return table.concat(n, ',');
    end)(), 'Club,Plain');
    check('MG22b the survivor kept its other gate', (function()
        for _, it in ipairs(w.Main) do if it.rec.Name == 'Club' then return it.mode; end end
    end)(), 'DT');

    -- a target nothing matches must not report or change anything
    w = mkWorking();
    r = ml.gateRefsInSet('TP', w, 'Weapon:Nonexistent', true);
    check('MG23 unmatched target finds nothing', #r.refs, 0);
    check('MG24 unmatched target changes nothing', r.changed, false);
    check('MG25 unmatched target keeps every row', #w.Main, 4);
    check('MG26 nil working table is safe', #ml.gateRefsInSet('TP', nil, 'X', true).refs, 0);
end)();

-- ---------------------------------------------------------------------------
-- SET. menuui -- the header Menu + Settings pure cores (2026-07-24).
-- Own function scope: a do-block's locals share the chunk's 200 budget.
-- ---------------------------------------------------------------------------
;(function()
    local mn = dofile('ui/menuui.lua');
    check('SET1 module loads headless', type(mn), 'table');

    -- The 3-value open setting. Anything unrecognised must read as 'never' --
    -- uiflags.lua is a plain Lua file a player may hand-edit, and the surprising
    -- failure mode is a window that pops up uninvited.
    check('SET2 never normalizes',        mn._normalizeOpenMode('never'), 'never');
    check('SET3 login normalizes',        mn._normalizeOpenMode('login'), 'login');
    check('SET4 job normalizes',          mn._normalizeOpenMode('job'),   'job');
    check('SET5 case-insensitive',        mn._normalizeOpenMode('LOGIN'), 'login');
    check('SET6 nil -> never',            mn._normalizeOpenMode(nil),     'never');
    check('SET7 garbage -> never',        mn._normalizeOpenMode('yes please'), 'never');
    check('SET8 number -> never',         mn._normalizeOpenMode(3),       'never');
    check('SET9 true -> never',           mn._normalizeOpenMode(true),    'never');

    -- Auto-open. 'never' never fires; nothing fires before a real job exists
    -- (job nil/0 = not logged in); 'login' fires exactly once per session;
    -- 'job' fires again only when the job actually CHANGES, so a manual close
    -- is never fought frame after frame.
    check('SET10 never mode never opens',      mn._shouldAutoOpen('never', 5, nil, false), false);
    check('SET11 no job yet -> hold',          mn._shouldAutoOpen('login', nil, nil, false), false);
    check('SET12 job 0 -> hold',               mn._shouldAutoOpen('login', 0, nil, false),   false);
    check('SET13 login fires once',            mn._shouldAutoOpen('login', 5, nil, false),   true);
    check('SET14 login does not re-fire',      mn._shouldAutoOpen('login', 5, 5, true),      false);
    check('SET15 login ignores a job change',  mn._shouldAutoOpen('login', 7, 5, true),      false);
    check('SET16 job mode fires at login',     mn._shouldAutoOpen('job', 5, nil, false),     true);
    check('SET17 job mode re-fires on change', mn._shouldAutoOpen('job', 7, 5, true),        true);
    check('SET18 job mode holds on same job',  mn._shouldAutoOpen('job', 5, 5, true),        false);
    check('SET19 garbage mode never opens',    mn._shouldAutoOpen('sometimes', 5, nil, false), false);

    -- The typed level override. nil = "not a number, do nothing", so a half-typed
    -- box never commits; 0 = back to live; everything else clamps into 1..75.
    check('SET20 plain number',        mn._parseLevel('37'),   37);
    check('SET21 whitespace tolerated',mn._parseLevel('  60 '),60);
    check('SET22 clamps above 75',     mn._parseLevel('120'),  75);
    check('SET23 zero = back to live', mn._parseLevel('0'),    0);
    check('SET24 negative = live',     mn._parseLevel('-4'),   0);
    check('SET25 empty -> nil',        mn._parseLevel(''),     nil);
    check('SET26 nil -> nil',          mn._parseLevel(nil),    nil);
    check('SET27 letters -> nil',      mn._parseLevel('abc'),  nil);
    check('SET28 partial -> nil',      mn._parseLevel('7x'),   nil);
    check('SET29 decimal -> nil',      mn._parseLevel('37.5'), nil);
    check('SET30 lower bound kept',    mn._parseLevel('1'),    1);
    check('SET31 upper bound kept',    mn._parseLevel('75'),   75);

    -- The row roster: order is stable, and the developer quartet exists ONLY
    -- under /dl debug on.
    local plain = mn._menuRows(false);
    local dbg   = mn._menuRows(true);
    check('SET32 eight rows when not debugging', #plain, 8);   -- +wishlist (2026-07-27), +NM Compendium (2026-08-04)
    check('SET33 first row is lockstyle',      plain[1], 'lockstyle');
    check('SET55 wishlist is a plain row',
        (function() for _, k in ipairs(plain) do if k == 'wishlist' then return true; end end return false; end)(), true);
    check('SET34 settings is the last plain row', plain[#plain], 'settings');
    check('SET35 debug adds exactly four',     #dbg - #plain, 4);
    check('SET36 augs only under debug',       dbg[#dbg], 'augs');
    check('SET37 no augs row when not debugging',
        (function() for _, k in ipairs(plain) do if k == 'augs' then return true; end end return false; end)(), false);

    -- The icon column is reserved whether or not a PNG exists -- that is what lets
    -- Henrik drop art in later without shifting the layout.
    check('SET38 icon column width exported', type(mn._ICON_W), 'number');
    check('SET39 label x clears the icon',    mn._LABEL_X > mn._ICON_W, true);
    -- The layout invariant: the label column must clear the icon GUTTER, not merely
    -- the icon width. Bump _ICON_W on its own and labels print over the art -- which
    -- is exactly what nearly happened growing the icons from 16 to 24.
    check('SET51 label clears the whole icon gutter',
        mn._LABEL_X >= mn._ICON_GAP + mn._ICON_W, true);
    -- The taller row needs a taller HIT AREA, or the bottom of every row goes dead.
    check('SET52 row height covers the icon', mn._ROW_H >= mn._ICON_W, true);
    -- The header button's declared width must actually fit its icon: gearui
    -- right-aligns the header by summing b.w, so a lying width shifts the whole row.
    check('SET53 header button width fits its icon',
        mn._MENU_BTN_W > mn._MENU_ICON_W, true);
    -- Henrik's call: the entry-point button wears the art at the SAME size the rows
    -- do, so it reads identically in both places. Pinned so a later row-icon bump
    -- does not silently leave the header behind.
    check('SET54 header icon matches the row icon size', mn._MENU_ICON_W, mn._ICON_W);

    -- activate() is inert until configure() runs: no deps, no action, no crash.
    check('SET40 activate inert unconfigured', mn.activate('lockstyle'), false);
    check('SET41 unknown key refused',         mn.activate('nonsense'),  false);

    -- Every row icon must exist as assets\<name>.png. filetex returns nil for a
    -- missing file and the row just draws a blank cell of the right width -- correct
    -- behaviour, but it means a typo or a rename is INVISIBLE in game. Pin it here.
    -- Seven row icons + the header button + the Developer section heading.
    local icons = mn._menuIcons();
    check('SET42 every icon slot is named', #icons, 10);   -- +NM Compendium (2026-08-04)
    local missing = {};
    for _, name in ipairs(icons) do
        local f = io.open('assets/' .. name .. '.png', 'rb');
        if f == nil then missing[#missing + 1] = name; else f:close(); end
    end
    check('SET43 every row icon exists on disk', table.concat(missing, ','), '');
    -- The floating Teleports button shares the Menu row's art (Henrik: "replace the
    -- ring floating icon with this as well"), so it is the same one file.
    check('SET44 teleports art is the shared one', (function()
        for _, n in ipairs(icons) do if n == 'teleports' then return true; end end
        return false;
    end)(), true);
    -- The header button and the Developer heading are covered by the same guard --
    -- they are the two icons that are NOT row icons, so they are the easiest to
    -- forget when the roster changes.
    check('SET45 header button icon is guarded', (function()
        for _, n in ipairs(icons) do if n == mn._MENU_ICON then return true; end end
        return false;
    end)(), true);
    check('SET46 developer heading icon is guarded', (function()
        for _, n in ipairs(icons) do if n == mn._DEBUG_ICON then return true; end end
        return false;
    end)(), true);

    -- headerButton adapts to whether the art loaded. Headless, filetex has no
    -- texture, so it MUST fall back to the labelled wide text button -- a failed
    -- texture load must never leave a mystery 26px square.
    local hb = mn.headerButton();
    check('SET47 no art -> labelled text button', hb.l, 'Menu');
    check('SET48 no art -> the wide width', hb.w, mn._MENU_W);
    check('SET49 no art -> declarative (no render fn)', hb.render, nil);
    check('SET50 fallback still carries the tooltip', type(hb.tip), 'string');

    -- SET55-59: the Teleports popup's QUICK WINDOW rows (Henrik, 2026-07-26 --
    -- Hobby bar + Lockstyle, replacing the Automations/HELM/Fishing cascades;
    -- E-Box Restock joined them ON TOP 2026-07-30, Crystal Warriors only).
    -- By default a row hands its key to menuui.activate and asks filetex for
    -- assets\<key>.png. A row may OPT OUT of both together -- the trailing
    -- `icon, function()...` pair -- when its art is not key-named and its target
    -- is not a menuui row (restock opens a Gear Helpers panel menuui does not
    -- own). BOTH lookups fail SILENTLY: a renamed key makes a menu-routed row a
    -- no-op, a renamed asset makes any row a blank cell. Neither is visible from
    -- a load test, so the source is parsed and both halves pinned here. Each call
    -- is read as its OWN segment (its start -> the `);` that closes it) so the
    -- opt-out probe can never wander into the next row or into the rest of the
    -- file -- there are `function`s everywhere below.
    local gsrc = nil;
    do
        local f = io.open('ui/gearui.lua', 'r');
        if f ~= nil then gsrc = f:read('*a'); f:close(); end
    end
    check('SET55 gearui is readable', gsrc ~= nil, true);
    local qrows, qkeys = {}, {};
    do
        local src, pos = tostring(gsrc or ''), 1;
        while true do
            local s = src:find('renderQuickWindowRow(', pos, true);
            if s == nil then break; end
            pos = s + 1;
            local seg = src:sub(s, math.min(src:find('renderQuickWindowRow(', pos, true) or (#src + 1),
                                            (src:find('%);', s) or #src) + 2) - 1);
            -- The DEFINITION line reaches here too; it has no quoted key, so it
            -- simply does not match and drops out.
            local key = seg:match("^renderQuickWindowRow%('([%w_]+)'");
            if key ~= nil then
                local icon = seg:match(",%s*'([%w_%-]+)',%s*function");
                qkeys[#qkeys + 1] = key;
                qrows[#qrows + 1] = { key = key, icon = icon or key, own = (icon ~= nil) };
            end
        end
    end
    check('SET56 three quick rows, restock above the Hobby bar',
        table.concat(qkeys, ','), 'restock,hobbybar,lockstyle');
    local known, badKey, badArt = {}, {}, {};
    for _, k in ipairs(mn._menuRows(true)) do known[k] = true; end
    for _, r in ipairs(qrows) do
        -- A row carrying its own action is free of the Menu roster. One WITHOUT
        -- it must name a real Menu row or the click does nothing at all.
        if not r.own and not known[r.key] then badKey[#badKey + 1] = r.key; end
        local f = io.open('assets/' .. r.icon .. '.png', 'rb');
        if f == nil then badArt[#badArt + 1] = r.icon; else f:close(); end
    end
    check('SET57 every menu-routed quick row is a real Menu row key', table.concat(badKey, ','), '');
    check('SET58 every quick row has its art on disk',    table.concat(badArt, ','), '');
    -- The CW gate is that row's whole safety -- a non-Crystal-Warrior must never
    -- see a row for content they cannot have (the same affirmative gate the Gear
    -- Helpers row uses). It lives inside an imgui-only draw path this suite
    -- cannot enter, so it is pinned on the source, anchored to the row it guards.
    check('SET59 the restock row sits behind the CW gate',
        tostring(gsrc or ''):match("gmode%.get%(%) == 'CW'.-renderQuickWindowRow%('restock'") ~= nil, true);
end)();

-- ---------------------------------------------------------------------------
-- UIF. gear/syncflags -- the uiflags.lua round-trip. This file had NO behavioural
-- test before 2026-07-24: a dropped key would have shipped silently.
-- ---------------------------------------------------------------------------
;(function()
    package.loaded['dlac\\lib\\cmdqueue'] = { enqueue = function() end, frame = function() return 0; end };
    local sf = dofile('gear/syncflags.lua');
    check('UIF1 module loads headless', type(sf), 'table');

    local wrote = {};
    local ui = { showAll = { false }, _openMode = 'job', _tgMon = true, _gfScale = 1.25 };
    sf.configure({
        dataDir = function() return 'X:\\char\\dlac\\'; end,
        charBase = function() return 'X:\\char\\'; end,
        writeFileText = function(p, t) wrote.path, wrote.text = p, t; return true; end,
        refreshGear = function() end,
        ui = ui,
    });
    sf.flags.debug, sf.flags.autosync, sf.flags.viewids = true, false, true;
    sf.flags.autobuildimport = false;      -- the 2026-07-27 opt-out
    sf.flags.gearwarn = false;             -- the 2026-08-01 opt-out
    sf.flags.buildstored = false;          -- the 2026-08-01 field-only build
    sf.saveUiFlags();
    check('UIF2 wrote to the mode-aware home', wrote.path, 'X:\\char\\dlac\\uiflags.lua');
    check('UIF3 emitted text parses', (function()
        local f = (loadstring or load)(wrote.text); return f ~= nil;
    end)(), true);

    local t = (loadstring or load)(wrote.text)();
    check('UIF4 debug round-trips',    t.debug,    true);
    check('UIF5 autosync round-trips', t.autosync, false);
    check('UIF6 viewids round-trips',  t.viewids,  true);
    check('UIF6a autobuildimport round-trips', t.autobuildimport, false);
    check('UIF6b gearwarn round-trips', t.gearwarn, false);
    check('UIF6c buildstored round-trips', t.buildstored, false);
    check('UIF7 openui round-trips',   t.openui,   'job');
    check('UIF8 openui is a STRING',   type(t.openui), 'string');
    check('UIF9 showall round-trips',  t.showall,  false);
    check('UIF10 tgmon round-trips',   t.tgmon,    true);
    check('UIF11 gfscale round-trips', t.gfscale,  1.25);

    -- A hand-edited openui must not be able to inject Lua: %q quotes and escapes it.
    ui._openMode = 'ne"ver\nrm -rf';
    sf.saveUiFlags();
    check('UIF12 hostile openui still parses', (function()
        local f = (loadstring or load)(wrote.text); return f ~= nil;
    end)(), true);
    check('UIF13 hostile openui reads back verbatim',
        ((loadstring or load)(wrote.text)()).openui, 'ne"ver\nrm -rf');
    check('UIF14 ...and menuui normalizes it away',
        dofile('ui/menuui.lua')._normalizeOpenMode(((loadstring or load)(wrote.text)()).openui), 'never');

    -- The reader. loadUiFlags is a one-shot latch, so this needs a FRESH instance
    -- (dofile returns one) with _G.loadfile stubbed to hand back our table.
    local sf2 = dofile('gear/syncflags.lua');
    local ui2 = { showAll = { false } };
    local realLoadfile = loadfile;
    _G.loadfile = function() return function()
        return { debug = false, autosync = true, viewids = false,
                 openui = 'login', showall = true, gfscale = 2.0,
                 autobuildimport = false, gearwarn = false, buildstored = false };
    end; end
    sf2.configure({
        dataDir = function() return 'X:\\char\\dlac\\'; end,
        charBase = function() return 'X:\\char\\'; end,
        writeFileText = function() return true; end,
        refreshGear = function() end,
        ui = ui2,
    });
    sf2.loadUiFlags();
    _G.loadfile = realLoadfile;
    check('UIF15 openui loads',   ui2._openMode, 'login');
    check('UIF16 showall loads',  ui2.showAll[1], true);
    check('UIF17 autosync loads', sf2.flags.autosync, true);
    check('UIF18 viewids loads',  sf2.flags.viewids,  false);
    check('UIF18a autobuildimport loads', sf2.flags.autobuildimport, false);
    check('UIF18b gearwarn loads', sf2.flags.gearwarn, false);
    check('UIF18c buildstored loads', sf2.flags.buildstored, false);

    -- Absent keys keep their defaults -- an old uiflags.lua written before this
    -- slice must not start opening windows or flipping Show all.
    local sf3 = dofile('gear/syncflags.lua');
    local ui3 = { showAll = { false } };
    _G.loadfile = function() return function() return { debug = true }; end; end
    sf3.configure({
        dataDir = function() return 'X:\\char\\dlac\\'; end,
        charBase = function() return 'X:\\char\\'; end,
        writeFileText = function() return true; end,
        refreshGear = function() end,
        ui = ui3,
    });
    sf3.loadUiFlags();
    _G.loadfile = realLoadfile;
    check('UIF19 absent openui stays nil',  ui3._openMode, nil);
    check('UIF20 ...which normalizes to never',
        dofile('ui/menuui.lua')._normalizeOpenMode(ui3._openMode), 'never');
    check('UIF21 absent showall stays off', ui3.showAll[1], false);
    -- Every uiflags.lua written before 2026-07-27 lacks the key. Those installs
    -- must keep auto-building on import, or a dlac update would silently change
    -- what an import does to everybody who never asked for the opt-out.
    check('UIF21a absent autobuildimport stays ON', sf3.flags.autobuildimport, true);
    -- Same rule for the 2026-08-01 key: an install that never opted out keeps
    -- being warned about trigger gear parked in storage.
    check('UIF21a2 absent gearwarn stays ON', sf3.flags.gearwarn, true);
    -- And for the other 2026-08-01 key: an install that never opted out keeps
    -- auto-building from everything it owns, storage included.
    check('UIF21a3 absent buildstored stays ON', sf3.flags.buildstored, true);

    -- The gate itself lives in gearui's afterImport hook, which needs imgui and a
    -- logged-in character to reach. Pin it at the source instead of not at all:
    -- the flag must be READ there, and read AFTER the two "we couldn't build
    -- anyway" gates, so the opt-out never steals their diagnosis.
    do
        local src = nil;
        local f = io.open('ui/gearui.lua', 'r');
        if f ~= nil then src = f:read('*a'); f:close(); end
        local hook = tostring(src or ''):match('afterImport = function.-\nend %}%);') or '';
        check('UIF21b afterImport reads the flag',
            hook:find('sf%.flags%.autobuildimport') ~= nil, true);
        check('UIF21c ...and only then auto-builds',
            (hook:find('sf%.flags%.autobuildimport') or 0) < (hook:find('autoBuildAll') or 0), true);

        -- Same treatment for the two 2026-08-01 Sets-tab rulings, both of which
        -- live inside imgui-only draw paths this suite cannot enter.
        --
        -- (1) "Auto-build with gear in storage": OFF must narrow the candidate
        -- pools by the AVAILABLE half (ownedcache.isStored), and it must do it
        -- inside autoBuild -- not in candidatesForSlot, which the + Add picker
        -- shares and which must keep offering everything you own.
        -- Patterns stop at the first column-0 `end` and take NO trailing newline:
        -- this file is CRLF on disk, and Windows Lua strips the \r while WSL's
        -- does not -- a trailing \n in the pattern passes on one and fails on the
        -- other (it did, first run).
        local ab = tostring(src or ''):match('local function autoBuild%(job, level%).-\nend') or '';
        check('UIF22 autoBuild reads the storage Setting',
            ab:find('sf%.flags%.buildstored') ~= nil, true);
        check('UIF22a ...and narrows by the AVAILABLE half',
            ab:find('owned%.isStored') ~= nil, true);
        local cf = tostring(src or ''):match('local function candidatesForSlot.-\nend') or '';
        check('UIF22b ...leaving the shared candidate pool untouched',
            #cf > 0 and cf:find('buildstored') == nil, true);

        -- (2) Auto-Build All re-solves and commits EVERY weighted set of the job,
        -- so the first click may only arm the button; only an armed click builds.
        local btn = tostring(src or ''):match("abArmed and 'Sure%?'.-\n    end") or '';
        check('UIF23 Auto-Build All arms on the first click',
            btn:find('ui%._buildAllArm = os%.clock%(%)') ~= nil, true);
        check('UIF23a ...and only an armed click builds',
            (btn:find('if abArmed then') or 0) < (btn:find('autoBuildAll%(job, level%)') or 0), true);
    end

    package.loaded['dlac\\lib\\cmdqueue'] = nil;
end)();

-- ---------------------------------------------------------------------------
-- LS. THE LOCKED SET (ADR 0022) -- `/dl lock set ...` as a frozen Claim.
--
-- Four commands that differ ONLY in which slots they freeze. That difference is
-- invisible to a source pin and costs four Incursion runs to check by hand, so
-- it is pinned here through the pure builder, and end-to-end through the real
-- M.dispatch below (the NK26 pattern -- the wiring BETWEEN the seams is what
-- has no other coverage).
-- ---------------------------------------------------------------------------
(function()
    local D = dispatchM;
    local B = D.buildLockedClaim;

    -- the injected seams: no Ashita, no bags, no game
    local WORN = { Main = 'Worn Sword', Head = 'Worn Hat', Ammo = nil, Ring1 = 'Worn Ring' };
    local function wornOf(slot) return WORN[slot]; end
    local BAGS = { ['set sword'] = 1, ['set hat'] = 1, ['worn sword'] = 1,
                   ['worn hat'] = 1, ['worn ring'] = 1, ['karin obi'] = 1 };
    local function locate(entry)
        local nm = D._setEntryName(entry);
        if nm == nil then return false, nil; end
        if BAGS[string.lower(nm)] then return true, nil; end
        if string.lower(nm) == 'parked hat' then return false, 'Mog Satchel'; end
        return false, nil;                      -- nowhere this character can see
    end
    local function resolve(v)                   -- the dlac: marker collapser
        local nm = string.lower(D._setEntryName(v) or '');
        if nm == 'dlac:autoobi' then return 'Karin Obi'; end
        return nil;                             -- everything else: no answer today
    end
    local function count(t) local n = 0; for _ in pairs(t) do n = n + 1; end return n; end

    -- LS1. the four words are DATA -- the command branch, the /dl lock help and
    -- these checks all read one table, so a fifth variant cannot drift.
    check('LS1 four lock-set words, in help order',
        table.concat(D._lockSetOrder, ','), 'set,set-loose,set-snapshot,set-current');
    check('LS1b strict fills unnamed slots with remove', D._lockSetModes['set'].fill, 'remove');
    check('LS1c loose fills nothing',                    D._lockSetModes['set-loose'].fill, nil);
    check('LS1d snapshot fills from what is worn',       D._lockSetModes['set-snapshot'].fill, 'worn');
    check('LS1e set-current is the only one needing no name',
        D._lockSetModes['set-current'].needsName, false);

    local SET = { Main = 'Set Sword', Head = 'Set Hat' };

    -- LS2. STRICT: "hard reserve EVERYTHING, even empty slots" (Henrik).
    local c2, m2, n2 = B(SET, 'remove', resolve, locate, wornOf);
    check('LS2 strict claims all 16 slots',        n2, 16);
    check('LS2b ...the set is what it names',      c2.Main, 'Set Sword');
    check('LS2c ...and every other slot is EMPTIED', c2.Ammo, 'remove');
    check('LS2d ...nothing is reported missing',   #m2, 0);
    -- The NK3 lesson, on a new producer: a lowercase key is dropped by the
    -- native engine's SLOT_ID map, so it would work in LAC and hold NOTHING
    -- natively -- the divergence that ships broken in the mode people run.
    check('LS2e keys are PROPER case',             c2.main, nil);

    -- LS3. LOOSE: "reserve ONLY the slots that have anything on them, the rest
    -- gets free use for any other claimants."
    local c3, m3, n3 = B(SET, nil, resolve, locate, wornOf);
    check('LS3 loose claims only the named slots', n3, 2);
    check('LS3b ...and leaves the rest available', c3.Ammo, nil);
    check('LS3c ...still holding what it named',   c3.Head, 'Set Hat');
    check('LS3d ...with nothing missing',          #m3, 0);

    -- LS4. SNAPSHOT: the set, plus what is worn everywhere else.
    local c4, _, n4 = B(SET, 'worn', resolve, locate, wornOf);
    check('LS4 snapshot claims all 16',            n4, 16);
    check('LS4b the set still wins its own slots', c4.Main, 'Set Sword');
    check('LS4c an unnamed slot takes what is worn', c4.Ring1, 'Worn Ring');
    check('LS4d an unnamed EMPTY slot is held empty', c4.Ammo, 'remove');

    -- LS5. set-current: no set at all, every slot from what is worn, strictly.
    local c5, m5, n5 = B(nil, 'worn', resolve, locate, wornOf);
    check('LS5 set-current claims all 16',         n5, 16);
    check('LS5b ...from what is worn',             c5.Head, 'Worn Hat');
    check('LS5c ...empty stays empty',             c5.Ammo, 'remove');
    check('LS5d ...and it can never report a miss', #m5, 0);

    -- LS6. sets are authored in any case; the claim is not.
    local c6 = B({ main = 'Set Sword', HEAD = 'Set Hat' }, nil, resolve, locate, wornOf);
    check('LS6 a lowercase set key is matched',    c6.Main, 'Set Sword');
    check('LS6b ...and an uppercase one',          c6.Head, 'Set Hat');

    -- LS7. dlac: markers are COLLAPSED at arm -- the reason a locked obi cannot
    -- follow the weather any more (Henrik: "Once you lock, it shall be constant").
    local c7 = B({ Waist = 'dlac:AutoObi' }, nil, resolve, locate, wornOf);
    check('LS7 a virtual is frozen to its answer', c7.Waist, 'Karin Obi');

    -- LS8. a marker with NO answer right now: the slot goes loose, and the
    -- marker is named rather than silently dropped.
    local c8, m8 = B({ Main = 'dlac:AutoStaff' }, 'remove', resolve, locate, wornOf);
    check('LS8 an unresolvable marker is not held', c8.Main, nil);
    check('LS8b ...it is reported',                 #m8, 1);
    check('LS8c ...by marker name',                 m8[1] and m8[1].item, 'dlac:AutoStaff');
    check('LS8d ...and strict does NOT empty it instead', c8.Main, nil);

    -- LS9. THE INCURSION CASE: a named piece that is not on you. The slot goes
    -- LOOSE (available), and we say where the gear actually is.
    local c9, m9, n9 = B({ Main = 'Set Sword', Head = 'Parked Hat', Body = 'Gone Forever' },
                         'remove', resolve, locate, wornOf);
    check('LS9 the piece we have is held',          c9.Main, 'Set Sword');
    check('LS9b a parked piece is NOT held',        c9.Head, nil);
    check('LS9c ...and is not emptied either -- it is LOOSE', c9.Head, nil);
    check('LS9d two pieces are reported',           #m9, 2);
    check('LS9e ...one located',                    m9[1] and m9[1].where, 'Mog Satchel');
    check('LS9f ...one nowhere to be found',        m9[2] and m9[2].where, nil);
    check('LS9g and the other 13 slots still emptied strictly', n9, 14);

    -- LS10. 'remove' and 'displaced' are equip LITERALS, not item names: they
    -- can never be missing from your bags, so they skip the locate check.
    local c10, m10 = B({ Ammo = 'remove', Range = 'displaced' }, nil, resolve, locate, wornOf);
    check('LS10 a remove entry is held as written', c10.Ammo, 'remove');
    check('LS10b displaced too',                    c10.Range, 'displaced');
    check('LS10c neither counts as missing',        #m10, 0);

    -- LS11. 'ignore' is the set author saying "not mine": leave the slot alone,
    -- and do NOT report it -- nothing is missing.
    local c11, m11 = B({ Ammo = 'ignore' }, nil, resolve, locate, wornOf);
    check('LS11 an ignore entry is not claimed',    c11.Ammo, nil);
    check('LS11b ...and is not reported missing',   #m11, 0);

    -- LS12. an entry TABLE (augment / Bag spec) survives whole -- freezing to a
    -- bare name would let planSet pick the wrong copy of a ring you own twice.
    local aug = { Name = 'Set Sword', Augment = { 'Attack+5' } };
    local c12 = B({ Main = aug }, nil, resolve, locate, wornOf);
    check('LS12 an augment spec is frozen intact',  c12.Main, aug);

    -- LS13. the stored record + its accessors
    local savedLocked = D.lockedSet;
    check('LS13 nothing locked to begin with',      D.lockedSetOn(), false);
    check('LS13b ...so there is no claim',          D.lockedSetClaim(), nil);
    check('LS13c ...and no label',                  D.lockedSetLabel(), nil);
    D.setLockedSet({ name = 'Incursion T3', mode = 'set', claim = { Head = 'Set Hat' }, n = 1 });
    check('LS13d armed',                            D.lockedSetOn(), true);
    check('LS13e ...labelled by set name',          D.lockedSetLabel(), 'Incursion T3');
    local claimA = D.lockedSetClaim();
    claimA.Head = 'TAMPERED';
    check('LS13f the claim is a COPY -- the apply path cannot reach the frozen one',
        D.lockedSetClaim().Head, 'Set Hat');
    D.setLockedSet({ name = nil, mode = 'set-current', claim = { Head = 'Worn Hat' }, n = 1 });
    check('LS13g set-current has no set name, so it says what it is',
        D.lockedSetLabel(), 'your gear as it was');
    check('LS13h releasing hands back the label',   D.clearLockedSet(), 'your gear as it was');
    check('LS13i ...and it is gone',                D.lockedSetOn(), false);
    check('LS13j releasing nothing returns nothing', D.clearLockedSet(), nil);

    -- LS14. LIFETIME -- it shares nakedWorldWatch (ADR 0022). Logging in locked
    -- to last night's set is the relog failure ADR 0021 calls the worst outcome,
    -- wearing different clothes: a naked player knows instantly, a locked one
    -- just finds their gear mysteriously stuck.
    local savedNaked = D.nakedArmed;
    D.nakedArmed = false;
    D.setLockedSet({ name = 'Incursion T3', mode = 'set', claim = { Head = 'Set Hat' }, n = 1 });
    check('LS14 same job, in the world -> stays locked', D.nakedWorldWatch(7, 7), nil);
    check('LS14b ...and it is still armed',              D.lockedSetOn(), true);
    -- Zones survive (Henrik, 2026-07-27): absence holds; outlasting drops.
    check('LS14c0 a zone-length absence holds the locked set', D.nakedWorldWatch(0, 7), nil);
    local why14, drop14 = D.nakedWorldWatch(0, 7, 1e9);
    check('LS14c outlasting a zone releases it',         why14, 'world');
    check('LS14d ...and it is gone',                     D.lockedSetOn(), false);
    check('LS14e ...the caller is told what dropped',    drop14 and drop14.locked, 'Incursion T3');
    check('LS14f ...and that naked was not part of it',  drop14 and drop14.naked, false);
    D.setLockedSet({ name = 'Incursion T3', mode = 'set', claim = { Head = 'Set Hat' }, n = 1 });
    local why14b, drop14b = D.nakedWorldWatch(3, 7);
    check('LS14g a JOB CHANGE releases it too',          why14b, 'job');
    check('LS14h ...naming it, because someone is there to read the line',
        drop14b and drop14b.locked, 'Incursion T3');
    -- both can drop in one pass, and the watch only ever CLEARS
    D.setLockedSet({ name = 'Incursion T3', mode = 'set', claim = { Head = 'Set Hat' }, n = 1 });
    D.nakedArmed = true;
    D.nakedWorldWatch(0, 7);
    local _, drop14c = D.nakedWorldWatch(0, 7, 1e9);
    check('LS14i both drop together',
        (drop14c and drop14c.naked == true and drop14c.locked == 'Incursion T3'), true);
    check('LS14j ...and neither is re-armed', D.nakedOn() == false and D.lockedSetOn() == false, true);
    -- LS14k. SLOT LOCKS SHARE IT TOO (v124, Henrik: "I don't want locks to
    -- outlive a relog, it should not outlive a main job change nor a log").
    -- Nothing used to watch them, so they rode straight through character select
    -- -- an Ashita addon survives a logout. Before v123 the engine self-swap
    -- happened to wipe them, which looked like a lifetime rule and was really a
    -- bug; removing that accident left the real gap visible.
    D.nakedArmed = false;
    D.lockedSet  = nil;
    D.locks['head'], D.locks['ammo'] = true, true;
    check('LS14k a lock alone is enough to arm the watch', D.worldWatch(7, 7), nil);
    check('LS14l ...and it survives standing still',       D.locks['head'], true);
    local why14d, drop14d = D.worldWatch(3, 7);
    check('LS14m a JOB CHANGE releases slot locks',        why14d, 'job');
    check('LS14n ...all of them',                          next(D.locks), nil);
    check('LS14o ...counted for the chat line',            drop14d and drop14d.locks, 2);
    D.locks['head'] = true;
    D.worldWatch(0, 7);
    check('LS14p outlasting a zone releases them too',     D.worldWatch(0, 7, 1e9), 'world');
    check('LS14q ...leaving nothing behind',               next(D.locks), nil);
    -- ...and with nothing held at all the watch stays silent, so the tick does
    -- not write the mirror on every frame of character select.
    check('LS14r nothing held -> the watch does nothing',  D.worldWatch(0, 7), nil);
    check('LS14s the pre-v124 name is the same function',
        rawequal(D.nakedWorldWatch, D.worldWatch), true);

    D.nakedArmed = savedNaked;
    D.lockedSet  = savedLocked;

    -- LS15. PRECEDENCE, from the one authority. The locked set rides the EXISTING
    -- Locks row, so "a locked slot moves for Naked and Pins, nothing else" is a
    -- statement about the default rank order -- not about new code.
    local def = D._arbDefaultOrder;
    local rank = {};
    for i, n in ipairs(def) do rank[n] = i; end
    check('LS15 Naked outranks a lock', rank['Naked'] < rank['Locks'], true);
    check('LS15b Pins outrank a lock (on demand, universally understood)',
        rank['Pins'] < rank['Locks'], true);
    check('LS15c no CLAIMANT else does', (function()
        for _, n in ipairs(def) do
            if n == 'Locks' then return true; end
            -- Disabled (ADR 0024) is above Locks and always will be: it is the
            -- CEILING, not a claimant -- it dresses nothing and cannot be dragged.
            -- The law this pins is about claimants, so it is named, not counted.
            if n ~= 'Naked' and n ~= 'Pins' and n ~= 'Disabled' then return n; end
        end
        return 'Locks row missing';
    end)(), true);
    check('LS15d no new CLAIMANT row was added (13 = the 12 ranked rows + the ADR 0024 ceiling)',
        #def, 13);

    -- LS16. END TO END through the REAL M.dispatch (the NK26 pattern). A locked
    -- set with NOTHING else armed -- no triggers, no pins, no hobby, no ammo --
    -- must still reach the equip door, which is the path BOTH bail guards have to
    -- let through. This is the check that would have caught the original bug.
    local savedPlayer, savedFunc, savedState = TEST_PLAYER, rawget(_G, 'gFunc'), rawget(_G, 'gState');
    TEST_PLAYER = { MainJob = 'WHM', MainJobLevel = 75, SubJob = 'BLM', SubJobLevel = 37,
                    MainJobSync = 75, SubJobSync = 37, Status = 'Idle', IsMoving = false };
    local wrote = {};
    -- The NATIVE equip door (purge Phase 2: gFunc.EquipSet is gone).
    local savedEngLS = package.loaded['dlac\\feature\\equipengine'];
    package.loaded['dlac\\feature\\equipengine'] = {
        nativeOn = function() return true; end,
        equipSet = function(t) for k, v in pairs(t or {}) do wrote[k] = v; end end,
        state = { tripped = false },
    };
    _G.gState = { CurrentCall = 'N/A', Disabled = {} };

    local strictClaim = B({ Main = 'Set Sword', Head = 'Set Hat' }, 'remove', resolve, locate, wornOf);
    D.setLockedSet({ name = 'Incursion T3', mode = 'set', claim = strictClaim, n = 16 });
    local okD, errD = pcall(D.dispatch, 'Default');
    check('LS16 a bare Default with only a locked set does not throw', okD, true);
    if not okD then print('LS16 error: ' .. tostring(errD)); end
    check('LS16b it reaches the equip door with all 16 slots', count(wrote), 16);
    check('LS16c the set holds its own slots',                 wrote.Main, 'Set Sword');
    check('LS16d ...and strict empties the rest',              wrote.Ammo, 'remove');

    -- LS17. A plain slot lock can never sabotage the hold. layerRespectsLocks
    -- asks `rank > lockRank` about the Locks row ITSELF, which is false -- so the
    -- hold punches through M.locks. That is exactly why arming no longer has to
    -- destroy the player's own locks first (ADR 0021 listed doing so as a defect).
    wrote = {};
    D.locks['head'] = true;
    pcall(D.dispatch, 'Default');
    check('LS17 a stale lock does not strip the slot out of the hold', wrote.Head, 'Set Hat');
    check('LS17b ...and the player keeps their lock',                  D.locks['head'], true);
    D.locks['head'] = nil;

    -- LS18. LOOSE really is available: the slots the hold left alone are simply
    -- not written by this layer.
    wrote = {};
    local looseClaim = B({ Main = 'Set Sword', Head = 'Set Hat' }, nil, resolve, locate, wornOf);
    D.setLockedSet({ name = 'Incursion T3', mode = 'set-loose', claim = looseClaim, n = 2 });
    pcall(D.dispatch, 'Default');
    check('LS18 loose writes only the slots it holds', count(wrote), 2);
    check('LS18b ...and nothing lands in the rest',    wrote.Ammo, nil);

    -- LS19. NAKED OUTRANKS IT (Henrik: "Naked means naked, whatever everyone
    -- else thinks"). The hold genuinely tries and the Arbiter genuinely blocks
    -- it -- Locks applies first, Naked overwrites all 16 -- so releasing the
    -- strip hands the slots straight back on the next pass.
    wrote = {};
    D.nakedArmed = true;
    pcall(D.dispatch, 'Default');
    check('LS19 naked beats the locked set in every slot', count(wrote), 16);
    check('LS19b ...including one the hold named',         wrote.Main, 'remove');
    D.nakedArmed = false;
    wrote = {};
    pcall(D.dispatch, 'Default');
    check('LS19c dressed again, the hold takes its slots back', wrote.Main, 'Set Sword');

    D.setLockedSet(nil);
    wrote = {};
    pcall(D.dispatch, 'Default');
    check('LS20 released, a bare dispatch writes nothing at all', next(wrote), nil);

    -- -----------------------------------------------------------------------
    -- DS. FREE EQUIP -- the DISABLED CEILING (ADR 0024), end to end through the
    --     REAL M.dispatch on the harness LS16 built. These are the checks that
    --     matter: everything else about this feature is a chat line.
    --
    --     The point of doing it here rather than at a pure seam is that the
    --     ceiling is enforced at engineEquipSet, BELOW equipResolved and below
    --     every whole-table post-pass -- so only a real dispatch can show that a
    --     disabled slot produces no write no matter who claimed it.
    -- -----------------------------------------------------------------------
    D.setLockedSet({ name = 'Incursion T3', mode = 'set', claim = strictClaim, n = 16 });

    wrote = {};
    D.setDisabled('main', true);
    pcall(D.dispatch, 'Default');
    check('DS1 a disabled slot is not written at all',   wrote.Main, nil);
    check('DS1b ...and the other 15 still are',          count(wrote), 15);
    check('DS1c ...specifically the ones the hold named', wrote.Head, 'Set Hat');

    -- THE ONE THAT MATTERS: the ceiling outranks the strip. A lock cannot do
    -- this -- Naked ranks above Locks and punches straight through it.
    wrote = {};
    D.nakedArmed = true;
    pcall(D.dispatch, 'Default');
    check('DS2 NAKED cannot strip a disabled slot',      wrote.Main, nil);
    check('DS2b ...and still strips every other one',    wrote.Head, 'remove');
    D.nakedArmed = false;

    wrote = {};
    D.setDisabled('all', true);
    pcall(D.dispatch, 'Default');
    check('DS3 all 16 disabled -> dlac writes nothing whatsoever', next(wrote), nil);

    wrote = {};
    D.setDisabled('all', false);
    pcall(D.dispatch, 'Default');
    check('DS4 re-enabled, the very next pass dresses them again', count(wrote), 16);
    check('DS4b ...with the held set back in Main',      wrote.Main, 'Set Sword');

    -- setDisabled's vocabulary, shaped exactly like setLock's.
    check('DS5 an unknown slot name is nil, never a throw', D.setDisabled('nosuchslot', true), nil);
    check('DS5b ...and disables nothing',                D.disabledOn(), false);
    check('DS6 nil state toggles a single slot',         D.setDisabled('ammo'), true);
    check('DS6b ...and toggles it back',                 D.setDisabled('ammo'), false);
    check('DS6c disabledOn(slot) answers per slot', (function()
        D.setDisabled('ear1', true);
        local a, b = D.disabledOn('ear1'), D.disabledOn('ear2');
        D.setDisabled('ear1', false);
        return a == true and b == false;
    end)(), true);
    check('DS7 disabledList is in canonical LAC order, not hash order', (function()
        D.setDisabled('feet', true); D.setDisabled('main', true); D.setDisabled('head', true);
        local l = table.concat(D.disabledList(), ',');
        D.setDisabled('all', false);
        return l;
    end)(), 'main,head,feet');

    -- stripDisabled: the seam itself. Case-insensitive on purpose -- claims are
    -- canonical ('Main'), the command vocabulary is lac-case ('main'), and
    -- equipcore's SLOT_ID map is case-SENSITIVE, so a case-blind compare would
    -- work in one engine and silently miss in the other.
    D.setDisabled('main', true);
    local src = { Main = 'A', Head = 'B', main = 'C', __meta = 'keep' };
    local out = D._stripDisabled(src);
    check('DS8 the canonical key is stripped',           out.Main, nil);
    check('DS8b the lac-case key is stripped too',       out.main, nil);
    check('DS8c an unrelated slot survives',             out.Head, 'B');
    check('DS8d __ metadata is never treated as a slot', out.__meta, 'keep');
    check('DS8e the caller\'s table is not mutated',     src.Main, 'A');
    D.setDisabled('all', false);
    local same = { Main = 'A' };
    check('DS9 with nothing disabled the set passes through by IDENTITY',
        D._stripDisabled(same) == same, true);

    -- Attribution. The claim exists ONLY so /dl why and the panel can name it.
    check('DS10 no claim when nothing is disabled',      D.disabledClaim(), nil);
    D.setDisabled('head', true);
    local dzc = D.disabledClaim();
    check('DS10b the claim is keyed CANONICALLY',        dzc and dzc.Head, D.DISABLED_FREE);
    check('DS10c ...and claims only the disabled slots', (function()
        local n = 0; for _ in pairs(dzc or {}) do n = n + 1; end; return n;
    end)(), 1);
    local dzWhy = table.concat(D.arbWhyLines(
        { Disabled = dzc, Naked = D.nakedClaim() }, D.arbOrder(nil), {}), '\n');
    check('DS11 /dl why collapses the ceiling into ONE line',
        select(2, dzWhy:gsub('FREE EQUIP %(ceiling', '')), 1);
    check('DS11b ...naming the slot',                    dzWhy:find('Head', 1, true) ~= nil, true);
    check('DS11c ...and who it beat',                    dzWhy:find('over Naked', 1, true) ~= nil, true);
    -- Woven MaxMP cedes a disabled slot for free -- that is what registering the
    -- claim above the mpCeded computation buys.
    local dzCede = D.arbCededAbove({ Disabled = dzc }, D.arbOrder(nil), 'MaxMP');
    check('DS12 MaxMP cedes a disabled slot',            dzCede['head'], 'Disabled');
    D.setDisabled('all', false);

    -- LIFETIME (Henrik, 2026-07-26): the same watch as the strip, a locked set
    -- and slot locks. A job change or leaving the world releases it; nothing
    -- persists it. Standing on a new job with a slot silently not swapping, and
    -- nothing on screen to explain it, is the failure this closes.
    D.setDisabled('back', true);
    check('DS13 free equip alone is enough to arm the watch', D.worldWatch(7, 7), nil);
    local dzWhy2, dzDrop = D.worldWatch(1, 7);
    check('DS13b a main job change releases it',         dzWhy2, 'job');
    check('DS13c ...and reports how many slots',         dzDrop and dzDrop.disabled, 1);
    check('DS13d ...leaving nothing behind',             D.disabledOn(), false);
    D.setDisabled('waist', true);
    -- Zones survive (Henrik, 2026-07-27): absence HOLDS free equip too;
    -- only outlasting a zone releases it -- the one lifetime rule, still.
    check('DS14 a world-gone read holds free equip through a zone', (D.worldWatch(nil, 7)), nil);
    check('DS14b outlasting a zone releases it',         (D.worldWatch(nil, 7, 1e9)), 'world');
    check('DS14c ...and it is gone',                     D.disabledOn(), false);

    D.setLockedSet(nil);
    TEST_PLAYER = savedPlayer;
    _G.gFunc, _G.gState = savedFunc, savedState;
    package.loaded['dlac\\feature\\equipengine'] = savedEngLS;
    D.nakedArmed = savedNaked;
    D.lockedSet  = savedLocked;
end)();

-- ---------------------------------------------------------------------------
-- CMD. THE /dl COMMAND SURFACE, DRIVEN FOR REAL (2026-07-26).
--
-- Until this section every /dl subcommand was tested by SEARCHING dispatch.lua
-- for its own name. NK23 records why: "dispatch's handler only registers inside
-- engineActive(), which is false headlessly, so the whitelist cannot be driven
-- -- pin it as SOURCE instead." A source pin proves a command is spelled right
-- and sits in the whitelist. It cannot see what the command DOES -- which is
-- exactly how `/dl lock set` shipped present, correctly spelled, whitelisted,
-- and INERT in native mode: its rawget(_G,'gEquip') bracket is nil in the addon
-- state, so the equip fell to the unbracketed path, landed in equipengine's
-- buffer, and the next fireEvent's bufferClear wiped it before it could send.
--
-- engineActive() is `inLac() or nativeEngine() ~= nil`, so the ADDON-state copy
-- of the engine -- inert since v1 -- becomes the LIVE one when the native flag
-- is on (the arming rule NEB1 pins). Arm it, re-load dispatch, and the real
-- command handler registers and is callable.
--
-- THIS LOADS A SECOND dispatch MODULE into a suite whose other checks hold a
-- reference to the first, so every shared thing it touches is saved and put
-- back: package.loaded (dispatch + chatfmt), gFunc/gState, profiles.nativeMode
-- and profiles.dataDir, ashita.events, equipengine's onEvent and tripwire.
-- dataDir is redirected to tests\ because the engineActive block runs
-- loadModeState/saveModeState AT LOAD -- unredirected, a plain test run would
-- write modestate.lua into a real character's folder.
--
-- chatfmt is stubbed BEFORE the load, never after: dispatch.lua:139 binds its
-- shadowed `print` once at load time, so a later _G.print override is not seen.
-- ---------------------------------------------------------------------------
(function()
    local SEP  = string.char(92);
    local prof = package.loaded['dlac\\profiles'];
    local eng  = package.loaded['dlac\\feature\\equipengine'];
    check('CMD0 profiles is loaded',     type(prof), 'table');
    check('CMD0b equipengine is loaded', type(eng),  'table');
    if type(prof) ~= 'table' or type(eng) ~= 'table' then return; end

    local saved = {
        nativeMode = prof.nativeMode,        dataDir = prof.dataDir,
        dispatch   = package.loaded['dlac\\dispatch'],
        chatfmt    = package.loaded['dlac\\chatfmt'],
        gFunc      = rawget(_G, 'gFunc'),    gState  = rawget(_G, 'gState'),
        reg        = ashita.events.register, unreg   = ashita.events.unregister,
        player     = TEST_PLAYER,
        onEvent    = eng.onEvent,            tripped = eng.state.tripped,
    };

    -- Captured chat. `said` is REASSIGNED per command and the stub closes over
    -- the variable rather than the table, so each run reads only its own lines.
    local said = {};
    local function capture(...)
        local parts = {};
        for i = 1, select('#', ...) do parts[#parts + 1] = tostring((select(i, ...))); end
        said[#said + 1] = table.concat(parts, ' ');
    end
    package.loaded['dlac\\chatfmt'] = { print = capture, warn = capture, err = capture };

    -- Arm the native engine: addon state (no gFunc) + flag on + tripwire clear.
    prof.nativeMode = function() return true; end
    prof.dataDir    = function() return 'tests' .. SEP; end
    _G.gFunc, _G.gState = nil, nil;
    eng.state.tripped = false;

    local handlers = {};
    ashita.events.register   = function(ev, nm, fn) handlers[ev] = fn; end
    ashita.events.unregister = function() end
    local okLoad, D = pcall(dofile, 'dispatch.lua');
    ashita.events.register, ashita.events.unregister = saved.reg, saved.unreg;

    check('CMD1 dispatch re-loads with the native engine armed', okLoad, true);
    if not okLoad then print('CMD1 error: ' .. tostring(D)); end
    check('CMD2 ...and the command handler registers for real',
          okLoad and type(handlers['command']), 'function');
    check('CMD2b ...alongside the frame tick',
          okLoad and type(handlers['d3d_present']), 'function');

    if okLoad and type(handlers['command']) == 'function' then
        TEST_PLAYER = { MainJob = 'WHM', MainJobLevel = 75, SubJob = 'BLM', SubJobLevel = 37,
                        MainJobSync = 75, SubJobSync = 37, Status = 'Idle', IsMoving = false };

        -- One /dl line, driven exactly as Ashita delivers it: an event table
        -- whose `blocked` field the handler sets when it owns the command.
        local function run(line)
            said = {};
            local e = { command = line, blocked = false };
            local ok, err = pcall(handlers['command'], e);
            if not ok then said[#said + 1] = 'ERROR: ' .. tostring(err); end
            return e, ok;
        end
        local function saidHas(frag)
            for _, l in ipairs(said) do
                if string.find(l, frag, 1, true) ~= nil then return true; end
            end
            return false;
        end
        local function saidText() return table.concat(said, ' | '); end

        -- This is the fact the whole section rests on: the command answered
        -- with NO gFunc in the state, so it is the addon-side native engine
        -- replying, not LuaAshitacast's copy.
        check('CMD3 no gFunc present -- this is the addon-state engine',
              rawget(_G, 'gFunc'), nil);

        -- The whitelist, driven instead of grepped (the v46 trap NK23 pins as
        -- source): an unknown subcommand must fall through UNBLOCKED and silent,
        -- or it looks like the command does not exist.
        local e4 = run('/dl bogus');
        check('CMD4 an unknown subcommand is not blocked', e4.blocked, false);
        check('CMD4b ...and prints nothing',               #said, 0);

        local e5 = run('/dl lock');
        check('CMD5 /dl lock is owned (blocked)',   e5.blocked, true);
        check('CMD5b ...and reports the lock state', saidHas('locked slots:'), true);

        -- slot locks, round trip through the REAL command
        run('/dl lock head on');
        check('CMD6 /dl lock head on sets the lock', D.locks['head'], true);
        check('CMD6b ...and says so',                saidHas('lock head ON'), true);
        run('/dl lock head off');
        check('CMD6c /dl lock head off releases it', D.locks['head'], nil);
        run('/dl lock all on');
        local nAll = 0;
        for _ in pairs(D.locks) do nAll = nAll + 1; end
        check('CMD6d /dl lock all on locks all 16',  nAll, 16);
        run('/dl lock all off');
        check('CMD6e /dl lock all off clears them',  next(D.locks), nil);
        local e6 = run('/dl lock nosuchslot');
        check('CMD6f an unknown slot is named back', saidHas('unknown slot: nosuchslot'), true);
        check('CMD6g ...and still owns the command', e6.blocked, true);

        -- the strip (ADR 0021), through the command rather than the flag
        run('/dl naked');
        check('CMD7 /dl naked arms the strip',        D.nakedOn(), true);
        check('CMD7b ...and states the TP wipe once', saidHas('zeroes your TP'), true);
        run('/dl naked');
        check('CMD7c a second /dl naked never dresses you', D.nakedOn(), true);
        check('CMD7d ...it says you already are',     saidHas('already naked'), true);
        run('/dl dress');
        check('CMD7e /dl dress releases it',          D.nakedOn(), false);
        run('/dl naked');
        run('/dl naked off');
        check('CMD7f /dl naked off releases it too',  D.nakedOn(), false);

        -- /dl lock set: the name check, which must refuse BEFORE it touches
        -- anything (a failed name that had already cleared the locks would
        -- leave the player half-unlocked with nothing equipped).
        run('/dl lock head on');
        local e8 = run('/dl lock set NoSuchSetName');
        check('CMD8 /dl lock set owns the command',   e8.blocked, true);
        check('CMD8b an unknown set is refused by name',
              saidHas('no committed set named'), true);
        check('CMD8c ...and the refusal leaves existing locks alone',
              D.locks['head'], true);
        run('/dl lock all off');
        run('/dl lock set');
        check('CMD9 /dl lock set with no name prints usage',
              saidHas('usage: /dl lock set'), true);

        if not saidHas('usage: /dl lock set') then print('CMD9 said: ' .. saidText()); end

        -- THE LOCKED SET (ADR 0022), through the real commands. Headless there
        -- is no AshitaCore, so wornItemName answers nil for every slot and
        -- set-current freezes sixteen empties -- which is still the whole arm ->
        -- claim -> release path, and the only one that proves the four command
        -- words reach the builder at all.
        run('/dl lock set-current');
        check('CMD10 /dl lock set-current arms a hold', D.lockedSetOn(), true);
        check('CMD10b ...strictly, all 16 slots',       D.lockedSet.n, 16);
        check('CMD10c ...and says what it locked',      saidHas('LOCKED to'), true);
        check('CMD10d ...naming the release door',      saidHas('/dl lock set off'), true);

        -- The state readout + the four-variant help Henrik asked for by name.
        run('/dl lock');
        check('CMD11 /dl lock reports the held set',    saidHas('locked set:'), true);
        local allFour = true;
        for _, w in ipairs(D._lockSetOrder) do
            if not saidHas('/dl lock ' .. w) then allFour = false; end
        end
        check('CMD11b ...and lists every variant',      allFour, true);
        check('CMD11c ...with the slot-lock line too',  saidHas('/dl lock <slot|all>'), true);

        -- The narrow door.
        run('/dl lock set off');
        check('CMD12 /dl lock set off releases it',     D.lockedSetOn(), false);
        check('CMD12b ...and says which set it was',    saidHas('released'), true);
        run('/dl lock set off');
        check('CMD12c releasing nothing is not an error', saidHas('no set is locked'), true);

        -- COEXISTENCE (Henrik, 2026-07-26): arming must no longer destroy the
        -- player's own locks. Today's code cleared them because they would strip
        -- slots out of the one-shot equip; a claim outranks them instead, so the
        -- lock is merely outranked while held and is still there on release.
        run('/dl lock ammo on');
        run('/dl lock set-current');
        check('CMD13 arming a hold leaves plain locks alone', D.locks['ammo'], true);
        check('CMD13b ...and the hold is armed anyway',       D.lockedSetOn(), true);

        -- The universal door: "/dl lock all off" is one word to the player, so
        -- it lets go of everything that word covers -- and says so.
        run('/dl lock all off');
        check('CMD14 /dl lock all off clears the slot locks', next(D.locks), nil);
        check('CMD14b ...and releases the held set too',      D.lockedSetOn(), false);
        check('CMD14c ...saying it did',                      saidHas('released the locked set'), true);

        -- Every variant refuses an unknown set BY NAME, before touching state.
        run('/dl lock ring1 on');
        local e15 = run('/dl lock set-loose NoSuchSetName');
        check('CMD15 set-loose owns the command',        e15.blocked, true);
        check('CMD15b ...refuses an unknown name',       saidHas('no committed set named'), true);
        check('CMD15c ...arms nothing',                  D.lockedSetOn(), false);
        check('CMD15d ...and leaves existing locks alone', D.locks['ring1'], true);
        run('/dl lock snapshot');   -- not a word: falls through to the slot branch
        check('CMD15e a near-miss word is an unknown SLOT, not a silent no-op',
              saidHas('unknown slot: snapshot'), true);
        run('/dl lock all off');

        -- FREE EQUIP (ADR 0024), through the REAL command handler. The whitelist
        -- half is the v46 trap NK23 records: a subcommand missing from it returns
        -- in SILENCE and looks like the command does not exist -- so `blocked` is
        -- checked on every one of these, not just the output.
        local e16 = run('/dl disable');
        check('CMD16 /dl disable is owned (whitelisted, not silently dropped)', e16.blocked, true);
        check('CMD16b bare /dl disable takes all 16',  #D.disabledList(), 16);
        -- ONE LINE (Henrik, 2026-07-26: "please remove all the text"). It still
        -- has to carry the release door -- an ack you cannot undo is worse than
        -- a paragraph -- so that is what is pinned, plus the line COUNT, because
        -- "terse" is the requirement and only a count can regress silently.
        check('CMD16c ...in one line',                 #said, 1);
        check('CMD16d ...naming the release door',     saidHas('/dlac enable'), true);
        check('CMD16e ...and reading as Henrik asked', said[1], '[dlac] All slots disabled - enable by /dlac enable');
        local e17 = run('/dl enable');
        check('CMD17 /dl enable is owned too',         e17.blocked, true);
        check('CMD17b ...and releases everything',     D.disabledOn(), false);

        -- THE LONG PREFIX IS REAL (Henrik, 2026-07-26: "do we have /dlac enable
        -- and such as well? If so, we need it"). argStart accepts both, and the
        -- chat lines say /dlac, so a player who copies what they are told back
        -- into the box must land somewhere. Driven, not read off argStart.
        local e17c = run('/dlac disable feet');
        check('CMD17c /dlac disable <slot> works', e17c.blocked and D.disabledOn('feet'), true);
        local e17d = run('/dlac enable feet');
        check('CMD17d /dlac enable <slot> works',  e17d.blocked and not D.disabledOn('feet'), true);
        run('/dlac disable');
        check('CMD17e /dlac disable bare works',   #D.disabledList(), 16);
        run('/dlac enable');
        check('CMD17f /dlac enable bare works',    D.disabledOn(), false);

        run('/dl disable head');
        check('CMD18 a single slot disables alone',    D.disabledList()[1], 'head');
        check('CMD18b ...only that one',               #D.disabledList(), 1);
        run('/dl disable ammo');
        check('CMD18c a second slot joins it',         #D.disabledList(), 2);
        run('/dl enable head');
        check('CMD18d ...and one can be released alone', D.disabledList()[1], 'ammo');
        check('CMD18e ...with the rest still named back', said[1], '[dlac] Head enabled - still disabled: ammo');
        check('CMD18f ...still one line',                 #said, 1);
        run('/dl enable all');
        check('CMD18g the all-clear is one line too', said[1], '[dlac] All slots enabled');

        -- The two off-forms, so nobody has to guess which release word works.
        run('/dl disable all');
        run('/dl disable off');
        check('CMD19 /dl disable off means enable all', D.disabledOn(), false);
        run('/dl disable legs');
        run('/dl disable legs off');
        check('CMD19b /dl disable <slot> off releases that slot', D.disabledOn('legs'), false);

        local e20 = run('/dl disable nosuchslot');
        check('CMD20 an unknown slot is named back',    said[1], '[dlac] "nosuchslot" is not a slot');
        check('CMD20b ...and still owns the command',   e20.blocked, true);
        check('CMD20c ...having disabled nothing',      D.disabledOn(), false);

        -- Two switches that both read as "stop moving my gear", one beating the
        -- other, is worth a line every time (the /lac disable precedent).
        run('/dl disable hands');
        run('/dl naked');
        check('CMD21 /dl naked warns that free equip outranks it', saidHas('Free equip is on'), true);
        check('CMD21b ...naming the slot it cannot strip',         saidHas('hands stay dressed'), true);
        run('/dl dress');
        run('/dl enable all');

        -- The GUI is a DIFFERENT Lua state and reads the engine's state through
        -- modestate's reserved __ namespace. No mirror = a checkbox that never
        -- moves, and no way to see free equip at all outside chat.
        run('/dl disable back');
        local ms = nil;
        pcall(function() ms = dofile('tests' .. SEP .. 'modestate.lua'); end);
        check('CMD22 the mirror carries __disabled',
              type(ms) == 'table' and type(ms.__disabled) == 'table', true);
        check('CMD22b ...naming the slot', ms and ms.__disabled and ms.__disabled.back, true);
        run('/dl enable all');
        ms = nil;
        pcall(function() ms = dofile('tests' .. SEP .. 'modestate.lua'); end);
        check('CMD22c ...and empties on release',
              ms and ms.__disabled and next(ms.__disabled), nil);
    end

    -- put every shared thing back exactly as it was
    prof.nativeMode, prof.dataDir   = saved.nativeMode, saved.dataDir;
    package.loaded['dlac\\dispatch'] = saved.dispatch;
    package.loaded['dlac\\chatfmt']  = saved.chatfmt;
    _G.gFunc, _G.gState             = saved.gFunc, saved.gState;
    eng.onEvent, eng.state.tripped  = saved.onEvent, saved.tripped;
    TEST_PLAYER                     = saved.player;
    os.remove('tests' .. SEP .. 'modestate.lua');
    os.remove('tests' .. SEP .. 'arbstate.lua');
end)();

-- ---------------------------------------------------------------------------
-- TRC. THE TRACE MUST NOT OUTLIVE THE WORLD IT DESCRIBED (field, 2026-07-26).
--
-- Mindie's boot: the install latch refused for ~2s (world not settled), the
-- Default dispatch built its trace lines against the EMPTY store -- "[NOT
-- FOUND in profile Sets]", true at that moment -- then the install landed,
-- equips worked, and /dl why kept printing the stale NOT FOUND lines with a
-- FRESH timestamp for the rest of the session. Cause: the retrace gate's sig
-- carries rules, locks and every overlay, but nothing about the SETS STORE,
-- and installSets' own re-dispatch therefore found the sig unchanged.
-- The law already exists as v118's "THE INSTALL INVALIDATES THE BELIEF";
-- M.modesRev is bumped by every install and re-flatten -- it belongs in the
-- sig. This section drives the real handler + dispatch exactly like CMD.
-- ---------------------------------------------------------------------------
(function()
    local SEP  = string.char(92);
    local prof = package.loaded['dlac\\profiles'];
    local eng  = package.loaded['dlac\\feature\\equipengine'];
    if type(prof) ~= 'table' or type(eng) ~= 'table' then return; end

    local saved = {
        nativeMode = prof.nativeMode,        dataDir = prof.dataDir,
        dispatch   = package.loaded['dlac\\dispatch'],
        chatfmt    = package.loaded['dlac\\chatfmt'],
        gFunc      = rawget(_G, 'gFunc'),    gState  = rawget(_G, 'gState'),
        gProfile   = rawget(_G, 'gProfile'),
        reg        = ashita.events.register, unreg   = ashita.events.unregister,
        player     = TEST_PLAYER,
        onEvent    = eng.onEvent,            tripped = eng.state.tripped,
    };

    local said = {};
    local function capture(...)
        local parts = {};
        for i = 1, select('#', ...) do parts[#parts + 1] = tostring((select(i, ...))); end
        said[#said + 1] = table.concat(parts, ' ');
    end
    package.loaded['dlac\\chatfmt'] = { print = capture, warn = capture, err = capture };

    -- The world: WHM idle, native armed, no LAC state, no stray gProfile.
    prof.nativeMode = function() return true; end
    prof.dataDir    = function() return 'tests' .. SEP; end
    _G.gFunc, _G.gState, _G.gProfile = nil, nil, nil;
    eng.state.tripped = false;
    TEST_PLAYER = { MainJob = 'WHM', MainJobLevel = 75, SubJob = 'BLM', SubJobLevel = 37,
                    MainJobSync = 75, SubJobSync = 37, Status = 'Idle', IsMoving = false };

    -- One Default rule aimed at a set that does not exist yet: the exact boot
    -- shape (rules load before the install latch lands).
    local trigDir  = 'tests' .. SEP .. 'triggers';
    local trigPath = trigDir .. SEP .. 'WHM.lua';
    -- Windows needs the directory made; on Linux `tests\triggers\WHM.lua` is ONE
    -- filename (backslash is an ordinary character there), so there is nothing to
    -- make. Guard the SHELL, not just the path: `2>nul` is cmd.exe's null device,
    -- but under sh -- the WSL CI-parity run -- it is a literal FILE named `nul`,
    -- dropped in the repo root every run (it broke a `git add`). Same guarded shape
    -- goldenfixtures and smoke_ui already use.
    if package.config:sub(1, 1) == '\\' then
        pcall(function() os.execute('mkdir "' .. trigDir .. '" >nul 2>&1'); end);
    end
    local tf = io.open(trigPath, 'w');
    if tf ~= nil then
        tf:write("return { Default = { { when = { status = 'Idle' }, set = 'Idle' } } };\n");
        tf:close();
    end

    local handlers = {};
    ashita.events.register   = function(ev, nm, fn) handlers[ev] = fn; end
    ashita.events.unregister = function() end
    local okLoad, D = pcall(dofile, 'dispatch.lua');
    ashita.events.register, ashita.events.unregister = saved.reg, saved.unreg;

    check('TRC0 dispatch loads native-armed', okLoad, true);
    if okLoad and type(handlers['command']) == 'function' then
        local function run(line)
            said = {};
            local e = { command = line, blocked = false };
            local ok, err = pcall(handlers['command'], e);
            if not ok then said[#said + 1] = 'ERROR: ' .. tostring(err); end
            return e, ok;
        end
        local function saidHas(frag)
            for _, l in ipairs(said) do
                if string.find(l, frag, 1, true) ~= nil then return true; end
            end
            return false;
        end

        -- Boot window: empty store. The NOT FOUND line is TRUE here.
        D._nativeSets = nil;
        pcall(D.dispatch, 'Default');
        run('/dl why');
        check('TRC1 empty store: the trace says NOT FOUND (true today)',
              saidHas('NOT FOUND in profile Sets'), true);
        check('TRC1b ...for the rule that matched', saidHas('set Idle'), true);

        -- The install lands: the store is swapped and modesRev bumped -- the
        -- two things EVERY installSets branch does (5668/5714). The next
        -- dispatch must rebuild the trace against the new world.
        D._nativeSets = { Dynamic = { Idle = { Body = 'Test Robe' } },
                          Idle    = { Body = 'Test Robe' } };
        D.modesRev = (D.modesRev or 0) + 1;
        pcall(D.dispatch, 'Default');
        run('/dl why');
        check('TRC2 after the install, the trace tells the truth',
              saidHas('NOT FOUND in profile Sets'), false);
        check('TRC2b ...still tracing the same rule', saidHas('set Idle'), true);

        -- And the reverse: the store DIES (a refused install empties it --
        -- 5689 -- after bumping modesRev at 5668). The trace must go stale
        -- honestly: NOT FOUND returns.
        D._nativeSets = nil;
        D.modesRev = (D.modesRev or 0) + 1;
        pcall(D.dispatch, 'Default');
        run('/dl why');
        check('TRC3 a dying store un-tells it too',
              saidHas('NOT FOUND in profile Sets'), true);
    end

    -- put every shared thing back exactly as it was
    prof.nativeMode, prof.dataDir    = saved.nativeMode, saved.dataDir;
    package.loaded['dlac\\dispatch'] = saved.dispatch;
    package.loaded['dlac\\chatfmt']  = saved.chatfmt;
    _G.gFunc, _G.gState              = saved.gFunc, saved.gState;
    _G.gProfile                      = saved.gProfile;
    eng.onEvent, eng.state.tripped   = saved.onEvent, saved.tripped;
    TEST_PLAYER                      = saved.player;
    os.remove(trigPath);
    os.remove('tests' .. SEP .. 'modestate.lua');
    os.remove('tests' .. SEP .. 'arbstate.lua');
end)();

-- ---------------------------------------------------------------------------
-- MDL. MODE LOCKS (2026-08-03, Henrik). "Once that mode is active, this slot
--     comes from THIS set and nothing in the trigger layer may move it."
--
--     Three tiers, because the feature has three failure modes and they are
--     nothing like each other:
--       MDL1-MDL9   the PURE planner -- who holds which slot, and the tie rule.
--                 A pairs()-ordered winner would land differently on two
--                 dispatches with nothing changed, which is a bug you can only
--                 catch by asking twice.
--       MDL10-MDL15 the WIPE CONTRACT -- locks live in the trigger file's Modes
--                 section, so a Commit that does not round-trip them silently
--                 unlocks every slot while the Modes list looks untouched.
--       MDL16-MDL22 END TO END through the REAL M.dispatch (the TRC/LS16 harness):
--                 the only tier that can prove a trigger rule actually loses
--                 the slot, on Default and on an action event alike.
-- ---------------------------------------------------------------------------
(function()
    local D = dispatchM;

    -- MDL1-MDL3. modeLocksOf: the ONE sanitizer, run on the way in AND out.
    local raw = { values = { 'Melee', 'Caster' },
                  locks = { ['Weapon:Melee'] = { main = 'MeleeWpn', Sub = 'MeleeWpn',
                                                 Nose = 'Nope', Head = 42 },
                            ['Weapon:Caster'] = {},
                            [''] = { Main = 'X' } } };
    local lk = D.modeLocksOf(raw);
    check('MDL1 a lac-case slot canonicalizes',        lk['Weapon:Melee'].Main, 'MeleeWpn');
    check('MDL1b a canonical slot passes through',     lk['Weapon:Melee'].Sub,  'MeleeWpn');
    check('MDL1c an unknown slot is dropped',          lk['Weapon:Melee'].Nose, nil);
    check('MDL1d a non-string set name is dropped',    lk['Weapon:Melee'].Head, nil);
    check('MDL2 a condition with no usable slot is dropped', lk['Weapon:Caster'], nil);
    check('MDL2b an empty condition key is dropped',   lk[''], nil);
    check('MDL3 a def with no locks answers nil',      D.modeLocksOf({ values = { 'A', 'B' } }), nil);
    check('MDL3b a non-table def answers nil',         D.modeLocksOf('nope'), nil);

    -- MDL4-MDL7. modeLockPlan: pure, both reads injected (the modeActive twin).
    local defs = {
        weapon = { name = 'Weapon', values = { 'Melee', 'Caster' },
                   locks = { ['Weapon:Melee'] = { Main = 'MeleeWpn', Sub = 'MeleeWpn' } } },
        dt     = { name = 'DT', locks = { ['DT'] = { Body = 'DTSet' } } },
    };
    check('MDL4 nothing active locks nothing', next(D.modeLockPlan(defs, {})), nil);
    local plan = D.modeLockPlan(defs, { weapon = 'Melee' });
    check('MDL5 the active cycle VALUE locks its slots',   plan.Main.set, 'MeleeWpn');
    check('MDL5b ...and names the mode that holds it',     plan.Main.by, 'Weapon:Melee');
    check('MDL5c ...for every slot it named',              plan.Sub.set, 'MeleeWpn');
    check('MDL5d ...and nothing it did not',               plan.Body, nil);
    check('MDL6 a DIFFERENT value of the same cycle does not fire',
        next(D.modeLockPlan(defs, { weapon = 'Caster' })), nil);
    local both = D.modeLockPlan(defs, { weapon = 'Melee', dt = true });
    check('MDL7 a toggle locks alongside a cycle', both.Body.set, 'DTSet');
    check('MDL7b ...and the cycle keeps its own',  both.Main.set, 'MeleeWpn');

    -- MDL8-MDL9. THE TIE: FIRST COME, FIRST SERVE (Henrik's ruling, 2026-08-03 --
    -- "the one who took the slot lock first should get it, the rest stand in
    -- queue"). Two active modes CAN name one slot; the ACTIVATION CLOCK decides,
    -- not the alphabet.
    local clash = {
        weapon = { name = 'Weapon', values = { 'Melee' },
                   locks = { ['Weapon:Melee'] = { Main = 'FromWeapon' } } },
        dt     = { name = 'DT', locks = { ['DT'] = { Main = 'FromDT' } } },
    };
    local live = { weapon = 'Melee', dt = true };
    -- Weapon took it FIRST (lower stamp) even though 'DT' sorts earlier: the
    -- alphabet must not be able to overrule the clock, which is the whole point.
    local p1, c1 = D.modeLockPlan(clash, live, { weapon = 1, dt = 2 });
    check('MDL8 the mode that took the slot FIRST holds it', p1.Main.by, 'Weapon:Melee');
    check('MDL8b ...even though the loser sorts alphabetically first', p1.Main.set, 'FromWeapon');
    -- Flip only the clock: the winner flips with it.
    local p2, c2 = D.modeLockPlan(clash, live, { weapon = 2, dt = 1 });
    check('MDL8c taking it first the other way round flips the winner', p2.Main.by, 'DT');
    check('MDL8d ...and the same inputs answer the same way twice',
        (D.modeLockPlan(clash, live, { weapon = 2, dt = 1 })).Main.by, p2.Main.by);
    -- No clock at all (an older mirror, or a headless caller): still deterministic.
    check('MDL8e with no clock it falls back to a STABLE order, never pairs() luck',
        (D.modeLockPlan(clash, live)).Main.by, 'DT');
    check('MDL8f ...and an equal-stamp tie breaks the same stable way',
        (D.modeLockPlan(clash, live, { weapon = 5, dt = 5 })).Main.by, 'DT');
    check('MDL9 the loser is queued, not swallowed', (c1 ~= nil) and c1[1].lost.set or nil, 'FromDT');
    check('MDL9b ...naming the slot and who holds it',
        (c1 ~= nil) and (c1[1].slot .. '/' .. c1[1].kept.set) or nil, 'Main/FromWeapon');
    check('MDL9c the queue flips with the clock', (c2 ~= nil) and c2[1].lost.set or nil, 'FromWeapon');
    -- THE QUEUE NEEDS NO STATE: drop the holder and the next in line simply wins
    -- the next walk -- which is what makes "the rest stand in queue" true without
    -- anything having to remember a queue.
    local p3, c3 = D.modeLockPlan(clash, { dt = true }, { weapon = 1, dt = 2 });
    check('MDL9d the holder going off hands the slot to the next in line', p3.Main.by, 'DT');
    check('MDL9e ...and nothing is left queued', c3, nil);

    -- MDL9f-MDL9i. THE CLOCK ITSELF: stamped on CHANGE, never on re-assertion --
    -- a macro that re-asserts a mode every pull must not send it to the back of
    -- the queue, and turning a mode off must release its place.
    local savedSeq, savedSeqN, savedModes = D.modeSeq, D.modeSeqN, D.modes;
    D.modeSeq, D.modeSeqN, D.modes = {}, 0, {};
    D.modeSet('dt', true);
    local first = D.modeSeq['dt'];
    D.modeSet('weapon', 'Melee');
    check('MDL9f the second mode stamps later', D.modeSeq['weapon'] > first, true);
    D.modeSet('dt', true);                      -- re-assert: nothing changed
    check('MDL9g re-asserting a mode does NOT move it down the queue', D.modeSeq['dt'], first);
    D.modeSet('weapon', 'Caster');              -- a real value change
    check('MDL9h changing a cycle VALUE is taking the slot again',
        D.modeSeq['weapon'] > D.modeSeq['dt'], true);
    D.modeSet('dt', nil);
    check('MDL9i turning a mode off releases its place', D.modeSeq['dt'], nil);
    D.modeSeq, D.modeSeqN, D.modes = savedSeq, savedSeqN, savedModes;

    -- MDL10-MDL15. THE WIPE CONTRACT. A Commit serializes the WHOLE model, so
    -- locks must survive serialize -> load -> fromRaw -> serialize byte for byte.
    -- If they do not, the Modes list looks identical and every slot is quietly
    -- unlocked -- the exact shape of the SetOptions/Modes bug that shipped once.
    local tmodel = dofile('gear/triggermodel.lua');
    local text = D.serializeTriggers({
        Default = { { when = { status = 'Idle' }, set = 'Idle' } },
        Modes = {
            Weapon = { values = { 'Melee', 'Caster' }, bind = '^F3',
                       locks = { ['Weapon:Melee'] = { Sub = 'MeleeWpn', Main = 'MeleeWpn' } } },
            DT     = { locks = { ['DT'] = { Body = 'DTSet' } } },
        },
    });
    check('MDL10 locks serialize into the Modes section',
        text:find('locks = { ["Weapon:Melee"] = { Main = "MeleeWpn", Sub = "MeleeWpn" } }', 1, true) ~= nil, true);
    check('MDL10b slots emit in vocabulary order, not pairs() order',
        text:find('{ Main = "MeleeWpn", Sub = "MeleeWpn" }', 1, true) ~= nil, true);
    check('MDL11 a bare toggle carries locks too',
        text:find('["DT"] = { locks = { ["DT"] = { Body = "DTSet" } } }', 1, true) ~= nil, true);
    local rawT = (loadstring or load)(text)();
    check('MDL12 the emitted file reloads', type(rawT), 'table');
    check('MDL13 serialize is byte-stable', D.serializeTriggers(rawT) == text, true);
    local model = tmodel.fromRaw(rawT, D.canonEvent);
    check('MDL14 WIPE CONTRACT: locks survive the edit model',
        (((model.Modes or {}).Weapon or {}).locks or {})['Weapon:Melee'].Main, 'MeleeWpn');
    check('MDL14b ...and the model re-serializes byte-identical', D.serializeTriggers(model) == text, true);
    -- Junk a hand-editor typed is dropped ONCE, on the way out, and never re-emitted.
    local junk = D.serializeTriggers({
        Modes = { X = { locks = { ['X'] = { Nose = 'Set', Feet = 'Set' } } } },
    });
    check('MDL15 an unknown slot never survives a Commit', junk:find('Nose', 1, true), nil);
    check('MDL15b ...while the good slot beside it does',  junk:find('Feet = "Set"', 1, true) ~= nil, true);

    -- MDL16-MDL22. END TO END. The TRC harness: a real trigger file, a real
    -- dispatch, a stubbed native equip door. This is the tier that can show a
    -- trigger rule LOSING a slot -- everything above is arithmetic.
    local SEP  = string.char(92);
    local prof = package.loaded['dlac\\profiles'];
    local eng  = package.loaded['dlac\\feature\\equipengine'];
    if type(prof) ~= 'table' or type(eng) ~= 'table' then return; end
    local saved = {
        nativeMode = prof.nativeMode,        dataDir = prof.dataDir,
        dispatch   = package.loaded['dlac\\dispatch'],
        engine     = package.loaded['dlac\\feature\\equipengine'],
        gFunc      = rawget(_G, 'gFunc'),    gState  = rawget(_G, 'gState'),
        gProfile   = rawget(_G, 'gProfile'),
        reg        = ashita.events.register, unreg   = ashita.events.unregister,
        player     = TEST_PLAYER,
    };
    prof.nativeMode = function() return true; end
    prof.dataDir    = function() return 'tests' .. SEP; end
    _G.gFunc, _G.gProfile = nil, nil;
    _G.gState = { CurrentCall = 'N/A', Disabled = {} };
    TEST_PLAYER = { MainJob = 'WHM', MainJobLevel = 75, SubJob = 'BLM', SubJobLevel = 37,
                    MainJobSync = 75, SubJobSync = 37, Status = 'Idle', IsMoving = false };

    local wrote = {};
    package.loaded['dlac\\feature\\equipengine'] = {
        nativeOn = function() return true; end,
        equipSet = function(t) for k, v in pairs(t or {}) do wrote[k] = v; end end,
        state    = { tripped = false },
    };

    local trigDir  = 'tests' .. SEP .. 'triggers';
    local trigPath = trigDir .. SEP .. 'WHM.lua';
    if package.config:sub(1, 1) == '\\' then
        pcall(function() os.execute('mkdir "' .. trigDir .. '" >nul 2>&1'); end);
    end
    local tf = io.open(trigPath, 'w');
    if tf ~= nil then
        -- Henrik's own case: a Weapon cycle whose Caster value swaps weapons on
        -- every event, and whose Melee value must never see one move.
        tf:write([[
return {
    Default  = { { when = { status = 'Idle' }, set = 'Idle' } },
    Midcast  = { { when = { any = true },      set = 'Nuke' } },
    Modes = {
        ["Weapon"] = { values = { "Melee", "Caster" },
                       locks = { ["Weapon:Melee"] = { Main = "LockedWpn", Head = "NoSuchSlot" } } },
    },
};
]]);
        tf:close();
    end

    local handlers = {};
    ashita.events.register   = function(ev, nm, fn) handlers[ev] = fn; end
    ashita.events.unregister = function() end
    local okLoad, E = pcall(dofile, 'dispatch.lua');
    ashita.events.register, ashita.events.unregister = saved.reg, saved.unreg;
    check('MDL16 dispatch loads with a locks-bearing trigger file', okLoad, true);

    if okLoad then
        -- Idle fills Main+Body; the lock's set fills Main only; NoSuchSlot fills
        -- nothing at all (the "lock that holds nothing" case, MDL21).
        E._nativeSets = {
            Dynamic     = { Idle = { Main = 'Rule Sword', Body = 'Rule Robe' },
                            Nuke = { Main = 'Rule Staff' },
                            LockedWpn  = { Main = 'Locked Sword' },
                            NoSuchSlot = { Body = 'Wrong Slot Piece' } },
            Idle        = { Main = 'Rule Sword', Body = 'Rule Robe' },
            Nuke        = { Main = 'Rule Staff' },
            LockedWpn   = { Main = 'Locked Sword' },
            NoSuchSlot  = { Body = 'Wrong Slot Piece' },
        };

        -- The cycle seats itself at values[1] = Melee on load, so start by
        -- jumping to Caster: the mode OFF baseline has to be a real baseline.
        E.setMode('Weapon', 'Caster');
        wrote = {};
        pcall(E.dispatch, 'Default');
        check('MDL17 with the lock inactive, the trigger rule owns Main', wrote.Main, 'Rule Sword');
        check('MDL17b ...and its other slots as always',                 wrote.Body, 'Rule Robe');

        E.setMode('Weapon', 'Melee');
        wrote = {};
        pcall(E.dispatch, 'Default');
        check('MDL18 the lock takes Main away from the rule',  wrote.Main, 'Locked Sword');
        check('MDL18b ...and leaves every other slot to it',   wrote.Body, 'Rule Robe');

        -- The whole point: the hold survives the events that swap weapons.
        wrote = {};
        pcall(E.dispatch, 'Midcast');
        check('MDL19 the lock holds on an ACTION event too', wrote.Main, 'Locked Sword');

        -- THE CLOCK MUST REACH THE OTHER LUA STATE. The GUI computes the same
        -- plan from the modestate mirror, so if `__seq` does not ride the file
        -- the window orders a contested slot alphabetically while the engine
        -- orders it by who took it first -- and names the wrong winner. Pins the
        -- wire format, which is the half a pure test cannot see.
        local mf = io.open('tests' .. SEP .. 'modestate.lua', 'r');
        local mtext = mf and mf:read('*a') or '';
        if mf then mf:close(); end
        check('MDL19b the mirror carries the activation clock',
            mtext:find('["__seq"]', 1, true) ~= nil, true);
        check('MDL19c ...stamping the mode that is actually active',
            mtext:find('["weapon"]', 1, true) ~= nil, true);
        local mchunk = (loadstring or load)(mtext);
        local mok, mstate = pcall(mchunk or function() end);
        check('MDL19d the mirror still parses with the clock in it', mok and type(mstate), 'table');
        -- The GUI's own call, with the defs it builds from its edit model and the
        -- two reads it has: the mirror's flags and the mirror's clock. It must
        -- reach the SAME answer the engine just equipped.
        local guiDefs = { weapon = { name = 'Weapon', values = { 'Melee', 'Caster' },
            locks = { ['Weapon:Melee'] = { Main = 'LockedWpn', Head = 'NoSuchSlot' } } } };
        local guiPlan = (mok and type(mstate) == 'table')
            and E.modeLockPlan(guiDefs, mstate, mstate.__seq) or {};
        check('MDL19e the GUI plans from the mirror and lands on the engine\'s answer',
            (guiPlan.Main or {}).set, 'LockedWpn');
        check('MDL19f ...naming the same holding mode', (guiPlan.Main or {}).by, 'Weapon:Melee');

        -- ...and lets go the moment the mode does. A lock that needed a reload
        -- to release would be worse than no lock.
        E.setMode('Weapon', 'Caster');
        wrote = {};
        pcall(E.dispatch, 'Default');
        check('MDL20 flipping the mode hands the slot straight back', wrote.Main, 'Rule Sword');

        -- A lock naming a set with no entry for its slot claims NOTHING: there
        -- is no answer to give, so the floor keeps the slot. The Mode Locks
        -- window flags this in red at edit time -- here we pin that it degrades
        -- quietly rather than blanking the slot.
        E.setMode('Weapon', 'Melee');
        wrote = {};
        pcall(E.dispatch, 'Default');
        check('MDL21 a lock whose set lacks the slot holds nothing', wrote.Head, nil);
        check('MDL21b ...and does not drag the wrong piece in',      wrote.Body, 'Rule Robe');

        -- The claimant is a REGISTERED row: /dl why must be able to name it, or
        -- a slot that stopped responding has no explanation anywhere.
        local named = nil;
        for _, row in ipairs(E._claimants) do
            if row.name == 'ModeLock' then named = row; break; end
        end
        check('MDL22 ModeLock is a registered claimant row', named ~= nil, true);
        check('MDL22b ...with a claim, an apply and a ladder',
            named ~= nil and named.claim ~= nil and named.apply ~= nil and named.rladder ~= nil, true);
        check('MDL22c ...and a live prioStatus naming the held slot',
            (named ~= nil) and (named.prioStatus():find('Main=LockedWpn', 1, true) ~= nil) or false, true);

        -- MDL23-MDL25. THE QUEUE MUST REACH THE DECISION RECORD (2026-08-03).
        -- The Arbiter Monitor renders STASHED records -- including pinned
        -- historical ones -- and derives nothing, so a queue computed live in the
        -- renderer would show TODAY's answer under a decision from ten minutes
        -- ago. Same law as the ladders and the reserve verdict: the queue that
        -- decided is the queue you read. Without this the monitor can only ever
        -- name the winner, which is the gap Henrik found by asking where the
        -- queue was visible.
        --
        -- A second mode locking the SAME slot. DT is armed FIRST (while Weapon
        -- holds Caster, which locks nothing), so DT takes Main; flipping Weapon
        -- to Melee afterwards makes Weapon:Melee the LATER arrival -- it queues,
        -- and the gear MOVES at the same time. That combination is deliberate:
        -- the ring appends on a moved OUTCOME, so a queue that forms while
        -- nothing moves reaches /dl why (the sig leg) but correctly does not
        -- mint a ring record with zero changed slots -- the v163 symptom.
        -- Weapon:Melee also locks an UNCONTESTED slot (Body), so its later
        -- arrival moves gear while it queues on Main. That is what lets the ring
        -- record it: the queue rides a decision that actually happened, rather
        -- than minting a record with nothing changed in it.
        local raw2 = D.readTriggersRaw(trigPath);
        raw2.Modes['DT'] = { locks = { ['DT'] = { Main = 'DTWpn' } } };
        raw2.Modes['Weapon'].locks['Weapon:Melee'].Body = 'LockedWpn';
        local tf2 = io.open(trigPath, 'w');
        if tf2 ~= nil then tf2:write(D.serializeTriggers(raw2)); tf2:close(); end
        E._nativeSets.DTWpn = { Main = 'DT Sword' };
        E._nativeSets.Dynamic.DTWpn = { Main = 'DT Sword' };
        E._nativeSets.LockedWpn.Body = 'Locked Robe';
        E._nativeSets.Dynamic.LockedWpn.Body = 'Locked Robe';
        E.reloadTriggers();
        E.setMode('Weapon', 'Caster');     -- locks nothing
        E.setMode('DT', true);             -- DT takes Main first
        wrote = {};
        pcall(E.dispatch, 'Default');
        check('MDL23 the first arrival takes the slot', wrote.Main, 'DT Sword');
        E.setMode('Weapon', 'Melee');      -- arrives LATER: queues behind DT
        wrote = {};
        pcall(E.dispatch, 'Default');
        check('MDL23b the later arrival does NOT take the contested slot', wrote.Main, 'DT Sword');
        check('MDL23c ...but DOES take the one nobody contests', wrote.Body, 'Locked Robe');
        local ring = E.getDecisions();
        local recQ = nil;
        for i = #ring, 1, -1 do
            if (ring[i].contest or {}).mlq ~= nil then recQ = ring[i]; break; end
        end
        check('MDL24 the decision record carries the queue', recQ ~= nil, true);
        if recQ ~= nil then
            local q = recQ.contest.mlq[1];
            check('MDL24b ...naming the contested slot', q.slot, 'Main');
            check('MDL24c ...who holds it',              q.kept.by, 'DT');
            check('MDL24d ...and who is waiting',        q.lost.by, 'Weapon:Melee');
        end
        -- Drop the holder: the queue empties and the waiter takes the slot, with
        -- nothing re-armed -- the "queue needs no state" claim, end to end.
        E.setMode('DT', false);
        wrote = {};
        pcall(E.dispatch, 'Default');
        check('MDL25 the holder going off hands Main to the one that waited', wrote.Main, 'Locked Sword');
        local ring2 = E.getDecisions();
        check('MDL25b ...and nothing is queued any more',
            (ring2[#ring2].contest or {}).mlq, nil);
        -- The QUEUE IS A RETRACE LEG (the rank-order precedent, v152): a mode
        -- that queues moves no gear and no claim, so without it in the leg the
        -- trace would keep saying nobody waits until something unrelated moved.
        local sigRow = nil;
        for _, row in ipairs(E._claimants) do
            if row.name == 'ModeLock' then sigRow = row; break; end
        end
        E.setMode('DT', true);             -- queues behind Weapon:Melee now
        E.modeLockLive();                  -- refresh M._modeLockQ the way ensure does
        local legQ = (sigRow ~= nil) and sigRow.sig(nil, true, E.modeLockLive()) or '';
        check('MDL26 the signature leg carries the queue', legQ:find('|q:Main<DT', 1, true) ~= nil, true);
        E.setMode('DT', false);
        E.modeLockLive();
        local legN = (sigRow ~= nil) and sigRow.sig(nil, true, E.modeLockLive()) or '';
        check('MDL26b ...and drops it when nobody waits', legN:find('|q:', 1, true), nil);
    end

    prof.nativeMode, prof.dataDir = saved.nativeMode, saved.dataDir;
    package.loaded['dlac\\dispatch'] = saved.dispatch;
    package.loaded['dlac\\feature\\equipengine'] = saved.engine;
    _G.gFunc, _G.gState, _G.gProfile = saved.gFunc, saved.gState, saved.gProfile;
    TEST_PLAYER = saved.player;
    os.remove(trigPath);
    os.remove('tests' .. SEP .. 'modestate.lua');
    os.remove('tests' .. SEP .. 'arbstate.lua');
end)();

-- ---------------------------------------------------------------------------
-- RQU. THE ENGINE MUST NOT WAIT FOR THE GUI TO LOAD ITS FLATTENER (field,
-- 2026-07-27, Xvs).
--
-- Every utils lookup in dispatch read package.loaded['dlac\\utils'] bare --
-- "loaded first in the LAC state" (the job shim's own first require). The
-- NATIVE state has no shim and nothing else loads utils at boot: the install
-- latch flattened NOTHING, refused every 0.4s as "world not settled", a
-- commit-time refusal nuked the store (nothing equips, /dl lock set finds no
-- set), and a session healed only when a GUI picker's lazy pcall(require)
-- happened to run -- which is why it read as per-JOB in the field (the healed
-- session's job "worked"; a game reload broke that job too). dispatch's
-- utilsModule() now requires lazily at call time. These drive the REAL
-- '/dl sets reload' handler through the exact boot shape: utils ABSENT from
-- package.loaded (package.preload stands in for the addon path, so the heal
-- needs no filesystem require headless).
-- ---------------------------------------------------------------------------
(function()
    local SEP  = string.char(92);
    local prof = package.loaded['dlac\\profiles'];
    local eng  = package.loaded['dlac\\feature\\equipengine'];
    if type(prof) ~= 'table' or type(eng) ~= 'table' then return; end

    local saved = {
        nativeMode = prof.nativeMode,        dataDir = prof.dataDir,
        dispatch   = package.loaded['dlac\\dispatch'],
        chatfmt    = package.loaded['dlac\\chatfmt'],
        utils      = package.loaded['dlac\\utils'],
        preload    = package.preload['dlac\\utils'],
        gFunc      = rawget(_G, 'gFunc'),    gState  = rawget(_G, 'gState'),
        gProfile   = rawget(_G, 'gProfile'),
        reg        = ashita.events.register, unreg   = ashita.events.unregister,
        player     = TEST_PLAYER,
        onEvent    = eng.onEvent,            tripped = eng.state.tripped,
    };
    local savedDM = saved.utils and saved.utils.dispatchModule or nil;

    local said = {};
    local function capture(...)
        local parts = {};
        for i = 1, select('#', ...) do parts[#parts + 1] = tostring((select(i, ...))); end
        said[#said + 1] = table.concat(parts, ' ');
    end
    package.loaded['dlac\\chatfmt'] = { print = capture, warn = capture, err = capture };

    -- The world: WHM idle, native armed, no LAC state, no stray gProfile.
    prof.nativeMode = function() return true; end
    prof.dataDir    = function() return 'tests' .. SEP; end
    _G.gFunc, _G.gState, _G.gProfile = nil, nil, nil;
    eng.state.tripped = false;
    -- Level 63: no earlier section leaves utils' rebuild cache there, so the
    -- level delta alone forces a re-flatten even before the modesRev wire below.
    TEST_PLAYER = { MainJob = 'WHM', MainJobLevel = 63, SubJob = 'BLM', SubJobLevel = 31,
                    MainJobSync = 63, SubJobSync = 31, Status = 'Idle', IsMoving = false };

    -- The active profile's sets file, where readSetsSource looks. Inline
    -- records (Name+Level), so the harness's empty NameToObject never matters.
    local setsDir  = 'tests' .. SEP .. 'profiles' .. SEP .. 'Default' .. SEP .. 'sets';
    local setsPath = setsDir .. SEP .. 'WHM.lua';
    if package.config:sub(1, 1) == '\\' then
        pcall(function() os.execute('mkdir "' .. setsDir .. '" >nul 2>&1'); end);
    end
    local sf = io.open(setsPath, 'w');
    if sf ~= nil then
        sf:write("return { Dynamic = { Idle = { Body = { { Name = 'Test Robe', Level = 1 } } } } };\n");
        sf:close();
    end

    local handlers = {};
    ashita.events.register   = function(ev, nm, fn) handlers[ev] = fn; end
    ashita.events.unregister = function() end
    local okLoad, D = pcall(dofile, 'dispatch.lua');
    ashita.events.register, ashita.events.unregister = saved.reg, saved.unreg;

    check('RQU0 dispatch loads native-armed', okLoad, true);
    if okLoad and type(handlers['command']) == 'function' then
        -- In the game the lazy require executes utils.lua fresh, whose own
        -- require('dlac\\dispatch') binds the LIVE engine instance. The harness
        -- preload hands back the long-loaded utils instead, so wire its
        -- dispatchModule to THIS dispatch copy to mirror that binding.
        if saved.utils ~= nil then saved.utils.dispatchModule = D; end

        local function run(line)
            said = {};
            local e = { command = line, blocked = false };
            local ok, err = pcall(handlers['command'], e);
            if not ok then said[#said + 1] = 'ERROR: ' .. tostring(err); end
            return e, ok;
        end
        local function saidHas(frag)
            for _, l in ipairs(said) do
                if string.find(l, frag, 1, true) ~= nil then return true; end
            end
            return false;
        end

        -- The native boot shape: NOTHING has loaded utils in this state yet.
        package.loaded['dlac\\utils'] = nil;
        package.preload['dlac\\utils'] = function() return saved.utils; end
        run('/dl sets reload');
        check('RQU1 utils absent: the reload flattens and lands', saidHas('sets hot-swapped'), true);
        check('RQU1b ...never the world-not-settled refusal', saidHas('flatten produced no sets'), false);
        check('RQU1c ...and the lazy require left utils loaded',
              package.loaded['dlac\\utils'], saved.utils);

        -- utils truly unresolvable: the refusal stays a refusal (safe, no
        -- crash) -- the pre-fix behavior is the fallback, never an error.
        -- package.path is emptied for the run: earlier sections leave paths
        -- that CAN resolve dlac\utils (exactly as the game's addons\?.lua
        -- does), and this case is specifically about the require FAILING.
        -- The store is cleared first -- that is the boot shape, and a store
        -- RQU1 already flattened would satisfy the count with no flatten.
        D._nativeSets = nil;
        package.loaded['dlac\\utils'] = nil;
        package.preload['dlac\\utils'] = nil;
        local savedPath = package.path;
        package.path = '';
        run('/dl sets reload');
        package.path = savedPath;
        check('RQU2 utils unresolvable: still the honest refusal, no crash',
              saidHas('flatten produced no sets'), true);
    end

    -- put every shared thing back exactly as it was
    package.loaded['dlac\\utils']  = saved.utils;
    package.preload['dlac\\utils'] = saved.preload;
    if saved.utils ~= nil then saved.utils.dispatchModule = savedDM; end
    prof.nativeMode, prof.dataDir    = saved.nativeMode, saved.dataDir;
    package.loaded['dlac\\dispatch'] = saved.dispatch;
    package.loaded['dlac\\chatfmt']  = saved.chatfmt;
    _G.gFunc, _G.gState              = saved.gFunc, saved.gState;
    _G.gProfile                      = saved.gProfile;
    eng.onEvent, eng.state.tripped   = saved.onEvent, saved.tripped;
    TEST_PLAYER                      = saved.player;
    os.remove(setsPath);
    os.remove('tests' .. SEP .. 'modestate.lua');
    os.remove('tests' .. SEP .. 'arbstate.lua');
end)();

-- ---------------------------------------------------------------------------
-- PRG. THE PURGE ALLOWLIST (Phase 4, Henrik's keep-list). A luashitacast PATH
-- LITERAL in shipped code -- the two-backslash string form `\\luashitacast` --
-- may exist ONLY in the sanctioned importer/migration READERS. Comments write
-- the single-backslash form and never trip this. The roster below IS the
-- coverage cap: a brand-new shipped file must be added here to be guarded
-- (a named limitation, not a silent one).
-- ---------------------------------------------------------------------------
(function()
    local SHIPPED = { 'dlac.lua','utils.lua','dispatch.lua','profiles.lua','chatfmt.lua','gear.lua',
        'feature/augments.lua','feature/check.lua','feature/chocowatch.lua','feature/craftwatch.lua',
        'feature/debug.lua','feature/eboxclient.lua','feature/eboxtrace.lua','feature/engine.lua',
        'feature/equipengine.lua','feature/fishwatch.lua','feature/helmwatch.lua','feature/lockstyle.lua',
        'feature/lockstyleapply.lua','feature/location.lua','feature/macrobook.lua','feature/meritwatch.lua',
        'feature/mpbands.lua','feature/nativedata.lua','feature/synthrun.lua','feature/useitem.lua',
        'gear/catalogindex.lua','gear/equipcore.lua','gear/gearcheck.lua','gear/gearexport.lua',
        'gear/gearfmt.lua','gear/gearimport.lua','gear/gearoptim.lua','gear/gearoracle.lua',
        'gear/gearrecord.lua','gear/jobgate.lua','gear/ownedcache.lua','gear/profilesets.lua',
        'gear/setimport.lua','gear/setmanager.lua','gear/weaponfilter.lua',
        'lib/cmdqueue.lua','lib/safewrite.lua','lib/statefile.lua','lib/entwatch.lua',
        'ui/automationsui.lua','ui/chocoui.lua','ui/craftbar.lua','ui/equippedui.lua','ui/fishbar.lua',
        'ui/fishui.lua','ui/gearui.lua','ui/helmbar.lua','ui/menuui.lua','ui/priorityui.lua',
        'ui/profilesmenu.lua','ui/restockui.lua','ui/setupui.lua','ui/triggersui.lua','ui/uihost.lua',
        'ui/uistyle.lua','ui/itemicons.lua' };
    local ALLOW = {   -- Henrik's keep-list: read-only doors into the old tree
        ['profiles.lua'] = true,          -- charBase/lacRoot/legacyDataPresent/legacyExportsDir
        ['gear/setmanager.lua'] = true,   -- the job-file scanner (whole-block import)
        -- (lockstyle, macrobook and gearoptim came OFF this list 2026-08-05:
        -- their literals fed dataDir fallbacks that could never fire, so the
        -- literals went with the fallbacks. Nothing was allowlisted away here --
        -- there is simply no legacy path left in those three files.)
    };
    local offenders = {};
    for _, f in ipairs(SHIPPED) do
        local fh = io.open(f, 'rb');
        if fh ~= nil then
            local raw = fh:read('*a'); fh:close();
            if raw:find('\\\\luashitacast', 1, true) ~= nil and not ALLOW[f] then
                offenders[#offenders + 1] = f;
            end
        end
    end
    check('PRG1 no legacy path literal outside the allowlist', table.concat(offenders, ','), '');
    check('PRG2 the importer door itself still exists', (function()
        local fh = io.open('profiles.lua', 'rb');
        if fh == nil then return false; end
        local raw = fh:read('*a'); fh:close();
        return raw:find('\\\\luashitacast', 1, true) ~= nil;
    end)(), true);

    -- PRG3: THE COMPOSED FALLBACK. PRG1 greps for the path LITERAL, so it was
    -- blind to the shape that actually survived the purge -- taking the LEGACY
    -- char base from somewhere else and hanging `dlac\` off it:
    --
    --     local base = charBase();  return base and (base .. 'dlac\\') or nil;
    --     if ddir == nil then ddir = base .. 'dlac\\'; end
    --
    -- Six of those outlived Phase 4 in five files, invisible to the guard,
    -- because the literal lives in profiles.charBase and the composition lives
    -- in the consumer. They were all dead code -- dataDir and charBase resolve
    -- off the same identity, so the fallback only fired when it was about to
    -- return nil anyway -- but one of them aimed the trigger editor at the
    -- legacy tree, and the same blindness hid a THIRD variant for months: the
    -- debug handoff readers kept a `dlac\` segment after the writer dropped it,
    -- so no engine half ever merged into a /dl report.
    --
    -- The rule this pins: `.. 'dlac\\'` composed onto anything is illegal in
    -- shipped code. The native home already carries the character level, and
    -- profiles.dataDir() is the only composer.
    -- profiles.lua is the ONE exception, and only for the two migration readers:
    -- _legacyProbe (does this character have legacy data?) and
    -- engineMigrateStorage's copyTree SOURCE. Both must name the old layout --
    -- that is their whole job. Everything else composes through dataDir().
    local COMPOSE_ALLOW = { ['profiles.lua'] = true };
    local composed = {};
    for _, f in ipairs(SHIPPED) do
        local fh = io.open(f, 'rb');
        if fh ~= nil then
            local raw = fh:read('*a'); fh:close();
            -- strip comment lines first: the ban is on CODE, and the comments
            -- explaining the removal must be free to name the shape they killed.
            local code = {};
            for line in (raw .. '\n'):gmatch('([^\n]*)\n') do
                if line:match('^%s*%-%-') == nil then code[#code + 1] = line; end
            end
            if table.concat(code, '\n'):find("%.%.%s*'dlac\\\\'") ~= nil and not COMPOSE_ALLOW[f] then
                composed[#composed + 1] = f;
            end
        end
    end
    check('PRG3 no composed legacy `.. \'dlac\\\\\'` path in shipped code',
          table.concat(composed, ','), '');
end)();

-- ---------------------------------------------------------------------------
-- SH. Commit reads gear.lua's SHAPE instead of assuming its own (field bug,
--     07-28, Abraxis). A legacy LuAshitacast gear.lua nests Ammo by category
--     (Archery/Marksmanship/Throwing) and says so in its own trailer; dlac
--     writes Ammo flat. The splice inserted the flat entry as a SIBLING of the
--     category tables -- the file still parsed, so the parse check passed, and
--     the trailer then evaluated ("Bone Arrow").Name -> nil:
--
--         gear.lua.tmp:9765: table index is nil
--
--     ...which named the trailer, ~6400 lines from the cause. Commit aborted
--     every time, so NO gear of any slot ever landed, the same batch re-staged
--     forever, and 15 identical backups piled up in 90 minutes.
--
--     Three pins: the shape is READ, a disagreement ABORTS with the slot named,
--     and a legitimately category-nested file is NOT flagged as broken.
-- ---------------------------------------------------------------------------
(function()
local gi = dofile('gear/gearimport.lua');
local function L(t) local o = {}; for l in (t .. '\n'):gmatch('([^\n]*)\n') do o[#o+1] = l; end return o; end

-- a file shaped like the field one: Ammo nested, Head flat
local legacy = table.concat({
    'gear = {',
    '    Ammo = {',
    '        Archery = {',
    '            BoneArrow = {',
    '                Name = "Bone Arrow",',
    '                Level = 7,',
    '                Stats = {',
    '                    DMG = 9,',
    '                }',
    '            },',
    '        },',
    '    },',
    '    Head = {',
    '        OldCap = {',
    '            Name = "Old Cap",',
    '        },',
    '    },',
    '};',
}, '\n');

local shapes = gi._slotShapes(L(legacy));
check('SH1 nested Ammo read as category', shapes.Ammo, 'category');
check('SH2 flat Head read as entry',      shapes.Head, 'entry');
-- an entry carrying a multi-line Stats block must NOT read as a category
check('SH3 Stats block does not fake a category', gi._slotShapes(L(table.concat({
    'gear = {', '    Head = {',
    '        StatCap = {',
    '            Name = "Stat Cap",',
    '            Stats = {',
    '                DEF = 9,',
    '            }',
    '        },',
    '    },', '};',
}, '\n'))).Head, 'entry');

local ammoStaging = table.concat({
    'return {',
    '    Ammo = {',
    '        SilverArrow = {',
    '            Name = "Silver Arrow",',
    '        },',
    '    },',
    '}',
}, '\n') .. '\n';
local spliced, rep = gi.spliceStaging(legacy, ammoStaging);
check('SH4 shape conflict reported',   #rep.shapeConflict, 1);
check('SH5 conflict names the slot',   rep.shapeConflict[1] and rep.shapeConflict[1].slot, 'Ammo');
check('SH6 conflict names the file shape', rep.shapeConflict[1] and rep.shapeConflict[1].found, 'category');
check('SH7 nothing spliced into it',   rep.inserted, 0);
check('SH8 text left byte-identical',  spliced, legacy .. '\n');
-- the pre-fix behaviour, pinned as the thing that must never come back
check('SH9 not silently reported as notfound', #rep.notfound, 0);

-- a flat slot in a flat file still takes its entry
local okSplice = select(2, gi.spliceStaging(legacy, table.concat({
    'return {', '    Head = {', '        NewCap = {', '            Name = "New Cap",',
    '        },', '    },', '}',
}, '\n') .. '\n'));
check('SH10 matching shape still inserts', okSplice.inserted, 1);
check('SH11 matching shape has no conflict', #okSplice.shapeConflict, 0);

-- SH10c-f. THE NEW BUCKET LANDS IN A FILE THAT HAS NEVER SEEN IT. The skill-0
-- Range families (animators, soultrappers) now index into Range.PUP / Range.Misc
-- (gearimport.rangeCategory, E29*) -- but a player whose gear.lua predates that
-- has no such category, and a fix that stages an entry with nowhere to put it
-- would heal nothing. The category is CREATED under its existing parent.
do
    local ranged = table.concat({
        'gear = {',
        '    Range = {',
        '        Throwing = {',
        '            Boomerang = {',
        '                Name = "Boomerang",',
        '            },',
        '        },',
        '    },',
        '};',
    }, '\n');
    local _, aRep = gi.spliceStaging(ranged, table.concat({
        'return {', '    Range = {', '        PUP = {', '            Animator = {',
        '                Name = "Animator",', '            },', '        },', '    },', '}',
    }, '\n') .. '\n');
    check('SH10c a missing Range bucket is created, not "notfound"', aRep.inserted, 1);
    check('SH10d ...and reported as created',   aRep.created[1], 'Range.PUP');
    check('SH10e nothing went missing',         #aRep.notfound, 0);
    check('SH10f no shape conflict with a category-nested Range', #aRep.shapeConflict, 0);
end

-- gearProblems: names the culprit, and stays quiet on a consistent legacy file
local function built(text)
    local c = (loadstring or load)(text);
    local env = setmetatable({}, { __index = _G });
    if setfenv ~= nil then setfenv(c, env); end
    pcall(c);
    return env.gear, L(text);
end
local okGear, okLines = built(legacy);
check('SH12 consistent nested file is NOT flagged', #gi.gearProblems(okGear, okLines), 0);

local badGear, badLines = built(table.concat({
    'gear = {',
    '    Ammo = {',
    '        SilverArrow = {',
    '            Name = "Silver Arrow",',
    '        },',
    '        Archery = {',
    '            BoneArrow = {',
    '                Name = "Bone Arrow",',
    '            },',
    '        },',
    '    },',
    '};',
}, '\n'));
local probs = gi.gearProblems(badGear, badLines);
check('SH13 wrong-depth entry diagnosed', #probs, 1);
check('SH14 diagnosis names the entry, not the trailer',
      probs[1] ~= nil and probs[1]:find('SilverArrow', 1, true) ~= nil, true);
check('SH15 diagnosis carries a line number',
      probs[1] ~= nil and probs[1]:find('line 3', 1, true) ~= nil, true);

local nnGear, nnLines = built(table.concat({
    'gear = {', '    Head = {',
    '        GoodCap = { Name = "Good Cap", },',
    '        BadCap = {',
    '            Level = 20,',
    '        },',
    '    },', '};',
}, '\n'));
local nnProbs = gi.gearProblems(nnGear, nnLines);
check('SH16 Name-less entry diagnosed', #nnProbs, 1);
check('SH17 Name-less diagnosis names it',
      nnProbs[1] ~= nil and nnProbs[1]:find('BadCap', 1, true) ~= nil, true);

-- Defect from the same family: indexGear/parseStaging used their own
-- `= {%s*$` patterns while parseGearEntries (fix/dedupe/prune) tolerated a
-- trailing comment. A commented CATEGORY header was invisible to indexGear
-- alone, so commit "created" a section that already existed, Lua's
-- last-key-wins discarded the new block, and commit reported success while
-- the items silently never landed.
local commented = table.concat({
    'gear = {',
    '    Main = { -- weapons',
    '        Sword = { -- my swords',
    '            OldSword = {',
    '                Name = "Old Sword",',
    '            },',
    '        },',
    '    },',
    '};',
}, '\n');
local _, cRep = gi.spliceStaging(commented, table.concat({
    'return {', '    Main = {', '        Sword = {', '            NewSword = {',
    '                Name = "New Sword",', '            },', '        },', '    },', '}',
}, '\n') .. '\n');
check('SH18 commented headers still index',  cRep.inserted, 1);
check('SH19 no phantom duplicate section',   #cRep.created, 0);
check('SH20 commented slot header found',    #cRep.notfound, 0);

-- Henrik's ruling, 2026-07-28: **dlac handles its own gear locally; the ONLY
-- FFXI-LAC integration is the Dynamic sets import.** Setup used to seed a new
-- character's gear.lua by COPYING `<charBase>\ffxi-lac\gear.lua` when one
-- existed -- which is how a brand-new install ended up with a foreign,
-- Ammo-nested, Id-less inventory dlac could not extend. The guard is a path
-- guard, deliberately: prose about ffxi-lac is fine and the CONTENT sniff that
-- routes an old profile into the sets migration must survive (SH22) -- what may
-- never come back is dlac READING a file out of that tree to seed itself.
local ffxiLacPathUsers = {};
for _, f in ipairs({ 'dlac.lua', 'utils.lua', 'profiles.lua', 'dispatch.lua',
                     'ui/setupui.lua', 'ui/gearui.lua', 'gear/gearimport.lua',
                     'gear/setmanager.lua', 'gear/profilesets.lua', 'gear/setimport.lua' }) do
    local fh = io.open(f, 'rb');
    if fh ~= nil then
        local raw = fh:read('*a'); fh:close();
        -- the PATH form only: 'ffxi-lac\' as written in a Lua string literal
        if raw:find('ffxi%-lac\\\\') ~= nil then ffxiLacPathUsers[#ffxiLacPathUsers + 1] = f; end
    end
end
check('SH21 nothing reads out of the ffxi-lac tree', table.concat(ffxiLacPathUsers, ','), '');
check('SH22 the sets-migration door still exists', (function()
    local fh = io.open('ui/setupui.lua', 'rb');
    if fh == nil then return false; end
    local raw = fh:read('*a'); fh:close();
    return raw:find("'ffxi-lac'", 1, true) ~= nil;   -- the CONTENT sniff -> st = 'ffxilac'
end)(), true);
end)();

-- ---------------------------------------------------------------------------
-- JH: the Job helper module system (issue #137) -- loader containment (good /
-- wrong-api / throwing / malformed fixtures), the config store, the per-job
-- order, and the module-activity predicate. All driven through injected seams
-- so no filesystem or Ashita is touched (the house shape).
-- ---------------------------------------------------------------------------
(function()
    package.loaded['dlac\\lib\\statefile'] = { charDir = function() return nil; end };
    local jh = dofile('feature/jobhelpers.lua');
    package.loaded['dlac\\feature\\jobhelpers'] = jh;

    -- ---- loader containment -------------------------------------------------
    -- Fixture "folders": each loadModule thunk returns what a folder's init.lua
    -- would (a good table, a wrong-api table), or ERRORS (a throwing/malformed
    -- folder). The loader must keep the good one and refuse the rest, one loud
    -- line + one ledger entry each, no crash.
    local good = { api = jh.API, label = 'Good Helper', jobs = { 'BST' },
                   panel = function() end };
    local wrongApi = { api = jh.API + 1, label = 'Old Helper', jobs = { 'BST' },
                       panel = function() end };
    local loaders = {
        good     = function() return true, good; end,
        wrongapi = function() return true, wrongApi; end,
        throwing = function() return pcall(function() error('boom in init.lua'); end); end,
        malformed= function() return true, 'not a table'; end,
    };
    local ledger = { total = 0, failed = {} };
    local lines = {};
    jh.loadAll({
        names      = { 'good', 'malformed', 'throwing', 'wrongapi' },  -- unsorted on purpose
        loadModule = function(id) return loaders[id](); end,
        ledger     = ledger,
        emit       = function(s) lines[#lines + 1] = s; end,
    });
    check('JH1 only the good module loads', jh.count(), 1);
    check('JH2 the survivor is the good one', jh.list()[1].id, 'good');
    check('JH3 three failures fed the ledger', #ledger.failed, 3);
    check('JH4 ledger total counts every candidate (1 good + 3 failed)', ledger.total, 4);
    check('JH5 one loud line per failure', #lines, 3);
    -- ledger entries are namespaced so /dl check reads them
    local failIds = {};
    for _, f in ipairs(ledger.failed) do failIds[f.mod] = f.err; end
    check('JH6 wrong-api named in the ledger',
          failIds['jobhelper:wrongapi'] ~= nil and failIds['jobhelper:wrongapi']:find('api', 1, true) ~= nil, true);
    check('JH7 throwing module contained + named', failIds['jobhelper:throwing'] ~= nil, true);
    check('JH8 malformed folder named', failIds['jobhelper:malformed'] ~= nil, true);

    -- a module whose OWN init hook throws is contained too (distinct from a load
    -- failure): it loads fine, then init errors -> refused, one line, ledger.
    local ledger2 = { total = 0, failed = {} };
    local lines2 = {};
    jh.loadAll({
        names      = { 'boominit' },
        loadModule = function() return true, { api = jh.API, label = 'B', jobs = { 'BST' },
            init = function() error('init explode'); end, panel = function() end }; end,
        ledger = ledger2, emit = function(s) lines2[#lines2 + 1] = s; end,
    });
    check('JH9 init-throw drops the module', jh.count(), 0);
    check('JH10 init-throw is one ledger failure', #ledger2.failed, 1);
    check('JH11 init-throw named as init', (ledger2.failed[1] or {}).err and ledger2.failed[1].err:find('init', 1, true) ~= nil, true);

    -- the optional `window` hook (ADR 0028 amendment 2026-08-04): a function
    -- loads and rides the record; anything else is refused loudly, naming the
    -- hook, like every other malformed piece of the contract.
    local ledger3 = { total = 0, failed = {} };
    jh.loadAll({
        names      = { 'badwindow', 'withwindow' },
        loadModule = function(id)
            if id == 'withwindow' then
                return true, { api = jh.API, label = 'W', jobs = { 'BST' },
                               panel = function() end, window = function() end };
            end
            return true, { api = jh.API, label = 'BW', jobs = { 'BST' },
                           panel = function() end, window = 'not a function' };
        end,
        ledger = ledger3, emit = function() end,
    });
    check('JH11b a module with a window hook loads', jh.count(), 1);
    check('JH11c its record carries the hook', type(jh.list()[1].mod.window), 'function');
    check('JH11d a non-function window is refused', #ledger3.failed, 1);
    check('JH11e ...naming the window hook',
          (ledger3.failed[1] or {}).err and ledger3.failed[1].err:find('window', 1, true) ~= nil, true);

    -- `open` (the quick-menu verb, 2026-08-04): same law -- function or refused.
    local ledger4 = { total = 0, failed = {} };
    jh.loadAll({
        names = { 'badopen' },
        loadModule = function() return true, { api = jh.API, label = 'BO', jobs = { 'BST' },
            panel = function() end, open = 'nope' }; end,
        ledger = ledger4, emit = function() end,
    });
    check('JH11f a non-function open is refused', #ledger4.failed, 1);
    check('JH11g ...naming the open hook',
          (ledger4.failed[1] or {}).err and ledger4.failed[1].err:find('open', 1, true) ~= nil, true);

    -- ---- registry queries ---------------------------------------------------
    local a = { api = jh.API, label = 'Alpha', jobs = { 'BST', 'PUP' }, panel = function() end };
    local b = { api = jh.API, label = 'Beta',  jobs = { 'PUP' },        panel = function() end };
    jh.loadAll({ names = { 'alpha', 'beta' },
        loadModule = function(id) return true, ({ alpha = a, beta = b })[id]; end });
    check('JH12 both loaded', jh.count(), 2);
    check('JH13 jobs() lists the union, sorted', table.concat(jh.jobs(), ','), 'BST,PUP');
    check('JH14 idsForJob BST = the multi-job module only', table.concat(jh.idsForJob('BST'), ','), 'alpha');
    check('JH15 idsForJob PUP = both, default order', table.concat(jh.idsForJob('PUP'), ','), 'alpha,beta');

    -- ---- the quick-menu listing (menuEntriesCore, 2026-08-04) ---------------
    -- alpha declares BST+PUP, beta PUP only (loaded above). Pure core: jobs and
    -- both per-id switches injected, so every case runs with no player.
    local yes = function() return true; end
    local no  = function() return false; end
    local function menu(m, s, f, e)
        local t = {};
        for _, r in ipairs(jh.menuEntriesCore(m, s, f, e)) do t[#t + 1] = r.id .. ':' .. r.via; end
        return table.concat(t, ',');
    end
    check('JH15a main-job helpers list via main', menu('BST', 'WHM', yes, yes), 'alpha:main');
    check('JH15b sub-job helpers ride behind main', menu('WAR', 'PUP', yes, yes), 'alpha:sub,beta:sub');
    check('JH15c the sub switch excludes from the sub door', menu('WAR', 'PUP', no, yes), '');
    check('JH15d a multi-job module lists ONCE, via main', menu('BST', 'PUP', yes, yes), 'alpha:main,beta:sub');
    check('JH15e a silenced module is not offered at all', menu('BST', 'PUP', yes, no), '');
    check('JH15f unknown jobs list nothing', menu(nil, '?', yes, yes), '');
    check('JH15g same main and sub collects once, via main', menu('PUP', 'PUP', yes, yes), 'alpha:main,beta:main');

    -- openHelper: a declared hook runs (handed rec.S -- nil in this harness,
    -- since modapi does not resolve headless); no hook = false (the caller
    -- falls back to the Panel jump).
    local opened = 0;
    jh.modules[1].mod.open = function() opened = opened + 1; end
    check('JH15h openHelper runs a declared hook', jh.openHelper('alpha'), true);
    check('JH15i ...exactly once', opened, 1);
    check('JH15j no hook answers false', jh.openHelper('beta'), false);
    jh.modules[1].mod.open = nil;

    -- ---- config store (pill + per-job order) -------------------------------
    -- point the store at an in-memory fake dir so writes round-trip through the
    -- real serialize/normalize path with a stubbed file layer.
    local FILES = {};
    local realOpen = io.open;
    jh._charDir = function() return 'FAKEDIR\\'; end
    io.open = function(path, mode)
        if type(path) == 'string' and path:find('FAKEDIR', 1, true) then
            if (mode or 'r'):find('w') then
                return { write = function(_, s) FILES[path] = (FILES[path] or '') .. s; end,
                         close = function() end };
            else
                if FILES[path] == nil then return nil; end
                local consumed = false;
                return { read = function() if consumed then return nil; end consumed = true; return FILES[path]; end,
                         close = function() end };
            end
        end
        return realOpen(path, mode);
    end
    -- loadfile is what the reader uses; back it with our FILES table.
    local realLoadfile = loadfile;
    loadfile = function(path)
        if type(path) == 'string' and path:find('FAKEDIR', 1, true) then
            local src = FILES[path];
            if src == nil then return nil; end
            return (loadstring or load)(src);
        end
        return realLoadfile(path);
    end

    check('JH16 pill default is ON for an untouched module', jh.isEnabled('alpha'), true);
    jh.setEnabled('alpha', false);
    check('JH17 pill toggles off', jh.isEnabled('alpha'), false);
    check('JH18 the config file was written', FILES['FAKEDIR\\jobhelpers.lua'] ~= nil, true);
    -- reload from disk (fresh char dir key) proves it round-trips
    jh._loadCfg();  -- warm
    local reread = jh._normalizeCfg((loadstring or load)(FILES['FAKEDIR\\jobhelpers.lua'])());
    check('JH19 off state survives a re-read', reread.enabled['alpha'], false);

    -- the sub-job switch (2026-08-04): default ON, only the opt-out is stored,
    -- and the opt-out round-trips like the pill. The write stub above APPENDS
    -- on every open (a real 'wb' truncates), so each snapshot clears first.
    check('JH19a sub-job default is ON for an untouched module', jh.subjobApplicable('alpha'), true);
    FILES['FAKEDIR\\jobhelpers.lua'] = nil;
    jh.setSubjobApplicable('alpha', false);
    check('JH19b the opt-out takes', jh.subjobApplicable('alpha'), false);
    local reread2 = jh._normalizeCfg((loadstring or load)(FILES['FAKEDIR\\jobhelpers.lua'])());
    check('JH19c the opt-out survives a re-read', reread2.subjob['alpha'], false);
    FILES['FAKEDIR\\jobhelpers.lua'] = nil;
    jh.setSubjobApplicable('alpha', true);
    check('JH19d flipping back to the default clears the entry',
          jh.subjobApplicable('alpha'), true);
    local reread3 = jh._normalizeCfg((loadstring or load)(FILES['FAKEDIR\\jobhelpers.lua'])());
    check('JH19e ...and the file stores no default-true rows', reread3.subjob['alpha'], nil);

    -- per-job order: reorder PUP section (alpha,beta) -> (beta,alpha), persisted.
    local moved = jh.moveInSection('PUP', { 'alpha', 'beta' }, 1, 1);
    check('JH20 move swaps within the section', table.concat(moved, ','), 'beta,alpha');
    check('JH21 orderFor now returns the remembered order',
          table.concat(jh.orderFor('PUP', { 'alpha', 'beta' }), ','), 'beta,alpha');
    -- a newly installed module backfills at the bottom, unknown ones drop
    check('JH22 order backfills a new id at the bottom',
          table.concat(jh.orderFor('PUP', { 'alpha', 'beta', 'gamma' }), ','), 'beta,alpha,gamma');
    check('JH23 order drops an uninstalled id from the walk',
          table.concat(jh.orderFor('PUP', { 'beta' }), ','), 'beta');
    -- an out-of-range move is a no-op (nil)
    check('JH24 move past the top is refused', jh.moveInSection('PUP', { 'beta', 'alpha' }, 1, -1), nil);

    io.open = realOpen; loadfile = realLoadfile;

    -- ---- the module-activity predicate -------------------------------------
    local mod = { jobs = { 'BST' } };
    check('JH25 off pill -> reason off',
          jh.activityCore(mod, { enabled = false, mainJob = 'BST' }).reason, 'off');
    check('JH26 wrong main job -> reason job',
          jh.activityCore(mod, { enabled = true, mainJob = 'WHM' }).reason, 'job');
    check('JH27 right job, in town -> reason town',
          jh.activityCore(mod, { enabled = true, mainJob = 'BST', inTown = true }).reason, 'town');
    check('JH28 dead outranks town',
          jh.activityCore(mod, { enabled = true, mainJob = 'BST', inTown = true, dead = true }).reason, 'dead');
    check('JH29 zoning outranks dead',
          jh.activityCore(mod, { enabled = true, mainJob = 'BST', dead = true, zoning = true }).reason, 'zoning');
    check('JH30 clear world -> active',
          jh.activityCore(mod, { enabled = true, mainJob = 'BST' }).active, true);
    check('JH31 unknown job never manufactures a reason (nil job -> active)',
          jh.activityCore(mod, { enabled = true, mainJob = nil }).active, true);
    check('JH32 the pre-login unreadable job string is not a false wrong-job',
          jh.activityCore(mod, { enabled = true, mainJob = '?' }).active, true);

    -- reset the registry so nothing downstream sees the fixtures.
    jh.modules = {};
    package.loaded['dlac\\feature\\jobhelpers'] = nil;
    package.loaded['dlac\\lib\\statefile'] = nil;
end)();

-- ---------------------------------------------------------------------------
-- RC: the ability recast READINESS service (issue #138). One-question core,
-- reader injected -- ready when off cooldown, down otherwise, and UNKNOWN reads
-- READY (the courtesy gate, hard rule 11). AC7/AC8.
-- ---------------------------------------------------------------------------
;(function()
    local rc = dofile('feature/recast.lua');
    local sig = rc.REWARD;
    check('RC1 ready when the reader says 0s', (rc.readyFor(sig, function() return 0; end)), true);
    check('RC2 down when the reader says 12s', (rc.readyFor(sig, function() return 12; end)), false);
    local ready2, rem2 = rc.readyFor(sig, function() return 12; end);
    check('RC3 the remaining seconds come back too', rem2, 12);
    check('RC4 unknown (nil) reads READY', (rc.readyFor(sig, function() return nil; end)), true);
    check('RC5 a throwing reader is unknown -> ready', (rc.readyFor(sig, function() error('boom'); end)), true);
    check('RC6 a negative recast clamps to 0 (ready)', (rc.readyFor(sig, function() return -3; end)), true);
    check('RC7 remainingFor returns nil on a non-number', rc.remainingFor(sig, function() return 'x'; end), nil);
    check('RC8 Reward is ability 103 (ported from Pup-Helper)', sig.id, 103);

    -- The two SUMMON methods (issue #141). Neither hardcodes a recast slot: the
    -- Pup-Helper reference only ever named Reward's, so these resolve theirs by
    -- NAME through the client's own ability resource -- live memory over every
    -- other source (hard rule 9) -- and an unresolvable one reads READY.
    check('RC9 Call Beast is named, not numbered', rc.CALL_BEAST.name, 'Call Beast');
    check('RC10 ...and so is Bestial Loyalty', rc.BESTIAL_LOYALTY.name, 'Bestial Loyalty');
    check('RC11 a declared timer id still wins (Reward\'s port)', rc.timerIdFor(rc.REWARD), 103);
    local asked = {};
    rc._abilityRes = function(name) asked[#asked + 1] = name; return { RecastTimerId = 77 }; end;
    check('RC12 an undeclared one resolves BY NAME off the resource',
          rc.timerIdFor({ name = 'Call Beast' }), 77);
    check('RC13 ...asking for exactly that ability', asked[1], 'Call Beast');
    rc._abilityRes = function() return nil; end;
    check('RC14 an unresolvable slot is UNKNOWN, never a guess',
          rc.timerIdFor({ name = 'Nonesuch' }), nil);
    check('RC15 ...which the live read turns into "ready" (the courtesy gate)',
          (rc.readyFor({ name = 'Nonesuch' }, rc.liveRemaining)), true);
    check('RC16 a resolution failure is NOT latched (hard rule 11)', (function()
        local sig2 = { name = 'Call Beast' };
        rc.timerIdFor(sig2);                                     -- fails: no resource yet
        rc._abilityRes = function() return { RecastTimerId = 42 }; end;
        return rc.timerIdFor(sig2);                              -- the resource is up now
    end)(), 42);
    check('RC17 Call Beast reads ready through its own one-liner',
          (rc.callBeastReady(function() return 0; end)), true);
    check('RC18 ...and down when measured down',
          (rc.bestialLoyaltyReady(function() return 900; end)), false);

    -- --- THE UNIT (2026-07-30). The client stores ability recast in JIFFIES,
    --     1/60s. This was /4 -- a quarter-second guess borrowed from
    --     nativedata's RecastDelay, which is a RESOURCE field and a different
    --     unit -- so every countdown dlac ever showed was 15x too big. Settled
    --     by two independent addons on disk: timers\recasts.lua builds its
    --     baseline as `60 * (90 + reduction)` ("the same format as timer is
    --     stored in"), Rune-Actually-Helper divides by 60 ("jiffies -> seconds").
    rc.forgetAbilities();
    rc._abilityRes  = function() return { RecastTimerId = 55 }; end;
    rc._recastMgr = function()
        return {
            GetAbilityTimerId = function(_, i) if i == 7 then return 55; end return 0; end,
            GetAbilityTimer   = function(_, i) if i == 7 then return 60 * 1200; end return 0; end,
        };
    end;
    check('RC19 a 20-minute recast reads as 1200 seconds, not 18000',
          rc.liveRemaining({ name = 'Bestial Loyalty' }), 1200);
    check('RC20 ...so the ability measures DOWN, and the fallback can see it',
          (rc.readyFor({ name = 'Bestial Loyalty' }, rc.liveRemaining)), false);
    -- READY and UNKNOWN are different answers. They were both nil until
    -- 2026-07-30, which is precisely why the Resummon rule could not tell an
    -- ability it knew was up from one it could not see at all.
    rc._recastMgr = function()
        return {
            GetAbilityTimerId = function() return 0; end,
            GetAbilityTimer   = function() return 0; end,
        };
    end;
    check('RC20a resolved, on no slot -> 0 seconds: MEASURED ready',
          rc.liveRemaining({ name = 'Call Beast' }), 0);
    rc._abilityRes = function() return nil; end;
    check('RC20b unresolvable -> nil: UNKNOWN, a different thing entirely',
          rc.liveRemaining({ name = 'Nonesuch' }), nil);
    check('RC20c ...and both still read READY to a button, which is right',
          (rc.readyFor({ name = 'Nonesuch' }, rc.liveRemaining)), true);

    -- --- THE RESOLUTION (2026-07-30). One name index was tried and abilities
    --     got `0`; dlac already hedges TWO indexes for items in two places
    --     because one did not answer. An unresolved slot is UNKNOWN, unknown
    --     read READY, and the Resummon rule fired into its own cooldown.
    -- A FRESH instance: the resolver is the thing under test here, and the
    -- checks above have replaced it on `rc` several times over.
    local rc2 = dofile('feature/recast.lua');
    local probed = {};
    AshitaCore = {
        GetResourceManager = function()
            return {
                GetAbilityByName = function(_, name, idx)
                    probed[#probed + 1] = tostring(name) .. '@' .. tostring(idx);
                    if idx == 2 and name == 'Bestial Loyalty' then return { RecastTimerId = 94 }; end
                    return nil;
                end,
            };
        end,
    };
    check('RC21 an index that answers is found even when the first does not',
          (rc2._abilityRes('Bestial Loyalty') or {}).RecastTimerId, 94);
    check('RC22 ...having actually probed more than one', #probed > 1, true);

    -- ...and when NO index answers, the whole table is walked once and indexed
    -- by name -- the read an index convention cannot defeat.
    local rc3 = dofile('feature/recast.lua');
    local built = 0;
    AshitaCore = {
        GetResourceManager = function()
            return {
                GetAbilityByName = function() return nil; end,
                GetAbilityById   = function(_, id)
                    built = built + 1;
                    if id == 387 then return { RecastTimerId = 94, Name = { 'Bestial Loyalty' } }; end
                    if id == 85  then return { RecastTimerId = 104, Name = { 'Call Beast' } }; end
                    return nil;
                end,
            };
        end,
    };
    check('RC23 no index answers -> the scan finds it anyway',
          (rc3._abilityRes('Bestial Loyalty') or {}).RecastTimerId, 94);
    check('RC24 ...case-insensitively', (rc3._abilityRes('call beast') or {}).RecastTimerId, 104);
    local after = built;
    rc3._abilityRes('Call Beast');
    check('RC25 ...and the scan is LATCHED, not repeated per frame', built, after);
    local rc4 = dofile('feature/recast.lua');
    AshitaCore = nil;
    check('RC26 no client at all is UNKNOWN, never a throw', rc4._abilityRes('Call Beast'), nil);

    -- --- THE GUARD (2026-07-30, and this is the one that mattered). Ashita's
    --     resource objects are NOT Lua tables -- they index with `.` and answer
    --     `userdata` to `type()`. Every working reader in dlac and in the proven
    --     sibling addons checks `~= nil`: nativedata (`res ~= nil` then
    --     `res.RecastTimerId`), dispatch's item lookup (`if r ~= nil`),
    --     Rune-Actually-Helper (`if cand ~= nil and cand.RecastTimerId == id`).
    --     recast.lua type-checked instead, so the by-NAME resolution never once
    --     returned a slot, from the day it was written. Reward hid it: it
    --     declares timerId = 103 and never takes the name path, so its countdown
    --     always worked while both summons read UNKNOWN -- and unknown reads
    --     READY, which is how the Resummon rule fired into a cooldown.
    --
    --     Driven with a REAL non-table object (a file handle is userdata in
    --     stock Lua), because a table stand-in passes either way and would have
    --     proven nothing -- which is exactly how this survived a test suite.
    local rc5 = dofile('feature/recast.lua');
    local UD = io.stdout;
    check('RC27 the stand-in really is not a table', type(UD) ~= 'table', true);
    AshitaCore = {
        GetResourceManager = function()
            return { GetAbilityByName = function() return UD; end };
        end,
    };
    check('RC28 a non-table resource object is ACCEPTED, not silently dropped',
          rc5._abilityRes('Call Beast'), UD);
    check('RC29 ...and reading a field off one never throws',
          rc5.timerIdFor({ name = 'Call Beast' }), nil);

    -- The same NON-TABLE object, this time carrying the field the resolver
    -- wants. The read is stubbed because stock Lua cannot fabricate userdata
    -- with fields -- what is under test is the GUARD in timerIdFor, which used
    -- to reject the object before ever reading it.
    local rc6 = dofile('feature/recast.lua');
    AshitaCore = {
        GetResourceManager = function()
            return { GetAbilityByName = function() return UD; end };
        end,
    };
    rc6._field = function(obj, key)
        if obj == UD and key == 'RecastTimerId' then return 94; end
        return nil;
    end;
    check('RC30 ...and a NON-TABLE one carrying the field resolves its slot',
          rc6.timerIdFor({ name = 'Bestial Loyalty' }), 94);
    AshitaCore = nil;
end)();

-- ---------------------------------------------------------------------------
-- PF: the pet-food LADDER (issue #138). Highest tier the level allows AND the
-- bags hold; carrying none is a LOUD refusal. AC4/AC8.
-- ---------------------------------------------------------------------------
;(function()
    local pf = dofile('feature/petfood.lua');
    local stock = { [17016] = 2, [17019] = 1 };    -- carrying Alpha(12) + Delta(48)
    local function of(t) return function(id) return t[id] or 0; end end
    local p = pf.pick({ level = 50, stockOf = of(stock) });
    check('PF1 picks the highest carried tier the level allows', p.ok and p.name, 'Pet Food Delta');
    local p2 = pf.pick({ level = 40, stockOf = of(stock) });
    check('PF2 falls to a lower tier when the top carried one is over-level', p2.ok and p2.name, 'Pet Food Alpha');
    local p3 = pf.pick({ level = 30, stockOf = of({ [17023] = 1 }) });   -- only Theta(96)
    check('PF3 carrying only over-level food -> level refusal', p3.ok == false and p3.reason, 'level');
    local p4 = pf.pick({ level = 75, stockOf = of({}) });
    check('PF4 carrying none -> none-carried refusal', p4.ok == false and p4.reason, 'none-carried');
    check('PF4b and it is a loud honest line', pf.refusalLine(p4):find('not carrying', 1, true) ~= nil, true);
    local p5 = pf.pick({ level = nil, stockOf = of({ [17023] = 1 }) });
    check('PF5 unknown level treats the carried tier as wearable', p5.ok and p5.name, 'Pet Food Theta');
    check('PF6 the ladder carries all eight tiers', #pf.TIERS, 8);

    -- --- the LEVEL the ladder gates on is the one the ENGINE gears at (issue
    -- #140, from the #138 merge review). House law, paid for by AutoAmmo v134:
    -- every picker reads the /dl set level main override and then the SYNC-aware
    -- level -- never raw MainJobLevel. Under level sync a raw read picks a food
    -- tier above the cap, the equip is refused, and the sequence ends in a
    -- contained verify timeout instead of correctly falling a rung.
    local realG, realOvr = rawget(_G, 'gData'), rawget(_G, 'staticMainLevel');
    _G.gData = { GetPlayer = function() return { MainJobSync = 40, MainJobLevel = 75 }; end };
    _G.staticMainLevel = nil;
    check('PF7 the level read is the SYNC-aware one, not the true job level', pf._playerLevel(), 40);
    _G.staticMainLevel = 62;
    check('PF8 ...and /dl set level main overrides even that', pf._playerLevel(), 62);
    _G.staticMainLevel = 0;
    check('PF9 an unset override (0) is not an override', pf._playerLevel(), 40);
    _G.gData = { GetPlayer = function() return { MainJobSync = 0 }; end };
    _G.staticMainLevel = nil;
    check('PF10 a not-yet-settled level reads UNKNOWN, never 0', pf._playerLevel(), nil);
    -- ...and unknown never hides a carried tier (PF5's rule, through liveReads)
    pf._stockOf = function(id) if id == 17023 then return 1; end return 0; end
    check('PF11 an unknown level still picks the carried tier',
          (pf.choose(pf.liveReads()) or {}).name, 'Pet Food Theta');
    -- the sync cap FALLS a rung rather than picking over it
    _G.gData = { GetPlayer = function() return { MainJobSync = 30, MainJobLevel = 99 }; end };
    pf._stockOf = function(id) if id == 17023 or id == 17016 then return 1; end return 0; end
    check('PF12 under level sync the ladder falls to the tier the cap allows',
          (pf.choose(pf.liveReads()) or {}).name, 'Pet Food Alpha');
    _G.gData, _G.staticMainLevel = realG, realOvr;
end)();

-- ---------------------------------------------------------------------------
-- PV: the PET VITALS service (issue #140). ONE question -- "is a pet out right
-- now, and how is it doing?" -- with the pet read injected, so presence, the
-- dead-pet law, the individually-nil-able vitals, the subscriber push and the
-- per-beat throttle all drive headlessly. AC5.
-- ---------------------------------------------------------------------------
;(function()
    local pv = dofile('feature/petvitals.lua');

    -- --- the pure core: a gData.GetPet() record in, the vitals answer out
    local live = { HPP = 62, TP = 1250, Name = 'Courier Carrie', Index = 745, Status = 'Engaged' };
    local v = pv.fromPet(live);
    check('PV1 a live pet is PRESENT', v.present, true);
    check('PV2 ...with its HP%', v.hpp, 62);
    check('PV3 ...its TP', v.tp, 1250);
    check('PV4 ...and its name', v.name, 'Courier Carrie');
    check('PV5 no pet record at all -> not present', pv.fromPet(nil).present, false);

    -- THE LAW: dead pet = no pet.
    check('PV6 a pet at 0 HP% is NOT a pet', pv.fromPet({ HPP = 0, Name = 'Courier Carrie' }).present, false);
    check('PV7 ...and carries no vitals to act on', pv.fromPet({ HPP = 0, TP = 3000 }).tp, nil);
    check('PV8 1 HP% is still a pet', pv.fromPet({ HPP = 1 }).present, true);

    -- an unreadable vital is reported honestly, never guessed
    check('PV9 a present pet with no readable HP says so', pv.fromPet({ Name = 'Carrie' }).hpp, nil);
    check('PV10 ...and is still present', pv.fromPet({ Name = 'Carrie' }).present, true);
    check('PV11 a padded entity name is trimmed (the GetName idiom)',
          pv.fromPet({ HPP = 50, Name = 'Sheep Familiar\0  ' }).name, 'Sheep Familiar');
    check('PV12 a blank name reads as no name', pv.fromPet({ HPP = 50, Name = '   ' }).name, nil);

    -- --- the one exported question, reads injected
    check('PV13 get() answers through the injected read',
          pv.get({ pet = function() return live; end }).name, 'Courier Carrie');
    check('PV14 a THROWING read is not permission to act',
          pv.get({ pet = function() error('boom'); end }).present, false);
    check('PV15 an absent read is not permission either', pv.get({}).present, false);

    -- --- subscribers + the per-beat throttle
    pv.reset(true);
    local beats = {};
    check('PV16 the pump does not read the world with nobody listening',
          pv.pump(0, { pet = function() error('must not be called'); end }), nil);
    check('PV17 subscribing takes a name and a callback', pv.subscribe('t', function(x) beats[#beats + 1] = x; end), true);
    check('PV18 ...and is counted', pv.subscriberCount(), 1);
    local READS = { pet = function() return live; end };
    pv.pump(100, READS);
    check('PV19 one beat pushes the vitals', #beats, 1);
    check('PV20 ...the live record', beats[1].hpp, 62);
    check('PV21 ...stamped', beats[1].at, 100);
    pv.pump(100.2, READS);
    check('PV22 a second beat inside the window is skipped', #beats, 1);
    pv.pump(100.5, READS);
    check('PV23 ...and published once the beat elapses', #beats, 2);
    check('PV24 last() is the published record', pv.last().hpp, 62);
    -- a clock that went BACKWARDS publishes rather than muting for a window
    pv.pump(3, READS);
    check('PV25 a backwards clock publishes, never mutes', #beats, 3);
    -- one throwing subscriber never costs another its beat
    pv.subscribe('bad', function() error('boom'); end);
    pv.pump(10, READS);
    check('PV26 a throwing subscriber does not cost the others their beat', #beats, 4);
    check('PV27 unsubscribing drops it', pv.unsubscribe('bad') and pv.subscriberCount(), 1);
    pv.reset(true);
    check('PV28 reset(true) drops the subscribers too', pv.subscriberCount(), 0);
    check('PV29 ...and the published record', pv.last(), nil);

    -- --- the live read consumes gData.GetPet (the ONE pet reader), never a
    -- second GetPetTargetIndex/GetHPPercent pair of its own.
    local realG = rawget(_G, 'gData');
    _G.gData = { GetPet = function() return live; end };
    check('PV30 the live read goes through gData.GetPet', pv.get().name, 'Courier Carrie');
    _G.gData = { GetPet = function() return nil; end };
    check('PV31 ...and a petless gData answers not present', pv.get().present, false);
    _G.gData = {};
    check('PV32 a gData without the provider is not permission to act', pv.get().present, false);
    _G.gData = realG;
end)();

-- ---------------------------------------------------------------------------
-- PVL: the CLASSIFIED PET-LOSS EDGE the vitals service gained (issue #141).
-- "My pet is gone -- why?", answered as a PURE function of the before/after
-- vitals plus what the world was observed doing. DEATH IS CONFIRMED, NEVER
-- ASSUMED: only the falls line or a low last-seen HP% prove one, and an
-- observed Leave / zoning / logout each suppress ahead of both. AC2/AC6.
-- ---------------------------------------------------------------------------
;(function()
    local pv = dofile('feature/petvitals.lua');

    local OUT  = { present = true, hpp = 78, name = 'Hare Familiar' };
    local HURT = { present = true, hpp = 9,  name = 'Hare Familiar' };
    local GONE = { present = false };
    -- The BST module's roster stands in as the injected name authority.
    local function jugAuth(name)
        if name == 'Hare Familiar' or name == 'Courier Carrie' then return true; end
        return false;
    end

    -- --- the falls line: matched lowercased, subject sliced from the original
    check('PVL1 a falls line names its subject', pv.fallsSubject('Hare Familiar falls to the ground.'),
          'Hare Familiar');
    check('PVL2 ...the message article is not part of the name',
          pv.fallsSubject('The Forest Hare falls to the ground.'), 'Forest Hare');
    check('PVL3 matched case-insensitively (the digrank lesson)',
          pv.fallsSubject('Hare Familiar FALLS TO THE GROUND.'), 'Hare Familiar');
    check('PVL4 an unrelated line is not a falls line',
          pv.fallsSubject('Hare Familiar hits the Forest Hare for 12 points of damage.'), nil);
    check('PVL4a the client\'s inline colour codes do not stick to the name',
          pv.fallsSubject('\30\01Hare Familiar\30\02 falls to the ground.'), 'Hare Familiar');
    check('PVL4b ...so such a line still matches MY pet',
          pv.isPetFalls('\30\01Hare Familiar\30\02 falls to the ground.', 'Hare Familiar'), true);
    check('PVL5 MY pet falling matches', pv.isPetFalls('Hare Familiar falls to the ground.', 'Hare Familiar'), true);
    check('PVL6 the mob I just killed does NOT',
          pv.isPetFalls('The Forest Hare falls to the ground.', 'Hare Familiar'), false);
    check('PVL7 a server that writes "Your pet" is still understood',
          pv.isPetFalls('Your pet falls to the ground.', 'Hare Familiar'), true);
    check('PVL8 ...and without a known pet name, a named subject is not assumed to be mine',
          pv.isPetFalls('The Forest Hare falls to the ground.', nil), false);

    -- --- nothing to classify
    check('PVL9 no pet was out -> no edge', pv.classifyLoss(nil, GONE, {}).lost, false);
    check('PVL10 a pet still out -> no edge', pv.classifyLoss(OUT, OUT, {}).lost, false);

    -- --- the three suppressors, checked BEFORE any death proof
    check('PVL11 zoning suppresses', pv.classifyLoss(HURT, GONE, { zoning = true }).kind, 'zone');
    check('PVL12 ...even with a falls line in the window',
          pv.classifyLoss(HURT, GONE, { zoning = true, falls = true }).confirmed, false);
    check('PVL13 logging out suppresses', pv.classifyLoss(HURT, GONE, { logout = true }).kind, 'logout');
    check('PVL14 an observed Leave suppresses', pv.classifyLoss(HURT, GONE, { leave = true }).kind, 'leave');
    check('PVL15 ...and a Leave on a DYING pet is still a Leave, never a death',
          pv.classifyLoss(HURT, GONE, { leave = true, falls = true }).kind, 'leave');

    -- --- the two proofs of death
    local d1 = pv.classifyLoss(OUT, GONE, { falls = 'Hare Familiar', isJugPet = jugAuth });
    check('PVL16 a falls line confirms a death at ANY last-seen HP', d1.kind, 'death');
    check('PVL17 ...and says so', d1.confirmed, true);
    check('PVL18 ...naming which proof', d1.how, 'falls');
    local d2 = pv.classifyLoss(HURT, GONE, { isJugPet = jugAuth });
    check('PVL19 a vanish after LOW HP confirms a death with no line at all', d2.kind, 'death');
    check('PVL20 ...by the other proof', d2.how, 'low-hp');
    check('PVL21 the low-HP ceiling is a threshold, not a guess',
          pv.classifyLoss({ present = true, hpp = pv.LOW_HP_PCT + 1, name = 'Hare Familiar' },
                          GONE, {}).kind, 'unknown');
    check('PVL22 ...and sitting exactly on it still confirms',
          pv.classifyLoss({ present = true, hpp = pv.LOW_HP_PCT, name = 'Hare Familiar' },
                          GONE, {}).kind, 'death');
    check('PVL23 an override moves the ceiling',
          pv.classifyLoss(OUT, GONE, { lowHp = 90 }).kind, 'death');

    -- --- gone with nothing to say why: confirms NOTHING (the whole law)
    local d3 = pv.classifyLoss(OUT, GONE, { isJugPet = jugAuth });
    check('PVL24 a healthy pet that vanished is UNKNOWN, never a death', d3.kind, 'unknown');
    check('PVL25 ...and confirms nothing', d3.confirmed, false);
    check('PVL26 ...but is still a loss', d3.lost, true);

    -- --- jug vs charm, decided by NAME through the injected authority
    check('PVL27 a jug pet is recognised by name', d1.pet, 'jug');
    check('PVL28 a charmed pet keeps its mob name and reads as charm',
          pv.classifyLoss({ present = true, hpp = 4, name = 'Forest Hare' }, GONE,
                          { isJugPet = jugAuth }).pet, 'charm');
    check('PVL29 ...and its death is still a DEATH, just not a jug one',
          pv.classifyLoss({ present = true, hpp = 4, name = 'Forest Hare' }, GONE,
                          { isJugPet = jugAuth }).kind, 'death');
    check('PVL30 no authority at all -> unknown, which is not a jug',
          pv.classifyLoss(HURT, GONE, {}).pet, 'unknown');
    check('PVL31 a THROWING authority is not permission either',
          pv.classifyLoss(HURT, GONE, { isJugPet = function() error('boom'); end }).pet, 'unknown');
    check('PVL32 the edge carries the pet as last seen', d2.name .. '/' .. tostring(d2.hpp),
          'Hare Familiar/9');

    -- --- the signal inbox: what the world said, with a shelf life
    pv.clearSignals();
    pv.noteSignal('falls', 100, 'Hare Familiar');
    check('PVL33 a noted signal is readable inside the window', pv.signals(101).falls, 'Hare Familiar');
    check('PVL34 ...and expires after the TTL', pv.signals(100 + pv.SIGNAL_TTL_S + 1).falls, nil);
    pv.noteSignal('leave', 200);
    check('PVL35 a signal with no name reads as true', pv.signals(201).leave, true);
    check('PVL36 a backwards clock keeps the signal rather than expiring it',
          pv.signals(150).leave, true);
    pv.clearSignals();
    check('PVL37 clearing empties the inbox', pv.signals(201).leave, nil);

    -- --- the edge on the BEAT: one loss, published once, to loss subscribers
    pv.reset(true);
    pv.lossCtx.isJugPet = jugAuth;
    local edges = {};
    local petNow = HURT;
    local READS = { pet = function() return (petNow.present and { HPP = petNow.hpp, Name = petNow.name }) or nil; end,
                    zoning = function() return false; end, loggingOut = function() return false; end };
    check('PVL38 a LOSS subscriber alone keeps the beat alive',
          pv.subscribeLoss('t', function(e) edges[#edges + 1] = e; end) and pv.lossSubscriberCount(), 1);
    check('PVL39 ...so the pump reads the world with no vitals subscriber at all',
          (pv.pump(100, READS) or {}).present, true);
    check('PVL40 a pet that is OUT publishes no loss', #edges, 0);
    check('PVL41 ...and is remembered as the edge\'s "before"', pv.lastPresent().hpp, 9);
    petNow = GONE;
    pv.pump(101, READS);
    check('PVL42 the vanish publishes exactly one edge', #edges, 1);
    check('PVL43 ...classified as a confirmed death', edges[1].kind .. '/' .. tostring(edges[1].confirmed),
          'death/true');
    check('PVL44 ...of a jug pet', edges[1].pet, 'jug');
    check('PVL45 ...stamped with the beat', edges[1].at, 101);
    pv.pump(102, READS);
    pv.pump(103, READS);
    check('PVL46 a pet that stays gone never re-fires the edge', #edges, 1);
    check('PVL47 lastLoss() answers the same edge', pv.lastLoss().kind, 'death');
    check('PVL48 ...and the "before" is spent', pv.lastPresent(), nil);

    -- a Leave observed in the window suppresses the very same transition
    pv.reset(false);
    edges, petNow = {}, HURT;
    pv.pump(200, READS);
    pv.noteSignal('leave', 200);
    petNow = GONE;
    pv.pump(201, READS);
    check('PVL49 the same vanish reads as a LEAVE once one was observed', edges[1].kind, 'leave');
    check('PVL50 ...and the signal does not explain the NEXT loss too', pv.signals(201).leave, nil);

    -- zoning wins over everything, read live through the injected reads
    pv.reset(false);
    edges, petNow = {}, HURT;
    READS.zoning = function() return true; end;
    pv.pump(300, READS);
    petNow = GONE;
    pv.pump(301, READS);
    check('PVL51 the live zoning read suppresses at the beat too', edges[1].kind, 'zone');
    READS.zoning = function() return false; end;

    -- a text line only becomes a signal while a pet is actually out
    pv.reset(false);
    petNow = OUT;
    pv.pump(400, READS);
    check('PVL52 a falls line about MY pet becomes a signal',
          pv.onTextLine('Hare Familiar falls to the ground.', 400) and pv.signals(400).falls,
          'Hare Familiar');
    pv.clearSignals();
    check('PVL53 ...a line about the mob does not',
          pv.onTextLine('The Forest Hare falls to the ground.', 400), false);

    -- --- the LEAVE observation: decode on the packet thread, resolve on ours
    pv.resetCommands();
    pv.clearSignals();
    -- an outgoing 0x01A: category 0x09 (Ability) at 0x0A, ability id at 0x0C
    local function actionPkt(cat, abil)
        local b = {};
        for i = 1, 16 do b[i] = 0; end
        b[0x0A + 1] = cat % 256;  b[0x0A + 2] = math.floor(cat / 256);
        b[0x0C + 1] = abil % 256; b[0x0C + 2] = math.floor(abil / 256);
        local s = '';
        for i = 1, 16 do s = s .. string.char(b[i]); end
        return s;
    end
    check('PVL54 an ability action packet decodes to its ability id',
          pv.decodeCommand(actionPkt(0x09, 261)), 261);
    check('PVL55 a battle EDGE is not this reader\'s packet (engagewatch owns those)',
          pv.decodeCommand(actionPkt(0x02, 261)), nil);
    check('PVL56 a torn packet decodes to nothing', pv.decodeCommand('\0\0'), nil);
    pv.onCommandPacket(actionPkt(0x09, 261));
    check('PVL57 the drain notes a Leave when the name resolves to one',
          pv.drainCommands(500, function(id) if id == 261 then return 'leave'; end return 'sic'; end), 1);
    check('PVL58 ...as a signal on THIS service\'s clock', pv.signals(500).leave, true);
    pv.clearSignals();
    pv.onCommandPacket(actionPkt(0x09, 262));
    check('PVL59 any other ability is not a Leave',
          pv.drainCommands(510, function() return 'reward'; end), 0);
    check('PVL60 ...and notes nothing', pv.signals(510).leave, nil);
    pv.onCommandPacket(actionPkt(0x09, 263));
    check('PVL61 an unresolvable ability name is not a Leave either (fails SAFE)',
          pv.drainCommands(520, function() return nil; end), 0);
    check('PVL62 draining an empty stash is free', pv.drainCommands(530), 0);

    -- --- THE CORPSE: the death witness that actually fires on this server
    --     (2026-07-30 -- CPetEntity::Die pushes no battle message at all, so
    --     the falls line can never come for a jug pet and the low-HP guess
    --     misses every pet killed from above the ceiling).
    check('PVL67 same entity at zero HP is a death', pv.corpseVerdict(4242, { id = 4242, hpp = 0 }), true);
    check('PVL68 ...and a dead STATUS says it too, whatever the HP read did',
          pv.corpseVerdict(4242, { id = 4242, status = 2 }), true);
    check('PVL69 the same entity still standing is NOT a death',
          pv.corpseVerdict(4242, { id = 4242, hpp = 61 }), false);
    check('PVL70 a different id at that index cannot tell (the corpse despawned)',
          pv.corpseVerdict(4242, { id = 99, hpp = 0 }), nil);
    check('PVL71 no read at all cannot tell', pv.corpseVerdict(4242, nil), nil);
    check('PVL72 no remembered id cannot tell', pv.corpseVerdict(nil, { id = 4242, hpp = 0 }), nil);

    local dc = pv.classifyLoss(OUT, GONE, { corpse = true, isJugPet = jugAuth });
    check('PVL73 a healthy-looking pet that left a CORPSE is a confirmed death',
          dc.kind .. '/' .. tostring(dc.confirmed) .. '/' .. tostring(dc.how), 'death/true/corpse');
    check('PVL74 the corpse outranks the falls line as the reported proof',
          pv.classifyLoss(OUT, GONE, { corpse = true, falls = true }).how, 'corpse');
    check('PVL75 a corpse that is ALIVE suppresses -- live memory outranks a guess',
          pv.classifyLoss(HURT, GONE, { corpse = false }).kind, 'unknown');
    check('PVL76 ...and outranks a falls line too',
          pv.classifyLoss(HURT, GONE, { corpse = false, falls = true }).confirmed, false);
    check('PVL77 the low-HP guess still speaks when the corpse could not be read',
          pv.classifyLoss(HURT, GONE, {}).how, 'low-hp');
    check('PVL78 a Leave still suppresses ahead of the corpse',
          pv.classifyLoss(HURT, GONE, { corpse = true, leave = true }).kind, 'leave');

    -- --- PROVENANCE: what we watched you press beats any roster
    check('PVL79 a pet we saw you Call Beast is a jug pet, roster or not',
          pv.classifyLoss({ present = true, hpp = 4, name = 'Custom Whatsit' }, GONE,
                          { origin = 'jug', isJugPet = jugAuth }).pet, 'jug');
    check('PVL80 ...and one we saw you charm is charm, whatever it is called',
          pv.classifyLoss(OUT, GONE, { origin = 'charm', isJugPet = jugAuth }).pet, 'charm');
    check('PVL81 with no origin the name authority still answers',
          pv.classifyLoss(OUT, GONE, { isJugPet = jugAuth }).pet, 'jug');

    -- the summon signal, from the same packet drain the Leave rides
    pv.resetCommands();
    pv.clearSignals();
    pv.onCommandPacket(actionPkt(0x09, 272));
    pv.drainCommands(600, function() return 'call beast'; end);
    check('PVL82 Call Beast is noted as a jug summon', pv.signals(600).summon, 'jug');
    pv.clearSignals();
    pv.onCommandPacket(actionPkt(0x09, 273));
    pv.drainCommands(610, function() return 'charm'; end);
    check('PVL83 ...and Charm as a charm', pv.signals(610).summon, 'charm');
    pv.clearSignals();

    -- --- the whole chain on the BEAT: summon, die, resummon-worthy edge
    pv.reset(true);
    pv.lossCtx.isJugPet = function() return false; end   -- the roster does NOT know it
    local edges2 = {};
    local live = { present = true, hpp = 55, name = 'Custom Whatsit', id = 4242, index = 0x123 };
    local ent  = { id = 4242, hpp = 55, status = 1 };
    local READS2 = {
        pet        = function() return live and { HPP = live.hpp, Name = live.name,
                                                  Id = live.id, Index = live.index } or nil; end,
        entity     = function(idx) if idx == 0x123 then return ent; end return nil; end,
        zoning     = function() return false; end,
        loggingOut = function() return false; end,
    };
    pv.subscribeLoss('t2', function(e) edges2[#edges2 + 1] = e; end);
    pv.onCommandPacket(actionPkt(0x09, 272));
    pv.drainCommands(700, function() return 'call beast'; end);
    pv.pump(700, READS2);
    check('PVL84 the pet is remembered with its identity', pv.lastPresent().id, 4242);
    check('PVL85 ...and with the provenance we watched', pv.origin(), 'jug');
    live = nil; ent = { id = 4242, hpp = 0, status = 2 };     -- it died where it stood
    pv.pump(701, READS2);
    check('PVL86 the corpse confirms the death with no chat line in sight',
          edges2[1].kind .. '/' .. tostring(edges2[1].how), 'death/corpse');
    check('PVL87 ...and it is a JUG pet on provenance alone (the roster said no)',
          edges2[1].pet, 'jug');
    check('PVL88 which is exactly what the Resummon rule needs',
          (edges2[1].confirmed == true and edges2[1].pet == 'jug'), true);

    -- the same vanish with the entity still standing is NOT a death
    pv.reset(false);
    edges2 = {};
    live = { present = true, hpp = 55, name = 'Forest Hare', id = 77, index = 0x200 };
    READS2.entity = function(idx) if idx == 0x200 then return { id = 77, hpp = 55, status = 1 }; end return nil; end
    pv.pump(800, READS2);
    live = nil;
    pv.pump(801, READS2);
    check('PVL89 a pet that stopped being ours while still standing is not a death',
          edges2[1].kind, 'unknown');
    pv.reset(true);

    -- --- the human line the Panel reports
    check('PVL63 the loss text names the death', pv.lossText(d1):find('died', 1, true) ~= nil, true);
    check('PVL64 ...and a charmed one says so',
          pv.lossText(pv.classifyLoss({ present = true, hpp = 4, name = 'Forest Hare' }, GONE,
                                      { isJugPet = jugAuth })):find('charmed', 1, true) ~= nil, true);
    check('PVL65 ...and a Leave reads as a dismissal',
          pv.lossText(pv.classifyLoss(HURT, GONE, { leave = true })):find('dismissed', 1, true) ~= nil, true);
    check('PVL66 nothing lost has nothing to say', pv.lossText(nil), 'no pet loss yet');
end)();

-- ---------------------------------------------------------------------------
-- JUG: the BST Helper's jug DATA (issue #141) -- the pet roster the death
-- classifier judges names against, and the jug -> pet mapping the picker shows.
-- The jug LIST itself is the catalog's, joined here, with the walk injected.
-- ---------------------------------------------------------------------------
;(function()
    local jugs = dofile('jobhelpers/bst/bst-helper/jugs.lua');

    -- --- the roster: the classifier's whole jug-vs-charm rule
    check('JUG1 a jug pet is on the roster', jugs.isJugPet('Hare Familiar'), true);
    check('JUG2 ...an HQ one too', jugs.isJugPet('Keeneared Steffi'), true);
    check('JUG3 a charmed mob keeps its mob name and is NOT one', jugs.isJugPet('Forest Hare'), false);
    check('JUG4 matched case-insensitively', jugs.isJugPet('hare familiar'), true);
    check('JUG5 ...and padding-trimmed (the GetName idiom)', jugs.isJugPet('Hare Familiar  '), true);
    -- THE SPACE (field 2026-07-30, from a chat line: "The SheepFamiliar defeats
    -- the Clipper."): the client's entity name for a jug pet has NO space, every
    -- published table writes one, and compared raw not a single jug pet matched
    -- its own roster row -- so every one of them classified as CHARMED and the
    -- Resummon rule refused, silently and completely.
    check('JUG5a the client\'s SPACELESS pet name matches the spaced roster row',
          jugs.isJugPet('SheepFamiliar'), true);
    check('JUG5b ...in either direction', jugs.isJugPet('Sheep Familiar'), true);
    check('JUG5c ...and an HQ two-word name too', jugs.isJugPet('KeenearedSteffi'), true);
    check('JUG5d ...while a mob is still not a jug pet', jugs.isJugPet('ForestHare'), false);
    check('JUG5e the player\'s own configured pet squashes the same way',
          jugs.isJugPet('WyvernFamiliar', 'Wyvern Familiar'), true);
    check('JUG6 no name to judge answers "cannot tell"', jugs.isJugPet(nil), nil);
    check('JUG7 an empty name too', jugs.isJugPet('   '), nil);
    check('JUG8 the player\'s own configured pet counts even off-roster',
          jugs.isJugPet('Wyvern Familiar', 'Wyvern Familiar'), true);
    check('JUG9 ...and only that one', jugs.isJugPet('Other Familiar', 'Wyvern Familiar'), false);
    check('JUG10 the roster is 14 families of NQ + HQ', #jugs.PETS, 28);

    -- --- the mapping: display only, and honest about what it does not know
    check('JUG11 a mapped jug names its pet', jugs.petFor('Carrot Broth'), 'Hare Familiar');
    check('JUG12 ...and where the row came from', jugs.sourceFor('Carrot Broth'), 'cexi');
    check('JUG13 an unmapped jug names nobody rather than guessing',
          jugs.petFor('Shadowy Broth'), nil);
    check('JUG14 a non-jug maps to nothing', jugs.petFor('Pet Food Alpha'), nil);
    check('JUG15 no mapping row points at a pet the roster does not carry', (function()
        local roster = {};
        for _, n in ipairs(jugs.PETS) do roster[n] = true; end
        for item, row in pairs(jugs.MAP) do
            if roster[row.pet] ~= true then return item .. ' -> ' .. tostring(row.pet); end
        end
        return 'ok';
    end)(), 'ok');
    check('JUG16 ...and no two jugs claim the same pet', (function()
        local seen = {};
        for item, row in pairs(jugs.MAP) do
            if seen[row.pet] ~= nil then return row.pet .. ' claimed twice'; end
            seen[row.pet] = item;
        end
        return 'ok';
    end)(), 'ok');

    -- --- the list: a jug is a BST-ONLY Ammo item, joined with the mapping
    local FIXTURE = {
        [17860] = { Name = 'Carrot Broth', Level = 10, Type = 'Ammo', Jobs = { 'BST' } },
        [17864] = { Name = 'Herbal Broth', Level = 15, Type = 'Ammo', Jobs = { 'BST' } },
        [17905] = { Name = 'Lucky Broth', Level = 75, Type = 'Ammo', Jobs = { 'BST' } },
        [17903] = { Name = 'Shadowy Broth', Level = 96, Type = 'Ammo', Jobs = { 'BST' } },
        [17016] = { Name = 'Pet Food Alpha', Level = 12, Type = 'Ammo',
                    Jobs = { 'WAR', 'BST', 'DRG' } },                       -- not BST-only
        [18761] = { Name = 'Acantha Shavers', Level = 69, Type = 'HandToHand', Jobs = { 'BST' } },
    };
    local READS = { index = function() return FIXTURE; end };
    local list = jugs.list(READS);
    check('JUG17 only BST-only Ammo is a jug', #list, 3);
    check('JUG18 ...ordered lowest level first', list[1].name, 'Carrot Broth');
    check('JUG19 ...then the rest', list[2].name .. '/' .. list[3].name, 'Herbal Broth/Lucky Broth');
    check('JUG20 a row carries its catalog id and level', list[1].id .. '/' .. list[1].level, '17860/10');
    check('JUG21 ...and the pet it calls', list[1].pet, 'Hare Familiar');
    check('JUG22 an unmapped jug rides the list with no pet name', list[3].pet, nil);
    check('JUG23 find() is case-insensitive (a name travels through a config file)',
          (jugs.find('carrot broth', READS) or {}).id, 17860);
    check('JUG24 ...and a non-jug is not found', jugs.find('Pet Food Alpha', READS), nil);
    check('JUG25 an unreadable catalog is an empty list, never a throw',
          #jugs.list({ index = function() error('no catalog'); end }), 0);

    -- --- the CAP: this server stops at 75, the catalog does not (2026-07-30 --
    --     65 of the live catalog's 98 BST-only Ammo rows are Lv76-99, so two
    --     thirds of the picker was jugs nobody here can equip, none of them
    --     even mapped to a pet).
    check('JUG17a a jug above the cap is not in the list at all',
          jugs.find('Shadowy Broth', READS), nil);
    check('JUG17b a jug EXACTLY at the cap is (75 is usable)',
          (jugs.find('Lucky Broth', READS) or {}).level, 75);
    check('JUG17c the cap is one named number, not a literal', jugs.MAX_LEVEL, 75);

    -- a LIVE-observed level override wins over the catalog's inherited base
    jugs.LEVEL['Carrot Broth'] = 8;
    check('JUG26 a live-observed level beats the repo one', jugs.list(READS)[1].level, 8);
    jugs.LEVEL['Carrot Broth'] = nil;
    -- ...and it is what the cap is applied TO, so a jug this server re-tuned
    -- down into reach comes back with ONE row here rather than by moving the cap.
    jugs.LEVEL['Shadowy Broth'] = 70;
    check('JUG17d a live-observed level can bring an above-cap jug back',
          (jugs.find('Shadowy Broth', READS) or {}).level, 70);
    jugs.LEVEL['Shadowy Broth'] = nil;
    check('JUG27 the default LEVEL table ships empty (nothing observed live yet)',
          next(jugs.LEVEL), nil);
end)();

-- ---------------------------------------------------------------------------
-- fakeApi: a stand-in for the MODULE API table (feature\modapi) that the loader
-- hands each Job helper. Since api 2 a module reaches every service, the clock,
-- its settings store and the two act doors through that ONE table -- which makes
-- driving a module headlessly a matter of handing it a fake, instead of stubbing
-- half a dozen package.loaded entries and hoping the module asked for exactly the
-- ones you faked.
--
-- The fake RECORDS what a rule did (`sent` for bare commands, `acts` for sequence
-- requests, `lines` for chat) and lets a test drive what the world says back
-- (`opts.acting`, `opts.pet`, `opts.food`, `opts.stock`, `opts.ready`, `clock`).
-- Every field is the shape modapi documents, so a rule that passes here is calling
-- the real surface correctly.
-- ---------------------------------------------------------------------------
local function fakeApi(opts)
    opts = opts or {};
    local vals = opts.vals or {};
    local S = { api = 2, id = opts.id or 'bst-helper', job = opts.job or 'bst',
                label = 'Fake Helper', jobs = { 'BST' },
                sent = {}, acts = {}, lines = {}, clock = opts.clock or 100, vals = vals };

    S.cfg = {
        get      = function(k) return vals[k]; end,
        set      = function(k, v) vals[k] = v; return true; end,
        forget   = function() end,
        path     = function() return 'FAKEDIR\\jobhelper-fake.lua'; end,
        keys     = function() return {}; end,
        defaults = function() return {}; end,
    };
    S.now     = function() return S.clock; end
    S.sibling = function(n) return (opts.siblings or {})[n]; end
    S.service = function() return nil; end
    S.who     = function(n) return 'jobhelper:' .. S.id .. ':' .. tostring(n); end

    local function line(l) S.lines[#S.lines + 1] = tostring(l); end
    S.say = { good = line, warn = line, err = line };

    S.me = {
        acting  = function() return opts.acting or { active = true, label = 'Active' }; end,
        order   = function() return opts.order or 1; end,
        enabled = function() return opts.enabled ~= false; end,
    };

    S.player = {
        job         = function() return 'BST'; end,
        subJob      = function() return nil; end,
        level       = function() return opts.level or 75; end,
        status      = function() return opts.status; end,
        zoning      = function() return opts.zoning; end,
        loggingOut  = function() return opts.logout; end,
        zone        = function() return opts.zone; end,
    };

    S.subs = {};                       -- what the module subscribed to, by key
    S.combat = {
        subscribe = function(n, cb) S.subs[S.who(n)] = cb; return true; end,
        state     = function() return opts.combat or {}; end,
        onEdge    = function(n, cb) S.subs[S.who(n)] = cb; return true; end,
        lastEdge  = function() return opts.edge; end,
    };

    S.pet = {
        get           = function() return opts.pet or { present = false }; end,
        subscribe     = function(n, cb) S.subs[S.who(n)] = cb; return true; end,
        onLoss        = function(n, cb) S.subs[S.who(n)] = cb; return true; end,
        lastLoss      = function() return nil; end,
        signals       = function() return opts.signals or {}; end,
        nameAuthority = function(fn) S.nameAuthority = fn; return true; end,
        food          = function() return opts.food or { ok = false, reason = 'none-carried' }; end,
        foodRefusal   = function(p)
            if type(p) == 'table' and p.reason == 'level' then
                return 'the pet food you are carrying is above your level.';
            end
            return 'you are not carrying any pet food.';
        end,
    };

    -- Mirrors the real contract, INCLUDING the part that separates "measured
    -- ready" from "could not measure": both answer ready = true, and the
    -- REMAINING beside it is the difference (0 = measured idle, nil = the recast
    -- slot never resolved). Unlisted stays UNKNOWN, which is what an ability
    -- whose slot dlac cannot resolve looks like.
    S.ability = {
        ready = function(sig)
            local nm = sig;
            if type(sig) == 'table' then nm = sig.name or sig.label; end
            local r = (opts.ready or {})[tostring(nm)];
            if r == nil then return true, nil; end                      -- unknown
            if r == false then return false, opts.remaining or 42; end  -- measured down
            return true, 0;                                             -- measured ready
        end,
    };

    S.item = {
        own    = function() return opts.stock or 0; end,
        stored = function() return opts.stock or 0; end,
        worn   = function(slot) return (opts.worn or {})[slot]; end,
        info   = function() return opts.info; end,
    };

    S.sets = {
        names   = function() return opts.setNames or {}; end,
        slotsOf = function(n) return (opts.setSlots or {})[n] or {}; end,
    };

    S.act = {
        request = function(r)
            S.acts[#S.acts + 1] = r;
            if opts.actResult ~= nil then return opts.actResult; end
            return { ok = true };
        end,
        busy   = function() return opts.busy == true; end,
        status = function() return 'idle'; end,
    };
    S.cmd = function(c) S.sent[#S.sent + 1] = c; return true; end

    return S;
end

-- ---------------------------------------------------------------------------
-- MC: feature\modcfg -- the MODULE SETTINGS STORE the framework provides so no
-- module copies the storage policy. The format halves are pure; a store is
-- closures over its own state, so N modules get N independent stores.
-- ---------------------------------------------------------------------------
;(function()
    local mc = dofile('feature/modcfg.lua');
    package.loaded['dlac\\feature\\modcfg'] = mc;

    local SPEC = { file = 'jobhelper-t.lua',
                   keys = { mode = 'string', pct = 'number', on = 'boolean' },
                   defaults = { mode = 'off', pct = 50, on = false } };

    -- --- validation: a declaration that does not say what it stores is refused
    check('MC1 a good spec validates', mc.validate(SPEC), true);
    check('MC2 a non-table is refused', mc.validate('nope'), nil);
    check('MC3 a spec with no keys is refused', mc.validate({}), nil);
    check('MC4 an empty keys table is refused', mc.validate({ keys = {} }), nil);
    check('MC5 an undeclarable type is refused',
          mc.validate({ keys = { x = 'table' } }), nil);
    check('MC6 ...and the reason names the key and the type', (function()
        local _, why = mc.validate({ keys = { x = 'table' } });
        return tostring(why):find('"x"', 1, true) ~= nil and tostring(why):find('table', 1, true) ~= nil;
    end)(), true);
    check('MC7 a default for an undeclared key is refused',
          mc.validate({ keys = { a = 'number' }, defaults = { b = 1 } }), nil);
    check('MC8 a default of the wrong type is refused',
          mc.validate({ keys = { a = 'number' }, defaults = { a = 'one' } }), nil);

    -- --- the filename: yours if you name one, else derived from your identity
    check('MC9 a declared filename wins', mc.fileFor('t-helper', SPEC), 'jobhelper-t.lua');
    check('MC10 ...otherwise it derives from the module id',
          mc.fileFor('t-helper', { keys = { a = 'number' } }), 'jobhelper-t-helper.lua');

    -- --- the format: declared keys of the declared type only, sorted, versioned
    local text = mc.serialize(SPEC, { mode = 'follow', pct = 35, on = true, junk = 1 });
    check('MC11 the file is format-versioned', text:find('fmt = 1', 1, true) ~= nil, true);
    check('MC12 declared values are written', text:find('["mode"] = "follow"', 1, true) ~= nil, true);
    check('MC13 an undeclared key is never written', text:find('junk', 1, true), nil);
    check('MC14 keys are SORTED, so an unchanged config re-serializes identically',
          mc.serialize(SPEC, { pct = 1, mode = 'a', on = true }),
          mc.serialize(SPEC, { on = true, mode = 'a', pct = 1 }));
    local back = mc.normalize(SPEC, (loadstring or load)(text)());
    check('MC15 a written file reads back', back.mode == 'follow' and back.pct, 35);
    check('MC16 a stored FALSE survives normalization (it is not "absent")',
          mc.normalize(SPEC, { on = false }).on, false);
    check('MC17 a wrong-typed value on disk is dropped, not coerced',
          mc.normalize(SPEC, { pct = 'thirty' }).pct, nil);
    check('MC18 a key from a NEWER dlac cannot survive into this one',
          mc.normalize(SPEC, { future = 'x' }).future, nil);
    check('MC19 a torn file (not a table) normalizes to just the version',
          mc.normalize(SPEC, 'garbage').fmt, 1);

    -- --- a live store against an in-memory disk
    local FILES = {};
    local realOpen, realLoadfile = io.open, loadfile;
    io.open = function(path, mode)
        if type(path) == 'string' and path:find('MCDIR', 1, true) then
            if (mode or 'r'):find('w') then
                FILES[path] = '';
                return { write = function(_, s) FILES[path] = (FILES[path] or '') .. s; end,
                         close = function() end };
            end
            return nil;
        end
        return realOpen(path, mode);
    end
    loadfile = function(path)
        if type(path) == 'string' and path:find('MCDIR', 1, true) then
            local s = FILES[path]; if s == nil then return nil; end
            return (loadstring or load)(s);
        end
        return realLoadfile(path);
    end

    local DIR = nil;                                    -- nil == pre-login
    local st = mc.open('t-helper', SPEC, function() return DIR; end);
    check('MC20 pre-login a read is the declared default', st.get('mode'), 'off');
    check('MC21 pre-login a write is refused, never cached', st.set('mode', 'follow'), false);
    check('MC22 ...and the read still answers the default', st.get('mode'), 'off');
    check('MC23 pre-login there is no path to write to', st.path(), nil);

    DIR = 'MCDIR\\';
    check('MC24 an absent file still reads the defaults', st.get('pct'), 50);
    check('MC25 nothing is written until something changes', FILES['MCDIR\\jobhelper-t.lua'], nil);
    check('MC26 a write takes effect', st.set('pct', 35) and st.get('pct'), 35);
    check('MC27 ...and lands in the module\'s OWN file', FILES['MCDIR\\jobhelper-t.lua'] ~= nil, true);
    local wrote = FILES['MCDIR\\jobhelper-t.lua'];
    check('MC28 an UNCHANGED write does not touch the disk', (function()
        st.set('pct', 35);
        return FILES['MCDIR\\jobhelper-t.lua'] == wrote;
    end)(), true);
    check('MC29 an undeclared key cannot be stored', st.set('nope', 1), false);
    check('MC30 a wrong-typed value cannot be stored', st.set('pct', 'many'), false);
    check('MC31 a stored value survives a forget + re-read off the file', (function()
        st.forget();
        return st.get('pct');
    end)(), 35);
    check('MC32 the store reports the file it writes', st.path(), 'MCDIR\\jobhelper-t.lua');

    -- two modules, two stores, no shared cache
    local st2 = mc.open('other-helper', { keys = { pct = 'number' }, defaults = { pct = 7 } },
                        function() return DIR; end);
    check('MC33 a second module gets an INDEPENDENT store', st2.get('pct'), 7);
    check('MC34 ...writing its own file', mc.fileFor('other-helper', {}), 'jobhelper-other-helper.lua');
    st2.set('pct', 9);
    check('MC35 ...and the first store is untouched', st.get('pct'), 35);

    io.open, loadfile = realOpen, realLoadfile;
    package.loaded['dlac\\feature\\modcfg'] = nil;
end)();

-- ---------------------------------------------------------------------------
-- MA: feature\modapi -- THE MODULE API. One table per module, closed over its
-- identity: namespaced subscription keys, recorded subscriptions, the act door
-- with module+order filled in, and answers in the author's vocabulary (a name,
-- not an item id; the gear level, not raw MainJobLevel).
-- ---------------------------------------------------------------------------
;(function()
    local ma = dofile('feature/modapi.lua');
    package.loaded['dlac\\feature\\modapi'] = ma;

    check('MA1 the API version is 2', ma.API, 2);

    local S = ma.build({ id = 'x-helper', job = 'whm', label = 'X', jobs = { 'WHM' } });
    check('MA2 identity comes from the loader, not the module', S.id, 'x-helper');
    check('MA3 ...including the job folder it filed under', S.job, 'whm');
    check('MA4 the API version rides along', S.api, 2);

    -- --- subscription keys are namespaced BY THE FRAMEWORK
    check('MA5 a rule name becomes a namespaced key', S.who('beat'), 'jobhelper:x-helper:beat');
    check('MA6 ...and a nameless subscription still gets one', S.who(nil), 'jobhelper:x-helper:main');
    local S2 = ma.build({ id = 'y-helper', job = 'whm' });
    check('MA7 two modules cannot collide on the same rule name',
          S.who('beat') ~= S2.who('beat'), true);

    -- --- subscriptions are RECORDED, which is what makes teardown possible
    local subbed, dropped = {}, {};
    package.loaded['dlac\\feature\\combat'] = {
        subscribe   = function(k) subbed[#subbed + 1] = k; return true; end,
        unsubscribe = function(k) dropped[#dropped + 1] = k; return true; end,
        get         = function() return { engaged = true }; end,
    };
    package.loaded['dlac\\feature\\petvitals'] = {
        subscribe     = function(k) subbed[#subbed + 1] = k; return true; end,
        unsubscribe   = function(k) dropped[#dropped + 1] = k; return true; end,
        subscribeLoss = function(k) subbed[#subbed + 1] = k; return true; end,
        unsubscribeLoss = function(k) dropped[#dropped + 1] = k; return true; end,
        get           = function() return { present = true, hpp = 40 }; end,
        lossCtx       = {},
    };
    check('MA8 a combat subscription goes through the namespaced key',
          S.combat.subscribe('beat', function() end) and subbed[1], 'jobhelper:x-helper:beat');
    S.pet.subscribe('vitals', function() end);
    S.pet.onLoss('loss', function() end);
    check('MA9 three subscriptions are recorded against the module', ma.subscriptionCount('x-helper'), 3);
    check('MA10 dropAll undoes every one of them', ma.dropAll('x-helper'), 3);
    check('MA11 ...through the matching unsubscribe door', #dropped, 3);
    check('MA12 ...and the record is cleared', ma.subscriptionCount('x-helper'), 0);
    check('MA13 dropAll on an unknown module is a harmless 0', ma.dropAll('nobody'), 0);

    -- --- the pet name authority is INJECTED, never pushed into the service
    S.pet.nameAuthority(function(n) return n == 'Hare Familiar'; end);
    check('MA14 the module hands the service its name list',
          package.loaded['dlac\\feature\\petvitals'].lossCtx.isJugPet('Hare Familiar'), true);

    -- --- the act door fills in what a module must not choose for itself
    local got = nil;
    package.loaded['dlac\\feature\\actionseq'] = {
        request = function(r) got = r; return { ok = true }; end,
        active  = function() return false; end,
    };
    package.loaded['dlac\\feature\\jobhelpers'] = {
        activity     = function() return { active = true, label = 'Active' }; end,
        sectionOrder = function() return 4; end,
        isEnabled    = function() return true; end,
    };
    S.act.request({ label = 'Thing', claim = { Ammo = 'X' }, command = '/ja "X" <me>' });
    check('MA15 the act door stamps the module id, which cannot be spoofed', got.module, 'x-helper');
    check('MA16 ...and the section order, which the module must not invent', got.order, 4);
    check('MA17 the module\'s own fields ride through untouched', got.command, '/ja "X" <me>');
    check('MA18 busy is answered by the sequencer, not guessed', S.act.busy(), false);

    -- --- unknown reads READY, and the reader is wired FOR you (the api-1 footgun)
    package.loaded['dlac\\feature\\recast'] = {
        readyFor      = function(sig, reader) return reader(sig) <= 0, reader(sig); end,
        liveRemaining = function(sig) if sig.name == 'Down' then return 12; end return 0; end,
    };
    local up, rem = S.ability.ready('Up');
    check('MA19 an ability off cooldown reads ready', up, true);
    check('MA20 a measured cooldown reads down, with the seconds left',
          select(1, S.ability.ready('Down')) == false and select(2, S.ability.ready('Down')), 12);
    check('MA21 a name is enough -- the live reader is wired for you', rem, 0);
    package.loaded['dlac\\feature\\recast'] = nil;
    check('MA22 an UNREACHABLE recast service still reads READY (the courtesy gate)',
          S.ability.ready('Whatever'), true);

    -- --- sets: the DYNAMIC library is what a module is offered, the engine's
    --     flatten is what it claims, and the wrapper-shape tolerance lives in
    --     the API rather than in the module (2026-07-30: this answered the
    --     STATICS -- the pre-profiles import sources -- and a migrated
    --     character's Reward picker listed sets they no longer edit).
    package.loaded['dlac\\gear\\profilesets'] = {
        dynamicSetNames = function() return { 'Melee', 'Reward' }; end,
        staticSetNames  = function() return { 'OldIdle' }; end,
        getSetsRoot     = function()
            return {
                Dynamic = {
                    Reward = { Head = 'Plain String', Body = { Name = 'Wrapped Name' },
                               Hands = { name = 'lower name' }, Legs = { item = 'item key' },
                               Feet = 12345,
                               Neck = { { Name = 'Ladder Head' }, { Name = 'Lower Rung' } } },
                },
                OldIdle = { Head = 'Static Head' },
            };
        end,
    };
    local savedNative = dispatchM._nativeSets;
    dispatchM._nativeSets = nil;                 -- nothing flattened: the degraded walk
    local slots = S.sets.slotsOf('Reward');
    check('MA23 a plain string set entry resolves', slots.Head, 'Plain String');
    check('MA24 ...and each wrapper shape the sets format allows', (function()
        return slots.Body == 'Wrapped Name' and slots.Hands == 'lower name'
           and slots.Legs == 'item key';
    end)(), true);
    check('MA25 a shape that names no item is skipped, not guessed at', slots.Feet, nil);
    check('MA26 "None" is an empty claim, not a set named None', next(S.sets.slotsOf('None')), nil);
    check('MA27 an unknown set is empty rather than an error', next(S.sets.slotsOf('Nope')), nil);
    check('MA28 the DYNAMIC names are the library, never the statics',
          table.concat(S.sets.names(), ','), 'Melee,Reward');
    check('MA28b an authored LADDER claims its head rung', slots.Neck, 'Ladder Head');
    check('MA28c a set that is only a static still resolves (a saved pick never breaks)',
          S.sets.slotsOf('OldIdle').Head, 'Static Head');
    -- The engine's flatten is the level/mode-aware answer, so it WINS: a helper
    -- claims the piece the engine would have equipped, not a second reading.
    dispatchM._nativeSets = { Reward = { Head = 'Flattened Head' } };
    check('MA28d the engine flatten outranks the authored ladder',
          S.sets.slotsOf('Reward').Head, 'Flattened Head');
    dispatchM._nativeSets = savedNative;

    -- --- items are asked for BY NAME; the id-keyed map is the API's problem
    package.loaded['dlac\\gear\\catalogindex'] = {
        flat = function()
            local rec = { Id = 4096, Name = 'Carrot Broth', Level = 23 };
            return { rec }, { [4096] = rec }, { ['carrot broth'] = rec };
        end,
    };
    package.loaded['dlac\\gear\\ownedcache'] = {
        counts = function() return { [4096] = 3 }; end,
        totals = function() return { [4096] = 8 }; end,
    };
    check('MA29 an item is asked for by NAME', S.item.own('Carrot Broth'), 3);
    check('MA30 ...case-insensitively', S.item.own('carrot BROTH'), 3);
    check('MA31 ...or by id, if that is what you have', S.item.own(4096), 3);
    check('MA32 an item nobody has heard of is 0, never nil', S.item.own('Nonesuch'), 0);
    check('MA33 owned-anywhere is a separate question from can-I-equip-it',
          S.item.stored('Carrot Broth'), 8);
    check('MA34 the record itself is available for a label', S.item.info('Carrot Broth').Level, 23);

    -- --- the level: the override wins, then the SYNC-aware level. There is no way
    -- to reach raw MainJobLevel from here, which is the point (a picker that read
    -- it chose a tier above the sync cap and cost a live field round).
    local savedG = rawget(_G, 'gData');
    _G.gData = { GetPlayer = function()
        return { MainJob = 'WHM', MainJobSync = 61, MainJobLevel = 75, Status = 'Engaged' };
    end };
    check('MA35 the level is the SYNC-aware one, never raw MainJobLevel', S.player.level(), 61);
    _G.staticMainLevel = 30;
    check('MA36 ...and the /dl set level override outranks even that', S.player.level(), 30);
    _G.staticMainLevel = nil;
    check('MA37 the job comes through', S.player.job(), 'WHM');
    check('MA38 ...and the status string', S.player.status(), 'Engaged');
    _G.gData = { GetPlayer = function() return { MainJob = '?', MainJobSync = 0 }; end };
    check('MA39 an unsettled job is nil, not the literal "?"', S.player.job(), nil);
    check('MA40 ...and an unreadable level is nil, never 0', S.player.level(), nil);
    _G.gData = savedG;

    -- --- the activity gate and the escape hatch
    package.loaded['dlac\\feature\\jobhelpers'] = {
        activity     = function(id) return { active = false, reason = 'town', label = 'In town', id = id }; end,
        sectionOrder = function() return 1; end,
        isEnabled    = function() return false; end,
    };
    check('MA41 the activity gate answers for THIS module', S.me.acting().reason, 'town');
    check('MA42 ...asked under the module\'s own id', S.me.acting().id, 'x-helper');
    check('MA43 the row pill is readable too', S.me.enabled(), false);
    check('MA44 the escape hatch reaches an unlisted module',
          type(S.service('dlac\\feature\\jobhelpers')), 'table');
    check('MA45 ...and answers nil for one that is not there', S.service('dlac\\nope'), nil);

    -- --- a missing service degrades ONE answer, it never throws into a module
    package.loaded['dlac\\feature\\jobhelpers'] = nil;
    check('MA46 an unreachable activity service still answers a table',
          type(S.me.acting()), 'table');
    check('MA47 ...defaulting to NOT acting, which is the safe direction',
          S.me.acting().active, false);
    check('MA48 an unreachable section order answers 1', S.me.order(), 1);

    for _, k in ipairs({ 'dlac\\feature\\combat', 'dlac\\feature\\petvitals',
                         'dlac\\feature\\actionseq', 'dlac\\feature\\jobhelpers',
                         'dlac\\gear\\profilesets', 'dlac\\gear\\catalogindex',
                         'dlac\\gear\\ownedcache', 'dlac\\feature\\modapi' }) do
        package.loaded[k] = nil;
    end
end)();

-- ---------------------------------------------------------------------------
-- CBT: feature\combat -- the COMBAT STATE service. One record per beat, and
-- `targetChanged` answered by the retarget EDGE when one arrived (which a poll
-- cannot see inside a beat, and cannot tell from a recycled entity index).
-- ---------------------------------------------------------------------------
;(function()
    local cb = dofile('feature/combat.lua');

    local function reads(t)
        t = t or {};
        return { engaged = t.engaged, target = t.target, swung = t.swung,
                 nameOf = function() return t.name or 'Nursery Nazuna'; end };
    end

    -- --- the pure core
    local r = cb.fromReads(reads({ engaged = true, target = 0x2E1, swung = true }));
    check('CBT1 the record carries the engagement', r.engaged, true);
    check('CBT2 ...the target index', r.targetIndex, 0x2E1);
    check('CBT3 ...its name, resolved once for the whole beat', r.targetName, 'Nursery Nazuna');
    check('CBT4 ...and the first-swing answer', r.swung, true);

    -- UNREADABLE STAYS UNREADABLE: each consumer decides which way its own nil
    -- goes, so the service must not flatten one to false on their behalf.
    local u = cb.fromReads(reads({ target = 0x2E1 }));
    check('CBT5 an unreadable engagement stays nil, never false', u.engaged, nil);
    check('CBT6 ...and so does an unreadable swing', u.swung, nil);
    check('CBT7 a target of 0 is no target at all', cb.fromReads(reads({ target = 0 })).targetIndex, nil);

    -- --- targetChanged: EDGE first, poll second, and it says which
    local e = cb.fromReads(reads({ engaged = true, target = 0x2E2 }), 0x2E1,
                           { { kind = 'retarget', index = 0x2E2 } });
    check('CBT8 a retarget edge answers targetChanged', e.targetChanged, true);
    check('CBT9 ...and says the EDGE answered it', e.changedBy, 'edge');
    local p = cb.fromReads(reads({ engaged = true, target = 0x2E2 }), 0x2E1, nil);
    check('CBT10 with no edge, the poll still catches a changed target', p.targetChanged, true);
    check('CBT11 ...and says so, so a consumer can tell the two apart', p.changedBy, 'poll');
    local same = cb.fromReads(reads({ engaged = true, target = 0x2E1 }), 0x2E1, nil);
    check('CBT12 the same target is not a change', same.targetChanged, false);
    -- The edge wins even when the poll cannot see it -- an A->B->A switch inside one
    -- beat leaves the polled index equal to the previous one, and it IS a change.
    local flip = cb.fromReads(reads({ engaged = true, target = 0x2E1 }), 0x2E1,
                              { { kind = 'retarget' } });
    check('CBT13 an A->B->A switch inside one beat is still a change (the edge saw it)',
          flip.targetChanged, true);
    check('CBT14 an ENGAGE edge is not a target change', cb.fromReads(
          reads({ engaged = true, target = 0x2E1 }), 0x2E1, { { kind = 'engage' } }).targetChanged, false);
    check('CBT15 the first beat of a fight is not a change',
          cb.fromReads(reads({ engaged = true, target = 0x2E1 }), nil, nil).targetChanged, false);

    -- --- get() reads NOW and has no opinion about change
    check('CBT16 get() answers without a beat', type(cb.get(reads({ engaged = true }))), 'table');
    check('CBT17 ...and never claims a change, which has no meaning outside a beat',
          cb.get(reads({ engaged = true, target = 5 })).targetChanged, false);

    -- --- the beat: nobody listening means nothing is read at all
    cb.reset(true);
    check('CBT18 with no subscribers the pump does not even read the world',
          cb.pump(100, reads({ engaged = true, target = 1 })), nil);

    local beats = {};
    cb.subscribe('t', function(s) beats[#beats + 1] = s; end);
    check('CBT19 one subscriber is one subscriber', cb.subscriberCount(), 1);
    cb.pump(100, reads({ engaged = true, target = 0x2E1 }));
    check('CBT20 the first beat publishes', #beats, 1);
    check('CBT21 ...stamped with the beat clock', beats[1].at, 100);
    cb.pump(100 + cb.TICK_S / 2, reads({ engaged = true, target = 0x2E1 }));
    check('CBT22 a beat inside the throttle window is skipped', #beats, 1);
    -- Past the window by a clear margin, not by exactly TICK_S: `x + 0.4 - x` is not
    -- reliably >= 0.4 in doubles, and a test that rides that boundary is testing the
    -- float unit rather than the throttle.
    cb.pump(101, reads({ engaged = true, target = 0x2E2 }));
    check('CBT23 a beat past it publishes', #beats, 2);
    check('CBT24 ...and the poll noticed the target moved', beats[2].targetChanged, true);
    -- disengaging drops the history, so the next fight's first mob is not "a change"
    cb.pump(200, reads({ engaged = false }));
    cb.pump(300, reads({ engaged = true, target = 0x2E9 }));
    check('CBT25 the first target of the NEXT fight is not a change',
          beats[#beats].targetChanged, false);
    check('CBT26 last() answers the published record', cb.last().targetIndex, 0x2E9);
    check('CBT27 a clock that went BACKWARDS publishes rather than muting a window',
          (function() local n = #beats; cb.pump(1, reads({ engaged = true, target = 7 })); return #beats > n; end)(), true);

    -- --- the edge inbox is bounded and drains per beat
    cb.reset(false);
    for _ = 1, cb.INBOX_MAX + 4 do cb.noteEdge({ kind = 'retarget' }); end
    check('CBT28 the edge inbox is bounded (a stalled pump cannot grow it)',
          cb.pump(400, reads({ engaged = true, target = 3 })).targetChanged, true);
    check('CBT29 ...and it drained, so the NEXT beat is not still "changed"',
          cb.pump(401, reads({ engaged = true, target = 3 })).targetChanged, false);
    check('CBT30 raw edge subscribers get the edge as it happens', (function()
        local seen = nil;
        cb.onEdge('t2', function(x) seen = x.kind; end);
        cb.noteEdge({ kind = 'engage' });
        return seen;
    end)(), 'engage');
    cb.reset(true);
    check('CBT31 reset(true) drops the subscribers too', cb.subscriberCount(), 0);

    -- THE LIVE SHAPE. Every check above feeds VALUES, and the live table
    -- (M.reads) is FUNCTIONS -- so the whole service could answer a function
    -- reference for `engaged` and stay green, which is exactly what it did
    -- (2026-07-30: every helper on the beat read "not engaged" forever, because
    -- a function is never == true). The reads are driven here the way the
    -- addon drives them: through get() and pump(), off M.reads itself.
    local live = { engaged = function() return true; end,
                   target  = function() return 0x2E1; end,
                   swung   = function() return true; end,
                   nameOf  = function() return 'Nursery Nazuna'; end };
    local fn = cb.fromReads(live);
    check('CBT32 a read that is a FUNCTION is called, not stored', fn.engaged, true);
    check('CBT33 ...the target too, so the beat has a target at all', fn.targetIndex, 0x2E1);
    check('CBT34 ...and the swing', fn.swung, true);
    check('CBT35 ...and the name still resolves off the called target', fn.targetName, 'Nursery Nazuna');

    cb.reads = live;
    check('CBT36 get() reads the LIVE table the addon actually passes', cb.get().engaged, true);
    check('CBT37 ...and a gate can trust it (engaged ~= true must be FALSE here)',
          cb.get().engaged ~= true, false);
    cb.subscribe('live', function() end);
    check('CBT38 the published beat carries values, never the readers',
          cb.pump(900).targetIndex, 0x2E1);
    check('CBT39 a read that THROWS is unreadable (nil), not a crash',
          cb.fromReads({ engaged = function() error('no core'); end }).engaged, nil);
    cb.reset(true);
end)();

-- ---------------------------------------------------------------------------
-- PK: ui\panelkit -- the Panel widget kit. The DRAWING is proven in smoke_ui
-- against a stub binding; what is checked here is the logic a Panel would
-- otherwise re-implement: the choice group's picking, the status precedence, and
-- degrading safely on a binding that lacks a widget.
-- ---------------------------------------------------------------------------
;(function()
    local pk = dofile('ui/panelkit.lua');

    -- A tiny stub binding: it records what was drawn and can click one id.
    local function stub(clickId)
        local out = { text = {}, buttons = {} };
        out.im = {
            TextColored = function(_, s) out.text[#out.text + 1] = tostring(s); end,
            Button      = function(l)
                out.buttons[#out.buttons + 1] = tostring(l);
                return clickId ~= nil and tostring(l):find(clickId, 1, true) ~= nil;
            end,
            SameLine = function() end, Spacing = function() end, Separator = function() end,
            IsItemHovered = function() return false; end, SetTooltip = function() end,
            CalcTextSize = function(s) return #tostring(s) * 8; end,
            PushStyleColor = function() out.pushed = (out.pushed or 0) + 1; end,
            PopStyleColor  = function(n) out.pushed = (out.pushed or 0) - (n or 1); end,
        };
        return out;
    end

    local OPTS = { values = { 'off', 'attack', 'follow' },
                   labels = { off = 'Off', attack = 'When I attack', follow = 'Follow my target' } };

    local s = stub(nil);
    check('PK1 a choice draws one button per way', (function()
        pk.choice(s.im, 'g', OPTS, 'off');
        return #s.buttons;
    end)(), 3);
    check('PK2 ...ids are <group>_<value>, one scheme for every module',
          s.buttons[1], 'Off##g_off');
    check('PK3 ...and nothing is picked when nothing was clicked',
          pk.choice(stub(nil).im, 'g', OPTS, 'off'), nil);
    check('PK4 clicking a way returns THAT value',
          pk.choice(stub('g_follow').im, 'g', OPTS, 'off'), 'follow');
    check('PK5 the lit way pushes exactly one colour and pops it on every path', (function()
        -- The colour ids are ImGui globals, absent headlessly -- seed one so the push
        -- path actually runs, which is the path that could leak the style stack.
        local savedCol = rawget(_G, 'ImGuiCol_Button');
        _G.ImGuiCol_Button = 21;
        local s2 = stub('g_attack');            -- the LIT one is also the clicked one
        pk.choice(s2.im, 'g', OPTS, 'attack');
        _G.ImGuiCol_Button = savedCol;
        return s2.pushed;
    end)(), 0);
    check('PK6 an empty choice draws nothing rather than erroring',
          pk.choice(stub(nil).im, 'g', { values = {} }, 'x'), nil);
    check('PK7 widths are MEASURED off the widest label, never hardcoded',
          pk.widthFor(s.im, { 'x', 'a much longer label' }) > pk.widthFor(s.im, { 'x' }), true);
    check('PK8 ...with a floor, so a tiny label still gets a usable button',
          pk.widthFor(s.im, { 'x' }) >= pk.CHOICE_MIN, true);

    -- the status precedence: off (dim) -> your own blocker (warn) -> the activity
    -- gate (warn) -> armed (ok), then the dim "last" line underneath.
    local function statusOf(spec)
        local s3 = stub(nil);
        pk.ruleStatus(s3.im, spec);
        return s3.text;
    end
    check('PK9 an unarmed rule reports itself off', statusOf({ armed = false,
          offText = 'it is off' })[1], 'it is off');
    check('PK10 an armed rule reports armed', statusOf({ armed = true,
          activity = { active = true }, armedText = 'armed!' })[1], 'armed!');
    check('PK11 the activity gate outranks "armed"', statusOf({ armed = true,
          activity = { active = false, label = 'In town' }, armedText = 'armed!' })[1],
          'Not acting: In town.');
    check('PK12 the module\'s OWN blocker outranks the activity gate', statusOf({ armed = true,
          blocked = 'No jug picked.', activity = { active = false, label = 'In town' } })[1],
          'No jug picked.');
    check('PK13 being off outranks everything -- the player turned it off',
          statusOf({ armed = false, blocked = 'No jug picked.', offText = 'off' })[1], 'off');
    check('PK14 the last line rides underneath, labelled', statusOf({ armed = true,
          activity = { active = true }, last = 'no pet out', lastLabel = 'Last beat' })[2],
          'Last beat: no pet out.');
    check('PK15 ...and is absent when the rule has decided nothing yet',
          #statusOf({ armed = true, activity = { active = true } }), 1);

    -- degrading: a binding that carries none of the widgets must not error
    check('PK16 every control degrades safely on an empty binding', (function()
        local bare = {};
        local ok = pcall(function()
            pk.header(bare, 'h', 't');   pk.toggle(bare, 'i', 'l', true, 't');
            pk.choice(bare, 'i', OPTS, 'off'); pk.slider(bare, 'i', 5, 1, 9, '%d', 't');
            pk.combo(bare, 'i', 'c', { 'a' }, tostring, 't', 'None');
            pk.ruleStatus(bare, { armed = true }); pk.button(bare, 'i', 'l', 't');
            pk.pill(bare, true, 'i', 'a', 'b'); pk.disabled(bare, 'x'); pk.sameLine(bare, 4);
        end);
        return ok;
    end)(), true);
    check('PK17 a button on a binding without Button reports "not clicked", not nil',
          pk.button({}, 'i', 'l', 't'), false);

    -- THE PERCENT TRAP. Every imgui text call is a printf format string, so an
    -- unescaped '%' is a CONVERSION: `below 51% pet HP` reached the field as
    -- `below 51F4A60263et HP` (2026-07-29) -- '% p' read as %p, a heap address
    -- printed, the 'p' eaten. A rule that states a threshold is the COMMON case
    -- here, so the kit escapes and this is what holds it escaped.
    check('PK21 a percent in status text is escaped, not read as a conversion',
          statusOf({ armed = true, activity = { active = true },
                     armedText = 'Armed: below 51% pet HP.' })[1],
          'Armed: below 51%% pet HP.');
    check('PK22 ...and in the last line underneath', statusOf({ armed = true,
          activity = { active = true }, last = 'fed at 40% HP' })[2],
          'Last: fed at 40%% HP.');
    check('PK23 ...and in disabled text, which has its own imgui call', (function()
        local got = nil;
        pk.disabled({ TextDisabled = function(x) got = x; end }, 'Reward now  (100% down)');
        return got;
    end)(), 'Reward now  (100%% down)');
    check('PK24 ...and in a tooltip, which is a format string too', (function()
        local got = nil;
        pk.button({ Button = function() return false; end,
                    IsItemHovered = function() return true; end,
                    SetTooltip = function(x) got = x; end }, 'i', 'l', 'below 50% HP');
        return got;
    end)(), 'below 50%% HP');

    -- --- the dropdown SEARCH rule (2026-07-30 -- "can be many sets and jugs, so
    --     might be good to find em"). Pure, so the whole rule is checked here and
    --     the smoke suite only has to prove the box is drawn and wired.
    check('PK25 an empty filter matches everything', pk.matchesFilter('Carrot Broth', ''), true);
    check('PK26 ...and so does a filter of pure whitespace', pk.matchesFilter('Carrot Broth', '   '), true);
    check('PK27 ...and a nil one (a binding with no InputText)', pk.matchesFilter('x', nil), true);
    check('PK28 a substring matches, case-insensitively', pk.matchesFilter('Carrot Broth', 'CARR'), true);
    check('PK29 ...and a miss is a miss', pk.matchesFilter('Carrot Broth', 'humus'), false);
    -- the compound case this exists for: the jug row carries the broth AND the
    -- familiar, and they are nowhere near each other in the string.
    local JUGROW = 'Carrot Broth (Lv 10) -- Hare Familiar';
    check('PK30 a jug is findable by the FAMILIAR it calls', pk.matchesFilter(JUGROW, 'hare'), true);
    check('PK31 several words must ALL match, in any order',
          pk.matchesFilter(JUGROW, 'hare carrot'), true);
    check('PK32 ...so one wrong word rejects the row',
          pk.matchesFilter(JUGROW, 'hare humus'), false);
    check('PK33 punctuation in the filter is LITERAL, never a pattern',
          pk.matchesFilter(JUGROW, '--') and pk.matchesFilter(JUGROW, '(lv 10)'), true);
    check('PK34 ...and a pattern quantifier cannot match what is not there',
          pk.matchesFilter('Carrot Broth', 'c+'), false);

    -- bind(): the kit with the handle applied, which is what a Panel actually gets
    local b = pk.bind(s.im);
    check('PK18 bind() carries every widget over', type(b.choice) == 'function'
          and type(b.ruleStatus) == 'function' and type(b.header), 'function');
    check('PK19 ...and the palette', b.COL.ok, pk.COL.ok);
    check('PK19b ...and esc survives binding UNBOUND -- it takes no handle, and a\n'
          .. '      handle-first wrapper would escape a table address instead',
          b.esc('50% done'), '50%% done');
    check('PK20 a bound call needs no handle',
          b.choice('g', OPTS, 'off') == nil and #s.buttons > 0, true);
end)();

-- ---------------------------------------------------------------------------
-- TPL: docs\templates\example-helper -- the copyable template. It is shipped as
-- the thing an author starts from, so it is held to the same bar as a real
-- module: it must satisfy the contract and its rule must obey the laws the guide
-- states. A broken template is worse than no template.
-- ---------------------------------------------------------------------------
;(function()
    local jh = dofile('feature/jobhelpers.lua');
    local mc = dofile('feature/modcfg.lua');
    package.loaded['dlac\\feature\\modcfg'] = mc;

    local tpl = dofile('docs/templates/example-helper/init.lua');
    local rule = dofile('docs/templates/example-helper/rule.lua');

    -- --- the contract, through the REAL validator
    local rec, why = jh._validate('example-helper', tpl);
    check('TPL1 the template satisfies the module contract', rec ~= nil, true);
    if rec == nil then print('   template refused: ' .. tostring(why)); end
    check('TPL2 it declares the CURRENT api', tpl.api, jh.API);
    check('TPL3 it declares a label', type(tpl.label), 'string');
    check('TPL4 it declares its jobs', #tpl.jobs > 0, true);
    check('TPL5 its config declaration is valid', mc.validate(tpl.config), true);
    check('TPL6 ...and the acting behaviour defaults OFF', tpl.config.defaults.armed, false);

    -- --- the rule's PURE laws
    local function armed(t)
        local st = { armed = true, active = true, busy = false, ready = true,
                     firedThisFight = false, now = 1000, lockout = 60 };
        for k, v in pairs(t or {}) do st[k] = v; end
        return st;
    end
    local ENGAGED = { engaged = true, targetIndex = 5 };

    check('TPL7 armed + acting + engaged acts', rule.decide(ENGAGED, armed()).act, true);
    check('TPL8 an unarmed rule never acts', rule.decide(ENGAGED, armed({ armed = false })).reason, 'off');
    check('TPL9 the activity gate holds it, carrying the reason',
          rule.decide(ENGAGED, armed({ active = false, reason = 'town' })).reason, 'town');
    check('TPL10 an UNREADABLE world is not permission (positive-true)',
          rule.decide(ENGAGED, { armed = true, now = 1000 }).act, false);
    check('TPL11 not engaged holds', rule.decide({}, armed()).reason, 'not-engaged');
    check('TPL12 an unreadable engagement is not permission either',
          rule.decide({ targetIndex = 5 }, armed()).reason, 'not-engaged');
    check('TPL13 once per fight', rule.decide(ENGAGED, armed({ firedThisFight = true })).reason, 'done');
    check('TPL14 the lockout holds a second attempt',
          rule.decide(ENGAGED, armed({ lastAttemptAt = 990 })).reason, 'lockout');
    check('TPL15 ...and reports how long is left',
          rule.decide(ENGAGED, armed({ lastAttemptAt = 990 })).retryIn, 50);
    check('TPL16 a whole window later it acts again',
          rule.decide(ENGAGED, armed({ lastAttemptAt = 940 })).act, true);
    check('TPL17 a clock that went BACKWARDS accepts rather than muting a window',
          rule.decide(ENGAGED, armed({ lastAttemptAt = 5000 })).act, true);
    check('TPL18 busy is a HOLD, not a failure', rule.decide(ENGAGED, armed({ busy = true })).reason, 'busy');
    check('TPL19 a measured cooldown holds', rule.decide(ENGAGED, armed({ ready = false })).reason, 'cooldown');
    check('TPL20 an UNKNOWN cooldown reads ready (the courtesy gate)',
          rule.decide(ENGAGED, armed({ ready = nil })).act, true);
    check('TPL21 every reason reads as a human sentence, never a slug', (function()
        for _, r in ipairs({ 'off', 'inactive', 'town', 'not-engaged', 'done', 'busy', 'cooldown' }) do
            local s = rule.decisionText({ act = false, reason = r });
            if type(s) ~= 'string' or s == r then return r; end
        end
        return true;
    end)(), true);

    -- --- the glue, against the fake module API
    -- `siblings` is what S.sibling('rule') resolves against -- the template loads its
    -- own files by BARE NAME through the API, never by a hardcoded path, which is
    -- exactly why renaming a copied folder is safe.
    local S = fakeApi({ id = 'example-helper', job = 'whm', siblings = { rule = rule },
                        vals = { armed = true, lockout = 60 }, clock = 100 });
    check('TPL22 the template arms through its init hook', (function()
        local ok = pcall(tpl.init, S);
        return ok and S.subs['jobhelper:example-helper:beat'] ~= nil;
    end)(), true);

    rule.init(S);
    rule.reset();
    rule.onBeat({ engaged = true, targetIndex = 5, at = 100 });
    check('TPL23 one beat while engaged issues ONE command', #S.sent, 1);
    check('TPL24 ...through the central command door', S.sent[1], rule.COMMAND);
    for i = 1, 10 do rule.onBeat({ engaged = true, targetIndex = 5, at = 100 + i }); end
    check('TPL25 ten more beats add nothing (once per fight)', #S.sent, 1);
    check('TPL26 ...and the Panel line says why', rule.lastLine(), 'already used this fight');
    rule.onBeat({ engaged = false, at = 200 });
    check('TPL27 disengaging clears the once-per-fight latch, without a second signal',
          rule.lastLine(), 'you are not engaged');
    S.clock = 100 + rule.LOCKOUT_S + 1;
    rule.onBeat({ engaged = true, targetIndex = 6, at = S.clock });
    check('TPL28 the next fight, past the lockout, acts again', #S.sent, 2);

    -- the module's own settings round-trip through the framework store
    check('TPL29 the rule reads its switch through the API store', rule.armed(), true);
    rule.setArmed(false);
    check('TPL30 ...and writes it back', rule.armed(), false);
    rule.onBeat({ engaged = true, targetIndex = 7, at = 9999 });
    check('TPL31 a disarmed template never acts', #S.sent, 2);

    package.loaded['dlac\\feature\\modcfg'] = nil;
    package.loaded['dlac\\feature\\jobhelpers'] = nil;
end)();

-- ---------------------------------------------------------------------------
-- BRS: the BST Helper's RESUMMON rule (issue #141), driven at its DECISION
-- SEAM -- a classified loss edge + state in, "summon / queue / hold" out, and
-- the queue tick's fire/cancel the same way. Death only, jug pets only, and
-- never a summon on a Leave, a zone, a logout or a charmed pet. AC1-AC6.
-- ---------------------------------------------------------------------------
;(function()
    local rs = dofile('jobhelpers/bst/bst-helper/resummon.lua');

    local DEATH = { lost = true, kind = 'death', confirmed = true, pet = 'jug',
                    name = 'Hare Familiar', hpp = 4 };
    -- `nil` in a table literal cannot CLEAR a key (pairs never sees it), and
    -- half these cases are exactly "this read came back unreadable" -- so the
    -- overrides carry an explicit unset marker.
    local UNSET = {};
    local function armed(over)
        local st = { armed = true, active = true, jug = 'Carrot Broth', method = 'call',
                     fallback = true, stock = 3, busy = false, now = 100 };
        for k, v in pairs(over or {}) do
            if v == UNSET then st[k] = nil; else st[k] = v; end
        end
        return st;
    end
    local function edge(over)
        local e = {};
        for k, v in pairs(DEATH) do e[k] = v; end
        for k, v in pairs(over or {}) do e[k] = v; end
        return e;
    end

    -- --- the happy path (AC1)
    local d = rs.decideLoss(DEATH, armed());
    check('BRS1 a confirmed jug-pet death summons', d.act, true);
    check('BRS2 ...with the chosen method', d.method, 'call');
    check('BRS3 ...and the configured jug', d.jug, 'Carrot Broth');
    check('BRS4 the request claims the jug into Ammo',
          rs.buildRequest('Carrot Broth', 'call').claim.Ammo, 'Carrot Broth');
    check('BRS5 ...and that same slot must VERIFY WORN before anything fires',
          rs.buildRequest('Carrot Broth', 'call').need.Ammo, 'Carrot Broth');
    check('BRS6 ...firing the chosen ability', rs.buildRequest('Carrot Broth', 'call').command,
          rs.METHOD_COMMAND.call);
    check('BRS7 ...labelled with the act, not the rule',
          rs.buildRequest('Carrot Broth', 'loyalty').label, 'Bestial Loyalty');

    -- --- the switches
    check('BRS8 an unarmed rule never acts', rs.decideLoss(DEATH, armed({ armed = false })).reason, 'off');
    check('BRS9 an inactive module never acts (reason carried)',
          rs.decideLoss(DEATH, armed({ active = false, reason = 'town' })).reason, 'town');
    check('BRS10 an unreadable world is not permission either',
          rs.decideLoss(DEATH, armed({ active = UNSET })).act, false);

    -- --- NEVER on anything but a proven jug-pet death (AC2)
    check('BRS11 a Leave is never a summon', rs.decideLoss(edge({ kind = 'leave', confirmed = false }),
          armed()).reason, 'leave');
    check('BRS12 zoning is never a summon', rs.decideLoss(edge({ kind = 'zone', confirmed = false }),
          armed()).reason, 'zone');
    check('BRS13 logging out is never a summon', rs.decideLoss(edge({ kind = 'logout', confirmed = false }),
          armed()).reason, 'logout');
    check('BRS14 an UNEXPLAINED vanish is never a summon',
          rs.decideLoss(edge({ kind = 'unknown', confirmed = false }), armed()).reason, 'unknown');
    check('BRS15 a charmed pet\'s death triggers nothing',
          rs.decideLoss(edge({ pet = 'charm' }), armed()).reason, 'charm');
    check('BRS16 ...and neither does an unidentifiable pet',
          rs.decideLoss(edge({ pet = 'unknown' }), armed()).reason, 'not-jug');
    check('BRS17 a "death" that confirmed nothing is not a death',
          rs.decideLoss(edge({ confirmed = false }), armed()).reason, 'unconfirmed');
    check('BRS18 no loss at all -> nothing', rs.decideLoss({ lost = false }, armed()).reason, 'no-loss');
    check('BRS19 none of them ever act', (function()
        for _, e in ipairs({ edge({ kind = 'leave' }), edge({ kind = 'zone' }), edge({ kind = 'logout' }),
                             edge({ kind = 'unknown' }), edge({ pet = 'charm' }),
                             edge({ confirmed = false }) }) do
            if rs.decideLoss(e, armed()).act == true then return 'one acted'; end
        end
        return 'none';
    end)(), 'none');

    -- --- out of jug: ONE loud line, and Loyalty still needs one (AC5)
    local nj = rs.decideLoss(DEATH, armed({ jug = UNSET }));
    check('BRS20 no jug picked refuses', nj.act, false);
    check('BRS21 ...loudly', nj.loud, true);
    check('BRS22 ...naming what to do',
          rs.refusalLine(nj):find('choose one', 1, true) ~= nil, true);
    local ns = rs.decideLoss(DEATH, armed({ stock = 0 }));
    check('BRS23 zero of the configured jug refuses', ns.reason, 'no-stock');
    check('BRS24 ...loudly, naming the jug', rs.refusalLine(ns):find('Carrot Broth', 1, true) ~= nil, true);
    check('BRS25 ...and says BOTH methods need one equipped',
          rs.refusalLine(ns):find('Bestial Loyalty', 1, true) ~= nil, true);
    check('BRS26 the Loyalty fallback does NOT rescue an empty bag',
          rs.decideLoss(DEATH, armed({ stock = 0, method = 'loyalty', callReady = false })).act, false);
    check('BRS27 an unreadable stock refuses rather than firing bare',
          rs.decideLoss(DEATH, armed({ stock = UNSET })).reason, 'no-stock');

    -- --- the binary choice + the cooldown fallback (AC3)
    check('BRS28 the chosen method wins while it is ready',
          rs.pickMethod('loyalty', true, true, true), 'loyalty');
    check('BRS29 chosen down + checkbox ON -> the other one',
          rs.pickMethod('call', true, false, true), 'loyalty');
    check('BRS30 ...and the other way round', rs.pickMethod('loyalty', true, true, false), 'call');
    check('BRS31 chosen down + checkbox OFF -> nothing (it will queue)',
          rs.pickMethod('call', false, false, true), nil);
    check('BRS32 both down -> nothing, whatever the checkbox says',
          rs.pickMethod('call', true, false, false), nil);
    check('BRS33 nothing measured at all -> the pick, and let the client judge it',
          rs.pickMethod('call', true, nil, nil), 'call');
    -- THE FIELD BUG (2026-07-30, the maintainer's own resummon): "unknown reads
    -- READY" is the recast service's courtesy gate, and it is right for greying
    -- out a button -- a recast we cannot see must never stop a player pressing
    -- one. Applied to a CHOICE it does not permit an action, it PREFERS one, and
    -- an ability we merely failed to measure beat one we knew was up: the pick
    -- (Bestial Loyalty) did not resolve, read ready, and won on the first line.
    -- The command went into its own cooldown, the pet stayed dead, and a
    -- correctly-configured fallback did nothing.
    check('BRS33a an UNMEASURED pick does NOT beat a MEASURED-ready other',
          rs.pickMethod('loyalty', true, true, nil), 'call');
    check('BRS33b ...but only with the checkbox on -- that checkbox is the consent,\n'
          .. '      and Call Beast spends a jug the player may be avoiding',
          rs.pickMethod('loyalty', false, true, nil), 'loyalty');
    check('BRS33c an unmeasured pick beside a measured-DOWN other is still the pick',
          rs.pickMethod('loyalty', true, false, nil), 'loyalty');
    check('BRS33d a measured-down pick falls to an UNMEASURED other -- it may well be up',
          rs.pickMethod('loyalty', true, nil, false), 'call');
    check('BRS34 the fallback reaches the other on the loss decision too',
          rs.decideLoss(DEATH, armed({ callReady = false })).method, 'loyalty');
    check('BRS35 ...and with the checkbox off it queues instead',
          rs.decideLoss(DEATH, armed({ callReady = false, fallback = false })).queue, true);
    check('BRS36 both down queues (AC4)',
          rs.decideLoss(DEATH, armed({ callReady = false, loyaltyReady = false })).queue, true);
    check('BRS37 ...naming why', rs.decideLoss(DEATH,
          armed({ callReady = false, loyaltyReady = false })).reason, 'recast');
    check('BRS38 a live sequence queues rather than being dropped',
          rs.decideLoss(DEATH, armed({ busy = true })).queue, true);

    -- --- the queue tick: cancels first, then holds, then fire (AC4)
    local function q(over)
        local st = armed(over);
        st.queued = { jug = 'Carrot Broth', method = 'call', fallback = true };
        st.callReady, st.loyaltyReady = false, false;   -- queued BECAUSE both are down
        for k, v in pairs(over or {}) do
            if v == UNSET then st[k] = nil; else st[k] = v; end
        end
        return st;
    end
    check('BRS39 nothing queued -> nothing to decide', rs.queueDecide(armed()).reason, 'none');
    check('BRS40 a pet appearing ANY other way cancels', rs.queueDecide(q({ petPresent = true })).cancel,
          'pet-appeared');
    check('BRS41 zoning cancels', rs.queueDecide(q({ zoning = true })).cancel, 'zone');
    check('BRS42 logging out cancels', rs.queueDecide(q({ logout = true })).cancel, 'logout');
    check('BRS43 an observed Leave cancels', rs.queueDecide(q({ leave = true })).cancel, 'leave');
    check('BRS44 disarming the rule cancels', rs.queueDecide(q({ armed = false })).cancel, 'off');
    check('BRS45 running out of the jug while queued cancels, loudly',
          rs.queueDecide(q({ stock = 0 })).cancel .. '/' .. tostring(rs.queueDecide(q({ stock = 0 })).loud),
          'no-stock/true');
    check('BRS46 an inactive module HOLDS, it does not cancel',
          rs.queueDecide(q({ active = false, reason = 'town' })).cancel, nil);
    check('BRS47 ...and says why it is waiting',
          rs.queueDecide(q({ active = false, reason = 'town' })).reason, 'town');
    check('BRS48 a busy sequencer holds too', rs.queueDecide(q({ busy = true })).reason, 'busy');
    check('BRS49 still on recast holds', rs.queueDecide(q()).reason, 'recast');
    check('BRS50 ...and fires the moment one comes up', rs.queueDecide(q({ callReady = true })).fire, true);
    check('BRS51 ...with that method', rs.queueDecide(q({ callReady = true })).method, 'call');
    check('BRS52 the queue re-decides which ability against what is ready NOW',
          rs.queueDecide(q({ loyaltyReady = true })).method, 'loyalty');
    check('BRS53 ...and honours the checkbox it was queued with', (function()
        local st = q({ loyaltyReady = true });
        st.queued = { jug = 'Carrot Broth', method = 'call', fallback = false };
        return rs.queueDecide(st).fire;
    end)(), false);
    check('BRS53a the JUG is read live, not off the queue record',
          rs.queueDecide(q({ callReady = true, jug = 'Herbal Broth' })).jug, 'Herbal Broth');
    check('BRS53b ...and clearing the picker while queued cancels, loudly',
          rs.queueDecide(q({ callReady = true, jug = UNSET })).cancel, 'no-jug');

    -- --- the reported lines (Panel, never chat -- except the two loud ones)
    check('BRS54 an act reports the ability it used',
          rs.decisionText({ act = true, method = 'loyalty' }), 'summoned with Bestial Loyalty');
    check('BRS55 a queue says it queued and why',
          rs.decisionText({ queue = true, reason = 'recast' }):find('queued', 1, true) ~= nil, true);
    check('BRS56 a cancel says it was cancelled and why',
          rs.decisionText({ cancel = 'pet-appeared' }):find('cancelled', 1, true) ~= nil, true);
    check('BRS57 a charmed pet\'s line does not blame the player',
          rs.decisionText({ reason = 'charm' }):find('charm stays yours', 1, true) ~= nil, true);
    check('BRS58 nothing yet reads as nothing yet', rs.decisionText(nil), 'nothing yet');

    -- --- the methods themselves
    check('BRS59 exactly two methods', #rs.METHODS, 2);
    check('BRS60 an unknown method is not one', rs.isMethod('sic'), false);
    check('BRS61 ...and a request built with one falls back to Call Beast',
          rs.buildRequest('Carrot Broth', 'sic').command, rs.METHOD_COMMAND.call);

    -- --- the GLUE: edge -> decision -> at most one act or one queued resummon.
    -- liveState and request are the two seams, so the whole lifecycle drives
    -- with no world, no sequencer and no chat.
    local acts, lines, WORLD = {}, {}, armed();
    rs.liveState = function() local c = {}; for k, v in pairs(WORLD) do c[k] = v; end return c; end;
    rs.request   = function(m) acts[#acts + 1] = m; return { ok = true }; end;
    rs._emit     = function(l) lines[#lines + 1] = l; end;

    rs.reset();
    rs.onLoss(DEATH, 'bst');
    check('BRS62 a confirmed jug death asks for the summon once', #acts, 1);
    check('BRS63 ...with the chosen method', acts[1], 'call');
    check('BRS64 ...and queues nothing', rs.queued(), nil);

    acts = {};
    rs.reset();
    WORLD = armed({ callReady = false, loyaltyReady = false });
    rs.onLoss(DEATH, 'bst');
    check('BRS65 both recasts down asks for nothing', #acts, 0);
    check('BRS66 ...and queues the resummon', (rs.queued() or {}).jug, 'Carrot Broth');
    check('BRS67 ...remembering the PICK, not a resolved method', rs.queued().method, 'call');
    check('BRS68 ...and the checkbox it was queued with', rs.queued().fallback, true);

    -- the queue tick rides the ordinary vitals beat
    rs.onVitals({ present = false, at = 101 }, 'bst');
    check('BRS69 still down: the queue holds', (rs.queued() or {}).jug, 'Carrot Broth');
    check('BRS70 ...and nothing was asked for', #acts, 0);
    WORLD = armed({ callReady = false, loyaltyReady = true });
    rs.onVitals({ present = false, at = 102 }, 'bst');
    check('BRS71 one coming up fires the queued resummon', acts[#acts], 'loyalty');
    check('BRS72 ...and spends the queue', rs.queued(), nil);
    check('BRS73 a beat with nothing queued is a no-op',
          rs.onVitals({ present = false, at = 103 }, 'bst'), nil);

    -- a pet appearing ANY other way cancels it
    acts = {};
    rs.reset();
    WORLD = armed({ callReady = false, loyaltyReady = false });
    rs.onLoss(DEATH, 'bst');
    rs.onVitals({ present = true, at = 110, name = 'Hare Familiar' }, 'bst');
    check('BRS74 a pet coming out cancels the queue', rs.queued(), nil);
    check('BRS75 ...without summoning anything', #acts, 0);

    -- zoning cancels it, read through liveState's world
    rs.reset();
    rs.onLoss(DEATH, 'bst');
    WORLD = armed({ callReady = false, loyaltyReady = false, zoning = true });
    rs.onVitals({ present = false, at = 120 }, 'bst');
    check('BRS76 zoning cancels the queue', rs.queued(), nil);

    -- ...and so does disarming the rule, which is the row pill's whole job
    rs.reset();
    WORLD = armed({ callReady = false, loyaltyReady = false });
    rs.onLoss(DEATH, 'bst');
    check('BRS77 a queue is standing', rs.queued() ~= nil, true);
    rs.setArmed(false);
    check('BRS78 disarming drops it on the spot', rs.queued(), nil);

    -- the loud refusals speak exactly once each
    lines, acts = {}, {};
    rs.reset();
    WORLD = armed({ stock = 0 });
    rs.onLoss(DEATH, 'bst');
    check('BRS79 out of jug says so, once', #lines, 1);
    check('BRS80 ...naming the jug', lines[1]:find('Carrot Broth', 1, true) ~= nil, true);
    check('BRS81 ...and summons nothing', #acts, 0);
    lines = {};
    WORLD = armed({ jug = UNSET });
    rs.onLoss(DEATH, 'bst');
    check('BRS82 no jug picked says so, once', #lines, 1);
    lines = {};
    WORLD = armed();
    rs.onLoss(edge({ kind = 'leave', confirmed = false }), 'bst');
    check('BRS83 a Leave is silent -- it is the rule working, not a blocker', #lines, 0);
    check('BRS84 ...and reported in the Panel line instead',
          rs.lastDecision().reason, 'leave');

    -- --- THE SUMMON SET (2026-07-30): the master's +CHR at spawn buys the jug
    --     pet Ready strength for its whole life on this server, so a summon now
    --     dresses -- best-effort, jug still the only slot that must land, and
    --     hands off the weapons unless the player says otherwise.
    local SUMMONSET = { Head = 'Chr Hat', Body = 'Chr Body', Main = 'Chr Sword',
                        Sub = 'Chr Shield', Range = 'Chr Bow', Ammo = 'Not The Jug' };
    local sumS = fakeApi({
        id       = 'bst-helper',
        setSlots = { ['CHR'] = SUMMONSET },
        stock    = 3,
        vals     = { resummonJug = 'Carrot Broth', resummonMethod = 'call',
                     resummonFallback = true, summonSet = 'CHR' },
    });
    rs.init(sumS);

    local req = rs.buildRequest('Carrot Broth', 'call');
    check('BRS85 the summon set dresses the ordinary slots',
          tostring(req.claim.Head) .. '/' .. tostring(req.claim.Body), 'Chr Hat/Chr Body');
    check('BRS86 the WEAPON slots are left alone by default (they cost your TP)',
          (req.claim.Main == nil and req.claim.Sub == nil and req.claim.Range == nil), true);
    check('BRS87 the JUG owns Ammo, whatever the set wanted there', req.claim.Ammo, 'Carrot Broth');
    check('BRS88 ...and is still the ONLY slot that must verify worn',
          (req.need.Ammo == 'Carrot Broth' and req.need.Head == nil), true);
    check('BRS89 the claim is held past the fire, for the spawn-time read',
          req.hold, rs.HOLD_S);

    sumS.vals.summonWeapons = true;
    local req2 = rs.buildRequest('Carrot Broth', 'call');
    check('BRS90 opting in lets the set claim the weapons too',
          tostring(req2.claim.Main) .. '/' .. tostring(req2.claim.Range), 'Chr Sword/Chr Bow');
    check('BRS91 ...and Ammo is STILL the jug, never the set\'s', req2.claim.Ammo, 'Carrot Broth');
    check('BRS91b the set the API handed over is never edited in place -- the claim is a COPY',
          tostring(SUMMONSET.Main) .. '/' .. tostring(SUMMONSET.Ammo), 'Chr Sword/Not The Jug');
    sumS.vals.summonWeapons = false;

    sumS.vals.summonSet = '';
    check('BRS92 no set picked claims the jug alone, exactly as before',
          (function()
              local r = rs.buildRequest('Carrot Broth', 'call');
              local n = 0;
              for _ in pairs(r.claim) do n = n + 1; end
              return n == 1 and r.claim.Ammo == 'Carrot Broth';
          end)(), true);
    sumS.vals.summonSet = 'CHR';

    -- --- SUMMON NOW: the third requester of the same act
    acts, lines = {}, {};
    check('BRS93 the button summons with the chosen method', rs.summonNow(), true);
    check('BRS94 ...through the one act, not a second implementation', acts[#acts], 'call');
    check('BRS95 ...and says nothing when it works', #lines, 0);

    sumS.vals.resummonJug = '';
    check('BRS96 no jug picked refuses', rs.summonNow(), false);
    check('BRS97 ...loudly, because the player can fix it', #lines, 1);
    sumS.vals.resummonJug = 'Carrot Broth';

    lines = {};
    local sumS2 = fakeApi({
        id    = 'bst-helper',
        stock = 0,
        vals  = { resummonJug = 'Carrot Broth', resummonMethod = 'call' },
    });
    rs.init(sumS2);
    check('BRS98 out of jug refuses', rs.summonNow(), false);
    check('BRS99 ...naming it', lines[#lines]:find('Carrot Broth', 1, true) ~= nil, true);

    lines = {};
    local sumS3 = fakeApi({
        id    = 'bst-helper',
        stock = 2,
        ready = { ['Call Beast'] = false, ['Bestial Loyalty'] = false },
        vals  = { resummonJug = 'Carrot Broth', resummonMethod = 'call', resummonFallback = true },
    });
    rs.init(sumS3);
    check('BRS100 both abilities down refuses', rs.summonNow(), false);
    check('BRS101 ...and says which, rather than doing nothing quietly',
          lines[#lines]:find('cooldown', 1, true) ~= nil, true);

    -- --- the keybind SETTING is the module's; the framework does the binding
    local keyS = fakeApi({ id = 'bst-helper', vals = {} });
    rs.init(keyS);
    -- --- the TRI-STATE, built here because the API's `ready` alone cannot carry
    --     it: an ability measured idle and one whose recast slot never resolved
    --     both answer true, and the REMAINING beside it is the difference. This
    --     is the plumbing the field bug needed and did not have.
    local triS = fakeApi({
        id    = 'bst-helper',
        ready = { ['Call Beast'] = true, ['Bestial Loyalty'] = false },
        remaining = 754,
        vals  = { resummonJug = 'Carrot Broth' },
    });
    check('BRS101a a measured-idle ability measures TRUE',
          rs.measure(triS, rs.RECAST.call), true);
    check('BRS101b a measured-down one measures FALSE',
          rs.measure(triS, rs.RECAST.loyalty), false);
    check('BRS101c an ability whose slot never resolved measures NIL, not ready',
          rs.measure(triS, { name = 'Nonesuch', label = 'Nonesuch' }), nil);
    check('BRS101d ...and the Panel says so in words rather than lying',
          rs.recastText(triS, { name = 'Nonesuch', label = 'Nonesuch' }),
          'cannot read its cooldown');
    check('BRS101e a ready ability reads ready', rs.recastText(triS, rs.RECAST.call), 'ready');
    check('BRS101f ...and a cooldown reads as minutes and seconds',
          rs.recastText(triS, rs.RECAST.loyalty), '12m 34s');

    -- --- THE FIELD CASE, END TO END, through the REAL liveState (the glue block
    --     above replaced it, so this drives a fresh instance): the pet dies, the
    --     pick is Bestial Loyalty, the client says Loyalty is DOWN and Call Beast
    --     is UP, the checkbox is on. 2026-07-30 it fired Loyalty into its own
    --     cooldown, because an unresolvable recast read READY and won on the
    --     first line of pickMethod. It must reach for Call Beast.
    local rsF = dofile('jobhelpers/bst/bst-helper/resummon.lua');
    local fired = {};
    rsF._emit = function() end;
    local fieldS = fakeApi({
        id    = 'bst-helper',
        stock = 3,
        ready = { ['Bestial Loyalty'] = false, ['Call Beast'] = true },
        -- delay 0: this block is about WHICH ability goes out. The pause has its
        -- own checks below.
        vals  = { resummonArmed = true, resummonJug = 'Carrot Broth',
                  resummonMethod = 'loyalty', resummonFallback = true,
                  resummonDelay = 0 },
    });
    fieldS.act.request = function(r) fired[#fired + 1] = r; return { ok = true }; end;
    rsF.init(fieldS);
    local fd = rsF.onLoss(DEATH);
    check('BRS101g the pick being DOWN no longer wins the summon', fd.method, 'call');
    check('BRS101h ...and the act that actually went out is Call Beast',
          (fired[1] or {}).command, rsF.METHOD_COMMAND.call);
    check('BRS101i ...carrying the configured jug, verified', (fired[1] or {}).need.Ammo,
          'Carrot Broth');
    check('BRS101j ...and nothing was queued -- it summoned', rsF.queued(), nil);

    -- with the checkbox OFF the pick is never swapped: it queues instead
    local rsG = dofile('jobhelpers/bst/bst-helper/resummon.lua');
    local fired2 = {};
    rsG._emit = function() end;
    local fieldS2 = fakeApi({
        id    = 'bst-helper',
        stock = 3,
        ready = { ['Bestial Loyalty'] = false, ['Call Beast'] = true },
        vals  = { resummonArmed = true, resummonJug = 'Carrot Broth',
                  resummonMethod = 'loyalty', resummonFallback = false,
                  resummonDelay = 0 },
    });
    fieldS2.act.request = function(r) fired2[#fired2 + 1] = r; return { ok = true }; end;
    rsG.init(fieldS2);
    local fd2 = rsG.onLoss(DEATH);
    check('BRS101k checkbox OFF: the pick is never swapped for it', #fired2, 0);
    check('BRS101l ...it queues and waits for the ability the player chose', fd2.queue, true);

    -- --- THE PAUSE (Henrik, 2026-07-30, on the first working resummon: "it was
    --     soooo instant"). Not a technical need -- it is what the act LOOKS
    --     like, and this project has already had a GM read an addon's behaviour
    --     as botting once. Implemented as the QUEUE rather than a private timer,
    --     which is what makes the wait cancellable.
    check('BRS101m the default is a pause, not instant', rsF.DEFAULT_DELAY_S, 1.0);
    check('BRS101n an unreadable store reads the DEFAULT -- "instant" must never be\n'
          .. '      what a missing setting falls back to', rsF.clampDelay(nil), 1.0);
    check('BRS101o ...and it is clamped to the band', (function()
        return rsF.clampDelay(-5) == 0 and rsF.clampDelay(99) == rsF.MAX_DELAY_S;
    end)(), true);

    local rsH = dofile('jobhelpers/bst/bst-helper/resummon.lua');
    local fired3 = {};
    rsH._emit = function() end;
    local delayS = fakeApi({
        id    = 'bst-helper',
        stock = 3,
        ready = { ['Call Beast'] = true, ['Bestial Loyalty'] = true },
        clock = 500,
        vals  = { resummonArmed = true, resummonJug = 'Carrot Broth',
                  resummonMethod = 'call', resummonFallback = true,
                  resummonDelay = 1.0 },
    });
    delayS.act.request = function(r) fired3[#fired3 + 1] = r; return { ok = true }; end;
    rsH.init(delayS);
    local dd = rsH.onLoss({ lost = true, kind = 'death', confirmed = true, pet = 'jug',
                            name = 'Hare Familiar', hpp = 4, at = 500 });
    check('BRS101p a confirmed death does NOT summon on the spot any more', #fired3, 0);
    check('BRS101q ...it queues, and says what it is waiting for', dd.reason, 'delay');
    check('BRS101r ...remembering the moment it may go',
          (rsH.queued() or {}).notBefore, 501.0);
    rsH.onVitals({ present = false, at = 500.6 });
    check('BRS101s a beat inside the pause fires nothing', #fired3, 0);
    check('BRS101t ...and still says why', (rsH.lastDecision() or {}).reason, 'delay');
    rsH.onVitals({ present = false, at = 501.2 });
    check('BRS101u the first beat past it summons', #fired3, 1);
    check('BRS101v ...and the queue is spent', rsH.queued(), nil);

    -- the wait is the PLAYER'S: summoning by hand inside it drops the pending one
    local rsI = dofile('jobhelpers/bst/bst-helper/resummon.lua');
    local fired4 = {};
    rsI._emit = function() end;
    local cancelS = fakeApi({
        id    = 'bst-helper',
        stock = 3,
        clock = 700,
        vals  = { resummonArmed = true, resummonJug = 'Carrot Broth',
                  resummonMethod = 'call', resummonFallback = true,
                  resummonDelay = 2.0 },
    });
    cancelS.act.request = function(r) fired4[#fired4 + 1] = r; return { ok = true }; end;
    rsI.init(cancelS);
    rsI.onLoss({ lost = true, kind = 'death', confirmed = true, pet = 'jug',
                 name = 'Hare Familiar', hpp = 4, at = 700 });
    check('BRS101w a pause is standing', rsI.queued() ~= nil, true);
    rsI.onVitals({ present = true, at = 700.8, name = 'Hare Familiar' });
    check('BRS101x a pet out inside the pause CANCELS it -- the helper never races\n'
          .. '      a player who summoned by hand', rsI.queued(), nil);
    check('BRS101y ...having summoned nothing', #fired4, 0);

    check('BRS102 no key is set by default', rs.key(), nil);
    rs.setKey('  ^F3  ');
    check('BRS103 a typed key is stored trimmed', rs.key(), '^F3');
    check('BRS104 ...under the config key the commands block names', keyS.vals.summonKey, '^F3');
    rs.setKey('');
    check('BRS105 clearing it is an ordinary write', rs.key(), nil);
end)();

-- ---------------------------------------------------------------------------
-- AS: the ACTION SEQUENCER (issue #138), driven at its SEAM with injected
-- worn / blocker / fire / release fakes -- never-fire-bare, timeout abort,
-- senior-claimant refusal, release, exactly one send, one-live-at-a-time, and
-- the simultaneous-request module-order tiebreak. AC1/AC2/AC3/AC6/AC8.
-- ---------------------------------------------------------------------------
;(function()
    local as = dofile('feature/actionseq.lua');
    local function mkio(worn, blocker)
        local rec = { fired = {}, released = 0, emits = {} };
        rec.io = {
            worn    = function(slot) return (worn or {})[slot]; end,
            blocker = function(slot) return (blocker or {})[slot]; end,
            fire    = function(cmd) rec.fired[#rec.fired + 1] = cmd; end,
            release = function() rec.released = rec.released + 1; end,
            emit    = function(line) rec.emits[#rec.emits + 1] = line; end,
        };
        return rec;
    end

    -- happy path: verified worn -> fire once -> hold -> release (AC1)
    as.reset();
    check('AS1 idle at rest', as.state(), 'idle');
    local acc = as.request({ module = 'bst', label = 'Reward', order = 1,
        claim = { Ammo = 'Pet Food Delta' }, need = { Ammo = 'Pet Food Delta' },
        command = '/ja "Reward" <me>', timeout = 4 });
    check('AS2 request accepted', acc.ok, true);
    check('AS3 the claim is live while claiming', (as.claim() or {}).Ammo, 'Pet Food Delta');
    check('AS4 active while claiming', as.active(), true);
    local r = mkio({}, {});
    as.tick(0, r.io);
    check('AS5 not worn yet -> still claiming, no fire', #r.fired, 0);
    local r2 = mkio({ Ammo = 'Pet Food Delta' }, {});
    as.tick(0.5, r2.io);
    check('AS6 verified worn -> fired once', #r2.fired, 1);
    check('AS7 fired the right command', r2.fired[1], '/ja "Reward" <me>');
    check('AS8 state is firing (gear held through the cast)', as.state(), 'firing');
    as.tick(0.6, r2.io);
    check('AS9 exactly ONE send across ticks', #r2.fired, 1);
    as.tick(1.5, r2.io);
    check('AS10 released after the hold', r2.released >= 1, true);
    check('AS11 idle after release', as.state(), 'idle');
    check('AS12 success is SILENT (no chat)', #r2.emits, 0);
    check('AS13 last outcome is fired', (as.lastOutcome() or {}).outcome, 'fired');

    -- never-fire-bare + timeout abort (AC3): the gear never matches
    as.reset();
    as.request({ module = 'bst', label = 'Reward', order = 1,
        claim = { Ammo = 'Pet Food Delta' }, need = { Ammo = 'Pet Food Delta' },
        command = 'FIRE', timeout = 4 });
    local r3 = mkio({ Ammo = 'Something Else' }, {});
    as.tick(0, r3.io);          -- startAt = 0
    as.tick(2, r3.io);          -- within the window, wrong gear worn
    check('AS14 never fires bare (wrong gear worn)', #r3.fired, 0);
    as.tick(4, r3.io);          -- timeout
    check('AS15 timeout -> aborted, nothing fired', #r3.fired, 0);
    check('AS16 abort emits one line', #r3.emits, 1);
    check('AS17 abort released the claim', r3.released >= 1, true);
    check('AS18 idle after abort', as.state(), 'idle');
    check('AS19 last outcome is aborted', (as.lastOutcome() or {}).outcome, 'aborted');

    -- senior-claimant refusal (AC2): a definitive blocker on a needed slot
    as.reset();
    as.request({ module = 'bst', label = 'Reward', order = 1,
        claim = { Ammo = 'Pet Food Delta' }, need = { Ammo = 'Pet Food Delta' },
        command = 'FIRE', timeout = 4 });
    local r4 = mkio({}, { Ammo = 'Free equip' });
    as.tick(0, r4.io);
    check('AS20 a blocker on a needed slot -> refused, no fire', #r4.fired, 0);
    check('AS21 refusal NAMES the blocker', (r4.emits[1] or ''):find('Free equip', 1, true) ~= nil, true);
    check('AS22 refusal released the claim', r4.released >= 1, true);
    check('AS23 last outcome is refused', (as.lastOutcome() or {}).outcome, 'refused');

    -- one live at a time: a started sequence is never preempted
    as.reset();
    as.request({ module = 'bst', label = 'Reward', order = 1, claim = { Ammo = 'X' }, command = 'FIRE', timeout = 4 });
    local busy = as.request({ module = 'pup', label = 'Ready', order = 1, claim = { Ammo = 'Y' }, command = 'FIRE2', timeout = 4 });
    check('AS24 a second request while one runs is refused', busy.ok, false);
    check('AS25 the refusal names the holder', busy.holder, 'bst');

    -- simultaneous contenders resolve by module order (AC6)
    as.reset();
    local win, losers = as.arbitrateRequests({
        { module = 'bst', order = 1 }, { module = 'pup', order = 3 }, { module = 'dnc', order = 2 } });
    check('AS26 the highest module order wins', win.module, 'pup');
    check('AS27 the losers are the rest', #losers, 2);
    check('AS28 a tie breaks deterministically by module id',
          (as.arbitrateRequests({ { module = 'zeta', order = 5 }, { module = 'alpha', order = 5 } })).module, 'alpha');
    as.reset();
end)();

-- ---------------------------------------------------------------------------
-- JHR: the JobHelper CLAIM PRIORITY row (issue #138). arbiter.placeJobHelper
-- (default below Locks), the per-job anchor store, moveRankRow, and placedOrder
-- hiding the row with zero modules. AC5.
-- ---------------------------------------------------------------------------
;(function()
    local ARB = dofile('gear/arbiter.lua');
    local BASE = { 'Disabled', 'Naked', 'Pins', 'Locks', 'AutoAmmo', 'MaxMP',
                   'Craft', 'HELM', 'Fishing', 'Chocobo', 'Triggers' };

    local function idxOf(list, name)
        for i, n in ipairs(list) do if n == name then return i; end end
        return nil;
    end

    local p = ARB.placeJobHelper(BASE, nil);
    check('JHR1 default places JobHelper directly below Locks', idxOf(p, 'JobHelper'), idxOf(p, 'Locks') + 1);
    check('JHR2 the Disabled ceiling stays first', p[1], 'Disabled');
    check('JHR3 the Triggers floor stays last', p[#p], 'Triggers');
    local p2 = ARB.placeJobHelper(BASE, 'Chocobo');
    check('JHR4 a chosen anchor places it directly below that row', idxOf(p2, 'JobHelper'), idxOf(p2, 'Chocobo') + 1);
    local p3 = ARB.placeJobHelper(BASE, 'Triggers');
    check('JHR5 anchor Triggers is refused -> falls back below Locks', p3[idxOf(p3, 'JobHelper') - 1], 'Locks');
    local p4 = ARB.placeJobHelper(p, nil);   -- placing over an order that already has it
    local cnt = 0; for _, n in ipairs(p4) do if n == 'JobHelper' then cnt = cnt + 1; end end
    check('JHR6 placeJobHelper is idempotent (exactly one JobHelper)', cnt, 1);

    -- the per-job store (jobhelpers) -- stub the config file layer
    local savedArb = package.loaded['dlac\\gear\\arbiter'];
    package.loaded['dlac\\gear\\arbiter'] = ARB;   -- jobhelpers lazily requires it
    local jh = dofile('feature/jobhelpers.lua');
    package.loaded['dlac\\feature\\jobhelpers'] = jh;
    local FILES = {};
    local realOpen, realLoadfile = io.open, loadfile;
    jh._charDir = function() return 'JHRDIR\\'; end
    io.open = function(path, mode)
        if type(path) == 'string' and path:find('JHRDIR', 1, true) then
            if (mode or 'r'):find('w') then
                return { write = function(_, s) FILES[path] = (FILES[path] or '') .. s; end, close = function() end };
            else
                if FILES[path] == nil then return nil; end
                local c = false;
                return { read = function() if c then return nil; end c = true; return FILES[path]; end, close = function() end };
            end
        end
        return realOpen(path, mode);
    end
    loadfile = function(path)
        if type(path) == 'string' and path:find('JHRDIR', 1, true) then
            local s = FILES[path]; if s == nil then return nil; end return (loadstring or load)(s);
        end
        return realLoadfile(path);
    end

    jh.modules = {};
    check('JHR7 placedOrder hides JobHelper with zero modules', idxOf(jh.placedOrder(BASE, 'BST'), 'JobHelper'), nil);

    jh.modules = { { id = 'bst', label = 'BST Helper', jobs = { 'BST' }, mod = {} } };
    check('JHR8 default anchor is Locks', jh.rankAnchorFor('BST'), 'Locks');
    local placed = jh.placedOrder(BASE, 'BST');
    check('JHR9 with a module installed JobHelper sits below Locks',
          placed[idxOf(placed, 'JobHelper') - 1], 'Locks');
    local moved = jh.moveRankRow(placed, 'BST', -1);   -- up one, above Locks
    check('JHR10 moveRankRow returns a new order', type(moved), 'table');
    check('JHR11 the anchor for BST is remembered (now Pins)', jh.rankAnchorFor('BST'), 'Pins');
    check('JHR12 a job never dragged keeps the default', jh.rankAnchorFor('PUP'), 'Locks');
    check('JHR13 the per-job anchor was written to disk', FILES['JHRDIR\\jobhelpers.lua'] ~= nil, true);
    check('JHR14 the anchor survives a re-read',
          (jh._normalizeCfg((loadstring or load)(FILES['JHRDIR\\jobhelpers.lua'])()).rank or {})['BST'], 'Pins');
    -- placedOrder now honors the remembered anchor for BST only
    check('JHR15 placedOrder reflects the remembered BST anchor',
          jh.placedOrder(BASE, 'BST')[idxOf(jh.placedOrder(BASE, 'BST'), 'JobHelper') - 1], 'Pins');
    check('JHR16 a different job still places at the default',
          jh.placedOrder(BASE, 'PUP')[idxOf(jh.placedOrder(BASE, 'PUP'), 'JobHelper') - 1], 'Locks');

    io.open = realOpen; loadfile = realLoadfile;
    jh.modules = {};
    package.loaded['dlac\\gear\\arbiter'] = savedArb;
    package.loaded['dlac\\feature\\jobhelpers'] = nil;
    package.loaded['dlac\\lib\\statefile'] = nil;
end)();

-- ---------------------------------------------------------------------------
-- JHW: the JobHelper claimant at the /dl why seam (issue #138). The row is
-- named by its DISPLAY LABEL everywhere a player reads it, never the internal
-- identity. AC8 ("claimant row tested at the registry seam including /dl why").
-- ---------------------------------------------------------------------------
;(function()
    local ARB = dofile('gear/arbiter.lua');
    check('JHW1 claimantLabel maps JobHelper -> "Job helper"', ARB.claimantLabel('JobHelper'), 'Job helper');
    local order = ARB.placeJobHelper({ 'Disabled', 'Naked', 'Pins', 'Locks', 'AutoAmmo', 'MaxMP',
                                       'Craft', 'HELM', 'Fishing', 'Chocobo', 'Triggers' }, nil);
    local lines = ARB.arbWhyLines({ JobHelper = { Ammo = 'Pet Food Delta' } }, order, {});
    local joined = table.concat(lines, '\n');
    check('JHW2 /dl why names the Job helper claimant by LABEL', joined:find('Job helper', 1, true) ~= nil, true);
    check('JHW3 /dl why never leaks the internal identity', joined:find('JobHelper', 1, true), nil);
    check('JHW4 the line names the Ammo slot it won', joined:find('Ammo', 1, true) ~= nil, true);
end)();

-- ---------------------------------------------------------------------------
-- EDG: the ENGAGE / TARGET EDGE service (issue #139). Recorded-byte replays of
-- BOTH packet kinds through the pure decode, then the per-target debounce and
-- the subscriber notification driven at the pump seam with an injected entity
-- reader. The bytes below are laid out per the pinned GP_CLI_COMMAND_ACTION
-- struct (u32 UniqueNo @0x04, u16 ActIndex @0x08, u16 Category @0x0A) -- the
-- same layout feature\equipengine's parseAction reads for the timing engine, and
-- the one accwatch's field-proven engage watch reads on feature/autoacc.
-- AC1/AC2/AC3/AC6.
-- ---------------------------------------------------------------------------
;(function()
    local ew = dofile('feature/engagewatch.lua');

    local function u16(v) return string.char(v % 256, math.floor(v / 256) % 256); end
    local function u32(v)
        return string.char(v % 256, math.floor(v / 256) % 256,
                           math.floor(v / 65536) % 256, math.floor(v / 16777216) % 256);
    end
    -- One outgoing 0x01A, 16 bytes: header, sync, UniqueNo, ActIndex, Category,
    -- Param. The header word is the FFXI packing -- id in the low 9 bits, size in
    -- 4-byte units above it: 0x1A + (16/4)*512 = 0x081A.
    local function actionPkt(serverId, index, category)
        return u16(0x081A) .. u16(0)          -- 0x00 id|size (16 bytes), 0x02 sync
            .. u32(serverId)                   -- 0x04 UniqueNo (target server id)
            .. u16(index)                      -- 0x08 ActIndex (target entity index)
            .. u16(category)                   -- 0x0A Category
            .. u16(0);                         -- 0x0C Param
    end
    -- Two real-shaped battle targets: dynamic-entity ids in the CatsEyeXI range.
    local MOB_A = { id = 17797121, ix = 0x2E1 };
    local MOB_B = { id = 17797122, ix = 0x2E2 };

    -- --- the pure decode, both kinds ---
    local e1 = ew.decode(actionPkt(MOB_A.id, MOB_A.ix, ew.CAT_ENGAGE));
    check('EDG1 an ENGAGE packet decodes as an engage edge', e1 ~= nil and e1.kind, 'engage');
    check('EDG2 it captures the exact entity index from the packet', e1.index, MOB_A.ix);
    check('EDG3 ...and the target server id', e1.serverId, MOB_A.id);
    local e2 = ew.decode(actionPkt(MOB_B.id, MOB_B.ix, ew.CAT_RETARGET));
    check('EDG4 a CHANGE-TARGET packet decodes as a retarget edge', e2 ~= nil and e2.kind, 'retarget');
    check('EDG5 ...with its own entity', e2.index, MOB_B.ix);
    check('EDG6 a spell action (category 3) is not an edge', ew.decode(actionPkt(MOB_A.id, MOB_A.ix, 0x03)), nil);
    check('EDG7 a weaponskill (category 7) is not an edge', ew.decode(actionPkt(MOB_A.id, MOB_A.ix, 0x07)), nil);
    check('EDG8 a torn/short packet decodes to nothing', ew.decode(string.rep('\0', 6)), nil);
    check('EDG9 a non-string decodes to nothing', ew.decode(nil), nil);
    check('EDG10 the readers are little-endian', ew._u32at(u32(17797121), 0), 17797121);
    check('EDG11 reading past the end is zeros, never an error', ew._u16at('ab', 40), 0);

    -- The fixture is byte-accurate, proved against the ENGINE's own readers
    -- rather than asserted: equipengine walks the header as a real chunk and its
    -- parseAction (the twin that reads the same packet for the timing engine)
    -- must see the same target and category. A fixture only this module can read
    -- would prove nothing about the wire.
    local eng = dofile('feature/equipengine.lua');
    local raw = actionPkt(MOB_A.id, MOB_A.ix, ew.CAT_ENGAGE);
    local walked = eng.parseChunk(raw);
    check('EDG11a the fixture is a well-formed 16-byte 0x01A chunk',
          #walked == 1 and walked[1].id == 0x1A and walked[1].size, 16);
    local twin = eng.parseAction(raw);
    check('EDG11b the engine twin decodes the same target index', twin.target, MOB_A.ix);
    check('EDG11c ...and the same category', twin.category, ew.CAT_ENGAGE);

    -- --- the target key: server id wins, index is the fallback, nothing is nil ---
    check('EDG12 the debounce key prefers the server id',
          ew.targetKey({ serverId = MOB_A.id, index = MOB_A.ix }), 'id:17797121');
    check('EDG13 ...and falls back to the entity index',
          ew.targetKey({ serverId = 0, index = MOB_A.ix }), 'ix:737');
    check('EDG14 a packet naming NO entity is not an actionable edge',
          ew.targetKey({ serverId = 0, index = 0 }), nil);

    -- --- the pump: debounce + notify, with the entity read injected ---
    local NAMES = { [MOB_A.ix] = 'Nursery Nazuna  ', [MOB_B.ix] = 'Wild Rabbit' };
    local function nameOf(ix) local n = NAMES[ix]; if n == nil then return nil; end
        return (n:gsub('%s+$', '')); end
    local seen = {};
    ew.reset(true);
    ew.subscribe('test', function(edge) seen[#seen + 1] = edge; end);

    ew.onPacket(actionPkt(MOB_A.id, MOB_A.ix, ew.CAT_ENGAGE), 100);
    check('EDG15 the network-thread half notifies nobody by itself', #seen, 0);
    check('EDG16 the main-thread pump accepts the edge', ew.pump(nil, nameOf), 1);
    check('EDG17 the subscriber got the edge', #seen, 1);
    check('EDG18 ...carrying the packet-captured entity', seen[1].serverId, MOB_A.id);
    check('EDG19 ...and the trimmed entity name', seen[1].name, 'Nursery Nazuna');
    check('EDG20 lastEdge answers the same record', (ew.lastEdge() or {}).serverId, MOB_A.id);

    -- same target, 2s later: stutter, debounced (AC2 "same-target stutter")
    ew.onPacket(actionPkt(MOB_A.id, MOB_A.ix, ew.CAT_ENGAGE), 102);
    check('EDG21 the SAME target inside 5s is debounced', ew.pump(nil, nameOf), 0);
    check('EDG22 ...so no subscriber heard it', #seen, 1);
    -- a retarget onto the same mob is a DIFFERENT KIND: it fires. FIELD-RULED
    -- 2026-07-29 (Henrik's BST, Fight round 1): a fresh attack sends 0x0F then
    -- 0x02 milliseconds apart, so a target-only key let the refused retarget
    -- swallow the engage as "stutter" and Fight never heard a single attack.
    -- The key is (target, kind); same-kind stutter stays muted (EDG21).
    ew.onPacket(actionPkt(MOB_A.id, MOB_A.ix, ew.CAT_RETARGET), 103);
    check('EDG23 the debounce is per (TARGET, KIND): a retarget after an engage fires', ew.pump(nil, nameOf), 1);
    -- ...and the field pair the ruling came from: retarget-then-engage on a
    -- FRESH mob (the client's real attack order) -- BOTH notify.
    ew.onPacket(actionPkt(77771, 0x341, ew.CAT_RETARGET), 103.4);
    ew.onPacket(actionPkt(77771, 0x341, ew.CAT_ENGAGE), 103.5);
    check('EDG23b the 0x0F-then-0x02 attack pair BOTH notify (the Fight field bug)', ew.pump(nil, nameOf), 2);
    -- same-kind stutter on that mob stays muted, both kinds
    ew.onPacket(actionPkt(77771, 0x341, ew.CAT_ENGAGE), 103.6);
    ew.onPacket(actionPkt(77771, 0x341, ew.CAT_RETARGET), 103.7);
    check('EDG23c same-kind repeats inside the window stay muted', ew.pump(nil, nameOf), 0);
    -- a DIFFERENT target inside the window fires at once (AC2 "rolling to the next mob")
    ew.onPacket(actionPkt(MOB_B.id, MOB_B.ix, ew.CAT_RETARGET), 103.2);
    check('EDG24 a DIFFERENT target inside the window fires immediately', ew.pump(nil, nameOf), 1);
    check('EDG25 ...as a retarget edge on the new entity',
          seen[#seen].kind == 'retarget' and seen[#seen].serverId, MOB_B.id);
    -- and the first mob again, after the window
    ew.onPacket(actionPkt(MOB_A.id, MOB_A.ix, ew.CAT_ENGAGE), 106);
    check('EDG26 the same target AFTER the window fires again', ew.pump(nil, nameOf), 1);

    -- a target the packet did not name never reaches a subscriber
    local before = #seen;
    ew.onPacket(actionPkt(0, 0, ew.CAT_RETARGET), 120);
    check('EDG27 clearing the target notifies nobody', ew.pump(nil, nameOf), 0);
    check('EDG28 ...and does not disturb the last edge', #seen, before);

    -- containment + housekeeping
    local other = 0;
    ew.subscribe('boom', function() error('subscriber boom'); end);
    ew.subscribe('other', function() other = other + 1; end);
    ew.onPacket(actionPkt(MOB_B.id, MOB_B.ix, ew.CAT_ENGAGE), 140);
    ew.pump(nil, nameOf);
    check('EDG29 a throwing subscriber never costs another its notification', other, 1);
    ew.unsubscribe('boom'); ew.unsubscribe('other');
    check('EDG30 unsubscribe drops it', ew.subscriberCount(), 1);

    ew.reset(true);
    for i = 1, ew.QUEUE_MAX + 4 do ew.onPacket(actionPkt(17800000 + i, 100 + i, ew.CAT_ENGAGE), 200 + i); end
    check('EDG31 the network-thread queue is capped (oldest dropped)', ew.pump(nil, nameOf), ew.QUEUE_MAX);
    check('EDG32 an empty queue is a cheap no-op', ew.pump(nil, nameOf), 0);
    ew._prune(1e6);
    ew.onPacket(actionPkt(17800005, 105, ew.CAT_ENGAGE), 1e6);
    check('EDG33 a pruned debounce key fires again', ew.pump(nil, nameOf), 1);
    ew.reset(true);
    check('EDG34 reset clears the answer', ew.lastEdge(), nil);
    check('EDG35 the debounce window is the PRD 5 seconds', ew.DEBOUNCE_S, 5.0);

    -- --- the FIRST-SWING signal (Henrik's "Send when" option, 2026-07-29) ----
    -- 0x028 fixture: actor u32 @0x05 (chars 6-9 LE), action type = 4 bits at
    -- byte 10 bit 2 (char 11, LSB-first -> type*4). equipengine.parse0x28's
    -- exact field layout.
    local function swingPkt(actor, atype)
        local a1 = actor % 256;
        local a2 = math.floor(actor / 256) % 256;
        local a3 = math.floor(actor / 65536) % 256;
        local a4 = math.floor(actor / 16777216) % 256;
        return string.char(0, 0, 0, 0, 0, a1, a2, a3, a4, 0, (atype or 1) * 4, 0, 0, 0, 0, 0);
    end
    check('EDG36 a melee round decodes to its actor', ew.decodeSwing(swingPkt(4242, 1)), 4242);
    check('EDG37 a non-melee action decodes to nil', ew.decodeSwing(swingPkt(4242, 4)), nil);
    check('EDG38 a short packet decodes to nil', ew.decodeSwing('abc'), nil);

    ew._myId = function() return 4242; end
    ew.reset();
    ew.onPacket(actionPkt(MOB_A.id, MOB_A.ix, ew.CAT_ENGAGE), 600);
    ew.pump(nil, function() return nil; end);
    check('EDG39 a fresh engagement has not swung', ew.swungThisEngagement(), false);
    ew.onSwingPacket(swingPkt(9999, 1));      -- someone ELSE's swing
    ew.pump(nil, function() return nil; end);
    check('EDG40 a stranger swing is not mine', ew.swungThisEngagement(), false);
    ew.onSwingPacket(swingPkt(4242, 1));      -- MY swing
    ew.pump(nil, function() return nil; end);
    check('EDG41 my melee round arms the flag', ew.swungThisEngagement(), true);
    ew.onPacket(actionPkt(MOB_B.id, MOB_B.ix, ew.CAT_ENGAGE), 620);
    ew.pump(nil, function() return nil; end);
    check('EDG42 the next engage edge resets it', ew.swungThisEngagement(), false);
    ew.reset(true);
end)();

-- ---------------------------------------------------------------------------
-- BFT: the BST Helper's FIGHT switch (issue #139; POLL rewrite 2026-07-29 --
-- the Pup-Helper-proven shape after two failed edge-driven field rounds). The
-- decision is a PURE function -- poll state in, command decision out -- so
-- every rule is a headless check: the three modes, the module gates, the
-- positive-true act gates, the retry spacing + cap, the follow retarget, and
-- the disengage reset. Then the vitals-beat glue end to end, injected reads.
-- ---------------------------------------------------------------------------
;(function()
    -- api 2: the rule reaches its settings, the clock, the activity gate and the
    -- command door through the MODULE API, so one fake replaces the two
    -- package.loaded stubs this section used to need -- and the fake records what
    -- the rule actually issued.
    local ft = dofile('jobhelpers/bst/bst-helper/fight.lua');
    package.loaded['dlac\\jobhelpers\\bst\\bst-helper\\fight'] = ft;
    local S = fakeApi({ id = 'bst-helper', vals = { fight = 'attack' }, clock = 100 });
    ft.init(S);
    local vals, sent = S.vals, S.sent;
    check('BFT0 the rule rides the COMBAT beat, not the pet beat',
          S.subs['jobhelper:bst-helper:fight'] ~= nil, true);

    -- The armed baseline: acting, engaged, pet out and idle, a target, clean history.
    local function armed(t)
        local st = { mode = 'attack', active = true, engaged = true, hasPet = true,
                     petIdle = true, targetIndex = 0x2E1, now = 100 };
        for k, v in pairs(t or {}) do st[k] = v; end
        return st;
    end

    -- the act path + the positive-true gates
    check('BFT1 engaged + idle pet + target -> send', ft.pollDecide(armed()).act, true);
    check('BFT2 ...with the pet Fight command', ft.pollDecide(armed()).command, ft.COMMAND);
    check('BFT3 off mode never acts', ft.pollDecide(armed({ mode = 'off' })).reason, 'off');
    check('BFT4 inactive module never acts (reason carried)',
          ft.pollDecide(armed({ active = false, reason = 'job' })).reason, 'job');
    check('BFT5 not engaged -> quiet', ft.pollDecide(armed({ engaged = false })).reason, 'not-engaged');
    -- `{ k = nil }` is an EMPTY table constructor -- a nil override never
    -- reaches armed()'s pairs loop, so unreadable-state cases are built as
    -- explicit literal states instead.
    check('BFT6 unreadable engagement is NOT permission',
          ft.pollDecide({ mode = 'attack', active = true, hasPet = true,
                          petIdle = true, targetIndex = 0x2E1, now = 100 }).reason, 'not-engaged');
    check('BFT7 no pet -> quiet', ft.pollDecide(armed({ hasPet = false })).reason, 'no-pet');
    check('BFT8 no target -> quiet',
          ft.pollDecide({ mode = 'attack', active = true, engaged = true,
                          hasPet = true, petIdle = true, now = 100 }).reason, 'no-target');
    check('BFT9 unreadable pet state is NOT permission',
          ft.pollDecide({ mode = 'attack', active = true, engaged = true,
                          hasPet = true, targetIndex = 0x2E1, now = 100 }).reason, 'pet-state-unknown');

    -- pacing: the retry window and the cap, dying with the target
    check('BFT10 same target inside RETRY_S waits',
          ft.pollDecide(armed({ last = { target = 0x2E1, at = 99, tries = 1 } })).reason, 'waiting');
    check('BFT11 same target after the window retries',
          ft.pollDecide(armed({ last = { target = 0x2E1, at = 90, tries = 1 } })).act, true);
    check('BFT12 the cap goes quiet after MAX_TRIES',
          ft.pollDecide(armed({ last = { target = 0x2E1, at = 90, tries = 3 } })).reason, 'capped');
    check('BFT13 a DIFFERENT target starts clean past the cap',
          ft.pollDecide(armed({ targetIndex = 0x2E2,
                                last = { target = 0x2E1, at = 99, tries = 3 } })).act, true);

    -- the busy pet: attack stops, follow re-sends on a target change
    check('BFT14 attack: a fighting pet is left alone',
          ft.pollDecide(armed({ petIdle = false })).reason, 'pet-busy');
    check('BFT15 follow: a fighting pet re-sends when MY target changed',
          ft.pollDecide(armed({ mode = 'follow', petIdle = false, targetChanged = true })).act, true);
    check('BFT16 follow: same target keeps the pet where it is',
          ft.pollDecide(armed({ mode = 'follow', petIdle = false, targetChanged = false })).reason, 'pet-busy');
    check('BFT17 attack ignores the change signal',
          ft.pollDecide(armed({ petIdle = false, targetChanged = true })).reason, 'pet-busy');

    -- decision text stays honest
    check('BFT18 the capped reason names the command-wording suspicion',
          ft.decisionText({ act = false, reason = 'capped' }):find('capped', 1, true) ~= nil, true);
    check('BFT19 an act with a name reads as sent-at',
          ft.decisionText({ act = true, targetName = 'Nursery Nazuna' }),
          'sent your pet at Nursery Nazuna');

    -- --- the combat-beat glue end to end: a fed beat record, captured commands --
    -- `world` is the state the combat service would be publishing. `targetChanged`
    -- is now the SERVICE's answer (the retarget EDGE when one arrived, its own poll
    -- otherwise) rather than something this rule re-derives -- so it is a field on
    -- the record here, and `beat()` clears it afterwards because a change is a fact
    -- about ONE beat, not a state that persists.
    local world = { engaged = true, target = 0x2E1, changed = false, swung = false };
    local function beat(petRec)
        local d = ft.onBeat({ engaged = world.engaged, targetIndex = world.target,
                              targetName = 'Nursery Nazuna', targetChanged = world.changed,
                              swung = world.swung }, petRec);
        world.changed = false;
        return d;
    end
    local IDLE  = { present = true, status = 'Idle' };
    local BUSY  = { present = true, status = 'Engaged' };
    ft.resetIssues();

    local d = beat(IDLE);
    check('BFT20 beat 1: idle pet is sent at the target', #sent, 1);
    check('BFT21 ...and the Panel line names the mob', ft.decisionText(d), 'sent your pet at Nursery Nazuna');
    S.clock = S.clock + 0.4;
    beat(IDLE);
    check('BFT22 beat 2 inside the window: no second command', #sent, 1);
    S.clock = S.clock + 0.4;
    beat(BUSY);
    check('BFT23 the pet took: quiet', #sent, 1);
    check('BFT24 ...and says so', ft.lastDecision().reason, 'pet-busy');

    -- follow: rolling to the next mob re-sends a FIGHTING pet
    vals.fight = 'follow';
    S.clock = S.clock + 2.5;
    world.target, world.changed = 0x2E2, true;
    beat(BUSY);
    check('BFT25 follow: the target roll re-sends the pet', #sent, 2);
    -- attack mode ignores the roll
    vals.fight = 'attack';
    S.clock = S.clock + 2.5;
    world.target, world.changed = 0x2E3, true;
    beat(BUSY);
    check('BFT26 attack: the roll leaves a fighting pet alone', #sent, 2);

    -- the retry-until-taken loop caps loudly-in-panel, silently in chat
    vals.fight = 'attack';
    world.target = 0x2E4;
    ft.resetIssues();
    for i = 1, 6 do
        S.clock = S.clock + 2.1;
        beat(IDLE);
    end
    check('BFT27 a command that never takes stops at MAX_TRIES', #sent, 2 + ft.MAX_TRIES);
    check('BFT28 ...and the Panel reads capped', ft.lastDecision().reason, 'capped');

    -- disengage resets the bookkeeping; re-engaging starts clean
    world.engaged = false;
    S.clock = S.clock + 0.4;
    beat(IDLE);
    check('BFT29 disengaged: quiet', ft.lastDecision().reason, 'not-engaged');
    world.engaged = true;
    S.clock = S.clock + 0.4;
    beat(IDLE);
    check('BFT30 re-engaging the same mob starts a fresh engagement', #sent, 3 + ft.MAX_TRIES);

    -- --- Respect Heel: the player's option (Henrik's ruling 2026-07-29) ------
    -- Pure core first: took + same target + option ON -> heeled; OFF -> resend;
    -- a different target clears the latch either way.
    check('BFT31 heeled: a TAKEN send is never repeated (option on)',
          ft.pollDecide(armed({ heelRespect = true,
                                last = { target = 0x2E1, at = 90, tries = 1, took = true } })).reason, 'heeled');
    check('BFT32 option off: an idle pet is re-sent past the latch',
          ft.pollDecide(armed({ heelRespect = false,
                                last = { target = 0x2E1, at = 90, tries = 1, took = true } })).act, true);
    check('BFT33 the latch dies with the target',
          ft.pollDecide(armed({ heelRespect = true, targetIndex = 0x2E9,
                                last = { target = 0x2E1, at = 90, tries = 1, took = true } })).act, true);

    -- Glue: send -> the pet takes (latch) -> Heel (idle again) -> respected;
    -- option off -> re-sent. fightHeel is ABSENT from fakeCfg, so the first
    -- pass also proves the default reads ON.
    local base = 3 + ft.MAX_TRIES;
    ft.resetIssues();
    world.target = 0x2F0;
    S.clock = S.clock + 5;
    beat(IDLE);
    check('BFT34 fresh mob: sent', #sent, base + 1);
    S.clock = S.clock + 0.4;
    beat(BUSY);            -- the send TOOK: the latch arms
    S.clock = S.clock + 2.5;
    beat(IDLE);            -- the player heeled
    check('BFT35 Heel respected by default: no re-send', #sent, base + 1);
    check('BFT36 ...and the Panel says so', ft.lastDecision().reason, 'heeled');
    vals.fightHeel = false;
    S.clock = S.clock + 2.5;
    beat(IDLE);
    check('BFT37 option off: the idle pet is re-sent', #sent, base + 2);
    vals.fightHeel = nil;

    -- --- "Send when": drawn (default) vs first swing (Henrik's option) -------
    check('BFT38 swing mode holds before the first swing',
          ft.pollDecide(armed({ needSwing = true })).reason, 'no-swing-yet');
    check('BFT39 ...and releases once it swung',
          ft.pollDecide(armed({ needSwing = true, swung = true })).act, true);
    world.swung = false;
    vals.fightWhen = 'swing';
    ft.resetIssues();
    world.target = 0x2F5;
    S.clock = S.clock + 5;
    beat(IDLE);
    check('BFT40 glue: engaged but unswung sends nothing', #sent, base + 2);
    check('BFT41 ...and the Panel says why', ft.lastDecision().reason, 'no-swing-yet');
    world.swung = true;
    S.clock = S.clock + 0.4;
    beat(IDLE);
    check('BFT42 the first swing releases the send', #sent, base + 3);
    vals.fightWhen = nil;
    world.swung = false;

    -- --- the beat's OWN answers, which the rule no longer re-derives ----------
    -- A rule that cannot read the world must not command a pet: an unreadable
    -- engagement and an unreadable pet each hold, positively.
    ft.resetIssues();
    S.clock = S.clock + 5;
    world.target = 0x300;
    ft.onBeat({ targetIndex = world.target }, IDLE);       -- engaged unreadable
    check('BFT43 an unreadable engagement is not permission',
          ft.lastDecision().reason, 'not-engaged');
    ft.onBeat({ engaged = true, targetIndex = world.target }, { present = true });
    check('BFT44 a pet whose STATE could not be read is not permission either',
          ft.lastDecision().reason, 'pet-state-unknown');
    ft.onBeat({ engaged = true, targetIndex = world.target }, nil);
    check('BFT45 ...and no pet record at all reads as no pet',
          ft.lastDecision().reason, 'no-pet');

    ft.resetIssues();
    package.loaded['dlac\\jobhelpers\\bst\\bst-helper\\fight'] = nil;
end)();

-- ---------------------------------------------------------------------------
-- BRW: the BST Helper's REWARD rule (issue #140). The decision is a PURE
-- function -- vitals + state in, "request the sequence?" out -- so the
-- threshold, the retry lockout and every module gate are headless checks. Then
-- the store (the slider persisted per character) and the two requesters driven
-- end to end against fakes, which is where "identical refusal behavior to the
-- button" is actually PROVEN rather than asserted: both paths are compared
-- claim-for-claim and line-for-line.
-- AC1/AC2/AC3/AC4/AC5.
-- ---------------------------------------------------------------------------
;(function()
    -- api 2: the module DECLARES its settings and the framework stores them, so the
    -- store half of this section drives the REAL declaration (init.lua's `config`
    -- block) through the REAL store (feature\modcfg) -- where api 1 tested a
    -- per-module copy of the storage policy.
    local modcfg = dofile('feature/modcfg.lua');
    package.loaded['dlac\\feature\\modcfg'] = modcfg;
    local bstInit = dofile('jobhelpers/bst/bst-helper/init.lua');
    local SPEC    = bstInit.config;
    local rw = dofile('jobhelpers/bst/bst-helper/reward.lua');
    package.loaded['dlac\\jobhelpers\\bst\\bst-helper\\reward'] = rw;

    check('BRW0a the module declares its settings on the contract table', type(SPEC), 'table');
    check('BRW0b ...and the framework accepts the declaration', modcfg.validate(SPEC), true);
    check('BRW0c ...keeping the filename api 1 shipped, so settings survive the upgrade',
          modcfg.fileFor('bst-helper', SPEC), 'jobhelper-bst.lua');

    -- The armed baseline: rule on, threshold 50, module acting, nothing running,
    -- Reward off cooldown, no lockout live.
    local function armed(t)
        local st = { armed = true, threshold = 50, active = true, busy = false,
                     recastReady = true, now = 1000 };
        for k, v in pairs(t or {}) do st[k] = v; end
        return st;
    end
    local function pet(hpp) return { present = true, hpp = hpp, tp = 500, name = 'Courier Carrie' }; end

    -- --- the THRESHOLD: strictly below fires, at or above never does (AC1)
    check('BRW1 a pet below the threshold asks for Reward', rw.decide(pet(30), armed()).act, true);
    check('BRW2 ...and carries the HP% it decided on', rw.decide(pet(30), armed()).hpp, 30);
    check('BRW3 a pet EXACTLY at the threshold does not', rw.decide(pet(50), armed()).act, false);
    check('BRW4 ...for the honest reason', rw.decide(pet(50), armed()).reason, 'above');
    check('BRW5 a pet above the threshold does not', rw.decide(pet(80), armed()).act, false);
    check('BRW6 one point under IS under', rw.decide(pet(49), armed()).act, true);
    check('BRW7 a full pet never fires at the top of the band',
          rw.decide(pet(100), armed({ threshold = 99 })).act, false);
    check('BRW8 the threshold is the player\'s, not a constant',
          rw.decide(pet(70), armed({ threshold = 75 })).act, true);

    -- --- the rule switch and the module gates (AC4)
    check('BRW9 the rule off: nothing is ever asked for', rw.decide(pet(5), armed({ armed = false })).act, false);
    check('BRW10 ...for the obvious reason', rw.decide(pet(5), armed({ armed = false })).reason, 'off');
    for _, r in ipairs({ 'job', 'town', 'dead', 'zoning', 'off' }) do
        local d = rw.decide(pet(5), armed({ active = false, reason = r }));
        check('BRW11 the module gate holds it (' .. r .. ')', d.act == false and d.reason, r);
    end
    -- nil means UNREADABLE, so this state is built by hand (armed()'s pairs copy
    -- cannot express "this key is absent").
    check('BRW12 an UNREADABLE world is not permission to spend food',
          rw.decide(pet(5), { armed = true, threshold = 50, now = 1000 }).act, false);

    -- --- the pet gates: no pet, dead pet, unreadable HP
    check('BRW13 no pet: nothing to Reward', rw.decide({ present = false }, armed()).reason, 'no-pet');
    check('BRW14 an UNREADABLE pet is not permission either', rw.decide({}, armed()).reason, 'no-pet');
    check('BRW15 no vitals at all decides nothing', rw.decide(nil, armed()).reason, 'no-pet');
    check('BRW16 a present pet whose HP could not be read is never guessed at',
          rw.decide({ present = true }, armed()).reason, 'no-hp');

    -- --- the LOCKOUT (AC2): one attempt per window, whatever the bar does
    check('BRW17 an attempt 5s ago holds the next one',
          rw.decide(pet(10), armed({ lastAttemptAt = 995 })).reason, 'lockout');
    check('BRW18 ...and says how long is left',
          rw.decide(pet(10), armed({ lastAttemptAt = 995 })).retryIn, 25);
    check('BRW19 an attempt a whole window ago does not',
          rw.decide(pet(10), armed({ lastAttemptAt = 1000 - rw.LOCKOUT_S })).act, true);
    check('BRW20 a clock that went BACKWARDS accepts, never mutes for a window',
          rw.decide(pet(10), armed({ lastAttemptAt = 5000 })).act, true);
    check('BRW21 the window is the rule\'s, not a constant',
          rw.decide(pet(10), armed({ lastAttemptAt = 995, lockout = 2 })).act, true);
    -- and the lockout never overrides the more specific truth above it
    check('BRW22 a pet ABOVE the threshold reports that, not the lockout',
          rw.decide(pet(80), armed({ lastAttemptAt = 995 })).reason, 'above');

    -- --- busy + recast: real holds, but nothing was ATTEMPTED, so neither is a
    -- refusal and neither arms the lockout.
    check('BRW23 a sequence already running holds it', rw.decide(pet(10), armed({ busy = true })).reason, 'busy');
    check('BRW24 Reward on cooldown holds it', rw.decide(pet(10), armed({ recastReady = false })).reason, 'recast');
    check('BRW25 an UNKNOWN recast reads READY (the courtesy gate)',
          rw.decide(pet(10), armed({ recastReady = nil })).act, true);

    -- --- the threshold clamp
    check('BRW26 an absent threshold is the default', rw.clampThreshold(nil), rw.DEFAULT_THRESHOLD);
    check('BRW27 the default is the PRD\'s 50', rw.DEFAULT_THRESHOLD, 50);
    check('BRW28 0 clamps into the band (the switch is the off switch)', rw.clampThreshold(0), rw.MIN_THRESHOLD);
    check('BRW29 100 clamps into the band (a full pet needs no Reward)', rw.clampThreshold(100), rw.MAX_THRESHOLD);
    check('BRW30 a fractional slider value lands on a whole percent', rw.clampThreshold(62.7), 63);
    check('BRW31 a numeric string is read, not dropped', rw.clampThreshold('75'), 75);
    check('BRW32 junk is the default, never 0', rw.clampThreshold('half'), 50);

    -- --- the decision reads as a human line (the Panel's report; never chat)
    check('BRW33 an act reads as a sentence',
          rw.decisionText(rw.decide(pet(30), armed())):find('30', 1, true) ~= nil, true);
    check('BRW34 a hold names the gate',
          rw.decisionText(rw.decide(pet(5), armed({ active = false, reason = 'town' }))), 'in town');
    check('BRW35 a lockout counts down',
          rw.decisionText(rw.decide(pet(10), armed({ lastAttemptAt = 995 }))):find('25', 1, true) ~= nil, true);
    check('BRW36 nothing yet reads as nothing yet', rw.decisionText(nil), 'nothing yet');

    -- --- the STORE: the slider persisted per character (AC4)
    local FILES = {};
    local realOpen, realLoadfile = io.open, loadfile;

    -- The rule reaches its store through the module API, so the harness is a fake
    -- API table with a real store hung on it. `S` doubles as the recorder for
    -- everything the rule DOES -- see fakeApi.
    local CHARDIR = nil;                            -- nil == pre-login
    local S = fakeApi({ id = 'bst-helper' });
    S.cfg = modcfg.open('bst-helper', SPEC, function() return CHARDIR; end);
    rw.init(S);

    check('BRW37 pre-login the rule reads its default (OFF)', rw.armed(), false);
    check('BRW38 ...and the threshold its default', rw.threshold(), 50);
    check('BRW39 ...and no Reward set', rw.setName(), nil);
    check('BRW39a pre-login a WRITE is refused rather than cached', rw.setArmed(true), false);
    check('BRW39b ...and the read still answers the default', rw.armed(), false);

    CHARDIR = 'BRWDIR\\';
    io.open = function(path, mode)
        if type(path) == 'string' and path:find('BRWDIR', 1, true) then
            if (mode or 'r'):find('w') then
                FILES[path] = '';      -- 'wb' TRUNCATES; this store is rewritten every save
                return { write = function(_, s) FILES[path] = (FILES[path] or '') .. s; end, close = function() end };
            end
            return nil;
        end
        return realOpen(path, mode);
    end
    loadfile = function(path)
        if type(path) == 'string' and path:find('BRWDIR', 1, true) then
            local s = FILES[path]; if s == nil then return nil; end return (loadstring or load)(s);
        end
        return realLoadfile(path);
    end
    local CFGFILE = 'BRWDIR\\jobhelper-bst.lua';

    check('BRW40 an absent config file reads the defaults', rw.armed() == false and rw.threshold(), 50);
    check('BRW41 the file is not written until something changes', FILES[CFGFILE], nil);
    check('BRW42 moving the slider persists it', rw.setThreshold(35), true);
    check('BRW43 ...and it reads back', rw.threshold(), 35);
    check('BRW44 ...into the module\'s OWN per-character file', FILES[CFGFILE] ~= nil, true);
    check('BRW45 an out-of-band write is clamped on the way IN, never stored raw',
          rw.setThreshold(300) and rw.threshold(), rw.MAX_THRESHOLD);
    rw.setThreshold(35);
    check('BRW46 arming the rule persists it', rw.setArmed(true) and rw.armed(), true);
    check('BRW47 ...and disarming it persists too', rw.setArmed(false) and rw.armed(), false);
    check('BRW48 the Reward set persists (the rule has no Panel to read it from)',
          rw.setSetName('Reward') and rw.setName(), 'Reward');
    check('BRW49 ...and "None" clears it', rw.setSetName('None') and rw.setName(), nil);
    check('BRW50 the file stays format-versioned',
          (modcfg.normalize(SPEC, (loadstring or load)(FILES[CFGFILE])()) or {}).fmt, 1);
    check('BRW51 a wrong-typed threshold on disk falls back to the default',
          modcfg.normalize(SPEC, { rewardThreshold = 'fifty' }).rewardThreshold, nil);
    check('BRW52 a stored FALSE survives normalization (it is not "absent")',
          modcfg.normalize(SPEC, { rewardArmed = false }).rewardArmed, false);
    check('BRW53 the Fight setting is untouched by the Reward rows',
          modcfg.normalize(SPEC, { fight = 'follow', rewardArmed = true }).fight, 'follow');
    check('BRW53a a key from a NEWER dlac cannot survive into this one',
          modcfg.normalize(SPEC, { rewardArmed = true, futureKey = 'x' }).futureKey, nil);
    -- ...and a fresh read off the written file survives a character switch
    S.cfg.forget();
    check('BRW54 the slider survives a reload (read back off the file)', rw.threshold(), 35);

    -- --- END TO END: the two requesters, driven against the fake module API.
    -- api 1 needed six package.loaded stubs here (jobhelpers, actionseq, petfood,
    -- profilesets, dispatch, recast) and the rule found them by hardcoded path. Now
    -- everything the rule can ASK or DO arrives through S, so ONE fake covers the
    -- whole lifecycle -- and a rule that passes is provably calling the real surface.
    local saved = { pv = package.loaded['dlac\\feature\\petvitals'] };
    local requests, lines = {}, {};
    local seqBusy, rewardDown = false, false;
    local acting  = { active = true };
    local foodPick = { ok = true, name = 'Pet Food Delta', key = 'Delta' };

    -- Each door is a closure over a LOCAL, so the checks below can retarget any of
    -- them (`requests = {}`, `foodPick = ...`) and the module still lands in the
    -- current one -- Lua closures capture the variable, not its value.
    S.me.acting     = function() return acting; end
    S.act.busy      = function() return seqBusy; end
    S.act.request   = function(r) requests[#requests + 1] = r; return { ok = true }; end
    S.pet.food      = function() return foodPick; end
    S.ability.ready = function()
        if rewardDown then return false, 42; end
        return true, nil;
    end
    S.sets.names    = function() return { 'Idle', 'Reward' }; end
    S.sets.slotsOf  = function(n)
        if n == 'Reward' then return { Head = 'Beast Helm', Body = 'Beast Jackcoat' }; end
        return {};
    end
    rw._emit = function(l) lines[#lines + 1] = tostring(l); end

    -- the BUTTON path
    rw.setSetName('Reward');
    local bres = rw.request();
    check('BRW55 the button opens one sequence', bres.ok == true and #requests, 1);
    local btnReq = requests[1];
    check('BRW56 ...claiming the food in Ammo', btnReq.claim.Ammo, 'Pet Food Delta');
    check('BRW57 ...with the chosen Reward set overlaid', btnReq.claim.Head, 'Beast Helm');
    check('BRW58 ...verifying the CONSUMED slot alone (the accepted ruling)',
          btnReq.need.Ammo == 'Pet Food Delta' and btnReq.need.Head, nil);
    check('BRW59 ...firing the Reward command', btnReq.command, rw.COMMAND);
    check('BRW60 ...and leaving module + order to the framework, which cannot be faked'
          .. ' by the module', btnReq.module == nil and btnReq.order, nil);
    check('BRW61 success is SILENT', #lines, 0);

    -- the AUTOMATIC path: the same request, byte for byte (AC3 -- "identical",
    -- proven rather than asserted).
    requests = {};
    rw.resetLockout();
    rw.setArmed(true);
    rw.setThreshold(50);
    local d = rw.onVitals({ present = true, hpp = 30, name = 'Courier Carrie', at = 2000 });
    check('BRW62 a pet under the threshold opens the sequence on its own', d.act, true);
    check('BRW63 ...exactly one', #requests, 1);
    local autoReq = requests[1];
    check('BRW64 ...the SAME claim the button builds', autoReq.claim.Ammo == btnReq.claim.Ammo
          and autoReq.claim.Head == btnReq.claim.Head, true);
    check('BRW65 ...the SAME needed slot', autoReq.need.Ammo, btnReq.need.Ammo);
    check('BRW66 ...the SAME command', autoReq.command, btnReq.command);
    check('BRW67 ...and it too is silent', #lines, 0);

    -- AC2: a SUSTAINED sub-threshold pet is one attempt per window, not a stream
    for i = 1, 20 do rw.onVitals({ present = true, hpp = 12, at = 2000 + i }); end
    check('BRW68 twenty more beats under the threshold add no commands', #requests, 1);
    check('BRW69 ...and no chat', #lines, 0);
    check('BRW70 ...the beats say why', rw.lastDecision().reason, 'lockout');
    rw.onVitals({ present = true, hpp = 12, at = 2000 + rw.LOCKOUT_S });
    check('BRW71 once the window elapses it tries again, once', #requests, 2);

    -- a pet ABOVE the threshold never fires, however many beats go by
    requests = {};
    rw.resetLockout();
    for i = 1, 10 do rw.onVitals({ present = true, hpp = 90, at = 3000 + i }); end
    check('BRW72 a healthy pet is never Rewarded', #requests, 0);
    check('BRW73 ...and the rule says so', rw.lastDecision().reason, 'above');

    -- AC3: no food carried -- the button's own line, and then ONCE PER ZONE.
    --
    -- (Henrik, 2026-07-30, off his own probe log, where the line turned up
    -- mid-fight while he was proving something else.) The LOCKOUT is the wrong
    -- budget for this one refusal: it is sized for "how often may this rule
    -- speak", and every other refusal it covers is something the world may fix
    -- on its own -- a cooldown ends, a pet heals. An empty bag does not. It is
    -- fixed by shopping, which you cannot usefully do in the middle of the fight
    -- that is printing it, so one line per window is thirty reminders of one
    -- thing you already know. A zone change is the moment it might have become
    -- false.
    requests, lines = {}, {};
    rw.resetLockout();
    local zoneNow = 100;
    S.player.zone = function() return zoneNow; end
    foodPick = { ok = false, reason = 'none-carried' };
    rw.request();
    local buttonLine = lines[1];
    check('BRW74 the button refuses loudly when the bags are empty',
          (buttonLine or ''):find('not carrying', 1, true) ~= nil, true);
    check('BRW75 ...and opens no sequence', #requests, 0);

    lines = {};
    rw.resetLockout();                      -- a job change re-arms it too
    for i = 1, 20 do rw.onVitals({ present = true, hpp = 10, at = 4000 + i }); end
    check('BRW76 the rule refuses with the IDENTICAL line', lines[1], buttonLine);
    check('BRW77 ...exactly once, however many beats go by', #lines, 1);
    check('BRW78 ...and still opens no sequence', #requests, 0);
    rw.onVitals({ present = true, hpp = 10, at = 4000 + rw.LOCKOUT_S });
    check('BRW78a the NEXT lockout window does not repeat it -- thirty seconds is not\n'
          .. '      long enough for the answer to have changed', #lines, 1);
    zoneNow = 200;
    rw.onVitals({ present = true, hpp = 10, at = 4000 + 2 * rw.LOCKOUT_S });
    check('BRW79 ZONING re-arms it -- you might have shopped', #lines, 2);
    rw.onVitals({ present = true, hpp = 10, at = 4000 + 3 * rw.LOCKOUT_S });
    check('BRW79a ...and then it is quiet in the new zone too', #lines, 2);

    -- Carrying food again re-arms the line where you stand: the next time you run
    -- out is genuinely new news.
    foodPick = { ok = true, name = 'Pet Food Delta', key = 'Delta' };
    rw.request();
    foodPick = { ok = false, reason = 'none-carried' };
    rw.onVitals({ present = true, hpp = 10, at = 4000 + 4 * rw.LOCKOUT_S });
    check('BRW79b running OUT again says so, in the same zone', #lines, 3);

    -- An unreadable zone is a value like any other, so a headless / pre-login
    -- world gets one line and silence -- never one per window forever.
    lines = {};
    rw.resetLockout();
    zoneNow = nil;
    rw.onVitals({ present = true, hpp = 10, at = 6000 });
    rw.onVitals({ present = true, hpp = 10, at = 6000 + rw.LOCKOUT_S });
    check('BRW79c an unknown zone still speaks exactly once', #lines, 1);
    zoneNow = 100;

    requests, lines = {}, {};
    rw.resetLockout();
    foodPick = { ok = true, name = 'Pet Food Delta', key = 'Delta' };

    -- AC3: Reward on cooldown -- the button GRAYS OUT and says nothing, so the
    -- rule holds and says nothing either. It is not an attempt, so no lockout.
    requests, lines = {}, {};
    rw.resetLockout();
    rewardDown = true;
    for i = 1, 10 do rw.onVitals({ present = true, hpp = 10, at = 5000 + i }); end
    check('BRW80 Reward on cooldown opens no sequence', #requests, 0);
    check('BRW81 ...and says NOTHING (the greyed button says nothing either)', #lines, 0);
    check('BRW82 ...naming the hold for the Panel', rw.lastDecision().reason, 'recast');
    check('BRW83 ...and it did not burn the lockout', rw.lockedUntil(), nil);
    rewardDown = false;
    rw.onVitals({ present = true, hpp = 10, at = 5100 });
    check('BRW84 the moment the recast is back, the held Reward goes', #requests, 1);

    -- AC3: a senior claimant holding the slot. The sequencer owns that refusal,
    -- and BOTH requesters hand it the same request -- so "identical" is the same
    -- code path, not two agreeing implementations. Driven through the REAL
    -- sequencer here to prove the refusal actually lands.
    local realSeq = dofile('feature/actionseq.lua');
    local fakeRequest = S.act.request;
    -- Point the API's act door at the REAL sequencer, filling module + order the way
    -- feature\modapi fills them -- so the refusal is proven through the real
    -- lifecycle, not against a stub that agrees with us.
    S.act.request = function(r)
        r.module, r.order = 'bst-helper', 1;
        return realSeq.request(r);
    end
    local emits = {};
    local io2 = { worn = function() return nil; end,
                  blocker = function(slot) if slot == 'Ammo' then return 'Locks'; end return nil; end,
                  fire = function() emits[#emits + 1] = 'FIRED'; end,
                  release = function() end,
                  emit = function(l) emits[#emits + 1] = l; end };
    realSeq.reset();
    rw.resetLockout();
    rw.onVitals({ present = true, hpp = 10, at = 6000 });
    realSeq.tick(0, io2);
    check('BRW85 a senior holder on the food slot refuses, and nothing fires',
          (emits[1] or ''):find('held by Locks', 1, true) ~= nil, true);
    check('BRW86 ...never-fire-bare holds for the automatic requester too', #emits, 1);
    realSeq.reset();
    S.act.request = fakeRequest;

    -- the module gates, end to end: a held module issues nothing and says nothing
    requests, lines = {}, {};
    for _, r in ipairs({ 'job', 'town', 'dead', 'zoning', 'off' }) do
        rw.resetLockout();
        acting = { active = false, reason = r };
        rw.onVitals({ present = true, hpp = 5, at = 7000 });
        check('BRW87 the module gate stops the rule dead (' .. r .. ')',
              #requests == 0 and rw.lastDecision().reason, r);
    end
    check('BRW88 ...and none of them said a word', #lines, 0);

    -- the rule DISARMED: the beat still runs, nothing ever happens
    acting = { active = true };
    rw.resetLockout();
    rw.setArmed(false);
    for i = 1, 10 do rw.onVitals({ present = true, hpp = 5, at = 8000 + i }); end
    check('BRW89 a disarmed rule never acts', #requests, 0);
    check('BRW90 ...and the default IS disarmed (a helper never arms itself)',
          SPEC.defaults.rewardArmed, false);

    -- --- the vitals service and the rule wired together: a real subscription
    -- through the API's own door, so the namespaced key is proven too.
    local pvMod = dofile('feature/petvitals.lua');
    package.loaded['dlac\\feature\\petvitals'] = pvMod;
    pvMod.reset(true);
    S.pet.subscribe = function(n, cb) return pvMod.subscribe(S.who(n), cb); end
    requests = {};
    rw.resetLockout();
    rw.setArmed(true);
    check('BRW91 the rule subscribes to the pet vitals service', rw.init(S), true);
    check('BRW92 ...as one named consumer', pvMod.subscriberCount(), 1);
    check('BRW92a ...under a key the FRAMEWORK namespaced, not the module',
          S.who('reward'), 'jobhelper:bst-helper:reward');
    local PETHP = 12;
    local READS = { pet = function() return { HPP = PETHP, TP = 100, Name = 'Courier Carrie' }; end };
    pvMod.pump(9000, READS);
    check('BRW93 one vitals beat under the threshold ends as ONE sequence', #requests, 1);
    for i = 1, rw.LOCKOUT_S - 1 do pvMod.pump(9000 + i, READS); end
    check('BRW94 a whole lockout window of beats adds nothing', #requests, 1);
    PETHP = 95;
    pvMod.pump(9100, READS);
    check('BRW95 a healed pet stops the rule cold', #requests, 1);
    -- and a dead pet is no pet, so the rule never fires at a corpse
    PETHP = 0;
    rw.resetLockout();
    pvMod.pump(9200, READS);
    check('BRW96 a DEAD pet is no pet: nothing is asked for', #requests, 1);
    check('BRW97 ...and the rule says so', rw.lastDecision().reason, 'no-pet');

    pvMod.reset(true);
    io.open, loadfile = realOpen, realLoadfile;
    S.cfg.forget();
    package.loaded['dlac\\feature\\petvitals'] = saved.pv;
    package.loaded['dlac\\jobhelpers\\bst\\bst-helper\\reward'] = nil;
    package.loaded['dlac\\feature\\modcfg'] = nil;
    package.loaded['dlac\\lib\\statefile'] = nil;
end)();

-- ---------------------------------------------------------------------------
-- KB: THE KEYBIND REGISTRY (2026-07-30). "Who holds this key, and with what?"
-- Before it existed dlac issued binds from two places that could not see each
-- other, and nothing ever RELEASED one -- so a mode from the job you left kept
-- its key for the session. Henrik's ruling: name the holder and block the
-- second claim. The io seam is injected, so every bind and unbind is counted
-- without a client.
-- ---------------------------------------------------------------------------
;(function()
    local kb = dofile('feature/keybinds.lua');
    local bound, unbound, said = {}, {}, {};
    kb.io.bind   = function(k, c) bound[#bound + 1] = k .. ' ' .. c; end;
    kb.io.unbind = function(k) unbound[#unbound + 1] = k; end;
    kb.say       = function(l) said[#said + 1] = l; end;
    kb.forget();

    check('KB1 a key is normalised for comparison, not for issuing', kb.normalize('  ^F3 '), '^f3');
    check('KB2 nothing holds a free key', kb.holder('^f3'), nil);

    check('KB3 a free key is claimed', (kb.register('mode:weapon', '^F3', '/dl mode Weapon', 'Mode: Weapon')), true);
    check('KB4 ...and issued exactly as the player typed it', bound[1], '^F3 /dl mode Weapon');
    check('KB5 ...and the registry can name the holder', kb.holder('^f3').label, 'Mode: Weapon');
    check('KB6 ...case-insensitively, because it is one physical key',
          kb.holder('^F3').owner, 'mode:weapon');

    bound = {};
    check('KB7 re-registering the SAME key and command changes nothing',
          select(2, kb.register('mode:weapon', '^F3', '/dl mode Weapon', 'Mode: Weapon')).unchanged, true);
    check('KB8 ...and issues no /bind (the field-reported bind storm)', #bound, 0);

    local ok2, info2 = kb.register('jobhelper:bst-helper:summon', '^f3', '/dl jh bst-helper summon', 'BST: Summon');
    check('KB9 a SECOND owner is refused, never silently given the key', ok2, false);
    check('KB10 ...and told who has it', info2.taken.label, 'Mode: Weapon');
    check('KB11 ...loudly, once', #said, 1);
    check('KB12 ...and the holder keeps it', kb.holder('^f3').owner, 'mode:weapon');
    check('KB13 ...and nothing was issued', #bound, 0);
    kb.register('jobhelper:bst-helper:summon', '^f3', '/dl jh bst-helper summon', 'BST: Summon');
    check('KB14 a repeated refusal does not repeat the line', #said, 1);

    bound, unbound = {}, {};
    check('KB15 an owner MOVING its key releases the old one',
          kb.register('mode:weapon', '!q', '/dl mode Weapon', 'Mode: Weapon') and unbound[1], '^F3');
    check('KB16 ...and binds the new', bound[1], '!q /dl mode Weapon');
    check('KB17 ...leaving the old key free for somebody else', kb.holder('^f3'), nil);

    check('KB18 an owner holds at most one key', kb.heldBy('mode:weapon').raw, '!q');
    check('KB19 releasing unbinds it', kb.release('mode:weapon') and kb.holder('!q'), nil);
    check('KB20 ...and releasing nothing is not an error', kb.release('mode:weapon'), false);

    -- --- syncGroup: the whole per-job group, diffed
    kb.forget(); bound, unbound, said = {}, {}, {};
    local GROUP = {
        { owner = 'mode:dt',     key = 'F9',  command = '/dl mode DT',     label = 'Mode: DT' },
        { owner = 'mode:weapon', key = '^F3', command = '/dl mode Weapon', label = 'Mode: Weapon' },
    };
    local r1 = kb.syncGroup('mode:', GROUP);
    check('KB21 a fresh group binds every member', r1.bound, 2);
    check('KB22 ...and releases nothing', r1.released, 0);
    bound, unbound = {}, {};
    local r2 = kb.syncGroup('mode:', GROUP);
    check('KB23 the same group again is entirely unchanged', r2.unchanged, 2);
    check('KB24 ...issuing nothing at all', #bound + #unbound, 0);

    -- the job change: a different file, a different set of modes
    local NEXTJOB = { { owner = 'mode:sic', key = 'F9', command = '/dl mode Sic', label = 'Mode: Sic' } };
    local r3 = kb.syncGroup('mode:', NEXTJOB);
    check('KB25 a job change releases the modes that are gone', r3.released, 2);
    check('KB26 ...and binds the ones that arrived', r3.bound, 1);
    check('KB27 ...so a key the last job held is free again', kb.holder('^f3'), nil);
    check('KB28 ...and one it kept can be re-taken by the new job\'s mode',
          kb.holder('f9').owner, 'mode:sic');

    -- a group never touches another group's keys
    kb.register('dlac:ui', '^k', '/dl ui', 'dlac window');
    kb.syncGroup('jobhelper:', {
        { owner = 'jobhelper:bst-helper:summon', key = '^s', command = '/dl jh bst-helper summon',
          label = 'BST Helper: Summon now' },
    });
    check('KB29 syncing one group leaves the others alone',
          kb.holder('^k').owner .. '/' .. kb.holder('f9').owner, 'dlac:ui/mode:sic');
    check('KB30 ...and its own member is in', kb.holder('^s').label, 'BST Helper: Summon now');
    check('KB31 the whole board is readable, sorted', (function()
        local rows, keys = kb.list(), {};
        for _, r in ipairs(rows) do keys[#keys + 1] = r.key; end
        return table.concat(keys, ',');
    end)(), '^k,^s,f9');

    -- a refused member of a group does not take the group down
    said = {};
    local r4 = kb.syncGroup('jobhelper:', {
        { owner = 'jobhelper:bst-helper:summon', key = '^k', command = '/dl jh bst-helper summon',
          label = 'BST Helper: Summon now' },
    });
    check('KB32 a member reaching for a taken key is refused', #r4.refused, 1);
    check('KB33 ...named in the result', r4.refused[1].owner, 'jobhelper:bst-helper:summon');
    check('KB34 ...and the real holder still has it', kb.holder('^k').owner, 'dlac:ui');
    check('KB34b ...and the refused owner KEEPS the key it already had -- a move that\n'
          .. '       cannot land must not cost you the bind you were using',
          kb.holder('^s').owner, 'jobhelper:bst-helper:summon');

    unbound = {};
    kb.releaseAll();
    check('KB35 releasing everything unbinds every key', #unbound, 3);
    check('KB36 ...and empties the board', kb.count(), 0);

    -- --- bad shapes never throw
    check('KB37 a nameless owner is refused', kb.register(nil, '^k', '/dl ui'), false);
    check('KB38 an empty key is refused', kb.register('x', '   ', '/dl ui'), false);
    check('KB39 a commandless bind is refused', kb.register('x', '^k', ''), false);
    check('KB40 ...and none of them bound anything', kb.count(), 0);
end)();

-- ---------------------------------------------------------------------------
-- JHC: JOB-HELPER COMMANDS + their framework-installed keybinds (2026-07-30).
-- `/dl jh <module> <action>` is the one door for a module's named actions, and
-- the thing a key is bound to. The module never touches the registry: it
-- declares which of its OWN config keys holds the bind and the framework
-- installs the group, job-scoped.
-- ---------------------------------------------------------------------------
;(function()
    local jh = dofile('feature/jobhelpers.lua');
    local kb = dofile('feature/keybinds.lua');
    package.loaded['dlac\\feature\\keybinds'] = kb;
    kb.forget();
    kb.io.bind, kb.io.unbind, kb.say = function() end, function() end, function() end;

    local ran, lines = {}, {};
    jh._say = function(l) lines[#lines + 1] = l; end;

    local MOD = {
        api = jh.API, label = 'BST Helper', jobs = { 'BST' },
        panel = function() end,
        config = { file = 'x.lua', keys = { summonKey = 'string', n = 'number' } },
        commands = {
            summon = { label = 'Summon now', key = 'summonKey',
                       run = function(S, args) ran[#ran + 1] = args or true; return true; end },
        },
    };
    check('JHC1 a commands block is accepted', (jh._validate('bst-helper', MOD) ~= nil), true);

    local function bad(mut)
        local m = {};
        for k, v in pairs(MOD) do m[k] = v; end
        mut(m);
        return select(2, jh._validate('bst-helper', m));
    end
    check('JHC2 a command with no run function is refused',
          bad(function(m) m.commands = { go = { label = 'Go' } }; end):find('no run function', 1, true) ~= nil, true);
    check('JHC3 a command binding through an UNDECLARED config key is refused',
          bad(function(m) m.commands = { go = { run = function() end, key = 'nope' } }; end)
              :find('not a declared string config key', 1, true) ~= nil, true);
    check('JHC4 ...or through one that is not a string key',
          bad(function(m) m.commands = { go = { run = function() end, key = 'n' } }; end)
              :find('not a declared string config key', 1, true) ~= nil, true);
    check('JHC5 a command name with whitespace is refused',
          bad(function(m) m.commands = { ['a b'] = { run = function() end } }; end)
              :find('whitespace', 1, true) ~= nil, true);

    -- a loaded registry, hand-built the way the loader leaves it
    local vals = {};
    local rec = { id = 'bst-helper', job = 'bst', label = 'BST Helper', jobs = { 'BST' },
                  mod = MOD, S = { fake = true },
                  cfg = { get = function(k) return vals[k]; end,
                          set = function(k, v) vals[k] = v; return true; end } };
    jh.modules = { rec };
    gData = { GetPlayer = function() return { MainJob = 'BST' }; end };

    check('JHC6 the module\'s actions are listed, sorted', table.concat(jh.actionNames('bst-helper'), ','), 'summon');
    check('JHC7 running one calls it with the module\'s OWN api table',
          jh.runCommand('bst-helper', 'summon') and #ran, 1);
    lines = {};
    check('JHC8 an unknown action refuses', jh.runCommand('bst-helper', 'nope'), false);
    check('JHC9 ...and says what the module DOES have', lines[1]:find('summon', 1, true) ~= nil, true);
    lines = {};
    check('JHC10 an unknown module refuses', jh.runCommand('nope', 'summon'), false);
    check('JHC11 ...loudly', #lines, 1);

    lines = {};
    gData = { GetPlayer = function() return { MainJob = 'WAR' }; end };
    check('JHC12 the wrong job refuses -- a BST helper does nothing on WAR',
          jh.runCommand('bst-helper', 'summon'), false);
    check('JHC13 ...naming the job it is for', lines[1]:find('BST', 1, true) ~= nil, true);

    -- --- the binds the framework installs for it
    check('JHC14 no key configured, nothing to bind', #jh.bindEntries(), 0);
    vals.summonKey = '^F3';
    check('JHC15 the wrong job wants no bind either', #jh.bindEntries(), 0);
    gData = { GetPlayer = function() return { MainJob = 'BST' }; end };
    local ents = jh.bindEntries();
    check('JHC16 on its job, the key is wanted', #ents, 1);
    check('JHC17 ...owned by the FRAMEWORK\'s id, not one the module chose',
          ents[1].owner, 'jobhelper:bst-helper:summon');
    check('JHC18 ...bound to the one command door', ents[1].command, '/dl jh bst-helper summon');
    check('JHC19 ...and labelled for a human', ents[1].label, 'BST Helper: Summon now');

    jh.pumpBinds(1000);
    check('JHC20 the beat installs it', kb.holder('^f3').owner, 'jobhelper:bst-helper:summon');
    jh.pumpBinds(1000.2);
    check('JHC21 ...and is throttled between beats', kb.holder('^f3') ~= nil, true);
    gData = { GetPlayer = function() return { MainJob = 'WAR' }; end };
    jh.pumpBinds(1002);
    check('JHC22 changing job hands the key back', kb.holder('^f3'), nil);
    gData = { GetPlayer = function() return { MainJob = 'BST' }; end };
    jh.pumpBinds(1004);
    check('JHC23 ...and changing back takes it again', kb.holder('^f3').owner,
          'jobhelper:bst-helper:summon');

    -- The pill, without a character on disk: the store is what setEnabled writes
    -- to and there is none here, so the PREDICATE is stubbed instead -- what this
    -- check is about is bindEntries consulting it at all.
    local realEnabled = jh.isEnabled;
    jh.isEnabled = function() return false; end;
    jh.pumpBinds(1006);
    check('JHC24 the row pill silences the key too', kb.holder('^f3'), nil);
    jh.isEnabled = realEnabled;

    jh.modules = {};
    kb.forget();
    package.loaded['dlac\\feature\\keybinds'] = nil;
    gData = nil;
end)();

-- ---------------------------------------------------------------------------
-- FW: what you last ate (feature\foodwatch).
--
-- The module's whole claim is that it can tell FOOD from any other usable item
-- without shipping a food list: an outgoing item use says WHICH item, and the
-- FOOD effect moving right afterwards says it was food. Both halves of that are
-- pinned here, including the one a presence-only reading would get wrong --
-- eating over a live food, where the icon never flickers and only the EXPIRY
-- moves.
--
-- charDir is stubbed to nil for the whole section, so path() is nil, load() is a
-- no-op and save() writes nothing: these tests touch no disk. The live reads go
-- in as a table pump CALLS, which is the same table shape the live path builds
-- (the combat.lua lesson: a core that stops calling its reads must fail HERE,
-- not ship green).
-- ---------------------------------------------------------------------------
(function()
    local savedSF   = package.loaded['dlac\\lib\\statefile'];
    local savedCF   = package.loaded['dlac\\chatfmt'];
    local savedCore = AshitaCore;
    local savedReg  = ashita.events.register;

    local said = {};
    package.loaded['dlac\\lib\\statefile'] = { charDir = function() return nil; end };
    package.loaded['dlac\\chatfmt'] = { print = function(s) said[#said + 1] = tostring(s); end };

    local handlers = {};
    ashita.events.register = function(ev, nm, fn) handlers[ev .. '/' .. nm] = fn; end
    local okLoad, fw = pcall(dofile, 'feature/foodwatch.lua');
    ashita.events.register = savedReg;
    package.loaded['dlac\\lib\\statefile'] = savedSF;

    check('FW0 foodwatch loads headlessly', okLoad and type(fw), 'table');
if okLoad and type(fw) == 'table' then

    -- --- the outgoing item use: WHICH item (equipengine.parseItemUse's twin)
    local pkt = string.rep('\0', 0x0E) .. string.char(7) .. '\0' .. string.char(3);
    local u = fw._parseItemUse(pkt);
    check('FW1 the item index is read off OUT 0x037', u and u.itemIndex, 7);
    check('FW1b ...and the container beside it', u and u.container, 3);
    check('FW2 a short packet names nothing', fw._parseItemUse('\0\0\0\0'), nil);

    -- --- _step: the one decision
    local S = function(food) return { food = food }; end
    local PEND = { id = 4381, at = 100 };
    check('FW3 food appears after a use -> that use was food',
          fw._step(S(nil), 101, { present = true, expiry = 500 }, PEND), PEND);
    check('FW4 no item use pending -> nothing was eaten',
          fw._step(S(nil), 101, { present = true, expiry = 500 }, nil), nil);
    check('FW5 a use older than the window is not attributable',
          fw._step(S(nil), 100 + fw.WINDOW + 1, { present = true, expiry = 500 }, PEND), nil);
    -- The potion case: food was already up and STAYS at the same expiry.
    check('FW6 a use that leaves the expiry alone is not food',
          fw._step(S({ present = true, expiry = 500 }), 101, { present = true, expiry = 500 }, PEND), nil);
    -- The case presence alone gets wrong: a food wearing off and being re-eaten
    -- inside one poll gap, which never flickers the icon. Expiries are in
    -- SIXTIETHS of a second, so a 30-minute meal is 30*60*60.
    -- The catalogue has to vouch for a re-eat: it is the ambiguous edge, so an
    -- item nothing else speaks for is not believed on it (FW9e/FW9f).
    check('FW7 a re-eat pushes the expiry out by a whole meal -> recorded',
          fw._step(S({ present = true, expiry = 500 }), 101,
                   { present = true, expiry = 500 + 30 * 60 * 60 }, PEND, { known = true }), PEND);
    check('FW7b ...and with no timer array to read, a re-eat stays unknowable',
          fw._step(S({ present = true, expiry = nil }), 101, { present = true, expiry = nil }, PEND), nil);
    -- FIELD DATA, 2026-08-03, and this is the Instant Warp bug in one line. Food
    -- is PAUSED while a zone loads, so the server hands back an expiry pushed
    -- forward by the length of the load -- +2s here, straight out of Henrik's
    -- foodhistory.lua -- and the bare `~=` that used to live here read that as a
    -- second meal and blamed the scroll he used on the far side of the screen.
    check('FW7c a zone re-basing the clock by 2s is NOT a meal',
          fw._step(S({ present = true, expiry = 3605674160 }), 101,
                   { present = true, expiry = 3605674280 }, PEND), nil);
    check('FW7d ...nor the 6s drift that cost the Flask of Echo Drops',
          fw._step(S({ present = true, expiry = 3603904400 }), 101,
                   { present = true, expiry = 3603904760 }, PEND), nil);
    -- The raw value is a uint32 that wraps every ~2.3 years. A wrap lands outside
    -- the sane band and answers "not movement" with no wrap math at all.
    check('FW7e a wrapped expiry is not a meal either',
          fw._step(S({ present = true, expiry = 0xFFFFFF00 }), 101,
                   { present = true, expiry = 200 }, PEND), nil);
    check('FW8 the effect being gone is never a meal',
          fw._step(S(nil), 101, { present = false }, PEND), nil);
    -- A dropped read must not blank the last known state, or the next good read
    -- looks like an appearance and the next item used becomes "food".
    local st = S({ present = true, expiry = 500 });
    fw._step(st, 101, nil, PEND);
    check('FW9 an unreadable poll keeps the last known effect', st.food.expiry, 500);
    check('FW9b ...so the good read after it is not a fake appearance',
          fw._step(st, 102, { present = true, expiry = 500 }, PEND), nil);

    -- --- THE CATALOGUE (2026-08-03). What the effect alone could never settle.
    local UP = { present = true, expiry = 500 };
    check('FW9c an item the server calls food is believed',
          fw._step(S(nil), 101, UP, PEND, { known = true }), PEND);
    check('FW9d an item the table has never heard of is still learned',
          fw._step(S(nil), 101, UP, PEND, { known = false }), PEND);
    check('FW9e ...but only from an effect that APPEARED, never from a re-eat',
          fw._step(S({ present = true, expiry = 500 }), 101,
                   { present = true, expiry = 500 + 30 * 60 * 60 }, PEND, { known = false }), nil);
    check('FW9f ...where a catalogued food IS believed on that same re-eat',
          fw._step(S({ present = true, expiry = 500 }), 101,
                   { present = true, expiry = 500 + 30 * 60 * 60 }, PEND, { known = true }), PEND);

    -- THE ZONE. An unvouched item cannot be believed while the status array is
    -- still replaying; a catalogued one can, or "zone in and eat" would break.
    local ZP = { id = 4381, at = 100 };
    check('FW9g an unknown item inside the zone-settle window is not a meal',
          fw._step(S(nil), 101, UP, ZP, { known = false, zonedAt = 100 }), nil);
    check('FW9h ...but a catalogued food eaten right after a zone still is',
          fw._step(S(nil), 101, UP, ZP, { known = true, zonedAt = 100 }), ZP);
    local LATE = { id = 4381, at = 118 };
    check('FW9i ...and once the array has settled the unknown one counts again',
          fw._step(S(nil), 120, UP, LATE, { known = false, zonedAt = 100 }), LATE);

    -- THE REFUSED USE. You cannot eat over food on CatsEyeXI, so an effect with
    -- more time left than this item could ever grant is an EARLIER meal that has
    -- merely reappeared -- a zone reload landing beside a use the server threw
    -- away. Sole Sushi runs 30 min; five hours left is not Sole Sushi.
    check('FW9j a meal longer than the food that bought it is refused',
          fw._step(S(nil), 101, UP, PEND, { known = true, book = 1800, left = 18000 }), nil);
    check('FW9k ...with room for FOOD_DURATION doubling it under Sigil',
          fw._step(S(nil), 101, UP, PEND, { known = true, book = 1800, left = 3500 }), PEND);
    check('FW9l ...and no opinion at all when the timer cannot be decoded',
          fw._step(S(nil), 101, UP, PEND, { known = true, book = 1800, left = nil }), PEND);
    -- A wild decode (a machine clock out of step with the client's) is an
    -- UNKNOWN, not a veto -- otherwise it would refuse every real meal forever.
    check('FW9l2 an out-of-band decode does not veto anything',
          fw._step(S(nil), 101, UP, PEND, { known = true, book = 1800, left = 25828132 }), PEND);

    -- --- WHICH use the edge belongs to. Eat a Cutlet, quaff a potion two
    -- seconds later, and the potion is the newest thing you used when the FOOD
    -- effect finally lands. One slot would hand it the credit.
    local CUTLET, POTION = { id = 6394, at = 100 }, { id = 4148, at = 102 };
    check('FW9m the catalogued food outranks the newer non-food use',
          fw._choose(POTION, CUTLET, 103), CUTLET);
    check('FW9n ...but not once it has aged out of the window',
          fw._choose(POTION, CUTLET, 100 + fw.WINDOW + 1), POTION);
    check('FW9o with no food use to prefer, the newest use stands',
          fw._choose(POTION, nil, 103), POTION);
    check('FW9p and a window with nothing live in it chooses nothing',
          fw._choose(POTION, CUTLET, 200), nil);

    -- --- THE ONE-TIME SWEEP. This fixture IS Henrik's foodhistory.lua.
    local isFood = function(id) return id == 6394 or id == 6343; end
    local FILE = { { id = 4181, name = 'Instant Warp' },  { id = 6394, name = 'Pork Cutlet' },
                   { id = 4151, name = 'Echo Drops' },    { id = 6343, name = 'Grape Daifuku' } };
    local swept, dropped = fw._sweep(FILE, 1, isFood);
    check('FW9q the sweep drops the two rows that were never food', dropped, 2);
    check('FW9r ...keeping the real meals', #swept, 2);
    check('FW9s ...in order, untouched', swept[1].name, 'Pork Cutlet');
    check('FW9t a file already at the new format is never re-judged',
          select(2, fw._sweep({ { id = 4181, name = 'Instant Warp' } }, fw.FMT, isFood)), 0);
    check('FW9u a row learned without the table is never swept',
          select(2, fw._sweep({ { id = 31337, name = 'Stew', learned = true } }, 1, isFood)), 0);
    check('FW9v an unreadable table sweeps nothing at all',
          select(2, fw._sweep({ { id = 4181, name = 'Instant Warp' } }, 1, function() return nil; end)), 0);

    -- --- the history
    local H = {};
    fw._remember(H, { id = 1, name = 'Sole Sushi', at = 10 }, 10);
    fw._remember(H, { id = 2, name = 'Meat Mithkabob', at = 20 }, 10);
    check('FW10 the newest food is first', H[1].name, 'Meat Mithkabob');
    check('FW10b ...and the one before it is kept', H[2].name, 'Sole Sushi');
    fw._remember(H, { id = 1, name = 'Sole Sushi', at = 30 }, 10);
    check('FW11 eating it again makes no second row', #H, 2);
    check('FW11b ...it moves to the front', H[1].name, 'Sole Sushi');
    check('FW11c ...and the meal is counted', H[1].n, 2);
    for i = 3, 12 do fw._remember(H, { id = i, name = 'Food ' .. i, at = 40 + i }, 10); end
    check('FW12 the history is capped', #H, 10);
    check('FW12b ...dropping the oldest', H[10].name, 'Food 3');

    -- --- the menu pick: the most recent ones you are CARRYING
    local stock = { [1] = 0, [2] = 5, [3] = 0, [4] = 2 };
    local L = { { id = 1, name = 'A' }, { id = 2, name = 'B' }, { id = 3, name = 'C' }, { id = 4, name = 'D' } };
    local picked = fw._pick(L, function(e) return stock[e.id] or 0; end, 2);
    check('FW13 a food you have run out of is walked past', #picked, 2);
    check('FW13b ...to the next one you still have', picked[1].name, 'B');
    check('FW13c ...and the one after that', picked[2].name, 'D');
    check('FW13d the row carries what /item needs', picked[1].cmd, '/item "B" <me>');
    check('FW13e ...and how many are left', picked[1].count, 5);
    check('FW14 carrying nothing lists nothing',
          #fw._pick(L, function() return 0; end, 2), 0);
    -- How many rows the menu offers. THREE since 2026-08-01 (Henrik: "add the
    -- number of foods up to 3 in the list"); pinned because _pick defaults to it
    -- and nothing else would notice it quietly going back to two. It must stay
    -- well under CAP, which is what gives the walk-past something to walk to.
    check('FW14a the menu offers three foods', fw.MENU_N, 3);
    check('FW14b ...and the history stays deeper than that', fw.CAP > fw.MENU_N, true);
    local three = fw._pick({ { id = 1, name = 'A' }, { id = 2, name = 'B' },
                             { id = 3, name = 'C' }, { id = 4, name = 'D' } },
                           function() return 1; end);
    check('FW14c _pick defaults to that many', #three, 3);
    check('FW14d ...most recent first', three[3].name, 'C');

    -- --- disk shape (round trip; nothing is written)
    local round = fw._fromRaw((loadstring or load)(fw._serialize(H))());
    check('FW15 the file round-trips', #round, #H);
    check('FW15b ...in order', round[1].name, H[1].name);
    check('FW15c ...with the meal count', round[1].n, H[1].n);
    check('FW16 a row with no name is dropped rather than half-understood',
          #fw._fromRaw({ fmt = 1, foods = { { id = 9 }, { id = 8, name = 'Ok' } } }), 1);

    -- --- pump: the live path, driven with injected reads it must CALL
    fw._reset();
    fw._pending = { id = 4381, at = 100 };
    local saves, asked = 0, { clock = 0, food = 0, name = 0 };
    local reads = {
        clock  = function() asked.clock = asked.clock + 1; return 101; end,
        stamp  = function() return 1700000000; end,
        food   = function() asked.food = asked.food + 1; return { present = true, expiry = 555 }; end,
        nameOf = function(id) asked.name = asked.name + 1;
                              return (id == 4381) and 'Meat Mithkabob' or nil; end,
        save   = function() saves = saves + 1; return true; end,
    };
    local rec = fw.pump(reads);
    check('FW17 the pump records the food that was just eaten', rec and rec.name, 'Meat Mithkabob');
    check('FW17b ...stamping when', rec and rec.at, 1700000000);
    check('FW17c ...and the expiry it landed on', rec and rec.expiry, 555);
    check('FW17d ...saving once', saves, 1);
    check('FW17e ...and consuming the pending use', fw._pending, nil);
    check('FW17f the pump really asked its reads', asked.clock >= 1 and asked.food >= 1 and asked.name >= 1, true);
    check('FW18 a second beat with nothing pending records nothing', fw.pump(reads), nil);
    check('FW18b ...and does not save again', saves, 1);
    -- An item we cannot name is an item we could never /item: not recorded. The
    -- effect has to APPEAR for the decision to reach the naming step at all --
    -- an unvouched item is not believed on any other edge (FW9e).
    fw._pending = { id = 99999, at = 100 };
    fw._state.food = { present = false };
    reads.food = function() return { present = true, expiry = 777 }; end
    check('FW19 an unnameable item is not remembered', fw.pump(reads), nil);
    check('FW19b ...and the history is untouched', #fw.history, 1);

    -- --- status: which food is up (Henrik's ruling, 2026-07-30 -- dlac is always
    -- loaded, so the effect being up means it is the last thing we recorded)
    local sres = fw.status();
    check('FW20 the effect is up', sres.active, true);
    check('FW20b ...and it is NAMED off the history', sres.current and sres.current.name, 'Meat Mithkabob');

    -- --- the live surfaces, over a stubbed bag
    local BAG0 = { [1] = { Id = 4381, Count = 12 }, [2] = { Id = 4271, Count = 3 } };
    local queued = {};
    AshitaCore = {
        GetMemoryManager = function(self) return {
            GetInventory = function(self2) return {
                GetContainerCountMax = function(self3, bag) return (bag == 0) and 4 or 0; end,
                GetContainerItem = function(self3, bag, i)
                    if bag ~= 0 then return nil; end
                    return BAG0[i];
                end,
            }; end,
        }; end,
        GetChatManager = function(self) return {
            QueueCommand = function(self2, n, cmd) queued[#queued + 1] = cmd; end,
        }; end,
    };

    fw._reset();
    fw._remember(fw.history, { id = 4381, name = 'Meat Mithkabob', at = 1 }, 10);
    fw._remember(fw.history, { id = 5555, name = 'Sole Sushi', at = 2 }, 10);   -- newest, NOT carried
    local rows = fw.menu();
    check('FW21 the menu shows only what is in Inventory', #rows, 1);
    check('FW21b ...naming it', rows[1].name, 'Meat Mithkabob');
    check('FW21c ...with the live count', rows[1].count, 12);

    -- A meal eaten NOW must show up in the menu on this frame, not after the bag
    -- cache times out -- the one second you would wait is exactly the second you
    -- would spend looking for the row.
    fw._pending = { id = 4271, at = 100 };
    fw._state.food = { present = false };
    local rec2 = fw.pump({
        clock  = function() return 101; end,
        stamp  = function() return 5; end,
        food   = function() return { present = true, expiry = 2 }; end,
        nameOf = function() return 'Rice Dumpling'; end,
        save   = function() return true; end,
    });
    check('FW21d the food just eaten heads the history', rec2 and rec2.name, 'Rice Dumpling');
    local rows2 = fw.menu();
    check('FW21e ...and the menu shows it without waiting out its cache',
          rows2[1] and rows2[1].name, 'Rice Dumpling');
    check('FW21f ...with the one you ate before it underneath',
          rows2[2] and rows2[2].name, 'Meat Mithkabob');

    -- the packet handler: WHICH item, stashed and nothing else
    local pout = handlers['packet_out/dlac-foodwatch-out'];
    check('FW22 the item-use handler registered', type(pout), 'function');
    if type(pout) == 'function' then
        fw._pending = nil;
        pout({ id = 0x37, data = string.rep('\0', 0x0E) .. string.char(1) .. '\0' .. string.char(0) });
        check('FW22b it stashes the id the bag slot holds', fw._pending and fw._pending.id, 4381);
        fw._pending = nil;
        pout({ id = 0x1A, data = string.rep('\0', 0x20) });
        check('FW22c ...and ignores every other packet', fw._pending, nil);
    end

    -- The zone stamp (2026-08-03). Two bare writes on the network thread: the
    -- clock STEP 4 of _step waits out, and the pending item use that has no
    -- business surviving a loading screen -- Henrik's Instant Warp is BOTH, since
    -- a warp scroll's own arrival fires this handler.
    local pin = handlers['packet_in/dlac-foodwatch-zonein'];
    check('FW22d the zone-in handler registered', type(pin), 'function');
    if type(pin) == 'function' then
        fw._pending     = { id = 4381, at = 1 };
        fw._pendingFood = { id = 4381, at = 1 };
        fw._zonedAt     = nil;
        pin({ id = 0x00A, data = '' });
        check('FW22e a zone drops the use waiting on the far side', fw._pending, nil);
        check('FW22f ...and the food use with it', fw._pendingFood, nil);
        check('FW22g ...and stamps when the array started replaying', type(fw._zonedAt), 'number');
        fw._zonedAt = nil;
        pin({ id = 0x00B, data = '' });
        check('FW22h ...ignoring every other packet', fw._zonedAt, nil);
    end

    -- the command
    local cmd = handlers['command/dlac-foodwatch'];
    check('FW23 /dl food registered', type(cmd), 'function');
    if type(cmd) == 'function' then
        said, queued = {}, {};
        local ev = { command = '/dl food 1', blocked = false };
        cmd(ev);
        check('FW23b it owns the command', ev.blocked, true);
        check('FW23c ...and eats the row', queued[1], '/item "Rice Dumpling" <me>');
        said, queued = {}, {};
        cmd({ command = '/dl food 9', blocked = false });
        check('FW24 asking for a row that is not there eats nothing', #queued, 0);
        check('FW24b ...and says why', (said[1] or ''):find('no food 9', 1, true) ~= nil, true);
        said = {};
        local ev2 = { command = '/dl fishing', blocked = false };
        cmd(ev2);
        check('FW25 another /dl subcommand falls straight through', ev2.blocked, false);
    end

-- --- WHAT A FOOD DOES (2026-08-01). The game's food icon never says WHICH food
-- is up, so after a relog dlac is the only thing that can answer. statsFor pairs
-- the history with data\fooddb.lua (the server's own item scripts, shipped).
do
    check('FW26 a whole-hour duration reads as hours', fw._fmtDur(10800), '3 hr');
    check('FW26b ...and a part-hour one as minutes', fw._fmtDur(1800), '30 min');
    check('FW26c an absent duration is nil, never "0"', fw._fmtDur(nil), nil);
    check('FW26d ...and so is a zero one', fw._fmtDur(0), nil);

    -- The client Description blob: one string, embedded newlines, the odd
    -- control byte where the game meant a line break.
    local dl = fw._descLines('HP +40\n\nSTR +7\1Attack +20%\r\n   INT -7   \n');
    check('FW27 the description splits into lines', #dl, 4);
    check('FW27b ...dropping the empties', dl[2], 'STR +7');
    check('FW27c ...breaking on a control byte too', dl[3], 'Attack +20%');
    check('FW27d ...and trimming', dl[4], 'INT -7');
    check('FW27e a description that is not there is no lines, not a crash', #fw._descLines(nil), 0);

    -- The shipped table is the AUTHORITY: it is the server's own script text.
    package.loaded['dlac\\data\\fooddb'] = {
        fmt = 1,
        foods = {
            [6394] = { d = 10800, s = { 'HP +40', 'Attack +20% (cap 120)' } },
            [4325] = { d = 3600,  s = {} },   -- known food, header-less script
        },
    };
    fw._reset();
    local descs = { [4325] = 'Defense +12%\nAGI +4', [777] = nil };
    local reads = { describe = function(id) return descs[id]; end };

    local s = fw.statsFor(6394, reads);
    check('FW28 the shipped table answers first', s and s.src, 'server');
    check('FW28b ...with the effect lines', s and s.lines[2], 'Attack +20% (cap 120)');
    check('FW28c ...and the duration', s and s.dur, 10800);
    -- The lines come off a require'd table shared by every later read: handing
    -- out the original would let one caller's trim corrupt all of them.
    s.lines[1] = 'MANGLED';
    local s2 = fw.statsFor(6394, reads);
    check('FW28d the lines are a copy, not the shipped table', s2 and s2.lines[1], 'HP +40');

    local c = fw.statsFor(4325, reads);
    check('FW29 a food with no server header falls back to the client', c and c.src, 'client');
    check('FW29b ...reading its description', c and c.lines[1], 'Defense +12%');
    check('FW29c ...and still reports the duration the table knows', c and c.dur, 3600);

    check('FW30 a food neither source knows draws no stats at all', fw.statsFor(777, reads), nil);
    check('FW30b ...and so does a nil id', fw.statsFor(nil, reads), nil);

    -- THE LOAD-BEARING SPLIT. fooddb is DISPLAY ONLY: it must never become the
    -- answer to "is this item food". Detection stays learned from the effect
    -- moving, so a food the shipped table has never heard of is still recorded
    -- and still eatable -- it just has no stats to hover. If this ever fails,
    -- someone has wired the table into M._step / M.pump and the "dlac ships no
    -- food list" guarantee is gone.
    fw._reset();
    fw._pending = { id = 31337, at = 100 };
    local rec = fw.pump({
        clock = function() return 100; end,
        stamp = function() return 500; end,
        food  = function() return { present = true, expiry = 42 }; end,
        nameOf = function() return 'Server Custom Stew'; end,
        save  = function() return true; end,
    });
    check('FW31 a food the shipped table never heard of is still learned',
          rec and rec.name, 'Server Custom Stew');
    check('FW31b ...and still eatable', (fw._pick(fw.history, function() return 1; end, 2)[1] or {}).cmd,
          '/item "Server Custom Stew" <me>');
    check('FW31c ...it simply has no stats to show', fw.statsFor(31337, { describe = function() return nil; end }), nil);
    -- ...and it is MARKED, which is what stops the one-time sweep from deciding
    -- later that a food the shipped table never listed was never food.
    check('FW31d a learned food carries the marker', fw.history[1] and fw.history[1].learned, true);
    check('FW31e ...and keeps it through the file',
          (fw._fromRaw((loadstring or load)(fw._serialize(fw.history))())[1] or {}).learned, true);

    -- The other side of the same coin: a food the table DOES vouch for needs no
    -- marker, because the catalogue can answer for it every time.
    fw._reset();
    fw._pending = { id = 6394, at = 100 };
    fw.pump({ clock  = function() return 100; end,
              stamp  = function() return 500; end,
              food   = function() return { present = true, expiry = 42 }; end,
              nameOf = function() return 'Pork Cutlet'; end,
              save   = function() return true; end });
    check('FW31f a catalogued food is recorded', fw.history[1] and fw.history[1].name, 'Pork Cutlet');
    check('FW31g ...and needs no learned marker', fw.history[1] and fw.history[1].learned, nil);

    package.loaded['dlac\\data\\fooddb'] = nil;
    fw._reset();
end

-- --- THE CLOCK STOPS WHEN YOU LOG OUT (2026-08-01). Henrik: "the food duration
-- doesn't go down when you're logged out." Food is PAUSED offline, so wall-clock
-- elapsed overstates by the length of every logout. The fix reads the client's
-- own status timer instead of counting seconds ourselves.
do
    -- The two numbers below are FIELD DATA, straight out of Henrik's
    -- foodhistory.lua: the raw expiry recorded beside each meal and the os.time()
    -- of the row. That makes this a golden, not a hand-built fixture -- if the
    -- decode ever drifts, it drifts against a real client's real output.
    local T0, RAW0 = 1785515840, 3592845320;   -- Hobgoblin Pie, a 3600s food
    check('FW32 the status timer decodes to what the server script says',
          fw._remaining(RAW0, T0), 3598);      -- 3600 less the 250ms poll's lag
    -- The same read on Pork Cutlet came back at exactly TWICE its 10800s script
    -- duration. Not a bug: xi.mod.FOOD_DURATION (Sigil, Sanction) grants +100%,
    -- which is the whole reason the duration must be MEASURED and never looked up.
    check('FW32a a doubled meal decodes as doubled', fw._remaining(3597700040, 1785578753), 21597);
    check('FW32b a permanent effect has no remaining time', fw._remaining(fw.INFINITE, T0), nil);
    check('FW32c ...and neither has an unreadable one', fw._remaining(nil, T0), nil);
    check('FW32d an expired timer is zero, not negative', fw._remaining(RAW0, T0 + 99999), 0);

    fw._reset();
    fw._pending = { id = 4325, at = 100 };
    local rec = fw.pump({
        clock  = function() return 100; end,
        stamp  = function() return T0; end,
        food   = function() return { present = true, expiry = RAW0 }; end,
        nameOf = function() return 'Hobgoblin Pie'; end,
        save   = function() return true; end,
    });
    check('FW33 the meal records its MEASURED duration', rec and rec.dur, 3598);

    local playing = fw.status({ stamp = function() return T0 + 600; end });
    check('FW34 ten minutes under it, ten minutes spent', playing.used, 600);
    check('FW34b ...and the rest still on it', playing.left, 2998);

    -- Now log out for eight hours. The server pauses food, so at login the client
    -- reports the SAME remaining time -- the raw expiry has slid forward by the
    -- whole offline stretch. Wall clock has not, which is exactly the bug.
    local OUT = 28800;
    fw._state.food = { present = true, expiry = RAW0 + OUT * 60 };
    local back = fw.status({ stamp = function() return T0 + 600 + OUT; end });
    check('FW35 an eight-hour logout costs the food nothing', back.used, 600);
    check('FW35b ...the timer still agrees', back.left, 2998);
    check('FW35c ...where wall clock would have claimed this much',
          (T0 + 600 + OUT) - rec.at, 29400);

    -- A row written before the duration was measured (or a decode that came back
    -- outside the sane band) has no `dur`: `used` must be nil so the caller falls
    -- back to wall-clock, rather than inventing a number.
    fw.history[1].dur = nil;
    local old = fw.status({ stamp = function() return T0 + 600; end });
    check('FW36 a row with no measured duration reports no spend', old.used, nil);
    check('FW36b ...but the effect is still up and still named', old.current.name, 'Hobgoblin Pie');

    -- The countdown (2026-08-01, Henrik: "if we have the number, just let it show
    -- an estimated countdown"). Not _fmtDur: a length may round to the nearest
    -- minute, a countdown may not round 20 seconds up to "1 min", and it needs
    -- something to say at zero rather than going blank as the food runs out.
    check('FW38 a countdown reads as an estimate', fw._fmtLeft(17460), '~4 hr 51 min left');
    check('FW38b ...a whole hour keeps it short', fw._fmtLeft(3600), '~1 hr left');
    check('FW38c ...seconds do not become a minute', fw._fmtLeft(20), 'under a minute left');
    check('FW38d ...and zero says so instead of going blank', fw._fmtLeft(0), 'expiring now');
    check('FW38e an unknown remaining draws nothing at all', fw._fmtLeft(nil), nil);
    -- `left` does NOT depend on the measured duration, so a row recorded before
    -- 2026-08-01 still gets a countdown even though it can report no spend.
    -- (Back to the pre-logout expiry: FW35 left the shifted one in place.)
    fw._state.food = { present = true, expiry = RAW0 };
    fw.history[1].dur = nil;
    local noDur = fw.status({ stamp = function() return T0 + 600; end });
    check('FW39 an unmeasured row still counts down', noDur.left, 2998);
    check('FW39b ...it just cannot say how much is spent', noDur.used, nil);
    fw.history[1].dur = 3598;

    -- ...and the measurement survives the disk round trip.
    fw.history[1].dur = 3598;
    local rt = fw._fromRaw((loadstring or load)(fw._serialize(fw.history))());
    check('FW37 the measured duration round-trips through the file', rt[1].dur, 3598);
    fw.history[1].dur = nil;
    local rt2 = fw._fromRaw((loadstring or load)(fw._serialize(fw.history))());
    check('FW37b ...and an absent one stays absent', rt2[1].dur, nil);
    fw._reset();
end
end

    AshitaCore = savedCore;
    package.loaded['dlac\\chatfmt'] = savedCF;
    package.loaded['dlac\\feature\\foodwatch'] = nil;
end)();

-- ---------------------------------------------------------------------------
-- SND. /dl sends -- the send counter (feature\sendlog, 2026-08-02).
--
-- Henrik asked mid-Incursion whether dlac sends "constant packets to have
-- things equipped or only once". The code says only-on-a-difference; this
-- readout is how the field proves it. The pure core is driven here; SND12 is
-- the one that matters most -- it pins the INVARIANT the whole readout rests
-- on (every AddOutgoingPacket site notes), because an uncounted send is the
-- only way a "dlac sent nothing" line could ever be a lie.
-- ---------------------------------------------------------------------------
(function()
    local SL = dofile('feature/sendlog.lua');
    check('SND0 sendlog loads', type(SL), 'table');
    if type(SL) ~= 'table' then return; end

    -- a fresh state
    local st = SL.newState(100);
    check('SND1 fresh state is empty', st.total == 0 and next(st.byId) == nil, true);

    SL._note(st, 0x51, 'Default (set, 4 slots)', 101);
    SL._note(st, 0x50, 'Default (single slot)',  101);
    SL._note(st, 0x50, 'Default (single slot)',  102);
    check('SND2 total counts every send',   st.total, 3);
    check('SND3 by-packet tallies per id',  st.byId[0x50] == 2 and st.byId[0x51] == 1, true);
    check('SND4 by-cause tallies per cause', st.byWhy['Default (single slot)'], 2);
    check('SND5 lastAt is the newest send', st.lastAt, 102);

    -- garbage in still COUNTS: a dropped send is the only real failure mode
    local sg = SL.newState(0);
    SL._note(sg, nil, nil, nil);
    check('SND6 malformed send still counted', sg.total == 1 and sg.byWhy['unknown'] == 1, true);

    -- the ring wraps and reads newest-first
    local sr = SL.newState(0);
    for i = 1, SL.RING + 3 do SL._note(sr, 0x50, 'n' .. i, i); end
    local rec = SL._recent(sr);
    check('SND7 ring caps at RING',        #rec, SL.RING);
    check('SND8 newest first',             rec[1].why, 'n' .. (SL.RING + 3));
    check('SND9 oldest surviving entry',   rec[SL.RING].why, 'n4');

    check('SND10a dur seconds', SL._dur(8),    '8s');
    check('SND10b dur minutes', SL._dur(862),  '14m22s');
    check('SND10c dur hours',   SL._dur(7380), '2h03m');

    -- the zero case: the answer to the question that begat the command
    local zl = SL._lines(SL.newState(0), 300);
    check('SND11a silence is stated as silence',
          zl[1]:match('NOTHING sent in 5m00s') ~= nil, true);
    check('SND11b ...and explained as the expected steady state',
          (zl[2] or ''):match('edge%-driven') ~= nil, true);

    local ll = SL._lines(st, 160);
    check('SND11c count + elapsed lead the readout',
          ll[1]:match('^sends: 3 from dlac %(3%.0/min%) in 1m00s') ~= nil, true);
    check('SND11d by-packet is ranked, most-sent first',
          ll[2]:match('^sends: by packet %-%- 0x050 x2, 0x051 x1$') ~= nil, true);
    check('SND11e by-cause names the dispatch point',
          ll[3]:match('Default %(single slot%) x2') ~= nil, true);
    check('SND11f the ring is rendered with ages',
          (ll[5] or ''):match('%-58s%s+0x050') ~= nil, true);

    -- THE SPLIT (Henrik, 08-02): a re-injected 0x01A is YOUR packet handed
    -- back to the wire, not traffic dlac added. Billing dlac for it made the
    -- headline read higher than its real contribution.
    local sp = SL.newState(0);
    SL._note(sp, 0x51, 'Precast (set, 4 slots)', 10);
    SL._note(sp, 0x1A, 'passed through (your own action)', 10, true);
    SL._note(sp, 0x1A, 'passed through (your own action)', 20, true);
    check('SND15a passed sends are tallied apart', sp.passed, 2);
    check('SND15b ...and still counted in the total', sp.total, 3);
    check('SND15c _own is the difference', SL._own(sp), 1);
    local pl = SL._lines(sp, 70);
    check('SND15d the headline splits the two',
          pl[1]:match('^sends: 1 from dlac %(0%.9/min%) %+ 2 of your own actions passed through = 3 in 1m10s') ~= nil,
          true);
    check('SND15e the rate is dlac\'s own, not the total',
          pl[1]:match('3%.0/min') == nil and pl[1]:match('2%.6/min') == nil, true);
    check('SND15f by-packet marks a wholly passed-through id',
          pl[2]:match('0x01A x2 %(passed through%)') ~= nil, true);
    check('SND15g ...and does not mark dlac\'s own',
          pl[2]:match('0x051 x1,') ~= nil or pl[2]:match('0x051 x1$') ~= nil, true);

    -- dlac added nothing and only your own actions went by: the SAME answer
    -- the zero case gives, and the shape a real casting session takes.
    local op = SL.newState(0);
    SL._note(op, 0x1A, 'passed through (your own action)', 10, true);
    local ol = SL._lines(op, 70);
    check('SND15h all-passed-through says dlac sent NOTHING',
          ol[2]:match('dlac itself sent NOTHING') ~= nil, true);
    check('SND15i ...and explains what a pass-through is',
          ol[2]:match('back on the wire byte%-identical') ~= nil, true);
    check('SND15j a partial pass is quantified, not rounded away',
          (function()
              local mx = SL.newState(0);
              SL._note(mx, 0x37, 'passed through (your own action)', 1, true);
              SL._note(mx, 0x37, 'Midcast (single slot)', 2);
              return SL._lines(mx, 60)[2]:match('0x037 x2 %(1 passed through%)') ~= nil;
          end)(), true);

    -- chat is a summary, the file is the record: a flap must not scroll the
    -- counters off the top of chat, but nothing may be lost from the report.
    local fl = SL.newState(0);
    for i = 1, SL.RING do SL._note(fl, 0x50, 'Default (single slot)', i); end
    local chat = SL._lines(fl, 100, 8);
    local file = SL._lines(fl, 100, nil);
    check('SND11g chat caps the ring',    #chat - 4, 8);
    check('SND11h ...and says what it withheld',
          chat[4]:match('%-%- %d+ more in the report file') ~= nil, true);
    check('SND11i the file keeps them all', #file - 4, SL.RING);
    check('SND11j ...with no withheld note', file[4]:match('more in the report file'), nil);

    -- THE INVARIANT PIN. Every AddOutgoingPacket in the shipped tree sits
    -- within reach of a sendlog note. A send site added WITHOUT one would
    -- make /dl sends under-report -- silently, and in the one direction that
    -- matters ("dlac sent nothing" when it did). Files are listed rather than
    -- globbed (no io.popen: `dir` vs `ls` would split Windows from the WSL CI
    -- run); A NEW FILE THAT SENDS PACKETS MUST BE ADDED HERE.
    local SEND_FILES = { 'feature/equipengine.lua', 'feature/lockstyleapply.lua',
                         'feature/craftwatch.lua', 'feature/eboxclient.lua',
                         'feature/helmwatch.lua' };
    local sites, bare = 0, {};
    for _, path in ipairs(SEND_FILES) do
        local f = io.open(path, 'r');
        local src = f and f:read('*a') or nil;
        if f then f:close(); end
        if src == nil then
            bare[#bare + 1] = path .. ' (UNREADABLE)';
        else
            -- An INVOCATION, not a mention: `AddOutgoingPacket%s*%(`. A plain
            -- substring search also matched prose about the send sites, and a
            -- pin that fails on its own documentation trains people to weaken
            -- it. (It fired on exactly that the first time -- 08-02.)
            local at = 1;
            while true do
                local s = string.find(src, 'AddOutgoingPacket%s*%(', at);
                if s == nil then break; end
                sites = sites + 1;
                local window = string.sub(src, s, s + 500);
                if string.find(window, 'sendlog', 1, true) == nil
                   and string.find(window, 'noteSend', 1, true) == nil then
                    bare[#bare + 1] = string.format('%s@%d', path, s);
                end
                at = s + 1;
            end
        end
    end
    check('SND12a every send site is instrumented', table.concat(bare, ', '), '');
    check('SND12b ...and all five chokepoints are still there', sites, 5);

    check('SND13a bare command',            SL._parse('/dl sends'),        '');
    check('SND13b trailing space',          SL._parse('/dl sends   '),     '');
    check('SND13c /dlac alias',             SL._parse('/dlac sends'),      '');
    check('SND13d argument',                SL._parse('/dl sends reset'),  'reset');
    check('SND13e a neighbour is NOT ours', SL._parse('/dl sendsfoo'),     nil);
    check('SND13f another command entirely', SL._parse('/dl why'),         nil);

    -- the live path (M.note -> M.state), not just the injected pure core
    SL.reset();
    SL.note(0x51, 'Precast (set, 2 slots)');
    check('SND14a note() reaches the live state', SL.state.total, 1);
    check('SND14b ...with the cause intact', SL.state.byWhy['Precast (set, 2 slots)'], 1);
    SL.reset();
    check('SND14c reset empties it', SL.state.total, 0);

    -- SND16. The wire-shape note (2026-08-06). Counts taken under a switched
    -- /dl gearpackets mode are uninterpretable unless the artifact says which
    -- mode produced them, and the player who forgot they were mid-experiment
    -- is exactly the one who sends the file. Absent note = today's output,
    -- byte for byte, which is what every check above still asserts.
    local nl = SL._lines(st, 160, nil, 'mode SET -- OVERRIDING every dispatch point');
    check('SND16a the note rides under the headline',
          (nl[2] or ''):match('^sends: wire shape %-%- mode SET') ~= nil, true);
    check('SND16b ...and pushes the counters down, not out',
          (nl[3] or ''):match('^sends: by packet') ~= nil, true);
    local zn = SL._lines(SL.newState(0), 300, nil, 'mode SINGLE');
    check('SND16c silence names the mode too',
          (zn[2] or ''):match('^sends: wire shape %-%- mode SINGLE') ~= nil, true);
    check('SND16d ...without losing the explanation',
          (zn[3] or ''):match('edge%-driven') ~= nil, true);
    check('SND16e an empty note adds no line',
          (SL._lines(st, 160, nil, '')[2] or ''):match('^sends: by packet') ~= nil, true);
end)();

-- ---------------------------------------------------------------------------
-- GP. /dl gearpackets -- the wire-shape switch (feature\gearpackets, 08-06).
--
-- Henrik asked whether the game's equipsets batch what dlac sends per slot.
-- They do: 0x051 carries up to 16 {index, slot, container} triples and the
-- server keeps no equipset of its own, so the batch needs no registration --
-- it is a shape choice available on every send. What it COSTS is the field's
-- to say (bytes favour singles under 9 pieces; the server's per-packet tail
-- favours the batch always), so this module exists to make the A/B one
-- command apart, for every dispatch point at once.
--
-- GP9 is the one that matters most: the defaults ARE LAC parity, so a player
-- who never types the command is on exactly the shape that shipped.
-- ---------------------------------------------------------------------------
(function()
    local GP = dofile('feature/gearpackets.lua');
    check('GP0 gearpackets loads', type(GP), 'table');
    if type(GP) ~= 'table' then return; end

    check('GP1a a mode is recognised',        GP.isMode('single'), 'single');
    check('GP1b ...case-insensitively',       GP.isMode('SET'),    'set');
    check('GP1c junk is not a mode',          GP.isMode('batch'),  nil);
    check('GP1d nil is not a mode',           GP.isMode(nil),      nil);
    check('GP1e every listed mode has a blurb to print', (function()
        for _, m in ipairs(GP.MODES) do
            if type(GP.MODE_BLURB[m]) ~= 'string' then return m; end
        end
        return true;
    end)(), true);

    check('GP2a a threshold clamps up from zero',  GP.clampThreshold(0),   1);
    check('GP2b ...and down from past sixteen',    GP.clampThreshold(99),  16);
    check('GP2c a float floors',                   GP.clampThreshold(3.7), 3);
    check('GP2d a numeric string is a number',     GP.clampThreshold('4'), 4);
    check('GP2e garbage is nil, not a guess',      GP.clampThreshold('x'), nil);

    -- THE RESOLUTION. 'default' is the only mode that lets the dispatch point
    -- speak; the rest replace it, which is what makes precast and midcast move
    -- together (they are the same timing problem -- both fire inside ONE
    -- outgoing chunk -- so a switch that moved one would measure nothing).
    check('GP3a default defers to the route',   GP.resolve('set', 'default'),  'set');
    check('GP3b ...for singles as well',        GP.resolve('single', 'default'), 'single');
    check('GP3c an unknown route style reads as auto',
          GP.resolve('bogus', 'default'), 'auto');
    check('GP3d single overrides a set route',  GP.resolve('set', 'single'),   'single');
    check('GP3e set overrides a single route',  GP.resolve('single', 'set'),   'set');
    check('GP3f auto overrides both',           GP.resolve('set', 'auto'),     'auto');
    check('GP3g an unknown MODE falls back to default, never to a guess',
          GP.resolve('set', 'sideways'), 'set');

    local pts = { { name = 'Precast', style = 'set' }, { name = 'Midcast', style = 'single' } };
    local eff = GP.effective(pts, 'set');
    check('GP4a effective keeps the asked style for the record',
          eff[2].asked, 'single');
    check('GP4b ...and reports what it will actually get', eff[2].gets, 'set');
    check('GP4c an unmoved point is visibly unmoved',
          GP.effective(pts, 'default')[1].gets, 'set');

    check('GP5a a set shape names one packet',   GP.shapeOf('set'),    'one 0x051');
    check('GP5b a single shape names per-slot',  GP.shapeOf('single'), 'one 0x050 per slot');
    check('GP5c auto is the only shape that quotes the number',
          GP.shapeOf('auto', 4):match('from 4 slots up') ~= nil, true);

    local L = GP.lines('set', 9, pts);
    check('GP6a the readout leads with the mode',
          L[1]:match('^gearpackets: mode SET') ~= nil, true);
    check('GP6b an unconsulted threshold says so rather than implying it applies',
          L[2]:match('not consulted in set mode') ~= nil, true);
    check('GP6c ...where a consulted one explains the number',
          GP.lines('auto', 3, pts)[2]:match('from 3 changed slots up') ~= nil, true);
    check('GP6d overridden points are marked', (function()
        for _, l in ipairs(L) do
            if l:match('Midcast') and l:match('overridden') then return true; end
        end
        return false;
    end)(), true);
    -- THE LINE THAT SAVES A FIELD ROUND: conflict strips stay 0x050 at every
    -- mode, so the first 0x050 seen in set mode is correct, not a broken switch.
    check('GP6e the strip caveat is always printed', (function()
        for _, l in ipairs(GP.lines('set', 9, pts)) do
            if l:match('conflict strips') then return true; end
        end
        return false;
    end)(), true);

    check('GP7a bare command',             #GP.parse('/dl gearpackets'),     0);
    check('GP7b the short alias',          #GP.parse('/dl gp'),              0);
    check('GP7c /dlac alias',              #GP.parse('/dlac gearpackets'),   0);
    check('GP7d arguments split',          table.concat(GP.parse('/dl gp threshold 3'), ','), 'threshold,3');
    check('GP7e a neighbour is NOT ours',  GP.parse('/dl gearpacketsfoo'),   nil);
    check('GP7f ...nor is a longer word starting gp', GP.parse('/dl gps'),   nil);
    check('GP7g another command entirely', GP.parse('/dl sends'),            nil);

    check('GP8a bare is show',        GP.intent({}).kind,                     'show');
    check('GP8b a mode word',         GP.intent({ 'single' }).mode,           'single');
    check('GP8c threshold long form', GP.intent({ 'threshold', '5' }).n,      5);
    check('GP8d threshold short form',GP.intent({ 't', '5' }).n,              5);
    check('GP8e a bare number is a threshold -- what a tired thumb types',
          GP.intent({ '3' }).n, 3);
    check('GP8f a threshold with no number is usage, not a silent default',
          GP.intent({ 'threshold' }).kind, 'usage');
    check('GP8g an unknown word is usage', GP.intent({ 'batch' }).kind,       'usage');

    -- GP9. THE PARITY PIN. With no store (headless, and pre-login in game)
    -- these must serve the LAC shape: a player who never types the command,
    -- and a store that fails to open, both land on what shipped.
    check('GP9a the default mode is LAC parity',   GP.mode(),      'default');
    check('GP9b the default threshold is 9',       GP.threshold(), 9);
    check('GP9c styleFor is identity under default', GP.styleFor('single'), 'single');
    check('GP9d a write with no store fails honestly rather than pretending',
          GP.setMode('set'), false);
    check('GP9e ...and leaves the mode alone',     GP.mode(),      'default');

    -- GP10. Every style the ROUTE TABLE declares must be one this module can
    -- resolve. A new dispatch point with a typo'd style would otherwise read
    -- as 'auto' forever and nobody would see it happen.
    local eng = dofile('feature/equipengine.lua');
    local known = { set = true, single = true, auto = true };
    local strays = {};
    for _, r in pairs((type(eng) == 'table' and eng.ACTION_ROUTES) or {}) do
        for _, key in ipairs({ 'preStyle', 'midStyle' }) do
            local s = r[key];
            if s ~= nil and known[s] ~= true then
                strays[#strays + 1] = tostring(r.type) .. '.' .. key .. '=' .. tostring(s);
            end
        end
    end
    check('GP10a every route style is a style this module knows',
          table.concat(strays, ', '), '');
    check('GP10b ...and the route table still declares the LAC split',
          (eng.ACTION_ROUTES[0x03] or {}).preStyle == 'set'
          and (eng.ACTION_ROUTES[0x03] or {}).midStyle == 'single', true);
end)();

-- ---------------------------------------------------------------------------
-- RPT. /dl report -- the support recorder (feature\report, 2026-08-03).
--
-- Henrik: "once the user base grows, I want people to enable the debug...
-- their whole dlac profile + gear, sets, triggers, everything... max 5
-- minutes... then send those files to me." The artifact is read by a human
-- and by an LLM, so the pure seams pinned here are the ones that decide what
-- LANDS IN IT: the window clamp, the decision renderer's vocabulary (it must
-- say the same words as /dl why and the Monitor hover), the digest's scope,
-- and the budget walk -- whose whole job is that nothing is ever dropped
-- SILENTLY.
-- ---------------------------------------------------------------------------
(function()
    local RP = dofile('feature/report.lua');
    check('RPT0 report loads', type(RP), 'table');
    if type(RP) ~= 'table' then return; end

    -- the window clamp: Henrik's five-minute ceiling, and a floor under it
    check('RPT1a bare window is the default', RP._dur(nil),  RP.DEF_S);
    check('RPT1b under the floor clamps up',  RP._dur(5),    RP.MIN_S);
    check('RPT1c over the ceiling clamps',    RP._dur(9000), RP.MAX_S);
    check('RPT1d the ceiling IS five minutes', RP.MAX_S,     300);
    check('RPT1e a real number rides',        RP._dur(120),  120);
    check('RPT1f garbage is the default',     RP._dur('x'),  RP.DEF_S);

    -- the command parse (sendlog's law: a command that eats its neighbours is
    -- worse than one that misses)
    check('RPT2a bare form',           RP._parse('/dl report'),      '');
    check('RPT2b /dlac alias',         RP._parse('/dlac report'),    '');
    check('RPT2c an argument',         RP._parse('/dl report stop'), 'stop');
    check('RPT2d seconds',             RP._parse('/dl report 90'),   '90');
    check('RPT2e a neighbour is NOT ours', RP._parse('/dl reportfoo'), nil);
    check('RPT2f another command',     RP._parse('/dl why'),         nil);

    -- the mark parse. CASE IS PRESERVED: the note is the player's own words
    -- and goes in the file as typed, so this reads the raw command.
    check('RPT3a bare mark',        RP._markParse('/dl mark'),                '');
    check('RPT3b a note',           RP._markParse('/dl mark Gear DID NOT swap'), 'Gear DID NOT swap');
    check('RPT3c /dlac alias',      RP._markParse('/dlac mark hi'),           'hi');
    check('RPT3d typed uppercase',  RP._markParse('/DL MARK Here'),           'Here');
    check('RPT3e a neighbour',      RP._markParse('/dl marker'),              nil);

    check('RPT4a clock minutes', RP._clock(250), '4:10');
    check('RPT4b clock seconds', RP._clock(38),  '0:38');

    -- the privacy filter: dlac's own lines only, control bytes stripped
    check('RPT5a our line is ours',  RP._isOurs(RP._clean('\007[dlac] report: recording')), true);
    check('RPT5b a tell is not',     RP._isOurs('Someone >> where are you'),                false);
    check('RPT5c control bytes go',  RP._clean('\001[dlac]\002 hi'),                        '[dlac] hi');

    -- ---------------------------------------------------------------------
    -- a decision record, shaped exactly as dispatch.recordDecision builds one
    -- ---------------------------------------------------------------------
    local REC = {
        seq = 42, time = '12:34:56', at = 1000, event = 'Precast', action = 'Cure IV',
        plan = { Head = 'Nahtirah Hat', Body = 'Vanya Robe', Ammo = 'remove' },
        changed = { Head = true, Ammo = true },
        nChanged = 2,
        ladders = { head = { set = 'Precast', items = { 'Chapeau', 'Nahtirah Hat' } } },
        ctx = { job = 'WHM', jobLevel = 75, sub = 'RDM', subLevel = 37, status = 'Idle',
                mpp = 62, tp = 0, day = 'Fire', weather = 'clear',
                modes = { 'Town' }, buffs = { 'Refresh' } },
        contest = {
            explain = {
                head = { { name = 'Triggers', rank = 11, item = 'Nahtirah Hat' },
                         { name = 'MaxMP',    rank = 6,  item = 'Zenith Crown' } },
                body = { { name = 'Triggers', rank = 11, item = 'Vanya Robe' } },
            },
            rep  = { head = { from = 'Chapeau', to = 'Nahtirah Hat', why = 'unavail' } },
            src  = { head = 'Precast', body = 'Precast' },
            fall = { refused = { head = { { name = 'Chapeau', why = 'unavail' } } }, dead = {} },
            pair = { slot = 'Ammo', loser = 'Bolt', keep = 'Sword', why = 'mismatch', remove = false },
        },
    };
    local function joined(t) return table.concat(t, '\n'); end

    local head = joined(RP._slotLines(REC, 'Head'));
    check('RPT6a the winner is named with its rank',
        head:match('<%- Triggers %(rank 11%)') ~= nil, true);
    check('RPT6b the losers are named too ("why did MY claim not win")',
        head:match('also asked: MaxMP:Zenith Crown') ~= nil, true);
    -- THE VOCABULARY PIN: the same sentence the Monitor hover and /dl why use.
    -- A player quoting one and support reading the other must be looking at
    -- the same words.
    check('RPT6c an unavailable fall says WHY in the shared wording',
        head:match('fell: Chapeau %-> Nahtirah Hat %(Chapeau is not in a bag you can equip from%)') ~= nil, true);
    check('RPT6d the whole ladder rides, refused rungs struck',
        head:match('ladder %(Precast%): 1%.Chapeau %[x not in your bags%]') ~= nil, true);
    check('RPT6e ...and the surviving rung is NOT struck',
        head:match('2%.Nahtirah Hat$') ~= nil, true);

    local ammo = joined(RP._slotLines(REC, 'Ammo'));
    check('RPT7a the pair verdict gets its OWN sentence, not "reserved"',
        ammo:match('cannot be fired by Sword') ~= nil, true);
    check('RPT7b ...and never claims a reserving piece that does not exist',
        ammo:match('reserved') == nil, true);

    -- a reserve fall reads differently from an unavailable one (two refusals,
    -- one line -- telling someone their Mog Safe piece "reserves Head" sends
    -- them hunting an imaginary bug)
    local RES = { plan = { Head = 'X' }, contest = {
        explain = { head = { { name = 'Triggers', rank = 11, item = 'X' } } },
        rep = { head = { from = 'Y', to = 'X', why = 'reserve', by = 'Main' } } } };
    check('RPT8 a reserve fall names the reserved slot',
        joined(RP._slotLines(RES, 'Head')):match('it reserves Main %-%- owned above') ~= nil, true);

    -- a slot whose whole ladder died
    local DEAD = { plan = {}, contest = { explain = {},
        fall = { dead = { feet = 'Herald\'s Gaiters' }, refused = {} } } };
    check('RPT9 a dead ladder says nothing below it was equippable either',
        joined(RP._slotLines(DEAD, 'Feet')):match('nothing below it on the ladder is either') ~= nil, true);

    -- the decision block
    local blk = joined(RP._decLines(REC, tostring));
    check('RPT10a the header carries seq, event and action',
        blk:match('^%[12:34:56%] #42 Precast %-%- Cure IV   %(2 slots changed%)') ~= nil, true);
    check('RPT10b the world it was decided under rides with it',
        blk:match('under: WHM75/RDM37  Idle  MP 62%%') ~= nil, true);
    check('RPT10c buffs ride too (a weatherMatch why is incomplete without them)',
        blk:match('buffs: Refresh') ~= nil, true);
    check('RPT10d a slot that did NOT change stays out of the block',
        blk:match('Body') == nil, true);
    check('RPT10e ...but a slot that FELL is in it even if the outcome held',
        blk:match('Head') ~= nil, true);
    check('RPT10f slots print in equip-screen order, so two reports diff',
        blk:find('Ammo', 1, true) < blk:find('Head', 1, true), true);
    check('RPT10g "all" prints the untouched slots too',
        joined(RP._decLines(REC, tostring, 'all')):match('Body') ~= nil, true);

    -- ---------------------------------------------------------------------
    -- THE DROPPED SLOT (field report 1, 2026-08-02). A DRG26's weaponskill
    -- blocks read "(7 slots changed)" over seven rows saying "(kept)" -- two
    -- statements that cannot both be true. The ring counts a slot as changed
    -- when it LEFT the plan; the renderer then had no item and no winner and
    -- fell through to the Monitor's word for "nobody claimed it".
    -- ---------------------------------------------------------------------
    local WS = {
        seq = 2, time = '16:33:35', event = 'Weaponskill', action = '"Double Thrust"',
        plan = { Head = 'Emperor Hairpin' },
        changed = { Neck = true, Ear1 = true, Head = true },
        nChanged = 3,
        contest = { explain = { head = { { name = 'Triggers', rank = 13, item = 'Emperor Hairpin' } } } },
    };
    local neck = joined(RP._slotLines(WS, 'Neck'));
    check('RPT33a a slot that left the plan is not "(kept)"',
        neck:match('%(kept%)'), nil);
    check('RPT33b ...it was left as worn',      neck:match('%(left as worn%)') ~= nil, true);
    -- the ROW stays one line: the prose belongs to the block (below), because
    -- repeating it per slot cost 21 lines on a seven-slot weaponskill
    check('RPT33c the row itself carries no prose',  select(2, neck:gsub('\n', '')), 0);
    check('RPT33d a slot that WAS filled is untouched by this',
        joined(RP._slotLines(WS, 'Head')):match('Emperor Hairpin') ~= nil, true);
    -- a genuinely unclaimed slot -- not in `changed` -- keeps the old word
    check('RPT33e an unchanged, unclaimed slot is still "(kept)"',
        joined(RP._slotLines(WS, 'Body')):match('%(kept%)') ~= nil, true);

    local wsb = joined(RP._decLines(WS, tostring));
    check('RPT34a the header breaks the count down when they differ',
        wsb:match('%(3 slots changed %-%- 1 placed, 2 left as worn%)') ~= nil, true);
    check('RPT34b ...and stays short when everything was placed',
        joined(RP._decLines(REC, tostring)):match('%(2 slots changed%)') ~= nil, true);
    check('RPT34c the block explains "left as worn" ONCE, naming both causes',
        wsb:match('its set does not name them') ~= nil
        and wsb:match('level, job, or you') ~= nil, true);
    check('RPT34d ...exactly once, however many slots dropped',
        select(2, wsb:gsub('its set does not name them', '')), 1);
    check('RPT34e a block with nothing dropped says nothing about it',
        joined(RP._decLines(REC, tostring)):match('left as worn'), nil);

    -- ---------------------------------------------------------------------
    -- THE EMPTY BLOCK (field report 2, 2026-08-02). Six of 37 blocks in
    -- Henrik's full report were a header, a ctx line and nothing -- records
    -- the ring appended because the fingerprint MOVED, rendered as if nothing
    -- had. The fingerprint is items + winners, so a zero-change record is one
    -- where the WINNER moved, and the block was hiding exactly that.
    -- ---------------------------------------------------------------------
    local function recWith(seq, plan, explain, changed, nCh)
        return { seq = seq, time = '17:22:56', event = 'Default', action = 'idle',
                 plan = plan, changed = changed or {}, nChanged = nCh or 0,
                 contest = { explain = explain } };
    end
    local A = recWith(26, { Main = 'Harpoon' },
                      { main = { { name = 'Triggers', rank = 13, item = 'Harpoon' } } });
    local B = recWith(27, { Main = 'Harpoon' }, {});          -- same item, nobody owns it now

    local sh = RP._claimantShifts(A, B);
    check('RPT40a a slot that lost its owner is a shift', #sh, 1);
    check('RPT40b ...naming the slot',        sh[1].slot, 'main');
    check('RPT40c ...who had it',             sh[1].from, 'Triggers');
    check('RPT40d ...and that nobody does now', sh[1].to, nil);
    check('RPT40e the reverse direction is seen too',
        RP._claimantShifts(B, A)[1].to, 'Triggers');
    check('RPT40f a slot that did not change hands is NOT a shift',
        #RP._claimantShifts(A, A), 0);
    check('RPT40g a handover between two claimants is one shift, both named',
        (function()
            local C = recWith(28, { Main = 'Harpoon' },
                              { main = { { name = 'Locks', rank = 4, item = 'Harpoon' } } });
            local s2 = RP._claimantShifts(A, C);
            return #s2 .. ':' .. tostring(s2[1].from) .. '->' .. tostring(s2[1].to);
        end)(), '1:Triggers->Locks');
    -- NOTHING TO COMPARE AGAINST is not "everything changed hands": the first
    -- record of a capture has no predecessor, and calling every winner in it a
    -- shift printed sixteen redundant lines over rows that already said it
    check('RPT40h no previous record yields NO shifts',
        #RP._claimantShifts(nil, A), 0);
    check('RPT40i ...and neither does a predecessor with no contest',
        #RP._claimantShifts({ plan = {} }, A), 0);

    local blk0 = joined(RP._decLines(B, tostring, nil, A));
    check('RPT41a the zero-change block is NO LONGER empty',
        blk0:match('claim moved') ~= nil, true);
    check('RPT41b ...it names who lost the slot and that the item held',
        blk0:match('Main%s+Harpoon%s+claim moved: Triggers %-> %(nobody%)') ~= nil
        and blk0:match('the item did not change') ~= nil, true);
    -- a slot whose ITEM moved already tells its story; repeating it as a shift
    -- would count one event twice
    check('RPT41c a slot printed as changed is not ALSO printed as a shift',
        (function()
            local D = recWith(29, { Main = 'Lance' },
                              { main = { { name = 'Locks', rank = 4, item = 'Lance' } } },
                              { Main = true }, 1);
            return select(2, joined(RP._decLines(D, tostring, nil, A)):gsub('    Main ', ''));
        end)(), 1);
    -- "the item did not change" is CHECKED, never asserted. The first cut
    -- printed that sentence over a slot that had gone from nothing to Emperor
    -- Hairpin, because it trusted the record's `changed` map to be complete.
    local E = recWith(30, { Head = 'Emperor Hairpin' },
                      { head = { { name = 'Triggers', rank = 13, item = 'Emperor Hairpin' } } });
    local Eprev = recWith(29, {}, {});
    local blkE = joined(RP._decLines(E, tostring, nil, Eprev));
    check('RPT41e a shift whose ITEM also moved never claims it did not',
        blkE:match('the item did not change'), nil);
    check('RPT41f ...it shows the item transition instead',
        blkE:match('the item went %(nothing%) %-> Emperor Hairpin') ~= nil, true);
    check('RPT41g ...and reports that the record failed to list the slot as changed',
        blkE:match('did not list this slot as changed') ~= nil, true);
    check('RPT41h a genuine pure-claim shift still says the item held',
        joined(RP._decLines(B, tostring, nil, A)):match('the item did not change') ~= nil, true);

    -- and the last-resort line: a record that can show neither is a finding
    check('RPT41d a block that can show nothing SAYS so, rather than a bare header',
        joined(RP._decLines(recWith(30, { Main = 'Harpoon' }, {}), tostring, nil,
                            recWith(29, { Main = 'Harpoon' }, {})))
            :match('it should not be possible') ~= nil, true);

    -- ---------------------------------------------------------------------
    -- Field report 3 (2026-08-02): two engine oddities the report rendered as
    -- ordinary rows, so neither could be diagnosed from the artifact.
    -- ---------------------------------------------------------------------

    -- (i) AN ITEM WITH NO OWNER. The plan carries the piece and the contest
    -- names nobody -- the two halves of one record disagreeing about who
    -- decided the slot, which is the invariant ADR 0027 holds. Ear1 landed
    -- Optical Earring this way on a level-up and picked up its claimant two
    -- dispatches later.
    local ORPHAN = recWith(40, { Ear1 = 'Optical Earring' }, {}, { Ear1 = true }, 1);
    local orow = joined(RP._slotLines(ORPHAN, 'Ear1', tostring));
    check('RPT44a a planned item with no claimant is CALLED OUT',
        orow:match('NO CLAIMANT RECORDED') ~= nil, true);
    check('RPT44b ...saying which half says what',
        orow:match('the plan has it, the contest names nobody') ~= nil, true);
    check('RPT44c a slot with a winner is untouched by it',
        joined(RP._slotLines(A, 'Main', tostring)):match('NO CLAIMANT'), nil);

    -- A CLAIMANT'S OFFER IS NOT A PLANNED ITEM. The row used to print the
    -- winner's item when the plan did not name the slot, formatted exactly
    -- like a piece that went on -- which is why a level-sync weapon hold read
    -- as a normal equip for two rounds of field reports.
    local HELD = { seq = 43, time = '17:53:53', event = 'Default', plan = {},
                   changed = {}, nChanged = 0,
                   contest = { explain = { main = { { name = 'Triggers', rank = 13,
                                                      item = 'Bronze Spear +1' } } } } };
    local hrow = joined(RP._slotLines(HELD, 'Main', tostring));
    check('RPT46a an unplanned slot does not wear the claimant\'s item as if equipped',
        hrow:match('Bronze Spear %+1%s+<%-'), nil);
    check('RPT46b ...it reads as not placed',   hrow:match('%(not placed%)') ~= nil, true);
    check('RPT46c ...and says who wanted what', hrow:match('Triggers claimed this slot with Bronze Spear %+1') ~= nil, true);
    check('RPT46d ...and names the cause a reader can act on',
        hrow:match('level%-sync weapon hold') ~= nil, true);
    -- a defending SENTINEL is not gear and never was: it keeps reading as itself
    local SENT = { seq = 44, plan = {}, changed = {}, nChanged = 0,
                   contest = { explain = { main = { { name = 'Disabled', rank = 1,
                                                      item = '(free equip)' } } } } };
    check('RPT46e a claim sentinel still prints as itself',
        joined(RP._slotLines(SENT, 'Main', tostring)):match('%(free equip%)') ~= nil, true);
    check('RPT44d ...and so is a slot with no item at all',
        joined(RP._slotLines(recWith(41, {}, {}), 'Main', tostring)):match('NO CLAIMANT'), nil);

    -- (ii) WHAT IT CHANGED FROM. A record claiming a slot changed to the piece
    -- it already had read exactly like a real change, because the row showed
    -- only the new item -- so #3 of his log said Main and Sub changed while
    -- both carried the same items as #2, and the artifact could not show it.
    local WAS = recWith(42, { Main = 'Bronze Spear +1' },
                        { main = { { name = 'Triggers', rank = 13, item = 'Bronze Spear +1' } } },
                        { Main = true }, 1);
    local PREV_DIFF = recWith(41, { Main = 'Harpoon' },
                              { main = { { name = 'Triggers', rank = 13, item = 'Harpoon' } } });
    check('RPT45a a changed slot says what it changed FROM',
        joined(RP._slotLines(WAS, 'Main', tostring, PREV_DIFF)):match('was: Harpoon') ~= nil, true);
    check('RPT45b a slot that came from nothing says so',
        joined(RP._slotLines(WAS, 'Main', tostring, recWith(41, {}, {})))
            :match('was: %(nothing worn from a set%)') ~= nil, true);
    -- THE ANOMALY: same item, and the record still lists the slot as changed
    check('RPT45c an unchanged item under a "changed" flag is called out',
        joined(RP._slotLines(WAS, 'Main', tostring, WAS)):match('SAME ITEM, yet the record lists') ~= nil, true);
    check('RPT45d no previous record = no claim about what it was',
        joined(RP._slotLines(WAS, 'Main', tostring)):match('was:'), nil);
    -- a slot the record does NOT call changed must never get a "was:" line --
    -- that would invent an event out of a slot that simply held
    check('RPT45e an unchanged slot is never given a was: line',
        joined(RP._slotLines(A, 'Main', tostring, PREV_DIFF)):match('was:'), nil);

    -- the sets that produced the decision -- on every record already, and the
    -- report threw it away unless a ladder happened to print
    local SRC = recWith(31, { Main = 'Harpoon' },
                        { main = { { name = 'Triggers', rank = 13, item = 'Harpoon' } } },
                        { Main = true }, 1);
    SRC.contest.src = { main = 'Weapons', head = 'Idle', neck = 'Idle' };
    check('RPT42a the block names the sets it came from',
        joined(RP._decLines(SRC, tostring)):match('sets: Idle, Weapons') ~= nil, true);
    check('RPT42b ...deduplicated and sorted, so two reports diff',
        select(2, joined(RP._decLines(SRC, tostring)):gsub('Idle', '')), 1);
    check('RPT42c a record with no src says nothing about sets',
        joined(RP._decLines(A, tostring)):match('sets:'), nil);

    -- the action counter's LABEL (it only ever counted the anchors)
    local sma = joined(RP._summaryLines({ recorded = 60, nDec = 3, nAct = 0, nSend = 1,
                                          nChat = 0, marks = {} }));
    check('RPT43a the headline no longer says a bare "0 actions"',
        sma:match('0 action[s]?,') , nil);
    check('RPT43b ...it says what the count MEANS',
        sma:match('0 actions dispatched and moved NO gear') ~= nil, true);
    check('RPT43c ...and that the other kind is not counted twice',
        sma:match('never counted twice') ~= nil, true);

    -- ---------------------------------------------------------------------
    -- The SETS-FILE scope (the blind spot behind the same report): gear that
    -- never reached a plan or a ladder left no trace, and that is exactly the
    -- gear that failed to qualify.
    -- ---------------------------------------------------------------------
    local GEARTBL = {
        Head = { JaridahKhud = { Name = 'Jaridah Khud', Level = 55, Id = 1 },
                 Faceguard_1 = { Name = 'Faceguard +1', Level = 10, Id = 2 } },
        Main = { Polearm = { Harpoon = { Name = 'Harpoon', Level = 20, Id = 3 } } },
    };
    local SRC = [[
        Ws_Default = { Head = { gear.Head.JaridahKhud, gear.Head.Faceguard_1 } },
        Weapons = { Main = { gear.Main.Polearm.Harpoon } },
        Bogus = { Head = { gear.Head.NoSuchThing } },
    ]];
    local sn = RP._setItemNames(SRC, GEARTBL);
    check('RPT35a a set reference resolves to the DISPLAY name, not the identifier',
        sn['Faceguard +1'], true);
    check('RPT35b ...at any depth (Main/Range nest by weapon category)',
        sn['Harpoon'], true);
    check('RPT35c a reference to gear you have never indexed resolves to nothing',
        sn['NoSuchThing'], nil);
    check('RPT35d exactly the three real names came back',
        (sn['Jaridah Khud'] and sn['Faceguard +1'] and sn['Harpoon']) == true, true);

    -- THE FLATTEN-TIME REFUSAL, which no decision record can ever carry: the
    -- entry is filtered before the contest starts, so there is no ladder to
    -- strike through and no rung to explain. The digest says it instead.
    local BYLV = { ['Jaridah Khud'] = { Name = 'Jaridah Khud', Level = 55, Id = 1, Jobs = { 'DRG' } },
                   ['Faceguard +1'] = { Name = 'Faceguard +1', Level = 10, Id = 2, Jobs = { 'DRG' } } };
    local dlv = joined(RP._digestLines({ ['Jaridah Khud'] = true, ['Faceguard +1'] = true },
                                       BYLV, nil, 26));
    -- matched WITHIN a line: Lua's '.' spans newlines, and the rows are
    -- alphabetical, so a greedy match would happily run from one row to a flag
    -- on another and pass for the wrong reason
    check('RPT36a gear above the observed level is FLAGGED',
        dlv:match('Jaridah Khud[^\n]*ABOVE YOUR LEVEL %(26%)') ~= nil, true);
    check('RPT36b ...and gear at or under it is not',
        dlv:match('Faceguard %+1[^\n]*ABOVE') == nil, true);
    check('RPT36c no level known = no claim either way',
        joined(RP._digestLines({ ['Jaridah Khud'] = true }, BYLV, nil, nil)):match('ABOVE') == nil, true);

    -- the level comes from the RECORD, so a sync that lapsed before the report
    -- was written cannot rewrite what you were deciding under
    local lst = {};
    RP._noteLevel(lst, { ctx = { job = 'DRG', jobLevel = 26 } });
    check('RPT37a the job and level are taken off the record', lst.job .. lst.level, 'DRG26');
    RP._noteLevel(lst, { ctx = {} });
    check('RPT37b a record without them leaves the last known alone', lst.level, 26);
    RP._noteLevel(lst, nil);
    check('RPT37c ...and so does no record at all', lst.level, 26);

    -- ---------------------------------------------------------------------
    -- The engine verdict FOR THE FILE. check._lines tells the reader that a
    -- "[dlac] check (engine): alive" line must appear -- true in chat, and
    -- impossible in this file, so every report accused a healthy engine.
    -- ---------------------------------------------------------------------
    check('RPT38a agreement is stated as an armed engine',
        joined(RP._engineLines({ fileV = 162, stampV = 162 })):match('AGREED, so the engine is armed') ~= nil, true);
    check('RPT38b ...and the reader is told not to hunt for the chat line',
        joined(RP._engineLines({ fileV = 162, stampV = 162 })):match('CHAT%-only') ~= nil, true);
    check('RPT38c a behind stamp names WHICH side is behind',
        joined(RP._engineLines({ fileV = 162, stampV = 160 })):match('STAMP IS BEHIND') ~= nil, true);
    check('RPT38d an ahead stamp says the tree is stale',
        joined(RP._engineLines({ fileV = 160, stampV = 162 })):match('addon tree is stale') ~= nil, true);
    check('RPT38e a missing stamp is inconclusive, not a verdict',
        joined(RP._engineLines({ fileV = 162 })):match('INCONCLUSIVE') ~= nil, true);

    -- the send line said the same thing twice
    check('RPT39a a cause that already says it is not annotated again',
        RP._passTag('passed through (your own action)', true), '');
    check('RPT39b a cause that does not IS annotated',
        RP._passTag('Precast (set)', true):match('passed through') ~= nil, true);
    check('RPT39c dlac\'s own sends are never annotated', RP._passTag('Precast (set)', false), '');

    -- the digest's SCOPE is the whole point: exactly the items whose gear
    -- facts can explain what the record did
    local names = RP._itemNames(REC);
    check('RPT11a the plan is in scope',        names['Nahtirah Hat'], true);
    check('RPT11b the ladder rungs are too',    names['Chapeau'],      true);
    check('RPT11c a losing claimant\'s offer is in scope',
        names['Zenith Crown'], true);
    check('RPT11d the "remove" literal is NOT an item', names['remove'], nil);
    local names2 = RP._itemNames({ plan = { Head = '(free equip)' } });
    check('RPT11e a claim sentinel is NOT an item', next(names2), nil);

    -- the digest itself
    local BY = { ['Nahtirah Hat'] = { Name = 'Nahtirah Hat', Id = 18863, Level = 75,
                                      Jobs = { 'WHM', 'BLM' } } };
    local dg = joined(RP._digestLines({ ['Nahtirah Hat'] = true, ['Chapeau'] = true }, BY,
        function(n) return n == 'Nahtirah Hat'; end));
    check('RPT12a a known item carries id, level and jobs',
        dg:match('Nahtirah Hat%s+id 18863%s+lv 75') ~= nil, true);
    check('RPT12b availability is the answer "unavail" needs',
        dg:match('IN BAGS') ~= nil, true);
    check('RPT12c an item nobody indexed is CALLED OUT, not omitted',
        dg:match('is not in gear%.lua at all') ~= nil and dg:match('Chapeau') ~= nil, true);
    check('RPT12d no availability source = no claim (never a wrong guess)',
        joined(RP._digestLines({ ['Nahtirah Hat'] = true }, BY, nil)):match('BAGS') == nil, true);

    -- the budget walk. NO SILENT CAPS: every exclusion comes back with a
    -- reason, because a truncated bundle that reads as complete is the one
    -- failure mode that costs a whole support round.
    local FILES = {
        { label = 'sets\\BLU.lua',  size = 38000, always = true },
        { label = 'gearweights.lua', size = 46000 },
        { label = 'modes.lua',      size = 400 },
        -- always=true bypasses the PER-FILE cap but never the budget: the
        -- ceiling is the one thing nothing gets to walk past.
        { label = 'huge.lua',       size = 900000, always = true },
    };
    local taken, skipped, used = RP._pick(FILES, 100000, 32768);
    local tl = {};
    for _, f in ipairs(taken) do tl[f.label] = true; end
    check('RPT13a the active job\'s sets file bypasses the per-file cap',
        tl['sets\\BLU.lua'], true);
    check('RPT13b a big optional file is skipped', tl['gearweights.lua'], nil);
    check('RPT13c a small one rides',              tl['modes.lua'],      true);
    check('RPT13d everything skipped is REPORTED', #skipped,             2);
    check('RPT13e ...with a reason a reader can act on',
        skipped[1].why:match('per%-file cap') ~= nil, true);
    check('RPT13f the budget is a hard ceiling',
        skipped[2].why:match('budget was full') ~= nil, true);
    check('RPT13g used is the bundled total',      used,                 38400);

    -- the manifest: what EXISTS, bundled or not, so a wrongly-scoped digest
    -- costs one follow-up instead of a lost session
    local mf = joined(RP._manifestLines({
        { label = 'gear.lua', size = 264111 },
        { label = 'modes.lua', size = 400, bundled = true } }));
    check('RPT14a an unbundled file is still listed',  mf:match('264111  gear%.lua') ~= nil, true);
    check('RPT14b a bundled one says so',              mf:match('%[bundled above%]') ~= nil, true);
    check('RPT14c an unlistable folder says that, rather than looking empty',
        joined(RP._manifestLines({})):match('could not be listed') ~= nil, true);

    -- the header's privacy paragraph is not optional furniture: it is what
    -- makes "send this file" an informed act
    local hdr = joined(RP._header({ char = 'Mindie', addonVer = '2026.08.03a', full = false,
                                    job = 'BLU', startedAt = 100, endedAt = 400,
                                    requested = 300, recorded = 300 }));
    check('RPT15a the character is named',       hdr:match('dlac support report %-%- Mindie') ~= nil, true);
    check('RPT15b the scope is stated',          hdr:match('scope: active job %(BLU%)') ~= nil, true);
    check('RPT15c what is in the file is stated', hdr:match('WHAT IS IN THIS FILE') ~= nil, true);
    check('RPT15d ...including that chat is dlac\'s own only',
        hdr:match('no tells, no party chat') ~= nil, true);
    check('RPT15e ...and that nothing leaves the machine by itself',
        hdr:match('Nothing here is sent anywhere on its own') ~= nil, true);
    check('RPT15f a full run says so',
        joined(RP._header({ full = true })):match('scope: FULL') ~= nil, true);

    -- the summary: the numbers and the marks, above the log
    local sm = joined(RP._summaryLines({ recorded = 300, nDec = 41, nAct = 12, nSend = 6,
        nChat = 9, nErr = 2, nPre = 7, marks = { { at = 134, note = 'gear did not swap' } } }));
    check('RPT16a the window is counted',   sm:match('41 decisions, 6 sends') ~= nil, true);
    check('RPT16a2 ...and the anchors are counted APART, with what they mean',
        sm:match('12 actions dispatched and moved NO gear') ~= nil, true);
    -- The pre-roll is counted APART. A summary reading "0 decisions" over a log
    -- that visibly contains one teaches the reader to distrust the numbers.
    check('RPT16b pre-roll decisions are counted, and separately',
        sm:match('plus 7 decisions already in memory') ~= nil, true);
    check('RPT16c failure lines are flagged for the reader',
        sm:match('2 of those chat lines look like FAILURES') ~= nil, true);
    check('RPT16d a mark carries its offset and the player\'s words',
        sm:match('%+2:14   gear did not swap') ~= nil, true);
    check('RPT16e no marks says so, and says how to leave one',
        joined(RP._summaryLines({ marks = {} })):match('/dl mark <note>') ~= nil, true);
    -- singulars, because a support file that says "1 decisions" reads as a
    -- machine that is not paying attention
    local one = joined(RP._summaryLines({ recorded = 60, nDec = 1, nAct = 1, nSend = 1,
        nChat = 1, nErr = 1, marks = { { at = 0 } } }));
    check('RPT16f one of each reads as one',
        one:match('1 decision, 1 send, 1 dlac chat line, 1 mark') ~= nil, true);
    check('RPT16f2 ...including the anchor line',
        one:match('1 action dispatched and moved NO gear') ~= nil, true);
    check('RPT16g ...including the failure sentence',
        one:match('1 of those chat lines looks like a FAILURE') ~= nil, true);
    check('RPT16h a zero pre-roll says nothing at all',
        one:match('already in memory') == nil, true);

    -- the action anchor: "I did a thing and gear did NOT move" has no
    -- decision to point at, which is exactly why the feed exists
    check('RPT17 an action that moved nothing says so',
        RP._actLine({ at = 0, event = 'Precast', ctx = { action = 'Cure IV' } }):match('NO gear change') ~= nil, true);

    -- the seeded engine copies in the data home are CODE, not settings
    check('RPT18a gear.lua is never bundled raw by default', RP.CODE_FILES['gear.lua'],  true);
    check('RPT18b nor is the seeded engine',                 RP.CODE_FILES['dispatch.lua'], true);
    check('RPT18c but a settings file is not code',          RP.CODE_FILES['modes.lua'], nil);

    -- ---------------------------------------------------------------------
    -- THE ASSEMBLY, end to end, against an in-memory tree (M._fs). The pure
    -- seams above pin the parts; this pins the thing a player actually sends
    -- -- which files were chosen, what the file SAYS about the ones it left
    -- out, and the promise in the header being true of the bytes.
    -- ---------------------------------------------------------------------
    local TREE = {
        ['D\\gear.lua']        = string.rep('x', 264000),   -- the elephant
        ['D\\dispatch.lua']    = string.rep('x', 355000),   -- seeded CODE
        ['D\\gearweights.lua'] = string.rep('x', 46000),    -- over the per-file cap
        ['D\\modes.lua']       = 'return { Town = true }',
        ['D\\profile.lua']     = 'return { active = "Default" }',
        ['D\\P\\Default\\sets\\BLU.lua']     = string.rep('s', 38000),  -- over the cap, but ALWAYS
        ['D\\P\\Default\\sets\\WHM.lua']     = string.rep('w', 26000),  -- another job
        ['D\\P\\Default\\triggers\\BLU.lua'] = 'return { rules = {} }',
    };
    local savedFs = RP._fs;
    local written = nil;
    RP._fs = {
        read = function(p) return TREE[p]; end,
        size = function(p) return TREE[p] ~= nil and #TREE[p] or nil; end,
        list = function(path)
            local seen, out = {}, {};
            for k in pairs(TREE) do
                local rest = k:match('^' .. path:gsub('%p', '%%%0') .. '(.+)$');
                if rest ~= nil then
                    local first = rest:match('^([^\\]+)');
                    if first ~= nil and not seen[first] then seen[first] = true; out[#out + 1] = first; end
                end
            end
            table.sort(out);
            return out;
        end,
        profiles = function()
            return {
                KINDS = { 'sets', 'triggers', 'lockstyles' },
                dataDir      = function() return 'D\\'; end,
                profilesRoot = function() return 'D\\P\\'; end,
                activeName   = function() return 'Default'; end,
                setsPath     = function(j) return 'D\\P\\Default\\sets\\' .. j .. '.lua'; end,
                triggersPath = function(j) return 'D\\P\\Default\\triggers\\' .. j .. '.lua'; end,
                lockstylesPath = function(j) return 'D\\P\\Default\\lockstyles\\' .. j .. '.lua'; end,
            };
        end,
        out   = function() return 'OUT.txt'; end,
        write = function(_, text) written = text; end,
    };
    local savedGD = gData;
    gData = { GetPlayer = function() return { MainJob = 'BLU' }; end };

    local ST = { char = 'Testchar', full = false, startedAt = 100, endedAt = 400,
                 requested = 300, recorded = 300, path = 'LOG',
                 nDec = 2, nAct = 1, nSend = 4, nChat = 3, nErr = 1, nPre = 5,
                 marks = { { at = 61, note = 'head did not swap' } },
                 names = { ['Nahtirah Hat'] = true } };
    TREE['LOG'] = '[12:00:00] #1 Default -- idle   (1 slot changed)\n';
    local wpath = RP._write(ST);
    check('RPT20 the report writes', wpath, 'OUT.txt');
    local W = tostring(written or '');

    check('RPT21a every section is present',
        W:match('SECTION: health') ~= nil and W:match('SECTION: summary') ~= nil
        and W:match('SECTION: config') ~= nil and W:match('SECTION: gear digest') ~= nil
        and W:match('SECTION: log') ~= nil and W:match('SECTION: manifest') ~= nil, true);
    check('RPT21b it terminates, so a truncated send is visible',
        W:match('===== END REPORT =====$') ~= nil, true);

    -- the scope decisions, which are the whole design
    check('RPT22a the active job\'s sets ride whole despite the per-file cap',
        W:match('FILE: profiles\\Default\\sets\\BLU%.lua %(38000 bytes%)') ~= nil, true);
    check('RPT22b ...and its triggers',
        W:match('FILE: profiles\\Default\\triggers\\BLU%.lua') ~= nil, true);
    check('RPT22c a small settings file rides',  W:match('FILE: modes%.lua') ~= nil, true);
    check('RPT22d ANOTHER job is not bundled by default',
        W:match('FILE: profiles\\Default\\sets\\WHM%.lua') == nil, true);
    check('RPT22e raw gear.lua is not bundled by default',
        W:match('FILE: gear%.lua') == nil, true);
    check('RPT22f seeded ENGINE CODE is never bundled',
        W:match('FILE: dispatch%.lua') == nil, true);

    -- and nothing is dropped silently -- the one failure mode that costs a
    -- whole support round, because a truncated bundle reads as a complete one
    check('RPT23a an over-cap file is named with its reason',
        W:match('gearweights%.lua %(46000 bytes%) %-%- over the') ~= nil, true);
    check('RPT23b gear.lua\'s absence is EXPLAINED, not just true',
        W:match('gear%.lua %-%- the bag index') ~= nil, true);
    check('RPT23c ...and so is the code files\'',
        W:match('seeded ENGINE CODE, not settings') ~= nil, true);
    check('RPT23d ...and the other jobs\', with the way to get them',
        W:match('"/dl report full" bundles every job') ~= nil, true);
    check('RPT23e everything unbundled is still in the manifest',
        W:match('264000  gear%.lua') ~= nil and W:match('26000  profiles\\Default\\sets\\WHM%.lua') ~= nil, true);

    -- the log is folded in, pre-roll and all
    check('RPT24 the live log is inlined', W:match('#1 Default %-%- idle') ~= nil, true);

    -- FULL widens exactly the three things it promises, and nothing else
    ST.full = true;
    RP._write(ST);
    local F = tostring(written or '');
    check('RPT25a full bundles the other job',
        F:match('FILE: profiles\\Default\\sets\\WHM%.lua') ~= nil, true);
    check('RPT25b full bundles raw gear.lua',  F:match('FILE: gear%.lua') ~= nil, true);
    check('RPT25c full still refuses engine CODE',
        F:match('FILE: dispatch%.lua') == nil, true);
    -- "full" has to be a word that is true: the per-file cap is a scoping
    -- device for the DEFAULT run, not a second ceiling inside an explicit ask
    check('RPT25f full bundles a file the default run capped out',
        F:match('FILE: gearweights%.lua') ~= nil, true);
    check('RPT25g ...so nothing is left to report as skipped',
        F:match('NOT BUNDLED') == nil, true);
    check('RPT25d full drops the "left out on purpose" note (nothing was)',
        F:match('left out ON PURPOSE') == nil, true);
    check('RPT25e the header says which scope produced the file',
        F:match('scope: FULL') ~= nil, true);

    RP._fs = savedFs;
    gData = savedGD;

    -- ---------------------------------------------------------------------
    -- MARKS: one moment, one mark (field round 1, 2026-08-02 -- Henrik could
    -- mark the same event several times, and a mark list is a reader's INDEX,
    -- so a doubled entry costs exactly what marks are for).
    -- ---------------------------------------------------------------------
    local savedDsp = package.loaded['dlac\\dispatch'];
    package.loaded['dlac\\dispatch'] = { getDecisions = function() return {}; end,
                                         getActions = function() return {}; end };
    -- The live log is drained by pump(), so the timeline is captured off the
    -- append seam rather than off the pending queue.
    local savedAppend, LOGGED = RP._fs.append, {};
    RP._fs.append = function(_, text) LOGGED[#LOGGED + 1] = text; end
    local function freshCapture()
        LOGGED = {};
        RP.st = { startedClk = os.clock(), endsClk = os.clock() + 300, path = 'LOG',
                  lastSeq = 7, lastASeq = 0, q = {}, marks = {}, names = {},
                  nDec = 0, nAct = 0, nSend = 0, nChat = 0, nErr = 0, full = false };
        return RP.st;
    end

    local cap = freshCapture();
    local ok1, what1 = RP.mark('gear did not swap');
    check('RPT26a the first mark on a moment is added', ok1 and what1, 'added');
    check('RPT26b ...and binds to the decision it was placed at', cap.marks[1].seq, 7);
    check('RPT26c the button now knows the moment is marked', RP.markState() ~= nil, true);
    check('RPT26d ...and status says so, for the label',        RP.status().marked, true);

    -- pressing again does NOT double it
    local ok2, what2 = RP.mark('still did not swap');
    check('RPT27a a second mark on the SAME moment replaces', ok2 and what2, 'replaced');
    check('RPT27b ...so the index still holds one',           #cap.marks, 1);
    check('RPT27c ...with the latest words',                  cap.marks[1].note, 'still did not swap');

    -- un-mark clears it
    check('RPT28a un-mark removes the current mark', RP.unmark(), true);
    check('RPT28b ...so the index is empty',         #cap.marks, 0);
    check('RPT28c ...and the button goes back to Mark', RP.markState(), nil);
    check('RPT28d un-marking nothing is a no-op, not an error', RP.unmark(), false);

    -- a NEW decision is a new moment: the next mark appends beside the old one
    cap = freshCapture();
    RP.mark('first');
    cap.lastSeq = 8;                       -- the ring moved on
    check('RPT29a the old mark is no longer "current"', RP.markState(), nil);
    local ok3, what3 = RP.mark('second');
    check('RPT29b ...so a new moment APPENDS rather than replacing', ok3 and what3, 'added');
    check('RPT29c ...and both marks survive', #cap.marks, 2);
    check('RPT29d ...in order',               cap.marks[1].note .. '/' .. cap.marks[2].note, 'first/second');

    -- THE EVIDENCE RULE: un-mark must never reach back past the current
    -- moment and delete a mark the player set against a DIFFERENT event
    cap.lastSeq = 9;
    check('RPT30a un-mark refuses once the moment has moved on', RP.unmark(), false);
    check('RPT30b ...leaving both marks intact',                 #cap.marks, 2);

    -- the log is append-only: a replace and a removal each add their own line
    -- rather than rewriting history
    cap = freshCapture();
    RP.mark('one'); RP.mark('two'); RP.unmark();
    local logged = table.concat(LOGGED, '');
    check('RPT31a the placement is in the timeline',  logged:match('%*%*%*%*%* MARK %+') ~= nil, true);
    check('RPT31b so is the replacement, with the words it replaced',
        logged:match('MARK REPLACED.*%(was: one%)') ~= nil, true);
    check('RPT31c so is the removal',
        logged:match('MARK REMOVED %(was %+.*two%)') ~= nil, true);

    -- the summary links a mark to the decision block it points at
    check('RPT32a a mark carries its decision number into the summary',
        joined(RP._summaryLines({ marks = { { at = 5, note = 'x', seq = 42 } } })):match('at decision #42') ~= nil, true);
    check('RPT32b ...and says so plainly when there is no decision to point at',
        joined(RP._summaryLines({ marks = { { at = 5, note = 'x', seq = 0 } } })):match('%(no decision yet%)') ~= nil, true);

    RP.st = nil;
    RP._fs.append = savedAppend;
    package.loaded['dlac\\dispatch'] = savedDsp;

    -- the observer seam sendlog grew for this (an uncounted send is the only
    -- way "dlac sent nothing" could lie -- an unobserved one is the only way
    -- the report's timeline could)
    local SL2 = dofile('feature/sendlog.lua');
    local seen = {};
    SL2.observer = function(id, why, pass) seen[#seen + 1] = { id = id, why = why, pass = pass }; end
    SL2.note(0x50, 'Precast (set, 2 slots)');
    check('RPT19a the observer hears the send',     #seen, 1);
    check('RPT19b ...with the cause the site knew', seen[1].why, 'Precast (set, 2 slots)');
    SL2.observer = function() error('an observer must not break the send'); end
    check('RPT19c a throwing observer cannot break the counter it rides',
        SL2.note(0x51, 'x'), true);
    SL2.observer = nil;
end)();

-- ---------------------------------------------------------------------------
-- NM. /dl nm -- the NM/placeholder lookup (feature\nmlookup, 2026-08-03).
--
--   Henrik: "it would be nice to give you an NM name, and you can look up the
--   place holder IDs and even indexes if possible and give me a filterscan
--   filter I can apply."
--
--   Two things are under test and they fail differently:
--     * the LOOKUP CODE (runs/score/match/render) -- ordinary logic, and
--     * the SHIPPED TABLE (data\nmdata.lua) -- regenerated by a python script
--       against a server clone. A bad regeneration is silent at runtime, so
--       the hand-verified camps below are pinned as data tripwires: Bonnacon
--       and Shadow Eye were read out of the clone by hand (mob_spawn_points +
--       phList) before any of this was written.
-- ---------------------------------------------------------------------------
(function()
    local savedChat = package.loaded['dlac\\chatfmt'];
    local out = {};
    local function sink(s) out[#out + 1] = tostring(s); end
    package.loaded['dlac\\chatfmt'] = { msg = sink, good = sink, warn = sink, err = sink };
    package.loaded['dlac\\data\\nmdata'] = dofile('data/nmdata.lua');

    local handler = nil;
    local savedReg = ashita.events.register;
    ashita.events.register = function(evt, name, fn)
        if name == 'dlac-nmlookup-cmd' then handler = fn; end
    end;
    local NM = dofile('feature/nmlookup.lua');
    ashita.events.register = savedReg;

    local function joined() return table.concat(out, '\n'); end
    local function run(cmd)
        out = {};
        local e = { command = cmd, blocked = false };
        handler(e);
        return e, joined();
    end

    -- ---- index-run formatting -------------------------------------------
    check('NM01a a contiguous block collapses',   NM.runs({ 354, 355, 356, 357, 358, 359 }), '354-359');
    check('NM01b a gap survives',                 NM.runs({ 73, 75, 76, 77 }), '73, 75-77');
    check('NM01c two in a row is still a range',  NM.runs({ 270, 271 }), '270-271');
    check('NM01d one is one',                     NM.runs({ 73 }), '73');
    check('NM01e unsorted input is sorted first', NM.runs({ 359, 354, 356, 355, 358, 357 }), '354-359');
    check('NM01f nothing renders as nothing',     NM.runs({}), '');

    check('NM02a a whole hour is plain',   NM.fmtDur(3600), '1h');
    check('NM02b 24h stays 24h',           NM.fmtDur(86400), '24h');
    check('NM02c 21h (Bloodtear window)',  NM.fmtDur(75600), '21h');
    check('NM02d sub-hour falls to minutes', NM.fmtDur(300), '5m');

    -- ---- the shipped table: hand-verified camps --------------------------
    -- Bonnacon, Uleguerand Range (zone 5): six contiguous Buffalo at 354-359,
    -- NM at 360, 5% per PH death, 1-24h before it can pop again.
    local bon = select(1, NM.matchInZone(5, 'Bonnacon'));
    check('NM10a Bonnacon is in zone 5',       bon ~= nil, true);
    check('NM10b ...NM index',                 NM.runs(bon.nm), '360');
    check('NM10c ...six placeholders',         #bon.ph, 6);
    check('NM10d ...contiguous 354-359',       NM.runs(bon.ph), '354-359');
    check('NM10e ...which are Buffalo',        bon.p, 'Buffalo');
    -- 5% is the BASE, not the rate: disfavour lifts it every round (NM40*/NM41*).
    check('NM10f ...a 5% base chance',         bon.c, 5);
    check('NM10g ...1h-24h window',            string.format('%d-%d', bon.w[1], bon.w[2]), '3600-86400');
    -- Shadow Eye, Xarcabard (112): one Evil Eye at NM-6.
    local se = select(1, NM.matchInZone(112, 'Shadow Eye'));
    check('NM11a Shadow Eye is in zone 112',   se ~= nil, true);
    check('NM11b ...NM index 212',             NM.runs(se.nm), '212');
    check('NM11c ...one PH at 206',            NM.runs(se.ph), '206');
    check('NM11d ...an Evil Eye',              se.p, 'Evil Eye');

    -- ---- the filter string ------------------------------------------------
    -- Decimal, comma separated, PHs then the NM -- exactly what FilterScan's
    -- `v == tostring(tidx)` arm matches on.
    check('NM12a the filter is PHs + the NM',
        NM.filterFor(bon), '354,355,356,357,358,359,360');
    check('NM12b a no-placeholder NM still filters on itself',
        NM.filterFor({ n = 'x', nm = { 217 } }), '217');
    check('NM12c duplicates collapse',
        NM.filterFor({ n = 'x', nm = { 5 }, ph = { 5, 4 } }), '4,5');
    check('NM12d nothing to filter on is nil',
        NM.filterFor({ n = 'x' }), nil);

    -- ---- fuzzy matching ---------------------------------------------------
    check('NM20a exact beats everything',      NM.score('Bonnacon', 'Bonnacon'), 1000);
    check('NM20b case does not matter',        NM.score('bOnNaCoN', 'Bonnacon'), 1000);
    check('NM20c an apostrophe does not matter', NM.score('nantina', "Nant'ina"), 1000);
    check('NM20d a prefix scores below exact but high',
        NM.score('bonn', 'Bonnacon') > 800, true);
    check('NM20e a one-letter typo still lands',
        NM.score('bonacon', 'Bonnacon') > 0, true);
    check('NM20f words in any order match',
        NM.score('baldarich steelfleece', 'Steelfleece Baldarich') >= 700, true);
    check('NM20g gibberish scores zero',       NM.score('zzzznothing', 'Bonnacon'), 0);
    check('NM20h an empty query scores zero',  NM.score('', 'Bonnacon'), 0);

    -- Nyzul Isle (77) and the Dynamis zones carry same-named copies with no
    -- placeholders. A tie must resolve to the open-world camp -- the one this
    -- command can actually hand you a filter for.
    local liz, lizScore, lizZone = NM.matchAnywhere('Leaping Lizzy');
    check('NM21a Leaping Lizzy resolves to South Gustaberg, not Nyzul',
        lizZone, 107);
    check('NM21b ...with both PH groups',      NM.runs(liz.ph), '379, 399');
    check('NM21c ...and both NM spots',        NM.runs(liz.nm), '380, 400');
    local sea, _, seaZone = NM.matchAnywhere('Shadow Eye');
    check('NM21d Shadow Eye resolves to Xarcabard, not Nyzul', seaZone, 112);
    check('NM21e ...and it is the one with the placeholder', #sea.ph, 1);

    -- ---- the command, driven for real -------------------------------------
    NM.zoneReader = function() return 5; end;

    local e1, t1 = run('/dl nm bonnacon');
    check('NM30a the command is blocked',      e1.blocked, true);
    check('NM30b it names the NM and zone',    t1:match('Bonnacon %-%- Uleguerand Range') ~= nil, true);
    check('NM30c it names the placeholder',    t1:match('Buffalo x6') ~= nil, true);
    check('NM30d it gives the ready filter',
        t1:match('/filterscan 354,355,356,357,358,359,360') ~= nil, true);
    check('NM30e an exact hit is not hedged',
        t1:match('closest match') == nil, true);

    local _, t2 = run('/dl nm');
    check('NM31a bare lists the zone',         t2:match('Uleguerand Range %-%- 14 NM') ~= nil, true);
    check('NM31b ...the ones with placeholders', t2:match('Bonnacon') ~= nil, true);
    check('NM31c ...and says which have none rather than hiding them',
        t2:match('no placeholders') ~= nil and t2:match('Jormungand') ~= nil, true);

    -- A name that is not in this zone answers about the right zone instead of
    -- dead-ending -- the indexes travel with you.
    local _, t3 = run('/dl nm shadow eye');
    check('NM32a it says the NM is elsewhere',
        t3:match('not in Uleguerand Range') ~= nil, true);
    check('NM32b ...and names where',          t3:match('Xarcabard') ~= nil, true);
    check('NM32c ...with that zone\'s filter', t3:match('/filterscan 206,212') ~= nil, true);

    -- Guessing across 221 zones from gibberish is worse than saying no.
    local _, t4 = run('/dl nm zzzznothing');
    check('NM33a gibberish is refused',        t4:match('nothing resembling') ~= nil, true);
    check('NM33b ...and no filter is offered', t4:match('/filterscan') == nil, true);

    -- A weak but real in-zone guess is shown AND labelled as a guess.
    local _, t5 = run('/dl nm bonacon');
    check('NM34a a typo still finds it',       t5:match('Bonnacon') ~= nil, true);
    check('NM34b ...but says it is a guess',   t5:match('closest match') ~= nil, true);

    -- Pre-login / mid-zone: never answer about a zone we cannot read.
    NM.zoneReader = function() return nil; end;
    local _, t6 = run('/dl nm');
    check('NM35a an unknown zone is admitted, not guessed',
        t6:match('cannot read your zone') ~= nil, true);
    -- ...but a named lookup still works, because the name carries the zone.
    local _, t7 = run('/dl nm bonnacon');
    check('NM35b a named lookup still answers without a zone read',
        t7:match('/filterscan 354,355,356,357,358,359,360') ~= nil, true);
    NM.zoneReader = function() return 5; end;

    -- ---- routing ----------------------------------------------------------
    local e8 = { command = '/dl unused', blocked = false };
    handler(e8);
    check('NM36a another /dl verb is left alone', e8.blocked, false);
    local e9 = { command = '/dl ph bonnacon', blocked = false };
    handler(e9);
    check('NM36b the ph alias works', e9.blocked, true);

    -- `apply` queues the filter for FilterScan. Headless there is no chat
    -- manager, so this also pins that a failed send SAYS SO and still leaves
    -- the pasteable line above it -- it must never look like it worked.
    local sent = nil;
    local savedCore = AshitaCore;
    AshitaCore = { GetChatManager = function()
        return { QueueCommand = function(_, _, cmd) sent = cmd; end };
    end };
    local _, t11 = run('/dl nm bonnacon apply');
    check('NM38a apply queues the filterscan command',
        sent, '/filterscan 354,355,356,357,358,359,360');
    check('NM38b ...and says so',              t11:match('applied') ~= nil, true);
    check('NM38c ...without eating the NM name', t11:match('Bonnacon') ~= nil, true);
    AshitaCore = nil;
    local _, t12 = run('/dl nm bonnacon apply');
    check('NM38d no chat manager -> admits it could not send',
        t12:match('could not send') ~= nil, true);
    check('NM38e ...and still prints the line to paste',
        t12:match('/filterscan 354,355,356,357,358,359,360') ~= nil, true);
    AshitaCore = savedCore;

    -- `apply` with no NM named: a zone list is not one camp, so the word is
    -- answered rather than silently dropped.
    local _, t13 = run('/dl nm apply');
    check('NM39a bare apply still lists the zone',
        t13:match('Uleguerand Range %-%- 14 NM') ~= nil, true);
    check('NM39b ...and says there was nothing to apply',
        t13:match('nothing to apply') ~= nil, true);
    check('NM39c ...and does not hunt for an NM called "apply"',
        t13:match('closest match') == nil, true);

    -- ---- the disfavour curve (issue #152) ---------------------------------
    --
    --   THESE TESTS ARE THE SOURCE. CatsEyeXI's disfavour system (bad-luck
    --   protection on lottery pops) exists in NO branch of the public server
    --   repository -- it lives in the private `catseyexi` overlay, which is
    --   empty publicly -- so the formula is HAND-CARRIED in nmlookup.lua and
    --   these checks stand in for the source it cannot be derived from.
    --
    --       rounds = phKills / phCount
    --       chance = 100 / max( (100/base) - rounds * (1 - base/100) / 2, 1 )
    --
    --   Four anchors were published with the mechanic and all four are pinned
    --   below. Anchors ALONE are not enough: they only fix the point where the
    --   curve reaches 100%, and several wrong formulas hit that point too. So
    --   the MIDDLE is pinned as well -- a dropped `/2`, a flipped sign or a
    --   base/100 read as base all move the mid-curve values while some of them
    --   leave an endpoint intact.
    -- -----------------------------------------------------------------------

    -- Compared to 4 decimals: fine enough that any of those slips fails, coarse
    -- enough to be immune to last-bit differences between interpreters.
    local function pct4(x) return string.format('%.4f', x); end

    -- The published anchors, written out here rather than read from the module,
    -- so the constant and the code are pinned to the SAME external fact.
    local PUBLISHED = { { 5, 40 }, { 10, 20 }, { 15, 14 }, { 20, 10 } };
    for _, a in ipairs(PUBLISHED) do
        local base, rounds = a[1], a[2];
        check(string.format('NM40 base %d%% is guaranteed after %d rounds', base, rounds),
            NM.roundsToGuaranteed(base), rounds);
        check(string.format('NM40 ...and %d rounds reads exactly 100%%', rounds),
            pct4(NM.chanceAfter(base, rounds)), '100.0000');
        -- The anchor is the FIRST guaranteed round, not merely a late one.
        check(string.format('NM40 ...while %d rounds is not there yet', rounds - 1),
            NM.chanceAfter(base, rounds - 1) < 100, true);
    end
    check('NM40e the constant records all four anchors', #NM.DISFAVOUR.anchors, 4);
    for i, a in ipairs(PUBLISHED) do
        check(string.format('NM40f anchor %d base', i),   NM.DISFAVOUR.anchors[i].base, a[1]);
        check(string.format('NM40g anchor %d rounds', i), NM.DISFAVOUR.anchors[i].rounds, a[2]);
    end

    -- Mid-curve. NM41d is the figure the PRD quotes back at the player ("30
    -- rounds in they are at 17%") and NM41e is the near-vertical end that made
    -- printing the base alone misleading in the first place.
    check('NM41a base 5% at 0 rounds is the base itself',  pct4(NM.chanceAfter(5, 0)),   '5.0000');
    check('NM41b base 5% at 10 rounds has already moved',  pct4(NM.chanceAfter(5, 10)),  '6.5574');
    check('NM41c base 5% at 20 rounds (halfway)',          pct4(NM.chanceAfter(5, 20)),  '9.5238');
    check('NM41d base 5% at 30 rounds -- the published ~17%',
        pct4(NM.chanceAfter(5, 30)),  '17.3913');
    check('NM41e base 5% at 39 rounds -- near-vertical',   pct4(NM.chanceAfter(5, 39)),  '67.7966');
    check('NM41f base 10% at 10 rounds',                   pct4(NM.chanceAfter(10, 10)), '18.1818');
    check('NM41g base 15% at 7 rounds',                    pct4(NM.chanceAfter(15, 7)),  '27.0880');
    check('NM41h base 20% at 5 rounds',                    pct4(NM.chanceAfter(20, 5)),  '33.3333');

    local rose, fell = true, false;
    local prevChance = NM.chanceAfter(5, 0);
    for r = 1, 40 do
        local c = NM.chanceAfter(5, r);
        if c <= prevChance then rose = false; end
        if c < prevChance then fell = true; end
        prevChance = c;
    end
    check('NM41i the curve rises on every single round',   rose, true);
    check('NM41j ...and never falls back',                 fell, false);

    -- Clamps and the guards around a base the table does not carry.
    check('NM42a past the guarantee it stays at 100%',     pct4(NM.chanceAfter(5, 41)), '100.0000');
    check('NM42b a negative round count reads as none',
        pct4(NM.chanceAfter(5, -3)), pct4(NM.chanceAfter(5, 0)));
    check('NM42c no rounds given reads as none',
        pct4(NM.chanceAfter(5, nil)), pct4(NM.chanceAfter(5, 0)));
    check('NM42d no base chance -> no number, never a guess', NM.chanceAfter(nil, 10), nil);
    check('NM42e a zero base is not a curve',                NM.chanceAfter(0, 10), nil);
    check('NM42f ...nor a round count',                      NM.roundsToGuaranteed(nil), nil);
    check('NM42g a 100% base is guaranteed on the first kill', NM.roundsToGuaranteed(100), 0);
    check('NM42h ...and reads 100% there',                   pct4(NM.chanceAfter(100, 0)), '100.0000');
    -- Quarter-way sample points, and never one that is already the guarantee.
    local pts = NM.curvePoints(5);
    check('NM42i three sample points on the way up',         #pts, 3);
    check('NM42j ...the first at a quarter of the distance', pts[1].rounds, 10);
    check('NM42k ...the last still short of guaranteed',     pts[3].rounds < 40, true);

    -- Provenance travels WITH the constant: an unscrapable fact with no source
    -- and no date is folklore, and the next maintainer cannot re-verify it.
    check('NM43a the source is recorded', type(NM.DISFAVOUR.source) == 'string'
        and #NM.DISFAVOUR.source > 20, true);
    check('NM43b ...and says it is not in the public repo',
        NM.DISFAVOUR.source:lower():match('overlay') ~= nil, true);
    check('NM43c a verification date is recorded',
        NM.DISFAVOUR.verified:match('^%d%d%d%d%-%d%d%-%d%d$') ~= nil, true);
    check('NM43d the formula is recorded next to it',
        NM.DISFAVOUR.formula:match('rounds') ~= nil, true);

    -- ---- the readout stops presenting the base as flat --------------------
    local _, t40 = run('/dl nm bonnacon');
    check('NM44a the old flat claim is gone',      t40:match('%% per kill') == nil, true);
    check('NM44b the base is named as a base',     t40:match('5%% base') ~= nil, true);
    check('NM44c ...and explicitly not flat',      t40:match('not flat') ~= nil, true);
    check('NM44d the mechanic is named',           t40:match('disfavour') ~= nil, true);
    check('NM44e rounds to a guaranteed pop are stated',
        t40:match('40 rounds is a guaranteed pop') ~= nil, true);
    check('NM44f the pop kind is stated',          t40:match('lottery pop') ~= nil, true);
    check('NM44g a round is defined in kills',     t40:match('a round = all 6 placeholders') ~= nil, true);
    -- The climb is SHOWN, not just asserted: a mid-curve figure that is neither
    -- the base nor 100 is the only thing that reads as a curve.
    check('NM44h the curve is shown at quarter marks',
        t40:match('10 rounds 6%.6%%, 20 rounds 9%.5%%, 30 rounds 17%%') ~= nil, true);
    check('NM44i the placeholders survive the rewrite',
        t40:match('Buffalo x6') ~= nil and t40:match('PH indexes 354%-359') ~= nil, true);
    check('NM44j ...and so does the filter',
        t40:match('/filterscan 354,355,356,357,358,359,360') ~= nil, true);

    -- ---- a non-lottery NM gets its OWN words, and no curve -----------------
    -- Reading a placeholder curve for an NM whose placeholders roll nothing is
    -- exactly the wasted camp this command exists to prevent.
    NM.zoneReader = function() return 2; end;
    local _, t45 = run('/dl nm Tempest Tigon');
    check('NM45a a timed NM says timed',            t45:match('timed pop') ~= nil, true);
    check('NM45b ...in plain words',                t45:match('its own timer') ~= nil, true);
    check('NM45c ...with the respawn it has',       t45:match('respawn 1h') ~= nil, true);
    check('NM45d ...and NO disfavour curve',        t45:match('disfavour') == nil, true);
    check('NM45e ...and no guaranteed-pop claim',   t45:match('guaranteed') == nil, true);
    check('NM45f ...and no borrowed lottery word',  t45:match('lottery') == nil, true);

    NM.zoneReader = function() return 1; end;
    local _, t46 = run('/dl nm Aipaloovik');
    check('NM46a a scripted NM says scripted',      t46:match('scripted pop') ~= nil, true);
    check('NM46b ...and what that means',           t46:match('a pop item, a quest, or a forced spawn') ~= nil, true);
    check('NM46c ...with no curve',                 t46:match('disfavour') == nil, true);
    local _, t46b = run('/dl nm Vodyanoi');
    check('NM46d a night spawn says night',         t46b:match('night pop') ~= nil, true);
    check('NM46e ...and still hands over its filter', t46b:match('/filterscan 14') ~= nil, true);

    -- Charybdis is the hard case and the reason `kind` is consulted at all: it
    -- CARRIES placeholders and a pop chance, but the server's spawn kind says
    -- scripted. The indexes stay (they are still where it comes from, and the
    -- filter needs them); the lottery language does not.
    NM.zoneReader = function() return 176; end;
    local _, t47 = run('/dl nm Charybdis');
    check('NM47a a scripted NM with placeholders says scripted',
        t47:match('scripted pop') ~= nil, true);
    check('NM47b ...and says why there is no curve',
        t47:match('not a lottery, so no disfavour curve') ~= nil, true);
    check('NM47c ...shows NO percentage at all',    t47:match('%d+%% base') == nil, true);
    check('NM47d ...and no rounds figure',          t47:match('rounds') == nil, true);
    check('NM47e ...but keeps the placeholders',    t47:match('Devil Manta x2') ~= nil, true);
    check('NM47f ...and keeps the filter',          t47:match('/filterscan 406,408,410') ~= nil, true);
    -- ...and the table itself still says so, so a regeneration that lost `kind`
    -- fails here rather than silently restoring the lottery language.
    local chary = select(1, NM.matchInZone(176, 'Charybdis'));
    check('NM47g the shipped table reads scripted for it', NM.kindLabel(chary), 'scripted');
    check('NM47h ...while carrying a pop chance',          chary.c, 10);
    check('NM47i ...and placeholders',                     #chary.ph, 2);
    check('NM47j so isLottery refuses it',                 NM.isLottery(chary), false);
    local bonk = select(1, NM.matchInZone(5, 'Bonnacon'));
    check('NM47k ...where Bonnacon reads lottery',         NM.kindLabel(bonk), 'lottery');
    check('NM47l ...and isLottery accepts it',             NM.isLottery(bonk), true);

    -- ---- honest degradations ----------------------------------------------
    -- A lottery whose base chance the table does not carry: the mechanic is
    -- still named, the number is not invented.
    NM.zoneReader = function() return 12; end;
    local _, t48 = run('/dl nm Swashstox');
    check('NM48a it is still a lottery',            t48:match('lottery pop') ~= nil, true);
    check('NM48b ...but the missing base is admitted',
        t48:match('base chance is not in the table') ~= nil, true);
    check('NM48c ...and no percentage is guessed',  t48:match('%d+%% base') == nil, true);
    -- A lottery the table has no placeholders for says exactly that.
    NM.zoneReader = function() return 15; end;
    local _, t49 = run('/dl nm Tonberry Lieje');
    check('NM49a it says the kind',                 t49:match('lottery pop') ~= nil, true);
    check('NM49b ...and that it has no placeholders here',
        t49:match('no placeholders for it') ~= nil, true);
    check('NM49c ...with no curve',                 t49:match('guaranteed') == nil, true);
    -- A pre-2026-08-03 table has no `kind` at all. That is not the server
    -- saying "not a lottery", so placeholders + a base chance still get the
    -- curve rather than silently losing it on a stale install.
    local old = { n = 'Old Table', nm = { 9 }, ph = { 7, 8 }, p = 'Thing', c = 10 };
    check('NM49d a kindless entry with placeholders is still a lottery',
        NM.isLottery(old), true);
    local oldLines = table.concat(NM.describe(old, 5, false), '\n');
    check('NM49e ...and still gets its curve',
        oldLines:match('20 rounds is a guaranteed pop') ~= nil, true);
    check('NM49f a kindless entry with no placeholders admits it does not know',
        table.concat(NM.describe({ n = 'x', nm = { 3 } }, 5, false), '\n')
            :match('the table does not say how') ~= nil, true);
    NM.zoneReader = function() return 5; end;

    -- ---- the compendium list (issue #156) ---------------------------------
    --
    --   The window is a thin renderer over THESE. They are pinned here rather
    --   than in the UI suite for the reason every pure core is: an imgui-less
    --   check can assert the ANSWER, where a render check can only assert that
    --   something was drawn. Two behaviours carry over from the chat command
    --   and are the whole reason the window does not grow its own matcher --
    --   a weak match is labelled a guess, and gibberish is refused.
    -- -----------------------------------------------------------------------
    local nrows, ntotal = NM.nameRows('bonnacon');
    check('NM60a a name search answers with rows',      #nrows > 0, true);
    check('NM60b ...best first',                        nrows[1].n, 'Bonnacon');
    check('NM60c ...carrying the zone it is in',        nrows[1].zid, 5);
    check('NM60d ...and the entry itself',              nrows[1].e.p, 'Buffalo');
    check('NM60e an exact hit is NOT a guess',          nrows[1].guess, false);
    check('NM60f ...and the total is what matched',     ntotal, #nrows);

    -- Gibberish is refused, exactly as chat refuses it: M.score answers 0 for a
    -- name with no resemblance, and a zero never becomes a row. Offering the
    -- closest thing in the game to nonsense is how a player ends up reading
    -- about a monster they never asked for.
    check('NM61a gibberish yields no rows at all',      #NM.nameRows('zzzznothing'), 0);
    check('NM61b an empty query is not a search',       #NM.nameRows(''), 0);
    check('NM61c ...nor is whitespace',                 #NM.nameRows('   '), 0);
    check('NM61d ...nor is nil',                        #NM.nameRows(nil), 0);

    -- A typo still finds it, and still says it is a guess. The threshold is
    -- ONE named constant, so the window and the chat readout cannot hedge
    -- differently about the same score.
    local trows = NM.nameRows('bonacon');
    check('NM62a a typo still finds the NM',            trows[1].n, 'Bonnacon');
    check('NM62b ...but the row is flagged a guess',    trows[1].guess, true);
    check('NM62c ...below the one shared floor',        trows[1].score < NM.GUESS_FLOOR, true);
    check('NM62d ...which is the floor chat hedges on', NM.GUESS_FLOOR, 800);

    -- THE TIE-BREAK. Same score, and one entry HAS placeholders: that is the
    -- open-world camp, and it wins. Pinned twice on purpose --
    --   * against a HAND-VERIFIED shipped row, so a regeneration that loses
    --     placeholders is caught here (Poisonhand Gnadgad is in Davoi with 8
    --     placeholders, and in two Campaign zones with none; Davoi's zone id is
    --     the HIGHER one, so without the tie-break it sorts last), and
    --   * against a synthetic pair, so the RULE stays pinned even on a day the
    --     shipped table happens to hold no tie at all.
    local tie = NM.nameRows('Poisonhand Gnadgad');
    check('NM63a the shipped table still holds this tie', #tie >= 2, true);
    check('NM63b every copy scores the same',           tie[1].score, tie[2].score);
    check('NM63c the one with placeholders wins',       tie[1].zid, 149);
    check('NM63d ...and it is the one with placeholders', tie[1].ph > 0, true);
    check('NM63e ...while the loser has none',          tie[2].ph, 0);
    local savedForTie = NM.data;
    NM.data = {
        [1] = { { n = 'Twinned Opo-opo', nm = { 900 }, ph = {}, kind = { 'scripted' } } },
        [2] = { { n = 'Twinned Opo-opo', nm = { 901 }, ph = { 899 }, p = 'Opo-opo',
                  c = 5, kind = { 'lottery' } } },
    };
    local syn = NM.nameRows('Twinned Opo-opo');
    check('NM63f a synthetic tie ranks placeholders first', syn[1].zid, 2);
    check('NM63g ...even though the other zone sorts lower', syn[2].zid, 1);
    NM.data = savedForTie;

    -- The cap is a READING limit, not a search limit: what was cut is counted
    -- and reported, because a silent truncation reads as "that is all there is".
    local crows, ctotal = NM.nameRows('a', 5);
    check('NM64a the cap holds the list down',          #crows, 5);
    check('NM64b ...and the total still says what matched', ctotal > 5, true);
    check('NM64c an uncapped search returns everything',
        select(2, NM.nameRows('a')), ctotal);

    -- ---- filter mode: by area ---------------------------------------------
    local arows = NM.areaRows(5);
    check('NM65a an area answers with every NM in it',  #arows, 14);
    check('NM65b ...the campable ones first',           arows[1].ph > 0, true);
    check('NM65c ...and none of them is a guess',       arows[1].guess, false);
    check('NM65d the last one has no placeholders',     arows[#arows].ph, 0);
    check('NM65e an unknown zone is empty, not an error', #NM.areaRows(99999), 0);
    check('NM65f ...and so is no zone at all',          #NM.areaRows(nil), 0);
    -- "Most zones hold a handful, the busiest field zone holds dozens" -- the
    -- reason the window's list must scroll rather than assume it is short.
    check('NM65g the busiest field zone really is dozens', #NM.areaRows(289) > 40, true);

    -- ---- the area picker's source -----------------------------------------
    local zc = NM.zoneChoices();
    check('NM66a every zone in the table is offered',   #zc, #NM.zoneIds());
    check('NM66b ...sorted by NAME, which is what is read',
        zc[1].name <= zc[2].name, true);
    check('NM66c ...each carrying how many it holds',   zc[1].n > 0, true);
    local zc5 = nil;
    for _, z in ipairs(zc) do if z.zid == 5 then zc5 = z; end end
    check('NM66d Uleguerand Range is in the picker',    zc5 ~= nil and zc5.name, 'Uleguerand Range');
    check('NM66e ...with its 14 NMs counted',           zc5 ~= nil and zc5.n, 14);

    -- ---- the row note (what a list row says beside the name) --------------
    check('NM67a a lottery row names its placeholders',
        NM.rowNote(select(1, NM.matchInZone(5, 'Bonnacon'))), 'Buffalo x6');
    check('NM67b a scripted NM with placeholders says so on the row',
        NM.rowNote(select(1, NM.matchInZone(176, 'Charybdis'))):match('not a lottery') ~= nil, true);
    check('NM67c one with no placeholders says how it pops instead',
        NM.rowNote({ n = 'x', nm = { 1 }, ph = {}, kind = { 'scripted' } }),
        'scripted pop, no placeholders');
    check('NM67d ...and admits it when the table does not say',
        NM.rowNote({ n = 'x', nm = { 1 }, ph = {} }), 'no placeholders');
    -- No percentage anywhere on a row: the numbers belong on the detail card,
    -- and every one of them is a `%` that has to survive an ImGui format string.
    check('NM67e a row note carries no percent sign',
        NM.rowNote(select(1, NM.matchInZone(5, 'Bonnacon'))):find('%%') == nil, true);

    -- ---- /dl nm window: the opener ----------------------------------------
    --
    --   Any surface may OPEN a floating window; exactly one site may DRAW it.
    --   This is the open, so all it may do is set state on ui\nmui -- and with
    --   no window module present it must SAY it cannot rather than no-op.
    -- -----------------------------------------------------------------------
    local savedUI = package.loaded['dlac\\ui\\nmui'];
    local opened = { name = nil, zid = nil, n = 0 };
    package.loaded['dlac\\ui\\nmui'] = {
        openName = function(q) opened.name = q; opened.n = opened.n + 1; end,
        openArea = function(z) opened.zid = z;  opened.n = opened.n + 1; end,
    };
    local ew, tw = run('/dl nm window bonnacon');
    check('NM68a the window verb is claimed',           ew.blocked, true);
    check('NM68b ...and opens on the name typed',       opened.name, 'bonnacon');
    check('NM68c ...without also answering in chat',    tw:match('Buffalo x6'), nil);
    opened = { name = nil, zid = nil, n = 0 };
    run('/dl nm window');
    check('NM68d bare, it opens on the zone you are in', opened.zid, 5);
    check('NM68e ...and does not also run a name search', opened.name, nil);
    opened = { name = nil, zid = nil, n = 0 };
    run('/dl nm win');
    check('NM68f the short alias works',                opened.zid, 5);
    -- The chat-only verbs do not travel into the window, and a dropped word
    -- must not look like an honoured one (hard rule 12).
    opened = { name = nil, zid = nil, n = 0 };
    local _, tw2 = run('/dl nm window bonnacon apply');
    check('NM68g apply beside window is answered, not eaten',
        tw2:match('answer in chat') ~= nil, true);
    check('NM68h ...and the window still opens',        opened.name, 'bonnacon');
    -- A build where the GUI failed to load loses the verb and NOTHING else.
    package.loaded['dlac\\ui\\nmui'] = { degraded = true, openName = function() end,
                                         openArea = function() end };
    local _, tw3 = run('/dl nm window');
    check('NM68i a degraded window says so',
        tw3:match('not available in this build') ~= nil, true);
    check('NM68j ...and points at the chat answer',     tw3:match('/dl nm <name>') ~= nil, true);
    package.loaded['dlac\\ui\\nmui'] = nil;
    local _, tw4 = run('/dl nm window');
    check('NM68k no window module at all is the same honest refusal',
        tw4:match('not available in this build') ~= nil, true);
    package.loaded['dlac\\ui\\nmui'] = savedUI;

    -- ---- a missing table degrades OFF, never errors -----------------------
    local savedData = NM.data;
    NM.data = {};
    local _, t10 = run('/dl nm bonnacon');
    check('NM37a no table -> a plain warning, no crash',
        t10:match('nmdata%.lua is missing') ~= nil, true);
    NM.data = savedData;

    package.loaded['dlac\\chatfmt'] = savedChat;
end)();

-- ---------------------------------------------------------------------------
-- ND. What an NM drops (feature\nmloot, issue #153, PRD #151).
--
--   Three properties of data\nmdrops.lua are load-bearing, and each is a
--   different way this readout could lie to a camper:
--     * a GROUPED row's `r` is a WEIGHT, not a percentage. The group rolls
--       ONCE at `gr` and then one item inside it wins by weight; 2009 of the
--       5372 rows are grouped, so flattening them misstates more than a third
--       of the shipped table.
--     * DUPLICATE rows are two independent rolls, not one row written twice.
--     * STEAL and DESPOIL are not kill loot, and listing them as drops tells a
--       player to expect something a kill will never give.
--
--   THE GROUP PIN IS CHOSEN, NOT CONVENIENT. Mee Deggi -- the worked example
--   in the issue -- cannot pin the first property: its group weights sum to
--   exactly 1000, so the share (10%) and the flattened reading (r/10 = 10%)
--   are the same number and a flattening bug passes. Ouryu's pool 3070 carries
--   a group of two at 425 each under `gr = 750`: the share is 50% and the
--   flattened reading is 42.5%, so only a correct implementation can print it.
--   The synthetic pool below is built on the same principle -- every rate in it
--   is chosen so that a wrong reading produces a DIFFERENT string.
-- ---------------------------------------------------------------------------
(function()
    package.loaded['dlac\\data\\nmdrops'] = dofile('data/nmdrops.lua');
    local NMDATA = package.loaded['dlac\\data\\nmdata'] or dofile('data/nmdata.lua');

    -- The client's item resources, with every ask COUNTED. The resolve has to
    -- be lazy -- a name table built at load runs before the player is logged in
    -- and the client answers with nothing -- and "how many times was the client
    -- asked, and when" is the only honest way to test that.
    local savedAC = AshitaCore;
    local asked = 0;
    local RES = {
        [16703] = 'Impact Knuckles', [13952] = 'Ochiudo\'s Kote', [656] = 'Beastcoin',
        [13014] = 'Leaping Boots',
        [101] = 'Widget A', [102] = 'Widget C', [103] = 'Widget D', [104] = 'Widget E',
        [105] = 'Widget F', [106] = 'Widget G', [107] = 'Widget H', [108] = 'Widget I',
    };
    -- The chat manager is here for `apply` alone (the TH verb has to compose
    -- with it); every other check in this section is arithmetic over a table.
    local sent = nil;
    AshitaCore = {
        GetResourceManager = function()
            return { GetItemById = function(_, id)
                asked = asked + 1;
                if RES[id] == nil then return nil; end
                return { Name = { RES[id] } };
            end };
        end,
        GetChatManager = function()
            return { QueueCommand = function(_, _, cmd) sent = cmd; end };
        end,
    };

    local LT = dofile('feature/nmloot.lua');

    local function entryFor(zid, name)
        for _, e in ipairs(NMDATA[zid] or {}) do
            if e.n == name then return e; end
        end
        return nil;
    end
    -- `th` is the Treasure Hunter level to render the rates at (issue #154);
    -- omitted means the player asked for no level, which is the default readout.
    local function rendered(entry, th) return table.concat(LT.lines(entry, th), '\n'); end

    -- ---- names resolve LAZILY, and a miss never latches ------------------
    check('ND00a loading the module asks the client for nothing', asked, 0);
    check('ND00b the shipped table is there all the same', #LT.rowsFor({ pool = { 2607 } }), 3);
    check('ND00c ...and that still asked the client for nothing', asked, 0);
    check('ND00d the first name resolves through the client', LT.itemName(16703), 'Impact Knuckles');
    check('ND00e ...which is one ask', asked, 1);
    check('ND00f asking again is remembered, not re-asked', LT.itemName(16703), 'Impact Knuckles');
    check('ND00g ...still one ask', asked, 1);
    -- An id the client cannot answer for renders AS AN ID: a row that vanished
    -- would be indistinguishable from a table that never carried it.
    check('ND00h an unresolvable id renders as an id', LT.itemName(4242), 'item #4242');
    -- ...and is NOT cached. A pre-login read is "cannot tell yet", not "no such
    -- item", and latching it would make one early ask permanent (ADR 0007).
    local before = asked;
    check('ND00i ...and asking again really asks again', LT.itemName(4242), 'item #4242');
    check('ND00j ...so the miss was never cached', asked > before, true);
    RES[4242] = 'Late Arrival';                       -- the player finishes logging in
    check('ND00k ...and the name arrives once the client can answer',
        LT.itemName(4242), 'Late Arrival');
    check('ND00l a nonsense id is still never nil', LT.itemName('x'), 'item #?');

    -- ---- the server's eight named tiers -----------------------------------
    check('ND01a 1000 is always',          LT.tierName(1000), 'always');
    check('ND01b 240 is very common',      LT.tierName(240), 'very common');
    check('ND01c 150 is common',           LT.tierName(150), 'common');
    check('ND01d 100 is uncommon',         LT.tierName(100), 'uncommon');
    check('ND01e 50 is rare',              LT.tierName(50), 'rare');
    check('ND01f 10 is very rare',         LT.tierName(10), 'very rare');
    check('ND01g 5 is super rare',         LT.tierName(5), 'super rare');
    check('ND01h 1 is ultra rare',         LT.tierName(1), 'ultra rare');
    check('ND01i the tier list is exactly those eight', (function()
        local n = 0; for _ in pairs(LT.TIERS) do n = n + 1; end; return n;
    end)(), 8);
    check('ND01j a tier renders its name beside the percentage',
        LT.rateText(150), 'common (15%)');
    check('ND01k rare reads 5%, the way the game says it, not 5.0%',
        LT.rateText(50), 'rare (5%)');
    check('ND01l the half-percent tier keeps its decimal',
        LT.rateText(5), 'super rare (0.5%)');
    check('ND01m ...and so does the tenth',  LT.rateText(1), 'ultra rare (0.1%)');
    check('ND01n always is 100%',            LT.rateText(1000), 'always (100%)');
    -- 1215 shipped rows carry a rate outside the eight. It is a valid weight,
    -- and snapping it to the nearest tier would be inventing a fact.
    check('ND01o a rate outside the eight has NO tier name', LT.tierName(250), nil);
    check('ND01p ...and renders as a bare percentage',       LT.rateText(250), '25%');
    check('ND01q ...even next door to a tier',               LT.rateText(230), '23%');
    check('ND01r a rate of zero is no rate at all',          LT.rateText(0), nil);

    -- ---- percentages for reading ------------------------------------------
    check('ND02a 100',            LT.pctText(100), '100%');
    check('ND02b 24',             LT.pctText(24), '24%');
    check('ND02c 10',             LT.pctText(10), '10%');
    check('ND02d 5 loses the dead decimal',   LT.pctText(5), '5%');
    check('ND02e 1 too',                      LT.pctText(1), '1%');
    check('ND02f a half percent keeps it',    LT.pctText(0.5), '0.5%');
    check('ND02g a tenth keeps it',           LT.pctText(0.1), '0.1%');
    check('ND02h a real share never prints as 0%', LT.pctText(0.0001), '<0.01%');
    check('ND02i nothing to say is said as nothing', LT.pctText(nil), '?');

    -- ---- the join, through the NM's pool id -------------------------------
    local mee = entryFor(151, 'Mee Deggi the Punisher');
    check('ND03a the shipped NM carries a pool id', (mee.pool or {})[1], 2607);
    check('ND03b ...and the join reaches its rows', #LT.rowsFor(mee), 3);
    check('ND03c an entry with no pool joins to nothing', #LT.rowsFor({ n = 'x' }), 0);
    check('ND03d ...and "cannot look it up" is not "has none"', LT.hasPool({ n = 'x' }), false);
    check('ND03e the same pool listed twice is ONE droplist',
        #LT.rowsFor({ pool = { 2607, 2607 } }), 3);
    check('ND03f several pools concatenate', #LT.rowsFor({ pool = { 2607, 2384 } }), 9);

    -- ---- rolls: what rolls together and what rolls apart -------------------
    local killM, takeM = LT.rolls(LT.rowsFor(mee));
    check('ND04a Mee Deggi is one roll',        #killM, 1);
    check('ND04b ...a group',                   killM[1].kind, 'group');
    check('ND04c ...of two',                    #killM[1].rows, 2);
    check('ND04d ...that always drops',         killM[1].gr, 1000);
    check('ND04e the Kote is its SHARE of the group', LT.shareOf(killM[1], killM[1].rows[2]), 10);
    check('ND04f ...and the Knuckles the rest',       LT.shareOf(killM[1], killM[1].rows[1]), 90);
    check('ND04g the steal row never reaches kill loot', #takeM, 1);
    check('ND04h ...and is named as Steal',             takeM[1].how, 'Steal');

    -- Leaping Lizzy lists item 926 at 240 and AGAIN at 150. Two rolls.
    local liz = entryFor(107, 'Leaping Lizzy');
    local killL = select(1, LT.rolls(LT.rowsFor(liz)));
    check('ND04i Leaping Lizzy rolls five times',   #killL, 5);
    check('ND04j the repeated item is TWO rolls',   killL[1].row.i, killL[2].row.i);
    check('ND04k ...at two different rates',
        string.format('%d/%d', killL[1].row.r, killL[2].row.r), '240/150');
    check('ND04l ...and the second pair repeats too',
        string.format('%d/%d', killL[4].row.i, killL[5].row.i), '852/852');

    -- Pool 245 lists group 1 at gr=1000 and then the SAME four items as group 1
    -- again at gr=100. Keyed on the group id alone one of those rates -- and the
    -- roll it belongs to -- would have to be thrown away.
    local kill245 = select(1, LT.rolls(LT.rowsFor({ pool = { 245 } })));
    check('ND04m a group id whose group rate changes under it is two rolls', #kill245, 3);
    check('ND04n ...the first always drops',            kill245[2].gr, 1000);
    check('ND04o ...the second is a tenth of that',     kill245[3].gr, 100);
    check('ND04p ...and neither lost a member',
        string.format('%d/%d', #kill245[2].rows, #kill245[3].rows), '4/4');

    -- ---- the readout, on a pool built so a wrong reading reads DIFFERENTLY --
    LT.data[999001] = {
        { i = 101, r = 240 },                          -- one of the eight tiers
        { i = 101, r = 150 },                          -- the SAME item again: a second roll
        { i = 102, r = 250 },                          -- not one of the eight
        { i = 103, r = 300, t = 1, g = 1, gr = 150 },  -- share 75%; flattened it would read 30%
        { i = 105, r = 0,   t = 2 },                   -- a steal row INSIDE the run
        { i = 104, r = 100, t = 1, g = 1, gr = 150 },  -- share 25%; flattened it would read 10%
        { i = 106, r = 500, t = 1, g = 1, gr = 1000 }, -- same group id, new group rate: a new roll
        { i = 107, r = 500, t = 1, g = 1, gr = 1000 },
        { i = 108, r = 150, t = 4 },                   -- despoil, and this one HAS a rate
        { i = 888888, r = 50 },                        -- an id the client cannot name
    };
    local syn = rendered({ n = 'Synthetic', pool = { 999001 } });
    check('ND05a ten rows are six independent ROLLS',
        syn:match('drops %-%- 6 rolls') ~= nil, true);
    check('ND05b a tier is named beside its percentage',
        syn:match('Widget A %-%- very common %(24%%%)') ~= nil, true);
    check('ND05c the repeated item appears a second time, at its own rate',
        syn:match('Widget A %-%- common %(15%%%)') ~= nil, true);
    check('ND05d a rate outside the eight shows a percentage and no tier name',
        syn:match('Widget C %-%- 25%%') ~= nil, true);
    check('ND05e ...and is not snapped to the nearest tier',
        syn:match('Widget C %-%- %a') == nil, true);
    check('ND05f a group renders AS a group, at the group\'s own rate, with shares',
        syn:match('one of these, common %(15%%%): Widget D 75%%, Widget E 25%%') ~= nil, true);
    check('ND05g ...never flattened into per-item percentages',
        syn:match('Widget D %-%-') == nil and syn:match('30%%') == nil, true);
    check('ND05h a steal row inside a group run does not split the group',
        syn:match('Widget D 75%%, Widget E 25%%') ~= nil, true);
    check('ND05i the same group id at a new group rate is a SECOND roll',
        syn:match('one of these, always %(100%%%): Widget G 50%%, Widget H 50%%') ~= nil, true);
    check('ND05j what the % beside a member means is said, once',
        select(2, syn:gsub('share of the group', '')), 1);
    check('ND05k steal and despoil get their own section, named',
        syn:match('not kill loot %-%- Steal / Despoil only') ~= nil, true);
    check('ND05l ...and are kept out of the drops list',
        syn:match('Widget F %-%-') == nil, true);
    check('ND05m a steal row the API gives no rate for states none',
        syn:match('Widget F %(Steal%)\n') ~= nil, true);
    check('ND05n ...and one that has a rate keeps it',
        syn:match('Widget I %(Despoil%) %-%- common %(15%%%)') ~= nil, true);
    check('ND05o an unresolvable id renders as an id rather than vanishing',
        syn:match('item #888888 %-%- rare %(5%%%)') ~= nil, true);

    -- A group of ONE is not a group to a player: its chance IS the group rate,
    -- and 22 shipped groups are that shape.
    LT.data[999002] = { { i = 101, r = 250, t = 1, g = 1, gr = 150 } };
    check('ND05p a group of one renders at the GROUP rate, not its weight',
        rendered({ pool = { 999002 } }):match('Widget A %-%- common %(15%%%)') ~= nil, true);
    check('ND05q ...and is not called "one of these"',
        rendered({ pool = { 999002 } }):match('one of these') == nil, true);

    -- ---- the same properties, against the SHIPPED table --------------------
    -- Ouryu's pool 3070: two items at 425 under a group rate of 750. Share 50%,
    -- flattened 42.5% -- the two readings cannot be confused here.
    local ouryu = rendered({ pool = { 3070 } });
    check('ND06a a shipped group states each member\'s share',
        ouryu:match('one of these, 75%%: item #1769 50%%, item #1764 50%%') ~= nil, true);
    check('ND06b ...and never the weight read as a percentage',
        ouryu:match('item #1769 4[23]') == nil, true);
    check('ND06c a group rate outside the eight is a bare percentage too',
        ouryu:match('one of these, 75%%:') ~= nil, true);
    check('ND06d the shipped NM table still joins Ouryu to that pool',
        (entryFor(29, 'Ouryu').pool or {})[1], 3070);
    check('ND06e the shipped group is still two items at 425 under gr 750', (function()
        for _, b in ipairs((select(1, LT.rolls(LT.rowsFor({ pool = { 3070 } }))))) do
            if b.kind == 'group' and b.gr == 750 and #b.rows == 2 then
                return string.format('%d+%d', b.rows[1].r, b.rows[2].r);
            end
        end
        return 'gone';
    end)(), '425+425');

    -- ---- absences, and they must not look alike ----------------------------
    check('ND07a an NM the drop table has nothing for says so',
        rendered(entryFor(112, 'Boreal Coeurl')),
        '  drops: nothing in the drop table for this one.');
    check('ND07b an NM table with no pool id says something else entirely',
        rendered({ n = 'x' }):match('carries no pool id') ~= nil, true);
    -- Five shipped pools hold Steal and Despoil rows and nothing else. Printing
    -- only that section would leave "what does it drop" unanswered.
    check('ND07e a pool with no kill loot at all says so, not nothing',
        rendered({ pool = { 4290 } }):match('nothing a kill gives') ~= nil, true);
    check('ND07f ...and still lists what is not kill loot',
        rendered({ pool = { 4290 } }):match('not kill loot %-%-') ~= nil, true);
    local savedDrops = LT.data;
    LT.data = {};
    check('ND07c a missing drop table names the file, and does not crash',
        rendered(mee):match('nmdrops%.lua') ~= nil, true);
    check('ND07d ...and does not read as "this NM drops nothing"',
        rendered(mee):match('nothing in the drop table') == nil, true);
    LT.data = savedDrops;

    -- ---- the caps say what they left out -----------------------------------
    -- A silent cap reads as "that is all of it", which is the one thing a drop
    -- readout must never imply.
    local big = {};
    for k = 1, 20 do big[k] = { i = 100 + k, r = 50, t = 1, g = 1, gr = 1000 }; end
    LT.data[999003] = big;
    local bigTxt = rendered({ pool = { 999003 } });
    check('ND08a a group past the cap shows exactly the cap\'s worth of members',
        select(2, bigTxt:gsub(' 5%%', '')), 12);
    check('ND08b ...says how many it did not show',
        bigTxt:match('%+8 more') ~= nil, true);
    check('ND08c ...and what they are worth together',
        bigTxt:match('%+8 more sharing 40%%') ~= nil, true);
    local many = {};
    for k = 1, 40 do many[k] = { i = 100 + k, r = 150 }; end
    LT.data[999004] = many;
    local manyTxt = rendered({ pool = { 999004 } });
    check('ND08d the roll cap is stated, never silent',
        manyTxt:match('and 8 more rolls not shown') ~= nil, true);
    check('ND08e ...and the head still counts them all',
        manyTxt:match('drops %-%- 40 rolls') ~= nil, true);
    check('ND08f nothing in the shipped table reaches that cap', (function()
        for _, list in pairs(NMDATA) do
            for _, e in ipairs(list) do
                if #(select(1, LT.rolls(LT.rowsFor(e)))) > LT.MAX_ROLLS then return e.n; end
            end
        end
        return 'none';
    end)(), 'none');
    LT.data[999001], LT.data[999002], LT.data[999003], LT.data[999004] = nil, nil, nil, nil;

    -- ---- Treasure Hunter: a bracket LOOKUP, not a multiplier (issue #154) ---
    --
    --   The whole feature rests on TH being computable: the rate selects a
    --   RARITY BRACKET and the TH level selects the value inside it, so the
    --   exact rate at any level is arithmetic rather than folklore. The table
    --   below is the server's own, and these checks are what stand between a
    --   transcription slip and a readout that confidently lies about odds.
    --
    --   THE UNITS ARE THE TRAP, and they are pinned first: the lookup works out
    --   of 10000 and the caller hands it `DropRate * 10`, so a stored 150 enters
    --   as 1500 and comes back 4500 at TH4. A missing times-ten reads a common
    --   drop as ultra rare and would still "look like a percentage".
    check('ND10a the table carries all fifteen TH levels', (function()
        local n = 0;
        for lvl = 0, 14 do if type(LT.TH_TABLE[lvl]) == 'table' then n = n + 1; end end
        return n;
    end)(), 15);
    check('ND10b ...and nothing above the last one', LT.TH_TABLE[15], nil);
    check('ND10c every row is the seven rarity brackets', (function()
        for lvl = 0, 14 do if #LT.TH_TABLE[lvl] ~= 7 then return 'row ' .. lvl; end end
        return 'all 7';
    end)(), 'all 7');
    check('ND10d the row ends are the shipped ones (0 and 14)',
        string.format('%d/%d/%d/%d', LT.TH_TABLE[0][1], LT.TH_TABLE[0][7],
            LT.TH_TABLE[14][1], LT.TH_TABLE[14][7]), '2400/10/8000/150');
    -- Row 5 opens 6666. It is left exactly as the server has it: this table is
    -- a copy, and tidying it to 6650 would be designing.
    check('ND10e the 6666 quirk on row 5 survives transcription', LT.TH_TABLE[5][1], 6666);
    -- Every column rises with the level. This is WHY "TH cannot help" has only
    -- two causes (the two short-circuits) rather than a third hiding in a flat
    -- column, which is the claim the verdict line makes to the player.
    check('ND10f no column ever falls as the TH level rises', (function()
        for col = 1, 7 do
            for lvl = 1, 14 do
                if LT.TH_TABLE[lvl][col] < LT.TH_TABLE[lvl - 1][col] then
                    return string.format('col %d fell at %d', col, lvl);
                end
            end
        end
        return 'rises';
    end)(), 'rises');
    check('ND10g ...and every one of them ends higher than it started', (function()
        for col = 1, 7 do
            if LT.TH_TABLE[14][col] <= LT.TH_TABLE[0][col] then return 'col ' .. col; end
        end
        return 'all climb';
    end)(), 'all climb');

    -- The bracket floors ARE the eight named tiers times ten, `always` dropped
    -- off the top -- which is why the bracket a drop sits in is the tier name
    -- this readout already prints beside it, and why no second vocabulary had
    -- to be invented for the columns.
    check('ND11a the bracket floors are the tiers x10',
        table.concat(LT.TH_BRACKETS, '/'), '2400/1500/1000/500/100/50/0');
    check('ND11b ...and each floor is a tier this module already names', (function()
        for i = 1, 6 do
            if LT.tierName(LT.TH_BRACKETS[i] / 10) ~= LT.TH_BRACKET_TIER[i] then
                return 'bracket ' .. i;
            end
        end
        return 'all named';
    end)(), 'all named');
    check('ND11c a rate lands in the FIRST floor it reaches',
        string.format('%d%d%d%d%d%d%d', LT.thBracket(2400), LT.thBracket(1500),
            LT.thBracket(1000), LT.thBracket(500), LT.thBracket(100),
            LT.thBracket(50), LT.thBracket(10)), '1234567');
    check('ND11d ...one under a floor drops to the next bracket',
        string.format('%d/%d', LT.thBracket(2399), LT.thBracket(1499)), '2/3');
    check('ND11e a rate above every floor is still the top bracket', LT.thBracket(9999), 1);

    -- The lookup itself, at several levels and in every bracket.
    check('ND12a common at TH0 is itself',        LT.thRate(0, 1500), 1500);
    check('ND12b common at TH4',                  LT.thRate(4, 1500), 4500);
    check('ND12c common at TH14',                 LT.thRate(14, 1500), 7000);
    check('ND12d very common at TH2',             LT.thRate(2, 2400), 5600);
    check('ND12e uncommon at TH7',                LT.thRate(7, 1000), 2100);
    check('ND12f rare at TH9',                    LT.thRate(9, 500), 1150);
    check('ND12g very rare at TH11',              LT.thRate(11, 100), 750);
    check('ND12h super rare at TH12',             LT.thRate(12, 50), 400);
    check('ND12i ultra rare at TH13',             LT.thRate(13, 10), 130);
    check('ND12j ...and ultra rare at TH0 is the one floor that is not a tier',
        LT.thRate(0, 10), 10);
    -- Both short-circuits, at every level -- these are the two ways TH cannot
    -- help, and the verdict line depends on there being no third.
    check('ND12k a rate already at 100% is unmoved at EVERY level', (function()
        for lvl = 0, 14 do if LT.thRate(lvl, 10000) ~= 10000 then return 'moved at ' .. lvl; end end
        return 'unmoved';
    end)(), 'unmoved');
    check('ND12l ...and a rate of nothing stays nothing', (function()
        for lvl = 0, 14 do if LT.thRate(lvl, 0) ~= 0 then return 'moved at ' .. lvl; end end
        return 'unmoved';
    end)(), 'unmoved');
    -- The clamps, both ends, both arguments.
    check('ND12m a level below the table clamps to TH0',   LT.thRate(-3, 1500), 1500);
    check('ND12n a level above it clamps to TH14',         LT.thRate(99, 1500), 7000);
    check('ND12o a rate above 10000 clamps to guaranteed', LT.thRate(4, 99999), 10000);
    check('ND12p a negative rate is nothing',              LT.thRate(4, -5), 0);
    check('ND12q the clamp says when it moved',
        string.format('%d/%s', select(1, LT.clampTH(20)), tostring(select(2, LT.clampTH(20)))), '14/true');
    check('ND12r ...and when it did not',
        string.format('%d/%s', select(1, LT.clampTH(4)), tostring(select(2, LT.clampTH(4)))), '4/false');

    -- The stored-rate door: out of 1000 in, a percentage out, with the server's
    -- times-ten done here so no caller holds two scales at once.
    check('ND13a a stored common rate reads 15% at TH0',  LT.thPct(0, 150), 15);
    check('ND13b ...and 45% at TH4',                      LT.thPct(4, 150), 45);
    check('ND13c ...and 70% at TH14',                     LT.thPct(14, 150), 70);
    check('ND13d a rate the table does not state is not guessed at', LT.thPct(4, 0), nil);
    check('ND13e TH can lift a rate below 100%',          LT.thHelps(150), true);
    check('ND13f ...and nothing lifts one already at it', LT.thHelps(1000), false);
    check('ND13g ...nor one the table does not state',    LT.thHelps(0), false);

    -- ---- the two cases verified against the live server --------------------
    -- 1. LEAPING BOOTS, pool 2384, ungrouped at r = 150: 15% at TH0, 45% at TH4.
    local boots = nil;
    for _, r in ipairs(LT.data[2384] or {}) do if r.i == 13014 then boots = r; end end
    check('ND14a the shipped table still carries Leaping Boots at 150',
        string.format('%s/%s', tostring(boots and boots.r), tostring(boots and boots.t)), '150/nil');
    check('ND14b ...which is 15% at TH0',  LT.thPct(0, boots.r), 15);
    check('ND14c ...45% at TH4',           LT.thPct(4, boots.r), 45);
    check('ND14d ...and 70% at TH14',      LT.thPct(14, boots.r), 70);
    local lizzy0 = rendered(entryFor(107, 'Leaping Lizzy'), 0);
    local lizzy4 = rendered(entryFor(107, 'Leaping Lizzy'), 4);
    check('ND14e the drop line itself reads 15% at TH0',
        lizzy0:match('Leaping Boots %-%- common %(15%%%)  |  TH0 15%%') ~= nil, true);
    check('ND14f ...and 45% at TH4',
        lizzy4:match('Leaping Boots %-%- common %(15%%%)  |  TH4 45%%') ~= nil, true);
    check('ND14g every roll on it carries its own TH figure',
        select(2, lizzy4:gsub('|  TH4 ', '')), 5);

    -- 2. OCHIUDO'S KOTE, pool 2607, a 10% share inside a group that ALWAYS
    --    drops. The group rate short-circuits, so no amount of TH moves it --
    --    the case that tells a player not to bother bringing TH at all.
    local meeKill = select(1, LT.rolls(LT.rowsFor(mee)));
    local meeGroup = meeKill[1];
    check('ND15a the Kote still sits in a group that always drops', meeGroup.gr, 1000);
    check('ND15b a 100% group is unchanged at EVERY TH level', (function()
        for lvl = 0, 14 do
            if LT.thPct(lvl, meeGroup.gr) ~= 100 then return 'moved at TH' .. lvl; end
        end
        return 'unchanged';
    end)(), 'unchanged');
    check('ND15c ...and so is the Kote\'s share of it, at every level', (function()
        for lvl = 0, 14 do
            local txt = rendered(mee, lvl);
            if txt:match('Ochiudo\'s Kote 10%%') == nil then return 'share moved at TH' .. lvl; end
        end
        return 'unchanged';
    end)(), 'unchanged');
    check('ND15d ...which the line says in WORDS, not by an unchanged number', (function()
        for lvl = 0, 14 do
            if rendered(mee, lvl):match('TH%d+: no gain %-%- the group already drops every time') == nil then
                return 'silent at TH' .. lvl;
            end
        end
        return 'said';
    end)(), 'said');
    check('ND15e ...and says TH never picks the winner inside the group either',
        rendered(mee, 4):match('TH never picks which item in it wins') ~= nil, true);
    -- The verdict a player gets WITHOUT asking for a level: the one that saves
    -- a gear set.
    check('ND15f the no-level verdict says there is nothing to gain',
        rendered(mee):match('TH: nothing to gain here') ~= nil, true);
    check('ND15g ...and why',
        rendered(mee):match('already drops every time') ~= nil, true);
    check('ND15h ...without printing a TH figure nobody asked for',
        rendered(mee):match('|  TH') == nil, true);

    -- ---- TH applies to the GROUP rate, never to the share inside it --------
    check('ND16a an ungrouped roll offers its own rate to the lookup',
        LT.rollRate({ kind = 'item', row = { i = 1, r = 150 } }), 150);
    check('ND16b a grouped roll offers the GROUP rate, not a member weight',
        LT.rollRate(meeGroup), 1000);
    -- The discriminating case: the Kote's own weight is 100, which the lookup
    -- would turn into 18% at TH4. That number must appear nowhere, because the
    -- weight is not a rate and TH never touches it.
    check('ND16c the member weight is never what gets looked up',
        LT.thPct(4, meeGroup.rows[2].r), 18);          -- what the wrong reading would say
    check('ND16d ...and that wrong reading reaches no line',
        rendered(mee, 4):match('18%%') == nil, true);
    -- Shares still sum once TH is applied to the group rate: the group's rate
    -- moved, the weights did not, so the shares are the same numbers as before.
    LT.data[999005] = {
        { i = 101, r = 300, t = 1, g = 1, gr = 150 },   -- share 75%
        { i = 102, r = 100, t = 1, g = 1, gr = 150 },   -- share 25%
    };
    local g5 = select(1, LT.rolls(LT.rowsFor({ pool = { 999005 } })))[1];
    check('ND16e the shares of a TH-lifted group still sum to 100', (function()
        local sum = 0;
        for _, row in ipairs(g5.rows) do sum = sum + LT.shareOf(g5, row); end
        return sum;
    end)(), 100);
    check('ND16f ...and the group rate itself is what TH lifted',
        string.format('%g -> %g', LT.pctOf(g5.gr), LT.thPct(4, g5.gr)), '15 -> 45');
    local sh0 = rendered({ pool = { 999005 } });
    local sh4 = rendered({ pool = { 999005 } }, 4);
    check('ND16g the printed shares do not move when TH is applied',
        sh4:match('Widget A 75%%, Widget C 25%%') ~= nil
            and sh0:match('Widget A 75%%, Widget C 25%%') ~= nil, true);
    check('ND16h ...and the group\'s own rate is the thing that did',
        sh4:match('TH4: the group rolls at 45%%; the shares above are unchanged') ~= nil, true);
    -- The members' line ENDS at the shares: no member is handed a TH figure of
    -- its own, because a share is not a chance and TH never touched it.
    check('ND16i ...which is stated as the group\'s roll, not an item\'s chance',
        sh4:match('one of these, common %(15%%%): Widget A 75%%, Widget C 25%%\n') ~= nil, true);

    -- ---- an off-tier rate reads at its BRACKET's value ---------------------
    -- 1215 shipped rows carry a rate outside the eight tiers, and the rate only
    -- SELECTS a bracket -- so 75% (the top bracket) reads 24% at TH0 and 64% at
    -- TH4. Left unexplained that reads as "TH lowered my drop rate", which is
    -- the one thing this line must never be taken for.
    check('ND17a an off-tier group rate reads at its bracket',
        string.format('%g/%g', LT.thPct(0, 750), LT.thPct(4, 750)), '24/64');
    local our4 = rendered({ pool = { 3070 } }, 4);
    check('ND17b ...and the line says why it is not the stated rate',
        our4:match('the group rolls at 64%% %-%- the stated rate only picks the bracket') ~= nil, true);
    check('ND17c a tier rate never carries that caveat',
        lizzy4:match('TH4 45%% %-%- the stated') == nil, true);
    check('ND17d the mental model is stated once, and only with figures on screen',
        string.format('%d/%d',
            select(2, our4:gsub('TH is a lookup, not a multiplier', '')),
            select(2, rendered({ pool = { 3070 } }):gsub('TH is a lookup, not a multiplier', ''))), '1/0');

    -- ---- the whole-NM verdict ---------------------------------------------
    check('ND18a an NM TH helps says how many rolls climb',
        rendered(entryFor(107, 'Leaping Lizzy')):match('TH: every roll here climbs with it') ~= nil, true);
    check('ND18b ...and names the command that shows the rates',
        rendered(entryFor(107, 'Leaping Lizzy')):match('"/dl nm Leaping Lizzy th4"') ~= nil, true);
    -- Mixed: Ouryu's pool rolls 24 times, six of them at a rate no TH can lift.
    check('ND18c a mixed NM counts both halves',
        rendered({ n = 'Ouryu', pool = { 3070 } }):match('TH: 18 of 24 rolls climb with it') ~= nil, true);
    check('ND18d ...and with a level asked for, only the stuck ones are called out',
        our4:match('TH: 6 of the 24 rolls above cannot be lifted by any TH level') ~= nil, true);
    check('ND18e ...while an NM where everything climbs adds nothing to repeat',
        lizzy4:match('cannot be lifted') == nil, true);
    -- Steal and Despoil are not the kill's drop roll, and the ABSENCE of TH
    -- figures there is stated rather than left to read as "TH does nothing".
    check('ND18f the not-kill-loot section says why it carries no TH figures',
        lizzy4:match('no TH figures here %-%- the lookup above is the kill\'s drop roll') ~= nil, true);
    check('ND18g ...and says nothing of the sort when no level was asked for',
        rendered(entryFor(107, 'Leaping Lizzy')):match('no TH figures here') == nil, true);
    -- A group of ONE renders as a plain drop, but at the GROUP's rate -- the
    -- presentation shortcut must never become an arithmetic one.
    LT.data[999006] = { { i = 101, r = 250, t = 1, g = 1, gr = 150 } };
    check('ND18h a group of one takes TH on the group rate, not its weight',
        rendered({ pool = { 999006 } }, 4):match('Widget A %-%- common %(15%%%)  |  TH4 45%%') ~= nil, true);
    -- The second short-circuit. No shipped kill row carries `r = 0` today, but
    -- "the table states no rate" and "TH cannot raise it" are different facts
    -- and must not be told in the same words (hard rule 12).
    LT.data[999007] = { { i = 101, r = 0 }, { i = 102, r = 150 } };
    local nor4 = rendered({ pool = { 999007 } }, 4);
    check('ND18i a roll with no stated rate says that, not "no gain"',
        nor4:match('Widget A  |  TH4 nothing to raise %-%- the table states no rate') ~= nil, true);
    check('ND18j ...and is counted among the ones TH cannot lift',
        nor4:match('TH: 1 of the 2 rolls above cannot be lifted by any TH level %-%- the table states no rate for it') ~= nil, true);
    LT.data[999005], LT.data[999006], LT.data[999007] = nil, nil, nil;

    -- ---- and it all reaches chat under /dl nm ------------------------------
    local savedChat = package.loaded['dlac\\chatfmt'];
    local savedLoot = package.loaded['dlac\\feature\\nmloot'];
    local out = {};
    local function sink(s) out[#out + 1] = tostring(s); end
    package.loaded['dlac\\chatfmt'] = { msg = sink, good = sink, warn = sink, err = sink };
    package.loaded['dlac\\data\\nmdata'] = NMDATA;
    package.loaded['dlac\\feature\\nmloot'] = LT;
    local handler = nil;
    local savedReg = ashita.events.register;
    ashita.events.register = function(evt, name, fn)
        if name == 'dlac-nmlookup-cmd' then handler = fn; end
    end;
    local NM2 = dofile('feature/nmlookup.lua');
    ashita.events.register = savedReg;
    local function run(zid, cmd)
        NM2.zoneReader = function() return zid; end;
        out = {};
        local e = { command = cmd, blocked = false };
        handler(e);
        return table.concat(out, '\n');
    end

    local t1 = run(151, '/dl nm mee deggi');
    check('ND09a the drops reach chat',        t1:match('drops %-%- 1 roll') ~= nil, true);
    check('ND09b ...as a group, with shares',
        t1:match('one of these, always %(100%%%): Impact Knuckles 90%%, Ochiudo\'s Kote 10%%') ~= nil, true);
    check('ND09c ...with steal in its own section',
        t1:match('not kill loot %-%- Steal only') ~= nil, true);
    check('ND09d ...and Beastcoin never listed as a drop',
        t1:match('Beastcoin %-%-') == nil, true);
    -- Nothing that was already there may move.
    check('ND09e the pop kind survives',       t1:match('lottery pop') ~= nil, true);
    check('ND09f the placeholders survive',    t1:match('Yagudo Interrogator x8') ~= nil, true);
    check('ND09g the disfavour lines survive',
        t1:match('5%% base') ~= nil and t1:match('not flat') ~= nil, true);
    check('ND09h the indexes survive',         t1:match('NM index 88') ~= nil, true);
    check('ND09i the FilterScan filter survives',
        t1:match('/filterscan 49,54,57,63,71,72,86,87,88') ~= nil, true);
    check('ND09j ...and the filter still comes before the drops',
        t1:find('/filterscan') < t1:find('drops %-%-'), true);
    local t2 = run(112, '/dl nm Boreal Coeurl');
    check('ND09k an NM with no drop data says so inside the command',
        t2:match('nothing in the drop table') ~= nil, true);
    check('ND09l ...and still answers everything else',
        t2:match('Boreal Coeurl') ~= nil, true);
    -- A guess is still labelled a guess, with drops attached.
    local t3 = run(5, '/dl nm bonacon');
    check('ND09m guess labelling survives the new section',
        t3:match('closest match') ~= nil and t3:match('drops %-%- 7 rolls') ~= nil, true);

    -- ---- ...and so does the TH level, under `/dl nm <name> th4` (#154) -----
    local t4 = run(107, '/dl nm leaping lizzy th4');
    check('ND19a a TH level reaches the drop lines -- 15% becomes 45% at TH4',
        t4:match('Leaping Boots %-%- common %(15%%%)  |  TH4 45%%') ~= nil, true);
    check('ND19b ...on every roll',            select(2, t4:gsub('|  TH4 ', '')), 5);
    check('ND19c ...without eating the NM name',
        t4:match('Leaping Lizzy %-%-') ~= nil, true);
    check('ND19d ...or anything else the card already answered',
        t4:match('/filterscan 379,380,399,400') ~= nil and t4:match('9%% base') ~= nil, true);
    check('ND19e a spaced "th 4" is the same verb',
        run(107, '/dl nm leaping lizzy th 4'):match('|  TH4 45%%') ~= nil, true);
    check('ND19f TH0 is a real level, not a missing one',
        run(107, '/dl nm leaping lizzy th0'):match('Leaping Boots %-%- common %(15%%%)  |  TH0 15%%') ~= nil, true);
    -- Above the table: clamped, and SAID -- answering TH14 to someone who typed
    -- TH20 without saying so answers a different question than the one asked.
    local t5 = run(107, '/dl nm leaping lizzy th20');
    check('ND19g a level past the table is clamped',
        t5:match('|  TH14 70%%') ~= nil, true);
    check('ND19h ...and the clamp is said out loud',
        t5:match('TH runs 0%-14 in the server\'s own table %-%- showing TH14') ~= nil, true);
    -- A bare `th` is answered with the syntax, never with a level we picked:
    -- the whole readout would then be about gear the player may not own.
    local t6 = run(107, '/dl nm leaping lizzy th');
    check('ND19i a bare th asks which level',
        t6:match('say which TH level') ~= nil, true);
    check('ND19j ...shows no figures it was not given a level for',
        t6:match('|  TH') == nil, true);
    check('ND19k ...and still answers the NM',
        t6:match('Leaping Lizzy %-%-') ~= nil, true);
    -- The verb is stripped whatever order it is typed in, and never swallows
    -- the ones that were already there.
    check('ND19l th composes with apply, either way round',
        string.format('%s/%s',
            tostring(run(107, '/dl nm leaping lizzy th4 apply'):match('|  TH4 45%%') ~= nil),
            tostring(run(107, '/dl nm leaping lizzy apply th4'):match('|  TH4 45%%') ~= nil)),
        'true/true');
    sent = nil;
    check('ND19m ...and apply still applies',
        run(107, '/dl nm leaping lizzy th4 apply'):match('applied') ~= nil, true);
    check('ND19m2 ...queuing the filter the NM was always going to get',
        sent, '/filterscan 379,380,399,400');
    check('ND19n a zone list has nothing to show a TH rate for, and says so',
        run(107, '/dl nm th4'):match('nothing to show a TH rate for') ~= nil, true);
    -- The verdict that saves a gear set, in chat, without asking for a level.
    check('ND19o the no-level verdict reaches chat',
        t1:match('TH: nothing to gain here') ~= nil, true);
    check('ND19p ...and names the group as the reason',
        t1:match('TH never picks which item inside a group wins') ~= nil, true);
    check('ND19q the same NM at TH14 still gains nothing, in words',
        run(151, '/dl nm mee deggi th14'):match('TH14: no gain %-%- the group already drops every time') ~= nil, true);
    check('ND19r ...and its share is the same 10% it always was',
        run(151, '/dl nm mee deggi th14'):match('Ochiudo\'s Kote 10%%') ~= nil, true);

    package.loaded['dlac\\chatfmt'] = savedChat;
    package.loaded['dlac\\feature\\nmloot'] = savedLoot;
    package.loaded['dlac\\data\\nmdrops'] = nil;
    AshitaCore = savedAC;
end)();

-- ---------------------------------------------------------------------------
-- NM7*. Filter mode BY DROP -- the reverse lookup (issue #157, PRD #151).
--
--   "Who drops Leaping Boots?" is the one question the Compendium could not
--   answer without leaving the game, and it is the same join run backwards:
--   item -> pools (feature\nmloot's index) -> the NM entries carrying them
--   (feature\nmlookup's table). It lives HERE rather than up in the NM block
--   because it needs both halves at once -- the drop table AND a client that
--   can name items -- which is the environment this section already builds.
--
--   Two properties decide whether the mode is worth having, and each is a way
--   it could quietly answer the wrong question:
--
--     * ONLY A REAL NAME HIT COUNTS. The by-name mode hedges a weak match and
--       LABELS it a guess, because there the player has one monster in mind.
--       Here they have one ITEM in mind out of 2183, and a list of NMs
--       dropping something spelled a bit like it does not answer the question,
--       it buries it. So M.ITEM_FLOOR refuses the near-miss outright.
--     * A ROW IS NEVER A GUESS. Whatever the item score, nothing about the
--       MONSTER was guessed at -- the table says it drops that item -- so the
--       "(guess)" hedge must not leak across from the by-name mode.
-- ---------------------------------------------------------------------------
(function()
    local savedAC    = AshitaCore;
    local savedLoot  = package.loaded['dlac\\feature\\nmloot'];
    local savedLook  = package.loaded['dlac\\feature\\nmlookup'];
    local savedDrops = package.loaded['dlac\\data\\nmdrops'];
    package.loaded['dlac\\data\\nmdata']  = package.loaded['dlac\\data\\nmdata']
        or dofile('data/nmdata.lua');
    package.loaded['dlac\\data\\nmdrops'] = dofile('data/nmdrops.lua');

    -- A DELIBERATELY TINY name universe over the REAL drop table. The client
    -- only ever answers for these five, so `namedItems` holds five entries and
    -- every row below is the shipped table's own answer about them -- which
    -- makes each check a data tripwire as well as a behaviour one.
    local RES = { [13014] = 'Leaping Boots', [13952] = 'Ochiudo\'s Kote',
                  [16703] = 'Impact Knuckles', [656] = 'Beastcoin', [926] = 'Rock Salt' };
    AshitaCore = {
        GetResourceManager = function()
            return { GetItemById = function(_, id)
                if RES[id] == nil then return nil; end
                return { Name = { RES[id] } };
            end };
        end,
    };

    -- dofile + register, the harness pattern: `require` has no addons/ on its
    -- path here, and nmlookup reaches nmloot through `require` at call time --
    -- so both instances have to be the ones package.loaded hands back.
    local savedReg = ashita.events.register;
    ashita.events.register = function() end;      -- the command handler is not this block's
    local NM = dofile('feature/nmlookup.lua');
    package.loaded['dlac\\feature\\nmlookup'] = NM;
    local LT = dofile('feature/nmloot.lua');
    package.loaded['dlac\\feature\\nmloot'] = LT;
    ashita.events.register = savedReg;
    LT._resetIndex();
    LT.NAME_RETRY_S = 0;      -- no throttle: the suite changes what the client knows

    -- ---- the index itself --------------------------------------------------
    check('NM70a the drop table indexes every item it carries', #LT.itemIds(), 2183);
    check('NM70b ...and Leaping Boots reaches exactly one pool',
        table.concat(LT.poolsForItem(13014), ','), '2384');
    check('NM70c an item the table does not carry indexes to nothing',
        #LT.poolsForItem(999999), 0);
    check('NM70d ...and so does a nonsense id',  #LT.poolsForItem('x'), 0);
    -- An NM may carry the same pool twice. That is one droplist mentioned
    -- twice, not two droplists -- and the drops readout has always read it
    -- that way, so the reverse index must agree.
    check('NM70e a repeated pool id is one pool',
        #LT.poolsOf({ pool = { 9, 9, 9 } }), 1);
    check('NM70f a bare number pool is a pool',   #LT.poolsOf({ pool = 500 }), 1);
    check('NM70g an entry with no pool has none', #LT.poolsOf({ n = 'x' }), 0);

    -- ---- the mode ----------------------------------------------------------
    local brows, btotal, bitems = NM.dropRows('Leaping Boots');
    check('NM71a a drop search answers with the NMs that give it', btotal, 1);
    check('NM71b ...naming the monster',        brows[1] ~= nil and brows[1].n, 'Leaping Lizzy');
    check('NM71c ...in the zone it lives in',   brows[1] ~= nil and NM.zoneName(brows[1].zid),
        'South Gustaberg');
    check('NM71d ...and saying WHICH drop answered', brows[1] ~= nil and brows[1].dropNote,
        'Leaping Boots');
    check('NM71e the search says what it is a list OF', table.concat(bitems, ', '),
        'Leaping Boots');
    -- The hedge must not leak across from the by-name mode: the table SAYS
    -- this NM drops that item. Nothing about the monster was guessed at.
    check('NM71f a drop row is never a guess',   brows[1] ~= nil and brows[1].guess, false);
    -- Part of a name still finds it -- that much forgiveness is worth having.
    check('NM71g part of an item name still finds it',
        select(2, NM.dropRows('boots')), 1);

    -- ---- refusal, not a wild guess ----------------------------------------
    check('NM72a a near-miss is refused rather than guessed at',
        select(2, NM.dropRows('Leeping Bots')), 0);
    check('NM72b gibberish is refused',      select(2, NM.dropRows('zzzznothing')), 0);
    check('NM72c an empty query is not a search', #NM.dropRows(''), 0);
    check('NM72d ...nor is whitespace',      #NM.dropRows('   '), 0);
    check('NM72e ...nor is nil',             #NM.dropRows(nil), 0);
    check('NM72f the floor is the one it is documented at', NM.ITEM_FLOOR, 700);

    -- ---- a common item lists every source, campable ones first -------------
    local crows, ctotal = NM.dropRows('beastcoin');
    check('NM73a a common drop lists every NM that gives it', ctotal, 24);
    check('NM73b ...the ones with placeholders first', crows[1].ph > 0, true);
    check('NM73c ...and the ones without at the end',  crows[ctotal].ph, 0);
    local phBlock = true;
    local seenNone = false;
    for _, r in ipairs(crows) do
        if r.ph == 0 then seenNone = true; elseif seenNone then phBlock = false; end
    end
    check('NM73d ...with no campable one stranded below them', phBlock, true);
    local capped, capTotal = NM.dropRows('beastcoin', 2);
    check('NM73e the cap holds the list down',        #capped, 2);
    check('NM73f ...and the total still says what matched', capTotal, 24);

    -- ---- the synthetic half: the shapes the shipped table cannot show ------
    local savedNMData, savedLTData = NM.data, LT.data;
    NM.data = {
        [1] = {
            { n = 'Fixture Alpha', nm = { 10 }, ph = { 11, 12 }, p = 'Fixture PH',
              c = 5, kind = { 'lottery' }, pool = { 9001 } },
            { n = 'Fixture Beta',  nm = { 20 }, ph = {}, kind = { 'scripted' }, pool = { 9002 } },
            -- the same droplist reached through a repeated pool id, plus one
            -- more: it must answer ONCE and list both pools' matches
            { n = 'Fixture Gamma', nm = { 30 }, ph = { 31 }, p = 'Fixture PH', c = 5,
              kind = { 'lottery' }, pool = { 9001, 9001, 9002 } },
        },
    };
    LT.data = {
        [9001] = { { i = 8001, r = 150 }, { i = 8002, r = 100 }, { i = 8003, r = 50 },
                   { i = 8004, r = 10 },  { i = 8005, r = 5 } },
        [9002] = { { i = 8006, r = 240 } },
    };
    local SYN = {};
    RES = SYN;                -- the client knows NOTHING about these yet
    LT._resetIndex();

    -- A PRE-LOGIN READ MUST NOT LATCH (ADR 0007). The client cannot name an
    -- item before the player is in the world, and "cannot tell yet" is not
    -- "no such item" -- so the same search must start working the moment it
    -- can, with nothing reset and nobody asked to retry.
    check('NM74a a client that can name nothing finds nothing', #NM.dropRows('widget'), 0);
    SYN[8001] = 'Widget Boots';  SYN[8002] = 'Widget Gloves'; SYN[8003] = 'Widget Cap';
    SYN[8004] = 'Widget Ring';   SYN[8005] = 'Widget Belt';   SYN[8006] = 'Gadget Sword';
    local wrows, wtotal = NM.dropRows('widget');
    check('NM74b ...and the miss never latched: the same search now answers', wtotal, 2);
    check('NM74c an NM listing one pool twice still answers once',
        wrows[2] ~= nil and wrows[2].n, 'Fixture Gamma');
    -- A row that matched five items names three and COUNTS the rest. A row
    -- that reads as a paragraph is a row nobody scans -- and a silent cut
    -- reads as "that is all it drops".
    check('NM74d a row names its matches, capped, and says what it cut',
        wrows[1] ~= nil and wrows[1].dropNote,
        'Widget Boots, Widget Gloves, Widget Cap +2 more');
    check('NM74e ...at the documented cap', NM.DROP_NAMES, 3);
    check('NM74f a row with one match just names it',
        (select(1, NM.dropRows('Gadget Sword')))[1].dropNote, 'Gadget Sword');
    -- The tie-break the whole list order rests on, in THIS mode too: two NMs
    -- give the item and the one you can camp is the one you mean.
    local grows = NM.dropRows('Gadget Sword');
    check('NM74g two sources tie, and the campable one wins', grows[1].n, 'Fixture Gamma');
    check('NM74h ...which is the one with placeholders',      grows[1].ph > 0, true);
    check('NM74i ...while the other is still listed',         grows[2].n, 'Fixture Beta');

    NM.data, LT.data = savedNMData, savedLTData;
    LT._resetIndex();
    package.loaded['dlac\\feature\\nmloot']   = savedLoot;
    package.loaded['dlac\\feature\\nmlookup'] = savedLook;
    package.loaded['dlac\\data\\nmdrops']     = savedDrops;
    AshitaCore = savedAC;
end)();

-- ---------------------------------------------------------------------------
-- NT. Passive pop tracking (feature\nmtrack, issue #155, PRD #151).
--
--   The tracker counts the placeholder kills this character personally
--   witnessed, turns them into disfavour ROUNDS, and refuses to render a
--   percentage it cannot stand behind. Three properties carry the whole
--   feature and each is pinned directly:
--
--     * COUNTED BY TARGET INDEX, NEVER BY NAME. Uleguerand holds ten Buffalo
--       and only six are placeholders; a name-based counter would credit the
--       other four -- kills that never rolled -- and read HIGH.
--     * A ROUND IS NOT A KILL. rounds = kills / phCount; six Buffalo make one
--       Bonnacon round, and feeding raw kills to the curve overstates the odds
--       six times over.
--     * A STALE RECORD RENDERS NO PERCENTAGE. The error a broken observation
--       makes runs optimistic -- someone else popping and killing the NM while
--       you were away leaves your number high -- so the number is withheld,
--       not hedged.
--
--   The reducer is driven as a PURE function throughout (state + event + data
--   in, new state out), and the live feed (engage edge x death line) is driven
--   through the same pump the game calls.
-- ---------------------------------------------------------------------------
(function()
    local savedChat = package.loaded['dlac\\chatfmt'];
    local out = {};
    local function sink(s) out[#out + 1] = tostring(s); end
    package.loaded['dlac\\chatfmt'] = { msg = sink, good = sink, warn = sink, err = sink };

    -- Its own nmlookup instance, registered so nmtrack's load-time require
    -- resolves to the SAME module the assertions read (the curve, the shipped
    -- table and the pop kind all come from there -- nothing is re-derived).
    local handler = nil;
    local savedReg = ashita.events.register;
    ashita.events.register = function(evt, name, fn)
        if name == 'dlac-nmlookup-cmd' then handler = fn; end
    end;
    local NM = dofile('feature/nmlookup.lua');
    package.loaded['dlac\\feature\\nmlookup'] = NM;
    local TR = dofile('feature/nmtrack.lua');
    package.loaded['dlac\\feature\\nmtrack'] = TR;
    ashita.events.register = savedReg;

    check('NT00a the tracker loads',            type(TR), 'table');
    check('NT00b the reducer is exported pure', type(TR.reduce), 'function');
    check('NT00c ...and so is the readout',     type(TR.status), 'function');
    -- The curve is CONSUMED, never re-carried: a second copy of the formula is
    -- how the anchors and the readout drift apart.
    local src = (function()
        local f = io.open('feature/nmtrack.lua', 'r');
        if f == nil then return ''; end
        local t = f:read('*a'); f:close(); return t;
    end)();
    check('NT00d the disfavour formula is not copied into the tracker',
        src:find('100 / max', 1, true) == nil and src:find('(1 - base / 100)', 1, true) == nil, true);

    -- Disk stays out of the way for everything but the persistence block: a
    -- path of nil makes load() and save() no-ops, so M.state is exactly what
    -- each check puts there (an earlier section leaves profiles.dataDir stubbed).
    TR.path = function() return nil; end;
    TR.TICK_S = 0;      -- the frame throttle is not what is under test

    -- The worked example from the issue, hand-built so the reducer is driven by
    -- values rather than by whatever the shipped table happens to hold today.
    -- Buffalo at 354-359 ARE Bonnacon's placeholders; the Buffalo at 26-29 are
    -- ordinary mobs wearing the same name.
    local BON = { n = 'Bonnacon', nm = { 360 }, ph = { 354, 355, 356, 357, 358, 359 },
                  p = 'Buffalo', c = 5, w = { 3600, 86400 }, kind = { 'lottery' } };
    local SCRIPTED = { n = 'Charybdis', nm = { 412 }, ph = { 406, 408 }, p = 'Devil Manta',
                       c = 10, kind = { 'scripted' } };
    local DATA = { [5] = { BON, SCRIPTED } };
    local KEY  = TR.campKey(5, BON);
    local NOW  = 1700000000;
    local function ctxAt(zone, now) return { data = DATA, zone = zone, now = now or NOW }; end
    local function killAt(index, name, at)
        return { kind = 'kill', index = index, name = name, at = at or NOW };
    end

    -- ---- classify: the index is the authority, the name is not ------------
    local e1, r1 = TR.classify(DATA[5], 354, 'Buffalo');
    check('NT01a a placeholder index is a placeholder', r1, 'ph');
    check('NT01b ...of the right camp',                 e1 and e1.n, 'Bonnacon');
    local e2, r2 = TR.classify(DATA[5], 26, 'Buffalo');
    check('NT01c a same-named non-placeholder index is nothing', r2, nil);
    check('NT01d ...and answers with no camp',                   e2, nil);
    local e3, r3 = TR.classify(DATA[5], 360, 'Bonnacon');
    check('NT01e the NM index is the NM',               r3, 'nm');
    check('NT01f ...and names the camp',                e3 and e3.n, 'Bonnacon');
    local _, r4 = TR.classify(DATA[5], nil, 'Bonnacon');
    check('NT01g the NM answers by NAME when no index came with the line', r4, 'nm');
    local _, r5 = TR.classify(DATA[5], nil, 'Buffalo');
    check('NT01h a placeholder NEVER answers by name', r5, nil);
    -- The index gets BOTH its chances before a name is consulted, so a
    -- placeholder whose display name collides with some other camp's NM is
    -- still read as the placeholder it is -- not as evidence that NM popped.
    local COLLIDE = { DATA[5][1], { n = 'Buffalo', nm = { 900 }, kind = { 'scripted' } } };
    local e6, r6 = TR.classify(COLLIDE, 354, 'Buffalo');
    check('NT01i an index that answers wins over a colliding name', r6, 'ph');
    check('NT01j ...for the camp the spawn point belongs to', e6 and e6.n, 'Bonnacon');
    local e7, r7 = TR.classify(COLLIDE, 900, 'Buffalo');
    check('NT01k ...while that NM\'s own index still reads as the NM', r7, 'nm');
    check('NT01l ...and names it',                    e7 and e7.n, 'Buffalo');

    -- ---- the reducer: a kill at a placeholder index counts ----------------
    local s0 = {};
    local s1 = TR.reduce(s0, killAt(354, 'Buffalo'), ctxAt(5));
    check('NT02a a placeholder kill starts a count', s1[KEY] and s1[KEY].kills, 1);
    check('NT02b ...keyed to the camp in that zone', s1[KEY] and s1[KEY].nm, 'Bonnacon');
    check('NT02c ...remembering how many placeholders a round takes',
        s1[KEY] and s1[KEY].ph, 6);
    -- PURITY: the input state is never mutated, so a caller can hold the old one.
    check('NT02d the input state is untouched',      next(s0), nil);
    local s2 = TR.reduce(s1, killAt(355, 'Buffalo'), ctxAt(5));
    check('NT02e a second placeholder increments',   s2[KEY].kills, 2);
    check('NT02f ...and the state it came from does not', s1[KEY].kills, 1);

    -- THE HEADLINE RULE: same name, wrong spawn point, no credit.
    local s3 = TR.reduce(s2, killAt(26, 'Buffalo'), ctxAt(5));
    check('NT03a a same-named non-placeholder does NOT increment', s3[KEY].kills, 2);
    check('NT03b ...and creates no record of its own',
        (function() local n = 0; for _ in pairs(s3) do n = n + 1; end; return n; end)(), 1);
    -- A zone we could not read is not a zone to guess at.
    local s4 = TR.reduce(s3, killAt(354, 'Buffalo'), ctxAt(nil));
    check('NT03c an unreadable zone drops the kill rather than crediting it',
        s4[KEY].kills, 2);
    -- A scripted NM's placeholders roll nothing, so counting them would invent
    -- a curve the server does not run.
    local s5 = TR.reduce(s4, killAt(406, 'Devil Manta'), ctxAt(5));
    check('NT03d a scripted NM\'s placeholder is not counted',
        s5[TR.campKey(5, SCRIPTED)], nil);

    -- ---- kills become ROUNDS, and the CURRENT chance is shown -------------
    local sixty = {};
    for i = 1, 60 do
        sixty = TR.reduce(sixty, killAt(354 + (i % 6), 'Buffalo'), ctxAt(5));
    end
    check('NT04a sixty kills are sixty kills',        sixty[KEY].kills, 60);
    local st = TR.status(sixty[KEY], BON, NOW);
    check('NT04b ...and ten ROUNDS, not sixty',       st.rounds, 10);
    check('NT04c the chance is the curve at ten rounds, not the base',
        string.format('%.4f', st.chance), string.format('%.4f', NM.chanceAfter(5, 10)));
    check('NT04d ...which is not the base chance',    st.chance > 5, true);
    check('NT04e rounds to a guaranteed pop come from the lookup module',
        st.guaranteed, NM.roundsToGuaranteed(5));
    check('NT04f rounds REMAINING are reported',      st.roundsLeft, 30);
    check('NT04g ...and what that is in kills',       st.killsLeft, 180);
    local liveLines = table.concat(TR.lines(sixty[KEY], BON, NOW), '\n');
    check('NT04h the readout states the count',       liveLines:match('60 placeholder kills') ~= nil, true);
    check('NT04i ...as rounds',                       liveLines:match('10 rounds') ~= nil, true);
    check('NT04j ...with the CURRENT chance',         liveLines:match('6%.6%% now') ~= nil, true);
    check('NT04k ...and the rounds left to a guaranteed pop',
        liveLines:match('30 rounds %(180 kills%) to a guaranteed pop') ~= nil, true);
    -- THE FLOOR, and the reason for it, wherever a number is shown.
    check('NT05a the count is labelled a floor',      liveLines:match('FLOOR') ~= nil, true);
    check('NT05b ...because the server counter is shared',
        liveLines:match('zone%-wide and shared') ~= nil, true);
    check('NT05c ...and other players are invisible',
        liveLines:match("other players' placeholder kills are invisible") ~= nil, true);

    -- ---- evidence of a pop resets the count -------------------------------
    local dead = TR.reduce(sixty, killAt(360, 'Bonnacon'), ctxAt(5));
    check('NT06a seeing the NM DIE resets the count', dead[KEY].kills, 0);
    check('NT06b ...and records what was seen',       dead[KEY].saw, 'dead');
    check('NT06c ...without touching the old state',  sixty[KEY].kills, 60);
    local alive = TR.reduce(sixty, { kind = 'sight', index = 360, name = 'Bonnacon', at = NOW }, ctxAt(5));
    check('NT06d seeing the NM ALIVE resets it too',  alive[KEY].kills, 0);
    check('NT06e ...and records that',                alive[KEY].saw, 'alive');
    -- A death line naming the NM with no index attached is still evidence: a
    -- wrong match here can only ever RESET, never inflate.
    local byName = TR.reduce(sixty, killAt(nil, 'Bonnacon'), ctxAt(5));
    check('NT06f the NM name alone is enough to reset', byName[KEY].kills, 0);

    -- ---- the two "kills cannot roll" states -------------------------------
    check('NT07a right after a kill it is on cooldown',
        select(1, TR.rollState(dead[KEY], BON, NOW + 60)), 'cooldown');
    check('NT07b ...for as long as the SHORTEST cooldown it can draw',
        select(1, TR.rollState(dead[KEY], BON, NOW + 3599)), 'cooldown');
    check('NT07c past that nothing is claimed',
        select(1, TR.rollState(dead[KEY], BON, NOW + 3601)), 'ok');
    check('NT07d ...but it is not claimed as CLEAR either',
        select(2, TR.rollState(dead[KEY], BON, NOW + 3601)), true);
    check('NT07e past the longest cooldown the hedge is gone',
        select(2, TR.rollState(dead[KEY], BON, NOW + 86401)), false);
    check('NT07f an NM you have seen alive is primed',
        select(1, TR.rollState(alive[KEY], BON, NOW + 60)), 'primed');
    local cdLines = table.concat(TR.lines(dead[KEY], BON, NOW + 60), '\n');
    check('NT07g the cooldown says kills cannot roll right now',
        cdLines:match('kills cannot roll right now') ~= nil, true);
    check('NT07h ...and names the window',            cdLines:match('1h%-24h') ~= nil, true);
    local prLines = table.concat(TR.lines(alive[KEY], BON, NOW + 60), '\n');
    check('NT07i primed says kills cannot roll right now',
        prLines:match('kills cannot roll right now') ~= nil, true);
    check('NT07j ...because you saw it up',           prLines:match('saw it alive') ~= nil, true);
    local hedgeLines = table.concat(TR.lines(dead[KEY], BON, NOW + 7200), '\n');
    check('NT07k the uncertain window is said out loud, not counted as clear',
        hedgeLines:match('may not have rolled') ~= nil, true);

    -- A kill that cannot roll is not sold back as progress.
    local wasted = TR.reduce(dead, killAt(354, 'Buffalo', NOW + 60), ctxAt(5, NOW + 60));
    check('NT08a a kill inside the cooldown does not raise the count', wasted[KEY].kills, 0);
    check('NT08b ...it is tallied as wasted effort',                   wasted[KEY].void, 1);
    check('NT08c ...and it does not re-vouch for the count',           wasted[KEY].at, NOW);
    local wastedLines = table.concat(TR.lines(wasted[KEY], BON, NOW + 60), '\n');
    check('NT08d ...which the readout says',
        wastedLines:match('landed while nothing could roll') ~= nil, true);
    local primedKill = TR.reduce(alive, killAt(354, 'Buffalo', NOW + 60), ctxAt(5, NOW + 60));
    check('NT08e a kill while it is primed does not count either', primedKill[KEY].kills, 0);
    check('NT08f ...and is wasted effort too',                     primedKill[KEY].void, 1);
    -- Once the certain part of the cooldown is behind us, kills count again.
    local after = TR.reduce(dead, killAt(354, 'Buffalo', NOW + 7200), ctxAt(5, NOW + 7200));
    check('NT08g past the shortest cooldown a kill counts again', after[KEY].kills, 1);

    -- ---- a break in observation makes it stale ----------------------------
    local zoned = TR.reduce(sixty, { kind = 'zone', at = NOW + 10 }, ctxAt(5, NOW + 10));
    check('NT09a zoning marks the record stale',      zoned[KEY].stale, true);
    check('NT09b ...saying which break it was',       zoned[KEY].why, 'zone');
    check('NT09c ...and the raw count SURVIVES',      zoned[KEY].kills, 60);
    local relogged = TR.reduce(sixty, { kind = 'relog', at = NOW + 10 }, ctxAt(5, NOW + 10));
    check('NT09d a relog marks it stale',             relogged[KEY].stale, true);
    check('NT09e ...with its own reason',             relogged[KEY].why, 'relog');
    check('NT09f ...and keeps the count',             relogged[KEY].kills, 60);
    -- Age: past the NM's OWN ceiling (its longest repop window), nobody can
    -- vouch for the count -- the camp may have popped and re-armed without you.
    local old = TR.reduce(sixty, { kind = 'tick', at = NOW + 86401 }, ctxAt(5, NOW + 86401));
    check('NT09g age past the cooldown ceiling marks it stale', old[KEY].stale, true);
    check('NT09h ...for that reason',                           old[KEY].why, 'age');
    local young = TR.reduce(sixty, { kind = 'tick', at = NOW + 3600 }, ctxAt(5, NOW + 3600));
    check('NT09i ...but a fresh count is left alone',           young[KEY].stale, nil);
    -- Staleness is STICKY: a later kill still counts, but nothing re-vouches
    -- for the break -- only pop evidence (which zeroes it) or an explicit reset.
    local after2 = TR.reduce(zoned, killAt(354, 'Buffalo', NOW + 20), ctxAt(5, NOW + 20));
    check('NT09j a kill after the break still raises the raw count', after2[KEY].kills, 61);
    check('NT09k ...and does NOT un-stale the record',               after2[KEY].stale, true);
    check('NT09l pop evidence is what clears it',
        TR.reduce(zoned, killAt(360, 'Bonnacon', NOW + 30), ctxAt(5, NOW + 30))[KEY].stale, nil);

    -- ---- THE PROPERTY: a stale record renders NO percentage ---------------
    local staleSt = TR.status(zoned[KEY], BON, NOW + 10);
    check('NT10a a stale record has no chance at all -- not a hedged one',
        staleSt.chance, nil);
    check('NT10b ...while the raw count is still there',   staleSt.kills, 60);
    check('NT10c ...and it says it is stale',              staleSt.stale, true);
    local staleLines = table.concat(TR.lines(zoned[KEY], BON, NOW + 600), '\n');
    check('NT10d the rendered lines carry no percentage sign at all',
        staleLines:find('%%') == nil, true);
    check('NT10e ...they say STALE',                       staleLines:match('STALE') ~= nil, true);
    check('NT10f ...name the break',                       staleLines:match('you left the zone') ~= nil, true);
    check('NT10g ...show the raw count',                   staleLines:match('60 placeholder kills') ~= nil, true);
    check('NT10h ...and when it was last vouched for',     staleLines:match('last vouched for 10m ago') ~= nil, true);
    check('NT10i ...and why the number cannot be trusted',
        staleLines:match('may have popped while you were not watching') ~= nil, true);
    -- The same, for every break: none of them may render a number.
    for _, br in ipairs({ zoned, relogged, old }) do
        check('NT10j no break renders a percentage',
            table.concat(TR.lines(br[KEY], BON, NOW + 86500), '\n'):find('%%') == nil, true);
    end

    -- ---- the death line ---------------------------------------------------
    check('NT11a the standard death line names what died',
        TR.deathName('The Buffalo falls to the ground.'), 'Buffalo');
    check('NT11b ...and a party member\'s kill does too',
        TR.deathName('Mindie defeats the Buffalo.'), 'Buffalo');
    check('NT11c ...for a name the message carries bare',
        TR.deathName('Mindie defeats Bonnacon.'), 'Bonnacon');
    check('NT11d the client\'s colour bytes do not stick to the name',
        TR.deathName('\30\1The Buffalo falls to the ground.\7'), 'Buffalo');
    check('NT11e an ordinary line is not a death',
        TR.deathName('Mindie casts Cure on Mindie.'), nil);
    check('NT11f a non-string is not a death',        TR.deathName(nil), nil);

    -- ---- the live feed: engage edge x death line --------------------------
    local ZONE, saves = 5, 0;
    local reads = {
        now  = function() return NOW; end,
        zone = function() return ZONE; end,
        data = function() return DATA; end,
        save = function() saves = saves + 1; return true; end,
    };
    TR.reset(); TR.state = {};
    TR.onEdge({ index = 354, name = 'Buffalo' }, NOW);
    TR.onDeathLine('The Buffalo falls to the ground.', NOW);
    TR.pump(reads);
    check('NT12a an engaged placeholder that dies is counted',
        TR.state[KEY] and TR.state[KEY].kills, 1);
    check('NT12b ...and the count is written',        saves > 0, true);
    -- One engagement can credit at most one kill: a second death line with
    -- nothing engaged cannot borrow the last target.
    TR.onDeathLine('The Buffalo falls to the ground.', NOW);
    TR.pump(reads);
    check('NT12c a death with nothing engaged credits nothing', TR.state[KEY].kills, 1);
    -- The headline rule again, this time through the whole feed.
    TR.onEdge({ index = 26, name = 'Buffalo' }, NOW);
    TR.onDeathLine('The Buffalo falls to the ground.', NOW);
    TR.pump(reads);
    check('NT12d killing a same-named NON-placeholder counts nothing',
        TR.state[KEY].kills, 1);
    -- AUTO-TARGET ORDERING, and it is not a detail: the client rolls onto the
    -- next mob the moment the last one dies, so the ring holds BOTH by the time
    -- the death line renders. The kill belongs to the one engaged FIRST.
    TR.reset(); TR.state = {};
    TR.onEdge({ index = 354, name = 'Buffalo' }, NOW);   -- the one you fought
    TR.onEdge({ index = 26,  name = 'Buffalo' }, NOW);   -- auto-target's next pick, alive
    TR.onDeathLine('The Buffalo falls to the ground.', NOW);
    TR.pump(reads);
    check('NT12g the kill goes to the mob engaged first, not the one now facing you',
        TR.state[KEY] and TR.state[KEY].kills, 1);
    -- ...and the other way round, which is the over-count this prevents: the
    -- ordinary Buffalo died, the placeholder auto-target rolled onto is alive.
    TR.reset(); TR.state = {};
    TR.onEdge({ index = 26,  name = 'Buffalo' }, NOW);
    TR.onEdge({ index = 354, name = 'Buffalo' }, NOW);
    TR.onDeathLine('The Buffalo falls to the ground.', NOW);
    TR.pump(reads);
    check('NT12h ...so a placeholder still standing is never credited',
        TR.state[KEY], nil);

    -- The NM itself, through the feed: engaged (alive) then dead.
    TR.state = {};
    TR.onEdge({ index = 354, name = 'Buffalo' }, NOW);
    TR.onDeathLine('The Buffalo falls to the ground.', NOW);
    TR.pump(reads);
    check('NT12i a count exists before the NM is seen', TR.state[KEY].kills, 1);
    TR.onEdge({ index = 360, name = 'Bonnacon' }, NOW);
    TR.onDeathLine('The Bonnacon falls to the ground.', NOW);
    TR.pump(reads);
    check('NT12e killing the NM resets the count',    TR.state[KEY].kills, 0);
    check('NT12f ...and starts its cooldown',         TR.state[KEY].saw, 'dead');
    -- Zoning, through the pump: only a change between two KNOWN zones counts.
    TR.reset(); TR.state = {};
    TR.onEdge({ index = 354, name = 'Buffalo' }, NOW);
    TR.onDeathLine('The Buffalo falls to the ground.', NOW);
    TR.pump(reads);
    check('NT13a a count exists before the zone',     TR.state[KEY].kills, 1);
    ZONE = nil; TR.pump(reads);
    check('NT13b a zone we cannot read is not a zone change', TR.state[KEY].stale, nil);
    ZONE = 6; TR.pump(reads);
    check('NT13c zoning out marks it stale',          TR.state[KEY].stale, true);
    check('NT13d ...for the right reason',            TR.state[KEY].why, 'zone');
    ZONE = 5;

    -- ---- persistence: per character, across a reload and a relog ----------
    local TMP = 'tests' .. string.char(92) .. 'nt_nmcounts.lua';
    TR.path = function() return TMP; end;
    TR._loadedFrom = nil;
    TR.state = { [KEY] = { zone = 5, nm = 'Bonnacon', kills = 14, void = 2, ph = 6,
                           at = NOW, since = NOW - 900, saw = 'dead', sawAt = NOW - 100 } };
    check('NT14a the count is written',               TR.save(), true);
    -- A reload/relog is a fresh module with an empty memory.
    TR.state = {}; TR._loadedFrom = nil;
    TR.load();
    check('NT14b the count survives the reload',      TR.state[KEY] and TR.state[KEY].kills, 14);
    check('NT14c ...with its wasted-kill tally',      TR.state[KEY].void, 2);
    check('NT14d ...its placeholder count',           TR.state[KEY].ph, 6);
    check('NT14e ...and what it last saw',            TR.state[KEY].saw, 'dead');
    -- ...and it comes back STALE, because dlac was not watching in between.
    check('NT14f everything read off disk is stale',  TR.state[KEY].stale, true);
    check('NT14g ...as a relog/reload',               TR.state[KEY].why, 'relog');
    check('NT14h ...so it renders no percentage',
        TR.status(TR.state[KEY], BON, NOW).chance, nil);
    -- A junk row is dropped rather than half-read.
    (function()
        local f = io.open(TMP, 'w');
        f:write('return { fmt = 1, camps = { { zone = 5 }, { nm = "Bonnacon", zone = 5, kills = 3 } } }\n');
        f:close();
    end)();
    TR.state = {}; TR._loadedFrom = nil;
    TR.load();
    check('NT14i a row with no NM name is dropped',
        (function() local n = 0; for _ in pairs(TR.state) do n = n + 1; end; return n; end)(), 1);
    check('NT14j ...and the good one survives',       TR.state[KEY].kills, 3);
    -- The login window: the file path is unreadable for the first moments after
    -- a character loads, so a kill witnessed before the first successful read
    -- must not be thrown away by it.
    TR.state = { [KEY] = { zone = 5, nm = 'Bonnacon', kills = 1, void = 0, ph = 6,
                           at = NOW, since = NOW } };
    TR._loadedFrom = nil;
    TR.load();
    check('NT14k a kill witnessed before the first read is not lost to it',
        TR.state[KEY].kills, 1);
    check('NT14l ...and is not marked stale by the read either',
        TR.state[KEY].stale, nil);
    os.remove(TMP);
    TR.path = function() return nil; end;

    -- ---- the readout, end to end through the real command handler ---------
    local function joined() return table.concat(out, '\n'); end
    local function run(cmd)
        out = {};
        local e = { command = cmd, blocked = false };
        handler(e);
        return e, joined();
    end
    NM.zoneReader = function() return 5; end;
    local realBon = select(1, NM.matchInZone(5, 'Bonnacon'));
    check('NT15a the shipped table still carries the worked example',
        realBon ~= nil and realBon.n, 'Bonnacon');
    local realKey = TR.campKey(5, realBon);

    TR.state = {};
    local _, t0 = run('/dl nm bonnacon');
    check('NT15b with no count, the command says so',
        t0:match('no count here yet') ~= nil, true);
    check('NT15c ...and says there is nothing to arm',
        t0:match('nothing to arm') ~= nil, true);
    check('NT15d ...while the curve itself is untouched',
        t0:match('40 rounds is a guaranteed pop') ~= nil, true);

    TR.state = { [realKey] = { zone = 5, nm = 'Bonnacon', kills = 60, void = 0, ph = 6,
                               at = os.time(), since = os.time() } };
    local _, t1 = run('/dl nm bonnacon');
    check('NT16a the count reaches the readout',      t1:match('your count: 60 placeholder kills') ~= nil, true);
    check('NT16b ...as rounds',                       t1:match('= 10 rounds') ~= nil, true);
    check('NT16c ...with the CURRENT chance, not the base',
        t1:match('6%.6%% now') ~= nil, true);
    check('NT16d ...and the base is still stated as the base',
        t1:match('5%% base') ~= nil, true);
    check('NT16e ...with the rounds left to a guaranteed pop',
        t1:match('30 rounds %(180 kills%) to a guaranteed pop') ~= nil, true);
    check('NT16f ...labelled a floor',                t1:match('FLOOR') ~= nil, true);

    TR.state[realKey].stale = true; TR.state[realKey].why = 'zone';
    local _, t2 = run('/dl nm bonnacon');
    check('NT17a a stale count says STALE',           t2:match('STALE') ~= nil, true);
    check('NT17b ...and renders no current chance',   t2:match('%% now') == nil, true);
    check('NT17c ...while still showing the raw count', t2:match('60 placeholder kills') ~= nil, true);
    check('NT17d ...and the mechanic is still explained',
        t2:match('40 rounds is a guaranteed pop') ~= nil, true);

    -- The camp list: which counts do I hold, and can I trust them?
    local _, t3 = run('/dl nm counts');
    check('NT18a the list names the camp',            t3:match('Bonnacon') ~= nil, true);
    check('NT18b ...and its zone',                    t3:match('Uleguerand Range') ~= nil, true);
    check('NT18c ...marks the stale one',             t3:match('STALE') ~= nil, true);
    check('NT18d ...and calls every count a floor',   t3:match('floor') ~= nil, true);
    check('NT18e the list is not hunted for as an NM name',
        t3:match('closest match') == nil, true);

    -- Reset: the one manual door, because staleness is sticky by design.
    local _, t4 = run('/dl nm bonnacon reset');
    check('NT19a reset says the count is cleared',    t4:match('count cleared') ~= nil, true);
    check('NT19b ...and the count is gone',           TR.state[realKey], nil);
    check('NT19c ...leaving the camp with a clean slate',
        t4:match('no count here yet') ~= nil, true);
    local _, t5 = run('/dl nm bonnacon reset');
    check('NT19d resetting nothing says so, rather than pretending',
        t5:match('no count to clear') ~= nil, true);
    local _, t6 = run('/dl nm reset');
    check('NT19e reset with no NM named is answered, not dropped',
        t6:match('nothing to reset') ~= nil, true);
    check('NT19f ...and is not hunted for as an NM called "reset"',
        t6:match('closest match') == nil, true);
    local _, t7 = run('/dl nm counts');
    check('NT19g an empty tracker says it is empty',  t7:match('no NM counts yet') ~= nil, true);
    -- ...and says which half it has seen, so "nothing is counting" and "the
    -- death line is worded differently on this server" cannot look identical
    -- in the field (hard rule 12). Both halves are needed for a kill to count.
    check('NT19h ...and reports what the feed has seen',
        t7:match('seen so far') ~= nil, true);
    check('NT19i ...naming the last engaged target and its index',
        t7:match('last engaged: "Buffalo" index 354') ~= nil, true);
    check('NT19j ...and the last death line it recognised',
        t7:match('last death line: "Buffalo"') ~= nil, true);
    TR.reset();
    local _, t7b = run('/dl nm counts');
    check('NT19k a feed that has seen nothing says exactly that',
        t7b:match('last engaged: nothing yet; last death line: nothing yet') ~= nil, true);

    -- A scripted NM has no rounds to be part-way through, so it gets no
    -- tracking lines at all -- the same rule that keeps the curve off it.
    NM.zoneReader = function() return 176; end;
    local _, t8 = run('/dl nm Charybdis');
    check('NT20a a scripted NM shows no count invitation',
        t8:match('no count here yet') == nil, true);
    check('NT20b ...and no floor caveat for a number it will never have',
        t8:match('FLOOR') == nil, true);
    NM.zoneReader = function() return 5; end;

    package.loaded['dlac\\chatfmt'] = savedChat;
end)();

-- ---------------------------------------------------------------------------
-- JB. Job browsing (2026-08-06) -- ui\jobbrowse.lua, the state behind the job
-- picker in the Gear window's header. Pure but for ONE live read (GetMainJob),
-- so the whole contract drives headlessly: which job the EDITORS answer for, at
-- what level, and when that stops following the character.
--
-- The two that are easy to get backwards, and are the whole feature:
--   * picking the job you are ON means "follow live" (nil), not "pin it" -- so a
--     later job change follows, exactly as it did before browsing existed;
--   * a real job change does NOT clear a selection -- the WAR set you are
--     halfway through building stays valid when you change to BLM, and only the
--     header moves. (gearui's working-set drop keys on the SAME job value, so
--     these two together decide when a half-built set survives.)
-- ---------------------------------------------------------------------------
;(function()
    local jb = dofile('ui/jobbrowse.lua');
    local savedCore = AshitaCore;
    local jobId = 7;                                     -- PLD
    AshitaCore = { GetMemoryManager = function()
        return { GetPlayer = function() return { GetMainJob = function() return jobId; end }; end };
    end };

    check('JB1a default holds no selection', jb.selected(), nil);
    check('JB1b default is not browsing', jb.active(), false);
    check('JB1c default level defers to the live reading', jb.level(), nil);
    check('JB1d default job is the live job', jb.job(), 'PLD');

    jb.set('WAR');
    check('JB2a a pick is remembered', jb.selected(), 'WAR');
    check('JB2b ...and reads as browsing', jb.active(), true);
    check('JB2c ...at a flat 75', jb.level(), 75);
    check('JB2d ...and IS the job the editors answer for', jb.job(), 'WAR');

    jobId = 4;                                           -- change job in game: BLM
    check('JB3a a live job change leaves the selection alone', jb.selected(), 'WAR');
    check('JB3b ...and browsing stays on', jb.active(), true);
    check('JB3c ...so the set being built is still WAR\'s', jb.job(), 'WAR');

    jb.set('BLM');                                       -- picking the job you are ON
    check('JB4a picking your own job clears the selection', jb.selected(), nil);
    check('JB4b ...and stops browsing', jb.active(), false);
    jobId = 3;                                           -- WHM
    check('JB4c ...so a later job change is followed again', jb.job(), 'WHM');

    jb.set('SAM'); jb.clear();
    check('JB5 clear() returns the editors to live', jb.active(), false);
    jb.set('SAM'); jb.set(nil);
    check('JB6a a nil pick clears', jb.selected(), nil);
    jb.set('SAM'); jb.set('');
    check('JB6b an empty pick clears', jb.selected(), nil);

    -- Character select / an unsettled GetMainJob (id 0 = no job, hard rule 11).
    -- A held selection must still READ as browsing there: the header saying
    -- "viewing RDM" is the honest answer, and looking normal is not.
    jb.set('RDM'); jobId = 0;
    check('JB7a no live job still reads as browsing', jb.active(), true);
    check('JB7b ...and the editors answer for the pick', jb.job(), 'RDM');
    check('JB7c liveJob is nil there', jb.liveJob(), nil);
    jb.clear();
    check('JB7d no pick and no live job = no job to edit', jb.job(), nil);

    AshitaCore = savedCore;
end)();

-- The warm-note artifact the dispatch-driving sections leave behind (dataDir
-- stubbed 'tests\'): on Windows a real tests\debug\mpwarm.txt (gitignored via
-- debug/), under WSL ONE backslash-bearing filename that drvfs PUA-mangles on
-- NTFS -- which .gitignore cannot match. Same string removes it on both.
pcall(os.remove, 'tests' .. string.char(92) .. 'debug' .. string.char(92) .. 'mpwarm.txt');

-- ---------------------------------------------------------------------------
-- verdict
-- ---------------------------------------------------------------------------
if #failures == 0 then
    print(string.format('OK -- %d checks passed', count));
    os.exit(0);
end
print(string.format('FAIL -- %d of %d checks failed:', #failures, count));
for _, f in ipairs(failures) do print('  ' .. f); end
os.exit(1);
